7: const playBtn = document.getElementById('play');
8: 
9: const dir = buildDirectorEp4();
10: const totalDur = dir.totalDur;
11: 
12: function activeShot(t) {
13:   for (let i = dir.shots.length - 1; i >= 0; i--) {
14:     if (t >= dir.shots[i].at) {
15:       const next = dir.shots[i + 1];
16:       const end = next ? next.at : totalDur;
17:       return { s: dir.shots[i], lt: t - dir.shots[i].at, d: end - dir.shots[i].at };
18:     }
19:   }
20:   const s = dir.shots[0];
21:   return { s, lt: t, d: (dir.shots[1]?.at ?? totalDur) };
22: }
23: 
24: export function drawFrame(t) {
25:   if (!ctx) return;
26:   t = Math.max(0, Math.min(t, totalDur));
27:   ctx.setTransform(1, 0, 0, 1, 0, 0);
28:   ctx.fillStyle = '#06080d';
29:   ctx.fillRect(0, 0, W, H);
30: 
31:   const { s, lt, d } = activeShot(t);
32:   const cam = s.cam ? s.cam(lt, d, t) : { x: W / 2, y: H / 2, zoom: 0 };
33:   const [sx, sy] = dir.shakeAt(t);
34:   const scale = 1 + (cam.zoom || 0);
35: 
36:   // Camera transform (push-in + impact shake)
37:   ctx.save();
38:   ctx.translate(W / 2 + sx, H / 2 + sy);
39:   ctx.scale(scale, scale);
40:   ctx.translate(-(cam.x ?? W / 2), -(cam.y ?? H / 2));
41:   s.draw(ctx, lt, d, t);
42:   ctx.restore();
