    shakeAt(t) {
      for (const s of shakes) {
        if (t >= s.t && t <= s.t + s.dur) {
          const decay = 1 - (t - s.t) / s.dur;
          const amp = s.amp * decay;
          return [(Math.random() - 0.5) * amp * 2, (Math.random() - 0.5) * amp * 2];
        }
      }
      return [0, 0];
    },
    flashAt(t) {
      for (const f of flashes) {
        if (t >= f.t && t <= f.t + f.dur) return f.col;
      }
      return null;
    }
  };
}
