import json
import re

transcript_path = r"C:\Users\dirgh\.gemini\antigravity\brain\08383f18-8836-44c0-b898-f0efe2c3452e\.system_generated\logs\transcript_full.jsonl"

all_lines = {}
line_regex = re.compile(r"^(\d+):\s?(.*)$", re.MULTILINE)

with open(transcript_path, "r", encoding="utf-8") as f:
    for row in f:
        try:
            obj = json.loads(row)
            content = obj.get("content", "")
            if "Showing lines " in content:
                for m in line_regex.finditer(content):
                    num = int(m.group(1))
                    val = m.group(2)
                    if num not in all_lines or len(val) > len(all_lines[num]):
                        all_lines[num] = val
        except Exception:
            pass

print(f"Collected {len(all_lines)} lines")
max_line = max(all_lines.keys()) if all_lines else 0
print(f"Max line: {max_line}")

if max_line >= 600:
    reconstructed = []
    missing = []
    for i in range(1, max_line + 1):
        if i in all_lines:
            reconstructed.append(all_lines[i])
        else:
            missing.append(i)
    print("Missing lines:", missing)
    if not missing:
        with open(r"z:\Mini Projects\Nirvana\Automation reel workflow\millbrook-lift-2d\src\shots_ep4.js", "w", encoding="utf-8") as out:
            out.write("\n".join(reconstructed) + "\n")
        print("Restored exact original shots_ep4.js!")

