export function drawFireAxe(ctx, x, y, scale = 1.0, rot = 0) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rot);
  ctx.scale(scale, scale);

  // Hickory wooden handle
  ctx.fillStyle = linGrad(ctx, -6, -140, 6, 140, [
