const fs = require('fs');
const content = fs.readFileSync('millbrook-lift-2d/src/shots_ep4.js', 'utf8');
const lines = content.split('\n');
let curShot = '';
let calls = {};
lines.forEach(l => {
  const m = l.match(/id:\s*'(S\d+)'/);
  if (m) curShot = m[1];
  if (curShot) {
    const draws = l.match(/draw\w+/g);
    if (draws) {
      if (!calls[curShot]) calls[curShot] = new Set();
      draws.forEach(d => calls[curShot].add(d));
    }
  }
});
for (const [s, set] of Object.entries(calls)) {
  console.log(s, Array.from(set).join(', '));
}
"

