    ctx.lineTo(36, 10); ctx.lineTo(-36, 10); ctx.closePath();
    fillStroke(ctx, '#282E3A', 4, INK);
    ctx.fillStyle = '#E6EAEF'; ctx.fillRect(-32, 4, 64, 7);
    ctx.restore();
  });

  // Torso twisted in dynamic swing
  ctx.save();
  ctx.rotate(-0.15);
