  ctx.moveTo(-74, torsoTop + 14);
  ctx.bezierCurveTo(-96, torsoTop + 50, -90, torsoBot - 35, -80, torsoBot);
  ctx.lineTo(80, torsoBot);
  ctx.bezierCurveTo(90, torsoBot - 35, 96, torsoTop + 50, 74, torsoTop + 14);
  ctx.quadraticCurveTo(0, torsoTop - 16, -74, torsoTop + 14);
  ctx.closePath();
  fillStroke(ctx, linGrad(ctx, -85, torsoTop, 85, torsoBot, [[0, '#1E2D4A'], [1, '#151F33']]), 5, INK);

  // Inner hoodie
  ctx.beginPath();
  ctx.moveTo(-34, torsoTop + 4); ctx.lineTo(34, torsoTop + 4);
  ctx.lineTo(28, torsoBot); ctx.lineTo(-28, torsoBot); ctx.closePath();
  fillStroke(ctx, '#5A181C', 3.5, INK);

  // Collar lapels
  [-1, 1].forEach((s) => {
    ctx.beginPath();
    ctx.moveTo(s * 28, torsoTop + 2);
    ctx.lineTo(s * 62, torsoTop + 24);
    ctx.lineTo(s * 40, torsoTop + 68);
    ctx.closePath();
    fillStroke(ctx, '#1E2D4A', 3.5, INK);
  });
  ctx.restore();

  // Head (determined, gritted teeth, fierce fighting spirit!)
  ctx.save();
  ctx.translate(0, -90);
  ctx.beginPath();
  ctx.ellipse(0, 0, 88, 98, 0, 0, TAU);
  fillStroke(ctx, PAL.mayaSkin, 4.5, INK);

  // Ponytail sweeping behind
  ctx.beginPath();
  ctx.moveTo(-75, -20);
  ctx.bezierCurveTo(-135, -40, -150, 20, -125, 60);
  ctx.bezierCurveTo(-115, 30, -95, 10, -75, 5);
  ctx.closePath();
  fillStroke(ctx, '#1A1818', 4, INK);

  // Hair bangs
  ctx.beginPath();
  ctx.moveTo(-88, -25);
  ctx.bezierCurveTo(-85, -95, 85, -95, 88, -25);
  ctx.bezierCurveTo(60, -45, 20, -40, 0, -25);
  ctx.bezierCurveTo(-20, -45, -60, -45, -88, -25);
  ctx.closePath();
  fillStroke(ctx, '#1A1818', 4, INK);

  // Fierce determined angled eyebrows
  ctx.fillStyle = INK;
  ctx.beginPath(); ctx.moveTo(-52, -22); ctx.lineTo(-14, -12); ctx.lineTo(-14, -6); ctx.lineTo(-52, -16); ctx.closePath(); ctx.fill();
  ctx.beginPath(); ctx.moveTo(52, -22); ctx.lineTo(14, -12); ctx.lineTo(14, -6); ctx.lineTo(52, -16); ctx.closePath(); ctx.fill();

  // Intense focused eyes
  [-32, 32].forEach((ex) => {
    ctx.beginPath(); ctx.ellipse(ex, 2, 18, 14, 0, 0, TAU); fillStroke(ctx, '#ffffff', 3.5, INK);
    ctx.beginPath(); ctx.ellipse(ex + 4, 2, 9, 9, 0, 0, TAU); ctx.fillStyle = '#1A1818'; ctx.fill();
    ctx.beginPath(); ctx.ellipse(ex + 6, -1, 3, 3, 0, 0, TAU); ctx.fillStyle = '#ffffff'; ctx.fill();
  });

  // Gritted teeth mouth
  ctx.save();
  ctx.translate(0, 48);
  rrPath(ctx, -26, -10, 52, 20, 6);
  fillStroke(ctx, '#ffffff', 3.5, INK);
  for (let tx = -18; tx <= 18; tx += 9) {
    ctx.beginPath(); ctx.moveTo(tx, -10); ctx.lineTo(tx, 10); ctx.strokeStyle = 'rgba(0,0,0,0.3)'; ctx.lineWidth = 1.5; ctx.stroke();
  }
  ctx.beginPath(); ctx.moveTo(-26, 0); ctx.lineTo(26, 0); ctx.strokeStyle = 'rgba(0,0,0,0.4)'; ctx.lineWidth = 2; ctx.stroke();
  ctx.restore();
  ctx.restore();

  // Arms tensed swinging the axe forward
  const axeAngle = 0.55 + Math.sin(swingPhase * Math.PI) * 0.15;
  drawLimbTube(ctx, -60, -30, 20, 10, 24, 20, '#151F33', 4.5);
  drawLimbTube(ctx, 40, -25, 60, 0, 24, 20, '#1E2D4A', 4.5);

  drawFireAxe(ctx, 70, -20, 1.25, axeAngle);
