// =============================================================
// NEW PROP: Stylized 2D Fire Axe
// =============================================================
export function drawFireAxe(ctx, x, y, scale = 1.0, rot = 0) {
  ctx.save();
  ctx.translate(x, y);
  ctx.rotate(rot);
  ctx.scale(scale, scale);

  // Hickory wooden handle
  ctx.fillStyle = linGrad(ctx, -6, -140, 6, 140, [
    [0, '#d97706'], [0.5, '#b45309'], [1, '#78350f']
  ]);
  rrPath(ctx, -7, -140, 14, 280, 5);
  fillStroke(ctx, ctx.fillStyle, 3, INK);

  // Handle lower rubber grip wrap
  ctx.fillStyle = '#1e293b';
  rrPath(ctx, -8, 60, 16, 75, 4);
  fillStroke(ctx, '#0f172a', 2.5, INK);
  for (let gy = 70; gy < 130; gy += 12) {
    ctx.strokeStyle = '#475569'; ctx.lineWidth = 2;
    ctx.beginPath(); ctx.moveTo(-7, gy); ctx.lineTo(7, gy); ctx.stroke();
  }

  // Steel Axe Head
  ctx.save();
  ctx.translate(0, -125);
  // Rear pick spike
  ctx.beginPath();
  ctx.moveTo(0, -18);
  ctx.lineTo(48, -6);
  ctx.lineTo(42, 6);
  ctx.lineTo(0, 18);
  ctx.closePath();
  fillStroke(ctx, '#94a3b8', 3, INK);

  // Main axe blade body (Red enamel)
  ctx.beginPath();
  ctx.moveTo(4, -22);
  ctx.lineTo(-45, -34);
  ctx.bezierCurveTo(-75, -20, -75, 20, -45, 34);
  ctx.lineTo(4, 22);
  ctx.closePath();
  fillStroke(ctx, '#dc2626', 3.5, INK);

  // Polished cutting edge
  ctx.beginPath();
  ctx.moveTo(-45, -34);
  ctx.bezierCurveTo(-75, -20, -75, 20, -45, 34);
  ctx.bezierCurveTo(-60, 15, -60, -15, -45, -34);
  ctx.closePath();
  fillStroke(ctx, '#f1f5f9', 2.5, INK);

  // Eye collar fixing
  ctx.fillStyle = '#64748b';
  rrPath(ctx, -10, -20, 20, 40, 4);
  fillStroke(ctx, '#475569', 2.5, INK);
  ctx.restore();

  ctx.restore();
}

