// Procedural Geometry & Texture Helpers for Roblox 3D Assets
import * as THREE from 'three';

const geoCache = new Map();
const texCache = new Map();

export function cachedGeo(key, buildFn) {
  if (!geoCache.has(key)) geoCache.set(key, buildFn());
  return geoCache.get(key);
}

// Authentic Roblox Chamfered Cuboid with Bevel
export function chamferBox(w, h, d, r = 0.035, bevelSegments = 2) {
  const key = `cbox_${w.toFixed(3)}_${h.toFixed(3)}_${d.toFixed(3)}_${r.toFixed(3)}_${bevelSegments}`;
  return cachedGeo(key, () => {
    const bw = Math.max(0.01, w - 2 * r), bd = Math.max(0.01, d - 2 * r), bh = Math.max(0.01, h - 2 * r);
    const hw = bw / 2, hd = bd / 2, cr = Math.min(r * 0.85, hw * 0.35, hd * 0.35);
    const s = new THREE.Shape();
    s.moveTo(-hw + cr, -hd);
    s.lineTo(hw - cr, -hd); s.quadraticCurveTo(hw, -hd, hw, -hd + cr);
    s.lineTo(hw, hd - cr); s.quadraticCurveTo(hw, hd, hw - cr, hd);
    s.lineTo(-hw + cr, hd); s.quadraticCurveTo(-hw, hd, -hw, hd - cr);
    s.lineTo(-hw, -hd + cr); s.quadraticCurveTo(-hw, -hd, -hw + cr, -hd);
    const g = new THREE.ExtrudeGeometry(s, {
      depth: bh,
      bevelEnabled: true,
      bevelThickness: r,
      bevelSize: r,
      bevelSegments,
      curveSegments: 4,
    });
    g.rotateX(Math.PI / 2);
    g.center();
    const pos = g.attributes.position;
    const uv = g.attributes.uv;
    for (let i = 0; i < pos.count; i++) {
      const u = THREE.MathUtils.clamp(pos.getX(i) / w + 0.5, 0.01, 0.99);
      const v = THREE.MathUtils.clamp(pos.getY(i) / h + 0.5, 0.01, 0.99);
      uv.setXY(i, u, v);
    }
    uv.needsUpdate = true;
    return g;
  });
}

// Procedural Canvas Texture Generator
export function canvasTex(key, w, h, drawFn, rep = [1, 1]) {
  let t = texCache.get(key);
  if (!t) {
    const c = document.createElement('canvas');
    c.width = w; c.height = h;
    drawFn(c.getContext('2d'), w, h);
    t = new THREE.CanvasTexture(c);
    t.colorSpace = THREE.SRGBColorSpace;
    t.wrapS = t.wrapT = THREE.RepeatWrapping;
    t.anisotropy = 8;
    texCache.set(key, t);
  }
  const u = t.clone();
  u.repeat.set(rep[0], rep[1]);
  u.needsUpdate = true;
  return u;
}

// Common High-Tech Materials
export const T = {
  // Hexagonal Carbon-Fiber Weave
  carbon: (base = '#111827', line = '#1F2937', rep = [8, 8]) => canvasTex(`carb_${base}_${line}`, 128, 128, (g, w, h) => {
    g.fillStyle = base; g.fillRect(0, 0, w, h);
    g.strokeStyle = line; g.lineWidth = 2;
    const s = 16;
    for (let y = 0; y < h + s; y += s * 1.5) {
      for (let x = 0; x < w + s * 2; x += s * 1.732) {
        const cx = x + ((Math.floor(y / (s * 1.5)) % 2) * (s * 0.866));
        g.beginPath();
        for (let i = 0; i < 6; i++) {
          const a = (i * Math.PI) / 3;
          const px = cx + (s * 0.5) * Math.cos(a);
          const py = y + (s * 0.5) * Math.sin(a);
          i === 0 ? g.moveTo(px, py) : g.lineTo(px, py);
        }
        g.closePath();
        g.stroke();
      }
    }
  }, rep),

  // Racing Pinstripe Body Decal
  racingStripe: (body = '#0F172A', stripe1 = '#F59E0B', stripe2 = '#00F0FF') => canvasTex(`strip_${body}_${stripe1}_${stripe2}`, 256, 256, (g, w, h) => {
    g.fillStyle = body; g.fillRect(0, 0, w, h);
    // Center dual gold racing stripes
    g.fillStyle = stripe1;
    g.fillRect(116, 0, 10, h);
    g.fillRect(130, 0, 10, h);
    // Outer cyan accent pinstripes
    g.fillStyle = stripe2;
    g.fillRect(108, 0, 3, h);
    g.fillRect(145, 0, 3, h);
  }, [1, 1]),

  // Telemetry Dashboard Screen
  dashboard: () => canvasTex('dash_screen', 256, 128, (g, w, h) => {
    g.fillStyle = '#050B14'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#00F0FF'; g.lineWidth = 2;
    g.strokeRect(4, 4, w - 8, h - 8);
    // Speedometer arc
    g.beginPath();
    g.arc(80, 70, 38, Math.PI * 0.8, Math.PI * 2.2);
    g.strokeStyle = '#38BDF8'; g.lineWidth = 6; g.stroke();
    // Digital readout
    g.fillStyle = '#00FFAA'; g.font = 'bold 24px monospace';
    g.fillText('540', 60, 78);
    g.font = '12px monospace'; g.fillText('STUDS/S', 52, 94);
    // Power graph bars
    for (let i = 0; i < 8; i++) {
      g.fillStyle = i > 5 ? '#FF0055' : '#00F0FF';
      g.fillRect(160 + i * 9, 85 - (i * 6), 6, i * 6 + 10);
    }
    g.fillStyle = '#F59E0B'; g.font = 'bold 13px sans-serif';
    g.fillText('[ SPEC-R // V1 ]', 150, 32);
  }, [1, 1]),

  // Badge / Decal on Side Fender
  fenderBadge: () => canvasTex('fender_badge', 256, 64, (g, w, h) => {
    g.fillStyle = 'rgba(0,0,0,0)'; g.clearRect(0, 0, w, h);
    g.fillStyle = '#F59E0B'; g.font = '900 28px sans-serif';
    g.fillText('AETHELGARD', 10, 34);
    g.fillStyle = '#00F0FF'; g.font = 'bold 16px monospace';
    g.fillText('MONARCH 01', 12, 54);
    g.strokeStyle = '#00F0FF'; g.lineWidth = 3;
    g.beginPath(); g.moveTo(190, 16); g.lineTo(240, 16); g.lineTo(225, 48); g.lineTo(175, 48); g.closePath();
    g.fillStyle = '#00F0FF'; g.fill();
  }, [1, 1])
};

// The Apex Neon Speeder — Luxury Cyber Flying Cruiser (Roblox 3D Asset)
import * as THREE from 'three';
import { chamferBox, canvasTex, T } from './core/geo.js';

const D = THREE.MathUtils.degToRad;

export function buildNeonSpeeder(opts = {}) {
  const g = new THREE.Group();

  // Colors & Materials
  const primaryCol = opts.primary || '#0B1120';    // Deep obsidian carbon
  const accentCol = opts.accent || '#F59E0B';      // Monarch Gold
  const neonCol = opts.neon || '#00F0FF';          // Electric Cyan
  const brakeCol = '#FF0044';                      // Crimson Neon

  const matBody = new THREE.MeshStandardMaterial({
    color: primaryCol,
    roughness: 0.28,
    metalness: 0.72,
    envMapIntensity: 1.4,
  });

  const matCarbon = new THREE.MeshStandardMaterial({
    map: T.carbon('#0F172A', '#1E293B', [12, 12]),
    roughness: 0.55,
    metalness: 0.25,
  });

  const matStripe = new THREE.MeshStandardMaterial({
    map: T.racingStripe(primaryCol, accentCol, neonCol),
    roughness: 0.26,
    metalness: 0.68,
  });

  const matGold = new THREE.MeshStandardMaterial({
    color: accentCol,
    roughness: 0.22,
    metalness: 0.88,
  });

  const matGlass = new THREE.MeshPhysicalMaterial({
    color: '#0369A1',
    roughness: 0.08,
    transmission: 0.75,
    thickness: 0.4,
    transparent: true,
    opacity: 0.70,
    metalness: 0.1,
  });

  const matNeon = new THREE.MeshStandardMaterial({
    color: neonCol,
    emissive: neonCol,
    emissiveIntensity: 2.8,
    roughness: 0.2,
  });

  const matHeadlight = new THREE.MeshStandardMaterial({
    color: '#FFFFFF',
    emissive: '#FFFFFF',
    emissiveIntensity: 3.5,
  });

  const matTaillight = new THREE.MeshStandardMaterial({
    color: brakeCol,
    emissive: brakeCol,
    emissiveIntensity: 3.0,
  });

  const matDarkMetal = new THREE.MeshStandardMaterial({
    color: '#1E293B',
    roughness: 0.45,
    metalness: 0.65,
  });

  const mkMesh = (geo, mat, pos = [0,0,0], rot = [0,0,0], parent = g) => {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(...pos);
    m.rotation.set(...rot);
    m.castShadow = true;
    m.receiveShadow = true;
    parent.add(m);
    return m;
  };

  // ==========================================
  // 1. MAIN CHASSIS & LOWER TRAY
  // ==========================================
  // Lower carbon tray (Length 5.2m, Width 2.2m, Height 0.25m)
  mkMesh(chamferBox(2.2, 0.22, 5.0, 0.04), matCarbon, [0, 0.25, 0]);

  // Main Center Hull with Racing Stripe Decal
  const mainHull = mkMesh(chamferBox(1.9, 0.45, 4.4, 0.06), matStripe, [0, 0.52, -0.1]);

  // Sloped Aerodynamic Nose Wedge
  const noseWedge = mkMesh(chamferBox(1.6, 0.26, 1.4, 0.05), matStripe, [0, 0.42, 2.2]);
  noseWedge.rotation.x = D(-8);

  // Front Splitter / Ground Effect Wing
  const splitter = mkMesh(chamferBox(2.1, 0.06, 0.6, 0.02), matCarbon, [0, 0.20, 2.65]);
  // Splitter support struts
  mkMesh(chamferBox(0.04, 0.16, 0.04, 0.01), matGold, [-0.55, 0.28, 2.65]);
  mkMesh(chamferBox(0.04, 0.16, 0.04, 0.01), matGold, [0.55, 0.28, 2.65]);

  // Front Lower Intake Mesh
  const intakeMesh = mkMesh(chamferBox(1.1, 0.14, 0.08, 0.02), matDarkMetal, [0, 0.32, 2.76]);

  // ==========================================
  // 2. FENDER ARCHES & HOVER POD NACELLES
  // ==========================================
  // 4 Aggressive Flared Wheel-less Arches
  const fenderPositions = [
    [-1.02, 0.48, 1.4],   // Front Left
    [1.02, 0.48, 1.4],    // Front Right
    [-1.08, 0.55, -1.3],  // Rear Left (Wider stance)
    [1.08, 0.55, -1.3],   // Rear Right
  ];

  fenderPositions.forEach(([x, y, z], idx) => {
    const isRear = idx >= 2;
    const w = isRear ? 0.36 : 0.30;
    const l = isRear ? 1.6 : 1.3;
    const h = isRear ? 0.52 : 0.44;
    const f = mkMesh(chamferBox(w, h, l, 0.04), matBody, [x, y, z]);
    f.rotation.z = (x < 0 ? 1 : -1) * D(4);

    // Side intake vent slit on each fender
    const vent = mkMesh(chamferBox(0.06, 0.10, l * 0.45, 0.02), matNeon, [x + (x < 0 ? -0.14 : 0.14), y, z]);

    // Underbelly Magnetic Hover-Discs
    const hoverPad = new THREE.Mesh(new THREE.CylinderGeometry(0.36, 0.38, 0.08, 24), matDarkMetal);
    hoverPad.position.set(x, 0.16, z);
    g.add(hoverPad);

    // Glowing Concentric Anti-Grav Core
    const hoverCore = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.25, 0.09, 20), matNeon);
    hoverCore.position.set(x, 0.15, z);
    g.add(hoverCore);
  });

  // Side Rocker Panels with Fender Decal
  const leftDoor = mkMesh(chamferBox(0.08, 0.38, 1.8, 0.02), matBody, [-0.98, 0.52, 0.05]);
  const rightDoor = mkMesh(chamferBox(0.08, 0.38, 1.8, 0.02), matBody, [0.98, 0.52, 0.05]);

  // Aethelgard Badge Plane on Right Door
  const badgeGeo = new THREE.PlaneGeometry(1.2, 0.3);
  const badgeMat = new THREE.MeshBasicMaterial({ map: T.fenderBadge(), transparent: true });
  const badgeL = new THREE.Mesh(badgeGeo, badgeMat);
  badgeL.position.set(-1.03, 0.52, 0.05); badgeL.rotation.y = -Math.PI / 2; g.add(badgeL);
  const badgeR = new THREE.Mesh(badgeGeo, badgeMat);
  badgeR.position.set(1.03, 0.52, 0.05); badgeR.rotation.y = Math.PI / 2; g.add(badgeR);

  // ==========================================
  // 3. COCKPIT CANOPY & HIGH-TECH INTERIOR
  // ==========================================
  // Translucent Fighter-Jet Canopy Bubble
  const canopy = mkMesh(chamferBox(1.24, 0.48, 1.95, 0.08), matGlass, [0, 0.95, 0.1]);
  canopy.rotation.x = D(-5);

  // Structural Roof Spine & Frame
  mkMesh(chamferBox(0.12, 0.06, 2.05, 0.02), matGold, [0, 1.20, 0.1]).rotation.x = D(-5);
  mkMesh(chamferBox(1.26, 0.05, 0.06, 0.02), matGold, [0, 1.15, -0.7]).rotation.x = D(-5);

  // Cockpit Interior Tub
  const interior = new THREE.Group(); interior.position.set(0, 0.65, 0.1); g.add(interior);
  // Floor & Console
  mkMesh(chamferBox(1.1, 0.12, 1.6, 0.02), matDarkMetal, [0, 0, 0], [0,0,0], interior);
  mkMesh(chamferBox(0.24, 0.22, 1.1, 0.02), matCarbon, [0, 0.15, 0], [0,0,0], interior);

  // 2 Race Bucket Seats
  for (const sx of [-0.32, 0.32]) {
    // Cushion
    mkMesh(chamferBox(0.38, 0.12, 0.45, 0.03), matCarbon, [sx, 0.12, -0.15], [0,0,0], interior);
    // Backrest
    const back = mkMesh(chamferBox(0.36, 0.52, 0.12, 0.03), matCarbon, [sx, 0.40, -0.38], [0,0,0], interior);
    back.rotation.x = D(-12);
    // Headrest with Gold Emblem
    mkMesh(chamferBox(0.24, 0.16, 0.09, 0.02), matGold, [sx, 0.68, -0.45], [D(-12),0,0], interior);
  }

  // Dashboard Telemetry Screen
  const dashScreen = mkMesh(chamferBox(0.55, 0.25, 0.04, 0.02), new THREE.MeshBasicMaterial({ map: T.dashboard() }), [0, 0.35, 0.58], [D(-25), 0, 0], interior);
  // Flight Yoke
  mkMesh(chamferBox(0.30, 0.14, 0.04, 0.01), matGold, [-0.32, 0.32, 0.35], [D(-20), 0, 0], interior);

  // ==========================================
  // 4. CANARD WINGLETS & REAR STABILIZER FINS
  // ==========================================
  // Mid Swept Canard Winglets
  const wingL = mkMesh(chamferBox(0.65, 0.05, 0.55, 0.02), matCarbon, [-1.25, 0.50, 0.3]);
  wingL.rotation.set(0, D(-18), D(5));
  const wingR = mkMesh(chamferBox(0.65, 0.05, 0.55, 0.02), matCarbon, [1.25, 0.50, 0.3]);
  wingR.rotation.set(0, D(18), D(-5));

  // Dual Angled Vertical Tailfins
  for (const [tx, rotZ] of [[-0.88, D(-15)], [0.88, D(15)]]) {
    const fin = mkMesh(chamferBox(0.08, 0.72, 1.0, 0.03), matBody, [tx, 1.02, -1.75]);
    fin.rotation.set(D(-14), 0, rotZ);
    // Glowing Cyan Edge on Fin
    const finEdge = mkMesh(chamferBox(0.04, 0.70, 0.06, 0.01), matNeon, [tx + (tx < 0 ? -0.04 : 0.04), 1.05, -1.3]);
    finEdge.rotation.set(D(-14), 0, rotZ);
  }

  // High-Downforce Rear Spoiler
  const spoilerStrutL = mkMesh(chamferBox(0.06, 0.45, 0.16, 0.02), matCarbon, [-0.55, 1.05, -2.1]);
  spoilerStrutL.rotation.x = D(-18);
  const spoilerStrutR = mkMesh(chamferBox(0.06, 0.45, 0.16, 0.02), matCarbon, [0.55, 1.05, -2.1]);
  spoilerStrutR.rotation.x = D(-18);

  const spoilerWing = mkMesh(chamferBox(2.25, 0.06, 0.45, 0.02), matCarbon, [0, 1.28, -2.25]);
  spoilerWing.rotation.x = D(-8);
  // Neon Cyan Underside Light Strip on Spoiler
  mkMesh(chamferBox(2.15, 0.02, 0.05, 0.01), matNeon, [0, 1.24, -2.25]);

  // ==========================================
  // 5. PROPULSION: DUAL PLASMA THRUSTER ENGINES
  // ==========================================
  const thrusterPos = [-0.55, 0.55];
  thrusterPos.forEach((x) => {
    // Outer Engine Cowling
    mkMesh(chamferBox(0.52, 0.46, 1.2, 0.04), matCarbon, [x, 0.58, -1.8]);

    // Stepped Titanium Exhaust Nozzle Ring
    const nozzleOuter = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.28, 0.28, 24, 1, true), matDarkMetal);
    nozzleOuter.rotation.x = Math.PI / 2;
    nozzleOuter.position.set(x, 0.58, -2.48);
    g.add(nozzleOuter);

    // Inner Concentric Gold Ring
    const nozzleInner = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.22, 0.22, 20, 1, true), matGold);
    nozzleInner.rotation.x = Math.PI / 2;
    nozzleInner.position.set(x, 0.58, -2.49);
    g.add(nozzleInner);

    // Glowing Cyan Plasma Core Disc
    const plasmaCore = new THREE.Mesh(new THREE.CircleGeometry(0.17, 24), matNeon);
    plasmaCore.position.set(x, 0.58, -2.50);
    plasmaCore.rotation.y = Math.PI;
    g.add(plasmaCore);

    // Concentric Center Needle
    const needle = new THREE.Mesh(new THREE.ConeGeometry(0.06, 0.25, 16), matDarkMetal);
    needle.position.set(x, 0.58, -2.38);
    needle.rotation.x = -Math.PI / 2;
    g.add(needle);
  });

  // Engine Deck Heat Exhaust Slats (Top deck)
  for (let z = -0.9; z >= -1.4; z -= 0.14) {
    mkMesh(chamferBox(0.85, 0.02, 0.06, 0.01), matGold, [0, 0.77, z]);
  }

  // Classic Roblox Stud Accents (4 studs on rear engine deck)
  for (const sx of [-0.25, 0.25]) {
    for (const sz of [-0.6, -0.78]) {
      const stud = new THREE.Mesh(new THREE.CylinderGeometry(0.05, 0.05, 0.03, 16), matGold);
      stud.position.set(sx, 0.78, sz);
      g.add(stud);
    }
  }

  // ==========================================
  // 6. LIGHTING SUITE: HEADLIGHTS, TAILLIGHTS, UNDERGLOW
  // ==========================================
  // Razor-Thin Full-Width Front LED Beam
  mkMesh(chamferBox(1.50, 0.045, 0.05, 0.01), matHeadlight, [0, 0.44, 2.76]);

  // Dual Lower Cyan Fog Slits
  mkMesh(chamferBox(0.28, 0.03, 0.04, 0.01), matNeon, [-0.55, 0.26, 2.75]);
  mkMesh(chamferBox(0.28, 0.03, 0.04, 0.01), matNeon, [0.55, 0.26, 2.75]);

  // Full-Width Aggressive Rear Crimson Brake Bar
  mkMesh(chamferBox(1.85, 0.06, 0.05, 0.01), matTaillight, [0, 0.68, -2.42]);
  // Lower center formula-one style hazard triangle
  const f1Light = mkMesh(chamferBox(0.22, 0.12, 0.04, 0.01), matTaillight, [0, 0.25, -2.48]);

  // Underglow Neon Tubes (Left & Right)
  const underglowL = mkMesh(chamferBox(0.04, 0.04, 3.2, 0.01), matNeon, [-0.85, 0.18, 0]);
  const underglowR = mkMesh(chamferBox(0.04, 0.04, 3.2, 0.01), matNeon, [0.85, 0.18, 0]);

  return g;
}

// 5-Angle Studio Turnaround Renderer for The Neon Speeder
import * as THREE from 'three';
import { makeEngine, lightRig } from './core/engine.js';
import { buildNeonSpeeder } from './speeder.js';
import { chamferBox, canvasTex } from './core/geo.js';

const D = THREE.MathUtils.degToRad;

const ANGLES = [
  { id: 'angle_1_hero', title: 'VIEW 01: FRONT 3/4 HERO', desc: 'Aggressive low-angle stance, nose splitter, LED bar, cockpit canopy', pos: [-3.8, 1.5, 4.0], target: [0, 0.58, 0.2], fov: 36 },
  { id: 'angle_2_side', title: 'VIEW 02: PURE SIDE PROFILE', desc: 'Sleek aerodynamic wedge, canard winglets, door badges, hover clearance', pos: [-6.2, 1.1, 0.0], target: [0, 0.58, 0.0], fov: 32 },
  { id: 'angle_3_rear', title: 'VIEW 03: REAR 3/4 THRUSTERS', desc: 'Dual plasma rocket engines, titanium nozzles, spoiler, crimson brake bar', pos: [3.8, 1.7, -4.0], target: [0, 0.58, -0.4], fov: 36 },
  { id: 'angle_4_front', title: 'VIEW 04: FRONT HEAD-ON', desc: 'Symmetrical width, razor-thin white LED beam, dual lower cyan fog lights', pos: [0.0, 1.05, 5.6], target: [0, 0.58, 0.8], fov: 32 },
  { id: 'angle_5_top', title: 'VIEW 05: TOP-DOWN 3/4 ELEVATED', desc: 'Dual gold racing stripes, canopy interior, heat slats, wing geometry', pos: [-3.2, 5.2, 2.4], target: [0, 0.45, 0.0], fov: 38 },
];

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas for rendering each angle
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Showroom Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#070B12');

  // Studio Lighting
  const lights = lightRig(scene, {
    key: '#FFFBEB', keyI: 2.5, keyPos: [5, 12, 6],
    rimCol: '#00F0FF', rimI: 1.4,
    sky: '#38BDF8', ground: '#0F172A', hemiI: 0.55,
    shadowBox: 12, target: [0, 0.5, 0]
  });

  // Secondary Warm Rim from opposite side
  const warmRim = new THREE.DirectionalLight('#F59E0B', 1.1);
  warmRim.position.set(-6, 5, -6);
  scene.add(warmRim);

  // Showroom Floor: Cyber Grid Reflective Hexagon Platform
  const floorTex = canvasTex('showroom_floor', 256, 256, (g, w, h) => {
    g.fillStyle = '#080D18'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#1E293B'; g.lineWidth = 2;
    g.strokeRect(0, 0, w, h);
    // Subtle crosshairs
    g.strokeStyle = 'rgba(0, 240, 255, 0.15)'; g.lineWidth = 1;
