// Headless Chrome capture for The Neon Speeder 5-Angle Turnaround
import { spawn } from 'node:child_process';
import http from 'node:http';
import fs from 'node:fs';
import os from 'node:os';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const CHROME = [
  process.env.CHROME,
  'C:/Program Files/Google/Chrome/Application/chrome.exe',
  'C:/Program Files (x86)/Google/Chrome/Application/chrome.exe',
].find((p) => p && fs.existsSync(p));

const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

const MIME = {
  '.html': 'text/html', '.js': 'text/javascript', '.mjs': 'text/javascript',
  '.json': 'application/json', '.png': 'image/png', '.jpg': 'image/jpeg',
  '.ttf': 'font/ttf', '.otf': 'font/otf'
};

function serve(port = 0) {
  return new Promise((res) => {
    const srv = http.createServer((req, r) => {
      const u = decodeURIComponent(req.url.split('?')[0]);
      const f = path.join(ROOT, u === '/' ? 'turnaround.html' : u);
      if (!f.startsWith(ROOT) || !fs.existsSync(f) || fs.statSync(f).isDirectory()) {
        r.writeHead(404); r.end(); return;
      }
      r.writeHead(200, { 'Content-Type': MIME[path.extname(f)] || 'application/octet-stream', 'Cache-Control': 'no-store' });
      fs.createReadStream(f).pipe(r);
    });
    srv.listen(port, '127.0.0.1', () => res(srv));
  });
}

async function run() {
  if (!CHROME) throw new Error('Google Chrome not found');
  const srv = await serve();
  const port = srv.address().port;
  console.log(`Server listening on http://127.0.0.1:${port}`);

  const prof = fs.mkdtempSync(path.join(os.tmpdir(), 'chrome-speeder-'));
  const chrome = spawn(CHROME, [
    '--headless=new', '--remote-debugging-port=0', `--user-data-dir=${prof}`,
    '--no-first-run', '--no-default-browser-check', '--hide-scrollbars',
    '--window-size=2400,1350', '--ignore-gpu-blocklist', '--disable-gpu-sandbox',
    '--enable-unsafe-swiftshader', '--disable-background-timer-throttling',
    'about:blank'
  ], { stdio: 'ignore' });

  let dbg;
  for (let i = 0; i < 200 && !dbg; i++) {
    try {
      dbg = fs.readFileSync(path.join(prof, 'DevToolsActivePort'), 'utf8').split('\n')[0].trim();
    } catch {
      await sleep(100);
    }
  }

  if (!dbg) {
    chrome.kill();
    fs.rmSync(prof, { recursive: true, force: true });
    srv.close();
    throw new Error('Chrome DevTools failed to start');
  }

  const url = `http://127.0.0.1:${port}/turnaround.html`;
  const r = await fetch(`http://127.0.0.1:${dbg}/json/new?${encodeURIComponent(url)}`, { method: 'PUT' });
  const target = await r.json();
  const ws = new WebSocket(target.webSocketDebuggerUrl);
  await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });

  let id = 0;
  const pend = new Map(), logs = [];
  ws.onmessage = (e) => {
    const m = JSON.parse(e.data);
    if (m.id && pend.has(m.id)) {
      const p = pend.get(m.id); pend.delete(m.id);
      m.error ? p.rej(new Error(m.error.message)) : p.res(m.result);
    } else if (m.method === 'Runtime.consoleAPICalled') {
      const text = m.params.args.map((a) => a.value ?? a.description).join(' ');
      console.log('CHROME LOG:', text);
    } else if (m.method === 'Runtime.exceptionThrown') {
      console.error('CHROME EXCEPTION:', m.params.exceptionDetails.text);
    }
  };

  const send = (method, params = {}) => new Promise((res, rej) => {
    const i = ++id; pend.set(i, { res, rej });
    ws.send(JSON.stringify({ id: i, method, params }));
  });

  const ev = async (expr) => {
    const x = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
    if (x.exceptionDetails) throw new Error(x.exceptionDetails.exception?.description || x.exceptionDetails.text);
    return x.result.value;
  };

  await send('Runtime.enable');

  console.log('Waiting for turnaround render...');
  for (let i = 0; ; i++) {
    const ready = await ev('window.READY === true').catch(() => false);
    if (ready) break;
    if (i > 300) throw new Error('Turnaround render timeout');
    await sleep(100);
  }

  console.log('Render complete! Fetching image buffers...');
  const images = await ev('window.RENDERED_IMAGES');

  const outDir = path.join(ROOT, 'review');
  fs.mkdirSync(outDir, { recursive: true });

  const saveBase64 = (filePath, dataUrl) => {
    const base64Data = dataUrl.replace(/^data:image\/png;base64,/, '');
    fs.writeFileSync(filePath, Buffer.from(base64Data, 'base64'));
    console.log(`Saved: ${filePath} (${Math.round(fs.statSync(filePath).size / 1024)} KB)`);
  };

  saveBase64(path.join(outDir, 'speeder_master_sheet.png'), images.master_sheet);
  saveBase64(path.join(outDir, 'speeder_angle_1_hero.png'), images.angle_1_hero);
  saveBase64(path.join(outDir, 'speeder_angle_2_side.png'), images.angle_2_side);
  saveBase64(path.join(outDir, 'speeder_angle_3_rear.png'), images.angle_3_rear);
  saveBase64(path.join(outDir, 'speeder_angle_4_front.png'), images.angle_4_front);
  saveBase64(path.join(outDir, 'speeder_angle_5_top.png'), images.angle_5_top);

  // Close everything
  ws.close();
  chrome.kill();
  srv.close();
  fs.rmSync(prof, { recursive: true, force: true });
  console.log('Done!');
}

run().catch((err) => {
  console.error('ERROR:', err);
  process.exit(1);
});

