    disc.position.set(x, 0.015, z);
    scene.add(disc);
  });

  const cam = new THREE.PerspectiveCamera(36, 1280 / 760, 0.1, 100);

  // 5-Panel Layout Coordinates on Master Sheet
  const PANELS = [
    { id: 'speeder_angle_1_hero', x: 50, y: 140, w: 1120, h: 560 },
    { id: 'speeder_angle_2_side', x: 1230, y: 140, w: 1120, h: 560 },
    { id: 'speeder_angle_3_rear', x: 50, y: 740, w: 730, h: 480 },
    { id: 'speeder_angle_4_front', x: 835, y: 740, w: 730, h: 480 },
    { id: 'speeder_angle_5_top', x: 1620, y: 740, w: 730, h: 480 },
  ];

  // Initialize Master Sheet Background
  masterCtx.fillStyle = '#060A12';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Background Cyber Grid
  masterCtx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < 2400; x += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Header Bar
  masterCtx.fillStyle = '#0B1324';
  masterCtx.fillRect(0, 0, 2400, 110);
  masterCtx.fillStyle = '#00F0FF';
  masterCtx.fillRect(0, 106, 2400, 4);

  // Header Typography
  masterCtx.font = '900 38px sans-serif';
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.fillText('AETHELGARD METROPOLIS // ASSET AUDIT 01', 50, 52);

  masterCtx.font = 'bold 20px monospace';
  masterCtx.fillStyle = '#F59E0B';
  masterCtx.fillText('CLASS 1: NEON SPEEDER (SPEC-R / MONARCH 01)', 52, 86);

  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillStyle = '#38BDF8';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('5-ANGLE ROBLOX 3D UGC MASTER SHEET • 100% IN-ENGINE THREE.JS', 2350, 56);
  masterCtx.fillStyle = '#64748B';
  masterCtx.fillText('RENDER: 2400x1350 • PCF SOFT SHADOWS • BLOOM PASS • DUAL PLASMA CORE', 2350, 86);
  masterCtx.textAlign = 'left';

  // Render and composite each angle
  for (let i = 0; i < ANGLES.length; i++) {
    const cfg = ANGLES[i];
    const p = PANELS[i];

    cam.fov = cfg.fov;
    cam.updateProjectionMatrix();
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    E.render(scene, cam, {
      bloom: 0.35,
      bloomThreshold: 1.25,
      bloomRadius: 0.50,
      exposure: 1.02,
      sat: 1.18,
      vignette: 0.18,
      focus: cam.position.distanceTo(new THREE.Vector3(...cfg.target)),
      aperture: 0.0004
    });

    // Save individual high-res angle image directly to disk
    const blob = await canvasToBlob(glCanvas);
    await uploadImage(`${cfg.id}.png`, blob);

    // Draw onto Master Sheet
    masterCtx.fillStyle = '#090F1D';
    masterCtx.fillRect(p.x, p.y, p.w, p.h);
    masterCtx.drawImage(glCanvas, p.x + 4, p.y + 4, p.w - 8, p.h - 50);

    masterCtx.strokeStyle = '#1E293B';
    masterCtx.lineWidth = 2;
    masterCtx.strokeRect(p.x, p.y, p.w, p.h);

    masterCtx.fillStyle = '#0B132B';
    masterCtx.fillRect(p.x, p.y + p.h - 46, p.w, 46);
    masterCtx.strokeStyle = '#00F0FF';
    masterCtx.lineWidth = 2;
    masterCtx.beginPath();
    masterCtx.moveTo(p.x, p.y + p.h - 46);
    masterCtx.lineTo(p.x + p.w, p.y + p.h - 46);
    masterCtx.stroke();

    masterCtx.fillStyle = '#00F0FF';
    masterCtx.fillRect(p.x, p.y, 16, 3);
    masterCtx.fillRect(p.x, p.y, 3, 16);
    masterCtx.fillRect(p.x + p.w - 16, p.y, 16, 3);
    masterCtx.fillRect(p.x + p.w - 3, p.y, 3, 16);

    masterCtx.font = 'bold 18px monospace';
    masterCtx.fillStyle = '#F59E0B';
    masterCtx.fillText(cfg.title, p.x + 16, p.y + p.h - 22);

    masterCtx.font = '13px sans-serif';
    masterCtx.fillStyle = '#94A3B8';
    masterCtx.textAlign = 'right';
    masterCtx.fillText(cfg.desc, p.x + p.w - 16, p.y + p.h - 22);
    masterCtx.textAlign = 'left';

    console.log(`RENDERED & SAVED: ${cfg.id}`);
  }

  // Footer Tagline
  masterCtx.fillStyle = '#475569';
  masterCtx.font = '14px monospace';
  masterCtx.fillText('STATUS: ASSET APPROVED FOR METROPOLIS SHOT 1 SKY-TRAFFIC • THREE.JS PROCEDURAL GLB READY', 50, 1315);

  // Save the master sheet directly
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('speeder_master_sheet.png', masterBlob);
  console.log('SAVED: speeder_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('TURNAROUND_ALL_COMPLETE');
}

window.initTurnaround = init;
init();

// The Apex Neon Speeder — Luxury Cyber Flying Cruiser (Roblox 3D Asset - Refined Supercar Edition)
import * as THREE from 'three';
import { chamferBox, canvasTex, T } from './core/geo.js';

const D = THREE.MathUtils.degToRad;

export function buildNeonSpeeder(opts = {}) {
  const g = new THREE.Group();

  // Colors & Materials
  const primaryCol = opts.primary || '#0F172A';    // Deep obsidian slate
  const secondaryCol = '#1E293B';                  // Charcoal trim
  const accentCol = opts.accent || '#F59E0B';      // Monarch Gold
  const neonCol = opts.neon || '#00F0FF';          // Electric Cyan
  const brakeCol = '#FF0055';                      // Neon Crimson

  // High-gloss automotive clear-coat material
  const matBody = new THREE.MeshStandardMaterial({
    color: primaryCol,
    roughness: 0.22,
    metalness: 0.65,
    envMapIntensity: 1.8,
  });

  const matTrim = new THREE.MeshStandardMaterial({
    color: secondaryCol,
    roughness: 0.38,
    metalness: 0.50,
  });

  const matCarbon = new THREE.MeshStandardMaterial({
    map: T.carbon('#0B0F19', '#1E293B', [16, 16]),
    roughness: 0.45,
    metalness: 0.35,
  });

  const matStripe = new THREE.MeshStandardMaterial({
    map: T.racingStripe(primaryCol, accentCol, neonCol),
    roughness: 0.20,
    metalness: 0.70,
  });

  const matGold = new THREE.MeshStandardMaterial({
    color: accentCol,
    roughness: 0.18,
    metalness: 0.90,
  });

  // Tinted Cyan Cockpit Windshield (High-gloss reflective glass)
  const matGlass = new THREE.MeshPhysicalMaterial({
    color: '#0891B2',
    roughness: 0.05,
    transmission: 0.60,
    thickness: 0.5,
    transparent: true,
    opacity: 0.85,
    reflectivity: 0.9,
    metalness: 0.2,
  });

  const matNeon = new THREE.MeshStandardMaterial({
    color: neonCol,
    emissive: neonCol,
    emissiveIntensity: 3.2,
    roughness: 0.1,
  });

  const matHeadlight = new THREE.MeshStandardMaterial({
    color: '#E0F2FE',
    emissive: '#38BDF8',
    emissiveIntensity: 4.2,
  });

  const matTaillight = new THREE.MeshStandardMaterial({
    color: brakeCol,
    emissive: brakeCol,
    emissiveIntensity: 3.5,
  });

  const matDarkMetal = new THREE.MeshStandardMaterial({
    color: '#0A0E17',
    roughness: 0.5,
    metalness: 0.8,
  });

  const mkMesh = (geo, mat, pos = [0,0,0], rot = [0,0,0], parent = g) => {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(...pos);
    m.rotation.set(...rot);
    m.castShadow = true;
    m.receiveShadow = true;
    parent.add(m);
    return m;
  };

  // ==========================================
  // 1. MAIN MONOCOQUE CHASSIS & HOOD
  // ==========================================
  // Lower carbon undertray (Total length 4.6m, width 2.1m)
  mkMesh(chamferBox(2.1, 0.20, 4.4, 0.04), matCarbon, [0, 0.28, -0.1]);

  // Main Mid-Body Monocoque
  mkMesh(chamferBox(1.75, 0.42, 3.2, 0.05), matStripe, [0, 0.54, -0.2]);

  // Sloped Front Hood (Aggressive sports car wedge rake)
  const hood = mkMesh(chamferBox(1.55, 0.24, 1.4, 0.04), matStripe, [0, 0.46, 1.6]);
  hood.rotation.x = D(-11);

  // Dual Hood Power Bulge Scoops
  for (const hx of [-0.42, 0.42]) {
    const scoop = mkMesh(chamferBox(0.26, 0.08, 0.9, 0.02), matCarbon, [hx, 0.58, 1.5]);
    scoop.rotation.x = D(-11);
    // Glowing cyan intake slit in front of scoop
    mkMesh(chamferBox(0.22, 0.03, 0.04, 0.01), matNeon, [hx, 0.58, 1.95]).rotation.x = D(-11);
  }

  // Front Aerodynamic Splitter Wing (Carbon fiber with gold tie-rods)
  mkMesh(chamferBox(2.0, 0.06, 0.55, 0.02), matCarbon, [0, 0.22, 2.35]);
  mkMesh(chamferBox(0.04, 0.14, 0.04, 0.01), matGold, [-0.6, 0.28, 2.35]);
  mkMesh(chamferBox(0.04, 0.14, 0.04, 0.01), matGold, [0.6, 0.28, 2.35]);

  // ==========================================
  // 2. AGGRESSIVE FENDER ARCHES & HOVER PODS
  // ==========================================
  // 4 Flared Widebody Wheel-less Fenders
  const fenderData = [
    { x: -0.96, z: 1.25, w: 0.34, l: 1.35, h: 0.46, rotZ: D(3) },   // Front Left
    { x: 0.96, z: 1.25, w: 0.34, l: 1.35, h: 0.46, rotZ: D(-3) },  // Front Right
    { x: -1.02, z: -1.15, w: 0.38, l: 1.65, h: 0.52, rotZ: D(4) }, // Rear Left (Muscular stance)
    { x: 1.02, z: -1.15, w: 0.38, l: 1.65, h: 0.52, rotZ: D(-4) }, // Rear Right
  ];

  fenderData.forEach((f) => {
    const mesh = mkMesh(chamferBox(f.w, f.h, f.l, 0.04), matBody, [f.x, 0.50, f.z]);
    mesh.rotation.z = f.rotZ;

    // Side aerodynamic air-blade with glowing cyan LED trace
    const blade = mkMesh(chamferBox(0.06, 0.12, f.l * 0.5, 0.02), matNeon, [f.x + (f.x < 0 ? -f.w * 0.48 : f.w * 0.48), 0.50, f.z]);

    // Recessed Magnetic Levitation Emitter Pad (Belly)
    const pad = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.34, 0.08, 24), matDarkMetal);
    pad.position.set(f.x, 0.18, f.z);
    g.add(pad);

    const padRing = new THREE.Mesh(new THREE.TorusGeometry(0.24, 0.035, 12, 24), matNeon);
    padRing.rotation.x = Math.PI / 2;
    padRing.position.set(f.x, 0.17, f.z);
    g.add(padRing);
  });

  // Side Rocker Panels & Doors
  mkMesh(chamferBox(0.10, 0.38, 1.45, 0.03), matBody, [-0.92, 0.52, 0.05]);
  mkMesh(chamferBox(0.10, 0.38, 1.45, 0.03), matBody, [0.92, 0.52, 0.05]);

  // Aethelgard Door Badges
  const badgeMat = new THREE.MeshBasicMaterial({ map: T.fenderBadge(), transparent: true });
  const bL = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 0.28), badgeMat);
  bL.position.set(-0.98, 0.52, 0.05); bL.rotation.y = -Math.PI / 2; g.add(bL);
  const bR = new THREE.Mesh(new THREE.PlaneGeometry(1.1, 0.28), badgeMat);
  bR.position.set(0.98, 0.52, 0.05); bR.rotation.y = Math.PI / 2; g.add(bR);

  // ==========================================
  // 3. SUPERCAR COCKPIT CANOPY & INTERIOR
  // ==========================================
  // Angled Windshield (Steep 28-degree rake forward)
  const windshield = mkMesh(chamferBox(1.15, 0.42, 0.85, 0.04), matGlass, [0, 0.88, 0.45]);
  windshield.rotation.x = D(-28);

  // Roof Canopy Cap
  const roof = mkMesh(chamferBox(1.10, 0.22, 1.1, 0.04), matGlass, [0, 1.05, -0.32]);
  roof.rotation.x = D(-6);

  // Rear Sloped Fastback Window
  const rearGlass = mkMesh(chamferBox(1.05, 0.28, 0.75, 0.04), matGlass, [0, 0.88, -1.05]);
  rearGlass.rotation.x = D(22);

  // Gold Structural Roof Spine (A-pillar to fastback)
  mkMesh(chamferBox(0.08, 0.05, 2.3, 0.02), matGold, [0, 1.12, -0.3]).rotation.x = D(-3);
  mkMesh(chamferBox(1.18, 0.05, 0.06, 0.02), matGold, [0, 1.05, 0.1]);

  // Cockpit Interior Tub & Detail
  const interior = new THREE.Group(); interior.position.set(0, 0.62, 0.0); g.add(interior);
  // Carbon center console
  mkMesh(chamferBox(0.24, 0.22, 1.2, 0.02), matCarbon, [0, 0.14, 0], [0,0,0], interior);
  // 2 Race Bucket Seats
  for (const sx of [-0.34, 0.34]) {
    // Cushion
    mkMesh(chamferBox(0.36, 0.12, 0.44, 0.03), matTrim, [sx, 0.12, -0.2], [0,0,0], interior);
    // Backrest
    const back = mkMesh(chamferBox(0.34, 0.54, 0.12, 0.03), matTrim, [sx, 0.42, -0.42], [D(-14),0,0], interior);
    // Gold Headrest
    mkMesh(chamferBox(0.22, 0.15, 0.09, 0.02), matGold, [sx, 0.72, -0.50], [D(-14),0,0], interior);
  }
  // Glowing Telemetry Dashboard Screen
  mkMesh(chamferBox(0.52, 0.24, 0.04, 0.02), new THREE.MeshBasicMaterial({ map: T.dashboard() }), [0, 0.38, 0.45], [D(-25), 0, 0], interior);
  // F1-Style Flight Yoke
  mkMesh(chamferBox(0.28, 0.14, 0.04, 0.01), matGold, [-0.34, 0.34, 0.26], [D(-20), 0, 0], interior);

  // ==========================================
  // 4. CANARD WINGLETS, VERTICAL TAILFINS & SPOILER
  // ==========================================
  // Swept Mid-Canard Winglets
  const wingL = mkMesh(chamferBox(0.55, 0.05, 0.65, 0.02), matCarbon, [-1.15, 0.52, 0.1]);
  wingL.rotation.set(0, D(-16), D(6));
  const wingR = mkMesh(chamferBox(0.55, 0.05, 0.65, 0.02), matCarbon, [1.15, 0.52, 0.1]);
  wingR.rotation.set(0, D(16), D(-6));

  // Dual Outward-Canted Vertical Tailfins
  for (const [tx, rotZ] of [[-0.85, D(-16)], [0.85, D(16)]]) {
    const fin = mkMesh(chamferBox(0.08, 0.68, 0.95, 0.03), matBody, [tx, 1.02, -1.65]);
    fin.rotation.set(D(-14), 0, rotZ);
    // Cyan illuminated fin tip
    const finTip = mkMesh(chamferBox(0.05, 0.08, 0.90, 0.01), matNeon, [tx + (tx < 0 ? -0.04 : 0.04), 1.34, -1.72]);
    finTip.rotation.set(D(-14), 0, rotZ);
  }

  // High-Downforce Carbon Supercar Spoiler
  const pylonL = mkMesh(chamferBox(0.06, 0.48, 0.16, 0.02), matCarbon, [-0.52, 1.02, -1.95]);
  pylonL.rotation.x = D(-22);
  const pylonR = mkMesh(chamferBox(0.06, 0.48, 0.16, 0.02), matCarbon, [0.52, 1.02, -1.95]);
  pylonR.rotation.x = D(-22);

  const spoilerWing = mkMesh(chamferBox(2.15, 0.06, 0.42, 0.02), matCarbon, [0, 1.25, -2.12]);
  spoilerWing.rotation.x = D(-8);
  // Full-width Cyan Neon Underside Glow on Spoiler
  mkMesh(chamferBox(2.05, 0.02, 0.05, 0.01), matNeon, [0, 1.21, -2.12]);

  // ==========================================
  // 5. PROPULSION: DUAL PLASMA ROCKET THRUSTERS
  // ==========================================
  for (const tx of [-0.52, 0.52]) {
    // Cylindrical Carbon Engine Housing
    const casing = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.26, 0.95, 20), matCarbon);
    casing.rotation.x = Math.PI / 2;
    casing.position.set(tx, 0.58, -1.65);
    g.add(casing);

    // Titanium Stepped Exhaust Nozzle Ring
    const nozzle = new THREE.Mesh(new THREE.CylinderGeometry(0.22, 0.26, 0.26, 24, 1, true), matDarkMetal);
    nozzle.rotation.x = Math.PI / 2;
    nozzle.position.set(tx, 0.58, -2.22);
    g.add(nozzle);

    // Inner Gold Retaining Lip
    const lip = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.21, 0.22, 20, 1, true), matGold);
    lip.rotation.x = Math.PI / 2;
    lip.position.set(tx, 0.58, -2.23);
    g.add(lip);

    // Glowing Cyan Plasma Core
    const core = new THREE.Mesh(new THREE.CircleGeometry(0.17, 24), matNeon);
    core.rotation.y = Math.PI;
    core.position.set(tx, 0.58, -2.24);
    g.add(core);

    // Center Afterburner Spike
    const spike = new THREE.Mesh(new THREE.ConeGeometry(0.05, 0.22, 16), matDarkMetal);
    spike.rotation.x = -Math.PI / 2;
    spike.position.set(tx, 0.58, -2.12);
    g.add(spike);
  }

  // Rear Engine Deck Ventilation Louvers (Gold slats)
  for (let z = -0.7; z >= -1.25; z -= 0.12) {
    mkMesh(chamferBox(0.82, 0.02, 0.05, 0.01), matGold, [0, 0.78, z]);
  }

  // Classic Roblox Stud Connectors (6 gold studs along engine deck)
  for (const sx of [-0.28, 0, 0.28]) {
    for (const sz of [-0.55, -0.72]) {
      const stud = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 0.025, 14), matGold);
      stud.position.set(sx, 0.79, sz);
      g.add(stud);
    }
  }

  // ==========================================
  // 6. LIGHTING SUITE: HYPER-LED HEADLIGHTS & TAILLIGHTS
  // ==========================================
  // Front Angular Cyber Headlights (Aggressive Quadra/Lamborghini style)
  for (const hx of [-0.60, 0.60]) {
    // Upper horizontal bar
    mkMesh(chamferBox(0.36, 0.045, 0.05, 0.01), matHeadlight, [hx, 0.46, 2.30]).rotation.y = (hx < 0 ? 1 : -1) * D(-12);
    // Angled vertical slash
    const slash = mkMesh(chamferBox(0.04, 0.14, 0.04, 0.01), matHeadlight, [hx + (hx < 0 ? -0.16 : 0.16), 0.39, 2.27]);
    slash.rotation.z = (hx < 0 ? 1 : -1) * D(25);
  }

  // Center Razor LED Monostrip
  mkMesh(chamferBox(0.65, 0.025, 0.04, 0.01), matHeadlight, [0, 0.44, 2.34]);

  // Full-Width Rear Crimson Brake Light Bar (Recessed under tail)
  mkMesh(chamferBox(1.78, 0.055, 0.05, 0.01), matTaillight, [0, 0.66, -2.18]);
  // F1-Style Rain / Reverse Light Flasher
  mkMesh(chamferBox(0.20, 0.10, 0.04, 0.01), matTaillight, [0, 0.28, -2.25]);

  // Underglow Neon Tubes (Left & Right)
  mkMesh(chamferBox(0.04, 0.04, 2.8, 0.01), matNeon, [-0.80, 0.20, -0.1]);
  mkMesh(chamferBox(0.04, 0.04, 2.8, 0.01), matNeon, [0.80, 0.20, -0.1]);

  return g;
}

// 5-Angle Studio Turnaround Renderer for The Neon Speeder (Refined Lighting & Proportions)
import * as THREE from 'three';
import { makeEngine, lightRig } from './core/engine.js';
import { buildNeonSpeeder } from './speeder.js';
import { canvasTex } from './core/geo.js';

const ANGLES = [
  { id: 'speeder_angle_1_hero', title: 'VIEW 01: FRONT 3/4 HERO', desc: 'Aggressive low-angle stance, nose splitter, LED bar, cockpit canopy', pos: [-3.4, 1.4, 3.2], target: [0, 0.55, 0.1], fov: 36 },
  { id: 'speeder_angle_2_side', title: 'VIEW 02: PURE SIDE PROFILE', desc: 'Sleek aerodynamic wedge, canard winglets, door badges, hover clearance', pos: [-5.4, 1.05, 0.0], target: [0, 0.55, 0.0], fov: 30 },
  { id: 'speeder_angle_3_rear', title: 'VIEW 03: REAR 3/4 THRUSTERS', desc: 'Dual plasma rocket engines, titanium nozzles, spoiler, crimson brake bar', pos: [3.4, 1.5, -3.2], target: [0, 0.55, -0.3], fov: 36 },
  { id: 'speeder_angle_4_front', title: 'VIEW 04: FRONT HEAD-ON', desc: 'Symmetrical width, razor-thin white LED beam, dual lower cyan fog lights', pos: [0.0, 0.95, 4.8], target: [0, 0.55, 0.6], fov: 32 },
  { id: 'speeder_angle_5_top', title: 'VIEW 05: TOP-DOWN 3/4 ELEVATED', desc: 'Dual gold racing stripes, canopy interior, heat slats, wing geometry', pos: [-2.8, 4.4, 1.8], target: [0, 0.45, 0.0], fov: 38 },
];

function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas for rendering each angle
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Showroom Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#060911');

  // High-End Automotive Studio Lighting
  const lights = lightRig(scene, {
    key: '#FFFBE8', keyI: 3.2, keyPos: [4.5, 11, 5.5],
    rimCol: '#00F0FF', rimI: 2.2,
    sky: '#38BDF8', ground: '#0F172A', hemiI: 0.68,
    shadowBox: 12, target: [0, 0.5, 0]
  });

  // Secondary Warm Gold Rim from rear-right
  const warmRim = new THREE.DirectionalLight('#F59E0B', 1.8);
  warmRim.position.set(-5, 4.5, -5);
  scene.add(warmRim);

  // Soft Front-Fill Light (preventing dark carbon crushing)
  const frontFill = new THREE.DirectionalLight('#93C5FD', 0.85);
  frontFill.position.set(-2, 3, 6);
  scene.add(frontFill);

  // Showroom Floor: Cyber Grid Reflective Hexagon Platform
  const floorTex = canvasTex('showroom_floor', 256, 256, (g, w, h) => {
    g.fillStyle = '#080D18'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#1E293B'; g.lineWidth = 2;
    g.strokeRect(0, 0, w, h);
    g.strokeStyle = 'rgba(0, 240, 255, 0.18)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(w/2, 0); g.lineTo(w/2, h); g.stroke();
    g.beginPath(); g.moveTo(0, h/2); g.lineTo(w, h/2); g.stroke();
  }, [14, 14]);

  const floorMat = new THREE.MeshStandardMaterial({
    map: floorTex,
    roughness: 0.30,
    metalness: 0.40,
  });

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(28, 28), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  scene.add(floor);

  // Circular Neon Trim Ring on Floor
  const ringGeo = new THREE.RingGeometry(4.0, 4.12, 64);
  const ringMat = new THREE.MeshBasicMaterial({ color: '#00F0FF', side: THREE.DoubleSide });
  const floorRing = new THREE.Mesh(ringGeo, ringMat);
  floorRing.rotation.x = -Math.PI / 2;
  floorRing.position.y = 0.01;
  scene.add(floorRing);

  // Outer Golden Perimeter Ring
  const outerRingGeo = new THREE.RingGeometry(6.2, 6.28, 64);
  const outerRingMat = new THREE.MeshBasicMaterial({ color: '#F59E0B', side: THREE.DoubleSide });
  const outerRing = new THREE.Mesh(outerRingGeo, outerRingMat);
  outerRing.rotation.x = -Math.PI / 2;
  outerRing.position.y = 0.01;
  scene.add(outerRing);

  // Build the Refined Speeder Asset
  const speeder = buildNeonSpeeder();
  speeder.position.set(0, 0.22, 0);
  scene.add(speeder);

  // Under-vehicle Blue Hover-glow Discs
  const hoverGlowMat = new THREE.MeshBasicMaterial({
    color: '#00D5FF',
    transparent: true,
    opacity: 0.55,
    side: THREE.DoubleSide,
  });

  const padCoords = [[-0.96, 1.25], [0.96, 1.25], [-1.02, -1.15], [1.02, -1.15]];
  padCoords.forEach(([x, z]) => {
    const disc = new THREE.Mesh(new THREE.CircleGeometry(0.52, 24), hoverGlowMat);
    disc.rotation.x = -Math.PI / 2;
    disc.position.set(x, 0.015, z);
    scene.add(disc);
  });

  const cam = new THREE.PerspectiveCamera(36, 1280 / 760, 0.1, 100);

  // 5-Panel Layout Coordinates on Master Sheet
  const PANELS = [
    { id: 'speeder_angle_1_hero', x: 50, y: 140, w: 1120, h: 560 },
    { id: 'speeder_angle_2_side', x: 1230, y: 140, w: 1120, h: 560 },
    { id: 'speeder_angle_3_rear', x: 50, y: 740, w: 730, h: 480 },
    { id: 'speeder_angle_4_front', x: 835, y: 740, w: 730, h: 480 },
    { id: 'speeder_angle_5_top', x: 1620, y: 740, w: 730, h: 480 },
  ];

  // Initialize Master Sheet Background
  masterCtx.fillStyle = '#060A12';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Background Cyber Grid
  masterCtx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < 2400; x += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Header Bar
  masterCtx.fillStyle = '#0B1324';
  masterCtx.fillRect(0, 0, 2400, 110);
  masterCtx.fillStyle = '#00F0FF';
  masterCtx.fillRect(0, 106, 2400, 4);

  // Header Typography
  masterCtx.font = '900 38px sans-serif';
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.fillText('AETHELGARD METROPOLIS // ASSET AUDIT 01', 50, 52);

  masterCtx.font = 'bold 20px monospace';
  masterCtx.fillStyle = '#F59E0B';
  masterCtx.fillText('CLASS 1: NEON SPEEDER (SPEC-R / MONARCH 01)', 52, 86);

  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillStyle = '#38BDF8';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('5-ANGLE ROBLOX 3D UGC MASTER SHEET • 100% IN-ENGINE THREE.JS', 2350, 56);
  masterCtx.fillStyle = '#64748B';
  masterCtx.fillText('RENDER: 2400x1350 • PCF SOFT SHADOWS • BLOOM PASS • DUAL PLASMA CORE', 2350, 86);
  masterCtx.textAlign = 'left';

  // Render and composite each angle
  for (let i = 0; i < ANGLES.length; i++) {
    const cfg = ANGLES[i];
    const p = PANELS[i];

    cam.fov = cfg.fov;
    cam.updateProjectionMatrix();
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    E.render(scene, cam, {
      bloom: 0.38,
      bloomThreshold: 1.20,
      bloomRadius: 0.52,
      exposure: 1.08,
      sat: 1.22,
      vignette: 0.16,
      focus: cam.position.distanceTo(new THREE.Vector3(...cfg.target)),
      aperture: 0.0003
    });

    // Save individual high-res angle image directly to disk
    const blob = await canvasToBlob(glCanvas);
    await uploadImage(`${cfg.id}.png`, blob);

    // Draw onto Master Sheet
    masterCtx.fillStyle = '#090F1D';
    masterCtx.fillRect(p.x, p.y, p.w, p.h);
    masterCtx.drawImage(glCanvas, p.x + 4, p.y + 4, p.w - 8, p.h - 50);

    masterCtx.strokeStyle = '#1E293B';
    masterCtx.lineWidth = 2;
    masterCtx.strokeRect(p.x, p.y, p.w, p.h);

    masterCtx.fillStyle = '#0B132B';
    masterCtx.fillRect(p.x, p.y + p.h - 46, p.w, 46);
    masterCtx.strokeStyle = '#00F0FF';
    masterCtx.lineWidth = 2;
    masterCtx.beginPath();
    masterCtx.moveTo(p.x, p.y + p.h - 46);
    masterCtx.lineTo(p.x + p.w, p.y + p.h - 46);
    masterCtx.stroke();

    masterCtx.fillStyle = '#00F0FF';
    masterCtx.fillRect(p.x, p.y, 16, 3);
    masterCtx.fillRect(p.x, p.y, 3, 16);
    masterCtx.fillRect(p.x + p.w - 16, p.y, 16, 3);
    masterCtx.fillRect(p.x + p.w - 3, p.y, 3, 16);

    masterCtx.font = 'bold 18px monospace';
    masterCtx.fillStyle = '#F59E0B';
    masterCtx.fillText(cfg.title, p.x + 16, p.y + p.h - 22);

    masterCtx.font = '13px sans-serif';
    masterCtx.fillStyle = '#94A3B8';
    masterCtx.textAlign = 'right';
    masterCtx.fillText(cfg.desc, p.x + p.w - 16, p.y + p.h - 22);
    masterCtx.textAlign = 'left';

    console.log(`RENDERED & SAVED: ${cfg.id}`);
  }

  // Footer Tagline
  masterCtx.fillStyle = '#475569';
  masterCtx.font = '14px monospace';
  masterCtx.fillText('STATUS: ASSET APPROVED FOR METROPOLIS SHOT 1 SKY-TRAFFIC • THREE.JS PROCEDURAL GLB READY', 50, 1315);

  // Save the master sheet directly
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('speeder_master_sheet.png', masterBlob);
  console.log('SAVED: speeder_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('TURNAROUND_ALL_COMPLETE');
}

window.initTurnaround = init;
init();

