function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas for rendering each angle
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Showroom Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#060911');

  // High-End Automotive Studio Lighting
  const lights = lightRig(scene, {
    key: '#FFFBE8', keyI: 2.8, keyPos: [4.5, 10, 5.5],
    rimCol: '#00F0FF', rimI: 1.6,
    sky: '#38BDF8', ground: '#0F172A', hemiI: 0.72,
    shadowBox: 12, target: [0, 0.5, 0]
  });

  // Secondary Warm Gold Rim from rear-right
  const warmRim = new THREE.DirectionalLight('#F59E0B', 1.4);
  warmRim.position.set(-5, 4.5, -5);
  scene.add(warmRim);

  // Soft Diffuse Front Fill (No harsh hot spots)
  const frontFill = new THREE.DirectionalLight('#93C5FD', 0.55);
  frontFill.position.set(-3, 6, 6);
  scene.add(frontFill);

  // Showroom Floor: Cyber Grid Reflective Hexagon Platform
  const floorTex = canvasTex('showroom_floor', 256, 256, (g, w, h) => {
    g.fillStyle = '#080D18'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#1E293B'; g.lineWidth = 2;
    g.strokeRect(0, 0, w, h);
    g.strokeStyle = 'rgba(0, 240, 255, 0.15)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(w/2, 0); g.lineTo(w/2, h); g.stroke();
    g.beginPath(); g.moveTo(0, h/2); g.lineTo(w, h/2); g.stroke();
  }, [14, 14]);

  const floorMat = new THREE.MeshStandardMaterial({
    map: floorTex,
    roughness: 0.30,
    metalness: 0.40,
  });

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(28, 28), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  scene.add(floor);

  // Circular Neon Trim Ring on Floor
  const ringGeo = new THREE.RingGeometry(4.0, 4.10, 64);
  const ringMat = new THREE.MeshBasicMaterial({ color: '#00F0FF', side: THREE.DoubleSide });
  const floorRing = new THREE.Mesh(ringGeo, ringMat);
  floorRing.rotation.x = -Math.PI / 2;
  floorRing.position.y = 0.01;
  scene.add(floorRing);

  // Outer Golden Perimeter Ring
  const outerRingGeo = new THREE.RingGeometry(6.2, 6.26, 64);
  const outerRingMat = new THREE.MeshBasicMaterial({ color: '#F59E0B', side: THREE.DoubleSide });
  const outerRing = new THREE.Mesh(outerRingGeo, outerRingMat);
  outerRing.rotation.x = -Math.PI / 2;
  outerRing.position.y = 0.01;
  scene.add(outerRing);

  // Build the Refined Speeder Asset
  const speeder = buildNeonSpeeder();
  speeder.position.set(0, 0.22, 0);
  scene.add(speeder);

  // Under-vehicle Blue Hover-glow Discs
  const hoverGlowMat = new THREE.MeshBasicMaterial({
    color: '#00D5FF',
    transparent: true,
    opacity: 0.40,
    side: THREE.DoubleSide,
  });

  const padCoords = [[-0.96, 1.25], [0.96, 1.25], [-1.02, -1.15], [1.02, -1.15]];
  padCoords.forEach(([x, z]) => {
    const disc = new THREE.Mesh(new THREE.CircleGeometry(0.50, 24), hoverGlowMat);
    disc.rotation.x = -Math.PI / 2;
    disc.position.set(x, 0.015, z);
    scene.add(disc);
  });

  const cam = new THREE.PerspectiveCamera(36, 1280 / 760, 0.1, 100);

  // 5-Panel Layout Coordinates on Master Sheet
  const PANELS = [
    { id: 'speeder_angle_1_hero', x: 50, y: 140, w: 1120, h: 560 },
    { id: 'speeder_angle_2_side', x: 1230, y: 140, w: 1120, h: 560 },
    { id: 'speeder_angle_3_rear', x: 50, y: 740, w: 730, h: 480 },
    { id: 'speeder_angle_4_front', x: 835, y: 740, w: 730, h: 480 },
    { id: 'speeder_angle_5_top', x: 1620, y: 740, w: 730, h: 480 },
  ];

  // Initialize Master Sheet Background
  masterCtx.fillStyle = '#060A12';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Background Cyber Grid
  masterCtx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < 2400; x += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Header Bar
  masterCtx.fillStyle = '#0B1324';
  masterCtx.fillRect(0, 0, 2400, 110);
  masterCtx.fillStyle = '#00F0FF';
  masterCtx.fillRect(0, 106, 2400, 4);

  // Header Typography
  masterCtx.font = '900 38px sans-serif';
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.fillText('AETHELGARD METROPOLIS // ASSET AUDIT 01', 50, 52);

  masterCtx.font = 'bold 20px monospace';
  masterCtx.fillStyle = '#F59E0B';
  masterCtx.fillText('CLASS 1: NEON SPEEDER (SPEC-R / MONARCH 01)', 52, 86);

  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillStyle = '#38BDF8';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('5-ANGLE ROBLOX 3D UGC MASTER SHEET • 100% IN-ENGINE THREE.JS', 2350, 56);
  masterCtx.fillStyle = '#64748B';
  masterCtx.fillText('RENDER: 2400x1350 • PCF SOFT SHADOWS • BLOOM PASS • DUAL PLASMA CORE', 2350, 86);
  masterCtx.textAlign = 'left';

  // Render and composite each angle
  for (let i = 0; i < ANGLES.length; i++) {
    const cfg = ANGLES[i];
    const p = PANELS[i];

    cam.fov = cfg.fov;
    cam.updateProjectionMatrix();
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    E.render(scene, cam, {
      bloom: 0.22,
      bloomThreshold: 1.35,
      bloomRadius: 0.45,
      exposure: 1.05,
      sat: 1.20,
      vignette: 0.16,
      focus: cam.position.distanceTo(new THREE.Vector3(...cfg.target)),
      aperture: 0.0002
    });

    // Save individual high-res angle image directly to disk
    const blob = await canvasToBlob(glCanvas);
    await uploadImage(`${cfg.id}.png`, blob);

    // Draw onto Master Sheet
    masterCtx.fillStyle = '#090F1D';
    masterCtx.fillRect(p.x, p.y, p.w, p.h);
    masterCtx.drawImage(glCanvas, p.x + 4, p.y + 4, p.w - 8, p.h - 50);

    masterCtx.strokeStyle = '#1E293B';
    masterCtx.lineWidth = 2;
    masterCtx.strokeRect(p.x, p.y, p.w, p.h);

    masterCtx.fillStyle = '#0B132B';
    masterCtx.fillRect(p.x, p.y + p.h - 46, p.w, 46);
    masterCtx.strokeStyle = '#00F0FF';
    masterCtx.lineWidth = 2;
    masterCtx.beginPath();
    masterCtx.moveTo(p.x, p.y + p.h - 46);
    masterCtx.lineTo(p.x + p.w, p.y + p.h - 46);
    masterCtx.stroke();

    masterCtx.fillStyle = '#00F0FF';
    masterCtx.fillRect(p.x, p.y, 16, 3);
    masterCtx.fillRect(p.x, p.y, 3, 16);
    masterCtx.fillRect(p.x + p.w - 16, p.y, 16, 3);
    masterCtx.fillRect(p.x + p.w - 3, p.y, 3, 16);

    masterCtx.font = 'bold 18px monospace';
    masterCtx.fillStyle = '#F59E0B';
    masterCtx.fillText(cfg.title, p.x + 16, p.y + p.h - 22);

    masterCtx.font = '13px sans-serif';
    masterCtx.fillStyle = '#94A3B8';
    masterCtx.textAlign = 'right';
    masterCtx.fillText(cfg.desc, p.x + p.w - 16, p.y + p.h - 22);
    masterCtx.textAlign = 'left';

    console.log(`RENDERED & SAVED: ${cfg.id}`);
  }

  // Footer Tagline
  masterCtx.fillStyle = '#475569';
  masterCtx.font = '14px monospace';
  masterCtx.fillText('STATUS: ASSET APPROVED FOR METROPOLIS SHOT 1 SKY-TRAFFIC • THREE.JS PROCEDURAL GLB READY', 50, 1315);

  // Save the master sheet directly
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('speeder_master_sheet.png', masterBlob);
  console.log('SAVED: speeder_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('TURNAROUND_ALL_COMPLETE');
}

window.initTurnaround = init;
init();

// The Sovereign Apex Citadel — Boss Skyscraper with Halo Rings & Orbiting Floating Islands
import * as THREE from 'three';
import { chamferBox, canvasTex, cachedGeo } from './core/geo.js';

const D = THREE.MathUtils.degToRad;

export function buildApexTower(opts = {}) {
  const g = new THREE.Group();

  // Colors & Materials
  const colObsidian = '#0A0E17';   // Dark obsidian monocoque
  const colMarble = '#F8FAFC';     // Pearlescent white marble
  const colGold = '#F59E0B';       // Sovereign Gold
  const colCyan = '#00F0FF';       // High-tech Cyan
  const colPurple = '#7E22CE';     // Monarch Purple
  const colRock = '#1E293B';       // Anti-grav dark crag

  // Texture Generators
  const texWindows = canvasTex('tower_windows', 256, 512, (ctx, w, h) => {
    ctx.fillStyle = '#0F172A'; ctx.fillRect(0, 0, w, h);
    ctx.fillStyle = '#38BDF8';
    // Vertical high-density illuminated window slits
    for (let x = 12; x < w - 12; x += 24) {
      for (let y = 16; y < h - 16; y += 32) {
        if ((x * 13 + y * 7) % 5 !== 0) {
          ctx.globalAlpha = 0.4 + ((x + y) % 6) * 0.1;
          ctx.fillRect(x, y, 14, 18);
        }
      }
    }
    ctx.globalAlpha = 1;
    // Gold architectural trim vertical mullions
    ctx.fillStyle = '#F59E0B';
    ctx.fillRect(0, 0, 8, h);
    ctx.fillRect(w - 8, 0, 8, h);
  }, [4, 8]);

  const texGuildHolo = canvasTex('guild_hologram', 512, 256, (ctx, w, h) => {
    ctx.fillStyle = 'rgba(0,0,0,0)'; ctx.clearRect(0, 0, w, h);
    ctx.strokeStyle = '#00F0FF'; ctx.lineWidth = 4;
    ctx.strokeRect(10, 10, w - 20, h - 20);
    // Outer diamond frame
    ctx.beginPath();
    ctx.moveTo(w / 2, 20); ctx.lineTo(w - 20, h / 2);
    ctx.lineTo(w / 2, h - 20); ctx.lineTo(20, h / 2);
    ctx.closePath(); ctx.stroke();
    // Guild text
    ctx.font = '900 36px sans-serif'; ctx.fillStyle = '#F59E0B'; ctx.textAlign = 'center';
    ctx.fillText('SOVEREIGN GUILD', w / 2, 90);
    ctx.font = 'bold 22px monospace'; ctx.fillStyle = '#00F0FF';
    ctx.fillText('[ RANK 1 // CITADEL 01 ]', w / 2, 130);
    ctx.font = 'bold 16px sans-serif'; ctx.fillStyle = '#C084FC';
    ctx.fillText('POWER LEVEL: 9,999,999', w / 2, 175);
    ctx.fillStyle = '#00F0FF';
    ctx.fillRect(w / 2 - 80, 195, 160, 4);
  }, [1, 1]);

  const matObsidian = new THREE.MeshStandardMaterial({
    color: colObsidian, roughness: 0.35, metalness: 0.65, envMapIntensity: 1.2
  });

  const matMarble = new THREE.MeshStandardMaterial({
    color: colMarble, roughness: 0.22, metalness: 0.15, envMapIntensity: 1.6
  });

  const matGold = new THREE.MeshStandardMaterial({
    color: colGold, roughness: 0.18, metalness: 0.92
  });

  const matWindows = new THREE.MeshStandardMaterial({
    map: texWindows, roughness: 0.25, metalness: 0.50
  });

  const matCyanNeon = new THREE.MeshStandardMaterial({
    color: colCyan, emissive: colCyan, emissiveIntensity: 2.4, roughness: 0.1
  });

  const matPurpleNeon = new THREE.MeshStandardMaterial({
    color: colPurple, emissive: colPurple, emissiveIntensity: 2.8, roughness: 0.1
  });

  const matCrystalCore = new THREE.MeshPhysicalMaterial({
    color: '#00F0FF', emissive: '#00B4D8', emissiveIntensity: 1.8,
    roughness: 0.05, transmission: 0.85, thickness: 1.2, transparent: true, opacity: 0.9
  });

  const matRock = new THREE.MeshStandardMaterial({
    color: colRock, roughness: 0.88, metalness: 0.1
  });

  const matGrass = new THREE.MeshStandardMaterial({
    color: '#059669', roughness: 0.75, metalness: 0.05
  });

  const mkMesh = (geo, mat, pos = [0,0,0], rot = [0,0,0], parent = g) => {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(...pos);
    m.rotation.set(...rot);
    m.castShadow = true;
    m.receiveShadow = true;
    parent.add(m);
    return m;
  };

  // ==============================================================
  // 1. FORTRESS FOUNDATION & LOWER BUTTRESSES (Y: 0m to 12m)
  // ==============================================================
  // Massive Octagonal Base Platform (Width 16m, Height 3m)
  const baseMat = new THREE.MeshStandardMaterial({ color: '#090D16', roughness: 0.4, metalness: 0.5 });
  const baseGeo = new THREE.CylinderGeometry(8.5, 9.8, 3.2, 8);
  mkMesh(baseGeo, baseMat, [0, 1.6, 0]);

  // Golden Foundation Trim Tier
  const baseGoldRing = new THREE.Mesh(new THREE.CylinderGeometry(8.6, 8.6, 0.4, 8), matGold);
  baseGoldRing.position.set(0, 3.2, 0); g.add(baseGoldRing);

  // 4 Diagonal Architectural Corner Buttress Pillars
  const angles = [0, Math.PI / 2, Math.PI, Math.PI * 1.5];
  angles.forEach((ang) => {
    const r = 7.2;
    const bx = Math.sin(ang) * r;
    const bz = Math.cos(ang) * r;
    const buttress = mkMesh(chamferBox(1.8, 14.0, 1.8, 0.08), matObsidian, [bx, 7.0, bz]);
    buttress.rotation.y = ang + Math.PI / 4;
    // Gold vertical spine
    mkMesh(chamferBox(0.3, 14.2, 0.3, 0.02), matGold, [bx, 7.0, bz]).rotation.y = ang + Math.PI / 4;
    // Cyan vertical conduit groove
    mkMesh(chamferBox(0.08, 13.5, 0.08, 0.01), matCyanNeon, [bx * 0.95, 7.0, bz * 0.95]);
  });

  // ==============================================================
  // 2. MID-TIER TOWER BODY & COMMERCE FLOORS (Y: 12m to 42m)
  // ==============================================================
  // Main Central Tower Monolith (Width 7.5m, Depth 7.5m, Height 30m)
  const midTower = mkMesh(chamferBox(7.2, 30.0, 7.2, 0.15), matWindows, [0, 18.0, 0]);

  // White Marble Corner Pilasters
  for (const mx of [-3.55, 3.55]) {
    for (const mz of [-3.55, 3.55]) {
      mkMesh(chamferBox(0.9, 30.2, 0.9, 0.06), matMarble, [mx, 18.0, mz]);
      mkMesh(chamferBox(0.2, 30.4, 0.2, 0.02), matGold, [mx, 18.0, mz]);
    }
  }

  // Giant 3D Holographic Guild Crest Billboard (Mounted on front facade)
  const holoPlane = new THREE.Mesh(new THREE.PlaneGeometry(7.0, 3.8), new THREE.MeshBasicMaterial({
    map: texGuildHolo, transparent: true, side: THREE.DoubleSide
  }));
  holoPlane.position.set(0, 22.0, 3.85);
  g.add(holoPlane);

  // Hologram Projector Brackets
  mkMesh(chamferBox(7.2, 0.25, 0.6, 0.02), matGold, [0, 24.1, 3.8]);
  mkMesh(chamferBox(7.2, 0.25, 0.6, 0.02), matGold, [0, 19.9, 3.8]);

  // Cantilevered VIP Landing Pad (Mid-tower balcony at Y = 28m)
  const padGrp = new THREE.Group(); padGrp.position.set(0, 28.0, -4.6); g.add(padGrp);
  mkMesh(chamferBox(5.5, 0.45, 4.2, 0.06), matObsidian, [0, 0, 0], [0,0,0], padGrp);
  // Gold edge border
  mkMesh(chamferBox(5.6, 0.15, 4.3, 0.02), matGold, [0, 0.22, 0], [0,0,0], padGrp);
  // Glowing Landing Circle
  const padRing = new THREE.Mesh(new THREE.RingGeometry(1.6, 1.75, 32), new THREE.MeshBasicMaterial({ color: colCyan, side: THREE.DoubleSide }));
  padRing.rotation.x = -Math.PI / 2; padRing.position.y = 0.25; padGrp.add(padRing);
  // Diagonal support trusses under pad
  const trussL = mkMesh(chamferBox(0.25, 4.5, 0.25, 0.02), matGold, [-2.2, -2.1, 1.2], [D(35), 0, 0], padGrp);
  const trussR = mkMesh(chamferBox(0.25, 4.5, 0.25, 0.02), matGold, [2.2, -2.1, 1.2], [D(35), 0, 0], padGrp);

  // ==============================================================
  // 3. UPPER SPONSOR TIER & BEVEL SETBACK (Y: 33m to 52m)
  // ==============================================================
  // Upper Tapered Spire Base
  mkMesh(chamferBox(5.4, 18.0, 5.4, 0.12), matObsidian, [0, 42.0, 0]);

  // Vertical Cyan Energy Ribbons along 4 faces
  for (const rotY of [0, Math.PI / 2, Math.PI, Math.PI * 1.5]) {
    const ribbon = mkMesh(chamferBox(0.25, 18.0, 0.15, 0.02), matCyanNeon, [0, 42.0, 2.76]);
    ribbon.rotation.y = rotY;
  }

  // ==============================================================
  // 4. THE GIANT DUAL HALO RINGS (ORBITING ENERGY ARCS)
  // ==============================================================
  const haloGroup = new THREE.Group();
  haloGroup.position.set(0, 52.0, 0);
  // Majestic tilt
  haloGroup.rotation.set(D(22), D(15), D(-8));
  g.add(haloGroup);

  // Outer Segmented Tech Ring (Radius 8.2m)
  const outerRingGeo = new THREE.TorusGeometry(8.2, 0.35, 16, 64);
  const outerRing = new THREE.Mesh(outerRingGeo, matGold);
  haloGroup.add(outerRing);

  // Outer Ring Cyan Energy Core
  const outerCoreGeo = new THREE.TorusGeometry(8.2, 0.14, 12, 64);
  const outerCore = new THREE.Mesh(outerCoreGeo, matCyanNeon);
  haloGroup.add(outerCore);

  // 8 Segmented Armor Clamps on Outer Ring
  for (let i = 0; i < 8; i++) {
    const ang = (i * Math.PI * 2) / 8;
    const cx = Math.cos(ang) * 8.2;
    const cy = Math.sin(ang) * 8.2;
    const clamp = mkMesh(chamferBox(0.95, 0.95, 0.55, 0.04), matObsidian, [cx, cy, 0], [0, 0, ang], haloGroup);
    mkMesh(chamferBox(0.25, 0.98, 0.25, 0.02), matPurpleNeon, [cx, cy, 0], [0, 0, ang], haloGroup);
  }

  // Inner Plasma Ring (Radius 6.4m, tilted counter to outer ring)
  const innerRingGeo = new THREE.TorusGeometry(6.4, 0.22, 16, 48);
  const innerRing = new THREE.Mesh(innerRingGeo, matPurpleNeon);
  innerRing.rotation.x = D(28);
  haloGroup.add(innerRing);

  // 4 Energy Tether Pylons Connecting Tower Neck to Halo
  angles.forEach((ang) => {
    const tx = Math.sin(ang) * 4.2;
    const tz = Math.cos(ang) * 4.2;
    const tether = mkMesh(chamferBox(0.20, 0.20, 4.6, 0.02), matCyanNeon, [tx, 52.0, tz]);
    tether.lookAt(new THREE.Vector3(0, 52.0, 0));
  });

  // ==============================================================
  // 5. DETACHED FLOATING APEX SPIRE & SOVEREIGN GEM (Y: 55m to 72m)
  // ==============================================================
  // Floating Gap of 3 meters between main tower and detached apex!
  const apexGroup = new THREE.Group();
  apexGroup.position.set(0, 56.5, 0);
  g.add(apexGroup);

  // Giant Glowing Crystalline Core Gem (Floating in the anti-grav gap)
  const gemGeo = new THREE.OctahedronGeometry(1.6, 0);
  const gem = new THREE.Mesh(gemGeo, matCrystalCore);
  gem.position.set(0, 0, 0);
  gem.scale.set(1.0, 1.8, 1.0);
  apexGroup.add(gem);

  // Inverted Lower Apex Funnel
  const lowerFunnel = new THREE.Mesh(new THREE.ConeGeometry(2.4, 3.2, 8), matGold);
  lowerFunnel.position.set(0, -1.8, 0);
  lowerFunnel.rotation.x = Math.PI;
  apexGroup.add(lowerFunnel);

  // Soaring Detached Master Spire Needle (Height 16m)
  const spireNeedle = new THREE.Mesh(new THREE.ConeGeometry(2.2, 16.0, 8), matMarble);
  spireNeedle.position.set(0, 9.2, 0);
  apexGroup.add(spireNeedle);

  // 4 Golden Corner Splines hugging the needle
  for (let i = 0; i < 4; i++) {
    const ang = (i * Math.PI * 2) / 4;
    const sx = Math.sin(ang) * 1.1;
    const sz = Math.cos(ang) * 1.1;
    const spine = mkMesh(chamferBox(0.18, 15.5, 0.18, 0.02), matGold, [sx, 9.0, sz], [0, ang, 0], apexGroup);
  }

  // Extreme Peak Beacon Light (Shooting vertical sky beam)
  const beaconCore = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 0.8, 12), matCyanNeon);
  beaconCore.position.set(0, 17.4, 0);
  apexGroup.add(beaconCore);

  // Vertical Volumetric Sky Beam Cylinder
  const beamGeo = new THREE.CylinderGeometry(0.18, 0.95, 45.0, 16, 1, true);
  const beamMat = new THREE.MeshBasicMaterial({
    color: '#00F0FF', transparent: true, opacity: 0.35, side: THREE.DoubleSide
  });
  const skyBeam = new THREE.Mesh(beamGeo, beamMat);
  skyBeam.position.set(0, 40.0, 0);
  apexGroup.add(skyBeam);

  // ==============================================================
  // 6. THREE ORBITING FLOATING SKY-ISLANDS (MINIATURE TERRAINS)
  // ==============================================================
  const ISLAND_CONFIGS = [
    // Island 1: West Floating Garden Estate (Y: 26m, Radius 11.5m)
    {
      pos: [-10.8, 25.5, 3.5], rotY: D(35), w: 6.2, d: 5.4, h: 4.2,
      hasBuilding: true, hasPad: true, bridgeTarget: [-3.6, 26.5, 1.2]
    },
    // Island 2: North-East Guild Courtyard (Y: 34m, Radius 10.5m)
    {
      pos: [8.5, 33.5, 6.2], rotY: D(-45), w: 5.2, d: 4.8, h: 3.8,
      hasBuilding: false, hasPad: true, bridgeTarget: [3.6, 34.0, 2.0]
    },
    // Island 3: South High Lookout Sanctuary (Y: 41m, Radius 9.2m)
    {
      pos: [2.5, 40.5, -9.0], rotY: D(110), w: 4.6, d: 4.2, h: 3.5,
      hasBuilding: true, hasPad: false, bridgeTarget: [1.0, 41.0, -2.7]
    },
  ];

  ISLAND_CONFIGS.forEach((isl, idx) => {
    const isGrp = new THREE.Group();
    isGrp.position.set(...isl.pos);
    isGrp.rotation.y = isl.rotY;
    g.add(isGrp);

    // Island Underside: Inverted Jagged Rock Stalactite (Anti-grav earth mass)
    const rockCrag = new THREE.Mesh(new THREE.ConeGeometry(isl.w * 0.48, isl.h, 7), matRock);
    rockCrag.position.set(0, -isl.h / 2, 0);
    rockCrag.rotation.x = Math.PI;
    isGrp.add(rockCrag);

    // Glowing Cyan Anti-Grav Crystal Deposit embedded in bottom of island rock
    const antiGravGem = new THREE.Mesh(new THREE.DodecahedronGeometry(0.45), matCyanNeon);
    antiGravGem.position.set(0, -isl.h * 0.85, 0);
    isGrp.add(antiGravGem);

    // Island Top Surface: Lush Green Lawn
    const grassTop = mkMesh(chamferBox(isl.w, 0.45, isl.d, 0.08), matGrass, [0, 0.15, 0], [0,0,0], isGrp);

    // Golden Perimeter Safety Balustrades
    const railMat = matGold;
    mkMesh(chamferBox(isl.w, 0.35, 0.06, 0.01), railMat, [0, 0.45, isl.d / 2 - 0.05], [0,0,0], isGrp);
    mkMesh(chamferBox(isl.w, 0.35, 0.06, 0.01), railMat, [0, 0.45, -isl.d / 2 + 0.05], [0,0,0], isGrp);
    mkMesh(chamferBox(0.06, 0.35, isl.d, 0.01), railMat, [isl.w / 2 - 0.05, 0.45, 0], [0,0,0], isGrp);

    // Optional Mini-House / Guild Pavilion on Island
    if (isl.hasBuilding) {
      const houseGrp = new THREE.Group(); houseGrp.position.set(-isl.w * 0.15, 0.35, 0); isGrp.add(houseGrp);
      // Modern white villa pod
      mkMesh(chamferBox(2.2, 1.6, 2.2, 0.05), matMarble, [0, 0.8, 0], [0,0,0], houseGrp);
      // Gold roof overhang
      mkMesh(chamferBox(2.6, 0.12, 2.6, 0.02), matGold, [0, 1.65, 0], [0,0,0], houseGrp);
      // Glowing Cyan panoramic window
      mkMesh(chamferBox(1.8, 0.8, 0.04, 0.01), matCyanNeon, [0, 0.85, 1.11], [0,0,0], houseGrp);
    }

    // Optional Private Landing Pad on Island
    if (isl.hasPad) {
      const padPos = isl.hasBuilding ? [isl.w * 0.28, 0.38, 0] : [0, 0.38, 0];
      const pad = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 0.95, 0.12, 20), matObsidian);
      pad.position.set(...padPos);
      isGrp.add(pad);
      const ring = new THREE.Mesh(new THREE.RingGeometry(0.7, 0.78, 24), new THREE.MeshBasicMaterial({ color: colCyan, side: THREE.DoubleSide }));
      ring.rotation.x = -Math.PI / 2; ring.position.set(padPos[0], padPos[1] + 0.07, padPos[2]);
      isGrp.add(ring);
    }

    // Translucent Energy Sky-Bridge Beam connecting Island to Main Tower
    const bridgeStart = new THREE.Vector3(...isl.pos);
    const bridgeEnd = new THREE.Vector3(...isl.bridgeTarget);
    const bridgeDist = bridgeStart.distanceTo(bridgeEnd);
    const bridgeMid = bridgeStart.clone().lerp(bridgeEnd, 0.5);

    const bridgeMesh = new THREE.Mesh(new THREE.BoxGeometry(0.65, 0.08, bridgeDist), new THREE.MeshBasicMaterial({
      color: colCyan, transparent: true, opacity: 0.55
    }));
    bridgeMesh.position.copy(bridgeMid);
    bridgeMesh.lookAt(bridgeEnd);
    g.add(bridgeMesh);
  });

  return g;
}

// 5-Angle Studio Turnaround Renderer for The Sovereign Apex Citadel (Boss Tower)
import * as THREE from 'three';
import { makeEngine, lightRig } from './core/engine.js';
import { buildApexTower } from './apex_tower.js';
import { canvasTex } from './core/geo.js';

const ANGLES = [
  { id: 'tower_angle_1_hero', title: 'VIEW 01: GROUND-UP HERO LOOM', desc: 'Monolithic perspective looking up at base, floating islands, and halo rings', pos: [-24, 6, 26], target: [0, 34, 0], fov: 48 },
  { id: 'tower_angle_2_profile', title: 'VIEW 02: FULL ELEVATION SILHOUETTE', desc: 'Complete 75m vertical profile from fortress foundation to apex sky beam', pos: [-55, 35, 0], target: [0, 35, 0], fov: 42 },
  { id: 'tower_angle_3_halo_apex', title: 'VIEW 03: HALO RINGS & DETACHED APEX', desc: 'Dual tilted tech halo rings, anti-grav gap, crystal core, and needle spire', pos: [-18, 56, 18], target: [0, 55, 0], fov: 38 },
  { id: 'tower_angle_4_island', title: 'VIEW 04: ORBITAL ISLAND & SKY-BRIDGE', desc: 'Floating garden estate, anti-grav rock stalactite, villa, and cyan energy beam', pos: [-19, 31, 12], target: [-10.8, 26.0, 3.5], fov: 36 },
  { id: 'tower_angle_5_topdown', title: 'VIEW 05: AERIAL ISOMETRIC OVERLOOK', desc: 'Bird-eye view looking down through halo rings, radial islands, and VIP pad', pos: [-28, 75, 24], target: [0, 40, 0], fov: 45 },
];

function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Studio Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#05070D');

  // Studio Lighting for Massive Monumental Skyscraper
  const lights = lightRig(scene, {
    key: '#FFFBE8', keyI: 3.0, keyPos: [25, 65, 35],
    rimCol: '#00F0FF', rimI: 2.0,
    sky: '#38BDF8', ground: '#0F172A', hemiI: 0.75,
    shadowBox: 45, target: [0, 30, 0]
  });

  // Secondary Warm Gold Rim from rear-right
  const warmRim = new THREE.DirectionalLight('#F59E0B', 1.8);
  warmRim.position.set(-25, 45, -30);
  scene.add(warmRim);

  // Soft Front Fill from lower-left
  const frontFill = new THREE.DirectionalLight('#93C5FD', 0.65);
  frontFill.position.set(-15, 25, 30);
  scene.add(frontFill);

  // Showroom Base Cyber Platform
  const floorTex = canvasTex('tower_base_grid', 256, 256, (g, w, h) => {
    g.fillStyle = '#070B14'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#1E293B'; g.lineWidth = 2;
    g.strokeRect(0, 0, w, h);
    g.strokeStyle = 'rgba(0, 240, 255, 0.12)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(w/2, 0); g.lineTo(w/2, h); g.stroke();
    g.beginPath(); g.moveTo(0, h/2); g.lineTo(w, h/2); g.stroke();
  }, [24, 24]);

  const floorMat = new THREE.MeshStandardMaterial({
    map: floorTex, roughness: 0.35, metalness: 0.40
  });

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(120, 120), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  scene.add(floor);

  // Concentric Foundation Grid Rings
  for (const r of [16, 28, 42]) {
    const ringGeo = new THREE.RingGeometry(r, r + 0.15, 64);
    const ringMat = new THREE.MeshBasicMaterial({ color: r === 28 ? '#F59E0B' : '#00F0FF', side: THREE.DoubleSide });
    const ringMesh = new THREE.Mesh(ringGeo, ringMat);
    ringMesh.rotation.x = -Math.PI / 2;
    ringMesh.position.y = 0.02;
    scene.add(ringMesh);
  }

  // Build the Boss Apex Tower Asset
  const tower = buildApexTower();
  scene.add(tower);

  const cam = new THREE.PerspectiveCamera(45, 1280 / 760, 0.1, 300);

  // 5-Panel Layout Coordinates on Master Sheet (2400 x 1350)
  const PANELS = [
    { id: 'tower_angle_1_hero', x: 50, y: 140, w: 1120, h: 560 },
    { id: 'tower_angle_2_profile', x: 1230, y: 140, w: 1120, h: 560 },
    { id: 'tower_angle_3_halo_apex', x: 50, y: 740, w: 730, h: 480 },
    { id: 'tower_angle_4_island', x: 835, y: 740, w: 730, h: 480 },
    { id: 'tower_angle_5_topdown', x: 1620, y: 740, w: 730, h: 480 },
  ];

  // Initialize Master Sheet Canvas
  masterCtx.fillStyle = '#060A12';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Background Grid Lines
  masterCtx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < 2400; x += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Header Bar
  masterCtx.fillStyle = '#0B1324';
  masterCtx.fillRect(0, 0, 2400, 110);
  masterCtx.fillStyle = '#00F0FF';
  masterCtx.fillRect(0, 106, 2400, 4);

  // Header Typography
  masterCtx.font = '900 38px sans-serif';
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.fillText('AETHELGARD METROPOLIS // ASSET AUDIT 02', 50, 52);

  masterCtx.font = 'bold 20px monospace';
  masterCtx.fillStyle = '#F59E0B';
  masterCtx.fillText('TYPE 1: THE SOVEREIGN APEX CITADEL (BOSS TOWER // RANK 1 GUILD)', 52, 86);

  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillStyle = '#38BDF8';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('5-ANGLE ROBLOX 3D UGC MASTER SHEET • 100% IN-ENGINE THREE.JS', 2350, 56);
  masterCtx.fillStyle = '#64748B';
  masterCtx.fillText('HALO RINGS • 3 FLOATING ISLANDS • CRYSTAL APEX • 75M MONOLITH', 2350, 86);
  masterCtx.textAlign = 'left';

  // Render and composite each angle
  for (let i = 0; i < ANGLES.length; i++) {
    const cfg = ANGLES[i];
    const p = PANELS[i];

    cam.fov = cfg.fov;
    cam.updateProjectionMatrix();
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    E.render(scene, cam, {
      bloom: 0.25,
      bloomThreshold: 1.30,
      bloomRadius: 0.48,
      exposure: 1.05,
      sat: 1.20,
      vignette: 0.16,
      focus: cam.position.distanceTo(new THREE.Vector3(...cfg.target)),
      aperture: 0.0001
    });

    // Save individual angle image
    const blob = await canvasToBlob(glCanvas);
    await uploadImage(`${cfg.id}.png`, blob);

    // Draw onto Master Sheet
    masterCtx.fillStyle = '#090F1D';
    masterCtx.fillRect(p.x, p.y, p.w, p.h);
    masterCtx.drawImage(glCanvas, p.x + 4, p.y + 4, p.w - 8, p.h - 50);

    masterCtx.strokeStyle = '#1E293B';
    masterCtx.lineWidth = 2;
    masterCtx.strokeRect(p.x, p.y, p.w, p.h);

    masterCtx.fillStyle = '#0B132B';
    masterCtx.fillRect(p.x, p.y + p.h - 46, p.w, 46);
    masterCtx.strokeStyle = '#00F0FF';
    masterCtx.lineWidth = 2;
    masterCtx.beginPath();
    masterCtx.moveTo(p.x, p.y + p.h - 46);
    masterCtx.lineTo(p.x + p.w, p.y + p.h - 46);
    masterCtx.stroke();

    masterCtx.fillStyle = '#00F0FF';
    masterCtx.fillRect(p.x, p.y, 16, 3);
    masterCtx.fillRect(p.x, p.y, 3, 16);
    masterCtx.fillRect(p.x + p.w - 16, p.y, 16, 3);
    masterCtx.fillRect(p.x + p.w - 3, p.y, 3, 16);

    masterCtx.font = 'bold 18px monospace';
    masterCtx.fillStyle = '#F59E0B';
    masterCtx.fillText(cfg.title, p.x + 16, p.y + p.h - 22);

    masterCtx.font = '13px sans-serif';
    masterCtx.fillStyle = '#94A3B8';
    masterCtx.textAlign = 'right';
    masterCtx.fillText(cfg.desc, p.x + p.w - 16, p.y + p.h - 22);
    masterCtx.textAlign = 'left';

    console.log(`RENDERED & SAVED: ${cfg.id}`);
  }

  // Footer Tagline
  masterCtx.fillStyle = '#475569';
  masterCtx.font = '14px monospace';
  masterCtx.fillText('STATUS: ASSET APPROVED FOR METROPOLIS SHOT 1 SKYLINE MONUMENT • PROCEDURAL GLB READY', 50, 1315);

  // Save the master sheet directly
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('tower_master_sheet.png', masterBlob);
  console.log('SAVED: tower_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('TOWER_TURNAROUND_COMPLETE');
}

window.initTurnaround = init;
init();

