const targetHtml = process.argv[2] || 'turnaround.html';

function serve(port = 0) {
  const outDir = path.join(ROOT, 'review');
  fs.mkdirSync(outDir, { recursive: true });

  return new Promise((res) => {
    const srv = http.createServer((req, r) => {
      // Direct binary image save endpoint
      if (req.method === 'POST' && req.url.startsWith('/save')) {
        const u = new URL(req.url, 'http://127.0.0.1');
        const name = u.searchParams.get('name') || 'unnamed.png';
        const targetPath = path.join(outDir, name);
        const out = fs.createWriteStream(targetPath);
        req.pipe(out).on('finish', () => {
          console.log(`Saved: ${targetPath} (${Math.round(fs.statSync(targetPath).size / 1024)} KB)`);
          r.writeHead(200, { 'Content-Type': 'text/plain' });
          r.end('OK');
        });
        return;
      }

      const u = decodeURIComponent(req.url.split('?')[0]);
      const f = path.join(ROOT, u === '/' ? targetHtml : u);
      if (!f.startsWith(ROOT) || !fs.existsSync(f) || fs.statSync(f).isDirectory()) {
        r.writeHead(404); r.end(); return;
      }
      r.writeHead(200, { 'Content-Type': MIME[path.extname(f)] || 'application/octet-stream', 'Cache-Control': 'no-store' });
      fs.createReadStream(f).pipe(r);
    });
    srv.listen(port, '127.0.0.1', () => res(srv));
  });
}

