    g.beginPath(); g.moveTo(190, 16); g.lineTo(240, 16); g.lineTo(225, 48); g.lineTo(175, 48); g.closePath();
    g.fillStyle = '#00F0FF'; g.fill();
  }, [1, 1]),

  // Roblox Sky-Taxi Checkerboard Waistline Stripe
  taxiChecker: () => canvasTex('taxi_checker', 256, 64, (g, w, h) => {
    g.fillStyle = '#FBBF24'; g.fillRect(0, 0, w, h);
    const sq = 32;
    for (let x = 0; x < w; x += sq) {
      for (let y = 0; y < h; y += sq) {
        const isBlack = (Math.floor(x / sq) + Math.floor(y / sq)) % 2 === 0;
        g.fillStyle = isBlack ? '#0F172A' : '#FFFFFF';
        g.fillRect(x, y, sq, sq);
      }
    }
  }, [4, 1]),

  // Glowing Holographic Roof Taxi Sign
  taxiRoofSign: () => canvasTex('taxi_roof_sign', 256, 128, (g, w, h) => {
    g.fillStyle = '#0F172A'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#F59E0B'; g.lineWidth = 4;
    g.strokeRect(6, 6, w - 12, h - 12);
    g.fillStyle = '#FBBF24'; g.font = '900 52px sans-serif'; g.textAlign = 'center';
    g.fillText('TAXI', w / 2, 65);
    g.font = 'bold 20px monospace'; g.fillStyle = '#00F0FF';
    g.fillText('FARE: 50R // SKY-CAB', w / 2, 102);
  }, [1, 1]),

  // Commuter License Plate
  taxiPlate: () => canvasTex('taxi_plate', 128, 64, (g, w, h) => {
    g.fillStyle = '#FFFFFF'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#0F172A'; g.lineWidth = 3; g.strokeRect(4, 4, w - 8, h - 8);
    g.fillStyle = '#0F172A'; g.font = '900 24px monospace'; g.textAlign = 'center';
    g.fillText('CAB-42', w / 2, 42);
  }, [1, 1])
};

args.Target:
  // Badge / Decal on Side Fender
  fenderBadge: () => canvasTex('fender_badge', 256, 64, (g, w, h) => {
    g.fillStyle = 'rgba(0,0,0,0)'; g.clearRect(0, 0, w, h);
    g.fillStyle = '#F59E0B'; g.font = '900 28px sans-serif';
    g.fillText('AETHELGARD', 10, 34);
    g.fillStyle = '#00F0FF'; g.font = 'bold 16px monospace';
    g.fillText('MONARCH 01', 12, 54);
    g.strokeStyle = '#00F0FF'; g.lineWidth = 3;
    g.beginPath(); g.moveTo(190, 16); g.lineTo(240, 16); g.lineTo(225, 48); g.lineTo(175, 48); g.closePath();
    g.fillStyle = '#00F0FF'; g.fill();
  }, [1, 1])
};

