// Class 2: The Commuter Sky-Taxi (Roblox Yellow Hover-Cab)
import * as THREE from 'three';
import { chamferBox, canvasTex, T } from './core/geo.js';

const D = THREE.MathUtils.degToRad;

export function buildSkyTaxi(opts = {}) {
  const g = new THREE.Group();

  // Colors & Materials
  const colYellow = opts.color || '#FBBF24';    // Iconic Vibrant Taxi Yellow
  const colCharcoal = '#1E293B';                 // Dark Trim
  const colCyan = '#00F0FF';                     // High-tech Cyan
  const colAmber = '#F59E0B';                    // Hazard Amber
  const colBrake = '#FF0044';                    // Crimson Taillight

  const matBody = new THREE.MeshStandardMaterial({
    color: colYellow, roughness: 0.28, metalness: 0.35, envMapIntensity: 1.4
  });

  const matDark = new THREE.MeshStandardMaterial({
    color: colCharcoal, roughness: 0.45, metalness: 0.55
  });

  const matChecker = new THREE.MeshStandardMaterial({
    map: T.taxiChecker(), roughness: 0.35, metalness: 0.25
  });

  const matGlass = new THREE.MeshPhysicalMaterial({
    color: '#0284C7', roughness: 0.08, transmission: 0.70,
    thickness: 0.4, transparent: true, opacity: 0.75, metalness: 0.15
  });

  const matNeon = new THREE.MeshStandardMaterial({
    color: colCyan, emissive: colCyan, emissiveIntensity: 2.0, roughness: 0.1
  });

  const matAmber = new THREE.MeshStandardMaterial({
    color: colAmber, emissive: colAmber, emissiveIntensity: 2.4, roughness: 0.1
  });

  const matHeadlight = new THREE.MeshStandardMaterial({
    color: '#F8FAFC', emissive: '#E0F2FE', emissiveIntensity: 2.5
  });

  const matTaillight = new THREE.MeshStandardMaterial({
    color: colBrake, emissive: colBrake, emissiveIntensity: 2.2
  });

  const mkMesh = (geo, mat, pos = [0,0,0], rot = [0,0,0], parent = g) => {
    const m = new THREE.Mesh(geo, mat);
    m.position.set(...pos);
    m.rotation.set(...rot);
    m.castShadow = true;
    m.receiveShadow = true;
    parent.add(m);
    return m;
  };

  // ==========================================
  // 1. MAIN TAXI CHASSIS & LOWER TRAY
  // ==========================================
  // Lower dark skid tray (Length 3.8m, Width 1.9m, Height 0.22m)
  mkMesh(chamferBox(1.9, 0.22, 3.8, 0.04), matDark, [0, 0.28, 0]);

  // Main Yellow Body Tub
  mkMesh(chamferBox(1.82, 0.48, 3.7, 0.06), matBody, [0, 0.58, 0]);

  // Checkerboard Beltline Stripe (Runs along left and right side)
  mkMesh(chamferBox(0.04, 0.14, 3.5, 0.01), matChecker, [-0.92, 0.65, 0]);
  mkMesh(chamferBox(0.04, 0.14, 3.5, 0.01), matChecker, [0.92, 0.65, 0]);

  // Front Sloped Hood (Chunky friendly bevel)
  const hood = mkMesh(chamferBox(1.68, 0.26, 1.1, 0.05), matBody, [0, 0.68, 1.3]);
  hood.rotation.x = D(-8);

  // Front Grille & Bumper
  mkMesh(chamferBox(1.75, 0.18, 0.15, 0.03), matDark, [0, 0.42, 1.88]);
  // Chrome / Yellow Grille Slats
  for (let y = 0.38; y <= 0.46; y += 0.04) {
    mkMesh(chamferBox(0.9, 0.015, 0.02, 0.005), matAmber, [0, y, 1.95]);
  }

  // Front & Rear License Plates
  const plateMat = new THREE.MeshBasicMaterial({ map: T.taxiPlate() });
  const fPlate = new THREE.Mesh(new THREE.PlaneGeometry(0.5, 0.24), plateMat);
  fPlate.position.set(0, 0.32, 1.96); g.add(fPlate);

  const rPlate = new THREE.Mesh(new THREE.PlaneGeometry(0.5, 0.24), plateMat);
  rPlate.position.set(0, 0.38, -1.91); rPlate.rotation.y = Math.PI; g.add(rPlate);

  // ==========================================
  // 2. CABIN GREENHOUSE & INTERIOR
  // ==========================================
  // Upright Wrap-Around Windshield (Steep friendly angle)
  const windshield = mkMesh(chamferBox(1.62, 0.52, 0.85, 0.04), matGlass, [0, 1.05, 0.52]);
  windshield.rotation.x = D(-24);

  // Passenger Cabin Greenhouse Body (Side windows & roof)
  mkMesh(chamferBox(1.62, 0.58, 1.8, 0.05), matGlass, [0, 1.12, -0.4]);

  // Yellow Roof Cap
  mkMesh(chamferBox(1.65, 0.12, 2.3, 0.04), matBody, [0, 1.44, -0.15]);

  // Yellow A-Pillars & B-Pillars
  mkMesh(chamferBox(0.08, 0.55, 0.08, 0.02), matBody, [-0.78, 1.08, 0.75]).rotation.x = D(-24);
  mkMesh(chamferBox(0.08, 0.55, 0.08, 0.02), matBody, [0.78, 1.08, 0.75]).rotation.x = D(-24);
  mkMesh(chamferBox(0.08, 0.58, 0.10, 0.02), matBody, [-0.79, 1.12, -0.35]);
  mkMesh(chamferBox(0.08, 0.58, 0.10, 0.02), matBody, [0.79, 1.12, -0.35]);

  // Interior: Seats, Taxi Meter & Yoke
  const interior = new THREE.Group(); interior.position.set(0, 0.72, 0); g.add(interior);
  // Front Driver Seat (Left side)
  mkMesh(chamferBox(0.42, 0.14, 0.44, 0.03), matDark, [-0.36, 0.10, 0.1], [0,0,0], interior);
  mkMesh(chamferBox(0.40, 0.50, 0.12, 0.03), matDark, [-0.36, 0.38, -0.1], [D(-10),0,0], interior);
  // Rear Passenger Bench Seat
  mkMesh(chamferBox(1.35, 0.15, 0.50, 0.03), matDark, [0, 0.10, -0.85], [0,0,0], interior);
  mkMesh(chamferBox(1.35, 0.52, 0.14, 0.03), matDark, [0, 0.38, -1.05], [D(-10),0,0], interior);

  // Dashboard & Glowing Taxi Meter Screen
  mkMesh(chamferBox(1.3, 0.22, 0.35, 0.02), matDark, [0, 0.25, 0.55], [0,0,0], interior);
  // Taxi Meter Fare Box
  const meterBox = mkMesh(chamferBox(0.24, 0.14, 0.08, 0.01), matAmber, [0.15, 0.42, 0.6], [D(-15), 0, 0], interior);

  // ==========================================
  // 3. ROOFTOP HOLOGRAPHIC TAXI SIGN
  // ==========================================
  const roofSignGrp = new THREE.Group(); roofSignGrp.position.set(0, 1.54, 0.05); g.add(roofSignGrp);
  // Aerodynamic Pod Base
  mkMesh(chamferBox(0.9, 0.10, 0.45, 0.02), matDark, [0, 0, 0], [0,0,0], roofSignGrp);

  // Dual-Sided Illuminated TAXI Sign
  const signMat = new THREE.MeshBasicMaterial({ map: T.taxiRoofSign() });
  const signF = new THREE.Mesh(new THREE.PlaneGeometry(0.85, 0.32), signMat);
  signF.position.set(0, 0.18, 0.04); roofSignGrp.add(signF);

  const signB = new THREE.Mesh(new THREE.PlaneGeometry(0.85, 0.32), signMat);
  signB.position.set(0, 0.18, -0.04); signB.rotation.y = Math.PI; roofSignGrp.add(signB);

  // Flashing Amber Beacon on Top of Sign
  const beacon = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.08, 0.12, 16), matAmber);
  beacon.position.set(0, 0.38, 0);
  roofSignGrp.add(beacon);

  // ==========================================
  // 4. PROPULSION: 4 HOVER PODS & REAR ION THRUSTERS
  // ==========================================
  // 4 Corner Magnetic Levitation Hover Pods
  const hoverCoords = [
    [-0.92, 1.25],   // Front Left
    [0.92, 1.25],    // Front Right
    [-0.92, -1.25],  // Rear Left
    [0.92, -1.25],   // Rear Right
  ];

  hoverCoords.forEach(([x, z]) => {
    // Outer nacelle housing
    const nacelle = mkMesh(chamferBox(0.32, 0.38, 0.75, 0.03), matDark, [x, 0.42, z]);
    // Cyan LED accent slit on nacelle
    mkMesh(chamferBox(0.03, 0.08, 0.45, 0.01), matNeon, [x + (x < 0 ? -0.16 : 0.16), 0.42, z]);

    // Recessed Underbelly Levitation Ring
    const pad = new THREE.Mesh(new THREE.CylinderGeometry(0.28, 0.30, 0.08, 20), matDark);
    pad.position.set(x, 0.18, z);
    g.add(pad);

    const padRing = new THREE.Mesh(new THREE.TorusGeometry(0.20, 0.03, 12, 20), matNeon);
    padRing.rotation.x = Math.PI / 2;
    padRing.position.set(x, 0.17, z);
    g.add(padRing);
  });

  // Dual Rear Cylindrical Ion Thrusters
  for (const rx of [-0.45, 0.45]) {
    const thruster = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.22, 0.45, 20), matDark);
    thruster.rotation.x = Math.PI / 2;
    thruster.position.set(rx, 0.48, -1.82);
    g.add(thruster);

    // Glowing Cyan Core Disc
    const core = new THREE.Mesh(new THREE.CircleGeometry(0.15, 20), matNeon);
    core.rotation.y = Math.PI;
    core.position.set(rx, 0.48, -2.05);
    g.add(core);
  }

  // Rear Engine Honeycomb Heat Grille
  mkMesh(chamferBox(0.70, 0.25, 0.05, 0.01), matDark, [0, 0.50, -1.88]);

  // ==========================================
  // 5. LIGHTING SUITE: HEADLIGHTS & TAILLIGHTS
  // ==========================================
  // Dual Classic Round Roblox Headlights with Chrome Rings
  for (const hx of [-0.62, 0.62]) {
    const chromeBezel = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.16, 0.04, 20), matBody);
    chromeBezel.rotation.x = Math.PI / 2;
    chromeBezel.position.set(hx, 0.58, 1.88);
    g.add(chromeBezel);

    const bulb = new THREE.Mesh(new THREE.CircleGeometry(0.13, 20), matHeadlight);
    bulb.position.set(hx, 0.58, 1.91);
    g.add(bulb);

    // Lower Amber Turn Signals
    mkMesh(chamferBox(0.20, 0.04, 0.04, 0.01), matAmber, [hx, 0.44, 1.90]);
  }

  // Full-Width Rear Crimson Brake Light Bar
  mkMesh(chamferBox(1.65, 0.06, 0.04, 0.01), matTaillight, [0, 0.70, -1.88]);
  // Dual Lower Vertical Red Reflectors
  mkMesh(chamferBox(0.04, 0.16, 0.03, 0.01), matTaillight, [-0.75, 0.42, -1.88]);
  mkMesh(chamferBox(0.04, 0.16, 0.03, 0.01), matTaillight, [0.75, 0.42, -1.88]);

  // Side Mirror Pods with Amber LED Turn Blinkers
  for (const mx of [-0.94, 0.94]) {
    mkMesh(chamferBox(0.18, 0.12, 0.14, 0.02), matBody, [mx, 0.92, 0.55]);
    mkMesh(chamferBox(0.02, 0.04, 0.12, 0.01), matAmber, [mx + (mx < 0 ? -0.09 : 0.09), 0.92, 0.55]);
  }

  return g;
}

// 5-Angle Studio Turnaround Renderer for The Commuter Sky-Taxi (Roblox Yellow Hover-Cab)
import * as THREE from 'three';
import { makeEngine, lightRig } from './core/engine.js';
import { buildSkyTaxi } from './taxi.js';
import { canvasTex } from './core/geo.js';

const ANGLES = [
  { id: 'taxi_angle_1_hero', title: 'VIEW 01: FRONT 3/4 HERO', desc: 'Vibrant yellow body, checkerboard stripe, headlights, TAXI roof sign', pos: [-3.2, 1.4, 3.2], target: [0, 0.75, 0.1], fov: 35 },
  { id: 'taxi_angle_2_side', title: 'VIEW 02: PURE SIDE PROFILE', desc: 'Classic boxy Roblox proportions, hover clearance, side windows, checker beltline', pos: [-5.2, 1.1, 0.0], target: [0, 0.75, 0.0], fov: 30 },
  { id: 'taxi_angle_3_rear', title: 'VIEW 03: REAR 3/4 THRUSTERS', desc: 'Dual ion thrusters, honeycomb grille, crimson taillights, rear TAXI sign', pos: [3.2, 1.5, -3.2], target: [0, 0.75, -0.2], fov: 35 },
  { id: 'taxi_angle_4_front', title: 'VIEW 04: FRONT HEAD-ON', desc: 'Symmetrical width, round chrome headlights, grille slats, CAB-42 plate', pos: [0.0, 0.85, 4.4], target: [0, 0.70, 0.5], fov: 32 },
  { id: 'taxi_angle_5_top', title: 'VIEW 05: TOP-DOWN 3/4 ELEVATED', desc: 'Roof pod beacon, wrap-around windshield, interior seats & taxi meter', pos: [-2.8, 4.2, 1.8], target: [0, 0.65, 0.0], fov: 36 },
];

function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Showroom Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#060911');

  // High-End Automotive Studio Lighting
  const lights = lightRig(scene, {
    key: '#FFFBE8', keyI: 3.0, keyPos: [4.5, 10, 5.5],
    rimCol: '#00F0FF', rimI: 1.8,
    sky: '#38BDF8', ground: '#0F172A', hemiI: 0.72,
    shadowBox: 12, target: [0, 0.6, 0]
  });

  // Secondary Warm Gold Rim
  const warmRim = new THREE.DirectionalLight('#F59E0B', 1.6);
  warmRim.position.set(-5, 4.5, -5);
  scene.add(warmRim);

  // Soft Front Fill Light
  const frontFill = new THREE.DirectionalLight('#93C5FD', 0.65);
  frontFill.position.set(-2, 4, 6);
  scene.add(frontFill);

  // Showroom Floor: Cyber Grid Reflective Hexagon Platform
  const floorTex = canvasTex('showroom_floor', 256, 256, (g, w, h) => {
    g.fillStyle = '#080D18'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#1E293B'; g.lineWidth = 2;
    g.strokeRect(0, 0, w, h);
    g.strokeStyle = 'rgba(0, 240, 255, 0.15)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(w/2, 0); g.lineTo(w/2, h); g.stroke();
    g.beginPath(); g.moveTo(0, h/2); g.lineTo(w, h/2); g.stroke();
  }, [14, 14]);

  const floorMat = new THREE.MeshStandardMaterial({
    map: floorTex, roughness: 0.30, metalness: 0.40
  });

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(28, 28), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  scene.add(floor);

  // Circular Neon Trim Ring on Floor
  const ringGeo = new THREE.RingGeometry(3.6, 3.72, 64);
  const ringMat = new THREE.MeshBasicMaterial({ color: '#FBBF24', side: THREE.DoubleSide });
  const floorRing = new THREE.Mesh(ringGeo, ringMat);
  floorRing.rotation.x = -Math.PI / 2;
  floorRing.position.y = 0.01;
  scene.add(floorRing);

  // Build the Sky-Taxi Asset
  const taxi = buildSkyTaxi();
  taxi.position.set(0, 0.22, 0);
  scene.add(taxi);

  // Under-vehicle Blue Hover-glow Discs
  const hoverGlowMat = new THREE.MeshBasicMaterial({
    color: '#00D5FF', transparent: true, opacity: 0.45, side: THREE.DoubleSide
  });

  const padCoords = [[-0.92, 1.25], [0.92, 1.25], [-0.92, -1.25], [0.92, -1.25]];
  padCoords.forEach(([x, z]) => {
    const disc = new THREE.Mesh(new THREE.CircleGeometry(0.48, 24), hoverGlowMat);
    disc.rotation.x = -Math.PI / 2;
    disc.position.set(x, 0.015, z);
    scene.add(disc);
  });

  const cam = new THREE.PerspectiveCamera(35, 1280 / 760, 0.1, 100);

  // 5-Panel Layout Coordinates on Master Sheet (2400 x 1350)
  const PANELS = [
    { id: 'taxi_angle_1_hero', x: 50, y: 140, w: 1120, h: 560 },
    { id: 'taxi_angle_2_side', x: 1230, y: 140, w: 1120, h: 560 },
    { id: 'taxi_angle_3_rear', x: 50, y: 740, w: 730, h: 480 },
    { id: 'taxi_angle_4_front', x: 835, y: 740, w: 730, h: 480 },
    { id: 'taxi_angle_5_top', x: 1620, y: 740, w: 730, h: 480 },
  ];

  // Initialize Master Sheet Canvas
  masterCtx.fillStyle = '#060A12';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Background Grid Lines
  masterCtx.strokeStyle = 'rgba(255, 255, 255, 0.03)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < 2400; x += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Header Bar
  masterCtx.fillStyle = '#0B1324';
  masterCtx.fillRect(0, 0, 2400, 110);
  masterCtx.fillStyle = '#FBBF24';
  masterCtx.fillRect(0, 106, 2400, 4);

  // Header Typography
  masterCtx.font = '900 38px sans-serif';
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.fillText('AETHELGARD METROPOLIS // ASSET AUDIT 03', 50, 52);

  masterCtx.font = 'bold 20px monospace';
  masterCtx.fillStyle = '#FBBF24';
  masterCtx.fillText('CLASS 2: COMMUTER SKY-TAXI (ROBLOX HOVER-CAB // CAB-42)', 52, 86);

  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillStyle = '#38BDF8';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('5-ANGLE ROBLOX 3D UGC MASTER SHEET • 100% IN-ENGINE THREE.JS', 2350, 56);
  masterCtx.fillStyle = '#64748B';
  masterCtx.fillText('RENDER: 2400x1350 • CHECKERBOARD BELTLINE • ROOFTOP TAXI SIGN • 4 HOVER PODS', 2350, 86);
  masterCtx.textAlign = 'left';

  // Render and composite each angle
  for (let i = 0; i < ANGLES.length; i++) {
    const cfg = ANGLES[i];
    const p = PANELS[i];

    cam.fov = cfg.fov;
    cam.updateProjectionMatrix();
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    E.render(scene, cam, {
      bloom: 0.22,
      bloomThreshold: 1.35,
      bloomRadius: 0.45,
      exposure: 1.05,
      sat: 1.20,
      vignette: 0.16,
      focus: cam.position.distanceTo(new THREE.Vector3(...cfg.target)),
      aperture: 0.0002
    });

    // Save individual angle image
    const blob = await canvasToBlob(glCanvas);
    await uploadImage(`${cfg.id}.png`, blob);

    // Draw onto Master Sheet
    masterCtx.fillStyle = '#090F1D';
    masterCtx.fillRect(p.x, p.y, p.w, p.h);
    masterCtx.drawImage(glCanvas, p.x + 4, p.y + 4, p.w - 8, p.h - 50);

    masterCtx.strokeStyle = '#1E293B';
    masterCtx.lineWidth = 2;
    masterCtx.strokeRect(p.x, p.y, p.w, p.h);

    masterCtx.fillStyle = '#0B132B';
    masterCtx.fillRect(p.x, p.y + p.h - 46, p.w, 46);
    masterCtx.strokeStyle = '#FBBF24';
    masterCtx.lineWidth = 2;
    masterCtx.beginPath();
    masterCtx.moveTo(p.x, p.y + p.h - 46);
    masterCtx.lineTo(p.x + p.w, p.y + p.h - 46);
    masterCtx.stroke();

    masterCtx.fillStyle = '#FBBF24';
    masterCtx.fillRect(p.x, p.y, 16, 3);
    masterCtx.fillRect(p.x, p.y, 3, 16);
    masterCtx.fillRect(p.x + p.w - 16, p.y, 16, 3);
    masterCtx.fillRect(p.x + p.w - 3, p.y, 3, 16);

    masterCtx.font = 'bold 16px monospace';
    masterCtx.fillStyle = '#FBBF24';
    masterCtx.fillText(cfg.title, p.x + 16, p.y + p.h - 22);

    masterCtx.font = '12px sans-serif';
    masterCtx.fillStyle = '#94A3B8';
    masterCtx.textAlign = 'right';
    masterCtx.fillText(cfg.desc, p.x + p.w - 16, p.y + p.h - 22);
    masterCtx.textAlign = 'left';

    console.log(`RENDERED & SAVED: ${cfg.id}`);
  }

  // Footer Tagline
  masterCtx.fillStyle = '#475569';
  masterCtx.font = '14px monospace';
  masterCtx.fillText('STATUS: ASSET APPROVED FOR METROPOLIS SHOT 1 COMMUTER TRAFFIC • PROCEDURAL GLB READY', 50, 1315);

  // Save the master sheet directly
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('taxi_master_sheet.png', masterBlob);
  console.log('SAVED: taxi_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('TAXI_TURNAROUND_COMPLETE');
}

window.initTurnaround = init;
init();

