  // Industrial Yellow/Black Diagonal Hazard Stripes
  hazardStripe: () => canvasTex('hazard_stripe', 256, 256, (g, w, h) => {
    g.fillStyle = '#F59E0B'; g.fillRect(0, 0, w, h);
    g.fillStyle = '#0F172A';
    const stripeWidth = 32;
    for (let x = -h; x < w + h; x += stripeWidth * 2) {
      g.beginPath();
      g.moveTo(x, 0);
      g.lineTo(x + stripeWidth, 0);
      g.lineTo(x + stripeWidth + h, h);
      g.lineTo(x + h, h);
      g.closePath();
      g.fill();
    }
  }, [4, 1]),

  // Shipping Container Corrugated Metal Skin + Stencil
  containerCorrugated: (baseColor = '#D97706', label = 'RO-CARGO') => canvasTex(`cnt_${baseColor}_${label}`, 256, 128, (g, w, h) => {
