    // Vertical corrugation ribs
    const ribStep = 16;
    for (let x = 0; x < w; x += ribStep) {
      g.fillStyle = 'rgba(0,0,0,0.18)';
      g.fillRect(x + 10, 0, 6, h);
      g.fillStyle = 'rgba(255,255,255,0.12)';
      g.fillRect(x, 0, 4, h);
    }
    // Stencil plate
    g.fillStyle = '#0F172A';
    g.fillRect(24, 20, 150, 42);
    g.strokeStyle = '#FBBF24'; g.lineWidth = 2;
