// 5-Angle Studio Turnaround Renderer for The Heavy Sky-Barge (Titan-88 Cargo Hauler)
import * as THREE from 'three';
import { makeEngine, lightRig } from './core/engine.js';
import { buildCargoBarge } from './cargo_barge.js';
import { canvasTex } from './core/geo.js';

const ANGLES = [
  { id: 'barge_angle_1_hero', title: 'VIEW 01: FRONT 3/4 HERO', desc: 'Titan-88 command bridge, hazard bumper, 4x VTOL pods, cargo stack', pos: [14.0, 7.5, 12.0], target: [0, 2.2, 0], fov: 36 },
  { id: 'barge_angle_2_side', title: 'VIEW 02: PURE SIDE PROFILE', desc: '14-meter armored keel, outrigger turbine nacelles, dual container bays', pos: [0.0, 4.2, 18.5], target: [0, 2.2, 0], fov: 32 },
  { id: 'barge_angle_3_rear', title: 'VIEW 03: REAR 3/4 THRUSTERS', desc: 'Twin super-heavy ion bells, rear VTOL pods, cryo cargo container', pos: [-14.5, 7.0, -11.5], target: [-1.0, 2.2, 0], fov: 36 },
  { id: 'barge_angle_4_front', title: 'VIEW 04: FRONT HEAD-ON', desc: 'Pusher cowcatcher, roof floodlights, symmetrical VTOL outriggers', pos: [18.0, 4.8, 0.0], target: [2.0, 2.2, 0], fov: 30 },
  { id: 'barge_angle_5_top', title: 'VIEW 05: TOP-DOWN 3/4 ELEVATED', desc: 'Bridge studs, tie-down latches, 3-container stack, vector thrust layout', pos: [8.0, 18.5, 12.5], target: [0, 1.8, 0], fov: 35 },
];

function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Showroom Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#05070D');

  // High-End Industrial Automotive Studio Lighting
  const lights = lightRig(scene, {
    key: '#FFFBE8', keyI: 3.2, keyPos: [12, 22, 14],
    rimCol: '#00F0FF', rimI: 2.2,
    sky: '#38BDF8', ground: '#0F172A', hemiI: 0.75,
    shadowBox: 28, target: [0, 2.0, 0]
  });

  // Secondary Warm Gold Rim
  const warmRim = new THREE.DirectionalLight('#F59E0B', 1.8);
  warmRim.position.set(-12, 10, -12);
  scene.add(warmRim);

  // Soft Front Fill Light
  const frontFill = new THREE.DirectionalLight('#93C5FD', 0.8);
  frontFill.position.set(6, 8, 14);
  scene.add(frontFill);

  // Showroom Floor: Cyber Grid Reflective Hexagon Platform
  const floorTex = canvasTex('barge_showroom_floor', 256, 256, (g, w, h) => {
    g.fillStyle = '#080C16'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#1E293B'; g.lineWidth = 2;
    g.strokeRect(0, 0, w, h);
    g.strokeStyle = 'rgba(245, 158, 11, 0.15)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(w / 2, 0); g.lineTo(w / 2, h); g.stroke();
    g.beginPath(); g.moveTo(0, h / 2); g.lineTo(w, h / 2); g.stroke();
  }, [24, 24]);

  const floorMat = new THREE.MeshStandardMaterial({
    map: floorTex, roughness: 0.32, metalness: 0.45
  });

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(60, 60), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  scene.add(floor);

  // Circular Neon Trim Ring on Floor
  const ringGeo = new THREE.RingGeometry(11.8, 12.0, 80);
  const ringMat = new THREE.MeshBasicMaterial({ color: '#F59E0B', side: THREE.DoubleSide });
  const floorRing = new THREE.Mesh(ringGeo, ringMat);
  floorRing.rotation.x = -Math.PI / 2;
  floorRing.position.y = 0.01;
  scene.add(floorRing);

  // Build the Heavy Sky-Barge Asset
  const barge = buildCargoBarge();
  scene.add(barge);

  // Render individual angles
  const renderedBitmaps = [];

  for (const angle of ANGLES) {
    E.cam.fov = angle.fov;
    E.cam.position.set(...angle.pos);
    E.cam.lookAt(new THREE.Vector3(...angle.target));
    E.cam.updateProjectionMatrix();

    E.render(scene);

    // Save individual angle render
    const blob = await canvasToBlob(glCanvas);
    await uploadImage(`${angle.id}.png`, blob);
    console.log(`RENDERED & SAVED: ${angle.id}`);

    // Create ImageBitmap for compositing master sheet
    const bmp = await createImageBitmap(glCanvas);
    renderedBitmaps.push({ bmp, angle });
  }

  // --------------------------------------------------------------------------
  // COMPOSITE MASTER 5-ANGLE INSPECTION SHEET (2400 x 1350)
  // --------------------------------------------------------------------------
  const MW = 2400;
  const MH = 1350;
  masterCanvas.width = MW;
  masterCanvas.height = MH;

  // Background
  masterCtx.fillStyle = '#05070D';
  masterCtx.fillRect(0, 0, MW, MH);

  // Subtle Cyan Grid Background
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.04)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < MW; x += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, MH); masterCtx.stroke();
  }
  for (let y = 0; y < MH; y += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(MW, y); masterCtx.stroke();
  }

  // Top Header Banner
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 36px "Segoe UI", Arial, sans-serif';
  masterCtx.fillText('AETHELGARD METROPOLIS // ASSET AUDIT 04', 48, 54);

  masterCtx.font = 'bold 17px monospace';
  masterCtx.fillStyle = '#F59E0B';
  masterCtx.fillText('CLASS 3: HEAVY SKY-BARGE (TITAN-88 INDUSTRIAL HAULER // VTOL FREIGHTER)', 48, 84);

  masterCtx.fillStyle = '#38BDF8';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('5-ANGLE ROBLOX 3D UGC MASTER SHEET • 100% IN-ENGINE THREE.JS', MW - 48, 48);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.fillText('RENDER: 2400x1350 • CORRUGATED CONTAINERS • 4x ROTATING VTOL PODS • HAZARD CHEVRONS', MW - 48, 76);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#F59E0B';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath();
  masterCtx.moveTo(48, 102);
  masterCtx.lineTo(MW - 48, 102);
  masterCtx.stroke();

  // Layout: 2 large panels on top (Views 1 & 2), 3 smaller panels on bottom (Views 3, 4, 5)
  const pad = 24;
  const topY = 126;
  const topH = 550;
  const topW = (MW - 48 * 2 - pad) / 2; // ~1136px each

  const botY = 700;
  const botH = 480;
  const botW = (MW - 48 * 2 - pad * 2) / 3; // ~749px each

  const panels = [
    { bmp: renderedBitmaps[0].bmp, angle: renderedBitmaps[0].angle, x: 48, y: topY, w: topW, h: topH },
    { bmp: renderedBitmaps[1].bmp, angle: renderedBitmaps[1].angle, x: 48 + topW + pad, y: topY, w: topW, h: topH },
    { bmp: renderedBitmaps[2].bmp, angle: renderedBitmaps[2].angle, x: 48, y: botY, w: botW, h: botH },
    { bmp: renderedBitmaps[3].bmp, angle: renderedBitmaps[3].angle, x: 48 + botW + pad, y: botY, w: botW, h: botH },
    { bmp: renderedBitmaps[4].bmp, angle: renderedBitmaps[4].angle, x: 48 + (botW + pad) * 2, y: botY, w: botW, h: botH },
  ];

  panels.forEach(({ bmp, angle, x, y, w, h }) => {
    // Panel Frame
    masterCtx.fillStyle = '#080C14';
    masterCtx.fillRect(x, y, w, h);

    // Border
    masterCtx.strokeStyle = 'rgba(245, 158, 11, 0.4)';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(x, y, w, h);

    // Render image (contained & centered with 8px margin inside)
    const imgMargin = 8;
    const destW = w - imgMargin * 2;
    const destH = h - 60; // leave bottom for label banner
    masterCtx.drawImage(bmp, 0, 0, bmp.width, bmp.height, x + imgMargin, y + imgMargin, destW, destH);

    // Tech Corner Accents
    const clen = 16;
    masterCtx.strokeStyle = '#F59E0B';
    masterCtx.lineWidth = 3;
    // Top-left
    masterCtx.beginPath(); masterCtx.moveTo(x, y + clen); masterCtx.lineTo(x, y); masterCtx.lineTo(x + clen, y); masterCtx.stroke();
    // Top-right
    masterCtx.beginPath(); masterCtx.moveTo(x + w - clen, y); masterCtx.lineTo(x + w, y); masterCtx.lineTo(x + w, y + clen); masterCtx.stroke();

    // Bottom Info Strip
    masterCtx.fillStyle = 'rgba(8, 12, 20, 0.95)';
    masterCtx.fillRect(x, y + h - 50, w, 50);

    masterCtx.strokeStyle = 'rgba(245, 158, 11, 0.3)';
    masterCtx.lineWidth = 1;
    masterCtx.beginPath();
    masterCtx.moveTo(x, y + h - 50);
    masterCtx.lineTo(x + w, y + h - 50);
    masterCtx.stroke();

    masterCtx.fillStyle = '#F59E0B';
    masterCtx.font = 'bold 15px monospace';
    masterCtx.fillText(angle.title, x + 16, y + h - 26);

    masterCtx.fillStyle = '#CBD5E1';
    masterCtx.font = '12px "Segoe UI", sans-serif';
    masterCtx.textAlign = 'right';
    masterCtx.fillText(angle.desc, x + w - 16, y + h - 26);
    masterCtx.textAlign = 'left';
  });

  // Footer status bar
  masterCtx.fillStyle = '#475569';
  masterCtx.font = '12px monospace';
  masterCtx.fillText('STATUS: ASSET APPROVED FOR METROPOLIS SHOT 1 HEAVY FREIGHT LANES • PROCEDURAL GLB READY', 48, MH - 28);

  // Save master sheet to disk
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('barge_master_sheet.png', masterBlob);
  console.log('SAVED: barge_master_sheet.png');

  console.log('BARGE_TURNAROUND_COMPLETE');
}

window.addEventListener('load', init);

