args.Content:
// ============================================================================
// THE GLITCH MARKET — 3D ASSET: THE HIGH-SPEED MAGLEV SKY-TRAIN (APEX EXPRESS)
// Authentic Roblox UGC Aesthetic: Aerodynamic chamfered wedges, studs,
// illuminated passenger window strips, articulated accordion gangways,
// magnetic levitation guide bogies, elevated concrete monorail beam.
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createBeveledBox, chamferBox, Textures } from './core/geo.js';

export function buildSkyTrain(options = {}) {
  const root = new THREE.Group();
  root.name = 'SkyTrain_ApexExpress';

  // --- Materials ---
  const matBodyWhite = new THREE.MeshStandardMaterial({
    color: 0xF1F5F9,
    roughness: 0.25,
    metalness: 0.4
  });

  const matBodyNavy = new THREE.MeshStandardMaterial({
    color: 0x0F172A,
    roughness: 0.35,
    metalness: 0.5
  });

  const matBellows = new THREE.MeshStandardMaterial({
    color: 0x181D26,
    roughness: 0.85,
    metalness: 0.1
  });

  const matTrackConcrete = new THREE.MeshStandardMaterial({
    map: Textures.trainTrackGrid(),
    roughness: 0.7,
    metalness: 0.3
  });

  const matGlass = new THREE.MeshStandardMaterial({
    color: 0x0284C7,
    roughness: 0.1,
    metalness: 0.2,
    transparent: true,
    opacity: 0.65
  });

  const matWindowStrip = new THREE.MeshStandardMaterial({
    map: Textures.trainWindows(),
    roughness: 0.2,
    metalness: 0.1
  });

  const matRouteSign = new THREE.MeshStandardMaterial({
    map: Textures.trainRouteSign('APEX EXPRESS // L1'),
    roughness: 0.3
  });

  const matGlowCyan = new THREE.MeshBasicMaterial({ color: 0x00F0FF });
  const matGlowRed = new THREE.MeshBasicMaterial({ color: 0xFF1744 });
  const matGlowAmber = new THREE.MeshBasicMaterial({ color: 0xF59E0B });
  const matGlowWhite = new THREE.MeshBasicMaterial({ color: 0xF8FAFC });

  // --------------------------------------------------------------------------
  // 1. ELEVATED MONORAIL GUIDEWAY & SUPPORT PYLON
  // --------------------------------------------------------------------------
  const trackGroup = new THREE.Group();
  trackGroup.name = 'MonorailGuideway';

  // Main Concrete Guideway Beam (32m long x 2.2m wide x 1.4m high)
  const trackBeam = createBeveledBox(32.0, 1.4, 2.2, 0.08, 2, matTrackConcrete);
  trackBeam.position.set(0, 0.7, 0);
  trackGroup.add(trackBeam);

  // Center High-Flux Magnetic Induction Rail
  const indRail = new THREE.Mesh(new THREE.BoxGeometry(32.0, 0.08, 0.4), matGlowCyan);
  indRail.position.set(0, 1.44, 0);
  trackGroup.add(indRail);

  // Guideway Side Energy Runners
  [-1.12, 1.12].forEach(z => {
    const sideRail = new THREE.Mesh(new THREE.BoxGeometry(32.0, 0.06, 0.04), matGlowCyan);
    sideRail.position.set(0, 0.9, z);
    trackGroup.add(sideRail);
  });

  // Elevated Cantilever Support Pylon (Center Column)
  const pylonBase = createBeveledBox(2.8, 1.2, 3.6, 0.1, 2, matBodyNavy);
  pylonBase.position.set(0, -0.6, 0);
  trackGroup.add(pylonBase);

  // Flared Pylon Braces
  [-1.4, 1.4].forEach(z => {
    const brace = createBeveledBox(1.8, 0.8, 0.5, 0.05, 1, matBodyNavy);
    brace.position.set(0, 0.1, z);
    brace.rotation.x = (z > 0 ? -1 : 1) * 0.35;
    trackGroup.add(brace);
  });

  root.add(trackGroup);

  // --------------------------------------------------------------------------
  // HELPER: BUILD MAGLEV BOGIE (MAGNETIC LEVITATION SKATE)
  // --------------------------------------------------------------------------
  function buildMaglevBogie(xPos) {
    const bogie = new THREE.Group();
    bogie.position.set(xPos, 1.48, 0);

    // Bogie central saddle
    const saddle = createBeveledBox(2.2, 0.35, 2.6, 0.04, 1, matBodyNavy);
    bogie.add(saddle);

    // Wrap-around magnetic guide shoes (clamping the monorail beam sides)
    [-1.25, 1.25].forEach(z => {
      const shoe = createBeveledBox(2.0, 0.6, 0.25, 0.03, 1, matBodyNavy);
      shoe.position.set(0, -0.2, z);
      bogie.add(shoe);

      // Glowing flux emitter strip on each shoe
      const flux = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.08, 0.04), matGlowCyan);
      flux.position.set(0, -0.2, z + (z > 0 ? -0.13 : 0.13));
      bogie.add(flux);
    });

    return bogie;
  }

  // --------------------------------------------------------------------------
  // 2. LEAD CAR: AERODYNAMIC BULLET LOCOMOTIVE
  // --------------------------------------------------------------------------
  const leadCar = new THREE.Group();
  leadCar.position.set(7.6, 1.85, 0);

  // Main Carriage Lower Hull (Navy Base)
  const leadBase = createBeveledBox(7.2, 0.6, 2.7, 0.06, 2, matBodyNavy);
  leadBase.position.set(0, 0.3, 0);
  leadCar.add(leadBase);

  // Main Passenger Cabin Body (Crisp White Shell)
  const leadCabin = createBeveledBox(5.6, 1.6, 2.6, 0.08, 2, matBodyWhite);
  leadCabin.position.set(-0.8, 1.35, 0);
  leadCar.add(leadCabin);

  // Aerodynamic Sloped Wedge Nose
  const noseShape = new THREE.Shape();
  noseShape.moveTo(0, 0);
  noseShape.lineTo(2.4, 0);
  noseShape.lineTo(1.8, 0.7);
  noseShape.lineTo(0.3, 1.6);
  noseShape.lineTo(0, 1.6);
  noseShape.closePath();

  const noseExtrude = new THREE.ExtrudeGeometry(noseShape, {
    depth: 2.5,
    bevelEnabled: true,
    bevelThickness: 0.05,
    bevelSize: 0.05,
    bevelSegments: 2
  });
  noseExtrude.center();
  noseExtrude.rotateY(Math.PI / 2);

  const noseMesh = new THREE.Mesh(noseExtrude, matBodyWhite);
  noseMesh.position.set(2.8, 1.35, 0);
  leadCar.add(noseMesh);

  // Pilot Cockpit Angled Windshield
  const leadWindshield = createBeveledBox(1.2, 0.65, 2.3, 0.04, 2, matGlass);
  leadWindshield.position.set(2.85, 1.65, 0);
  leadWindshield.rotation.z = -0.42;
  leadCar.add(leadWindshield);

  // Front Cyclops Headlight Cluster
  const headlightBar = createBeveledBox(0.2, 0.25, 2.1, 0.03, 1, matGlowCyan);
  headlightBar.position.set(3.9, 0.85, 0);
  leadCar.add(headlightBar);

  // Lower Auxiliary High-Beam Spots
  [-0.7, 0.7].forEach(z => {
    const spot = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 0.1, 12), matGlowWhite);
    spot.rotation.z = Math.PI / 2;
    spot.position.set(3.88, 0.5, z);
    leadCar.add(spot);
  });

  // Digital Route Sign above Windshield
  const routeSign = createBeveledBox(0.1, 0.32, 1.8, 0.02, 1, matRouteSign);
