const tailLightBar = createBeveledBox(0.2, 0.25, 2.1, 0.03, 1, matGlowRed);
tailLightBar.position.set(-3.9, 0.85, 0);
rearCar.add(tailLightBar);

// Twin Rear Jet Assist Nozzles
[-0.65, 0.65].forEach(z => {
  const nozzle = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.25, 0.5, 12, 1, true), matBodyNavy);
  nozzle.rotation.z = -Math.PI / 2;
  nozzle.position.set(-3.85, 0.45, z);
  rearCar.add(nozzle);

  const nozzleGlow = new THREE.Mesh(new THREE.CircleGeometry(0.16, 12), matGlowCyan);
  nozzleGlow.rotation.y = -Math.PI / 2;
  nozzleGlow.position.set(-4.11, 0.45, z);
  rearCar.add(nozzleGlow);
});

