  commercialFacade: () => canvasTex('comm_facade', 256, 512, (g, w, h) => {
    g.fillStyle = '#0A0E17'; g.fillRect(0, 0, w, h);
    const rows = 16;
    const cols = 8;
    const cw = w / cols;
    const rh = h / rows;
    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const lit = ((r * 7 + c * 13) % 5) !== 0;
        if (lit) {
          const colPick = (r + c) % 3;
          g.fillStyle = colPick === 0 ? '#38BDF8' : colPick === 1 ? '#00F0FF' : '#FBBF24';
          g.fillRect(c * cw + 6, r * rh + 6, cw - 12, rh - 12);
        } else {
          g.fillStyle = '#131924';
          g.fillRect(c * cw + 6, r * rh + 6, cw - 12, rh - 12);
        }
      }
      // Floor divider neon line every 4 floors
