// ============================================================================
// THE GLITCH MARKET — 3D ASSET: THE STEPPED COMMERCIAL CYBER-TOWER
// Authentic Roblox UGC Aesthetic: Setback terraces, chamfered blocks, studs,
// cantilevered sky-taxi landing pads, vertical holographic billboards, comms spire.
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createBeveledBox, chamferBox, Textures } from './core/geo.js';

export function buildSteppedTower(options = {}) {
  const root = new THREE.Group();
  root.name = 'SteppedCyberTower';

  // --- Materials ---
  const matStructureDark = new THREE.MeshStandardMaterial({
    color: 0x111622,
    roughness: 0.65,
    metalness: 0.4
  });

  const matStructureSteel = new THREE.MeshStandardMaterial({
    color: 0x1E2738,
    roughness: 0.5,
    metalness: 0.6
  });

  const matAccentCyan = new THREE.MeshStandardMaterial({
    color: 0x00F0FF,
    emissive: 0x00F0FF,
    emissiveIntensity: 1.5,
    roughness: 0.2
  });

  const matAccentAmber = new THREE.MeshStandardMaterial({
    color: 0xF59E0B,
    emissive: 0xF59E0B,
    emissiveIntensity: 1.8,
    roughness: 0.2
  });

  const matFacade = new THREE.MeshStandardMaterial({
    map: Textures.commercialFacade(),
    roughness: 0.25,
    metalness: 0.35
  });

  const matHoloAd = new THREE.MeshBasicMaterial({
    map: Textures.holoAdVertical(),
    transparent: true,
    opacity: 0.95
  });

  const matHelipad = new THREE.MeshStandardMaterial({
    map: Textures.helipadMarking(),
    roughness: 0.4,
    metalness: 0.2
  });

  const matGlassObservation = new THREE.MeshStandardMaterial({
    color: 0x0284C7,
    roughness: 0.1,
    metalness: 0.2,
    transparent: true,
    opacity: 0.6
  });

  const matWarningRed = new THREE.MeshBasicMaterial({ color: 0xFF1744 });
  const matGlowWhite = new THREE.MeshBasicMaterial({ color: 0xF8FAFC });

  // --------------------------------------------------------------------------
  // TIER 1: BASE PODIUM & STREET TRANSIT TERMINAL (Y: 0 to 10m)
  // --------------------------------------------------------------------------
  const tier1Group = new THREE.Group();

  // Foundation Plinth
  const plinth = createBeveledBox(15.0, 1.2, 15.0, 0.1, 2, matStructureDark);
  plinth.position.set(0, 0.6, 0);
  tier1Group.add(plinth);

  // Main Podium Block
  const t1Body = createBeveledBox(13.6, 8.8, 13.6, 0.12, 2, matFacade);
  t1Body.position.set(0, 5.6, 0);
  tier1Group.add(t1Body);

  // Heavy Corner Structural Columns (4 corners)
  [
    [-6.8, -6.8], [6.8, -6.8], [-6.8, 6.8], [6.8, 6.8]
  ].forEach(([cx, cz]) => {
    const col = createBeveledBox(1.6, 10.0, 1.6, 0.08, 2, matStructureSteel);
    col.position.set(cx, 5.0, cz);
    tier1Group.add(col);

    // Vertical cyan neon groove along each column
    const groove = new THREE.Mesh(new THREE.BoxGeometry(0.1, 9.6, 0.1), matAccentCyan);
    groove.position.set(cx + (cx > 0 ? -0.76 : 0.76), 5.0, cz + (cz > 0 ? -0.76 : 0.76));
    tier1Group.add(groove);
  });

  // Street Entrances (North & South)
  [-6.85, 6.85].forEach(z => {
    const portal = createBeveledBox(5.0, 3.6, 0.4, 0.06, 1, matStructureSteel);
    portal.position.set(0, 2.0, z);
    tier1Group.add(portal);

    const portalGlow = new THREE.Mesh(new THREE.BoxGeometry(4.2, 0.15, 0.1), matAccentCyan);
    portalGlow.position.set(0, 3.8, z + (z > 0 ? 0.22 : -0.22));
    tier1Group.add(portalGlow);
  });

  // Tier 1 Roof Coping / Balustrade
  const t1RoofCoping = createBeveledBox(14.0, 0.4, 14.0, 0.05, 1, matStructureSteel);
  t1RoofCoping.position.set(0, 10.2, 0);
  tier1Group.add(t1RoofCoping);

  root.add(tier1Group);

  // --------------------------------------------------------------------------
  // TIER 2: MID CORPORATE FLOORS & SKY-LANDING TERRACE (Y: 10m to 22m)
  // --------------------------------------------------------------------------
  const tier2Group = new THREE.Group();

  // Tier 2 Core Body (10.6m x 10.6m)
  const t2Body = createBeveledBox(10.6, 11.6, 10.6, 0.1, 2, matFacade);
  t2Body.position.set(0, 16.2, 0);
  tier2Group.add(t2Body);

  // Corner Reinforced Pylons
  [
    [-5.3, -5.3], [5.3, -5.3], [-5.3, 5.3], [5.3, 5.3]
  ].forEach(([cx, cz]) => {
    const col = createBeveledBox(1.2, 11.8, 1.2, 0.06, 1, matStructureDark);
    col.position.set(cx, 16.2, cz);
    tier2Group.add(col);
  });

  // Lower Sky-Terrace Landing Pad (East Cantilever: X = +7.8m)
  const padCantilever = createBeveledBox(4.8, 0.6, 5.6, 0.08, 2, matStructureSteel);
  padCantilever.position.set(7.4, 10.5, 0);
  tier2Group.add(padCantilever);

  // Diagonal support trusses beneath pad
  const trussMat = matStructureDark;
  [-1.8, 1.8].forEach(tz => {
    const truss = new THREE.Mesh(new THREE.CylinderGeometry(0.15, 0.15, 3.4, 8), trussMat);
    truss.rotation.z = -0.55;
    truss.position.set(6.2, 8.8, tz);
    tier2Group.add(truss);
  });

  // Landing Helipad Surface Decal
  const pad1Surface = new THREE.Mesh(new THREE.PlaneGeometry(4.4, 4.4), matHelipad);
  pad1Surface.rotation.x = -Math.PI / 2;
  pad1Surface.position.set(7.4, 10.82, 0);
  tier2Group.add(pad1Surface);

  // Landing Pad Perimeter Runway Lights (Green & Cyan)
  const matPadGreen = new THREE.MeshBasicMaterial({ color: 0x00FF88 });
  [-1.9, 1.9].forEach(px => {
    [-2.2, 2.2].forEach(pz => {
      const pLight = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 8), matPadGreen);
      pLight.position.set(7.4 + px, 10.9, pz);
      tier2Group.add(pLight);
    });
  });

  // Cantilevered Sky-Bridge Docking Port (West Side: X = -5.8m)
  const bridgePort = createBeveledBox(2.2, 3.2, 3.2, 0.06, 1, matStructureSteel);
  bridgePort.position.set(-5.9, 17.0, 0);
  tier2Group.add(bridgePort);

  const bridgeRing = new THREE.Mesh(new THREE.RingGeometry(1.0, 1.3, 16), matAccentCyan);
  bridgeRing.rotation.y = Math.PI / 2;
  bridgeRing.position.set(-7.02, 17.0, 0);
  tier2Group.add(bridgeRing);

  // Tier 2 Roof Coping
  const t2RoofCoping = createBeveledBox(11.0, 0.4, 11.0, 0.05, 1, matStructureSteel);
  t2RoofCoping.position.set(0, 22.2, 0);
  tier2Group.add(t2RoofCoping);

  root.add(tier2Group);

  // --------------------------------------------------------------------------
  // TIER 3: UPPER EXECUTIVE FLOORS & VERTICAL HOLO-AD (Y: 22m to 33m)
  // --------------------------------------------------------------------------
  const tier3Group = new THREE.Group();

  // Tier 3 Core Body (7.6m x 7.6m)
  const t3Body = createBeveledBox(7.6, 10.6, 7.6, 0.08, 2, matFacade);
  t3Body.position.set(0, 27.6, 0);
  tier3Group.add(t3Body);

  // Massive Vertical Holographic Corporate Billboard (Facing South: Z = +4.1m)
  const holoFrame = createBeveledBox(4.4, 8.8, 0.3, 0.05, 1, matStructureSteel);
  holoFrame.position.set(0, 27.6, 4.05);
  tier3Group.add(holoFrame);

  const holoScreen = new THREE.Mesh(new THREE.PlaneGeometry(3.8, 8.0), matHoloAd);
  holoScreen.position.set(0, 27.6, 4.22);
  tier3Group.add(holoScreen);

  // Outrigger Gantry Arms holding Holo Billboard
  [-1.8, 1.8].forEach(hx => {
    [24.0, 31.0].forEach(hy => {
      const gantryArm = createBeveledBox(0.2, 0.2, 0.8, 0.02, 1, matStructureDark);
      gantryArm.position.set(hx, hy, 4.2);
      tier3Group.add(gantryArm);
    });
  });

  // Upper Executive Helipad on North Terrace Setback (Z = -2.6m, Y = 22.4m)
  const pad2Surface = new THREE.Mesh(new THREE.PlaneGeometry(3.6, 3.6), matHelipad);
  pad2Surface.rotation.x = -Math.PI / 2;
  pad2Surface.position.set(0, 22.42, -4.2);
  tier3Group.add(pad2Surface);

  // Tier 3 Roof Coping
  const t3RoofCoping = createBeveledBox(8.0, 0.4, 8.0, 0.05, 1, matStructureSteel);
  t3RoofCoping.position.set(0, 33.1, 0);
  tier3Group.add(t3RoofCoping);

  root.add(tier3Group);

  // --------------------------------------------------------------------------
  // TIER 4: CROWN OBSERVATORY & PENTHOUSE SUITE (Y: 33m to 39m)
  // --------------------------------------------------------------------------
  const tier4Group = new THREE.Group();

  // Glass Panorama Observatory
  const obsGlass = createBeveledBox(5.6, 4.8, 5.6, 0.06, 2, matGlassObservation);
  obsGlass.position.set(0, 35.6, 0);
  tier4Group.add(obsGlass);

  // Interior Illuminated Core
  const obsCore = createBeveledBox(3.0, 4.6, 3.0, 0.04, 1, matAccentAmber);
  obsCore.position.set(0, 35.6, 0);
  tier4Group.add(obsCore);

  // Observatory Mullion Columns (4 corners)
  [
    [-2.8, -2.8], [2.8, -2.8], [-2.8, 2.8], [2.8, 2.8]
  ].forEach(([cx, cz]) => {
    const col = createBeveledBox(0.5, 5.0, 0.5, 0.03, 1, matStructureSteel);
    col.position.set(cx, 35.6, cz);
    tier4Group.add(col);
  });

  // Flared Stepped Crown Roof
  const crownRoof1 = createBeveledBox(6.4, 0.5, 6.4, 0.05, 1, matStructureSteel);
  crownRoof1.position.set(0, 38.25, 0);
  tier4Group.add(crownRoof1);

  const crownRoof2 = createBeveledBox(5.0, 0.5, 5.0, 0.04, 1, matStructureSteel);
  crownRoof2.position.set(0, 38.75, 0);
  tier4Group.add(crownRoof2);

  // Signature Roblox Studs on Crown Roof Parapet
  for (let sx = -2.0; sx <= 2.0; sx += 0.8) {
    for (let sz = -2.0; sz <= 2.0; sz += 0.8) {
      if (Math.abs(sx) > 1.4 || Math.abs(sz) > 1.4) {
        const stud = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 0.1, 8), matStructureSteel);
        stud.position.set(sx, 39.05, sz);
        tier4Group.add(stud);
      }
    }
  }

  root.add(tier4Group);

  // --------------------------------------------------------------------------
  // 5. CROWN SPIRE & COMMUNICATIONS ARRAY (Y: 39m to 48m)
  // --------------------------------------------------------------------------
  const spireGroup = new THREE.Group();

  // Spire Hexagonal Base Collar
  const spireBase = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 1.4, 1.6, 6), matStructureDark);
  spireBase.position.set(0, 39.8, 0);
  spireGroup.add(spireBase);

  // Slender Needle Antenna Mast
  const antennaMast = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.45, 8.0, 8), matStructureSteel);
  antennaMast.position.set(0, 44.2, 0);
  spireGroup.add(antennaMast);

  // Spire Tip Beacon (Blinking Aviation Red)
  const tipBeacon = new THREE.Mesh(new THREE.SphereGeometry(0.25, 12, 12), matWarningRed);
  tipBeacon.position.set(0, 48.3, 0);
  spireGroup.add(tipBeacon);

  // Directional Microwave Dishes (x2)
  [-0.65, 0.65].forEach(dy => {
    const dish = new THREE.Mesh(new THREE.ConeGeometry(0.65, 0.35, 12, 1, true), matStructureSteel);
    dish.rotation.z = Math.PI / 2;
    dish.position.set(0.65, 42.5 + dy * 2.0, 0);
    spireGroup.add(dish);
  });

  // Cross-Arm Sensor Gantry
  const crossArm = createBeveledBox(2.8, 0.12, 0.12, 0.02, 1, matStructureSteel);
  crossArm.position.set(0, 43.5, 0);
  spireGroup.add(crossArm);

  [-1.3, 1.3].forEach(cx => {
    const armLight = new THREE.Mesh(new THREE.SphereGeometry(0.1, 8, 8), matGlowWhite);
    armLight.position.set(cx, 43.6, 0);
    spireGroup.add(armLight);
  });

  root.add(spireGroup);

  return root;
}

// 5-Angle Studio Turnaround Renderer for The Stepped Commercial Cyber-Tower
import * as THREE from 'three';
import { makeEngine, lightRig } from './core/engine.js';
import { buildSteppedTower } from './stepped_tower.js';
import { canvasTex } from './core/geo.js';

const ANGLES = [
  { id: 'stower_angle_1_hero', title: 'VIEW 01: FRONT 3/4 HERO FULL TOWER', desc: '4-tier stepped setbacks, cantilever landing pad, vertical holo-ad, crown spire', pos: [34.0, 25.0, 34.0], target: [0, 22.0, 0], fov: 46 },
  { id: 'stower_angle_2_side', title: 'VIEW 02: PURE SIDE PROFILE', desc: 'Setback terraces, cantilevered vehicle dock, sky-bridge port, corner columns', pos: [45.0, 22.0, 0.0], target: [0, 22.0, 0], fov: 42 },
  { id: 'stower_angle_3_helipad', title: 'VIEW 03: SKY-TAXI LANDING PAD CLOSEUP', desc: 'Cantilevered landing pad, runway perimeter lights, structural under-trusses', pos: [18.0, 16.0, 10.0], target: [7.4, 11.0, 0], fov: 35 },
  { id: 'stower_angle_4_hoload', title: 'VIEW 04: VERTICAL HOLO-AD & MID TIER', desc: 'CYBER-CORP holographic billboard, gantry arms, dense office window grid', pos: [0.0, 30.0, 16.0], target: [0, 27.6, 4.0], fov: 38 },
  { id: 'stower_angle_5_crown', title: 'VIEW 05: CROWN OBSERVATORY & SPIRE', desc: 'Glass observation deck, roof studs, needle comms mast & microwave dishes', pos: [14.0, 45.0, 14.0], target: [0, 40.0, 0], fov: 36 },
];

function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Showroom Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#05070D');

  // High-End Architectural Studio Lighting
  const lights = lightRig(scene, {
    key: '#FFFBE8', keyI: 3.4, keyPos: [25, 45, 30],
    rimCol: '#00F0FF', rimI: 2.2,
    sky: '#38BDF8', ground: '#0F172A', hemiI: 0.75,
    shadowBox: 48, target: [0, 22.0, 0]
  });

  // Secondary Warm Gold Rim
  const warmRim = new THREE.DirectionalLight('#F59E0B', 1.8);
  warmRim.position.set(-25, 25, -25);
  scene.add(warmRim);

  // Soft Front Fill Light
  const frontFill = new THREE.DirectionalLight('#93C5FD', 0.85);
  frontFill.position.set(10, 20, 35);
  scene.add(frontFill);

  // Showroom Floor: Cyber Grid Reflective Hexagon Platform
  const floorTex = canvasTex('stower_showroom_floor', 256, 256, (g, w, h) => {
    g.fillStyle = '#080C16'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#1E293B'; g.lineWidth = 2;
    g.strokeRect(0, 0, w, h);
    g.strokeStyle = 'rgba(0, 240, 255, 0.15)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(w / 2, 0); g.lineTo(w / 2, h); g.stroke();
    g.beginPath(); g.moveTo(0, h / 2); g.lineTo(w, h / 2); g.stroke();
  }, [32, 32]);

  const floorMat = new THREE.MeshStandardMaterial({
    map: floorTex, roughness: 0.30, metalness: 0.45
  });

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(80, 80), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  scene.add(floor);

  // Circular Neon Trim Ring on Floor
  const ringGeo = new THREE.RingGeometry(21.8, 22.0, 80);
  const ringMat = new THREE.MeshBasicMaterial({ color: '#00F0FF', side: THREE.DoubleSide });
  const floorRing = new THREE.Mesh(ringGeo, ringMat);
  floorRing.rotation.x = -Math.PI / 2;
  floorRing.position.y = 0.01;
  scene.add(floorRing);

  // Build the Stepped Cyber-Tower Asset
  const tower = buildSteppedTower();
  scene.add(tower);

  const cam = new THREE.PerspectiveCamera(45, 1280 / 760, 0.1, 200);

  // Render individual angles
  const renderedBitmaps = [];

  for (const angle of ANGLES) {
    cam.fov = angle.fov;
    cam.position.set(...angle.pos);
    cam.lookAt(new THREE.Vector3(...angle.target));
    cam.updateProjectionMatrix();

    E.render(scene, cam, {
      bloom: 0.28,
      bloomThreshold: 1.25,
      bloomRadius: 0.45,
      exposure: 1.05,
      sat: 1.22,
      vignette: 0.16,
      focus: cam.position.distanceTo(new THREE.Vector3(...angle.target)),
      aperture: 0.0001
    });

    // Save individual angle render
    const blob = await canvasToBlob(glCanvas);
    await uploadImage(`${angle.id}.png`, blob);
    console.log(`RENDERED & SAVED: ${angle.id}`);

    // Create ImageBitmap for compositing master sheet
    const bmp = await createImageBitmap(glCanvas);
    renderedBitmaps.push({ bmp, angle });
  }

  // --------------------------------------------------------------------------
  // COMPOSITE MASTER 5-ANGLE INSPECTION SHEET (2400 x 1350)
  // --------------------------------------------------------------------------
  const MW = 2400;
  const MH = 1350;
  masterCanvas.width = MW;
  masterCanvas.height = MH;

  // Background
  masterCtx.fillStyle = '#05070D';
  masterCtx.fillRect(0, 0, MW, MH);

  // Subtle Cyan Grid Background
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.04)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < MW; x += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, MH); masterCtx.stroke();
  }
  for (let y = 0; y < MH; y += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(MW, y); masterCtx.stroke();
  }

  // Top Header Banner
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 36px "Segoe UI", Arial, sans-serif';
  masterCtx.fillText('AETHELGARD METROPOLIS // ASSET AUDIT 06', 48, 54);

  masterCtx.font = 'bold 17px monospace';
  masterCtx.fillStyle = '#00F0FF';
  masterCtx.fillText('TYPE 2: STEPPED COMMERCIAL CYBER-TOWER (AETHELGARD COMMERCE SPIRE)', 48, 84);

  masterCtx.fillStyle = '#38BDF8';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('5-ANGLE ROBLOX 3D UGC MASTER SHEET • 100% IN-ENGINE THREE.JS', MW - 48, 48);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.fillText('RENDER: 2400x1350 • 4-TIER SETBACKS • VEHICLE HELIPADS • VERTICAL HOLO-ADS • CROWN SPIRE', MW - 48, 76);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath();
  masterCtx.moveTo(48, 102);
  masterCtx.lineTo(MW - 48, 102);
  masterCtx.stroke();

  // Layout: 2 large panels on top (Views 1 & 2), 3 smaller panels on bottom (Views 3, 4, 5)
  const pad = 24;
  const topY = 126;
  const topH = 550;
  const topW = (MW - 48 * 2 - pad) / 2;

  const botY = 700;
  const botH = 480;
  const botW = (MW - 48 * 2 - pad * 2) / 3;

  const panels = [
    { bmp: renderedBitmaps[0].bmp, angle: renderedBitmaps[0].angle, x: 48, y: topY, w: topW, h: topH },
    { bmp: renderedBitmaps[1].bmp, angle: renderedBitmaps[1].angle, x: 48 + topW + pad, y: topY, w: topW, h: topH },
    { bmp: renderedBitmaps[2].bmp, angle: renderedBitmaps[2].angle, x: 48, y: botY, w: botW, h: botH },
    { bmp: renderedBitmaps[3].bmp, angle: renderedBitmaps[3].angle, x: 48 + botW + pad, y: botY, w: botW, h: botH },
    { bmp: renderedBitmaps[4].bmp, angle: renderedBitmaps[4].angle, x: 48 + (botW + pad) * 2, y: botY, w: botW, h: botH },
  ];

  panels.forEach(({ bmp, angle, x, y, w, h }) => {
    // Panel Frame
    masterCtx.fillStyle = '#080C14';
    masterCtx.fillRect(x, y, w, h);

    // Border
    masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.4)';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(x, y, w, h);

    // Render image
    const imgMargin = 8;
    const destW = w - imgMargin * 2;
    const destH = h - 60;
    masterCtx.drawImage(bmp, 0, 0, bmp.width, bmp.height, x + imgMargin, y + imgMargin, destW, destH);

    // Tech Corner Accents
    const clen = 16;
    masterCtx.strokeStyle = '#00F0FF';
    masterCtx.lineWidth = 3;
    masterCtx.beginPath(); masterCtx.moveTo(x, y + clen); masterCtx.lineTo(x, y); masterCtx.lineTo(x + clen, y); masterCtx.stroke();
    masterCtx.beginPath(); masterCtx.moveTo(x + w - clen, y); masterCtx.lineTo(x + w, y); masterCtx.lineTo(x + w, y + clen); masterCtx.stroke();

    // Bottom Info Strip
    masterCtx.fillStyle = 'rgba(8, 12, 20, 0.95)';
    masterCtx.fillRect(x, y + h - 50, w, 50);

    masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.3)';
    masterCtx.lineWidth = 1;
    masterCtx.beginPath();
    masterCtx.moveTo(x, y + h - 50);
    masterCtx.lineTo(x + w, y + h - 50);
    masterCtx.stroke();

    masterCtx.fillStyle = '#00F0FF';
    masterCtx.font = 'bold 15px monospace';
    masterCtx.fillText(angle.title, x + 16, y + h - 26);

    masterCtx.fillStyle = '#CBD5E1';
    masterCtx.font = '12px "Segoe UI", sans-serif';
    masterCtx.textAlign = 'right';
    masterCtx.fillText(angle.desc, x + w - 16, y + h - 26);
    masterCtx.textAlign = 'left';
  });

  // Footer status bar
  masterCtx.fillStyle = '#475569';
  masterCtx.font = '12px monospace';
  masterCtx.fillText('STATUS: ASSET APPROVED FOR METROPOLIS SHOT 1 MID-GROUND COMMERCIAL DISTRICT • PROCEDURAL GLB READY', 48, MH - 28);

  // Save master sheet to disk
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('stower_master_sheet.png', masterBlob);
  console.log('SAVED: stower_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('STOWER_TURNAROUND_COMPLETE');
}

window.initTurnaround = init;
init();

