    // Louver slits
    for (let y = 28; y <= 100; y += 10) {
      g.fillStyle = '#1E293B';
      g.fillRect(24, y, 80, 4);
    }
  }, [1, 1]),

  // High-Tech Blue Solar Panel Array
  solarPanel: () => canvasTex('solar_panel', 256, 256, (g, w, h) => {
    g.fillStyle = '#0F172A'; g.fillRect(0, 0, w, h);
    const cells = 4;
    const cw = w / cells;
    const ch = h / cells;
    for (let r = 0; r < cells; r++) {
      for (let c = 0; c < cells; c++) {
        g.fillStyle = '#1D4ED8';
        g.fillRect(c * cw + 3, r * ch + 3, cw - 6, ch - 6);
        // Grid wires
        g.strokeStyle = 'rgba(255, 255, 255, 0.35)'; g.lineWidth = 1;
