// ============================================================================
// THE GLITCH MARKET — 3D ASSET: RESIDENTIAL POD HIGHRISE ("MINI HOUSES")
// Authentic Roblox UGC Aesthetic: Cantilevered modular micro-apartments,
// individual balconies, AC compressors, satellite dishes, rooftop solar arrays.
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createBeveledBox, chamferBox, Textures } from './core/geo.js';

export function buildPodHighrise(options = {}) {
  const root = new THREE.Group();
  root.name = 'ResidentialPodHighrise';

  // --- Materials ---
  const matCoreDark = new THREE.MeshStandardMaterial({
    color: 0x141822,
    roughness: 0.7,
    metalness: 0.3
  });

  const matElevatorGlass = new THREE.MeshStandardMaterial({
    color: 0x00F0FF,
    roughness: 0.1,
    metalness: 0.1,
    transparent: true,
    opacity: 0.45
  });

  const matSteelRail = new THREE.MeshStandardMaterial({
    color: 0xF59E0B,
    roughness: 0.4,
    metalness: 0.5
  });

  const matACVent = new THREE.MeshStandardMaterial({
    map: Textures.acLouvers(),
    roughness: 0.5,
    metalness: 0.3
  });

  const matSolar = new THREE.MeshStandardMaterial({
    map: Textures.solarPanel(),
    roughness: 0.2,
    metalness: 0.6
  });

  const matHazard = new THREE.MeshStandardMaterial({
    map: Textures.hazardStripe(),
    roughness: 0.5
  });

  const matGlowWarm = new THREE.MeshBasicMaterial({ color: 0xFBBF24 });
  const matGlowCyan = new THREE.MeshBasicMaterial({ color: 0x00F0FF });
  const matGlowRed = new THREE.MeshBasicMaterial({ color: 0xEF4444 });

  // --------------------------------------------------------------------------
  // 1. CENTRAL MEGASTRUCTURE CORE & ELEVATOR SHAFT (Y: 0 to 36m)
  // --------------------------------------------------------------------------
  const coreGroup = new THREE.Group();

  // Foundation Base
  const baseSlab = createBeveledBox(12.0, 1.2, 12.0, 0.1, 2, matCoreDark);
  baseSlab.position.set(0, 0.6, 0);
  coreGroup.add(baseSlab);

  // Central Vertical Spine (5.2m x 5.2m x 36m)
  const mainSpine = createBeveledBox(5.2, 35.0, 5.2, 0.1, 2, matCoreDark);
  mainSpine.position.set(0, 18.0, 0);
  coreGroup.add(mainSpine);

  // Glass Panorama Elevator Shaft running up Front Face (Z = 2.8m)
  const elevatorShaft = createBeveledBox(1.8, 34.0, 0.8, 0.05, 1, matElevatorGlass);
  elevatorShaft.position.set(0, 18.0, 2.8);
  coreGroup.add(elevatorShaft);

  // Glowing Elevator Car mid-shaft
  const elevatorCar = createBeveledBox(1.4, 2.2, 0.7, 0.04, 1, matGlowWarm);
  elevatorCar.position.set(0, 19.5, 2.8);
  coreGroup.add(elevatorCar);

  // Vertical Spine Neon Conduit Lines
  [-2.65, 2.65].forEach(x => {
    const conduit = new THREE.Mesh(new THREE.BoxGeometry(0.12, 35.0, 0.12), matGlowCyan);
    conduit.position.set(x, 18.0, -2.65);
    coreGroup.add(conduit);
  });

  root.add(coreGroup);

  // --------------------------------------------------------------------------
  // 2. MODULAR MICRO-HOUSE UNITS ("MINI HOUSES")
  // --------------------------------------------------------------------------
  const podsGroup = new THREE.Group();

  const POD_PALETTES = [
    { base: '#0D9488', trim: '#14B8A6', name: 'teal' },      // Cyber Teal
    { base: '#B91C1C', trim: '#EF4444', name: 'red' },       // Terracotta Red
    { base: '#1E293B', trim: '#38BDF8', name: 'navy' },      // Industrial Navy
    { base: '#D97706', trim: '#FBBF24', name: 'yellow' },    // Muted Gold
  ];

  function createMiniHouse(colorData, width = 3.6, height = 2.6, depth = 3.2) {
    const pod = new THREE.Group();

    const matPodBody = new THREE.MeshStandardMaterial({
      color: new THREE.Color(colorData.base),
      roughness: 0.45,
      metalness: 0.25
    });

    const matPodWin = new THREE.MeshStandardMaterial({
      map: Textures.podWindows(colorData.base),
      roughness: 0.3
    });

    // Main Box Living Volume
    const podBody = createBeveledBox(width, height, depth, 0.06, 2, matPodBody);
    pod.add(podBody);

    // Front Window Facade Plane
    const winFront = new THREE.Mesh(new THREE.PlaneGeometry(width - 0.4, height - 0.4), matPodWin);
    winFront.position.set(0, 0, depth / 2 + 0.02);
    pod.add(winFront);

    // Walk-out Balcony Cantilever
    const balcSlab = createBeveledBox(width, 0.18, 1.2, 0.03, 1, matCoreDark);
    balcSlab.position.set(0, -height / 2 + 0.09, depth / 2 + 0.6);
    pod.add(balcSlab);

    // Balcony Safety Railing (Yellow Steel)
    const railFront = createBeveledBox(width, 0.06, 0.06, 0.01, 1, matSteelRail);
    railFront.position.set(0, -height / 2 + 0.75, depth / 2 + 1.15);
    pod.add(railFront);

    [-width / 2 + 0.05, width / 2 - 0.05].forEach(rx => {
      const railSide = createBeveledBox(0.06, 0.06, 1.1, 0.01, 1, matSteelRail);
      railSide.position.set(rx, -height / 2 + 0.75, depth / 2 + 0.6);
      pod.add(railSide);
    });

    // Exterior AC Compressor Unit hanging on bracket
    const acUnit = createBeveledBox(0.8, 0.6, 0.4, 0.03, 1, matACVent);
    acUnit.position.set(width / 2 - 0.6, -height / 2 + 0.4, depth / 2 + 0.3);
    pod.add(acUnit);

    // Satellite Dish Bracket on Corner
    const dishArm = new THREE.Mesh(new THREE.CylinderGeometry(0.02, 0.02, 0.4, 6), matCoreDark);
    dishArm.position.set(-width / 2 + 0.3, height / 2 - 0.3, depth / 2 + 0.2);
    dishArm.rotation.z = -0.4;
    pod.add(dishArm);

    const dishCone = new THREE.Mesh(new THREE.ConeGeometry(0.28, 0.12, 10, 1, true), matSteelRail);
    dishCone.rotation.x = Math.PI / 4;
    dishCone.position.set(-width / 2 + 0.4, height / 2 - 0.1, depth / 2 + 0.35);
    pod.add(dishCone);

    // Signature Roblox Studs on Pod Roof
    [-0.8, 0.8].forEach(sx => {
      [-0.8, 0.8].forEach(sz => {
        const stud = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.06, 8), matPodBody);
        stud.position.set(sx, height / 2 + 0.03, sz);
        pod.add(stud);
      });
    });

    return pod;
  }

  // Generate Staggered Stack of Pods across 8 vertical levels
  const podLayouts = [
    // Level 1 (Y: 4m)
    { pos: [3.8, 4.0, 0.8], rotY: 0, pal: 0 },
    { pos: [-3.8, 4.0, -0.6], rotY: Math.PI, pal: 1 },
    // Level 2 (Y: 7.5m)
    { pos: [0.6, 7.5, 3.8], rotY: Math.PI / 2, pal: 2 },
    { pos: [-0.6, 7.5, -3.8], rotY: -Math.PI / 2, pal: 3 },
    // Level 3 (Y: 11.0m)
    { pos: [3.9, 11.0, -0.5], rotY: 0, pal: 1 },
    { pos: [-3.9, 11.0, 0.7], rotY: Math.PI, pal: 0 },
    // Level 4 (Y: 14.5m)
    { pos: [-0.5, 14.5, 3.9], rotY: Math.PI / 2, pal: 3 },
    { pos: [0.7, 14.5, -3.9], rotY: -Math.PI / 2, pal: 2 },
    // Level 5 (Y: 18.0m)
    { pos: [4.0, 18.0, 0.6], rotY: 0, pal: 0 },
    { pos: [-4.0, 18.0, -0.8], rotY: Math.PI, pal: 1 },
    // Level 6 (Y: 21.5m)
    { pos: [0.8, 21.5, 3.9], rotY: Math.PI / 2, pal: 2 },
    { pos: [-0.6, 21.5, -3.9], rotY: -Math.PI / 2, pal: 3 },
    // Level 7 (Y: 25.0m)
    { pos: [3.8, 25.0, -0.5], rotY: 0, pal: 1 },
    { pos: [-3.8, 25.0, 0.5], rotY: Math.PI, pal: 0 },
    // Level 8 (Y: 28.5m - Penthouse Duplex Pods)
    { pos: [0.0, 28.5, 3.8], rotY: Math.PI / 2, pal: 3 },
    { pos: [0.0, 28.5, -3.8], rotY: -Math.PI / 2, pal: 2 },
  ];

  podLayouts.forEach(layout => {
    const pal = POD_PALETTES[layout.pal];
    const miniHouse = createMiniHouse(pal);
    miniHouse.position.set(...layout.pos);
    miniHouse.rotation.y = layout.rotY;
    podsGroup.add(miniHouse);
  });

  root.add(podsGroup);

  // --------------------------------------------------------------------------
  // 3. ROOFTOP UTILITIES & SOLAR ARRAY (Y: 35m to 40m)
  // --------------------------------------------------------------------------
  const roofGroup = new THREE.Group();
  roofGroup.position.set(0, 35.5, 0);

  // Rooftop Machinery Deck
  const roofDeck = createBeveledBox(5.6, 0.4, 5.6, 0.05, 1, matCoreDark);
  roofGroup.add(roofDeck);

  // Twin Water Storage Cisterns with Hazard Stripe Bands
  [-1.5, 1.5].forEach(x => {
    const tank = new THREE.Mesh(new THREE.CylinderGeometry(0.9, 0.9, 2.2, 16), matCoreDark);
    tank.position.set(x, 1.2, -1.2);
    roofGroup.add(tank);

    const stripe = new THREE.Mesh(new THREE.CylinderGeometry(0.92, 0.92, 0.4, 16), matHazard);
    stripe.position.set(x, 1.2, -1.2);
    roofGroup.add(stripe);
  });

  // Tilted Photovoltaic Solar Arrays (Facing Sun)
  [-1.4, 1.4].forEach(x => {
    const panel = new THREE.Mesh(new THREE.PlaneGeometry(1.8, 1.8), matSolar);
    panel.rotation.x = -Math.PI / 4;
    panel.position.set(x, 1.4, 1.4);
    roofGroup.add(panel);

    // Solar mounting bracket
    const mount = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 1.2, 6), matSteelRail);
    mount.position.set(x, 0.7, 1.2);
    roofGroup.add(mount);
  });

  // Rooftop Aviation Warning Beacon
  const roofBeacon = new THREE.Mesh(new THREE.SphereGeometry(0.2, 8, 8), matGlowRed);
  roofBeacon.position.set(0, 3.2, 0);
  roofGroup.add(roofBeacon);

  root.add(roofGroup);

  return root;
}

// 5-Angle Studio Turnaround Renderer for The Residential Pod Highrise ("Mini Houses")
import * as THREE from 'three';
import { makeEngine, lightRig } from './core/engine.js';
import { buildPodHighrise } from './pod_highrise.js';
import { canvasTex } from './core/geo.js';

const ANGLES = [
  { id: 'pod_angle_1_hero', title: 'VIEW 01: FRONT 3/4 HERO FULL TOWER', desc: 'Cantilevered modular mini-houses, glass elevator spine, balconies & conduits', pos: [30.0, 22.0, 30.0], target: [0, 18.0, 0], fov: 45 },
  { id: 'pod_angle_2_side', title: 'VIEW 02: PURE SIDE PROFILE', desc: 'Staggered interlocking pod projections, vertical spine, roof utility deck', pos: [38.0, 18.0, 0.0], target: [0, 18.0, 0], fov: 42 },
  { id: 'pod_angle_3_podclose', title: 'VIEW 03: MINI-HOUSE POD CLOSEUP', desc: 'Cozy glowing window, safety balcony, AC compressor unit, satellite dish', pos: [11.0, 13.0, 7.5], target: [3.9, 11.0, -0.5], fov: 32 },
  { id: 'pod_angle_4_elevator', title: 'VIEW 04: GLASS ELEVATOR SHAFT', desc: 'Glowing observation elevator car, vertical cyan conduits, central spine', pos: [0.0, 20.0, 16.0], target: [0, 19.5, 2.8], fov: 36 },
  { id: 'pod_angle_5_rooftop', title: 'VIEW 05: ROOFTOP SOLAR & CISTERNS', desc: 'Photovoltaic solar panels, water tanks with hazard bands, warning beacon', pos: [9.0, 42.0, 9.0], target: [0, 36.0, 0], fov: 35 },
];

function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Showroom Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#05070D');

  // High-End Architectural Studio Lighting
  const lights = lightRig(scene, {
    key: '#FFFBE8', keyI: 3.4, keyPos: [22, 42, 28],
    rimCol: '#00F0FF', rimI: 2.2,
    sky: '#38BDF8', ground: '#0F172A', hemiI: 0.75,
    shadowBox: 44, target: [0, 18.0, 0]
  });

  // Secondary Warm Gold Rim
  const warmRim = new THREE.DirectionalLight('#F59E0B', 1.8);
  warmRim.position.set(-22, 22, -22);
  scene.add(warmRim);

  // Soft Front Fill Light
  const frontFill = new THREE.DirectionalLight('#93C5FD', 0.85);
  frontFill.position.set(10, 18, 30);
  scene.add(frontFill);

  // Showroom Floor: Cyber Grid Reflective Hexagon Platform
  const floorTex = canvasTex('pod_showroom_floor', 256, 256, (g, w, h) => {
    g.fillStyle = '#080C16'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#1E293B'; g.lineWidth = 2;
    g.strokeRect(0, 0, w, h);
    g.strokeStyle = 'rgba(0, 240, 255, 0.15)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(w / 2, 0); g.lineTo(w / 2, h); g.stroke();
    g.beginPath(); g.moveTo(0, h / 2); g.lineTo(w, h / 2); g.stroke();
  }, [30, 30]);

  const floorMat = new THREE.MeshStandardMaterial({
    map: floorTex, roughness: 0.30, metalness: 0.45
  });

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(75, 75), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.receiveShadow = true;
  scene.add(floor);

  // Circular Neon Trim Ring on Floor
  const ringGeo = new THREE.RingGeometry(18.8, 19.0, 80);
  const ringMat = new THREE.MeshBasicMaterial({ color: '#F59E0B', side: THREE.DoubleSide });
  const floorRing = new THREE.Mesh(ringGeo, ringMat);
  floorRing.rotation.x = -Math.PI / 2;
  floorRing.position.y = 0.01;
  scene.add(floorRing);

  // Build the Residential Pod Highrise Asset
  const building = buildPodHighrise();
  scene.add(building);

  const cam = new THREE.PerspectiveCamera(45, 1280 / 760, 0.1, 200);

  // Render individual angles
  const renderedBitmaps = [];

  for (const angle of ANGLES) {
    cam.fov = angle.fov;
    cam.position.set(...angle.pos);
    cam.lookAt(new THREE.Vector3(...angle.target));
    cam.updateProjectionMatrix();

    E.render(scene, cam, {
      bloom: 0.28,
      bloomThreshold: 1.25,
      bloomRadius: 0.45,
      exposure: 1.05,
      sat: 1.22,
      vignette: 0.16,
      focus: cam.position.distanceTo(new THREE.Vector3(...angle.target)),
      aperture: 0.0001
    });

    // Save individual angle render
    const blob = await canvasToBlob(glCanvas);
    await uploadImage(`${angle.id}.png`, blob);
    console.log(`RENDERED & SAVED: ${angle.id}`);

    // Create ImageBitmap for compositing master sheet
    const bmp = await createImageBitmap(glCanvas);
    renderedBitmaps.push({ bmp, angle });
  }

  // --------------------------------------------------------------------------
  // COMPOSITE MASTER 5-ANGLE INSPECTION SHEET (2400 x 1350)
  // --------------------------------------------------------------------------
  const MW = 2400;
  const MH = 1350;
  masterCanvas.width = MW;
  masterCanvas.height = MH;

  // Background
  masterCtx.fillStyle = '#05070D';
  masterCtx.fillRect(0, 0, MW, MH);

  // Subtle Cyan Grid Background
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.04)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < MW; x += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, MH); masterCtx.stroke();
  }
  for (let y = 0; y < MH; y += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(MW, y); masterCtx.stroke();
  }

  // Top Header Banner
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 36px "Segoe UI", Arial, sans-serif';
  masterCtx.fillText('AETHELGARD METROPOLIS // ASSET AUDIT 07', 48, 54);

  masterCtx.font = 'bold 17px monospace';
  masterCtx.fillStyle = '#F59E0B';
  masterCtx.fillText('TYPE 4: RESIDENTIAL POD HIGHRISE (MINI HOUSES // HABITATION STACKS)', 48, 84);

  masterCtx.fillStyle = '#38BDF8';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('5-ANGLE ROBLOX 3D UGC MASTER SHEET • 100% IN-ENGINE THREE.JS', MW - 48, 48);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.fillText('RENDER: 2400x1350 • CANTILEVERED MINI HOUSES • BALCONIES & AC • GLASS ELEVATOR • SOLAR ARRAY', MW - 48, 76);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#F59E0B';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath();
  masterCtx.moveTo(48, 102);
  masterCtx.lineTo(MW - 48, 102);
  masterCtx.stroke();

  // Layout: 2 large panels on top (Views 1 & 2), 3 smaller panels on bottom (Views 3, 4, 5)
  const pad = 24;
  const topY = 126;
  const topH = 550;
  const topW = (MW - 48 * 2 - pad) / 2;

  const botY = 700;
  const botH = 480;
  const botW = (MW - 48 * 2 - pad * 2) / 3;

  const panels = [
    { bmp: renderedBitmaps[0].bmp, angle: renderedBitmaps[0].angle, x: 48, y: topY, w: topW, h: topH },
    { bmp: renderedBitmaps[1].bmp, angle: renderedBitmaps[1].angle, x: 48 + topW + pad, y: topY, w: topW, h: topH },
    { bmp: renderedBitmaps[2].bmp, angle: renderedBitmaps[2].angle, x: 48, y: botY, w: botW, h: botH },
    { bmp: renderedBitmaps[3].bmp, angle: renderedBitmaps[3].angle, x: 48 + botW + pad, y: botY, w: botW, h: botH },
    { bmp: renderedBitmaps[4].bmp, angle: renderedBitmaps[4].angle, x: 48 + (botW + pad) * 2, y: botY, w: botW, h: botH },
  ];

  panels.forEach(({ bmp, angle, x, y, w, h }) => {
    // Panel Frame
    masterCtx.fillStyle = '#080C14';
    masterCtx.fillRect(x, y, w, h);

    // Border
    masterCtx.strokeStyle = 'rgba(245, 158, 11, 0.4)';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(x, y, w, h);

    // Render image
    const imgMargin = 8;
    const destW = w - imgMargin * 2;
    const destH = h - 60;
    masterCtx.drawImage(bmp, 0, 0, bmp.width, bmp.height, x + imgMargin, y + imgMargin, destW, destH);

    // Tech Corner Accents
    const clen = 16;
    masterCtx.strokeStyle = '#F59E0B';
    masterCtx.lineWidth = 3;
    masterCtx.beginPath(); masterCtx.moveTo(x, y + clen); masterCtx.lineTo(x, y); masterCtx.lineTo(x + clen, y); masterCtx.stroke();
    masterCtx.beginPath(); masterCtx.moveTo(x + w - clen, y); masterCtx.lineTo(x + w, y); masterCtx.lineTo(x + w, y + clen); masterCtx.stroke();

    // Bottom Info Strip
    masterCtx.fillStyle = 'rgba(8, 12, 20, 0.95)';
    masterCtx.fillRect(x, y + h - 50, w, 50);

    masterCtx.strokeStyle = 'rgba(245, 158, 11, 0.3)';
    masterCtx.lineWidth = 1;
    masterCtx.beginPath();
    masterCtx.moveTo(x, y + h - 50);
    masterCtx.lineTo(x + w, y + h - 50);
    masterCtx.stroke();

    masterCtx.fillStyle = '#F59E0B';
    masterCtx.font = 'bold 15px monospace';
    masterCtx.fillText(angle.title, x + 16, y + h - 26);

    masterCtx.fillStyle = '#CBD5E1';
    masterCtx.font = '12px "Segoe UI", sans-serif';
    masterCtx.textAlign = 'right';
    masterCtx.fillText(angle.desc, x + w - 16, y + h - 26);
    masterCtx.textAlign = 'left';
  });

  // Footer status bar
  masterCtx.fillStyle = '#475569';
  masterCtx.font = '12px monospace';
  masterCtx.fillText('STATUS: ASSET APPROVED FOR METROPOLIS SHOT 1 HIGH-DENSITY RESIDENTIAL SECTOR • PROCEDURAL GLB READY', 48, MH - 28);

  // Save master sheet to disk
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('pod_master_sheet.png', masterBlob);
  console.log('SAVED: pod_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('POD_TURNAROUND_COMPLETE');
}

window.initTurnaround = init;
init();

