// ============================================================================
// THE GLITCH MARKET — 3D ASSET: THE SKY-HIGHWAY & SUSPENDED GUIDEWAY SYSTEM
// Authentic Roblox UGC Aesthetic: Multi-lane suspended highway deck, crash barriers,
// studs, overhead digital sign gantry, inverted-Y support pylon, live traffic scale.
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createBeveledBox, chamferBox, Textures } from './core/geo.js';
import { buildSkyTaxi } from './taxi.js';
import { buildNeonSpeeder } from './speeder.js';

export function buildSkyHighway(options = {}) {
  const root = new THREE.Group();
  root.name = 'SkyHighwaySystem';

  // --- Materials ---
  const matDeckConcrete = new THREE.MeshStandardMaterial({
    color: 0x141822,
    roughness: 0.7,
    metalness: 0.2
  });

  const matRoadSurface = new THREE.MeshStandardMaterial({
    map: Textures.highwayRoadSurface(),
    roughness: 0.45,
    metalness: 0.25
  });

  const matBarrier = new THREE.MeshStandardMaterial({
    color: 0x222938,
    roughness: 0.55,
    metalness: 0.45
  });

  const matTrussSteel = new THREE.MeshStandardMaterial({
    color: 0x1E293B,
    roughness: 0.45,
    metalness: 0.6
  });

  const matGantrySign = new THREE.MeshStandardMaterial({
    map: Textures.highwayGantrySign(),
    roughness: 0.3
  });

  const matGlowCyan = new THREE.MeshBasicMaterial({ color: 0x00F0FF });
  const matGlowAmber = new THREE.MeshBasicMaterial({ color: 0xF59E0B });
  const matGlowGreen = new THREE.MeshBasicMaterial({ color: 0x00FF88 });
  const matGlowRed = new THREE.MeshBasicMaterial({ color: 0xFF1744 });

  // --------------------------------------------------------------------------
  // 1. HIGHWAY DECK & BARRIERS (Length: 36m, Width: 12m)
  // --------------------------------------------------------------------------
  const deckGroup = new THREE.Group();
  deckGroup.position.set(0, 10.0, 0);

  // Main Concrete Roadbed Slab
  const roadbed = createBeveledBox(36.0, 1.2, 12.0, 0.08, 2, matDeckConcrete);
  roadbed.position.set(0, 0, 0);
  deckGroup.add(roadbed);

  // 4-Lane Asphalt Road Surface
  const roadSurface = new THREE.Mesh(new THREE.PlaneGeometry(36.0, 10.8), matRoadSurface);
  roadSurface.rotation.x = -Math.PI / 2;
  roadSurface.position.set(0, 0.62, 0);
  deckGroup.add(roadSurface);

  // Side Crash Barriers (Left: Z = +5.7m, Right: Z = -5.7m)
  [-5.7, 5.7].forEach(z => {
    // Continuous barrier wall
    const barrier = createBeveledBox(36.0, 1.4, 0.7, 0.06, 2, matBarrier);
    barrier.position.set(0, 1.1, z);
    deckGroup.add(barrier);

    // Continuous glowing edge light along bottom of barrier
    const edgeGlow = new THREE.Mesh(new THREE.BoxGeometry(36.0, 0.06, 0.04), z > 0 ? matGlowAmber : matGlowCyan);
    edgeGlow.position.set(0, 0.65, z + (z > 0 ? -0.37 : 0.37));
    deckGroup.add(edgeGlow);

    // Signature Roblox Studs along barrier top parapet
    for (let x = -17.0; x <= 17.0; x += 1.2) {
      const stud = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.12, 0.08, 8), matBarrier);
      stud.position.set(x, 1.84, z);
      deckGroup.add(stud);
    }

    // Safety Hazard Stanchions with Blinking Yellow Reflectors
    for (let x = -16.0; x <= 16.0; x += 4.0) {
      const reflector = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.25, 0.12), matGlowAmber);
      reflector.position.set(x, 1.1, z + (z > 0 ? -0.38 : 0.38));
      deckGroup.add(reflector);
    }
  });

  root.add(deckGroup);

  // --------------------------------------------------------------------------
  // 2. OVERHEAD DIGITAL SIGN GANTRY (HIGHWAY PORTAL)
  // --------------------------------------------------------------------------
  const gantryGroup = new THREE.Group();
  gantryGroup.position.set(2.0, 10.0, 0);

  // Vertical Support Columns (Left and Right)
  [-6.2, 6.2].forEach(z => {
    const col = createBeveledBox(0.9, 5.4, 0.9, 0.06, 2, matTrussSteel);
    col.position.set(0, 3.2, z);
    gantryGroup.add(col);

    // Base mounting shoe
    const shoe = createBeveledBox(1.4, 0.4, 1.4, 0.04, 1, matDeckConcrete);
    shoe.position.set(0, 0.8, z);
    gantryGroup.add(shoe);
  });

  // Cross-Span Overhead Beam Box (Truss arch)
  const crossTruss = createBeveledBox(1.2, 1.2, 13.4, 0.06, 2, matTrussSteel);
  crossTruss.position.set(0, 5.6, 0);
  gantryGroup.add(crossTruss);

  // Massive Dual-Sided Digital Overhead Signboard
  const signBox = createBeveledBox(0.3, 2.0, 9.6, 0.04, 1, matGantrySign);
  signBox.position.set(0.65, 5.2, 0);
  gantryGroup.add(signBox);

  // Overhead Radar Speed Camera Sensor Pods
  [-3.4, 0.0, 3.4].forEach(z => {
    const sensor = createBeveledBox(0.5, 0.4, 0.5, 0.03, 1, matDeckConcrete);
    sensor.position.set(0.65, 3.9, z);
    gantryGroup.add(sensor);

    const sensorLens = new THREE.Mesh(new THREE.SphereGeometry(0.1, 8, 8), matGlowRed);
    sensorLens.position.set(0.92, 3.9, z);
    gantryGroup.add(sensorLens);
  });

  root.add(gantryGroup);

  // --------------------------------------------------------------------------
  // 3. SUSPENDED INVERTED-Y PYLON & CABLE-STAY SUPPORT (Below Deck)
  // --------------------------------------------------------------------------
  const pylonGroup = new THREE.Group();
  pylonGroup.position.set(0, 0, 0);

  // Heavy Central Foundation Pier at ground level
  const pierBase = createBeveledBox(5.0, 2.0, 8.0, 0.12, 2, matDeckConcrete);
  pierBase.position.set(0, 1.0, 0);
  pylonGroup.add(pierBase);

  // Main Pylon Column ascending to meet deck
  const pylonCol = createBeveledBox(3.4, 8.5, 4.4, 0.1, 2, matBarrier);
  pylonCol.position.set(0, 5.2, 0);
  pylonGroup.add(pylonCol);

  // Diagonal Deck Support Buttresses (Cantilever Outriggers)
  [-4.2, 4.2].forEach(z => {
    const buttress = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.35, 6.2, 8), matTrussSteel);
    buttress.rotation.x = (z > 0 ? -1 : 1) * 0.42;
    buttress.position.set(0, 6.8, z * 0.65);
    pylonGroup.add(buttress);
  });

  // Vertical Neon Power Conduit running down pylon
  const pylonConduit = new THREE.Mesh(new THREE.BoxGeometry(0.15, 9.0, 0.15), matGlowCyan);
  pylonConduit.position.set(1.75, 5.5, 0);
  pylonGroup.add(pylonConduit);

  root.add(pylonGroup);

  // --------------------------------------------------------------------------
  // 4. LIVE HIGHWAY TRAFFIC VEHICLES (SCALE & ACTION DEMO)
  // --------------------------------------------------------------------------
  const trafficGroup = new THREE.Group();

  // Mini Sky-Taxi cruising in lane 2
  const taxi = buildSkyTaxi();
  taxi.scale.set(0.65, 0.65, 0.65);
  taxi.position.set(-6.0, 10.9, -2.4);
  taxi.rotation.y = Math.PI; // heading down the road
  trafficGroup.add(taxi);

  // Mini Neon Speeder cruising in fast lane 1
  const speeder = buildNeonSpeeder();
  speeder.scale.set(0.65, 0.65, 0.65);
  speeder.position.set(10.0, 10.9, 2.4);
  trafficGroup.add(speeder);

  root.add(trafficGroup);

  return root;
}

// 5-Angle Studio Turnaround Renderer for The Sky-Highway & Suspended Guideway System
import * as THREE from 'three';
import { makeEngine, lightRig } from './core/engine.js';
import { buildSkyHighway } from './sky_highway.js';
import { canvasTex } from './core/geo.js';

const ANGLES = [
  { id: 'hwy_angle_1_hero', title: 'VIEW 01: FRONT 3/4 HERO HIGH-ANGLE', desc: '4-lane suspended skyway, overhead digital sign gantry, cruising taxi & speeder', pos: [24.0, 20.0, 22.0], target: [0, 11.5, 0], fov: 42 },
  { id: 'hwy_angle_2_side', title: 'VIEW 02: PURE SIDE PROFILE', desc: '36-meter suspended roadbed, crash barriers, foundation pier & support buttresses', pos: [0.0, 11.0, 30.0], target: [0, 10.0, 0], fov: 38 },
  { id: 'hwy_angle_3_gantry', title: 'VIEW 03: OVERHEAD GANTRY CLOSEUP', desc: 'Digital exit signboards, green lane status arrows, speed radar cameras', pos: [14.0, 15.5, 6.0], target: [2.0, 15.0, 0], fov: 35 },
  { id: 'hwy_angle_4_driver', title: 'VIEW 04: ON-ROAD DRIVER PERSPECTIVE', desc: 'Low-angle tarmac view, dashed cyan neon lane lines, vehicles in motion', pos: [18.0, 12.2, 2.2], target: [-8.0, 11.5, 0], fov: 42 },
  { id: 'hwy_angle_5_top', title: 'VIEW 05: TOP-DOWN 3/4 ELEVATED', desc: 'Multi-lane layout, barrier parapet studs, underbody pylon & traffic integration', pos: [12.0, 32.0, 16.0], target: [0, 10.0, 0], fov: 40 },
];

function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Showroom Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#05070D');

  // High-End Architectural Studio Lighting
  const lights = lightRig(scene, {
    key: '#FFFBE8', keyI: 3.4, keyPos: [20, 35, 25],
    rimCol: '#00F0FF', rimI: 2.2,
    sky: '#38BDF8', ground: '#0F172A', hemiI: 0.75,
    shadowBox: 42, target: [0, 10.0, 0]
  });

  // Secondary Warm Gold Rim
  const warmRim = new THREE.DirectionalLight('#F59E0B', 1.8);
  warmRim.position.set(-20, 20, -20);
  scene.add(warmRim);

  // Soft Front Fill Light
  const frontFill = new THREE.DirectionalLight('#93C5FD', 0.85);
  frontFill.position.set(10, 16, 25);
  scene.add(frontFill);

  // Showroom Floor: Cyber Grid Reflective Hexagon Platform
  const floorTex = canvasTex('hwy_showroom_floor', 256, 256, (g, w, h) => {
    g.fillStyle = '#080C16'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#1E293B'; g.lineWidth = 2;
    g.strokeRect(0, 0, w, h);
    g.strokeStyle = 'rgba(0, 240, 255, 0.15)'; g.lineWidth = 1;
    g.beginPath(); g.moveTo(w / 2, 0); g.lineTo(w / 2, h); g.stroke();
    g.beginPath(); g.moveTo(0, h / 2); g.lineTo(w, h / 2); g.stroke();
  }, [30, 30]);

  const floorMat = new THREE.MeshStandardMaterial({
    map: floorTex, roughness: 0.30, metalness: 0.45
  });

  const floor = new THREE.Mesh(new THREE.PlaneGeometry(80, 80), floorMat);
  floor.rotation.x = -Math.PI / 2;
  floor.position.y = 0.0;
  floor.receiveShadow = true;
  scene.add(floor);

  // Circular Neon Trim Ring on Floor
  const ringGeo = new THREE.RingGeometry(22.8, 23.0, 80);
  const ringMat = new THREE.MeshBasicMaterial({ color: '#00F0FF', side: THREE.DoubleSide });
  const floorRing = new THREE.Mesh(ringGeo, ringMat);
  floorRing.rotation.x = -Math.PI / 2;
  floorRing.position.y = 0.01;
  scene.add(floorRing);

  // Build the Sky-Highway Asset
  const highway = buildSkyHighway();
  scene.add(highway);

  const cam = new THREE.PerspectiveCamera(45, 1280 / 760, 0.1, 200);

  // Render individual angles
  const renderedBitmaps = [];

  for (const angle of ANGLES) {
    cam.fov = angle.fov;
    cam.position.set(...angle.pos);
    cam.lookAt(new THREE.Vector3(...angle.target));
    cam.updateProjectionMatrix();

    E.render(scene, cam, {
      bloom: 0.28,
      bloomThreshold: 1.25,
      bloomRadius: 0.45,
      exposure: 1.05,
      sat: 1.22,
      vignette: 0.16,
      focus: cam.position.distanceTo(new THREE.Vector3(...angle.target)),
      aperture: 0.0001
    });

    // Save individual angle render
    const blob = await canvasToBlob(glCanvas);
    await uploadImage(`${angle.id}.png`, blob);
    console.log(`RENDERED & SAVED: ${angle.id}`);

    // Create ImageBitmap for compositing master sheet
    const bmp = await createImageBitmap(glCanvas);
    renderedBitmaps.push({ bmp, angle });
  }

  // --------------------------------------------------------------------------
  // COMPOSITE MASTER 5-ANGLE INSPECTION SHEET (2400 x 1350)
  // --------------------------------------------------------------------------
  const MW = 2400;
  const MH = 1350;
  masterCanvas.width = MW;
  masterCanvas.height = MH;

  // Background
  masterCtx.fillStyle = '#05070D';
  masterCtx.fillRect(0, 0, MW, MH);

  // Subtle Cyan Grid Background
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.04)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < MW; x += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, MH); masterCtx.stroke();
  }
  for (let y = 0; y < MH; y += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(MW, y); masterCtx.stroke();
  }

  // Top Header Banner
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 36px "Segoe UI", Arial, sans-serif';
  masterCtx.fillText('AETHELGARD METROPOLIS // ASSET AUDIT 08', 48, 54);

  masterCtx.font = 'bold 17px monospace';
  masterCtx.fillStyle = '#00F0FF';
  masterCtx.fillText('TRANSIT INFRASTRUCTURE: SKY-HIGHWAY & SUSPENDED GUIDEWAY SYSTEM (SKYWAY 101)', 48, 84);

  masterCtx.fillStyle = '#38BDF8';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('5-ANGLE ROBLOX 3D UGC MASTER SHEET • 100% IN-ENGINE THREE.JS', MW - 48, 48);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.fillText('RENDER: 2400x1350 • 4-LANE DECK • CRASH BARRIERS & STUDS • DIGITAL SIGN GANTRY • LIVE TRAFFIC', MW - 48, 76);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath();
  masterCtx.moveTo(48, 102);
  masterCtx.lineTo(MW - 48, 102);
  masterCtx.stroke();

  // Layout: 2 large panels on top (Views 1 & 2), 3 smaller panels on bottom (Views 3, 4, 5)
  const pad = 24;
  const topY = 126;
  const topH = 550;
  const topW = (MW - 48 * 2 - pad) / 2;

  const botY = 700;
  const botH = 480;
  const botW = (MW - 48 * 2 - pad * 2) / 3;

  const panels = [
    { bmp: renderedBitmaps[0].bmp, angle: renderedBitmaps[0].angle, x: 48, y: topY, w: topW, h: topH },
    { bmp: renderedBitmaps[1].bmp, angle: renderedBitmaps[1].angle, x: 48 + topW + pad, y: topY, w: topW, h: topH },
    { bmp: renderedBitmaps[2].bmp, angle: renderedBitmaps[2].angle, x: 48, y: botY, w: botW, h: botH },
    { bmp: renderedBitmaps[3].bmp, angle: renderedBitmaps[3].angle, x: 48 + botW + pad, y: botY, w: botW, h: botH },
    { bmp: renderedBitmaps[4].bmp, angle: renderedBitmaps[4].angle, x: 48 + (botW + pad) * 2, y: botY, w: botW, h: botH },
  ];

  panels.forEach(({ bmp, angle, x, y, w, h }) => {
    // Panel Frame
    masterCtx.fillStyle = '#080C14';
    masterCtx.fillRect(x, y, w, h);

    // Border
    masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.4)';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(x, y, w, h);

    // Render image
    const imgMargin = 8;
    const destW = w - imgMargin * 2;
    const destH = h - 60;
    masterCtx.drawImage(bmp, 0, 0, bmp.width, bmp.height, x + imgMargin, y + imgMargin, destW, destH);

    // Tech Corner Accents
    const clen = 16;
    masterCtx.strokeStyle = '#00F0FF';
    masterCtx.lineWidth = 3;
    masterCtx.beginPath(); masterCtx.moveTo(x, y + clen); masterCtx.lineTo(x, y); masterCtx.lineTo(x + clen, y); masterCtx.stroke();
    masterCtx.beginPath(); masterCtx.moveTo(x + w - clen, y); masterCtx.lineTo(x + w, y); masterCtx.lineTo(x + w, y + clen); masterCtx.stroke();

    // Bottom Info Strip
    masterCtx.fillStyle = 'rgba(8, 12, 20, 0.95)';
    masterCtx.fillRect(x, y + h - 50, w, 50);

    masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.3)';
    masterCtx.lineWidth = 1;
    masterCtx.beginPath();
    masterCtx.moveTo(x, y + h - 50);
    masterCtx.lineTo(x + w, y + h - 50);
    masterCtx.stroke();

    masterCtx.fillStyle = '#00F0FF';
    masterCtx.font = 'bold 15px monospace';
    masterCtx.fillText(angle.title, x + 16, y + h - 26);

    masterCtx.fillStyle = '#CBD5E1';
    masterCtx.font = '12px "Segoe UI", sans-serif';
    masterCtx.textAlign = 'right';
    masterCtx.fillText(angle.desc, x + w - 16, y + h - 26);
    masterCtx.textAlign = 'left';
  });

  // Footer status bar
  masterCtx.fillStyle = '#475569';
  masterCtx.font = '12px monospace';
  masterCtx.fillText('STATUS: ASSET APPROVED FOR METROPOLIS SHOT 1 ARTERIAL TRANSIT INFRASTRUCTURE • PROCEDURAL GLB READY', 48, MH - 28);

  // Save master sheet to disk
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('hwy_master_sheet.png', masterBlob);
  console.log('SAVED: hwy_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('HIGHWAY_TURNAROUND_COMPLETE');
}

window.initTurnaround = init;
init();

