// ============================================================================
// THE GLITCH MARKET — EPISODE 1 // SHOT 1: AETHELGARD METROPOLIS SKYLINE
// Complete Multi-Layered Urban Assembly combining all 8 authentic Roblox 3D UGC assets:
// - Sovereign Apex Citadel (Boss Tower + Floating Islands + Crystal Spire)
// - Stepped Commercial Cyber-Towers (Tiered setbacks, helipads, holo-billboards)
// - Residential Pod Highrises ("Mini Houses", balconies, ACs, solar arrays)
// - High-Speed Maglev Sky-Train (Apex Express traversing elevated monorail)
// - Suspended Sky-Highway System (Skyway 101, overhead digital sign gantry)
// - Air Traffic Streams: Heavy Cargo Barges, Commuter Sky-Taxis, Neon Speeders
// - Foreground Hero Speeder banking past camera lens with glowing thrusters
// ============================================================================

import * as THREE from 'three';
import { makeEngine, lightRig } from './core/engine.js';
import { createBeveledBox, chamferBox, Textures, canvasTex } from './core/geo.js';

// Import our 8 modular assets
import { buildApexTower } from './apex_tower.js';
import { buildSteppedTower } from './stepped_tower.js';
import { buildPodHighrise } from './pod_highrise.js';
import { buildSkyTrain } from './sky_train.js';
import { buildSkyHighway } from './sky_highway.js';
import { buildCargoBarge } from './cargo_barge.js';
import { buildSkyTaxi } from './taxi.js';
import { buildNeonSpeeder } from './speeder.js';

export function buildMetropolisSkyline(options = {}) {
  const city = new THREE.Group();
  city.name = 'AethelgardMetropolis';

  // --------------------------------------------------------------------------
  // 1. DEEP BACKGROUND: SOVEREIGN APEX CITADEL (BOSS TOWER)
  // --------------------------------------------------------------------------
  const apexTower = buildApexTower();
  apexTower.scale.set(1.6, 1.6, 1.6);
  // Positioned in deep center-background towering into the cyber clouds
  apexTower.position.set(0, 0, -280);
  city.add(apexTower);

  // Distant Horizon Silhouette Towers (Flanking the Apex Citadel)
  const distantMat = new THREE.MeshStandardMaterial({
    color: 0x080D18,
    roughness: 0.8,
    metalness: 0.5
  });

  const distantWindowTex = canvasTex('dist_win', 128, 256, (g, w, h) => {
    g.fillStyle = '#060A14'; g.fillRect(0, 0, w, h);
    for (let y = 8; y < h; y += 16) {
      for (let x = 8; x < w; x += 12) {
        if ((x + y) % 5 === 0) {
          g.fillStyle = Math.random() > 0.5 ? '#38BDF8' : '#F59E0B';
          g.fillRect(x, y, 4, 8);
        }
      }
    }
  }, [1, 4]);

  const matDistantTower = new THREE.MeshStandardMaterial({
    color: 0x0C1220,
    map: distantWindowTex,
    roughness: 0.5
  });

  [
    [-80, -320, 1.3], [80, -320, 1.4],
    [-130, -350, 1.1], [130, -350, 1.2],
    [-45, -260, 0.9], [55, -270, 0.95]
  ].forEach(([x, z, s]) => {
    const dTower = createBeveledBox(16 * s, 70 * s, 16 * s, 0.2, 1, matDistantTower);
    dTower.position.set(x, 35 * s, z);
    city.add(dTower);
  });

  // --------------------------------------------------------------------------
  // 2. MID-GROUND SKYWAY CANYON: COMMERCIAL & RESIDENTIAL TOWERS
  // --------------------------------------------------------------------------
  // Left Bank (West Flank: X < 0)
  // Commercial Tower 1 (Mid-distance, high setbacks)
  const commLeft1 = buildSteppedTower();
  commLeft1.scale.set(1.1, 1.1, 1.1);
  commLeft1.position.set(-42, 0, -140);
  commLeft1.rotation.y = 0.35;
  city.add(commLeft1);

  // Residential Pod Stack 1 (Closer, high density)
  const podLeft1 = buildPodHighrise();
  podLeft1.position.set(-28, 0, -75);
  podLeft1.rotation.y = 0.5;
  city.add(podLeft1);

  // Residential Pod Stack 2 (Mid-distance)
  const podLeft2 = buildPodHighrise();
  podLeft2.scale.set(0.9, 0.9, 0.9);
  podLeft2.position.set(-58, 0, -190);
  podLeft2.rotation.y = -0.25;
  city.add(podLeft2);

  // Right Bank (East Flank: X > 0)
  // Commercial Tower 2 (Main commercial focal tower with vertical holo-ad)
  const commRight1 = buildSteppedTower();
  commRight1.scale.set(1.15, 1.15, 1.15);
  commRight1.position.set(45, 0, -125);
  commRight1.rotation.y = -0.4;
