  commRight2.scale.set(0.95, 0.95, 0.95);
  commRight2.position.set(65, 0, -180);
  commRight2.rotation.y = 0.2;
  city.add(commRight2);

  // --------------------------------------------------------------------------
  // 3. SUSPENDED SKY-BRIDGES (CONNECTING TOWERS ACROSS THE CHASM)
  // --------------------------------------------------------------------------
  const matSkyBridge = new THREE.MeshStandardMaterial({
    color: 0x1A2230,
    roughness: 0.45,
    metalness: 0.55
  });

  const matBridgeGlass = new THREE.MeshStandardMaterial({
    color: 0x00F0FF,
    roughness: 0.1,
    transparent: true,
    opacity: 0.6
  });

  function createSkyBridge(fromPos, toPos, yPos) {
    const bridgeGroup = new THREE.Group();
    const vFrom = new THREE.Vector3(...fromPos, yPos);
    const vTo = new THREE.Vector3(...toPos, yPos);
    const len = vFrom.distanceTo(vTo);
    const mid = new THREE.Vector3().addVectors(vFrom, vTo).multiplyScalar(0.5);

    const bBox = createBeveledBox(len, 2.6, 2.8, 0.05, 1, matSkyBridge);
    bBox.position.copy(mid);
    bBox.lookAt(vTo);
    bBox.rotateY(Math.PI / 2);
    bridgeGroup.add(bBox);

    // Glowing glass observation strip along bridge sides
    const bGlass = new THREE.Mesh(new THREE.BoxGeometry(len - 0.4, 1.2, 2.85), matBridgeGlass);
    bGlass.position.copy(mid);
    bGlass.lookAt(vTo);
    bGlass.rotateY(Math.PI / 2);
    bridgeGroup.add(bGlass);

    return bridgeGroup;
  }

