  barge1.position.set(-18.0, 16.0, -110);
  barge1.rotation.y = -0.3; // drifting outward
  city.add(barge1);

  // Commuter Sky-Taxi 1: Cruising along mid-altitude flight lane
  const taxi1 = buildSkyTaxi();
  taxi1.scale.set(0.85, 0.85, 0.85);
  taxi1.position.set(-8.0, 24.0, -70);
