  taxi3.scale.set(0.5, 0.5, 0.5);
  taxi3.position.set(12.0, 28.0, -170);
  taxi3.rotation.y = 0.35;
  city.add(taxi3);

  // Neon Speeder 1 (Mid-ground speeder overtaking traffic)
