  midSpeeder.scale.set(0.75, 0.75, 0.75);
  midSpeeder.position.set(6.0, 22.0, -85);
  midSpeeder.rotation.y = 0.2;
  city.add(midSpeeder);

  // Neon Speeder 2 (Distant fast racer banking around left tower)
