    wireframe: true,
    transparent: true,
    opacity: 0.18
  });
  const voidGrid = new THREE.Mesh(new THREE.PlaneGeometry(350, 450, 24, 28), voidGridMat);
  voidGrid.rotation.x = -Math.PI / 2;
  voidGrid.position.set(0, -12.5, -180);
  city.add(voidGrid);

  return city;
}

