  function createFloatingIsland(x, z, w, d, h) {
    const islandGroup = new THREE.Group();
    // Stepped beveled strata
    const topCap = createBeveledBox(w, h * 0.3, d, 0.15, 1, matVoxelBedrock);
    topCap.position.set(x, -h * 0.15, z);
