    const midLayer = createBeveledBox(w * 0.8, h * 0.4, d * 0.8, 0.2, 1, matVoxelBedrock);
    midLayer.position.set(x, -h * 0.45, z);
    islandGroup.add(midLayer);

    const botKeel = createBeveledBox(w * 0.5, h * 0.3, d * 0.5, 0.25, 1, matVoxelBedrock);
    botKeel.position.set(x, -h * 0.75, z);
