  // Floating foundations under major tower clusters
  city.add(createFloatingIsland(-32, -100, 48, 60, 18));
  city.add(createFloatingIsland(34, -95, 52, 65, 20));
  city.add(createFloatingIsland(0, -250, 75, 80, 28));

  // The Glitch Void Bottom Grid (Deep infinite abyss at Y = -40m)
  const voidGridMat = new THREE.MeshBasicMaterial({
