export function buildMetropolisSkyline(options = {}) {
  const city = new THREE.Group();
  city.name = 'AethelgardMetropolis';

  // --------------------------------------------------------------------------
  // 1. DEEP BACKGROUND: SOVEREIGN APEX CITADEL (BOSS TOWER)
  // --------------------------------------------------------------------------
  const apexTower = buildApexTower();
  apexTower.scale.set(1.5, 1.5, 1.5);
  apexTower.position.set(0, 0, -250);
  city.add(apexTower);

  // Distant Horizon Silhouette Towers with glowing office windows
  const distantWindowTex = canvasTex('dist_win_dense', 128, 256, (g, w, h) => {
    g.fillStyle = '#050A14'; g.fillRect(0, 0, w, h);
    for (let y = 6; y < h; y += 12) {
      for (let x = 6; x < w; x += 10) {
        if ((x * 3 + y * 7) % 4 !== 0) {
          g.fillStyle = (x + y) % 3 === 0 ? '#38BDF8' : '#F59E0B';
          g.fillRect(x, y, 5, 7);
        }
      }
    }
  }, [2, 6]);

  const matDistantTower = new THREE.MeshStandardMaterial({
    color: 0x080D1A,
    map: distantWindowTex,
    roughness: 0.45,
    metalness: 0.5
  });

  [
    [-65, -290, 1.3], [65, -290, 1.35],
    [-110, -330, 1.1], [110, -330, 1.15],
    [-38, -220, 0.9], [42, -225, 0.95]
  ].forEach(([x, z, s]) => {
    const dTower = createBeveledBox(14 * s, 85 * s, 14 * s, 0.2, 1, matDistantTower);
    dTower.position.set(x, 42 * s, z);
    city.add(dTower);
  });

  // --------------------------------------------------------------------------
  // 2. MID-GROUND CANYON: COMMERCIAL TOWERS & POD HIGH-RISES
  // Facing window facades toward camera for maximum visual density!
  // --------------------------------------------------------------------------
  // Left Flank (West)
  // Stepped Commercial Tower 1 (Vertical Holo-Ad facing toward camera)
  const commLeft1 = buildSteppedTower();
  commLeft1.scale.set(1.05, 1.05, 1.05);
  commLeft1.position.set(-32, 2.0, -100);
  commLeft1.rotation.y = -0.25; // rotated so holo-billboard & windows face viewer!
  city.add(commLeft1);

  // Residential Pod Highrise 1 (Balconies & warm windows facing camera)
  const podLeft1 = buildPodHighrise();
  podLeft1.scale.set(1.05, 1.05, 1.05);
  podLeft1.position.set(-20, 2.0, -60);
  podLeft1.rotation.y = -0.15;
  city.add(podLeft1);

  // Distant Pod Highrise 2 (Deep left skyline)
  const podLeft2 = buildPodHighrise();
  podLeft2.scale.set(0.85, 0.85, 0.85);
  podLeft2.position.set(-46, 0, -160);
  podLeft2.rotation.y = 0.3;
  city.add(podLeft2);

  // Right Flank (East — framing the right side of the vertical shot)
  // Stepped Commercial Tower 2 (Main commercial highrise on right with helipad)
  const commRight1 = buildSteppedTower();
  commRight1.scale.set(1.1, 1.1, 1.1);
  commRight1.position.set(30, 2.0, -95);
  commRight1.rotation.y = 0.35; // windows and landing pad facing viewer!
  city.add(commRight1);

  // Residential Pod Highrise 3 (Close right foreground mid-tier with colorful mini-houses)
  const podRight1 = buildPodHighrise();
  podRight1.scale.set(1.0, 1.0, 1.0);
  podRight1.position.set(22, 2.0, -52);
  podRight1.rotation.y = 0.45; // balconies facing camera!
  city.add(podRight1);

  // Stepped Commercial Tower 3 (Deep right skyline)
  const commRight2 = buildSteppedTower();
  commRight2.scale.set(0.9, 0.9, 0.9);
  commRight2.position.set(50, 0, -155);
  commRight2.rotation.y = -0.2;
  city.add(commRight2);

  // --------------------------------------------------------------------------
  // 3. SUSPENDED SKY-BRIDGES (CONNECTING TOWERS ACROSS THE VOID)
  // --------------------------------------------------------------------------
  const matSkyBridge = new THREE.MeshStandardMaterial({
    color: 0x1A2230,
    roughness: 0.45,
    metalness: 0.55
  });

  const matBridgeGlass = new THREE.MeshStandardMaterial({
    color: 0x00F0FF,
    roughness: 0.1,
    transparent: true,
    opacity: 0.65
  });

  function createSkyBridge(fromPos, toPos, yPos) {
    const bridgeGroup = new THREE.Group();
    const vFrom = new THREE.Vector3(...fromPos, yPos);
    const vTo = new THREE.Vector3(...toPos, yPos);
    const len = vFrom.distanceTo(vTo);
    const mid = new THREE.Vector3().addVectors(vFrom, vTo).multiplyScalar(0.5);

    const bBox = createBeveledBox(len, 2.6, 2.8, 0.05, 1, matSkyBridge);
    bBox.position.copy(mid);
    bBox.lookAt(vTo);
    bBox.rotateY(Math.PI / 2);
    bridgeGroup.add(bBox);

    const bGlass = new THREE.Mesh(new THREE.BoxGeometry(len - 0.4, 1.2, 2.85), matBridgeGlass);
    bGlass.position.copy(mid);
    bGlass.lookAt(vTo);
    bGlass.rotateY(Math.PI / 2);
    bridgeGroup.add(bGlass);

    return bridgeGroup;
  }

  city.add(createSkyBridge([-32, -100], [-20, -60], 22.0));
  city.add(createSkyBridge([22, -52], [30, -95], 20.0));

  // --------------------------------------------------------------------------
  // 4. HIGH-ALTITUDE TRANSIT: HIGH-SPEED MAGLEV SKY-TRAIN (APEX EXPRESS)
  // --------------------------------------------------------------------------
  const train1 = buildSkyTrain();
  train1.scale.set(0.9, 0.9, 0.9);
