  const barge1 = buildCargoBarge();
  barge1.scale.set(0.65, 0.65, 0.65);
  barge1.position.set(-14.0, 22.0, -95);
  barge1.rotation.y = -0.22;
  city.add(barge1);

  // Commuter Sky-Taxi 1: Cruising along mid-altitude flight corridor
  const taxi1 = buildSkyTaxi();
  taxi1.scale.set(0.85, 0.85, 0.85);
  taxi1.position.set(-5.0, 26.0, -55);
  taxi1.rotation.y = 0.18;
  city.add(taxi1);

  // Commuter Sky-Taxi 2: Approaching commercial tower helipad on right
  const taxi2 = buildSkyTaxi();
  taxi2.scale.set(0.75, 0.75, 0.75);
  taxi2.position.set(28.0, 22.0, -90);
  taxi2.rotation.y = -1.1;
  city.add(taxi2);

  // Commuter Sky-Taxi 3: Distant commuter in traffic stream
  const taxi3 = buildSkyTaxi();
  taxi3.scale.set(0.55, 0.55, 0.55);
  taxi3.position.set(12.0, 31.0, -150);
  taxi3.rotation.y = 0.35;
  city.add(taxi3);

  // Neon Speeder 1 (Mid-ground speeder overtaking traffic)
  const midSpeeder = buildNeonSpeeder();
  midSpeeder.scale.set(0.75, 0.75, 0.75);
  midSpeeder.position.set(4.0, 24.0, -72);
  midSpeeder.rotation.y = 0.25;
  city.add(midSpeeder);

  // Neon Speeder 2 (Distant fast racer banking around left tower)
  const distSpeeder = buildNeonSpeeder();
  distSpeeder.scale.set(0.5, 0.5, 0.5);
  distSpeeder.position.set(-25.0, 29.0, -120);
  distSpeeder.rotation.y = 0.55;
  distSpeeder.rotation.z = -0.28;
  city.add(distSpeeder);

  // --------------------------------------------------------------------------
  // 7. FOREGROUND HERO ELEMENT: CLOSE SPEEDER BANKING PAST CAMERA
  // --------------------------------------------------------------------------
  const heroSpeeder = buildNeonSpeeder();
  heroSpeeder.scale.set(1.2, 1.2, 1.2);
  heroSpeeder.position.set(4.6, 17.5, -15.0);
  heroSpeeder.rotation.y = 0.30;
  heroSpeeder.rotation.z = -0.26;
  heroSpeeder.rotation.x = -0.10;
  city.add(heroSpeeder);

  // Glowing Cyan Ion Thruster Jet Plumes behind Hero Speeder
  const matJetPlume = new THREE.MeshBasicMaterial({
    color: 0x00F0FF,
    transparent: true,
    opacity: 0.85
  });

  [-0.82, 0.82].forEach(tz => {
    const plume = new THREE.Mesh(
      new THREE.ConeGeometry(0.40, 3.2, 12),
      matJetPlume
    );
    plume.rotation.z = Math.PI / 2;
    plume.position.set(2.8, 17.5 + tz * 0.18, -15.0 - 2.2 + tz * 0.45);
    city.add(plume);
  });

  // --------------------------------------------------------------------------
  // 8. THE GLITCH VOID & FLOATING OBSIDIAN BEDROCK ISLANDS
  // --------------------------------------------------------------------------
  // Dark reflective obsidian bedrock under tower bases (No brown!)
  const matVoxelBedrock = new THREE.MeshStandardMaterial({
    color: 0x0A0F1A,
    roughness: 0.35,
    metalness: 0.7
  });

  function createFloatingIsland(x, z, w, d, h) {
    const islandGroup = new THREE.Group();
    const topCap = createBeveledBox(w, h * 0.3, d, 0.15, 1, matVoxelBedrock);
    topCap.position.set(x, -h * 0.15, z);
    islandGroup.add(topCap);

    const midLayer = createBeveledBox(w * 0.8, h * 0.4, d * 0.8, 0.2, 1, matVoxelBedrock);
    midLayer.position.set(x, -h * 0.45, z);
    islandGroup.add(midLayer);

    const botKeel = createBeveledBox(w * 0.5, h * 0.3, d * 0.5, 0.25, 1, matVoxelBedrock);
    botKeel.position.set(x, -h * 0.75, z);
    islandGroup.add(botKeel);

    return islandGroup;
  }

  city.add(createFloatingIsland(-28, -90, 42, 55, 16));
  city.add(createFloatingIsland(28, -85, 46, 58, 18));
  city.add(createFloatingIsland(0, -240, 70, 75, 26));

  // The Glitch Void Bottom Grid (Deep infinite abyss at Y = -35m)
  const voidGridMat = new THREE.MeshBasicMaterial({
    color: 0x00F0FF,
    wireframe: true,
    transparent: true,
    opacity: 0.28
  });
  const voidGrid = new THREE.Mesh(new THREE.PlaneGeometry(600, 700, 36, 44), voidGridMat);
  voidGrid.rotation.x = -Math.PI / 2;
  voidGrid.position.set(0, -35.0, -160);
  city.add(voidGrid);

  // Soft Upward Cyan Light Shafts positioned in the deep background (Z < -130)
  const lightShaftMatCyan = new THREE.MeshBasicMaterial({
    color: 0x00F0FF,
    transparent: true,
    opacity: 0.05,
    side: THREE.DoubleSide
  });

  const lightShaftMatPurple = new THREE.MeshBasicMaterial({
    color: 0x8B5CF6,
    transparent: true,
    opacity: 0.04,
    side: THREE.DoubleSide
