function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Build the 3D Metropolis Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#020409');
  // Atmospheric Deep Void Fog
  scene.fog = new THREE.FogExp2('#020409', 0.0030);

  // Directional High-Altitude Moon/City Key Light (Cool Ice White / Pale Cyan)
  const keyLight = new THREE.DirectionalLight('#DCEBFA', 2.2);
  keyLight.position.set(40, 80, -50);
  keyLight.target.position.set(0, 20, -120);
  scene.add(keyLight);
  scene.add(keyLight.target);

  // Intense Cyan Underbelly Void Rim Light
  const cyanRim = new THREE.DirectionalLight('#00F0FF', 3.2);
  cyanRim.position.set(-45, -12, -100);
  cyanRim.target.position.set(0, 22, -120);
  scene.add(cyanRim);
