  cyberSkyBackdrop: () => canvasTex('cyber_sky_bg', 2048, 1024, (g, w, h) => {
    // Vertical twilight gradient
    const grad = g.createLinearGradient(0, 0, 0, h);
    grad.addColorStop(0.0, '#03050F');
    grad.addColorStop(0.35, '#0B1028');
    grad.addColorStop(0.65, '#2D1052');
    grad.addColorStop(0.85, '#1E1B4B');
    grad.addColorStop(1.0, '#042F2E');
    g.fillStyle = grad;
    g.fillRect(0, 0, w, h);

    // Nebula Glow Clouds (Electric Purple & Cyan Wisps)
    for (let i = 0; i < 6; i++) {
      const cx = (w * (0.2 + i * 0.15)) % w;
      const cy = h * (0.35 + (i % 3) * 0.12);
      const rad = 250 + (i % 3) * 120;
      const nGrad = g.createRadialGradient(cx, cy, 10, cx, cy, rad);
      nGrad.addColorStop(0.0, i % 2 === 0 ? 'rgba(147, 51, 234, 0.35)' : 'rgba(6, 182, 212, 0.28)');
      nGrad.addColorStop(0.6, i % 2 === 0 ? 'rgba(126, 34, 206, 0.12)' : 'rgba(14, 116, 144, 0.08)');
      nGrad.addColorStop(1.0, 'rgba(0,0,0,0)');
      g.fillStyle = nGrad;
      g.beginPath(); g.arc(cx, cy, rad, 0, Math.PI * 2); g.fill();
    }

    // Distant Cyber Moon / Celestial Data Sphere
    const mx = w * 0.52;
    const my = h * 0.28;
    const mGrad = g.createRadialGradient(mx, my, 15, mx, my, 180);
    mGrad.addColorStop(0.0, 'rgba(255, 255, 255, 0.95)');
    mGrad.addColorStop(0.2, 'rgba(56, 189, 248, 0.85)');
    mGrad.addColorStop(0.5, 'rgba(168, 85, 247, 0.35)');
    mGrad.addColorStop(1.0, 'rgba(0, 0, 0, 0)');
    g.fillStyle = mGrad;
    g.beginPath(); g.arc(mx, my, 180, 0, Math.PI * 2); g.fill();

    // Data Sphere Wireframe Rings
    g.strokeStyle = 'rgba(0, 240, 255, 0.4)'; g.lineWidth = 2;
    g.beginPath(); g.arc(mx, my, 55, 0, Math.PI * 2); g.stroke();
    g.beginPath(); g.ellipse(mx, my, 85, 25, Math.PI / 6, 0, Math.PI * 2); g.stroke();

    // Voxel Star Field / Data Sparks
    for (let s = 0; s < 400; s++) {
      const sx = Math.random() * w;
      const sy = Math.random() * h * 0.7;
      const sz = Math.random() > 0.85 ? 2.5 : 1.2;
      g.fillStyle = Math.random() > 0.4 ? '#38BDF8' : '#F5D0FE';
      g.fillRect(sx, sy, sz, sz);
    }

    // Horizon City Smog Neon Glow
    const hGrad = g.createLinearGradient(0, h * 0.75, 0, h);
    hGrad.addColorStop(0.0, 'rgba(0, 240, 255, 0.0)');
    hGrad.addColorStop(0.7, 'rgba(6, 182, 212, 0.22)');
