        // Block footprint
        g.fillStyle = '#0A0F1D';
        g.fillRect(bx + 4, by + 4, bSize - 8, bSize - 8);

        // Thousands of tiny rooftop & building window points
        for (let ix = bx + 8; ix < bx + bSize - 8; ix += 8) {
