    for (let r = 0; r < rows; r++) {
      for (let c = 0; c < cols; c++) {
        const lit = ((r * 11 + c * 17) % 4) !== 0;
        if (lit) {
          const colPick = (r + c * 3) % 5;
          g.fillStyle = colPick === 0 ? '#38BDF8' : colPick === 1 ? '#00F0FF' : colPick === 2 ? '#FBBF24' : colPick === 3 ? '#A855F7' : '#F43F5E';
          g.fillRect(c * cw + 4, r * rh + 4, cw - 8, rh - 8);
        } else {
          g.fillStyle = '#0D1424';
          g.fillRect(c * cw + 4, r * rh + 4, cw - 8, rh - 8);
        }
