// ============================================================================
// THE GLITCH MARKET — EPISODE 1 // SHOT 1: AETHELGARD METROPOLIS SKYLINE
// Master High-Density Urban Environment (No Plain Void / Pure Cyberpunk Megalopolis):
// - Cyber Celestial Skybox: Nebula clouds, celestial data moon, voxel starfield, cyan horizon glow
// - Sprawling Lower City Underbelly: 800m glowing street grid, 25+ ground cyber-blocks, neon conduits
// - Horizon Megacity Silhouettes: 40+ layered distant skyscrapers with dense glowing window matrices
// - Mid-Ground Canyon: Stepped Commercial Towers, Pod Highrises, crisscrossing Sky-Bridges
// - Giant Holographic Billboards: GLITCH MARKET, SHADOW MONARCH, AETHELGARD
// - Multi-Tier Transit: High-Speed Maglev Train, Dual Skyways (Y=14m, Y=22m) with digital gantries
// - Swarming Air Traffic: 18+ Sky-Taxis, Cargo Barges, and Speeders with light trails
// - Foreground Hero Speeder: Monarch-01 banking sharply with glowing cyan ion plumes
// ============================================================================

import * as THREE from 'three';
import { createBeveledBox, chamferBox, Textures, canvasTex } from './core/geo.js';

// Modular Assets
import { buildApexTower } from './apex_tower.js';
import { buildSteppedTower } from './stepped_tower.js';
import { buildPodHighrise } from './pod_highrise.js';
import { buildSkyTrain } from './sky_train.js';
import { buildSkyHighway } from './sky_highway.js';
import { buildCargoBarge } from './cargo_barge.js';
import { buildSkyTaxi } from './taxi.js';
import { buildNeonSpeeder } from './speeder.js';

export function buildMetropolisSkyline(options = {}) {
  const city = new THREE.Group();
  city.name = 'AethelgardMetropolis';

  // --------------------------------------------------------------------------
  // 1. GRAND CYBER SKY BACKDROP DOME (NEBULA, DATA MOON & STARFIELD)
  // --------------------------------------------------------------------------
  const skyGeo = new THREE.CylinderGeometry(550, 550, 450, 48, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 120, -180);
  city.add(skyDome);

  // --------------------------------------------------------------------------
  // 2. SPRAWLING LOWER CITY UNDERBELLY (800m x 800m DENSE METROPOLIS GRID)
  // --------------------------------------------------------------------------
  const groundMat = new THREE.MeshStandardMaterial({
    map: Textures.citySprawlGround(),
    roughness: 0.35,
    metalness: 0.5
  });

  const cityGround = new THREE.Mesh(new THREE.PlaneGeometry(800, 800), groundMat);
  cityGround.rotation.x = -Math.PI / 2;
  cityGround.position.set(0, -6.0, -180);
  city.add(cityGround);

  // Ground-Level Cyber-Blocks & Industrial Slum Pods (25+ low-to-mid buildings)
  const matLowerBlock = new THREE.MeshStandardMaterial({
    color: 0x111624,
    roughness: 0.55,
    metalness: 0.4
  });

  const matNeonSign = new THREE.MeshBasicMaterial({ color: 0x00F0FF });
  const matOrangeSign = new THREE.MeshBasicMaterial({ color: 0xF59E0B });
  const matMagentaSign = new THREE.MeshBasicMaterial({ color: 0xEC4899 });

  for (let gx = -160; gx <= 160; gx += 40) {
    for (let gz = -240; gz <= -40; gz += 45) {
      if (Math.abs(gx) > 20 || gz < -140) {
        const bHeight = 8 + ((Math.abs(gx) * 3 + Math.abs(gz)) % 18);
        const bWidth = 18 + (Math.abs(gx) % 12);
        const bDepth = 18 + (Math.abs(gz) % 12);

        const lowerBlock = createBeveledBox(bWidth, bHeight, bDepth, 0.1, 1, matLowerBlock);
        lowerBlock.position.set(gx + ((gz % 7) * 2), bHeight / 2 - 6.0, gz);
        city.add(lowerBlock);

        // Neon storefront signs and rooftop vents on lower blocks
        const signCol = (gx + gz) % 3 === 0 ? matNeonSign : (gx + gz) % 3 === 1 ? matOrangeSign : matMagentaSign;
        const sign = new THREE.Mesh(new THREE.BoxGeometry(bWidth * 0.7, 0.4, 0.2), signCol);
        sign.position.set(gx + ((gz % 7) * 2), bHeight - 7.5, gz + bDepth / 2 + 0.12);
        city.add(sign);

        // Rooftop AC / Machinery box with studs
        const roofUnit = createBeveledBox(4.0, 1.6, 4.0, 0.05, 1, matLowerBlock);
        roofUnit.position.set(gx + ((gz % 7) * 2), bHeight - 5.2, gz);
        city.add(roofUnit);
      }
    }
  }

  // --------------------------------------------------------------------------
  // 3. HORIZON MEGACITY SKYLINE (40+ DISTANT TOWERS ACROSS ENTIRE HORIZON)
  // --------------------------------------------------------------------------
  const matDistantTower = new THREE.MeshStandardMaterial({
    map: Textures.denseHighriseFacade(),
    roughness: 0.35,
    metalness: 0.45
  });

  const matAviationRed = new THREE.MeshBasicMaterial({ color: 0xFF1744 });
  const matAviationCyan = new THREE.MeshBasicMaterial({ color: 0x00F0FF });

  // Generate a continuous dense arc of skyscrapers across the horizon
  for (let i = -20; i <= 20; i++) {
    const angle = (i / 20) * (Math.PI * 0.45);
    const dist = 320 + Math.abs(i) * 5 + ((i * 17) % 25);
    const tx = Math.sin(angle) * dist;
    const tz = -Math.cos(angle) * dist - 30;
    const th = 70 + ((Math.abs(i) * 11) % 65);
    const tw = 16 + (Math.abs(i) % 10);
    const td = 16 + ((i * 7) % 10);

    const horizonTower = createBeveledBox(tw, th, td, 0.2, 1, matDistantTower);
