    glowRunner.position.copy(mid);
    glowRunner.position.y += 1.45;
    glowRunner.lookAt(vTo);
    glowRunner.rotateY(Math.PI / 2);
    bridgeGroup.add(glowRunner);

    return bridgeGroup;
  }

