    // [type, x, y, z, rotY, scale]
    ['barge', -14.0, 22.0, -90, -0.22, 0.65],
    ['barge', 26.0, 18.0, -125, 0.35, 0.60],
    ['taxi', -5.0, 26.0, -52, 0.18, 0.85],
    ['taxi', 25.0, 22.0, -82, -1.1, 0.75],
    ['taxi', 12.0, 31.0, -145, 0.35, 0.55],
