    masterCtx.fillStyle = '#64748B';
    masterCtx.font = '12px "Segoe UI", sans-serif';
    masterCtx.fillText(item.desc, legendX + 112, itemY + 16);
  });

  // Footer status bar
  masterCtx.fillStyle = 'rgba(5, 8, 18, 0.95)';
  masterCtx.fillRect(legendX, botY + botH - 44, botHalfW, 44);
  masterCtx.fillStyle = '#00FF88';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.fillText('✔ HIGH-DENSITY ASSEMBLY VALIDATED • ZERO PLAIN VOID', legendX + 16, botY + botH - 20);

  // Save the master presentation sheet
