// Overhead Highway Gantry Electronic Sign
highwayGantrySign: () => canvasTex('hwy_gantry_sign', 512, 128, (g, w, h) => {
  g.fillStyle = '#050914'; g.fillRect(0, 0, w, h);
  g.strokeStyle = '#00F0FF'; g.lineWidth = 4; g.strokeRect(4, 4, w - 8, h - 8);
  // Left destination: Sector 01
  g.fillStyle = '#00F0FF'; g.font = '900 24px monospace';
  g.fillText('EXIT 12A: APEX CITADEL', 24, 44);
  g.font = 'bold 14px monospace'; g.fillStyle = '#38BDF8';
  g.fillText('LOWER SKYWAY // SPEED: 600 STUDS/S', 24, 70);
  // Right destination: Arena
  g.fillStyle = '#F59E0B'; g.font = '900 24px monospace';
  g.fillText('EXIT 12B: COLOSSEUM', 270, 44);
  g.font = 'bold 14px monospace'; g.fillStyle = '#FBBF24';
  g.fillText('ARENA SECTOR // LIVE COMBAT', 270, 70);
