  }
}, [1, 1]),

// Cyberpunk Street Bodega / Shopfront Facade Texture
streetBodegaFacade: (shopType = 0) => canvasTex(`bodega_facade_${shopType}`, 256, 512, (g, w, h) => {
  // Upper wall body (dark concrete with panels)
  g.fillStyle = '#0F172A'; g.fillRect(0, 0, w, h);

  // Panel horizontal joints
  g.strokeStyle = '#1E293B'; g.lineWidth = 2;
  for (let y = 0; y < h * 0.6; y += 40) {
    g.beginPath(); g.moveTo(0, y); g.lineTo(w, y); g.stroke();
  }

  // 2nd & 3rd Floor Windows with glowing frames & blinds
  const winTiers = [60, 160];
  winTiers.forEach(wy => {
    [32, 144].forEach(wx => {
      g.fillStyle = '#0A0F1D'; g.fillRect(wx - 4, wy - 4, 88, 72);
      const winLit = (wx + wy + shopType) % 2 === 0;
      g.fillStyle = winLit ? '#FBBF24' : '#38BDF8';
      g.fillRect(wx, wy, 80, 64);
      // Blinds / mullions
      g.fillStyle = '#0A0F1D';
      g.fillRect(wx + 38, wy, 4, 64);
      g.fillRect(wx, wy + 30, 80, 4);
      // Horizontal blind slats
      for (let by = wy + 4; by < wy + 26; by += 6) {
        g.fillStyle = 'rgba(15, 23, 42, 0.4)';
        g.fillRect(wx, by, 80, 2);
      }
    });
  });

  // Floor divider neon line
  g.fillStyle = shopType === 0 ? '#00F0FF' : shopType === 1 ? '#F59E0B' : '#EC4899';
  g.fillRect(0, h * 0.58, w, 4);

  // Ground Floor Bodega Storefront (h * 0.6 to h)
  g.fillStyle = '#070B14'; g.fillRect(0, h * 0.6, w, h * 0.4);

  // Illuminated Neon Signboard Banner
  const bannerY = h * 0.62;
  g.fillStyle = '#050811'; g.fillRect(12, bannerY, w - 24, 48);
  g.strokeStyle = shopType === 0 ? '#F43F5E' : shopType === 1 ? '#00F0FF' : '#F59E0B';
  g.lineWidth = 3; g.strokeRect(12, bannerY, w - 24, 48);

  const shopNames = ['RAMEN 2077', 'CYBER-CHIP', 'GLITCH MART', 'UGC BLADES'];
  const shopColors = ['#FF2A6D', '#00F0FF', '#05FFA1', '#F59E0B'];
  g.fillStyle = shopColors[shopType % shopColors.length];
  g.font = '900 20px monospace'; g.textAlign = 'center';
  g.fillText(shopNames[shopType % shopNames.length], w / 2, bannerY + 32);

  // Ground Storefront: Roll-up Security Shutter or Glass Window
  const storeY = h * 0.74;
  g.fillStyle = '#1E2530'; g.fillRect(20, storeY, w - 40, h - storeY - 10);
  // Slat lines on metal shutter
  for (let sy = storeY; sy < h - 10; sy += 8) {
    g.strokeStyle = '#0F141C'; g.lineWidth = 1.5;
    g.beginPath(); g.moveTo(20, sy); g.lineTo(w - 20, sy); g.stroke();
  }
  // Hazard stripe on bottom edge
  for (let hz = 20; hz < w - 20; hz += 16) {
    g.fillStyle = '#F59E0B';
    g.beginPath();
    g.moveTo(hz, h - 22); g.lineTo(hz + 8, h - 22); g.lineTo(hz + 4, h - 14); g.lineTo(hz - 4, h - 14);
    g.closePath(); g.fill();
  }
}, [1, 1]),

