352:   const baseW = opts.width || 20;
353:   const stepH = opts.stepHeight || 6.0;
354:   const baseD = opts.depth || 16;
355: 
356:   for (let s = 0; s < steps; s++) {
357:     const sw = baseW * (1.0 - s * 0.18);
358:     const sd = baseD * (1.0 - s * 0.18);
359:     const sy = s * stepH + stepH / 2;
360: 
361:     const block = createBeveledBox(sw, stepH, sd, 0.1, 2, s % 2 === 0 ? MATS.cyberTeal : MATS.steelAlloy);
362:     block.position.set(0, sy, -s * (baseD * 0.08));
363:     root.add(block);
364: 
365:     // Stepped Terrace Rooftop Balcony with green solar tiles
366:     const balcony = new THREE.Mesh(new THREE.PlaneGeometry(sw * 0.9, sd * 0.3), MATS.glowGreen);
367:     balcony.rotation.x = -Math.PI / 2;
368:     balcony.position.set(0, sy + stepH / 2 + 0.02, -s * (baseD * 0.08) + sd * 0.3);
369:     root.add(balcony);
370: 
371:     // Terrace Safety Railing
372:     const rail = createBeveledBox(sw * 0.92, 0.6, 0.08, 0.01, 1, MATS.glowAmber);
373:     rail.position.set(0, sy + stepH / 2 + 0.32, -s * (baseD * 0.08) + sd * 0.46);
374:     root.add(rail);
375:   }
376: 
377:   return root;
378: }
