// ============================================================================
// THE GLITCH MARKET — 3D ASSETS: EXPANDED MODULAR BUILDING ARCHETYPES
// 8 Brand-New Authentic Roblox UGC Building Models for Dense Megalopolis:
// 1. Twin-Spire Gateway Tower (Dual hexagonal spires with cross-skybridge arch)
// 2. Cantilevered Tetris Midrise (Interlocking staggered cantilever blocks)
// 3. Hexagonal Data-Silo (Brutalist server monolith with vertical cooling fins)
// 4. Sloped Wedge Sky-Blade (Aerodynamic angled skyscraper with diagonal trusses)
// 5. Cylindrical Neo-Rotunda Tower (Concentric observation tiers & 360 wrap ticker)
// 6. Compact Cyber-Shophouse Block (Low-rise street bodegas, neon awnings, roll-up doors, ACs)
// 7. Stepped Terraced Apartment Block (Ziggurat stepped residential block with rooftop gardens)
// 8. Industrial Power Substation (Heavy steel transformer gantry with glowing conduits)
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createBeveledBox, chamferBox, Textures, canvasTex } from './core/geo.js';

// Common Palette Materials (Cached for performance)
const MATS = {
  darkConcrete: new THREE.MeshStandardMaterial({ color: 0x111622, roughness: 0.65, metalness: 0.35 }),
  steelAlloy: new THREE.MeshStandardMaterial({ color: 0x1E2638, roughness: 0.45, metalness: 0.6 }),
  lightPlate: new THREE.MeshStandardMaterial({ color: 0xCBD5E1, roughness: 0.35, metalness: 0.4 }),
  terracotta: new THREE.MeshStandardMaterial({ color: 0xB91C1C, roughness: 0.5 }),
  cyberTeal: new THREE.MeshStandardMaterial({ color: 0x0D9488, roughness: 0.4 }),
  industrialAmber: new THREE.MeshStandardMaterial({ color: 0xD97706, roughness: 0.45 }),
  glassCyan: new THREE.MeshStandardMaterial({ color: 0x00F0FF, roughness: 0.1, transparent: true, opacity: 0.65 }),
  glowCyan: new THREE.MeshBasicMaterial({ color: 0x00F0FF }),
  glowAmber: new THREE.MeshBasicMaterial({ color: 0xF59E0B }),
  glowMagenta: new THREE.MeshBasicMaterial({ color: 0xEC4899 }),
  glowRed: new THREE.MeshBasicMaterial({ color: 0xFF1744 }),
  glowGreen: new THREE.MeshBasicMaterial({ color: 0x00FF88 }),
};

// ============================================================================
// 1. TWIN-SPIRE GATEWAY TOWER (DUAL HEXAGONAL SPIRES WITH CROSS-SKYBRIDGE)
// ============================================================================
export function buildTwinSpireTower(opts = {}) {
  const root = new THREE.Group();
  root.name = 'TwinSpireGatewayTower';
  const h = opts.height || 58;
  const w = opts.width || 22;

  const spireW = w * 0.38;
  const gap = w * 0.24;

  const matHighriseWindow = new THREE.MeshStandardMaterial({
    map: Textures.denseHighriseFacade(),
    roughness: 0.35,
    metalness: 0.4,
  });

  // Left & Right Spires
  [-gap / 2 - spireW / 2, gap / 2 + spireW / 2].forEach((x, sIdx) => {
    // Main Hexagonal Column
    const shaft = createBeveledBox(spireW, h * 0.85, spireW, 0.15, 2, MATS.steelAlloy);
    shaft.position.set(x, (h * 0.85) / 2, 0);
    root.add(shaft);

    // High-Density Window Facade Panels on front and back
    [-spireW / 2 - 0.05, spireW / 2 + 0.05].forEach((fz, fIdx) => {
      const facade = new THREE.Mesh(new THREE.PlaneGeometry(spireW * 0.88, h * 0.8), matHighriseWindow);
      facade.position.set(x, (h * 0.85) / 2, fz);
      if (fIdx === 0) facade.rotation.y = Math.PI;
      root.add(facade);
    });

    // Vertical slim cyan corner edge lights (delicate pinstripes)
    [-spireW / 2, spireW / 2].forEach(cx => {
      const edge = new THREE.Mesh(new THREE.BoxGeometry(0.08, h * 0.85, 0.08), MATS.glowCyan);
      edge.position.set(x + cx, (h * 0.85) / 2, spireW / 2);
      root.add(edge);
    });

    // Spire Needle Crown
    const needle = new THREE.Mesh(new THREE.ConeGeometry(spireW * 0.45, h * 0.25, 6), MATS.lightPlate);
    needle.position.set(x, h * 0.85 + (h * 0.25) / 2, 0);
    root.add(needle);

    // Tip aviation warning beacon
    const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.35, 8, 8), MATS.glowRed);
    beacon.position.set(x, h * 0.98 + (h * 0.25) / 2, 0);
    root.add(beacon);
  });

  // Cross-Skybridge Arch connecting spires at 68% height
  const bridge = createBeveledBox(w + 1.0, 3.4, spireW * 0.75, 0.08, 1, MATS.darkConcrete);
  bridge.position.set(0, h * 0.65, 0);
  root.add(bridge);

  const bridgeGlass = new THREE.Mesh(new THREE.BoxGeometry(w * 0.85, 1.8, spireW * 0.78), MATS.glassCyan);
  bridgeGlass.position.set(0, h * 0.65, 0);
  root.add(bridgeGlass);

  // Ground Atrium Base with illuminated lobby
  const base = createBeveledBox(w + 4, 6.0, spireW + 4, 0.2, 2, MATS.darkConcrete);
  base.position.set(0, 3.0, 0);
  root.add(base);

  const lobbyGlass = new THREE.Mesh(new THREE.BoxGeometry(w + 2, 4.0, spireW + 4.2), MATS.glassCyan);
  lobbyGlass.position.set(0, 3.0, 0);
  root.add(lobbyGlass);

  return root;
}

// ============================================================================
// 2. CANTILEVERED TETRIS MIDRISE (STACKED OFFSET BLOCKS)
// ============================================================================
export function buildTetrisMidrise(opts = {}) {
  const root = new THREE.Group();
  root.name = 'TetrisMidrise';
  const tiers = opts.tiers || 6;
  const blockSize = opts.blockSize || 7.0;

  const matComm = new THREE.MeshStandardMaterial({
    map: Textures.commercialFacade(),
    roughness: 0.4,
    metalness: 0.35,
  });

  for (let i = 0; i < tiers; i++) {
    const y = i * (blockSize * 0.85) + (blockSize * 0.85) / 2;
    // Alternate cantilever shifts in X and Z
    const shiftX = (i % 2 === 0 ? 1 : -1) * (i * 0.85);
    const shiftZ = ((i + 1) % 2 === 0 ? 1 : -1) * (i * 0.65);

    const block = createBeveledBox(blockSize, blockSize * 0.8, blockSize, 0.1, 2, MATS.steelAlloy);
    block.position.set(shiftX, y, shiftZ);
    root.add(block);

    // Front & Side Window arrays
    const facadeF = new THREE.Mesh(new THREE.PlaneGeometry(blockSize * 0.88, blockSize * 0.7), matComm);
    facadeF.position.set(shiftX, y, shiftZ + blockSize / 2 + 0.02);
    root.add(facadeF);

    const facadeS = new THREE.Mesh(new THREE.PlaneGeometry(blockSize * 0.88, blockSize * 0.7), matComm);
    facadeS.position.set(shiftX + blockSize / 2 + 0.02, y, shiftZ);
    facadeS.rotation.y = Math.PI / 2;
    root.add(facadeS);

    // Under-cantilever cyan downlight
    if (i > 0) {
      const downLight = new THREE.Mesh(new THREE.BoxGeometry(1.8, 0.08, 1.8), MATS.glowCyan);
      downLight.position.set(shiftX, y - (blockSize * 0.4) - 0.04, shiftZ);
      root.add(downLight);
    }
  }

  // Rooftop Comms Array on highest block
  const topY = tiers * (blockSize * 0.85);
  const topX = ((tiers - 1) % 2 === 0 ? 1 : -1) * ((tiers - 1) * 0.85);
  const topZ = ((tiers) % 2 === 0 ? 1 : -1) * ((tiers - 1) * 0.65);

  const mast = new THREE.Mesh(new THREE.CylinderGeometry(0.1, 0.2, 5.0, 8), MATS.steelAlloy);
  mast.position.set(topX, topY + 2.5, topZ);
  root.add(mast);

  const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.25, 8, 8), MATS.glowAmber);
  beacon.position.set(topX, topY + 5.1, topZ);
  root.add(beacon);

  return root;
}

// ============================================================================
// 3. HEXAGONAL DATA-SILO (BRUTALIST SERVER MONOLITH)
// ============================================================================
export function buildHexDataSilo(opts = {}) {
  const root = new THREE.Group();
  root.name = 'HexDataSilo';
  const h = opts.height || 46;
  const radius = opts.radius || 8.0;

  // Hexagonal Prism Main Body
  const hexGeo = new THREE.CylinderGeometry(radius, radius * 1.08, h, 6);
  const hexBody = new THREE.Mesh(hexGeo, MATS.darkConcrete);
  hexBody.position.set(0, h / 2, 0);
  root.add(hexBody);

  // Vertical Heat Sink Cooling Fins running up the 6 corners
  for (let a = 0; a < 6; a++) {
    const angle = (a * Math.PI) / 3;
    const fx = Math.cos(angle) * (radius * 1.05);
    const fz = Math.sin(angle) * (radius * 1.05);
    const fin = createBeveledBox(0.4, h * 0.9, 1.8, 0.03, 1, MATS.steelAlloy);
    fin.position.set(fx, h / 2, fz);
    fin.rotation.y = angle;
    root.add(fin);
  }

  // Recessed Glowing Server Light Racks (Magenta & Cyan)
  for (let r = 0; r < 5; r++) {
    const ry = (h * 0.15) + r * (h * 0.18);
    const rackBand = new THREE.Mesh(
      new THREE.CylinderGeometry(radius + 0.04, radius + 0.04, 1.2, 6),
      r % 2 === 0 ? MATS.glowCyan : MATS.glowMagenta
    );
    rackBand.position.set(0, ry, 0);
    root.add(rackBand);
  }

  // Heavy Machinery Rooftop Deck & Microwave Radar
  const roofDome = new THREE.Mesh(new THREE.SphereGeometry(radius * 0.65, 12, 8, 0, Math.PI * 2, 0, Math.PI / 2), MATS.steelAlloy);
  roofDome.position.set(0, h, 0);
  root.add(roofDome);

  const radarMast = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.2, 4.5, 8), MATS.steelAlloy);
  radarMast.position.set(0, h + 2.2, 0);
  root.add(radarMast);

  const radarDish = new THREE.Mesh(new THREE.ConeGeometry(1.6, 0.6, 12, 1, true), MATS.steelAlloy);
  radarDish.rotation.x = Math.PI / 3;
  radarDish.position.set(0, h + 4.0, 0.6);
  root.add(radarDish);

  return root;
}

// ============================================================================
// 4. SLOPED WEDGE SKY-BLADE (AERODYNAMIC ANGLED SKYSCRAPER)
// ============================================================================
export function buildWedgeSkyBlade(opts = {}) {
  const root = new THREE.Group();
  root.name = 'WedgeSkyBlade';
  const h = opts.height || 54;
  const w = opts.width || 14;
  const d = opts.depth || 18;

  // Extruded Right-Angle Wedge Shape
  const shape = new THREE.Shape();
  shape.moveTo(-d / 2, 0);
  shape.lineTo(d / 2, 0);
  shape.lineTo(d / 2, h * 0.4);
  shape.lineTo(-d / 2, h);
  shape.closePath();

  const geom = new THREE.ExtrudeGeometry(shape, {
    depth: w,
    bevelEnabled: true,
    bevelThickness: 0.12,
    bevelSize: 0.12,
    bevelSegments: 2
  });
  geom.center();

  const wedgeMesh = new THREE.Mesh(geom, MATS.steelAlloy);
  wedgeMesh.position.set(0, h / 2, 0);
  wedgeMesh.rotateY(Math.PI / 2);
  root.add(wedgeMesh);

  // Sloping Window Strips along the diagonal roof
  for (let s = 1; s <= 4; s++) {
    const sw = new THREE.Mesh(new THREE.BoxGeometry(w * 0.8, 1.2, 0.15), MATS.glassCyan);
    const t = s / 5.0;
    const sy = (h * 0.4) + t * (h * 0.6);
    const sz = (d / 2) - t * d;
    sw.position.set(0, sy, sz);
    sw.rotation.x = -0.55;
    root.add(sw);
  }

  // Glowing Front Blade Edge Light (Cyan Knife-Edge)
  const edgeLight = new THREE.Mesh(new THREE.BoxGeometry(0.12, h * 0.85, 0.12), MATS.glowCyan);
  edgeLight.position.set(0, h / 2 + 2, d / 2 + 0.1);
  root.add(edgeLight);

  // Diagonal Side Structural Trusses
  [-w / 2 - 0.1, w / 2 + 0.1].forEach(x => {
    const truss = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.18, h * 0.9, 8), MATS.darkConcrete);
    truss.rotation.x = 0.35;
    truss.position.set(x, h / 2, 0);
    root.add(truss);
  });

  // Rooftop Angled Landing Helipad
  const pad = createBeveledBox(w * 0.75, 0.4, w * 0.75, 0.05, 1, MATS.darkConcrete);
  pad.position.set(0, h * 0.92, -d * 0.2);
  root.add(pad);

  const padRing = new THREE.Mesh(new THREE.RingGeometry(2.0, 2.3, 16), MATS.glowAmber);
  padRing.rotation.x = -Math.PI / 2;
  padRing.position.set(0, h * 0.92 + 0.22, -d * 0.2);
  root.add(padRing);

  return root;
}

// ============================================================================
// 5. CYLINDRICAL NEO-ROTUNDA TOWER (TIERED CONCENTRIC RINGS)
// ============================================================================
export function buildRotundaTower(opts = {}) {
  const root = new THREE.Group();
  root.name = 'RotundaTower';
  const tiers = opts.tiers || 4;
  const baseRadius = opts.radius || 11.0;
  const tierHeight = opts.tierHeight || 9.5;

  for (let i = 0; i < tiers; i++) {
    const r = baseRadius * (1.0 - i * 0.16);
    const y = i * tierHeight + tierHeight / 2;

    // Cylindrical Tier Body
    const cyl = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.95, r, tierHeight, 24), MATS.darkConcrete);
    cyl.position.set(0, y, 0);
    root.add(cyl);

    // Cantilevered Observation Ring Balcony
    const ring = new THREE.Mesh(new THREE.CylinderGeometry(r + 1.2, r + 1.2, 0.35, 24), MATS.steelAlloy);
    ring.position.set(0, y + tierHeight / 2 - 0.2, 0);
    root.add(ring);

    // Glowing Neon Ring Edge Light (delicate torus)
    const neonRing = new THREE.Mesh(new THREE.TorusGeometry(r + 1.22, 0.06, 8, 24), i % 2 === 0 ? MATS.glowCyan : MATS.glowAmber);
    neonRing.rotation.x = Math.PI / 2;
    neonRing.position.set(0, y + tierHeight / 2 - 0.2, 0);
    root.add(neonRing);

    // Wrap-around panoramic glass strip
    const glassStrip = new THREE.Mesh(new THREE.CylinderGeometry(r * 0.96, r * 0.96, tierHeight * 0.45, 24, 1, true), MATS.glassCyan);
    glassStrip.position.set(0, y, 0);
    root.add(glassStrip);

    // Vertical structural window mullions (12 pillars per tier)
    for (let m = 0; m < 12; m++) {
      const ma = (m * Math.PI * 2) / 12;
      const mx = Math.cos(ma) * (r * 0.97);
      const mz = Math.sin(ma) * (r * 0.97);
      const mullion = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, tierHeight * 0.48, 6), MATS.steelAlloy);
      mullion.position.set(mx, y, mz);
      root.add(mullion);
    }
  }

  // Crown Dome & Needle
  const totalH = tiers * tierHeight;
  const crownDome = new THREE.Mesh(new THREE.SphereGeometry(baseRadius * 0.4, 16, 12, 0, Math.PI * 2, 0, Math.PI / 2), MATS.lightPlate);
  crownDome.position.set(0, totalH, 0);
  root.add(crownDome);

  const crownNeedle = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.25, 7.0, 8), MATS.steelAlloy);
  crownNeedle.position.set(0, totalH + 3.5, 0);
  root.add(crownNeedle);

  const tipBeacon = new THREE.Mesh(new THREE.SphereGeometry(0.3, 8, 8), MATS.glowCyan);
  tipBeacon.position.set(0, totalH + 7.1, 0);
  root.add(tipBeacon);

  return root;
}

// ============================================================================
// 6. COMPACT CYBER-SHOPHOUSE / CORNER BODEGA BLOCK (LOW-RISE STREET LIFE)
// ============================================================================
export function buildCornerShophouse(opts = {}) {
  const root = new THREE.Group();
  root.name = 'CyberShophouse';
  const w = opts.width || 12;
  const h = opts.height || 14;
  const d = opts.depth || 11;
  const shopType = opts.shopType !== undefined ? opts.shopType : 0;

  // Ground Floor Bodega / Ramen Shop Body
  const groundFloor = createBeveledBox(w, 4.5, d, 0.08, 2, MATS.darkConcrete);
  groundFloor.position.set(0, 2.25, 0);
  root.add(groundFloor);

  // Upper Living Quarters (Stories 2-3) Body
  const upperBody = createBeveledBox(w - 0.2, h - 4.5, d - 0.2, 0.08, 2, MATS.steelAlloy);
  upperBody.position.set(0, 4.5 + (h - 4.5) / 2, 0);
  root.add(upperBody);

  // High-Resolution Front Facade (Shop signage, roll-up shutter, multi-floor windows)
  const matBodega = new THREE.MeshStandardMaterial({
    map: Textures.streetBodegaFacade(shopType),
    roughness: 0.45,
    metalness: 0.3,
  });
  const frontFacade = new THREE.Mesh(new THREE.PlaneGeometry(w * 0.94, h * 0.96), matBodega);
  frontFacade.position.set(0, h * 0.48, d / 2 + 0.05);
  root.add(frontFacade);

  // Glowing Projected Neon Shop Awning (Amber / Magenta / Cyan)
  const awningColor = shopType === 0 ? MATS.glowRed : shopType === 1 ? MATS.glowCyan : shopType === 2 ? MATS.glowGreen : MATS.glowAmber;
  const awning = createBeveledBox(w * 0.88, 0.25, 1.8, 0.02, 1, awningColor);
  awning.rotation.x = 0.22;
  awning.position.set(0, 4.2, d / 2 + 0.9);
  root.add(awning);

  // Projected Blade Neon Sign perpendicular to street
  const bladeSignMat = new THREE.MeshBasicMaterial({ color: shopType === 0 ? 0xFF0055 : shopType === 1 ? 0x00F0FF : 0xFBBF24 });
  const bladeSign = createBeveledBox(0.12, 3.2, 1.6, 0.02, 1, bladeSignMat);
  bladeSign.position.set(-w / 2 - 0.1, 8.5, d / 2 - 1.2);
  root.add(bladeSign);

  // Side Wall Window Array (Warm Pod Windows)
  const matPodWin = new THREE.MeshStandardMaterial({ map: Textures.podWindows('#1E293B'), roughness: 0.5 });
  const sideWin = new THREE.Mesh(new THREE.PlaneGeometry(d * 0.7, 4.0), matPodWin);
  sideWin.position.set(w / 2 + 0.02, 8.8, 0);
  sideWin.rotation.y = Math.PI / 2;
  root.add(sideWin);

  // Exterior AC Compressor Unit with Louvers on side
  const matAc = new THREE.MeshStandardMaterial({ map: Textures.acLouvers(), roughness: 0.6 });
  const acBox = createBeveledBox(1.4, 1.0, 0.7, 0.02, 1, matAc);
  acBox.position.set(w / 2 + 0.38, 6.8, d * 0.2);
  root.add(acBox);

  // Exterior Fire Escape Metal Ladder / Gantry
  const ladder = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, h - 3, 6), MATS.steelAlloy);
  ladder.position.set(-w / 2 - 0.2, (h + 3) / 2, 0);
  root.add(ladder);

  // Rooftop Water Tank with Hazard Band & Studs
  const tank = new THREE.Mesh(new THREE.CylinderGeometry(1.4, 1.4, 3.0, 14), MATS.steelAlloy);
  tank.position.set(-w * 0.25, h + 1.5, -d * 0.2);
  root.add(tank);

  const tankHazard = new THREE.Mesh(new THREE.CylinderGeometry(1.42, 1.42, 0.4, 14), MATS.glowAmber);
  tankHazard.position.set(-w * 0.25, h + 1.5, -d * 0.2);
  root.add(tankHazard);

  // Rooftop Satellite Dish & Antenna Mast
  const dish = new THREE.Mesh(new THREE.ConeGeometry(1.2, 0.5, 12, 1, true), MATS.lightPlate);
  dish.rotation.x = Math.PI / 3;
  dish.position.set(w * 0.28, h + 1.6, -d * 0.15);
  root.add(dish);

  const ant = new THREE.Mesh(new THREE.CylinderGeometry(0.06, 0.1, 4.0, 6), MATS.steelAlloy);
  ant.position.set(w * 0.28, h + 2.0, d * 0.2);
  root.add(ant);

  const antGlow = new THREE.Mesh(new THREE.SphereGeometry(0.18, 8, 8), MATS.glowRed);
  antGlow.position.set(w * 0.28, h + 4.1, d * 0.2);
  root.add(antGlow);

  // Authentic Roblox Studs on Roof Parapet
  for (let sx = -w * 0.42; sx <= w * 0.42; sx += 1.6) {
    const stud = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.14, 0.08, 8), MATS.darkConcrete);
    stud.position.set(sx, h + 0.05, d / 2 - 0.35);
    root.add(stud);
  }

  return root;
}

// ============================================================================
// 7. STEPPED TERRACED APARTMENT BLOCK (ZIGGURAT RESIDENTIAL)
// ============================================================================
export function buildTerraceApartment(opts = {}) {
  const root = new THREE.Group();
  root.name = 'TerraceApartment';
  const steps = opts.steps || 4;
  const baseW = opts.width || 20;
  const stepH = opts.stepHeight || 6.0;
  const baseD = opts.depth || 16;

  const matPodWin = new THREE.MeshStandardMaterial({
    map: Textures.podWindows('#0F172A'),
    roughness: 0.4,
  });

  const matSolar = new THREE.MeshStandardMaterial({
    map: Textures.solarPanel(),
    roughness: 0.2,
    metalness: 0.7,
  });

  for (let s = 0; s < steps; s++) {
    const sw = baseW * (1.0 - s * 0.18);
    const sd = baseD * (1.0 - s * 0.18);
    const sy = s * stepH + stepH / 2;

    const block = createBeveledBox(sw, stepH, sd, 0.1, 2, s % 2 === 0 ? MATS.cyberTeal : MATS.steelAlloy);
    block.position.set(0, sy, -s * (baseD * 0.08));
    root.add(block);

    // Front window array
    const winMesh = new THREE.Mesh(new THREE.PlaneGeometry(sw * 0.85, stepH * 0.65), matPodWin);
    winMesh.position.set(0, sy, -s * (baseD * 0.08) + sd / 2 + 0.02);
    root.add(winMesh);

    // Stepped Terrace Rooftop Balcony with high-tech blue solar panels
    const solarBalcony = new THREE.Mesh(new THREE.PlaneGeometry(sw * 0.85, sd * 0.35), matSolar);
    solarBalcony.rotation.x = -Math.PI / 2;
    solarBalcony.position.set(0, sy + stepH / 2 + 0.02, -s * (baseD * 0.08) + sd * 0.28);
    root.add(solarBalcony);

    // Terrace Safety Railing with delicate amber edge light
    const rail = createBeveledBox(sw * 0.88, 0.5, 0.06, 0.01, 1, MATS.glowAmber);
    rail.position.set(0, sy + stepH / 2 + 0.28, -s * (baseD * 0.08) + sd * 0.46);
    root.add(rail);
  }

  return root;
}

// ============================================================================
// 8. INDUSTRIAL POWER SUBSTATION & CONDUIT GANTRY
// ============================================================================
export function buildIndustrialSubstation(opts = {}) {
  const root = new THREE.Group();
  root.name = 'IndustrialSubstation';
  const w = opts.width || 16;
  const h = opts.height || 18;

  // Steel Foundation Slab
  const foundation = createBeveledBox(w, 1.2, 12, 0.08, 1, MATS.darkConcrete);
  foundation.position.set(0, 0.6, 0);
  root.add(foundation);

  // Twin High-Voltage Transformers
  [-4.2, 4.2].forEach(x => {
    const xfmr = createBeveledBox(5.2, 4.8, 5.2, 0.1, 2, MATS.steelAlloy);
    xfmr.position.set(x, 3.6, 0);
    root.add(xfmr);

    // Ceramic Insulator Bushings (3 per transformer)
    [-1.6, 0, 1.6].forEach(bz => {
      const bushing = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.45, 1.8, 8), MATS.terracotta);
      bushing.position.set(x, 6.8, bz);
      root.add(bushing);

      const sparkGlow = new THREE.Mesh(new THREE.SphereGeometry(0.18, 8, 8), MATS.glowCyan);
      sparkGlow.position.set(x, 7.8, bz);
      root.add(sparkGlow);
    });
  });

  // Steel Lattice Overhead Gantry Arch
  const gantryBar = createBeveledBox(w + 2, 0.8, 0.8, 0.04, 1, MATS.steelAlloy);
  gantryBar.position.set(0, h, 0);
  root.add(gantryBar);

  [-w / 2, w / 2].forEach(lx => {
    const col = new THREE.Mesh(new THREE.CylinderGeometry(0.35, 0.45, h, 8), MATS.steelAlloy);
    col.position.set(lx, h / 2, 0);
    root.add(col);
  });

  // High-Voltage Illuminated Power Conduits
  [-3.0, 0, 3.0].forEach(cx => {
    const cable = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.08, 14), MATS.glowCyan);
    cable.position.set(cx, h - 0.5, 0);
    root.add(cable);
  });

  return root;
}

// ============================================================================
// THE GLITCH MARKET — EPISODE 1: "THE SHADOW'S AWAKENING"
// SHOT 1: AETHELGARD METROPOLIS SKYLINE — COMPLETE 3D SCENE ASSEMBLY
//
// Key Architectural Feats:
// 1. Cyber Celestial Skybox Dome (Nebula wisps, Data Moon & Starfield)
// 2. Real 3D Ground Streetscape (Multi-lane asphalt avenue, raised sidewalks, street lamps)
// 3. Lower-Tier Street Shophouses (8+ distinct Bodegas, Ramen Bars, Cyber-Shops, Substations)
// 4. Mid-Tier Architectural Canyon (Tetris Midrises, Terraces, Wedge Sky-Blades, Rotundas)
// 5. High-Rise Gateway Spires (Twin Spires, Hex Data Silos, Pod Stacks, Stepped Spire)
// 6. Deep Sovereign Apex Citadel (Dominant boss tower with floating sky-islands)
// 7. Architectural Sky-Bridges (Truss frames angled to frame the Citadel)
// 8. Elevated Transit (Skyway 101 Expressway + High-Speed Maglev Sky-Train)
// 9. Air Traffic (16+ Flying Speeders, Commuter Taxis, Heavy Cargo Barges)
// 10. Dynamic Foreground Speeder (Banking into turn with glowing ion trails)
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createBeveledBox, chamferBox, Textures } from './core/geo.js';

// Import All 8 Core Hero Assets
import { buildNeonSpeeder } from './speeder.js';
import { buildApexTower } from './apex_tower.js';
import { buildSkyTaxi } from './taxi.js';
import { buildCargoBarge } from './cargo_barge.js';
import { buildSkyTrain } from './sky_train.js';
import { buildSteppedTower } from './stepped_tower.js';
import { buildPodHighrise } from './pod_highrise.js';
import { buildSkyHighway } from './sky_highway.js';

// Import 8 Brand-New Modular Building Archetypes
import {
  buildTwinSpireTower,
  buildTetrisMidrise,
  buildHexDataSilo,
  buildWedgeSkyBlade,
  buildRotundaTower,
  buildCornerShophouse,
  buildTerraceApartment,
  buildIndustrialSubstation,
} from './buildings.js';

export function buildMetropolisSkyline() {
  const city = new THREE.Group();
  city.name = 'AethelgardMetropolisSkyline';

  // --------------------------------------------------------------------------
  // 1. GRAND CYBER SKY BACKDROP DOME (NEBULA, DATA MOON & STARFIELD)
  // --------------------------------------------------------------------------
  const skyGeo = new THREE.CylinderGeometry(550, 550, 480, 48, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 130, -180);
  city.add(skyDome);

  // --------------------------------------------------------------------------
  // 2. REAL 3D GROUND STREETSCAPE (AVENUES, SIDEWALKS & STREET LAMPS)
  // --------------------------------------------------------------------------
  // Dark Metropolitan Asphalt Bedrock
  const matStreetAsphalt = new THREE.MeshStandardMaterial({
    color: 0x080B14,
    roughness: 0.85,
    metalness: 0.15
  });
  const streetFloor = createBeveledBox(500, 3.0, 500, 0.2, 1, matStreetAsphalt);
  streetFloor.position.set(0, -1.5, -160);
  city.add(streetFloor);

  // Central 4-Lane Paved Avenue with glowing road lines
  const matRoad = new THREE.MeshStandardMaterial({
    map: Textures.highwayRoadSurface(),
    roughness: 0.7,
    metalness: 0.2
  });
  const roadSurface = new THREE.Mesh(new THREE.PlaneGeometry(16, 320), matRoad);
  roadSurface.rotation.x = -Math.PI / 2;
  roadSurface.position.set(0, 0.05, -150);
  city.add(roadSurface);

  // Raised Sidewalks on Left and Right with beveled granite curbs
  const matCurb = new THREE.MeshStandardMaterial({ color: 0x1E2638, roughness: 0.6 });
  [-14.5, 14.5].forEach(sx => {
    const sidewalk = createBeveledBox(11, 0.5, 320, 0.06, 1, matCurb);
    sidewalk.position.set(sx, 0.25, -150);
    city.add(sidewalk);
  });

  // Cyber Street Lamps along Sidewalks
  for (let lz = -20; lz >= -260; lz -= 32) {
    [-9.5, 9.5].forEach(lx => {
      const lampPost = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.12, 5.5, 8), matCurb);
      lampPost.position.set(lx, 2.75, lz);
      city.add(lampPost);

      const lampHead = createBeveledBox(0.8, 0.2, 1.2, 0.02, 1, matCurb);
      lampHead.position.set(lx + (lx > 0 ? -0.4 : 0.4), 5.4, lz);
      city.add(lampHead);

      const lampGlow = new THREE.Mesh(
        new THREE.BoxGeometry(0.6, 0.05, 1.0),
        new THREE.MeshBasicMaterial({ color: lx > 0 ? 0x00F0FF : 0xFBBF24 })
      );
      lampGlow.position.set(lx + (lx > 0 ? -0.4 : 0.4), 5.3, lz);
      city.add(lampGlow);
    });
  }

  // --------------------------------------------------------------------------
  // 3. LOWER-TIER STREET SHOPHOUSES (BODEGAS, RAMEN BARS, SUBSTATIONS)
  // Richly detailed with neon signs, roll-up doors, AC units, roof water tanks
  // --------------------------------------------------------------------------
  // Left Street Frontage (X = -20)
  const leftStreetBlocks = [
    { type: 'shop', shopType: 0, z: -35, rot: 0.08, s: 1.0 }, // Ramen 2077
    { type: 'shop', shopType: 1, z: -52, rot: -0.05, s: 1.05 }, // Cyber-Chip
    { type: 'sub', z: -72, rot: 0.25, s: 0.95 }, // Power Substation
    { type: 'shop', shopType: 2, z: -94, rot: 0.02, s: 1.0 }, // Glitch Mart
    { type: 'shop', shopType: 3, z: -115, rot: -0.1, s: 1.1 }, // UGC Blades
    { type: 'shop', shopType: 0, z: -136, rot: 0.06, s: 1.0 }, // Ramen 2077
  ];

  leftStreetBlocks.forEach(b => {
    let m;
    if (b.type === 'shop') {
      m = buildCornerShophouse({ shopType: b.shopType });
    } else {
      m = buildIndustrialSubstation({ width: 14, height: 16 });
    }
    m.scale.set(b.s, b.s, b.s);
    m.position.set(-21.0, 0, b.z);
    m.rotation.y = b.rot;
    city.add(m);
  });

  // Right Street Frontage (X = +20)
  const rightStreetBlocks = [
    { type: 'shop', shopType: 1, z: -38, rot: -0.1, s: 1.0 }, // Cyber-Chip
    { type: 'shop', shopType: 0, z: -56, rot: 0.05, s: 1.05 }, // Ramen 2077
    { type: 'shop', shopType: 3, z: -78, rot: -0.08, s: 1.0 }, // UGC Blades
    { type: 'sub', z: -100, rot: -0.22, s: 1.0 }, // Power Substation
    { type: 'shop', shopType: 2, z: -124, rot: 0.04, s: 1.1 }, // Glitch Mart
    { type: 'shop', shopType: 1, z: -145, rot: -0.05, s: 1.0 }, // Cyber-Chip
  ];

  rightStreetBlocks.forEach(b => {
    let m;
    if (b.type === 'shop') {
      m = buildCornerShophouse({ shopType: b.shopType });
    } else {
      m = buildIndustrialSubstation({ width: 14, height: 16 });
    }
    m.scale.set(b.s, b.s, b.s);
    m.position.set(21.0, 0, b.z);
    m.rotation.y = b.rot;
    city.add(m);
  });

  // --------------------------------------------------------------------------
  // 4. MID-TIER ARCHITECTURAL CANYON (TETRIS, WEDGES, TERRACES & ROTUNDAS)
  // Stepped up behind the street blocks creating natural urban depth
  // --------------------------------------------------------------------------
  // Model 2: Cantilevered Tetris Midrise (Left Near-Midground: X = -38, Z = -62)
  const tetris1 = buildTetrisMidrise({ tiers: 7, blockSize: 6.8 });
  tetris1.position.set(-38, 0, -62);
  tetris1.rotation.y = 0.25;
  city.add(tetris1);

  // Model 4: Sloped Wedge Sky-Blade (Left Midground: X = -48, Z = -100)
  const blade1 = buildWedgeSkyBlade({ height: 58, width: 15, depth: 20 });
  blade1.position.set(-48, 0, -100);
  blade1.rotation.y = 0.35;
  city.add(blade1);

  // Model 7: Stepped Terraced Apartment (Left Mid-to-Deep: X = -40, Z = -140)
  const terrace1 = buildTerraceApartment({ steps: 5, width: 22, depth: 18, stepHeight: 5.5 });
  terrace1.position.set(-40, 0, -140);
  terrace1.rotation.y = -0.15;
  city.add(terrace1);

  // Model 5: Cylindrical Neo-Rotunda Tower (Left Deep-Mid: X = -54, Z = -175)
  const rotunda1 = buildRotundaTower({ tiers: 5, radius: 9.5, tierHeight: 8.5 });
  rotunda1.position.set(-54, 0, -175);
  rotunda1.rotation.y = -0.4;
  city.add(rotunda1);

  // Right Side Mid-Tier Buildings
  // Core Asset: Residential Pod Highrise (Right Foreground Flank: X = +30, Z = -45)
  const podStack1 = buildPodHighrise();
  podStack1.scale.set(0.95, 0.95, 0.95);
  podStack1.position.set(30, 0, -45);
  podStack1.rotation.y = -0.35;
  city.add(podStack1);

  // Model 7: Stepped Terraced Apartment (Right Near-Midground: X = +40, Z = -72)
  const terrace2 = buildTerraceApartment({ steps: 4, width: 18, depth: 15, stepHeight: 5.8 });
  terrace2.position.set(40, 0, -72);
  terrace2.rotation.y = 0.4;
  city.add(terrace2);

  // Model 4: Sloped Wedge Sky-Blade (Right Midground: X = +46, Z = -110)
  const blade2 = buildWedgeSkyBlade({ height: 52, width: 14, depth: 18 });
  blade2.position.set(46, 0, -110);
  blade2.rotation.y = -0.55;
  city.add(blade2);

  // Model 2: Cantilevered Tetris Midrise (Right Mid-to-Deep: X = +40, Z = -148)
  const tetris2 = buildTetrisMidrise({ tiers: 8, blockSize: 6.2 });
  tetris2.scale.set(0.9, 0.9, 0.9);
  tetris2.position.set(40, 0, -148);
  tetris2.rotation.y = -0.35;
  city.add(tetris2);

  // Model 5: Cylindrical Neo-Rotunda Tower (Right Deep-Mid: X = +52, Z = -180)
  const rotunda2 = buildRotundaTower({ tiers: 4, radius: 10.5, tierHeight: 9.0 });
  rotunda2.position.set(52, 0, -180);
  rotunda2.rotation.y = 0.3;
  city.add(rotunda2);

  // --------------------------------------------------------------------------
  // 5. HIGH-RISE GATEWAY & CORE ASSETS (DEEP SKYLINE FLANKS)
  // --------------------------------------------------------------------------
  // Core Asset: Stepped Commercial Cyber-Tower (Left Focal Skyscraper: X = -32, Z = -165)
  const steppedComm1 = buildSteppedTower();
  steppedComm1.scale.set(1.15, 1.15, 1.15);
  steppedComm1.position.set(-32, 0, -165);
  steppedComm1.rotation.y = -0.2;
  city.add(steppedComm1);

  // Core Asset: Stepped Commercial Cyber-Tower (Right Focal Skyscraper: X = +34, Z = -175)
  const steppedComm2 = buildSteppedTower();
  steppedComm2.scale.set(1.1, 1.1, 1.1);
  steppedComm2.position.set(34, 0, -175);
  steppedComm2.rotation.y = 0.25;
  city.add(steppedComm2);

  // Model 1: Twin-Spire Gateway Tower (Left Skyline Anchor: X = -52, Z = -215)
  const twinSpire1 = buildTwinSpireTower({ height: 70, width: 26 });
  twinSpire1.position.set(-52, 0, -215);
  twinSpire1.rotation.y = 0.2;
  city.add(twinSpire1);

  // Model 1: Twin-Spire Gateway Tower (Right Skyline Anchor: X = +54, Z = -210)
  const twinSpire2 = buildTwinSpireTower({ height: 68, width: 24 });
  twinSpire2.position.set(54, 0, -210);
  twinSpire2.rotation.y = -0.25;
  city.add(twinSpire2);

  // Model 3: Hexagonal Data-Silo (Left Background: X = -25, Z = -230)
  const hexSilo1 = buildHexDataSilo({ height: 56, radius: 9.0 });
  hexSilo1.position.set(-25, 0, -230);
  city.add(hexSilo1);

  // Model 3: Hexagonal Data-Silo (Right Background: X = +28, Z = -235)
  const hexSilo2 = buildHexDataSilo({ height: 58, radius: 9.5 });
  hexSilo2.position.set(28, 0, -235);
  city.add(hexSilo2);

  // --------------------------------------------------------------------------
  // 6. DEEP BACKGROUND BOSS TOWER: SOVEREIGN APEX CITADEL
  // Fully visible and towering into the celestial nebula sky
  // --------------------------------------------------------------------------
  const apexTower = buildApexTower();
  apexTower.scale.set(1.75, 1.75, 1.75);
  apexTower.position.set(0, 0, -250);
  city.add(apexTower);

  // --------------------------------------------------------------------------
  // 7. ARCHITECTURAL SKY-BRIDGES (ANGLED TO FRAME CITADEL)
  // Re-engineered with steel truss frames & delicate edge lights
  // --------------------------------------------------------------------------
  const matBridgeSteel = new THREE.MeshStandardMaterial({ color: 0x1E293B, roughness: 0.5, metalness: 0.5 });
  const matBridgeGlass = new THREE.MeshStandardMaterial({ color: 0x00F0FF, roughness: 0.1, transparent: true, opacity: 0.65 });
  const matBridgeGlow = new THREE.MeshBasicMaterial({ color: 0x00F0FF });

  function addSkyBridge(fromXYZ, toXYZ) {
    const vFrom = new THREE.Vector3(...fromXYZ);
    const vTo = new THREE.Vector3(...toXYZ);
    const len = vFrom.distanceTo(vTo);
    const mid = new THREE.Vector3().addVectors(vFrom, vTo).multiplyScalar(0.5);

    // Dark steel tube body
    const bridgeMesh = createBeveledBox(len, 2.6, 2.8, 0.06, 1, matBridgeSteel);
    bridgeMesh.position.copy(mid);
    bridgeMesh.lookAt(vTo);
    bridgeMesh.rotateY(Math.PI / 2);
    city.add(bridgeMesh);

    // Tinted window strip
    const glassMesh = new THREE.Mesh(new THREE.BoxGeometry(len - 0.6, 1.2, 2.85), matBridgeGlass);
    glassMesh.position.copy(mid);
    glassMesh.lookAt(vTo);
    glassMesh.rotateY(Math.PI / 2);
    city.add(glassMesh);

    // Top & Bottom delicate neon edge lines
    [-1.25, 1.25].forEach(ey => {
      const edge = new THREE.Mesh(new THREE.BoxGeometry(len, 0.08, 0.08), matBridgeGlow);
      edge.position.set(mid.x, mid.y + ey, mid.z);
      edge.lookAt(new THREE.Vector3(vTo.x, vTo.y + ey, vTo.z));
      edge.rotateY(Math.PI / 2);
      city.add(edge);
    });
  }

  // Angled skybridges connecting flanking towers without blocking Citadel
  addSkyBridge([-34, 26, -90], [-46, 24, -120]); // Left Flank Angled Bridge
  addSkyBridge([36, 28, -85], [44, 25, -115]); // Right Flank Angled Bridge
  addSkyBridge([-26, 38, -165], [28, 38, -175]); // High Horizon Skybridge (Y = 38m)
  addSkyBridge([-38, 20, -62], [-21, 14, -52]); // Street-to-Midrise Access Walkway

  // --------------------------------------------------------------------------
  // 8. ELEVATED TRANSIT: MAGLEV SKY-TRAIN & HIGHWAY 101
  // --------------------------------------------------------------------------
  // High-Speed Maglev Sky-Train traversing high monorail beam at Y = 36m
  const train1 = buildSkyTrain();
  train1.scale.set(0.9, 0.9, 0.9);
  train1.position.set(-2.0, 36.0, -145);
  train1.rotation.y = -0.10;
  city.add(train1);

  // Suspended Skyway 101 Expressway (Lower Arterial: Y = 14m, Z = -88)
  const highwaySection1 = buildSkyHighway();
  highwaySection1.scale.set(1.0, 1.0, 1.0);
  highwaySection1.position.set(0, 14.0, -88);
  highwaySection1.rotation.y = 0.22;
  city.add(highwaySection1);

  const highwaySection2 = buildSkyHighway();
  highwaySection2.scale.set(1.0, 1.0, 1.0);
  highwaySection2.position.set(-34.0, 14.0, -95.5);
  highwaySection2.rotation.y = 0.22;
  city.add(highwaySection2);

  // --------------------------------------------------------------------------
  // 9. HIGH-DENSITY AIR TRAFFIC (16+ VEHICLES IN TRANSIT)
  // --------------------------------------------------------------------------
  const trafficData = [
    ['barge', -14.0, 24.0, -105, -0.22, 0.65],
    ['barge', 28.0, 21.0, -135, 0.35, 0.60],
    ['taxi', -6.0, 26.0, -56, 0.18, 0.85],
    ['taxi', 22.0, 23.0, -88, -1.1, 0.75],
    ['taxi', 12.0, 31.0, -150, 0.35, 0.55],
    ['taxi', -22.0, 18.0, -75, 0.45, 0.70],
    ['taxi', 16.0, 17.0, -68, 0.2, 0.80],
    ['speeder', 4.0, 25.0, -72, 0.25, 0.75],
    ['speeder', -20.0, 29.0, -118, 0.55, 0.50],
    ['speeder', 14.0, 27.0, -98, -0.4, 0.65],
    ['speeder', -8.0, 20.0, -48, 0.15, 0.85],
    ['speeder', 30.0, 33.0, -138, -0.6, 0.55],
  ];

  trafficData.forEach(([type, x, y, z, rotY, s]) => {
    let veh;
    if (type === 'taxi') veh = buildSkyTaxi();
    else if (type === 'barge') veh = buildCargoBarge();
    else veh = buildNeonSpeeder();

    veh.scale.set(s, s, s);
    veh.position.set(x, y, z);
    veh.rotation.y = rotY;
    city.add(veh);
  });

  // --------------------------------------------------------------------------
  // 10. FOREGROUND HERO ELEMENT: CLOSE SPEEDER BANKING INTO TURN
  // --------------------------------------------------------------------------
  const heroSpeeder = buildNeonSpeeder();
  heroSpeeder.scale.set(1.15, 1.15, 1.15);
  heroSpeeder.position.set(-4.5, 16.5, -14.0);
  heroSpeeder.rotation.y = -0.25;
  heroSpeeder.rotation.z = 0.28;
  heroSpeeder.rotation.x = -0.10;
  city.add(heroSpeeder);

  // High-Energy Cyan Ion Jet Exhaust Plumes
  const matJetPlume = new THREE.MeshBasicMaterial({ color: 0x00F0FF, transparent: true, opacity: 0.9 });
  [-0.8, 0.8].forEach(tz => {
    const plume = new THREE.Mesh(new THREE.ConeGeometry(0.38, 3.2, 12), matJetPlume);
    plume.rotation.z = Math.PI / 2;
    plume.position.set(-6.2, 16.5 + tz * 0.15, -14.0 - 2.2 + tz * 0.35);
    city.add(plume);
  });

  return city;
}

