// ============================================================================
// THE GLITCH MARKET — AURA & CINEMATIC ATMOSPHERE VFX ENGINE
// Provides:
// 1. High-Speed Plasma Ion Light Trails & Speed Ribbons
// 2. Volumetric Headlight Beams & Underglow Halos
// 3. Floating Cyber Data Sparks & Ambient Embers
// 4. Rooftop Sky-Sweeping Searchlight Beams
// 5. Atmospheric Low-Altitude Street Fog Layers
// ============================================================================

import * as THREE from '../vendor/three.module.js';

// Reusable cached materials
const AURA_MATS = {
  cyanTrail: new THREE.MeshBasicMaterial({ color: 0x00F0FF, transparent: true, opacity: 0.85 }),
  amberTrail: new THREE.MeshBasicMaterial({ color: 0xF59E0B, transparent: true, opacity: 0.85 }),
  magentaTrail: new THREE.MeshBasicMaterial({ color: 0xEC4899, transparent: true, opacity: 0.85 }),
  headlightBeam: new THREE.MeshBasicMaterial({ color: 0xE0F2FE, transparent: true, opacity: 0.22, depthWrite: false }),
  amberBeam: new THREE.MeshBasicMaterial({ color: 0xFDE047, transparent: true, opacity: 0.24, depthWrite: false }),
  cyanSearchlight: new THREE.MeshBasicMaterial({ color: 0x00F0FF, transparent: true, opacity: 0.12, depthWrite: false }),
  purpleSearchlight: new THREE.MeshBasicMaterial({ color: 0xA855F7, transparent: true, opacity: 0.14, depthWrite: false }),
  streetFog: new THREE.MeshBasicMaterial({ color: 0x0A1628, transparent: true, opacity: 0.35, depthWrite: false }),
};

/**
 * Creates an aerodynamic glowing ion trail / speed ribbon behind a vehicle thruster.
 */
export function createIonRibbon(length = 8.0, width = 0.5, colorHex = 0x00F0FF, curvature = 0) {
  const geom = new THREE.PlaneGeometry(width, length, 1, 8);
  // Center at front and extend back
  geom.translate(0, length / 2, 0);

  const mat = new THREE.MeshBasicMaterial({
    color: colorHex,
    transparent: true,
    opacity: 0.82,
    side: THREE.DoubleSide,
    depthWrite: false
  });

  const mesh = new THREE.Mesh(geom, mat);
  mesh.rotation.x = Math.PI / 2;
  return mesh;
}

/**
 * Creates a soft volumetric vehicle headlight beam cone.
 */
export function createHeadlightBeam(length = 16.0, radius = 2.4, colorHex = 0xE0F2FE) {
  const geom = new THREE.ConeGeometry(radius, length, 16, 1, true);
  geom.translate(0, -length / 2, 0);
  geom.rotateX(Math.PI / 2);

  const mat = new THREE.MeshBasicMaterial({
    color: colorHex,
    transparent: true,
    opacity: 0.22,
    side: THREE.DoubleSide,
    depthWrite: false
  });

  return new THREE.Mesh(geom, mat);
}

/**
 * Creates sweeping vertical searchlights projecting from rooftops into the nebula.
 */
export function createRooftopSearchlight(height = 140, baseRadius = 1.0, topRadius = 9.0, colorHex = 0x00F0FF) {
  const geom = new THREE.CylinderGeometry(topRadius, baseRadius, height, 16, 1, true);
  geom.translate(0, height / 2, 0);

  const mat = new THREE.MeshBasicMaterial({
    color: colorHex,
    transparent: true,
    opacity: 0.13,
    side: THREE.DoubleSide,
    depthWrite: false
  });

  return new THREE.Mesh(geom, mat);
}

/**
 * Creates floating luminous cyber motes / data embers in the city canyon.
 */
export function createCyberEmbers(count = 350, bounds = { xMin: -45, xMax: 45, yMin: 4, yMax: 65, zMin: -220, zMax: -10 }) {
  const group = new THREE.Group();
  group.name = 'CyberEmbers';

  const emberGeo = new THREE.BoxGeometry(0.18, 0.18, 0.18);
  const cyanMat = new THREE.MeshBasicMaterial({ color: 0x00F0FF });
  const amberMat = new THREE.MeshBasicMaterial({ color: 0xF59E0B });
  const purpleMat = new THREE.MeshBasicMaterial({ color: 0xC084FC });

  for (let i = 0; i < count; i++) {
    const mat = (i % 3 === 0) ? cyanMat : (i % 3 === 1) ? amberMat : purpleMat;
    const ember = new THREE.Mesh(emberGeo, mat);
    ember.position.set(
      bounds.xMin + Math.random() * (bounds.xMax - bounds.xMin),
      bounds.yMin + Math.random() * (bounds.yMax - bounds.yMin),
      bounds.zMin + Math.random() * (bounds.zMax - bounds.zMin)
    );
    group.add(ember);
  }

  return group;
}

/**
 * Creates horizontal atmospheric street fog layers over the lower avenue.
 */
export function createStreetFogPlanes() {
  const group = new THREE.Group();
  group.name = 'StreetFog';

  const fogMat = new THREE.MeshBasicMaterial({
    color: 0x07152A,
    transparent: true,
    opacity: 0.28,
    depthWrite: false
  });

  for (let f = 0; f < 3; f++) {
    const plane = new THREE.Mesh(new THREE.PlaneGeometry(120, 260), fogMat);
    plane.rotation.x = -Math.PI / 2;
    plane.position.set(0, 1.8 + f * 1.6, -140);
    group.add(plane);
  }

  return group;
}

