// --------------------------------------------------------------------------
// 11. ATMOSPHERIC AURA: SEARCHLIGHTS, DIGITAL EMBERS & STREET FOG
// --------------------------------------------------------------------------
// Sweeping Sky-Searchlights from Spire Rooftops into the Nebula
const beamLeftSpire = createRooftopSearchlight(160, 1.2, 12, 0x00F0FF);
beamLeftSpire.position.set(-52, 60, -215);
