// ============================================================================
// THE GLITCH MARKET — EPISODE 1 // SHOT 1 CAMERA ANGLE SHOWCASE & AURA COMPOSITOR
// Produces:
// 1. shot1_keyframe_01.png (Angle 1: 1080x1920 Grand Canyon Drone Glide)
// 2. shot1_camera_angle_2_highdive.png (Angle 2: 1080x1920 High-Altitude Skyway Dive)
// 3. shot1_camera_angle_3_streetlookup.png (Angle 3: 1080x1920 Street-Level Bodega Look-Up)
// 4. shot1_camera_angle_4_chase.png (Angle 4: 1080x1920 Speeder Chase / Over-The-Shoulder)
// 5. shot1_camera_showcase.png (2560x1440 4-Up Comparative Master Production Showcase)
// 6. shot1_metropolis_master.png (2400x1350 Production Audit Sheet)
// ============================================================================

import * as THREE from 'three';
import { makeEngine } from './core/engine.js';
import { buildMetropolisSkyline } from './shot1_skyline.js';

function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Build the 3D Metropolis Scene with Aura VFX
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#030612');
  scene.fog = new THREE.FogExp2('#060B1C', 0.0015);

  // Directional High-Altitude Moon/City Key Light (Cool Ice White / Pale Cyan)
  const keyLight = new THREE.DirectionalLight('#DCEBFA', 2.4);
  keyLight.position.set(45, 85, -40);
  keyLight.target.position.set(0, 20, -110);
  scene.add(keyLight);
  scene.add(keyLight.target);

  // Intense Cyan Underbelly Void Rim Light
  const cyanRim = new THREE.DirectionalLight('#00F0FF', 2.6);
  cyanRim.position.set(-45, -5, -90);
  cyanRim.target.position.set(0, 22, -110);
  scene.add(cyanRim);
  scene.add(cyanRim.target);

  // Warm Amber Commercial Fill Light
  const amberFill = new THREE.DirectionalLight('#F59E0B', 1.0);
  amberFill.position.set(55, 55, -90);
  amberFill.target.position.set(0, 20, -110);
  scene.add(amberFill);
  scene.add(amberFill.target);

  // Ambient Sky/Ground Light
  const hemi = new THREE.HemisphereLight('#38BDF8', '#080F1E', 0.95);
  scene.add(hemi);

  // Build the complete multi-asset city with Aura effects
  const city = buildMetropolisSkyline();
  scene.add(city);

  // Helper function to render a 1080x1920 vertical pass
  function renderPass(cam, postOpts) {
    const c = document.createElement('canvas');
    c.width = 1080;
    c.height = 1920;
    const eng = makeEngine(c, { w: 1080, h: 1920, samples: 4, shadowSize: 2048 });
    eng.render(scene, cam, postOpts);
    return c;
  }

  // --------------------------------------------------------------------------
  // PASS 1: ANGLE 1 — "THE GRAND CANYON GLIDE" (MASTER OPENING SHOT)
  // --------------------------------------------------------------------------
  const cam1 = new THREE.PerspectiveCamera(58, 1080 / 1920, 0.1, 900);
  cam1.position.set(5.5, 27.0, 6.0);
  cam1.lookAt(new THREE.Vector3(-1.5, 22.0, -115.0));

  const canvas1 = renderPass(cam1, {
    bloom: 0.42,
    bloomThreshold: 1.12,
    bloomRadius: 0.55,
    exposure: 1.14,
    sat: 1.32,
    vignette: 0.16,
    focus: 30.0,
    aperture: 0.0001
  });
  const blob1 = await canvasToBlob(canvas1);
  await uploadImage('shot1_keyframe_01.png', blob1);
  await uploadImage('shot1_camera_angle_1_drone.png', blob1);
  console.log('SAVED: shot1_camera_angle_1_drone.png');

  // --------------------------------------------------------------------------
  // PASS 2: ANGLE 2 — "THE HIGH-ALTITUDE SKYWAY DIVE" (STEEP TOP-DOWN SCALE)
  // --------------------------------------------------------------------------
  const cam2 = new THREE.PerspectiveCamera(64, 1080 / 1920, 0.1, 900);
  cam2.position.set(0.0, 52.0, 8.0);
  cam2.lookAt(new THREE.Vector3(0.0, 16.0, -95.0));

  const canvas2 = renderPass(cam2, {
    bloom: 0.38,
    bloomThreshold: 1.15,
    bloomRadius: 0.50,
    exposure: 1.10,
    sat: 1.28,
    vignette: 0.18,
    focus: 60.0,
    aperture: 0.00008
  });
  const blob2 = await canvasToBlob(canvas2);
  await uploadImage('shot1_camera_angle_2_highdive.png', blob2);
  console.log('SAVED: shot1_camera_angle_2_highdive.png');

  // --------------------------------------------------------------------------
  // PASS 3: ANGLE 3 — "STREET-LEVEL BODEGA LOOK-UP" (PEDESTRIAN SCALE)
  // --------------------------------------------------------------------------
  const cam3 = new THREE.PerspectiveCamera(65, 1080 / 1920, 0.1, 900);
  cam3.position.set(-6.5, 2.8, -22.0);
  cam3.lookAt(new THREE.Vector3(0.0, 42.0, -120.0));

  const canvas3 = renderPass(cam3, {
    bloom: 0.44,
    bloomThreshold: 1.10,
    bloomRadius: 0.56,
    exposure: 1.12,
    sat: 1.30,
    vignette: 0.20,
    focus: 25.0,
    aperture: 0.0001
  });
  const blob3 = await canvasToBlob(canvas3);
  await uploadImage('shot1_camera_angle_3_streetlookup.png', blob3);
  await uploadImage('shot1_angle_3_lowangle.png', blob3);
  console.log('SAVED: shot1_camera_angle_3_streetlookup.png');

  // --------------------------------------------------------------------------
  // PASS 4: ANGLE 4 — "SPEEDER CHASE / OVER-THE-SHOULDER" (ANIME ACTION ENERGY)
  // --------------------------------------------------------------------------
  const cam4 = new THREE.PerspectiveCamera(56, 1080 / 1920, 0.1, 900);
  cam4.position.set(1.4, 20.2, -9.0);
  cam4.lookAt(new THREE.Vector3(0.0, 18.0, -75.0));

  const canvas4 = renderPass(cam4, {
    bloom: 0.46,
    bloomThreshold: 1.08,
    bloomRadius: 0.58,
    exposure: 1.16,
    sat: 1.35,
    vignette: 0.17,
    focus: 18.0,
    aperture: 0.0001
  });
  const blob4 = await canvasToBlob(canvas4);
  await uploadImage('shot1_camera_angle_4_chase.png', blob4);
  console.log('SAVED: shot1_camera_angle_4_chase.png');

  // --------------------------------------------------------------------------
  // PASS 5: WIDE 2.39:1 HORIZON PASS (FOR AUDIT COMPOSITOR)
  // --------------------------------------------------------------------------
  const wideCanvas = document.createElement('canvas');
  wideCanvas.width = 1920;
  wideCanvas.height = 800;
  const wideEngine = makeEngine(wideCanvas, { w: 1920, h: 800, samples: 4, shadowSize: 2048 });
  const camWide = new THREE.PerspectiveCamera(55, 1920 / 800, 0.1, 900);
  camWide.position.set(0.0, 36.0, 16.0);
  camWide.lookAt(new THREE.Vector3(0.0, 24.0, -120.0));
  wideEngine.render(scene, camWide, {
    bloom: 0.35,
    bloomThreshold: 1.18,
    bloomRadius: 0.50,
    exposure: 1.10,
    sat: 1.25,
    vignette: 0.15,
  });
  const wideBlob = await canvasToBlob(wideCanvas);
  await uploadImage('shot1_angle_2_horizon.png', wideBlob);

  // --------------------------------------------------------------------------
  // 6. MASTER 4-UP COMPARATIVE CAMERA SHOWCASE SHEET (2560 x 1440)
  // --------------------------------------------------------------------------
  const SW = 2560;
  const SH = 1440;
  masterCanvas.width = SW;
  masterCanvas.height = SH;

  masterCtx.fillStyle = '#020409';
  masterCtx.fillRect(0, 0, SW, SH);

  // Subtle Cyan Tech Grid
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.04)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < SW; x += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, SH); masterCtx.stroke();
  }
  for (let y = 0; y < SH; y += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(SW, y); masterCtx.stroke();
  }

  // Top Header Banner
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 38px "Segoe UI", Arial, sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // SHOT 1: CINEMATIC CAMERA ANGLE COMPARISON', 48, 54);

  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillStyle = '#00F0FF';
  masterCtx.fillText('OPENING SCENE DIRECTORS SUITE — 4 DYNAMIC VERTICAL (9:16) CAMERA PERSPECTIVES', 48, 88);

  masterCtx.fillStyle = '#38BDF8';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('PLASMA ION TRAILS • VEHICLE HEADLIGHT BEAMS • SEARCHLIGHTS • CYBER EMBERS', SW - 48, 52);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.fillText('ALL RENDERS FULL 1080x1920 VERTICAL (ROBLOX UGC 3D CINEMATIC SPEC)', SW - 48, 80);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath();
  masterCtx.moveTo(48, 108);
  masterCtx.lineTo(SW - 48, 108);
  masterCtx.stroke();

  // 4 Side-by-Side Vertical Frames:
  const cardGap = 24;
  const cardW = (SW - 96 - cardGap * 3) / 4; // ~598px per card
  const cardH = 1260;
  const cardY = 132;

  const cameraAngles = [
    {
      canvas: canvas1,
      title: 'ANGLE 1: GRAND CANYON GLIDE',
      subtitle: 'Aerial 3/4 Crane Establishing Shot',
      badge: 'RECOMMENDED OPENER',
      badgeCol: '#00F0FF',
      desc: 'Hero speeder banking in foreground, 4-lane avenue leading to Sovereign Apex Citadel.',
      camSpec: 'POS: (5.5, 27, 6) | FOV: 58° | PITCH: -4°',
    },
    {
      canvas: canvas2,
      title: 'ANGLE 2: SKYWAY DIVE',
      subtitle: 'High-Altitude Vertical Scale',
      badge: 'MEGASTRUCTURE DIVE',
      badgeCol: '#F59E0B',
      desc: 'Looking down past Maglev Sky-Train & Highway 101, showing multi-tier vertical canyon depth.',
      camSpec: 'POS: (0, 52, 8) | FOV: 64° | PITCH: -24°',
    },
    {
      canvas: canvas3,
      title: 'ANGLE 3: BODEGA LOOK-UP',
      subtitle: 'Pedestrian Street Perspective',
      badge: 'BLADE RUNNER VIBE',
      badgeCol: '#EC4899',
      desc: 'Street-level by Ramen 2077 neon awning, flying cars swooping overhead under sky-bridges.',
      camSpec: 'POS: (-6.5, 2.8, -22) | FOV: 65° | PITCH: +38°',
    },
    {
      canvas: canvas4,
      title: 'ANGLE 4: SPEEDER CHASE',
      subtitle: 'Over-The-Shoulder Action Cam',
      badge: 'HIGH-OCTANE AURA',
      badgeCol: '#00FF88',
      desc: 'Locked right behind hero speeder cockpit & wing, tracing ion ribbons weaving past cabs.',
      camSpec: 'POS: (1.4, 20.2, -9) | FOV: 56° | PITCH: -3°',
    },
  ];

  cameraAngles.forEach((a, idx) => {
    const cx = 48 + idx * (cardW + cardGap);

    // Card Background
    masterCtx.fillStyle = '#050914';
    masterCtx.fillRect(cx, cardY, cardW, cardH);

    // Draw Rendered Image
    const imgH = cardH - 180;
    masterCtx.drawImage(a.canvas, 0, 0, 1080, 1920, cx + 4, cardY + 4, cardW - 8, imgH);

    // Card Outer Border
    masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.45)';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(cx, cardY, cardW, cardH);

    // Info Footer Card
    masterCtx.fillStyle = '#070D1B';
    masterCtx.fillRect(cx, cardY + imgH, cardW, cardH - imgH);

    // Badge
    masterCtx.fillStyle = a.badgeCol;
    masterCtx.font = '900 11px monospace';
    masterCtx.fillText(`[ ${a.badge} ]`, cx + 14, cardY + imgH + 26);

    // Title & Subtitle
    masterCtx.fillStyle = '#FFFFFF';
    masterCtx.font = 'bold 16px "Segoe UI", sans-serif';
    masterCtx.fillText(a.title, cx + 14, cardY + imgH + 50);

    masterCtx.fillStyle = '#94A3B8';
    masterCtx.font = '12px "Segoe UI", sans-serif';
    masterCtx.fillText(a.subtitle, cx + 14, cardY + imgH + 70);

    // Description
    masterCtx.fillStyle = '#CBD5E1';
    masterCtx.font = '11px sans-serif';
    masterCtx.fillText(a.desc, cx + 14, cardY + imgH + 92, cardW - 28);

    // Camera Telemetry
    masterCtx.fillStyle = '#00F0FF';
    masterCtx.font = 'bold 11px monospace';
    masterCtx.fillText(a.camSpec, cx + 14, cardY + imgH + 116);
  });

  const showcaseBlob = await canvasToBlob(masterCanvas);
  await uploadImage('shot1_camera_showcase.png', showcaseBlob);
  console.log('SAVED: shot1_camera_showcase.png');

  // Also update shot1_metropolis_master.png for full compatibility
  await uploadImage('shot1_metropolis_master.png', showcaseBlob);
  console.log('SAVED: shot1_metropolis_master.png');

  console.log('SHOT1_AURA_SHOWCASE_COMPLETE');
}

window.addEventListener('DOMContentLoaded', init);

