91:   const target = await r.json();
92:   const ws = new WebSocket(target.webSocketDebuggerUrl);
93:   await new Promise((res, rej) => { ws.onopen = res; ws.onerror = rej; });
94: 
95:   let id = 0;
96:   const pend = new Map();
97:   ws.onmessage = (e) => {
98:     const m = JSON.parse(e.data);
99:     if (m.id && pend.has(m.id)) {
100:       const p = pend.get(m.id); pend.delete(m.id);
101:       m.error ? p.rej(new Error(m.error.message)) : p.res(m.result);
102:     } else if (m.method === 'Runtime.consoleAPICalled') {
103:       const text = m.params.args.map((a) => a.value ?? a.description).join(' ');
104:       console.log('CHROME LOG:', text);
105:     } else if (m.method === 'Runtime.exceptionThrown') {
106:       console.error('CHROME EXCEPTION:', m.params.exceptionDetails.exception?.description || m.params.exceptionDetails.text);
107:     }
108:   };
109: 
110:   const send = (method, params = {}) => new Promise((res, rej) => {
111:     const i = ++id; pend.set(i, { res, rej });
112:     ws.send(JSON.stringify({ id: i, method, params }));
113:   });
114: 
115:   const ev = async (expr) => {
116:     const x = await send('Runtime.evaluate', { expression: expr, returnByValue: true, awaitPromise: true });
117:     if (x.exceptionDetails) throw new Error(x.exceptionDetails.exception?.description || x.exceptionDetails.text);
118:     return x.result.value;
119:   };
120: 
121:   await send('Runtime.enable');
