    flareR.position.set(0.65, 0.25, 2.35);
    veh.add(flareR);
    // Dual speed trail ribbons behind
    const trailL = createIonRibbon(11.0, 0.28, colHex);
    trailL.position.set(-0.72, 0.32, -2.3);
    veh.add(trailL);
    const trailR = createIonRibbon(11.0, 0.28, colHex);
    trailR.position.set(0.72, 0.32, -2.3);
    veh.add(trailR);
  }

  veh.scale.set(s, s, s);
  veh.position.set(x, y, z);
