  // Colosseum Arena Combat Deck Non-Slip Tiles & Hazard Boundary
  arenaFloorDecal: () => canvasTex('arena_floor_decal', 1024, 1024, (g, w, h) => {
    // Dark volcanic obsidian / basalt bedrock
    g.fillStyle = '#080C14'; g.fillRect(0, 0, w, h);

    // Subtle carbon grid tiles
    const tileSize = 32;
    g.strokeStyle = '#111827'; g.lineWidth = 1.5;
    for (let x = 0; x < w; x += tileSize) {
      g.beginPath(); g.moveTo(x, 0); g.lineTo(x, h); g.stroke();
    }
    for (let y = 0; y < h; y += tileSize) {
      g.beginPath(); g.moveTo(0, y); g.lineTo(w, y); g.stroke();
    }

    // Outer Octagonal / Circular Hazard Border Ring (Yellow/Black)
    const cx = w / 2;
    const cy = h / 2;
    const outerR = 480;
    const innerR = 440;

    g.strokeStyle = '#F59E0B'; g.lineWidth = 8;
    g.beginPath(); g.arc(cx, cy, outerR, 0, Math.PI * 2); g.stroke();

    // Hazard Hash Marks
    const numHashes = 48;
    for (let i = 0; i < numHashes; i++) {
      const a = (i * Math.PI * 2) / numHashes;
      const x1 = cx + Math.cos(a) * innerR;
      const y1 = cy + Math.sin(a) * innerR;
      const x2 = cx + Math.cos(a) * outerR;
      const y2 = cy + Math.sin(a) * outerR;
      g.strokeStyle = (i % 2 === 0) ? '#F59E0B' : '#0F172A';
      g.lineWidth = 14;
      g.beginPath(); g.moveTo(x1, y1); g.lineTo(x2, y2); g.stroke();
    }

    // Inner Glowing Cyan Boundary Ring
    g.strokeStyle = '#00F0FF'; g.lineWidth = 6;
    g.beginPath(); g.arc(cx, cy, 380, 0, Math.PI * 2); g.stroke();

    // Concentric Energy Conduits / Runes
    g.strokeStyle = 'rgba(0, 240, 255, 0.45)'; g.lineWidth = 3;
    g.beginPath(); g.arc(cx, cy, 260, 0, Math.PI * 2); g.stroke();
    g.beginPath(); g.arc(cx, cy, 140, 0, Math.PI * 2); g.stroke();

    // Cardinal Energy Spikes
    for (let i = 0; i < 8; i++) {
      const a = (i * Math.PI) / 4;
      g.strokeStyle = '#00F0FF'; g.lineWidth = 4;
      g.beginPath();
      g.moveTo(cx + Math.cos(a) * 140, cy + Math.sin(a) * 140);
      g.lineTo(cx + Math.cos(a) * 380, cy + Math.sin(a) * 380);
      g.stroke();
    }

    // Center Arena Sovereign Gladiator Emblem
    g.fillStyle = '#00F0FF';
    g.beginPath(); g.arc(cx, cy, 50, 0, Math.PI * 2); g.fill();
    g.fillStyle = '#080C14';
    g.beginPath(); g.arc(cx, cy, 38, 0, Math.PI * 2); g.fill();

    // Crossed Swords Glyph in Center
    g.fillStyle = '#F59E0B'; g.font = '900 42px monospace'; g.textAlign = 'center';
    g.fillText('⚔', cx, cy + 14);
  }, [1, 1]),

