    // Center Countdown Match Timer
    g.fillStyle = '#0F1E38'; g.fillRect(w / 2 - 140, 95, 280, 110);
    g.strokeStyle = '#F59E0B'; g.lineWidth = 3;
    g.strokeRect(w / 2 - 140, 95, 280, 110);
    g.fillStyle = '#FBBF24'; g.font = '900 76px monospace'; g.textAlign = 'center';
    g.fillText('00:45', w / 2, 180);
    g.font = 'bold 16px monospace'; g.fillStyle = '#EC4899';
    g.fillText('MATCH IN PROGRESS', w / 2, 230);

    // Left Fighter: Rich Bully Pro (Dominus / Level 99)
