    const f2X = w - 355;
    const f2Y = 110;
    g.fillStyle = '#0E1726'; g.fillRect(f2X, f2Y, 320, 240);
    g.strokeStyle = '#EF4444'; g.lineWidth = 2; g.strokeRect(f2X, f2Y, 320, 240);
    g.fillStyle = '#F43F5E'; g.font = '900 24px sans-serif'; g.textAlign = 'left';
    g.fillText('BACON_HAIR_MC', f2X + 16, f2Y + 38);
    g.font = 'bold 16px monospace'; g.fillStyle = '#94A3B8';
    g.fillText('RANK: UNRANKED // LVL 12', f2X + 16, f2Y + 68);
    g.fillText('GEAR: TATTERED STARTER', f2X + 16, f2Y + 95);

    // F2 Health Bar (18% Critical Red)
    g.fillStyle = '#080E1A'; g.fillRect(f2X + 16, f2Y + 120, 288, 32);
    g.fillStyle = '#EF4444'; g.fillRect(f2X + 16, f2Y + 120, 52, 32);
    g.fillStyle = '#FFFFFF'; g.font = '900 16px monospace'; g.textAlign = 'center';
    g.fillText('18% HP (180/1000)', f2X + 160, f2Y + 143);

    // Bottom Warning Ticker (Solo Leveling System Warning)
    g.fillStyle = '#180B24'; g.fillRect(16, h - 85, w - 32, 65);
    g.strokeStyle = '#8B5CF6'; g.lineWidth = 2; g.strokeRect(16, h - 85, w - 32, 65);
    g.fillStyle = '#C084FC'; g.font = '900 20px monospace'; g.textAlign = 'center';
    g.fillText('⚠ SYSTEM ALERT: EMERGENCY SHADOW PROTOCOL DETECTED // 10% SOUL CORRUPTION', w / 2, h - 44);
  }, [1, 1]),

  // Spectator Bleachers Crowd with Cheering Lightsticks
  spectatorCrowdTexture: () => canvasTex('spectator_crowd', 512, 512, (g, w, h) => {
    g.fillStyle = '#060A14'; g.fillRect(0, 0, w, h);
    // Tier divider lines
    const tiers = 8;
    const th = h / tiers;
    for (let t = 0; t < tiers; t++) {
      const ty = t * th;
      g.fillStyle = (t % 2 === 0) ? '#0A1020' : '#0D1528';
      g.fillRect(0, ty, w, th);
      g.strokeStyle = '#1E293B'; g.lineWidth = 2;
      g.beginPath(); g.moveTo(0, ty); g.lineTo(w, ty); g.stroke();

      // Cheering spectator blockout heads & glowing lightsticks
      for (let x = 12; x < w - 12; x += 16) {
        // Head silhouette
        g.fillStyle = '#11192C';
        g.beginPath(); g.arc(x, ty + th - 12, 6, 0, Math.PI * 2); g.fill();
        // Lightstick (Cyan, Magenta, Amber, Green)
        const colPick = (x * 7 + t * 13) % 4;
        g.fillStyle = colPick === 0 ? '#00F0FF' : colPick === 1 ? '#EC4899' : colPick === 2 ? '#FBBF24' : '#00FF88';
        const angle = (Math.random() - 0.5) * 0.6;
        g.save();
        g.translate(x + 5, ty + th - 14);
        g.rotate(angle);
        g.fillRect(-1.5, -12, 3, 14);
        g.restore();
      }
    }
  }, [2, 2])
};

