// ============================================================================
// THE GLITCH MARKET — 5-ANGLE STUDIO AUDIT RENDERER
// ASSET: THE COLOSSEUM DEATHMATCH ARENA (SHOT 2)
//
// Produces:
// 1. colosseum_angle_1_hero.png (View 01: Front 3/4 Hero Overview)
// 2. colosseum_angle_2_ring.png (View 02: Combat Deck Floor Level)
// 3. colosseum_angle_3_underbelly.png (View 03: Underbelly Anti-Grav Repulsors)
// 4. colosseum_angle_4_jumbotron.png (View 04: Jumbotron HUD & VIP Skybox)
// 5. colosseum_angle_5_top.png (View 05: Top-Down Tactical Satellite)
// 6. colosseum_master_sheet.png (2400x1350 5-Panel Master Production Audit Sheet)
// ============================================================================

import * as THREE from 'three';
import { makeEngine, lightRig } from './core/engine.js';
import { buildColosseumArena } from './colosseum_arena.js';
import { Textures } from './core/geo.js';

const ANGLES = [
  { id: 'colosseum_angle_1_hero', title: 'VIEW 01: FRONT 3/4 HERO OVERVIEW', desc: 'Floating octagonal ring, 8 energy pylons, forcefield shield, jumbotron & crowd', pos: [48.0, 36.0, 48.0], target: [0, 10.0, 0], fov: 42 },
  { id: 'colosseum_angle_2_ring', title: 'VIEW 02: COMBAT DECK FLOOR LEVEL', desc: 'Obsidian non-slip tiles, hazard border ring, crossed swords glyph & pylon flames', pos: [0.0, 6.5, 24.0], target: [0, 8.0, -15.0], fov: 48 },
  { id: 'colosseum_angle_3_underbelly', title: 'VIEW 03: UNDERBELLY ANTI-GRAV ENGINES', desc: '4x heavy vector repulsor thrusters blasting cyan plasma lift jets into the void', pos: [28.0, -18.0, 32.0], target: [0, -4.0, 0], fov: 44 },
  { id: 'colosseum_angle_4_jumbotron', title: 'VIEW 04: JUMBOTRON HUD & VIP SKYBOX', desc: 'Holographic scoreboard timer 00:45, HP bars, Solo Leveling system alert & VIP pod', pos: [-12.0, 26.0, 22.0], target: [0, 24.0, 0], fov: 38 },
  { id: 'colosseum_angle_5_top', title: 'VIEW 05: TOP-DOWN TACTICAL PLAN', desc: 'Octagonal arena symmetry, hazard boundaries, 8 pylons, spectator amphitheater', pos: [0.0, 75.0, 0.1], target: [0, 0, 0], fov: 40 },
];

function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas for 5-angle rendering
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Colosseum Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#030612');
  scene.fog = new THREE.FogExp2('#060B1C', 0.0018);

  // Studio Lighting for Arena
  const keyLight = new THREE.DirectionalLight('#DCEBFA', 3.0);
  keyLight.position.set(35, 65, 35);
  keyLight.target.position.set(0, 8, 0);
  scene.add(keyLight);
  scene.add(keyLight.target);

  // Intense Cyan Rim / Underbelly Lift Light
  const cyanRim = new THREE.DirectionalLight('#00F0FF', 2.8);
  cyanRim.position.set(-30, -15, -30);
  cyanRim.target.position.set(0, 4, 0);
  scene.add(cyanRim);
  scene.add(cyanRim.target);

  // Warm Amber Fill Light
  const amberFill = new THREE.DirectionalLight('#F59E0B', 1.4);
  amberFill.position.set(40, 20, -40);
  amberFill.target.position.set(0, 8, 0);
  scene.add(amberFill);
  scene.add(amberFill.target);

  // Hemisphere Sky / Ground Light
  const hemi = new THREE.HemisphereLight('#38BDF8', '#080F1E', 0.95);
  scene.add(hemi);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(450, 450, 380, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 80, 0);
  scene.add(skyDome);

  // Build the complete Colosseum Arena
  const arena = buildColosseumArena();
  scene.add(arena);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 700);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    E.render(scene, cam, {
      bloom: 0.42,
      bloomThreshold: 1.12,
      bloomRadius: 0.55,
      exposure: 1.15,
      sat: 1.30,
      vignette: 0.15,
      focus: 35.0,
      aperture: 0.0001
    });

    const cCopy = document.createElement('canvas');
    cCopy.width = 1280;
    cCopy.height = 760;
    const ctx = cCopy.getContext('2d');
    ctx.drawImage(glCanvas, 0, 0);
    renderedCanvases.push({ canvas: cCopy, ...cfg });

    const blob = await canvasToBlob(cCopy);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png`);
  }

  // --------------------------------------------------------------------------
  // COMPOSITE MASTER 5-PANEL PRODUCTION AUDIT SHEET (2400 x 1350)
  // --------------------------------------------------------------------------
  const MW = 2400;
  const MH = 1350;
  masterCanvas.width = MW;
  masterCanvas.height = MH;

  masterCtx.fillStyle = '#020409';
  masterCtx.fillRect(0, 0, MW, MH);

  // Subtle Cyan Grid
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.04)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < MW; x += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, MH); masterCtx.stroke();
  }
  for (let y = 0; y < MH; y += 48) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(MW, y); masterCtx.stroke();
  }

  // Top Header Banner
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 38px "Segoe UI", Arial, sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // SHOT 2: THE COLOSSEUM DEATHMATCH ARENA', 48, 54);

  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillStyle = '#00F0FF';
  masterCtx.fillText('ASSET AUDIT: SECTOR 04 FLOATING PVP ARENA — 5-ANGLE MASTER PRODUCTION SHEET', 48, 88);

  masterCtx.fillStyle = '#38BDF8';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('FLOATING COMBAT RING • FORCEFIELD SHIELD • JUMBOTRON HUD • ANTI-GRAV REPULSORS', MW - 48, 52);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.fillText('DIAMETER: 64M • 8 ENERGY PYLONS • 5 TIER GRANDSTANDS • 4 VIP SKYBOXES', MW - 48, 80);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath();
  masterCtx.moveTo(48, 108);
  masterCtx.lineTo(MW - 48, 108);
  masterCtx.stroke();

  // Left Hero Panel: View 01 (Large)
  const leftX = 48;
  const leftY = 132;
  const leftW = 1420;
  const leftH = 820;

  masterCtx.fillStyle = '#050914';
  masterCtx.fillRect(leftX, leftY, leftW, leftH);
  masterCtx.drawImage(renderedCanvases[0].canvas, 0, 0, 1280, 760, leftX + 4, leftY + 4, leftW - 8, leftH - 52);

  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.5)';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(leftX, leftY, leftW, leftH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(leftX, leftY + leftH - 48, leftW, 48);
  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText(renderedCanvases[0].title, leftX + 16, leftY + leftH - 18);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px sans-serif';
  masterCtx.textAlign = 'right';
  masterCtx.fillText(renderedCanvases[0].desc, leftX + leftW - 16, leftY + leftH - 18);
  masterCtx.textAlign = 'left';

  // Right Top & Bottom: Views 02, 03, 04, 05 (4 Smaller Cards)
  const rightX = leftX + leftW + 24;
  const rightW = MW - rightX - 48;
  const smallCardW = (rightW - 16) / 2;
  const smallCardH = 398;

  const smallGrid = [
    { idx: 1, col: 0, row: 0 },
    { idx: 2, col: 1, row: 0 },
    { idx: 3, col: 0, row: 1 },
    { idx: 4, col: 1, row: 1 },
  ];

  smallGrid.forEach(g => {
    const item = renderedCanvases[g.idx];
    const cx = rightX + g.col * (smallCardW + 16);
    const cy = leftY + g.row * (smallCardH + 24);

    masterCtx.fillStyle = '#050914';
    masterCtx.fillRect(cx, cy, smallCardW, smallCardH);
    masterCtx.drawImage(item.canvas, 0, 0, 1280, 760, cx + 4, cy + 4, smallCardW - 8, smallCardH - 42);

    masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.4)';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(cx, cy, smallCardW, smallCardH);

    masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
    masterCtx.fillRect(cx, cy + smallCardH - 38, smallCardW, 38);
    masterCtx.fillStyle = '#F59E0B';
    masterCtx.font = 'bold 13px monospace';
    masterCtx.fillText(item.title, cx + 12, cy + smallCardH - 14);
  });

  // Bottom Technical Telemetry & Specifications Bar
  const botY = leftY + leftH + 24;
  const botW = MW - 96;
  const botH = MH - botY - 48;

  masterCtx.fillStyle = '#050914';
  masterCtx.fillRect(leftX, botY, botW, botH);
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.35)';
  masterCtx.lineWidth = 1.5;
  masterCtx.strokeRect(leftX, botY, botW, botH);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = '900 16px monospace';
  masterCtx.fillText('// ARENA ENGINEERING & PRODUCTION SPECIFICATIONS', leftX + 24, botY + 36);

  const specs = [
    'RING GEOMETRY: 64M OCTAGONAL DECK // OBSIDIAN TILES & DUAL HAZARD BORDERS',
    'FORCEFIELD: 8x 15M STEEL PYLONS WITH TRANSLUCENT CYBER SHIELD BARRIER',
    'ANTI-GRAV PROPULSION: 4x VECTOR THRUSTERS WITH CONTINUOUS CYAN PLASMA LIFT',
    'JUMBOTRON HUD: 24M DUAL-SIDED 3D DISPLAY WITH TIMER 00:45 & SYSTEM ALERT',
    'BROADCAST: QUAD-ROTOR DRONE WITH REC TALLY & 4x OVERHEAD STADIUM FLOODLIGHTS',
    'SPECTATOR CAPACITY: 5-TIER AMPHITHEATER WITH 2500+ LIGHTSTICK BLOCKOUTS',
  ];

  masterCtx.font = '13px monospace';
  masterCtx.fillStyle = '#E2E8F0';
  specs.forEach((s, idx) => {
    const col = idx < 3 ? 0 : 1;
    const row = idx % 3;
    masterCtx.fillText(`• ${s}`, leftX + 24 + col * 750, botY + 70 + row * 26);
  });

  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('colosseum_master_sheet.png', masterBlob);
  console.log('SAVED: colosseum_master_sheet.png');

  console.log('COLOSSEUM_ARENA_COMPLETE');
  window.ALL_SAVED = true;
}

