// ============================================================================
// THE GLITCH MARKET — 3D ASSETS: THE COLOSSEUM DEATHMATCH ARENA (SHOT 2)
//
// Key Architectural Features:
// 1. Floating Octagonal Combat Ring (30m radius, non-slip tiles, hazard borders, runes)
// 2. 8 Perimeter Energy Pylons & Honeycomb Hex Forcefield Shield
// 3. Underbelly Anti-Gravity Propulsion (4 Heavy repulsors blasting plasma jets)
// 4. Multi-Tiered Spectator Grandstands (Thousands of cheering crowd silhouettes)
// 5. Hovering VIP Skyboxes & Sponsor Holograms
// 6. Giant 3D Holographic Match Jumbotron (Timer 00:45, HP bars, System Alert)
// 7. Arena Broadcast Camera Drone (Quad-rotor drone tracking the duel)
// 8. Overhead High-Intensity Stadium Floodlight Banks
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createBeveledBox, chamferBox, Textures } from './core/geo.js';

export function buildColosseumArena() {
  const arena = new THREE.Group();
  arena.name = 'ColosseumDeathmatchArena';

  // Common Materials
  const MATS = {
    steelPlate: new THREE.MeshStandardMaterial({ color: 0x1E2638, roughness: 0.45, metalness: 0.6 }),
    darkObsidian: new THREE.MeshStandardMaterial({ color: 0x090D16, roughness: 0.7, metalness: 0.3 }),
    goldTrim: new THREE.MeshStandardMaterial({ color: 0xF59E0B, roughness: 0.25, metalness: 0.85 }),
    hazardAmber: new THREE.MeshBasicMaterial({ color: 0xF59E0B }),
    glowCyan: new THREE.MeshBasicMaterial({ color: 0x00F0FF }),
    glowMagenta: new THREE.MeshBasicMaterial({ color: 0xEC4899 }),
    glowRed: new THREE.MeshBasicMaterial({ color: 0xFF1744 }),
  };

  const R = 30.0; // Combat Ring Radius
  const H = 4.0;  // Platform Thickness

  // --------------------------------------------------------------------------
  // 1. MAIN FLOATING COMBAT PLATFORM (OCTAGONAL SLAB)
  // --------------------------------------------------------------------------
  // Platform Body Cylinder (8-sided)
  const slabGeo = new THREE.CylinderGeometry(R, R * 1.05, H, 8);
  const slabMesh = new THREE.Mesh(slabGeo, MATS.steelPlate);
  slabMesh.position.set(0, H / 2, 0);
  arena.add(slabMesh);

  // Upper Combat Deck Surface with Custom Decal (Obsidian tiles, hazard border, center runes)
  const matFloor = new THREE.MeshStandardMaterial({
    map: Textures.arenaFloorDecal(),
    roughness: 0.55,
    metalness: 0.4,
  });
  const deckSurface = new THREE.Mesh(new THREE.CylinderGeometry(R * 0.99, R * 0.99, 0.1, 8), matFloor);
  deckSurface.position.set(0, H + 0.05, 0);
  arena.add(deckSurface);

  // Perimeter Luminous Cyan LED Belt around platform rim
  const ledBelt = new THREE.Mesh(new THREE.CylinderGeometry(R * 1.02, R * 1.02, 0.35, 8, 1, true), MATS.glowCyan);
  ledBelt.position.set(0, H * 0.7, 0);
  arena.add(ledBelt);

  // --------------------------------------------------------------------------
  // 2. 8 PERIMETER ENERGY PYLONS & HONEYCOMB FORCEFIELD SHIELD
  // --------------------------------------------------------------------------
  const pylonPositions = [];
  const pylonH = 15.0;

  for (let i = 0; i < 8; i++) {
    const angle = (i * Math.PI * 2) / 8 + Math.PI / 8;
    const px = Math.cos(angle) * (R * 1.02);
    const pz = Math.sin(angle) * (R * 1.02);
    pylonPositions.push({ x: px, z: pz, angle });

    // Main Pylon Steel Column
    const pylon = createBeveledBox(2.2, pylonH, 2.2, 0.1, 2, MATS.steelPlate);
    pylon.position.set(px, pylonH / 2 + 1.0, pz);
    pylon.rotation.y = -angle;
    arena.add(pylon);

    // Glowing Neon Vertical Conduit along pylon face
    const conduit = new THREE.Mesh(new THREE.BoxGeometry(0.18, pylonH * 0.85, 0.18), MATS.glowCyan);
    conduit.position.set(px * 0.98, pylonH / 2 + 1.0, pz * 0.98);
    arena.add(conduit);

    // Pylon Crown Crystal Emitter Head
    const emitterHead = new THREE.Mesh(new THREE.ConeGeometry(1.4, 2.8, 6), MATS.goldTrim);
    emitterHead.position.set(px, pylonH + 2.4, pz);
    arena.add(emitterHead);

    const emitterGlow = new THREE.Mesh(new THREE.SphereGeometry(0.55, 12, 12), MATS.glowCyan);
    emitterGlow.position.set(px, pylonH + 3.8, pz);
    arena.add(emitterGlow);

    // Pyrotechnic Plasma Flare Jets on top
    const flareTorch = new THREE.Mesh(new THREE.ConeGeometry(0.35, 2.2, 8), MATS.hazardAmber);
    flareTorch.position.set(px, pylonH + 4.9, pz);
    arena.add(flareTorch);
  }

  // Honeycomb Hexagonal Energy Shield (Delicate wireframe grid with high transparency)
  const hexMatShield = new THREE.MeshBasicMaterial({
    map: Textures.hexGrid('#020612', '#00F0FF', 0.8, 64, 4),
    transparent: true,
    opacity: 0.28,
    side: THREE.DoubleSide,
    depthWrite: false,
    blending: THREE.AdditiveBlending
  });

  const shieldGeo = new THREE.CylinderGeometry(R * 1.01, R * 1.01, pylonH - 2.0, 8, 1, true);
  const shieldMesh = new THREE.Mesh(shieldGeo, hexMatShield);
  shieldMesh.position.set(0, (pylonH - 2.0) / 2 + H, 0);
  arena.add(shieldMesh);

  // Top & Bottom Glowing Forcefield Perimeter Rails
  const topRail = new THREE.Mesh(new THREE.CylinderGeometry(R * 1.015, R * 1.015, 0.18, 8, 1, true), MATS.glowCyan);
  topRail.position.set(0, pylonH + H - 2.0, 0);
  arena.add(topRail);

  const midRail = new THREE.Mesh(new THREE.CylinderGeometry(R * 1.015, R * 1.015, 0.12, 8, 1, true), MATS.glowAmber);
  midRail.position.set(0, (pylonH / 2) + H, 0);
  arena.add(midRail);

  // --------------------------------------------------------------------------
  // 3. UNDERBELLY ANTI-GRAV PROPULSION ENGINES
  // --------------------------------------------------------------------------
  // Central Heavy Reactor Core Hub
  const coreHub = new THREE.Mesh(new THREE.CylinderGeometry(9.0, 12.0, 6.0, 12), MATS.darkObsidian);
  coreHub.position.set(0, -3.0, 0);
  arena.add(coreHub);

  // 4 Massive Angled Anti-Gravity Repulsor Thrusters
  const repulsorData = [
    { x: -14.0, z: -14.0, rotX: 0.15, rotZ: 0.15 },
    { x: 14.0, z: -14.0, rotX: 0.15, rotZ: -0.15 },
    { x: -14.0, z: 14.0, rotX: -0.15, rotZ: 0.15 },
    { x: 14.0, z: 14.0, rotX: -0.15, rotZ: -0.15 },
  ];

  repulsorData.forEach(r => {
    // Housing
    const casing = new THREE.Mesh(new THREE.CylinderGeometry(3.2, 4.0, 5.0, 16), MATS.steelPlate);
    casing.position.set(r.x, -3.5, r.z);
    casing.rotation.x = r.rotX;
    casing.rotation.z = r.rotZ;
    arena.add(casing);

    // Glowing Cyan Plasma Lift Exhaust Jet
    const jetPlume = new THREE.Mesh(
      new THREE.ConeGeometry(3.4, 24.0, 16, 1, true),
      new THREE.MeshBasicMaterial({ color: 0x00F0FF, transparent: true, opacity: 0.75, depthWrite: false })
    );
    jetPlume.position.set(r.x, -16.0, r.z);
    jetPlume.rotation.x = Math.PI + r.rotX;
    jetPlume.rotation.z = r.rotZ;
    arena.add(jetPlume);
  });

  // --------------------------------------------------------------------------
  // 4. MULTI-TIERED SPECTATOR GRANDSTANDS & CHEERING CROWD
  // --------------------------------------------------------------------------
  const matCrowd = new THREE.MeshStandardMaterial({
    map: Textures.spectatorCrowdTexture(),
    roughness: 0.65,
    metalness: 0.2,
  });

  const standTiers = 6;
  for (let s = 0; s < standTiers; s++) {
    const innerRadius = 34.0 + s * 4.5;
    const outerRadius = innerRadius + 4.5;
    const tierH = 2.0 + s * 3.5;

    // Stepped Bleachers Arc (encircling the platform)
    const bleacher = new THREE.Mesh(
      new THREE.CylinderGeometry(outerRadius, innerRadius, 2.5, 32, 1, true),
      matCrowd
    );
    bleacher.position.set(0, tierH, 0);
    arena.add(bleacher);

    // Concrete Footing & Parapet
    const footing = new THREE.Mesh(
      new THREE.CylinderGeometry(outerRadius, outerRadius, 1.2, 32, 1, true),
      MATS.darkObsidian
    );
    footing.position.set(0, tierH - 1.2, 0);
    arena.add(footing);
  }

  // --------------------------------------------------------------------------
  // 5. HOVERING VIP OBSERVATION SKYBOXES
  // --------------------------------------------------------------------------
  for (let v = 0; v < 4; v++) {
    const vAngle = (v * Math.PI) / 2 + Math.PI / 4;
    const vx = Math.cos(vAngle) * 58.0;
    const vz = Math.sin(vAngle) * 58.0;

    const skybox = new THREE.Group();
    skybox.position.set(vx, 28.0, vz);
    skybox.lookAt(new THREE.Vector3(0, 8.0, 0));

    // Suite Pod Body
    const podBody = createBeveledBox(12.0, 5.0, 8.0, 0.12, 2, MATS.steelPlate);
    skybox.add(podBody);

    // Panoramic Gold Glass Front
    const podGlass = new THREE.Mesh(new THREE.BoxGeometry(11.2, 3.4, 0.2), MATS.goldTrim);
    podGlass.position.set(0, 0.2, 4.0);
    skybox.add(podGlass);

    // Glowing Neon Sponsor Banner
    const sponsorBanner = new THREE.Mesh(
      new THREE.PlaneGeometry(10.0, 1.2),
      new THREE.MeshBasicMaterial({ color: v % 2 === 0 ? 0x00F0FF : 0xF59E0B })
    );
    sponsorBanner.position.set(0, 3.0, 4.02);
    skybox.add(sponsorBanner);

    arena.add(skybox);
  }

  // --------------------------------------------------------------------------
  // 6. GIANT 3D HOLOGRAPHIC MATCH JUMBOTRON / STATUS HUD
  // --------------------------------------------------------------------------
  const jumbotron = new THREE.Group();
  jumbotron.name = 'ArenaJumbotron';
  jumbotron.position.set(0, 26.0, 0);

  const matScoreboard = new THREE.MeshStandardMaterial({
    map: Textures.arenaScoreboard(),
    roughness: 0.2,
    metalness: 0.4,
  });

  // Dual-Sided Jumbotron Screen (Facing Both Halves of the Stadium)
  const screenW = 20.0;
  const screenH = 10.0;

  // Front Screen
  const frontScreen = new THREE.Mesh(new THREE.PlaneGeometry(screenW, screenH), matScoreboard);
  frontScreen.position.set(0, 0, 1.2);
  jumbotron.add(frontScreen);

  // Back Screen
  const backScreen = new THREE.Mesh(new THREE.PlaneGeometry(screenW, screenH), matScoreboard);
  backScreen.position.set(0, 0, -1.2);
  backScreen.rotation.y = Math.PI;
  jumbotron.add(backScreen);

  // Jumbotron Steel Frame & Bevels
  const frame = createBeveledBox(screenW + 1.4, screenH + 1.4, 2.2, 0.15, 2, MATS.steelPlate);
  jumbotron.add(frame);

  // Overhead Suspension Steel Truss Cables
  for (const cx of [-8.0, 8.0]) {
    const cable = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 25.0, 8), MATS.steelPlate);
    cable.position.set(cx, 16.0, 0);
    jumbotron.add(cable);
  }

  arena.add(jumbotron);

  // --------------------------------------------------------------------------
  // 7. ARENA BROADCAST CAMERA DRONE
  // --------------------------------------------------------------------------
  const drone = new THREE.Group();
  drone.name = 'ArenaBroadcastDrone';
  drone.position.set(10.0, 12.0, -14.0);
  drone.lookAt(new THREE.Vector3(0, 6.0, 0));

  // Drone Monocoque Body
  const droneBody = createBeveledBox(2.2, 0.8, 2.2, 0.05, 1, MATS.steelPlate);
  drone.add(droneBody);

  // 4 Rotor Booms & Energy Rotor Discs
  [[-1.6, -1.6], [1.6, -1.6], [-1.6, 1.6], [1.6, 1.6]].forEach(([rx, rz]) => {
    const boom = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.12, 1.2), MATS.steelPlate);
    boom.position.set(rx * 0.6, 0.1, rz * 0.6);
    drone.add(boom);

    // Glowing Cyan Energy Rotor Ring
    const rotor = new THREE.Mesh(new THREE.TorusGeometry(0.75, 0.04, 8, 16), MATS.glowCyan);
    rotor.rotation.x = Math.PI / 2;
    rotor.position.set(rx, 0.25, rz);
    drone.add(rotor);
  });

  // Gimbaled Broadcast Camera Lens with Red Recording Tally Light
  const camLens = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.35, 0.6, 12), MATS.darkObsidian);
  camLens.rotation.x = Math.PI / 4;
  camLens.position.set(0, -0.45, 0.8);
  drone.add(camLens);

  const tallyLight = new THREE.Mesh(new THREE.SphereGeometry(0.12, 8, 8), MATS.glowRed);
  tallyLight.position.set(0, -0.25, 1.15);
  drone.add(tallyLight);

  arena.add(drone);

  // --------------------------------------------------------------------------
  // 8. OVERHEAD HIGH-INTENSITY STADIUM FLOODLIGHTS
  // --------------------------------------------------------------------------
  const floodlightRig = new THREE.Group();
  floodlightRig.name = 'StadiumFloodlights';

  for (let fl = 0; fl < 4; fl++) {
    const fAngle = (fl * Math.PI) / 2;
    const fx = Math.cos(fAngle) * 36.0;
    const fz = Math.sin(fAngle) * 36.0;

    const gantry = createBeveledBox(6.0, 1.8, 1.4, 0.05, 1, MATS.steelPlate);
    gantry.position.set(fx, 24.0, fz);
    gantry.lookAt(new THREE.Vector3(0, 4.0, 0));

    // 4 Spot Bulbs per Gantry
    for (let b = -2.0; b <= 2.0; b += 1.3) {
      const bulb = new THREE.Mesh(
        new THREE.SphereGeometry(0.35, 8, 8),
        new THREE.MeshBasicMaterial({ color: 0xF0F9FF })
      );
      bulb.position.set(b, 0, 0.8);
      gantry.add(bulb);
    }

    floodlightRig.add(gantry);
  }

  arena.add(floodlightRig);

  return arena;
}

