  // Hexagonal Honeycomb Forcefield Grid (Pure black background for AdditiveBlending)
  hexGrid: (lineCol = '#00F0FF', lineWidth = 3, hexRadius = 24) => canvasTex(`hex_grid_${lineCol}_${lineWidth}_${hexRadius}`, 512, 512, (g, w, h) => {
    // Pure black background (100% invisible in AdditiveBlending)
    g.fillStyle = '#000000';
    g.fillRect(0, 0, w, h);

    const r = hexRadius;
    const wStep = Math.sqrt(3) * r;
    const hStep = 1.5 * r;

    g.strokeStyle = lineCol;
    g.lineWidth = lineWidth;
    g.lineCap = 'round';
    g.lineJoin = 'round';

    function drawHex(cx, cy) {
      g.beginPath();
      for (let i = 0; i < 6; i++) {
        const a = (Math.PI / 3) * i + Math.PI / 6;
        const x = cx + r * Math.cos(a);
        const y = cy + r * Math.sin(a);
        if (i === 0) g.moveTo(x, y);
        else g.lineTo(x, y);
      }
      g.closePath();
      g.stroke();
    }

    const cols = Math.ceil(w / wStep) + 2;
    const rows = Math.ceil(h / hStep) + 2;

    for (let row = -1; row < rows; row++) {
      const y = row * hStep;
      const xOffset = (row % 2 !== 0) ? wStep / 2 : 0;
      for (let col = -1; col < cols; col++) {
        const x = col * wStep + xOffset;
        drawHex(x, y);
      }
    }

    // Glowing pulse nodes at hex vertices
    g.fillStyle = '#FFFFFF';
    for (let row = -1; row < rows; row += 2) {
      const y = row * hStep;
      const xOffset = (row % 2 !== 0) ? wStep / 2 : 0;
      for (let col = -1; col < cols; col += 2) {
        const x = col * wStep + xOffset;
        g.beginPath();
        g.arc(x, y + r, 2.5, 0, Math.PI * 2);
        g.fill();
      }
    }
  }, [8, 4])
};

