// ============================================================================
// THE GLITCH MARKET — 3D ASSETS: CLASSIC ROBLOX NOOB SPECTATOR AVATAR (SHOT 2)
//
// Key Authentic Features:
// 1. Canonical R6 Blocky Proportions (Head, Torso, Left/Right Arms, Legs)
// 2. Exact Roblox Injection-Molded Plastic Materials & Stud Geometry:
//    - Cylindrical Head Stud with embossed circular rim
//    - Torso Shoulder Studs
//    - Fine Chamfered Box Limbs (Authentic Roblox beveled edges)
// 3. Classic Noob Tri-Color Palette:
//    - Skin: Bright Yellow (#FEDC00)
//    - Torso: Blox Royal Blue (#0D69AC)
//    - Legs: Blox Bright Green (#28A745)
// 4. Custom Classic Roblox Smiley Face Decal (Ovals + Wide Open Arc)
// 5. Arena Spectator Cheering Rig:
//    - Right arm raised high waving a dual-tone glowing neon lightstick
//    - Left arm fist-pumping in excitement
//    - Lanyard with [SECTOR 04 VIP FAN] Holographic Badge
//    - Dual pose support: Standing Cheering & Seated Bleacher Pose
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createBeveledBox, canvasTex } from './core/geo.js';

/**
 * Creates the classic Roblox smiley face decal canvas texture
 */
export function createRobloxSmileDecal() {
  return canvasTex('classic_roblox_smile', 512, 512, (g, w, h) => {
    g.clearRect(0, 0, w, h);

    // Deep obsidian black features
    g.fillStyle = '#0B0F19';

    // Left Oval Eye
    g.beginPath();
    g.ellipse(172, 195, 18, 30, 0, 0, Math.PI * 2);
    g.fill();

    // Right Oval Eye
    g.beginPath();
    g.ellipse(340, 195, 18, 30, 0, 0, Math.PI * 2);
    g.fill();

    // Specular Catchlights in eyes (gives lively character)
    g.fillStyle = '#FFFFFF';
    g.beginPath();
    g.arc(166, 184, 6, 0, Math.PI * 2);
    g.fill();
    g.beginPath();
    g.arc(334, 184, 6, 0, Math.PI * 2);
    g.fill();

    // Wide Classic Open Smile Arc
    g.strokeStyle = '#0B0F19';
    g.lineWidth = 18;
    g.lineCap = 'round';
    g.beginPath();
    g.arc(256, 235, 105, 0.22 * Math.PI, 0.78 * Math.PI, false);
    g.stroke();

    // Subtle dimple corners
    g.beginPath();
    g.arc(174, 304, 7, 0, Math.PI * 2);
    g.fill();
    g.beginPath();
    g.arc(338, 304, 7, 0, Math.PI * 2);
    g.fill();
  }, [1, 1]);
}

/**
 * Creates the holographic Sector 04 Arena Fan Badge decal
 */
export function createArenaFanBadge() {
  return canvasTex('arena_fan_badge', 256, 256, (g, w, h) => {
    // Dark laminate badge card
    g.fillStyle = '#090D1A';
    g.fillRect(10, 10, w - 20, h - 20);
    g.strokeStyle = '#00F0FF';
    g.lineWidth = 4;
    g.strokeRect(10, 10, w - 20, h - 20);

    // Top Header Banner
    g.fillStyle = '#00F0FF';
    g.fillRect(10, 10, w - 20, 48);
    g.fillStyle = '#030712';
    g.font = '900 20px monospace';
    g.textAlign = 'center';
    g.fillText('ARENA S04', w / 2, 42);

    // Badge Title & Barcode
    g.fillStyle = '#FEDC00';
    g.font = 'bold 24px sans-serif';
    g.fillText('VIP FAN', w / 2, 105);

    g.fillStyle = '#94A3B8';
    g.font = '14px monospace';
    g.fillText('DEATHMATCH PASS', w / 2, 135);

    // Mini Barcode
    g.fillStyle = '#00F0FF';
    for (let x = 35; x < w - 35; x += 8) {
      const bw = (x * 7) % 3 === 0 ? 4 : 2;
      g.fillRect(x, 160, bw, 32);
    }

    g.fillStyle = '#64748B';
    g.font = '11px monospace';
    g.fillText('SEC: 04 // ROW: 02', w / 2, 218);
  }, [1, 1]);
}

/**
 * Builds the complete 3D Roblox Noob Spectator Avatar
 * @param {Object} options Configuration options
 * @param {boolean} options.seated If true, poses the avatar seated for bleachers
 * @param {string} options.lightstickCol Color of the glowing lightstick ('#00F0FF', '#EC4899', '#FBBF24', '#00FF88')
 * @param {boolean} options.hasBadge If true, renders the arena fan lanyard badge
 * @param {number} options.cheerArmAngle Angle offset for arm waving animation
 */
export function buildNoobAvatar(options = {}) {
  const {
    seated = false,
    lightstickCol = '#00F0FF',
    hasBadge = true,
    cheerArmAngle = 0
  } = options;

  const noob = new THREE.Group();
  noob.name = 'RobloxNoobSpectator';

  // Materials with classic Roblox shiny toy plastic response
  const MATS = {
    skinYellow: new THREE.MeshStandardMaterial({
      color: 0xFEDC00,
      roughness: 0.32,
      metalness: 0.05
    }),
    torsoBlue: new THREE.MeshStandardMaterial({
      color: 0x0D69AC,
      roughness: 0.35,
      metalness: 0.05
    }),
    legsGreen: new THREE.MeshStandardMaterial({
      color: 0x28A745,
      roughness: 0.38,
      metalness: 0.05
    }),
    darkSteel: new THREE.MeshStandardMaterial({
      color: 0x1E293B,
      roughness: 0.4,
      metalness: 0.7
    }),
    lightstickGlow: new THREE.MeshBasicMaterial({
      color: new THREE.Color(lightstickCol)
    }),
    lightstickCore: new THREE.MeshBasicMaterial({
      color: 0xFFFFFF
    }),
    lanyardCord: new THREE.MeshBasicMaterial({
      color: 0x00F0FF
    }),
    faceDecal: new THREE.MeshBasicMaterial({
      map: createRobloxSmileDecal(),
      transparent: true,
      depthWrite: false
    }),
    badgeDecal: new THREE.MeshStandardMaterial({
      map: createArenaFanBadge(),
      roughness: 0.3,
      metalness: 0.1
    })
  };

  // Dimensions (Standard Canonical Roblox R6 Units, 1 Unit = ~0.6m in our world space)
  const HEAD_SIZE = 1.25;
  const TORSO_W = 2.0;
  const TORSO_H = 2.0;
  const TORSO_D = 1.0;
  const LIMB_W = 1.0;
  const LIMB_H = 2.0;
  const LIMB_D = 1.0;

  // Root Pivot Y Offset
  const baseY = seated ? 1.0 : 2.0;

  // --------------------------------------------------------------------------
  // 1. TORSO (Royal Blue Box + Shoulder Studs)
  // --------------------------------------------------------------------------
  const torsoGroup = new THREE.Group();
  torsoGroup.position.set(0, baseY + TORSO_H / 2, 0);

  // Beveled Torso Block
  const torsoMesh = createBeveledBox(TORSO_W, TORSO_H, TORSO_D, 0.04, 2, MATS.torsoBlue);
  torsoMesh.castShadow = true;
  torsoMesh.receiveShadow = true;
  torsoGroup.add(torsoMesh);

  // 4 Top Shoulder Studs (2 on left, 2 on right)
  const studPositions = [
    [-0.6, TORSO_H / 2 + 0.05, -0.22],
    [-0.6, TORSO_H / 2 + 0.05, 0.22],
    [0.6, TORSO_H / 2 + 0.05, -0.22],
    [0.6, TORSO_H / 2 + 0.05, 0.22]
  ];
  studPositions.forEach(([sx, sy, sz]) => {
    const stud = new THREE.Mesh(new THREE.CylinderGeometry(0.16, 0.16, 0.10, 16), MATS.torsoBlue);
    stud.position.set(sx, sy, sz);
    stud.castShadow = true;
    torsoGroup.add(stud);
  });

  // Neck Connector Stud
  const neckStud = new THREE.Mesh(new THREE.CylinderGeometry(0.24, 0.24, 0.15, 16), MATS.skinYellow);
  neckStud.position.set(0, TORSO_H / 2 + 0.08, 0);
  torsoGroup.add(neckStud);

  // Lanyard & Arena Badge
  if (hasBadge) {
    // V-shaped cord over chest
    const cordLeft = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 1.3, 8), MATS.lanyardCord);
    cordLeft.position.set(-0.35, 0.2, TORSO_D / 2 + 0.02);
    cordLeft.rotation.z = -0.38;
    torsoGroup.add(cordLeft);

    const cordRight = new THREE.Mesh(new THREE.CylinderGeometry(0.015, 0.015, 1.3, 8), MATS.lanyardCord);
    cordRight.position.set(0.35, 0.2, TORSO_D / 2 + 0.02);
    cordRight.rotation.z = 0.38;
    torsoGroup.add(cordRight);

    // Hanging Plastic Pass
    const badge = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.65, 0.02), MATS.badgeDecal);
    badge.position.set(0, -0.4, TORSO_D / 2 + 0.035);
    badge.rotation.z = 0.06;
    torsoGroup.add(badge);
  }

  noob.add(torsoGroup);

  // --------------------------------------------------------------------------
  // 2. HEAD & FACE DECAL
  // --------------------------------------------------------------------------
  const headGroup = new THREE.Group();
  headGroup.position.set(0, baseY + TORSO_H + HEAD_SIZE / 2 + 0.06, 0);
  // Cheerful upward head tilt towards the arena action
  headGroup.rotation.x = -0.12;
  headGroup.rotation.y = 0.08;

  // Yellow Beveled Head Cube
  const headMesh = createBeveledBox(HEAD_SIZE, HEAD_SIZE, HEAD_SIZE, 0.04, 2, MATS.skinYellow);
  headMesh.castShadow = true;
  headGroup.add(headMesh);

  // Canonical Top Roblox Head Stud with Circular Rim
  const headStud = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.32, 0.16, 24), MATS.skinYellow);
  headStud.position.set(0, HEAD_SIZE / 2 + 0.08, 0);
  headStud.castShadow = true;
  headGroup.add(headStud);

  const headStudRim = new THREE.Mesh(new THREE.TorusGeometry(0.30, 0.025, 8, 24), MATS.skinYellow);
  headStudRim.position.set(0, HEAD_SIZE / 2 + 0.16, 0);
  headStudRim.rotation.x = Math.PI / 2;
  headGroup.add(headStudRim);

  // Classic Smile Face Decal on Front Face (+Z)
  const facePlane = new THREE.Mesh(new THREE.PlaneGeometry(HEAD_SIZE * 0.94, HEAD_SIZE * 0.94), MATS.faceDecal);
  facePlane.position.set(0, 0, HEAD_SIZE / 2 + 0.005);
  headGroup.add(facePlane);

  noob.add(headGroup);

  // --------------------------------------------------------------------------
  // 3. RIGHT ARM & CHEERING NEON LIGHTSTICK (Active Cheering Arm)
  // --------------------------------------------------------------------------
  const rightArmGroup = new THREE.Group();
  // Shoulder Pivot Joint
  rightArmGroup.position.set(TORSO_W / 2 + LIMB_W / 2, baseY + TORSO_H - 0.2, 0);

  // Raised Cheering Pose: Arm waving overhead with lightstick
  rightArmGroup.rotation.z = -Math.PI * 0.72 + cheerArmAngle;
  rightArmGroup.rotation.x = 0.28;
  rightArmGroup.rotation.y = -0.15;

  const rightArmMesh = createBeveledBox(LIMB_W, LIMB_H, LIMB_D, 0.04, 2, MATS.skinYellow);
  rightArmMesh.position.set(0, -LIMB_H / 2 + 0.2, 0);
  rightArmMesh.castShadow = true;
  rightArmGroup.add(rightArmMesh);

  // Glowing Neon Lightstick Batons in Right Hand
  const lightstick = new THREE.Group();
  lightstick.position.set(0, -LIMB_H + 0.25, 0.35);
  lightstick.rotation.x = Math.PI / 2 + 0.2;

  // Dark Handle
  const handle = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.45, 12), MATS.darkSteel);
  handle.position.set(0, -0.2, 0);
  lightstick.add(handle);

  const hiltRing = new THREE.Mesh(new THREE.TorusGeometry(0.10, 0.025, 8, 16), MATS.lightstickGlow);
  hiltRing.position.set(0, 0.02, 0);
  hiltRing.rotation.x = Math.PI / 2;
  lightstick.add(hiltRing);

  // Neon Light Tube
  const tube = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 1.35, 16), MATS.lightstickGlow);
  tube.position.set(0, 0.7, 0);
  lightstick.add(tube);

  // Ultra-Bright White Inner Core
  const core = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 1.28, 8), MATS.lightstickCore);
  core.position.set(0, 0.7, 0);
  lightstick.add(core);

  // Glowing Tip Cap
  const tip = new THREE.Mesh(new THREE.SphereGeometry(0.09, 12, 12), MATS.lightstickGlow);
  tip.position.set(0, 1.38, 0);
  lightstick.add(tip);

  rightArmGroup.add(lightstick);
  noob.add(rightArmGroup);

  // --------------------------------------------------------------------------
  // 4. LEFT ARM (Pumping / Cheering Stance)
  // --------------------------------------------------------------------------
  const leftArmGroup = new THREE.Group();
  leftArmGroup.position.set(-(TORSO_W / 2 + LIMB_W / 2), baseY + TORSO_H - 0.2, 0);

  // Pumping Forward/Upward Pose
  leftArmGroup.rotation.z = Math.PI * 0.22;
  leftArmGroup.rotation.x = -0.55;
  leftArmGroup.rotation.y = 0.2;

  const leftArmMesh = createBeveledBox(LIMB_W, LIMB_H, LIMB_D, 0.04, 2, MATS.skinYellow);
  leftArmMesh.position.set(0, -LIMB_H / 2 + 0.2, 0);
  leftArmMesh.castShadow = true;
  leftArmGroup.add(leftArmMesh);

  noob.add(leftArmGroup);

  // --------------------------------------------------------------------------
  // 5. LEGS (Green Box Limbs — Standing or Seated Bleacher Pose)
  // --------------------------------------------------------------------------
  const leftLegGroup = new THREE.Group();
  leftLegGroup.position.set(-LIMB_W / 2, baseY, 0);

  const rightLegGroup = new THREE.Group();
  rightLegGroup.position.set(LIMB_W / 2, baseY, 0);

  if (seated) {
    // Seated Bleacher Pose: Legs rotated 90 degrees forward
    leftLegGroup.rotation.x = -Math.PI / 2 + 0.05;
    rightLegGroup.rotation.x = -Math.PI / 2 - 0.05;
  } else {
    // Standing Lively Stance: Slight natural step
    leftLegGroup.rotation.x = 0.12;
    rightLegGroup.rotation.x = -0.15;
  }

  const leftLegMesh = createBeveledBox(LIMB_W, LIMB_H, LIMB_D, 0.04, 2, MATS.legsGreen);
  leftLegMesh.position.set(0, -LIMB_H / 2, 0);
  leftLegMesh.castShadow = true;
  leftLegMesh.receiveShadow = true;
  leftLegGroup.add(leftLegMesh);

  const rightLegMesh = createBeveledBox(LIMB_W, LIMB_H, LIMB_D, 0.04, 2, MATS.legsGreen);
  rightLegMesh.position.set(0, -LIMB_H / 2, 0);
  rightLegMesh.castShadow = true;
  rightLegMesh.receiveShadow = true;
  rightLegGroup.add(rightLegMesh);

  noob.add(leftLegGroup);
  noob.add(rightLegGroup);

  return noob;
}

