function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas for 5-angle rendering
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Showroom Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#030712');

  // High-End Studio Lighting for Character Presentation
  const keyLight = new THREE.DirectionalLight('#FFFBE8', 3.2);
  keyLight.position.set(4.5, 8.0, 5.0);
  keyLight.target.position.set(0, 2.5, 0);
  keyLight.castShadow = true;
  keyLight.shadow.mapSize.width = 2048;
  keyLight.shadow.mapSize.height = 2048;
  keyLight.shadow.bias = -0.0005;
  scene.add(keyLight);
  scene.add(keyLight.target);

  // Intense Cyan Rim Light (Arena Ambiance)
  const cyanRim = new THREE.DirectionalLight('#00F0FF', 2.4);
  cyanRim.position.set(-4.5, 5.0, -4.0);
  cyanRim.target.position.set(0, 2.5, 0);
  scene.add(cyanRim);
  scene.add(cyanRim.target);

  // Warm Amber Fill Light
  const amberFill = new THREE.DirectionalLight('#F59E0B', 1.5);
  amberFill.position.set(4.0, 2.0, -3.5);
  amberFill.target.position.set(0, 2.5, 0);
  scene.add(amberFill);
  scene.add(amberFill.target);

  // Soft Ambient Hemisphere Sky/Ground
  const hemi = new THREE.HemisphereLight('#38BDF8', '#090D1A', 0.85);
  scene.add(hemi);

  // Studio Display Pedestal
  const pedestalGeo = new THREE.CylinderGeometry(2.8, 3.2, 0.35, 48);
  const pedestalMat = new THREE.MeshStandardMaterial({
    color: 0x0F172A,
    roughness: 0.35,
    metalness: 0.6
  });
  const pedestal = new THREE.Mesh(pedestalGeo, pedestalMat);
  pedestal.position.set(0, -0.175, 0);
  pedestal.receiveShadow = true;
  scene.add(pedestal);

  // Glowing Cyan Circular Base Trim
  const trimGeo = new THREE.TorusGeometry(3.22, 0.04, 8, 48);
  const trimMat = new THREE.MeshBasicMaterial({ color: 0x00F0FF });
  const trim = new THREE.Mesh(trimGeo, trimMat);
  trim.rotation.x = Math.PI / 2;
  trim.position.set(0, 0.02, 0);
  scene.add(trim);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    // Clear and build the avatar in the requested pose
    const existingAvatar = scene.getObjectByName('RobloxNoobSpectator');
    if (existingAvatar) scene.remove(existingAvatar);

    const avatar = buildNoobAvatar({
      seated: cfg.seated,
      lightstickCol: cfg.lightstickCol,
      hasBadge: true
    });
    scene.add(avatar);

    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 100);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    // Render WebGL frame
    E.renderer.render(scene, cam);

    // Save individual angle canvas
    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = 1280;
    angleCanvas.height = 760;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Overlay HUD on individual angle
    actx.fillStyle = 'rgba(3, 7, 18, 0.72)';
    actx.fillRect(20, 20, 580, 54);
    actx.strokeStyle = '#00F0FF';
    actx.lineWidth = 1.5;
    actx.strokeRect(20, 20, 580, 54);

    actx.fillStyle = '#00F0FF';
    actx.font = 'bold 18px monospace';
    actx.fillText(cfg.title, 34, 44);

    actx.fillStyle = '#94A3B8';
    actx.font = '12px monospace';
    actx.fillText(cfg.desc, 34, 62);

    renderedCanvases.push(angleCanvas);

    // Upload individual angle
    const blob = await canvasToBlob(angleCanvas);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png`);
  }

  // --------------------------------------------------------------------------
  // ASSEMBLE 2400 × 1350 MASTER PRODUCTION SHEET
  // --------------------------------------------------------------------------
  masterCtx.fillStyle = '#030712';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Cyber Grid Backdrop
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.05)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < 2400; x += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Master Header
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 34px sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // SHOT 2 SPECTATOR ROSTER: CLASSIC ROBLOX NOOB FAN', 45, 55);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText('ASSET B-01: CANONICAL R6 SPECTATOR AVATAR RIG — 5-ANGLE PRODUCTION AUDIT', 45, 85);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('ROBLOX R6 RIG • SHINY TOY PLASTIC • HEAD & TORSO STUDS • DUAL POSE RIG', 2355, 55);
  masterCtx.fillText('DECALS: CLASSIC SMILE & SECTOR 04 FAN PASS • PROPS: GLOWING LIGHTSTICK', 2355, 78);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath(); masterCtx.moveTo(45, 105); masterCtx.lineTo(2355, 105); masterCtx.stroke();

  // Grid Layout:
  // Large Hero on Left: 1420 × 840
  // 4 Smaller Angles on Right: 2 × 2 grid, each 430 × 255
  const heroX = 45;
  const heroY = 130;
  const heroW = 1420;
  const heroH = 840;

  masterCtx.drawImage(renderedCanvases[0], heroX, heroY, heroW, heroH);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(heroX, heroY, heroW, heroH);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.fillText('VIEW 01: FRONT 3/4 HERO OVERVIEW', heroX + 16, heroY + heroH - 18);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('Standing cheering pose, glowing cyan lightstick, smiling face decal & shoulder studs', heroX + heroW - 16, heroY + heroH - 18);
  masterCtx.textAlign = 'left';

  // 4 Thumbnail Panels on Right
  const rightX = 1500;
  const thumbW = 855;
  const thumbH = 200;
  const thumbGap = 13;

  for (let i = 1; i < 5; i++) {
    const ty = heroY + (i - 1) * (thumbH + thumbGap);
    masterCtx.drawImage(renderedCanvases[i], rightX, ty, thumbW, thumbH);
    masterCtx.strokeStyle = '#1E293B';
