    masterCtx.strokeRect(rightX, ty, thumbW, thumbH);

    masterCtx.fillStyle = 'rgba(3, 7, 18, 0.7)';
    masterCtx.fillRect(rightX + 8, ty + thumbH - 30, thumbW - 16, 22);

    masterCtx.fillStyle = '#00F0FF';
    masterCtx.font = 'bold 12px monospace';
    masterCtx.fillText(ANGLES[i].title, rightX + 16, ty + thumbH - 14);
  }

  // Bottom Specifications Panel
  const specY = 1000;
  const specH = 300;
  masterCtx.fillStyle = 'rgba(9, 13, 26, 0.85)';
  masterCtx.fillRect(45, specY, 2310, specH);
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.3)';
  masterCtx.lineWidth = 1.5;
  masterCtx.strokeRect(45, specY, 2310, specH);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillText('// AVATAR ENGINEERING & ROBLOX UGC SPECIFICATIONS', 70, specY + 36);

  const col1X = 70;
  const col2X = 840;
  const col3X = 1600;
  const lineH = 26;

