// ============================================================================
// THE GLITCH MARKET — 3D SPECTATOR AVATARS & CROWD SYSTEM (SHOT 2)
//
// Archetypes Built:
// 1. Classic Noob Fan (Yellow skin, royal blue torso, green legs, classic smile, lightstick)
// 2. Rich / Pro Spectator (Titanium armor, glowing neon cyber visor, Valkyrie horns, gold pauldrons)
// 3. Bacon Hair Starter Spectator (Layered bacon hair mesh, starter jacket, denim jeans, anxious face)
// 4. VIP Suite Elite Patron (Top hat with silk band, gold monocle, formal tuxedo & bowtie)
// 5. Holographic Cheering Banners & Lightsticks (Animated crowd props)
// 6. Bleacher Crowd Generator (Populates arena grandstands with diverse 3D avatars)
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createBeveledBox, canvasTex } from './core/geo.js';
import { createRobloxSmileDecal, createArenaFanBadge } from './noob_avatar.js';

// Shared Materials Palette
const MATS = {
  // Skins
  skinYellow: new THREE.MeshStandardMaterial({ color: 0xFEDC00, roughness: 0.32, metalness: 0.05 }),
  skinPale: new THREE.MeshStandardMaterial({ color: 0xF7D0B5, roughness: 0.35, metalness: 0.02 }),
  skinDarkTitanium: new THREE.MeshStandardMaterial({ color: 0x1E293B, roughness: 0.25, metalness: 0.6 }),

  // Clothing
  torsoBlue: new THREE.MeshStandardMaterial({ color: 0x0D69AC, roughness: 0.35, metalness: 0.05 }),
  legsGreen: new THREE.MeshStandardMaterial({ color: 0x28A745, roughness: 0.38, metalness: 0.05 }),
  armorObsidian: new THREE.MeshStandardMaterial({ color: 0x0B0F19, roughness: 0.2, metalness: 0.8 }),
  goldTrim: new THREE.MeshStandardMaterial({ color: 0xF59E0B, roughness: 0.25, metalness: 0.85 }),
  tuxedoBlack: new THREE.MeshStandardMaterial({ color: 0x070B14, roughness: 0.45, metalness: 0.1 }),
  denimBlue: new THREE.MeshStandardMaterial({ color: 0x1E3A8A, roughness: 0.6, metalness: 0.05 }),
  starterJacket: new THREE.MeshStandardMaterial({ color: 0x2563EB, roughness: 0.5, metalness: 0.1 }),
  baconHairBrown: new THREE.MeshStandardMaterial({ color: 0x6D4C41, roughness: 0.65, metalness: 0.05 }),
  baconHairHighlight: new THREE.MeshStandardMaterial({ color: 0x8D6E63, roughness: 0.6, metalness: 0.05 }),
  silkRed: new THREE.MeshStandardMaterial({ color: 0xDC2626, roughness: 0.3, metalness: 0.2 }),
  darkSteel: new THREE.MeshStandardMaterial({ color: 0x1E293B, roughness: 0.4, metalness: 0.7 }),

  // Emissive & Neons
  glowCyan: new THREE.MeshBasicMaterial({ color: 0x00F0FF }),
  glowMagenta: new THREE.MeshBasicMaterial({ color: 0xEC4899 }),
  glowAmber: new THREE.MeshBasicMaterial({ color: 0xFBBF24 }),
  glowGreen: new THREE.MeshBasicMaterial({ color: 0x00FF88 }),
  glowRed: new THREE.MeshBasicMaterial({ color: 0xFF1744 }),
  coreWhite: new THREE.MeshBasicMaterial({ color: 0xFFFFFF })
};

// ----------------------------------------------------------------------------
// CUSTOM DECALS
// ----------------------------------------------------------------------------

export function createBaconHairAnxiousFace() {
  return canvasTex('bacon_anxious_face', 512, 512, (g, w, h) => {
    g.clearRect(0, 0, w, h);
    g.fillStyle = '#111827';
    // Wide open round eyes (anxious/amazed reaction to duel)
    g.beginPath(); g.arc(175, 195, 26, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(337, 195, 26, 0, Math.PI * 2); g.fill();

    // White eye highlights
    g.fillStyle = '#FFFFFF';
    g.beginPath(); g.arc(168, 186, 8, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(330, 186, 8, 0, Math.PI * 2); g.fill();

    // Small open nervous mouth
    g.fillStyle = '#111827';
    g.beginPath(); g.ellipse(256, 280, 24, 18, 0, 0, Math.PI * 2); g.fill();

    // Worried curved eyebrows
    g.strokeStyle = '#111827';
    g.lineWidth = 8;
    g.beginPath(); g.moveTo(145, 145); g.quadraticCurveTo(175, 130, 205, 150); g.stroke();
    g.beginPath(); g.moveTo(367, 145); g.quadraticCurveTo(337, 130, 307, 150); g.stroke();
  }, [1, 1]);
}

export function createTuxedoShirtDecal() {
  return canvasTex('tuxedo_shirt_decal', 512, 512, (g, w, h) => {
    // Black tuxedo jacket lapels
    g.fillStyle = '#070B14'; g.fillRect(0, 0, w, h);
    // White dress shirt V-insert
    g.fillStyle = '#F8FAFC';
    g.beginPath();
    g.moveTo(140, 0); g.lineTo(372, 0); g.lineTo(256, 380);
    g.closePath(); g.fill();

    // Crimson Bowtie
    g.fillStyle = '#DC2626';
    g.beginPath();
    g.moveTo(256, 75); g.lineTo(210, 50); g.lineTo(210, 100); g.closePath(); g.fill();
    g.beginPath();
    g.moveTo(256, 75); g.lineTo(302, 50); g.lineTo(302, 100); g.closePath(); g.fill();
    g.beginPath(); g.arc(256, 75, 10, 0, Math.PI * 2); g.fill();

    // Shirt buttons & pleats
    g.fillStyle = '#0F172A';
    for (let y = 140; y <= 320; y += 50) {
      g.beginPath(); g.arc(256, y, 5, 0, Math.PI * 2); g.fill();
    }
  }, [1, 1]);
}

export function createBannerTexture(text, sub, col = '#F59E0B') {
  return canvasTex(`banner_${text}`, 512, 256, (g, w, h) => {
    // Dark background
    g.fillStyle = '#060B14'; g.fillRect(0, 0, w, h);
    g.strokeStyle = col; g.lineWidth = 6; g.strokeRect(6, 6, w - 12, h - 12);

    // Accent header
    g.fillStyle = col; g.fillRect(10, 10, w - 20, 32);
    g.fillStyle = '#030712'; g.font = '900 18px monospace'; g.textAlign = 'center';
    g.fillText('ARENA S04 // CHAMPIONSHIP', w / 2, 32);

    // Main text
    g.fillStyle = '#FFFFFF'; g.font = '900 36px sans-serif';
    g.fillText(text, w / 2, 120);

    // Subtitle
    g.fillStyle = col; g.font = 'bold 20px monospace';
    g.fillText(sub, w / 2, 175);

    // Hazard bottom border
    for (let x = 14; x < w - 20; x += 24) {
      g.fillStyle = col;
      g.fillRect(x, h - 28, 12, 14);
    }
  }, [1, 1]);
}

// ----------------------------------------------------------------------------
// 1. RICH / PRO SPECTATOR AVATAR
// ----------------------------------------------------------------------------
export function buildProSpectator(options = {}) {
  const { seated = false, visorCol = '#00F0FF', lightstickCol = '#FBBF24' } = options;
  const pro = new THREE.Group();
  pro.name = 'ProSpectator';

  const baseY = seated ? 1.0 : 2.0;

  // Torso (Dark titanium armor with gold accents)
  const torsoGroup = new THREE.Group();
  torsoGroup.position.set(0, baseY + 1.0, 0);
  const torso = createBeveledBox(2.0, 2.0, 1.0, 0.04, 2, MATS.armorObsidian);
  torsoGroup.add(torso);

  // Gold Chest Plate Crest
  const chestPlate = new THREE.Mesh(new THREE.BoxGeometry(1.4, 1.2, 0.08), MATS.goldTrim);
  chestPlate.position.set(0, 0.1, 0.52);
  torsoGroup.add(chestPlate);

  // Glowing Cyan Arc Reactor Rune on chest
  const rune = new THREE.Mesh(new THREE.TorusGeometry(0.25, 0.04, 8, 16), MATS.glowCyan);
  rune.position.set(0, 0.1, 0.57);
  torsoGroup.add(rune);

  // Gold Shoulder Pauldrons
  [-1.25, 1.25].forEach(px => {
    const pauldron = createBeveledBox(0.7, 0.35, 1.1, 0.04, 2, MATS.goldTrim);
    pauldron.position.set(px, 0.95, 0);
    torsoGroup.add(pauldron);
  });

  // Black Flowing Cape on back
  const cape = new THREE.Mesh(new THREE.PlaneGeometry(1.6, 2.6), MATS.tuxedoBlack);
  cape.position.set(0, 0.2, -0.55);
  cape.rotation.x = 0.12;
  torsoGroup.add(cape);

  pro.add(torsoGroup);

  // Head with Glowing Cyber Visor & Valkyrie Horns
  const headGroup = new THREE.Group();
  headGroup.position.set(0, baseY + 2.0 + 0.625 + 0.06, 0);
  headGroup.rotation.x = -0.08;

  const head = createBeveledBox(1.25, 1.25, 1.25, 0.04, 2, MATS.skinDarkTitanium);
  headGroup.add(head);

  // Glowing Horizontal Cyber Visor across eyes
  const visorMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(visorCol) });
  const visor = new THREE.Mesh(new THREE.BoxGeometry(1.15, 0.24, 0.12), visorMat);
  visor.position.set(0, 0.08, 0.62);
  headGroup.add(visor);

  // Valkyrie Horns / Cyber Crown
  [-0.6, 0.6].forEach((hx, i) => {
    const horn = new THREE.Mesh(new THREE.ConeGeometry(0.18, 0.9, 8), MATS.goldTrim);
    horn.position.set(hx, 0.7, -0.15);
    horn.rotation.z = (i === 0 ? 0.35 : -0.35);
    horn.rotation.x = -0.25;
    headGroup.add(horn);
  });

  // Head Stud
  const stud = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.32, 0.16, 24), MATS.skinDarkTitanium);
  stud.position.set(0, 1.25 / 2 + 0.08, 0);
  headGroup.add(stud);

  pro.add(headGroup);

  // Right Arm with Lightstick
  const rightArm = new THREE.Group();
  rightArm.position.set(1.5, baseY + 1.8, 0);
  rightArm.rotation.z = Math.PI * 0.65;
  rightArm.rotation.x = -0.1;
  const rArmMesh = createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, MATS.armorObsidian);
  rArmMesh.position.set(0, -0.8, 0);
  rightArm.add(rArmMesh);

  // Lightstick
  const stick = buildLightstickMesh(lightstickCol);
  stick.position.set(0, -1.8, 0.2);
  stick.rotation.z = -Math.PI * 0.45;
  rightArm.add(stick);
  pro.add(rightArm);

  // Left Arm (Leaning / Resting Stance)
  const leftArm = new THREE.Group();
  leftArm.position.set(-1.5, baseY + 1.8, 0);
  leftArm.rotation.z = -0.2;
  leftArm.rotation.x = 0.2;
  const lArmMesh = createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, MATS.armorObsidian);
  lArmMesh.position.set(0, -0.8, 0);
  leftArm.add(lArmMesh);
  pro.add(leftArm);

  // Legs (Titanium greaves)
  const leftLeg = new THREE.Group();
  leftLeg.position.set(-0.5, baseY, 0);
  const rightLeg = new THREE.Group();
  rightLeg.position.set(0.5, baseY, 0);

  if (seated) {
    leftLeg.rotation.x = -Math.PI / 2;
    rightLeg.rotation.x = -Math.PI / 2;
  } else {
    leftLeg.rotation.x = 0.08;
    rightLeg.rotation.x = -0.1;
  }

  leftLeg.add(createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, MATS.armorObsidian).translateY(-1.0));
  rightLeg.add(createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, MATS.armorObsidian).translateY(-1.0));
  pro.add(leftLeg);
  pro.add(rightLeg);

  return pro;
}

// ----------------------------------------------------------------------------
// 2. BACON HAIR / STARTER SPECTATOR AVATAR
// ----------------------------------------------------------------------------
export function buildBaconHairSpectator(options = {}) {
  const { seated = false, lightstickCol = '#00FF88' } = options;
  const bacon = new THREE.Group();
  bacon.name = 'BaconHairSpectator';

  const baseY = seated ? 1.0 : 2.0;

  // Torso: Blue Starter Jacket
  const torsoGroup = new THREE.Group();
  torsoGroup.position.set(0, baseY + 1.0, 0);
  const torso = createBeveledBox(2.0, 2.0, 1.0, 0.04, 2, MATS.starterJacket);
  torsoGroup.add(torso);

  // White V-Stripe Graphic on front
  const stripe = new THREE.Mesh(new THREE.BoxGeometry(0.12, 1.4, 0.02), MATS.coreWhite);
  stripe.position.set(-0.3, 0.1, 0.51);
  stripe.rotation.z = -0.3;
  torsoGroup.add(stripe);
  const stripeR = new THREE.Mesh(new THREE.BoxGeometry(0.12, 1.4, 0.02), MATS.coreWhite);
  stripeR.position.set(0.3, 0.1, 0.51);
  stripeR.rotation.z = 0.3;
  torsoGroup.add(stripeR);

  bacon.add(torsoGroup);

  // Head with Layered Bacon Hair Mesh & Anxious Face
  const headGroup = new THREE.Group();
  headGroup.position.set(0, baseY + 2.0 + 0.625 + 0.06, 0);
  headGroup.rotation.x = -0.12;

  const head = createBeveledBox(1.25, 1.25, 1.25, 0.04, 2, MATS.skinPale);
  headGroup.add(head);

  // Top Stud
  const stud = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.32, 0.16, 24), MATS.skinPale);
  stud.position.set(0, 1.25 / 2 + 0.08, 0);
  headGroup.add(stud);

  // Anxious Decal Face
  const facePlane = new THREE.Mesh(
    new THREE.PlaneGeometry(1.18, 1.18),
    new THREE.MeshBasicMaterial({ map: createBaconHairAnxiousFace(), transparent: true, depthWrite: false })
  );
  facePlane.position.set(0, 0, 1.25 / 2 + 0.005);
  headGroup.add(facePlane);

  // 3D Layered Bacon Hair (Wavy blocky hair strands)
  const hairGroup = new THREE.Group();
  // Central hair crest
  const strandTop = createBeveledBox(1.32, 0.35, 1.35, 0.04, 2, MATS.baconHairBrown);
  strandTop.position.set(0, 0.65, 0);
  hairGroup.add(strandTop);

  // Front wavy bacon strands hanging over forehead
  const strandFront1 = createBeveledBox(0.4, 0.6, 0.3, 0.03, 1, MATS.baconHairHighlight);
  strandFront1.position.set(-0.35, 0.45, 0.62);
  strandFront1.rotation.z = -0.2;
  hairGroup.add(strandFront1);

  const strandFront2 = createBeveledBox(0.45, 0.75, 0.3, 0.03, 1, MATS.baconHairBrown);
  strandFront2.position.set(0.2, 0.38, 0.62);
