  stick.position.set(0, -1.8, 0.2);
  stick.rotation.z = -Math.PI * 0.45;
  rightArm.add(stick);
  bacon.add(rightArm);

  // Left Arm (Nervous fist clench at chest)
  const leftArm = new THREE.Group();
  leftArm.position.set(-1.5, baseY + 1.8, 0);
  leftArm.rotation.z = -0.35;
  leftArm.rotation.x = -0.65;
  const lArmMesh = createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, MATS.skinPale);
  lArmMesh.position.set(0, -0.8, 0);
  leftArm.add(lArmMesh);
  bacon.add(leftArm);

  // Legs: Classic Denim Jeans
  const leftLeg = new THREE.Group(); leftLeg.position.set(-0.5, baseY, 0);
  const rightLeg = new THREE.Group(); rightLeg.position.set(0.5, baseY, 0);
  if (seated) {
    leftLeg.rotation.x = -Math.PI / 2;
    rightLeg.rotation.x = -Math.PI / 2;
  } else {
    leftLeg.rotation.x = 0.1;
    rightLeg.rotation.x = -0.12;
  }
  leftLeg.add(createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, MATS.denimBlue).translateY(-1.0));
  rightLeg.add(createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, MATS.denimBlue).translateY(-1.0));
  bacon.add(leftLeg);
  bacon.add(rightLeg);

  return bacon;
}

