function buildLightstickMesh(colHex) {
  const stick = new THREE.Group();
  const matGlow = new THREE.MeshBasicMaterial({ color: new THREE.Color(colHex) });

  // Handle
  const handle = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.08, 0.45, 12), MATS.darkSteel);
  handle.position.set(0, -0.2, 0);
  stick.add(handle);

  // Neon Tube
  const tube = new THREE.Mesh(new THREE.CylinderGeometry(0.09, 0.09, 1.35, 16), matGlow);
  tube.position.set(0, 0.7, 0);
  stick.add(tube);

  // White Core
  const core = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 1.28, 8), MATS.coreWhite);
  core.position.set(0, 0.7, 0);
  stick.add(core);

  // Tip
  const tip = new THREE.Mesh(new THREE.SphereGeometry(0.09, 12, 12), matGlow);
  tip.position.set(0, 1.38, 0);
  stick.add(tip);

  return stick;
}

