export function buildCheeringBanner(text = 'RICH_BULLY #1', sub = 'EZ CLAP // 3500 HP', col = '#F59E0B') {
  const bannerGroup = new THREE.Group();
  bannerGroup.name = 'CheeringBanner';

  const w = 3.6;
  const h = 1.8;

  const matBanner = new THREE.MeshBasicMaterial({
    map: createBannerTexture(text, sub, col),
    side: THREE.DoubleSide
  });

  const screen = new THREE.Mesh(new THREE.PlaneGeometry(w, h), matBanner);
  bannerGroup.add(screen);

  // Gilded Neon Frame
  const frameMat = new THREE.MeshBasicMaterial({ color: new THREE.Color(col) });
  const frameTop = new THREE.Mesh(new THREE.BoxGeometry(w + 0.1, 0.06, 0.06), frameMat);
  frameTop.position.set(0, h / 2, 0);
  bannerGroup.add(frameTop);

  const frameBot = new THREE.Mesh(new THREE.BoxGeometry(w + 0.1, 0.06, 0.06), frameMat);
  frameBot.position.set(0, -h / 2, 0);
