  [-w / 2 + 0.3, w / 2 - 0.3].forEach(px => {
    const pole = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.04, 2.8, 8), MATS.darkSteel);
    pole.position.set(px, -0.6, -0.05);
    bannerGroup.add(pole);
  });

  return bannerGroup;
}

