  masterCtx.fillText('• STARTER APPAREL: ROYAL BLUE MOTORCYCLE JACKET WITH WHITE V-STRIPE GRAPHIC & DENIM JEANS', col2X, specY + 75 + lineH);
  masterCtx.fillText('• ANXIOUS EXPRESSION: CUSTOM 512×512 WORRIED ROUND EYES & OPEN REACTION MOUTH DECAL', col2X, specY + 75 + lineH * 2);
  masterCtx.fillText('• B-04 VIP ELITE: PRESSED BLACK TUXEDO WITH CRISP WHITE DRESS SHIRT & RED SILK BOWTIE DECAL', col2X, specY + 75 + lineH * 3);
  masterCtx.fillText('• LUXURY ATTIRE: FORMAL BLACK TOP HAT WITH CRIMSON SILK BAND & GILDED RIGHT-EYE MONOCLE', col2X, specY + 75 + lineH * 4);

  // Column 3: Banners & Stadium Deployment
  masterCtx.fillText('• B-05 CHEERING BANNERS: 3.6m×1.8m GLOWING DUAL-SIDED PLACARDS WITH METAL SUPPORT POLES', col3X, specY + 75);
  masterCtx.fillText('• BANNER 1: "RICH_BULLY #1 // EZ CLAP // LVL 99" WITH GILDED AMBER HAZARD BORDERS', col3X, specY + 75 + lineH);
  masterCtx.fillText('• BANNER 2: "BACON HAIR // CLUTCH UP // NOOB POWER" WITH HIGH-ENERGY CYAN GLOW', col3X, specY + 75 + lineH * 2);
  masterCtx.fillText('• MODULAR INSTANCING: ARCHETYPES SUPPORT INSTANCING ACROSS ALL 5 SECTOR 04 BLEACHER TIERS', col3X, specY + 75 + lineH * 3);
  masterCtx.fillText('• ATMOSPHERE: COMBINES WITH DUAL-POSE SYSTEM (SEATED & CHEERING) FOR HYPER-DENSE ARENA CROWDS', col3X, specY + 75 + lineH * 4);

  // Upload Master Sheet
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('audience_roster_master_sheet.png', masterBlob);
  console.log('SAVED: audience_roster_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('AUDIENCE_ROSTER_COMPLETE');
}

