args.Content:
// ============================================================================
// THE GLITCH MARKET — 3D ASSETS: ARENA PERIPHERY & BACKGROUND (BATCH C)
//
// Key Architectural Features:
// 1. Broadcaster Anchor Sky-Tower & Commentary Booth (Cantilevered tower, dish, radar, LIVE ticker)
// 2. Sky-Taxi & VIP Shuttle Docking Platform (18m floating helipad, skybridge, docked hover-cabs)
// 3. Floating Holographic Stadium Sponsor Billboards (3 orbiting monoliths: Blox-Cola, Dominus Bank, Apex Gear)
// 4. Broadcast Micro-Drone Tracking Swarm (Fast camera orbs with trailing cyan/magenta light ribbons)
// 5. Heavy Security Enforcer Skiffs (Patrol hovercraft with flashing blue/red sirens & spotlights)
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createBeveledBox, canvasTex } from './core/geo.js';
import { buildSkyTaxi } from './taxi.js';

// Shared Materials Palette
const MATS = {
  steelDark: new THREE.MeshStandardMaterial({ color: 0x111827, roughness: 0.45, metalness: 0.65 }),
  steelPlate: new THREE.MeshStandardMaterial({ color: 0x1E293B, roughness: 0.35, metalness: 0.7 }),
  titaniumBlack: new THREE.MeshStandardMaterial({ color: 0x090D16, roughness: 0.25, metalness: 0.85 }),
  goldTrim: new THREE.MeshStandardMaterial({ color: 0xF59E0B, roughness: 0.2, metalness: 0.85 }),
  goldGlass: new THREE.MeshStandardMaterial({ color: 0xFBBF24, roughness: 0.1, metalness: 0.9, transparent: true, opacity: 0.75 }),
  hazardAmber: new THREE.MeshBasicMaterial({ color: 0xF59E0B }),
  glowCyan: new THREE.MeshBasicMaterial({ color: 0x00F0FF }),
  glowMagenta: new THREE.MeshBasicMaterial({ color: 0xEC4899 }),
  glowBlue: new THREE.MeshBasicMaterial({ color: 0x2563EB }),
  glowRed: new THREE.MeshBasicMaterial({ color: 0xFF1744 }),
  coreWhite: new THREE.MeshBasicMaterial({ color: 0xFFFFFF }),
};

// ----------------------------------------------------------------------------
// PROCEDURAL TEXTURES FOR PERIPHERY
// ----------------------------------------------------------------------------

export function broadcasterTickerTexture() {
  return canvasTex('broadcaster_ticker', 1024, 128, (g, w, h) => {
    g.fillStyle = '#060B14'; g.fillRect(0, 0, w, h);
    g.strokeStyle = '#00F0FF'; g.lineWidth = 3; g.strokeRect(4, 4, w - 8, h - 8);

    // Recording live dot
    g.fillStyle = '#FF1744';
    g.beginPath(); g.arc(45, h / 2, 16, 0, Math.PI * 2); g.fill();
    g.fillStyle = '#FFFFFF';
    g.beginPath(); g.arc(41, h / 2 - 4, 5, 0, Math.PI * 2); g.fill();

    // LIVE text
    g.fillStyle = '#FF1744';
    g.font = '900 28px sans-serif';
    g.fillText('LIVE', 75, h / 2 + 10);

    // Ticker content
    g.fillStyle = '#00F0FF';
    g.font = '900 24px monospace';
    g.fillText('BLOX-NET SPORTS // SECTOR 04 CHAMPIONSHIP DEATHMATCH // 4.2M VIEWERS // RANKED 1v1', 170, h / 2 + 8);
  }, [1, 1]);
}

export function helipadDockTexture() {
  return canvasTex('helipad_dock', 512, 512, (g, w, h) => {
    g.fillStyle = '#0B1120'; g.fillRect(0, 0, w, h);

    // Outer hazard ring
    const cx = w / 2, cy = h / 2;
    g.strokeStyle = '#F59E0B'; g.lineWidth = 8;
    g.beginPath(); g.arc(cx, cy, 210, 0, Math.PI * 2); g.stroke();

    // Concentric guide circle
    g.strokeStyle = '#00F0FF'; g.lineWidth = 4;
    g.beginPath(); g.arc(cx, cy, 140, 0, Math.PI * 2); g.stroke();

    // Bold [ H ] Helipad / Hover-Pad symbol
    g.fillStyle = '#FBBF24';
    g.font = '900 130px sans-serif';
    g.textAlign = 'center'; g.textBaseline = 'middle';
    g.fillText('H', cx, cy - 6);

    // Bay markings
    g.fillStyle = '#94A3B8';
    g.font = 'bold 24px monospace';
    g.fillText('SKY-DOCK 04', cx, 65);
    g.fillText('VIP / TAXI BERTH', cx, h - 55);
  }, [1, 1]);
}

export function billboardTexture(type = 1) {
  return canvasTex(`billboard_sponsor_${type}`, 1024, 512, (g, w, h) => {
    g.fillStyle = '#040712'; g.fillRect(0, 0, w, h);

    if (type === 1) {
      // BLOX-COLA: Cyan & Electric Amber
      g.strokeStyle = '#00F0FF'; g.lineWidth = 8; g.strokeRect(8, 8, w - 16, h - 16);
      g.fillStyle = '#00F0FF'; g.fillRect(16, 16, w - 32, 60);
      g.fillStyle = '#030712'; g.font = '900 32px sans-serif'; g.textAlign = 'center';
      g.fillText('OFFICIAL DEATHMATCH ENERGY PARTNER', w / 2, 58);

      g.fillStyle = '#F59E0B'; g.font = '900 84px sans-serif';
      g.fillText('BLOX-COLA', w / 2, 200);

      g.fillStyle = '#FFFFFF'; g.font = 'bold 36px monospace';
      g.fillText('+200% STAMINA // INSTANT REGEN', w / 2, 280);

      g.fillStyle = '#38BDF8'; g.font = 'bold 24px monospace';
      g.fillText('CRACK ONE OPEN IN SECTOR 04 CONCOURSE', w / 2, 360);

      // Hazard bar
      for (let x = 24; x < w - 24; x += 40) {
        g.fillStyle = '#F59E0B'; g.fillRect(x, h - 50, 20, 26);
      }
    } else if (type === 2) {
      // DOMINUS BANK: Gold & Titanium
      g.strokeStyle = '#F59E0B'; g.lineWidth = 8; g.strokeRect(8, 8, w - 16, h - 16);
      g.fillStyle = '#F59E0B'; g.fillRect(16, 16, w - 32, 60);
      g.fillStyle = '#030712'; g.font = '900 32px sans-serif'; g.textAlign = 'center';
      g.fillText('THE ROBLOX LUXURY RESERVE', w / 2, 58);

      g.fillStyle = '#FDE68A'; g.font = '900 76px sans-serif';
      g.fillText('DOMINUS BANK', w / 2, 195);

      g.fillStyle = '#94A3B8'; g.font = 'bold 32px monospace';
      g.fillText('INSTANT ROBUX TRANSFERS & ESCROW', w / 2, 275);

      g.fillStyle = '#00F0FF'; g.font = 'bold 24px monospace';
      g.fillText('EXCLUSIVE VAULTS FOR DIAMOND RANK PLAYERS', w / 2, 355);

      // Gold crown studs
      for (let x = 40; x < w - 40; x += 60) {
        g.fillStyle = '#F59E0B';
        g.beginPath(); g.arc(x, h - 38, 10, 0, Math.PI * 2); g.fill();
      }
    } else {
      // APEX SHADOW GEAR: Glitch Purple & Neon Red
      g.strokeStyle = '#8B5CF6'; g.lineWidth = 8; g.strokeRect(8, 8, w - 16, h - 16);
      g.fillStyle = '#8B5CF6'; g.fillRect(16, 16, w - 32, 60);
      g.fillStyle = '#030712'; g.font = '900 30px monospace'; g.textAlign = 'center';
      g.fillText('⚠ CONTRABAND SPECIFICATION // BLACK MARKET', w / 2, 58);

      g.fillStyle = '#C084FC'; g.font = '900 72px sans-serif';
      g.fillText('APEX SHADOW GEAR', w / 2, 195);

      g.fillStyle = '#FF1744'; g.font = '900 32px monospace';
      g.fillText('FORBIDDEN STAT BOOSTS // BREAK THE RULES', w / 2, 275);

      g.fillStyle = '#94A3B8'; g.font = 'bold 22px monospace';
      g.fillText('AVAILABLE AT THE SECRET MARKET FOUNTAIN DRAIN', w / 2, 355);

      // Glitch warning hashes
      for (let x = 24; x < w - 24; x += 36) {
        g.fillStyle = '#FF1744'; g.fillRect(x, h - 48, 18, 24);
      }
    }
  }, [1, 1]);
}

// ----------------------------------------------------------------------------
// 1. BROADCASTER ANCHOR SKY-TOWER & COMMENTARY BOOTH (ASSET C-01)
// ----------------------------------------------------------------------------
export function buildBroadcasterTower() {
  const tower = new THREE.Group();
  tower.name = 'BroadcasterSkyTower';

  // Tower Height: 48m, Width: 10m
  const baseH = 34.0;
  const boothH = 10.0;

  // Heavy Cantilevered Triangular Steel Lattice Mast
  const mast = createBeveledBox(4.5, baseH, 4.5, 0.1, 2, MATS.steelPlate);
  mast.position.set(0, baseH / 2, 0);
  tower.add(mast);

  // Vertical Cyan Conduit Ribs along tower spine
  [-2.28, 2.28].forEach(mx => {
    const spine = new THREE.Mesh(new THREE.BoxGeometry(0.18, baseH, 0.18), MATS.glowCyan);
    spine.position.set(mx, baseH / 2, 0);
    tower.add(spine);
  });

  // Outrigger Structural Support Trusses
  [-1, 1].forEach(side => {
    const truss = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.2, 24.0, 8), MATS.steelDark);
    truss.position.set(side * 6.5, 12.0, 0);
    truss.rotation.z = side * 0.45;
    tower.add(truss);
  });

  // Cantilevered Commentary Room Pod at Top (Octagonal Capsule)
  const boothGroup = new THREE.Group();
  boothGroup.position.set(0, baseH + boothH / 2, 0);

  // Pod Main Shell
  const podBody = createBeveledBox(12.0, boothH, 9.0, 0.15, 2, MATS.titaniumBlack);
  boothGroup.add(podBody);

  // Panoramic Gold-Tinted Viewing Glass
  const glass = new THREE.Mesh(new THREE.BoxGeometry(11.2, 4.2, 0.2), MATS.goldGlass);
  glass.position.set(0, 0.5, 4.52);
  boothGroup.add(glass);

  // Illuminated Broadcaster Digital Ticker
  const tickerMat = new THREE.MeshBasicMaterial({ map: broadcasterTickerTexture() });
  const ticker = new THREE.Mesh(new THREE.PlaneGeometry(11.4, 1.4), tickerMat);
  ticker.position.set(0, -3.2, 4.53);
  boothGroup.add(ticker);

  // Rooftop Satellite Transmitter Dish
  const dish = new THREE.Mesh(new THREE.CylinderGeometry(3.2, 0.4, 1.2, 24), MATS.steelPlate);
  dish.rotation.x = Math.PI / 4;
  dish.rotation.y = -Math.PI / 6;
  dish.position.set(-2.5, boothH / 2 + 1.8, 0);
  boothGroup.add(dish);

  // Dish Feed Horn Emitter
  const horn = new THREE.Mesh(new THREE.ConeGeometry(0.4, 1.6, 8), MATS.glowCyan);
  horn.rotation.x = -Math.PI / 4;
  horn.position.set(-2.5, boothH / 2 + 2.8, 0.8);
  boothGroup.add(horn);

  // High-Altitude Communications Mast with Aviation Beacon
  const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.16, 12.0, 8), MATS.steelPlate);
  antenna.position.set(3.5, boothH / 2 + 6.0, 0);
  boothGroup.add(antenna);

  const beacon = new THREE.Mesh(new THREE.SphereGeometry(0.25, 8, 8), MATS.glowRed);
  beacon.position.set(3.5, boothH / 2 + 12.1, 0);
  boothGroup.add(beacon);

  tower.add(boothGroup);
  return tower;
}

// ----------------------------------------------------------------------------
// 2. SKY-TAXI & VIP SHUTTLE DOCKING PLATFORM (ASSET C-02)
// ----------------------------------------------------------------------------
export function buildDockingPlatform() {
  const dock = new THREE.Group();
  dock.name = 'DockingPlatform';

  const R = 12.0; // Docking platform radius
  const H = 2.4;  // Deck thickness

  // Main Floating Octagonal Platform Body
  const slab = new THREE.Mesh(new THREE.CylinderGeometry(R, R * 1.05, H, 8), MATS.steelPlate);
  slab.position.set(0, H / 2, 0);
  dock.add(slab);

  // Helipad Paved Surface with Custom Decal
  const padMat = new THREE.MeshStandardMaterial({
    map: helipadDockTexture(),
    roughness: 0.5,
    metalness: 0.4
  });
  const padSurface = new THREE.Mesh(new THREE.CylinderGeometry(R * 0.98, R * 0.98, 0.1, 8), padMat);
  padSurface.position.set(0, H + 0.05, 0);
  dock.add(padSurface);

  // Perimeter Luminous Amber Safety Railing
  const rail = new THREE.Mesh(new THREE.CylinderGeometry(R * 1.01, R * 1.01, 0.25, 8, 1, true), MATS.hazardAmber);
  rail.position.set(0, H + 0.8, 0);
  dock.add(rail);

  // Underbelly Anti-Gravity Thruster Pods (4 Repulsors)
  [[-6.5, -6.5], [6.5, -6.5], [-6.5, 6.5], [6.5, 6.5]].forEach(([tx, tz]) => {
    const thruster = new THREE.Mesh(new THREE.CylinderGeometry(1.6, 2.2, 2.8, 12), MATS.steelDark);
    thruster.position.set(tx, -1.4, tz);
    dock.add(thruster);

    const plume = new THREE.Mesh(
      new THREE.ConeGeometry(1.8, 10.0, 12, 1, true),
      new THREE.MeshBasicMaterial({ color: 0x00F0FF, transparent: true, opacity: 0.7, depthWrite: false })
    );
    plume.rotation.x = Math.PI;
    plume.position.set(tx, -6.5, tz);
    dock.add(plume);
  });

  // Docked Yellow Sky-Taxi (CAB-42) Powered Down on Berth 1
  const taxi = buildSkyTaxi();
  taxi.scale.set(1.4, 1.4, 1.4);
  taxi.position.set(-3.8, H + 0.2, 0.5);
  taxi.rotation.y = Math.PI / 4;
  dock.add(taxi);

  // Docked VIP Executive Hover-Shuttle on Berth 2 (Sleek Obsidian/Gold)
  const shuttle = new THREE.Group();
  shuttle.position.set(4.2, H + 1.2, -0.5);
  shuttle.rotation.y = -Math.PI / 5;

  const shuttleBody = createBeveledBox(3.4, 1.5, 6.2, 0.08, 2, MATS.titaniumBlack);
  shuttle.add(shuttleBody);

  const shuttleWindshield = new THREE.Mesh(new THREE.BoxGeometry(2.8, 0.9, 2.4), MATS.goldGlass);
  shuttleWindshield.position.set(0, 0.5, 1.2);
  shuttle.add(shuttleWindshield);

  // VIP Gold Side Flares
  [-1.75, 1.75].forEach(sx => {
    const wing = createBeveledBox(0.4, 0.3, 4.8, 0.04, 1, MATS.goldTrim);
    wing.position.set(sx, -0.2, -0.4);
    shuttle.add(wing);
  });

  dock.add(shuttle);

  // Connecting Skybridge Gantry (extending toward the main stadium)
  const bridge = createBeveledBox(4.5, 3.2, 16.0, 0.08, 2, MATS.steelPlate);
  bridge.position.set(0, H + 1.6, R + 8.0);
  dock.add(bridge);

  const bridgeLights = new THREE.Mesh(new THREE.BoxGeometry(4.3, 0.1, 15.8), MATS.glowCyan);
  bridgeLights.position.set(0, H + 3.2, R + 8.0);
  dock.add(bridgeLights);

  return dock;
}

// ----------------------------------------------------------------------------
// 3. FLOATING HOLOGRAPHIC STADIUM SPONSOR BILLBOARDS (ASSET C-03)
// ----------------------------------------------------------------------------
export function buildSponsorBillboard(sponsorType = 1) {
  const board = new THREE.Group();
  board.name = `SponsorBillboard_${sponsorType}`;

  const w = 12.0;
  const h = 6.0;

  // Dual-Sided Holographic Monolith Screen
  const matScreen = new THREE.MeshBasicMaterial({
    map: billboardTexture(sponsorType),
    side: THREE.DoubleSide
  });
  const screen = new THREE.Mesh(new THREE.PlaneGeometry(w, h), matScreen);
  board.add(screen);

  // Back Screen (facing reverse direction)
  const backScreen = new THREE.Mesh(new THREE.PlaneGeometry(w, h), matScreen);
  backScreen.rotation.y = Math.PI;
  board.add(backScreen);

  // Titanium Beveled Frame
  const frameColor = sponsorType === 1 ? 0x00F0FF : sponsorType === 2 ? 0xF59E0B : 0x8B5CF6;
  const frameMat = new THREE.MeshBasicMaterial({ color: frameColor });

  // Top & Bottom Housing Rails
  [-h / 2, h / 2].forEach(fy => {
    const rail = createBeveledBox(w + 0.8, 0.45, 0.6, 0.04, 1, MATS.titaniumBlack);
    rail.position.set(0, fy, 0);
    board.add(rail);

    const neonStrip = new THREE.Mesh(new THREE.BoxGeometry(w + 0.6, 0.1, 0.65), frameMat);
    neonStrip.position.set(0, fy, 0);
    board.add(neonStrip);
  });

  // Floating Anti-Grav Stabilizer Drones on Left & Right Ends
  [-w / 2 - 0.4, w / 2 + 0.4].forEach(ex => {
    const drone = createBeveledBox(0.8, 2.2, 1.2, 0.05, 1, MATS.steelPlate);
    drone.position.set(ex, 0, 0);
    board.add(drone);

    const thruster = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.35, 0.6, 8), frameMat);
    thruster.position.set(ex, -1.3, 0);
    board.add(thruster);
  });

  return board;
}

// ----------------------------------------------------------------------------
// 4. BROADCAST MICRO-DRONE TRACKING SWARM (ASSET C-04)
// ----------------------------------------------------------------------------
export function buildMicroDrone(glowCol = '#00F0FF') {
  const drone = new THREE.Group();
  drone.name = 'BroadcastMicroDrone';

  const matGlow = new THREE.MeshBasicMaterial({ color: new THREE.Color(glowCol) });

  // Aerodynamic Sphere Core
  const core = new THREE.Mesh(new THREE.SphereGeometry(0.48, 16, 16), MATS.titaniumBlack);
  drone.add(core);

  // Glowing Equatorial Sensor Ring
  const ring = new THREE.Mesh(new THREE.TorusGeometry(0.52, 0.035, 8, 24), matGlow);
  ring.rotation.x = Math.PI / 2;
  drone.add(ring);

  // Telephoto Camera Lens (Forward Facing)
  const lens = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.24, 0.4, 12), MATS.steelPlate);
  lens.rotation.x = Math.PI / 2;
  lens.position.set(0, 0, 0.42);
  drone.add(lens);

  // Blinking Red Recording Tally
  const tally = new THREE.Mesh(new THREE.SphereGeometry(0.08, 8, 8), MATS.glowRed);
  tally.position.set(0, 0.25, 0.44);
  drone.add(tally);

  // Dual Stabilizer Thruster Fins
  [-0.45, 0.45].forEach(fx => {
    const fin = createBeveledBox(0.06, 0.25, 0.5, 0.02, 1, MATS.steelPlate);
    fin.position.set(fx, 0, -0.2);
    drone.add(fin);
  });

  // Trailing Ion Plasma Jet Ribbon behind drone
  const trailMat = new THREE.MeshBasicMaterial({
    color: new THREE.Color(glowCol),
    transparent: true,
    opacity: 0.6,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const trail = new THREE.Mesh(new THREE.PlaneGeometry(0.25, 3.5), trailMat);
  trail.position.set(0, 0, -1.9);
  trail.rotation.x = Math.PI / 2;
  drone.add(trail);

  return drone;
}

// ----------------------------------------------------------------------------
// 5. HEAVY SECURITY ENFORCER SKIFF (ASSET C-05)
// ----------------------------------------------------------------------------
export function buildSecuritySkiff() {
  const skiff = new THREE.Group();
  skiff.name = 'SecurityEnforcerSkiff';

  // Length: 8.5m, Width: 3.8m, Height: 2.2m
  // Angular Police Interceptor Monocoque Chassis
  const hull = createBeveledBox(3.4, 1.6, 7.8, 0.1, 2, MATS.titaniumBlack);
  hull.position.set(0, 0.8, 0);
  skiff.add(hull);

  // Reinforced Armored Cab & Tinted Blue Glass
  const cab = new THREE.Mesh(new THREE.BoxGeometry(2.6, 0.9, 3.6), MATS.steelPlate);
  cab.position.set(0, 1.8, -0.4);
  skiff.add(cab);

  const glass = new THREE.Mesh(new THREE.BoxGeometry(2.5, 0.7, 1.8), MATS.goldGlass);
  glass.position.set(0, 1.85, 0.8);
  skiff.add(glass);

  // Alternating Police Emergency Roof Lightbar (Red / Blue)
  const lightbarGroup = new THREE.Group();
  lightbarGroup.position.set(0, 2.35, -0.4);

  const barHousing = new THREE.Mesh(new THREE.BoxGeometry(2.2, 0.18, 0.4), MATS.steelPlate);
  lightbarGroup.add(barHousing);

  const redBeacon = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.16, 0.35), MATS.glowRed);
  redBeacon.position.set(-0.55, 0.02, 0);
  lightbarGroup.add(redBeacon);

  const blueBeacon = new THREE.Mesh(new THREE.BoxGeometry(0.9, 0.16, 0.35), MATS.glowBlue);
  blueBeacon.position.set(0.55, 0.02, 0);
  lightbarGroup.add(blueBeacon);

  skiff.add(lightbarGroup);

  // Twin Heavy Interceptor Laser Blaster Cannons (Nose Mounted)
  [-1.1, 1.1].forEach(bx => {
    const cannon = new THREE.Mesh(new THREE.CylinderGeometry(0.12, 0.16, 2.2, 12), MATS.steelDark);
    cannon.rotation.x = Math.PI / 2;
    cannon.position.set(bx, 0.6, 3.8);
    skiff.add(cannon);

    const tip = new THREE.Mesh(new THREE.CylinderGeometry(0.14, 0.14, 0.25, 12), MATS.glowCyan);
    tip.rotation.x = Math.PI / 2;
    tip.position.set(bx, 0.6, 4.9);
    skiff.add(tip);
  });

  // High-Powered Scanning Spotlights (Angled downward toward arena)
  [-1.4, 1.4].forEach(sx => {
    const spot = new THREE.Mesh(new THREE.CylinderGeometry(0.3, 0.4, 0.6, 12), MATS.steelPlate);
    spot.rotation.x = Math.PI / 3;
    spot.position.set(sx, 0.2, 2.2);
    skiff.add(spot);

    const lens = new THREE.Mesh(new THREE.SphereGeometry(0.28, 8, 8), MATS.coreWhite);
    lens.position.set(sx, 0.0, 2.45);
    skiff.add(lens);
  });

  // Dual Rear Vector Thrusters with Cyan Plasma Plumes
  [-1.1, 1.1].forEach(rx => {
    const nozzle = new THREE.Mesh(new THREE.CylinderGeometry(0.7, 0.9, 1.4, 16), MATS.steelPlate);
    nozzle.rotation.x = Math.PI / 2;
    nozzle.position.set(rx, 0.8, -4.2);
    skiff.add(nozzle);

    const flame = new THREE.Mesh(
      new THREE.ConeGeometry(0.8, 6.0, 16, 1, true),
      new THREE.MeshBasicMaterial({ color: 0x00F0FF, transparent: true, opacity: 0.75, depthWrite: false })
    );
    flame.rotation.x = -Math.PI / 2;
    flame.position.set(rx, 0.8, -7.2);
    skiff.add(flame);
  });

  return skiff;
}

// ============================================================================
// THE GLITCH MARKET — 5-ANGLE STUDIO AUDIT RENDERER
// BATCH C: ARENA PERIPHERY & BACKGROUND WORLD ASSETS (SHOT 2)
//
// Produces:
// 1. periphery_angle_1_hero.png (View 01: Periphery Panoramic Ensemble)
// 2. periphery_angle_2_tower.png (View 02: Broadcaster Anchor Sky-Tower & Dish)
// 3. periphery_angle_3_dock.png (View 03: Sky-Taxi & VIP Shuttle Docking Platform)
// 4. periphery_angle_4_billboards.png (View 04: Floating Holographic Stadium Sponsor Billboards)
// 5. periphery_angle_5_enforcer.png (View 05: Heavy Security Enforcer Skiff & Micro-Drones)
// 6. periphery_master_sheet.png (2400x1350 5-Panel Master Production Audit Sheet)
// ============================================================================

import * as THREE from 'three';
import { makeEngine } from './core/engine.js';
import {
  buildBroadcasterTower,
  buildDockingPlatform,
  buildSponsorBillboard,
  buildMicroDrone,
  buildSecuritySkiff
} from './arena_periphery.js';

const ANGLES = [
  {
    id: 'periphery_angle_1_hero',
    title: 'VIEW 01: PERIPHERY PANORAMIC ENSEMBLE',
    desc: 'Complete Sector 04 periphery: Broadcaster Sky-Tower, Docking Pad, Billboards & Patrol Skiff',
    pos: [0.0, 18.0, 36.0],
    target: [0.0, 8.0, 0.0],
    fov: 46
  },
  {
    id: 'periphery_angle_2_tower',
    title: 'VIEW 02: BROADCASTER SKY-TOWER & DISH',
    desc: 'Cantilevered commentary room, 4m satellite dish, antenna beacon & LIVE ON BLOX-NET ticker',
    pos: [-10.0, 34.0, 16.0],
    target: [-18.0, 36.0, 0.0],
    fov: 34
  },
  {
    id: 'periphery_angle_3_dock',
    title: 'VIEW 03: SKY-TAXI & VIP DOCKING PLATFORM',
    desc: '18m floating helipad [ H ], docked yellow Sky-Taxi (CAB-42), VIP shuttle, repulsors & skybridge',
    pos: [-8.0, 9.0, 14.0],
    target: [0.0, 3.2, 4.0],
    fov: 38
  },
  {
    id: 'periphery_angle_4_billboards',
    title: 'VIEW 04: HOLOGRAPHIC SPONSOR BILLBOARDS',
    desc: 'Floating 12m×6m ad monoliths: BLOX-COLA, DOMINUS BANK & APEX SHADOW GEAR with drone stabilizers',
    pos: [6.0, 16.0, -1.0],
    target: [6.0, 14.0, -10.0],
    fov: 40
  },
  {
    id: 'periphery_angle_5_enforcer',
    title: 'VIEW 05: SECURITY ENFORCER SKIFF & DRONES',
    desc: '8.5m police patrol hovercraft with flashing red/blue lightbar, nose cannons & micro-camera orbs',
    pos: [21.0, 12.0, 5.0],
    target: [14.0, 10.0, -2.0],
    fov: 36
  }
];

function canvasToBlob(canvas) {
  return new Promise((res) => canvas.toBlob(res, 'image/png'));
}

async function uploadImage(name, blob) {
  await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob,
  });
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Offscreen WebGL Canvas
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const E = makeEngine(glCanvas, { w: 1280, h: 760, samples: 4, shadowSize: 2048 });

  // Build the 3D Showroom Scene
  const scene = new THREE.Scene();
  scene.background = new THREE.Color('#030712');
  scene.fog = new THREE.FogExp2('#060B1C', 0.002);

  // Atmospheric Cyber Lighting
  const keyLight = new THREE.DirectionalLight('#DCEBFA', 3.2);
  keyLight.position.set(30, 55, 35);
  keyLight.target.position.set(0, 10, 0);
  scene.add(keyLight);
  scene.add(keyLight.target);

  const cyanRim = new THREE.DirectionalLight('#00F0FF', 2.8);
  cyanRim.position.set(-30, 20, -25);
  cyanRim.target.position.set(0, 10, 0);
  scene.add(cyanRim);
  scene.add(cyanRim.target);

  const amberFill = new THREE.DirectionalLight('#F59E0B', 1.6);
  amberFill.position.set(25, 15, -30);
  amberFill.target.position.set(0, 10, 0);
  scene.add(amberFill);
  scene.add(amberFill.target);

  const hemi = new THREE.HemisphereLight('#38BDF8', '#070C1A', 0.85);
  scene.add(hemi);

  // Assemble the 5 Periphery Assets
  // 1. Broadcaster Anchor Sky-Tower (C-01)
  const tower = buildBroadcasterTower();
  tower.position.set(-18.0, 0.0, 0.0);
  scene.add(tower);

  // 2. Sky-Taxi & VIP Shuttle Docking Platform (C-02)
  const dock = buildDockingPlatform();
  dock.position.set(0.0, 0.0, 4.0);
  scene.add(dock);

  // 3. Floating Holographic Stadium Sponsor Billboards (C-03)
  const bb1 = buildSponsorBillboard(1); // Blox-Cola
  bb1.position.set(-6.0, 14.0, -10.0);
  scene.add(bb1);

  const bb2 = buildSponsorBillboard(2); // Dominus Bank
  bb2.position.set(6.0, 14.0, -10.0);
  scene.add(bb2);

  const bb3 = buildSponsorBillboard(3); // Apex Shadow Gear
  bb3.position.set(18.0, 14.0, -10.0);
  scene.add(bb3);

  // 4. Heavy Security Enforcer Skiff (C-05)
  const skiff = buildSecuritySkiff();
  skiff.position.set(14.0, 10.0, -2.0);
  skiff.rotation.y = -Math.PI / 4;
  scene.add(skiff);

  // 5. Broadcast Micro-Drone Tracking Swarm (C-04)
  const drone1 = buildMicroDrone('#00F0FF');
  drone1.position.set(8.0, 12.0, 2.0);
  drone1.rotation.y = Math.PI / 3;
  scene.add(drone1);

  const drone2 = buildMicroDrone('#EC4899');
  drone2.position.set(-8.0, 8.0, 6.0);
  drone2.rotation.y = -Math.PI / 4;
  scene.add(drone2);

  const drone3 = buildMicroDrone('#FBBF24');
  drone3.position.set(2.0, 16.0, -4.0);
  drone3.rotation.y = Math.PI / 6;
  scene.add(drone3);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 400);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    // Render WebGL frame
    E.renderer.render(scene, cam);

    // Save individual angle canvas
    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = 1280;
    angleCanvas.height = 760;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Overlay HUD
    actx.fillStyle = 'rgba(3, 7, 18, 0.72)';
    actx.fillRect(20, 20, 580, 54);
    actx.strokeStyle = '#00F0FF';
    actx.lineWidth = 1.5;
    actx.strokeRect(20, 20, 580, 54);

    actx.fillStyle = '#00F0FF';
    actx.font = 'bold 18px monospace';
    actx.fillText(cfg.title, 34, 44);

    actx.fillStyle = '#94A3B8';
    actx.font = '12px monospace';
    actx.fillText(cfg.desc, 34, 62);

    renderedCanvases.push(angleCanvas);

    // Upload individual angle
    const blob = await canvasToBlob(angleCanvas);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png`);
  }

  // --------------------------------------------------------------------------
  // ASSEMBLE 2400 × 1350 MASTER PRODUCTION SHEET
  // --------------------------------------------------------------------------
  masterCtx.fillStyle = '#030712';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Cyber Grid Backdrop
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.05)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < 2400; x += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Master Header
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 34px sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // SHOT 2 ARENA PERIPHERY & BACKGROUND', 45, 55);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText('BATCH C: 5 PERIPHERY WORLD ASSETS & BROADCAST INFRASTRUCTURE — 5-ANGLE AUDIT', 45, 85);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('ASSETS: SKY-TOWER • DOCKING PAD • 3x BILLBOARDS • SECURITY SKIFF • DRONE SWARM', 2355, 55);
  masterCtx.fillText('SECTOR 04 STRATOSPHERE ENVIRONMENT • FULL IN-ENGINE THREE.JS PRODUCTION', 2355, 78);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath(); masterCtx.moveTo(45, 105); masterCtx.lineTo(2355, 105); masterCtx.stroke();

  // Grid Layout:
  // Large Hero on Left: 1420 × 840
  const heroX = 45;
  const heroY = 130;
  const heroW = 1420;
  const heroH = 840;

  masterCtx.drawImage(renderedCanvases[0], heroX, heroY, heroW, heroH);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(heroX, heroY, heroW, heroH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(heroX, heroY + heroH - 48, heroW, 48);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.fillText('VIEW 01: PERIPHERY PANORAMIC ENSEMBLE', heroX + 16, heroY + heroH - 18);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('Broadcaster Sky-Tower, Docking Helipad with Sky-Cabs, Holographic Billboards & Patrol Skiff', heroX + heroW - 16, heroY + heroH - 18);
  masterCtx.textAlign = 'left';

  // 4 Thumbnail Panels on Right (2x2 Grid)
  const rightX = heroX + heroW + 24;
  const rightW = 2400 - rightX - 45;
  const smallCardW = (rightW - 16) / 2;
  const smallCardH = (heroH - 20) / 2;

  const smallGrid = [
    { idx: 1, col: 0, row: 0 },
    { idx: 2, col: 1, row: 0 },
    { idx: 3, col: 0, row: 1 },
    { idx: 4, col: 1, row: 1 },
  ];

  smallGrid.forEach(g => {
    const angleCanvas = renderedCanvases[g.idx];
    const cx = rightX + g.col * (smallCardW + 16);
    const cy = heroY + g.row * (smallCardH + 20);

    masterCtx.fillStyle = '#050914';
    masterCtx.fillRect(cx, cy, smallCardW, smallCardH);
    masterCtx.drawImage(angleCanvas, 0, 0, 1280, 760, cx + 4, cy + 4, smallCardW - 8, smallCardH - 42);

    masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.4)';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(cx, cy, smallCardW, smallCardH);

    masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
    masterCtx.fillRect(cx, cy + smallCardH - 38, smallCardW, 38);
    masterCtx.fillStyle = '#F59E0B';
    masterCtx.font = 'bold 13px monospace';
    masterCtx.fillText(ANGLES[g.idx].title, cx + 12, cy + smallCardH - 14);
  });

  // Bottom Specifications Panel
  const specY = 1000;
  const specH = 300;
  masterCtx.fillStyle = 'rgba(9, 13, 26, 0.85)';
  masterCtx.fillRect(45, specY, 2310, specH);
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.3)';
  masterCtx.lineWidth = 1.5;
  masterCtx.strokeRect(45, specY, 2310, specH);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillText('// ARENA PERIPHERY & BACKGROUND ENGINEERING SPECIFICATIONS', 70, specY + 36);

  const col1X = 70;
  const col2X = 840;
  const col3X = 1600;
  const lineH = 26;

  masterCtx.font = '13px monospace';
  masterCtx.fillStyle = '#E2E8F0';

  // Column 1: C-01 & C-02
  masterCtx.fillText('• C-01 BROADCASTER TOWER: 48m CANTILEVERED STEEL LATTICE SPIRE WITH PANORAMIC GOLD GLASS ROOM', col1X, specY + 75);
  masterCtx.fillText('• BROADCAST TRANSMITTER: 4m SATELLITE DISH, ROTATING RADAR BEACON & 12m ANTENNA MAST WITH RED BEACON', col1X, specY + 75 + lineH);
  masterCtx.fillText('• DIGITAL TICKER: 1024×128 HIGH-LUMINANCE LED BANNER ("LIVE ON BLOX-NET // 4.2M VIEWERS")', col1X, specY + 75 + lineH * 2);
  masterCtx.fillText('• C-02 DOCKING HELIPAD: 18m FLOATING OCTAGONAL DECK WITH [ H ] HOVER-PAD DECAL & AMBER SAFETY RAILS', col1X, specY + 75 + lineH * 3);
  masterCtx.fillText('• BERTH FLEET: 1x YELLOW SKY-TAXI (CAB-42) + 1x SLEEK BLACK/GOLD VIP EXECUTIVE SHUTTLE + SKYBRIDGE', col1X, specY + 75 + lineH * 4);

  // Column 2: C-03 Sponsor Billboards
  masterCtx.fillText('• C-03 SPONSOR BILLBOARDS: 3x 12m×6m FLOATING DUAL-SIDED HOLOGRAPHIC MONOLITHS WITH STABILIZER DRONES', col2X, specY + 75);
  masterCtx.fillText('• BILLBOARD 1: BLOX-COLA ("POWER UP YOUR MANA // 200% STAMINA") IN ELECTRIC CYAN & AMBER', col2X, specY + 75 + lineH);
  masterCtx.fillText('• BILLBOARD 2: DOMINUS BANK ("LUXURY ROBUX RESERVE // INSTANT TRADING") IN METALLIC GOLD', col2X, specY + 75 + lineH * 2);
  masterCtx.fillText('• BILLBOARD 3: APEX SHADOW GEAR ("CONTRABAND STAT BOOSTS // BLACK MARKET") IN GLITCH PURPLE/RED', col2X, specY + 75 + lineH * 3);
  masterCtx.fillText('• ANTI-GRAV STABILIZERS: DUAL WING DRONE UNITS WITH EMISSIVE NEON EDGES MAINTAINING ORBITAL HOVER', col2X, specY + 75 + lineH * 4);

  // Column 3: C-04 & C-05 Security & Swarm
  masterCtx.fillText('• C-04 MICRO-DRONE SWARM: 3x 0.8m FAST-TRACKING CAMERA ORBS WITH HIGH-INTENSITY ION LIGHT RIBBONS', col3X, specY + 75);
  masterCtx.fillText('• TELEPHOTO OPTICS: GIMBALED FORWARD CAMERA LENSES + BLINKING RED TALLY LIGHTS (CYAN/MAGENTA/AMBER)', col3X, specY + 75 + lineH);
  masterCtx.fillText('• C-05 SECURITY SKIFF: 8.5m ANGULAR POLICE INTERCEPTOR WITH BLUE/RED EMERGENCY ROOF LIGHTBAR', col3X, specY + 75 + lineH * 2);
  masterCtx.fillText('• ARMAMENT & RECON: TWIN NOSE LASER CANNONS + HIGH-POWERED DOWNWARD ARENA SCANNING SPOTLIGHTS', col3X, specY + 75 + lineH * 3);
  masterCtx.fillText('• PROPULSION: DUAL HEAVY VECTOR THRUSTERS BLASTING CONTINUOUS CYAN PLASMA JETS INTO THE ABYSS', col3X, specY + 75 + lineH * 4);

  // Upload Master Sheet
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('periphery_master_sheet.png', masterBlob);
  console.log('SAVED: periphery_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('ARENA_PERIPHERY_COMPLETE');
}

window.onload = init;

