// ============================================================================
// THE GLITCH MARKET — 3D ASSETS: BATTLE SCARS & ARENA ATMOSPHERE (BATCH D)
//
// Key Features:
// 1. Cracked Obsidian Impact Crater & Scorch Decals (Radial fractures, smoldering embers, rubble chunks)
// 2. Volumetric Stadium Spotlight Cones (Additive god rays piercing the duel ring)
// 3. Perimeter Pyrotechnic Spark Fountains (Golden spark emitters at pylon bases)
// 4. Distant Lower Abyss Metropolis Backdrop (Grounding Sector 04 in the stratosphere)
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createBeveledBox, canvasTex } from './core/geo.js';

// ----------------------------------------------------------------------------
// 1. PROCEDURAL CRACKED OBSIDIAN CRATER DECAL
// ----------------------------------------------------------------------------
export function createCraterDecalTexture() {
  return canvasTex('arena_crater_scorch', 512, 512, (g, w, h) => {
    g.clearRect(0, 0, w, h);

    const cx = w / 2;
    const cy = h / 2;

    // Dark scorched carbon radial falloff
    const grad = g.createRadialGradient(cx, cy, 10, cx, cy, 240);
    grad.addColorStop(0, 'rgba(5, 7, 14, 0.95)');
    grad.addColorStop(0.35, 'rgba(11, 15, 25, 0.85)');
    grad.addColorStop(0.7, 'rgba(15, 23, 42, 0.45)');
    grad.addColorStop(1, 'rgba(15, 23, 42, 0)');
    g.fillStyle = grad;
    g.beginPath(); g.arc(cx, cy, 240, 0, Math.PI * 2); g.fill();

    // Central Impact Blast Mark (Scorched black crater)
    g.fillStyle = '#020408';
    g.beginPath();
    for (let a = 0; a < Math.PI * 2; a += 0.3) {
      const r = 40 + Math.sin(a * 5) * 12 + Math.cos(a * 3) * 8;
      const x = cx + r * Math.cos(a);
      const y = cy + r * Math.sin(a);
      if (a === 0) g.moveTo(x, y);
      else g.lineTo(x, y);
    }
    g.closePath(); g.fill();

    // Radial Jagged Fractures with Glowing Molten Embers
    const numCracks = 16;
    for (let c = 0; c < numCracks; c++) {
      const baseAngle = (c * Math.PI * 2) / numCracks + (Math.sin(c) * 0.2);
      let curX = cx;
      let curY = cy;
      const maxDist = 80 + (c % 3) * 60 + ((c * 7) % 50);

      // Draw dark crevice
      g.strokeStyle = '#050811';
      g.lineWidth = 6;
      g.lineCap = 'round';
      g.beginPath();
      g.moveTo(curX, curY);

      const segments = 6;
      const pts = [{ x: curX, y: curY }];
      for (let s = 1; s <= segments; s++) {
        const segDist = (maxDist / segments) * s;
        const angleJitter = (Math.sin(s * 1.7 + c) - 0.5) * 0.4;
        const nx = cx + segDist * Math.cos(baseAngle + angleJitter);
        const ny = cy + segDist * Math.sin(baseAngle + angleJitter);
        pts.push({ x: nx, y: ny });
        g.lineTo(nx, ny);
      }
      g.stroke();

      // Draw glowing molten orange/amber ember core in center of crevice
      g.strokeStyle = (c % 2 === 0) ? '#F59E0B' : '#EF4444';
      g.lineWidth = 2.2;
      g.beginPath();
      g.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length - 1; i++) {
        g.lineTo(pts[i].x, pts[i].y);
      }
      g.stroke();

      // Branching minor fissures
      if (c % 2 === 0 && pts.length > 3) {
        g.strokeStyle = '#F97316';
        g.lineWidth = 1.4;
        g.beginPath();
        g.moveTo(pts[2].x, pts[2].y);
        const branchX = pts[2].x + Math.cos(baseAngle + 0.8) * 35;
        const branchY = pts[2].y + Math.sin(baseAngle + 0.8) * 35;
        g.lineTo(branchX, branchY);
        g.stroke();
      }
    }
  }, [1, 1]);
}

/**
 * Builds the 3D Cracked Impact Crater object with rubble chunks
 */
export function buildImpactCrater(radius = 12.0) {
  const crater = new THREE.Group();
  crater.name = 'ImpactCrater';

  // Flat decal plane flush with the combat deck
  const matDecal = new THREE.MeshBasicMaterial({
    map: createCraterDecalTexture(),
    transparent: true,
    depthWrite: false,
    opacity: 0.95
  });

  const decalMesh = new THREE.Mesh(new THREE.PlaneGeometry(radius, radius), matDecal);
  decalMesh.rotation.x = -Math.PI / 2;
  decalMesh.position.set(0, 0.06, 0);
  crater.add(decalMesh);

  // 3D Broken Obsidian Rubble Chunks scattered around impact center
  const matRubble = new THREE.MeshStandardMaterial({
    color: 0x090D16,
    roughness: 0.8,
    metalness: 0.2
  });
  const matEmber = new THREE.MeshBasicMaterial({ color: 0xF59E0B });

  for (let i = 0; i < 14; i++) {
    const angle = (i * Math.PI * 2) / 14 + (i * 0.3);
    const dist = 1.2 + (i % 4) * 0.9;
    const rx = Math.cos(angle) * dist;
    const rz = Math.sin(angle) * dist;

    const rw = 0.35 + (i % 3) * 0.15;
    const rh = 0.18 + (i % 2) * 0.12;
    const rd = 0.3 + ((i * 3) % 3) * 0.15;

    const rock = createBeveledBox(rw, rh, rd, 0.02, 1, matRubble);
    rock.position.set(rx, rh / 2 + 0.06, rz);
    rock.rotation.set((i * 0.4) % 0.8, (i * 0.7) % 3.14, (i * 0.3) % 0.8);
    crater.add(rock);

    // Glowing ember micro-fragment
    if (i % 3 === 0) {
      const ember = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.08, 0.08), matEmber);
      ember.position.set(rx * 0.85, 0.08, rz * 0.85);
      crater.add(ember);
    }
  }

  return crater;
}

// ----------------------------------------------------------------------------
// 2. VOLUMETRIC STADIUM SPOTLIGHT BEAMS
// ----------------------------------------------------------------------------
export function buildVolumetricSpotlights() {
  const rig = new THREE.Group();
  rig.name = 'VolumetricSpotlights';

  // 4 Additive light cones originating from floodlight gantries down to arena deck
  const matBeam = new THREE.MeshBasicMaterial({
    color: 0x38BDF8,
    transparent: true,
    opacity: 0.12,
    blending: THREE.AdditiveBlending,
    depthWrite: false,
    side: THREE.DoubleSide
  });

  const floodlightPos = [
    { x: 36.0, y: 24.0, z: 0.0, target: [6.0, 4.0, 0.0] },
    { x: -36.0, y: 24.0, z: 0.0, target: [-6.0, 4.0, 0.0] },
    { x: 0.0, y: 24.0, z: 36.0, target: [0.0, 4.0, 6.0] },
    { x: 0.0, y: 24.0, z: -36.0, target: [0.0, 4.0, -6.0] },
  ];

  floodlightPos.forEach(f => {
    const origin = new THREE.Vector3(f.x, f.y, f.z);
    const target = new THREE.Vector3(...f.target);
    const dist = origin.distanceTo(target);

    // Conical light beam
    const coneGeo = new THREE.ConeGeometry(9.0, dist, 24, 1, true);
    // Align cone along axis
    coneGeo.translate(0, -dist / 2, 0);
    coneGeo.rotateX(-Math.PI / 2);

    const beam = new THREE.Mesh(coneGeo, matBeam);
    beam.position.copy(origin);
    beam.lookAt(target);
    rig.add(beam);

    // Bright core flare disk at spotlight origin
    const flare = new THREE.Mesh(
      new THREE.SphereGeometry(1.2, 12, 12),
      new THREE.MeshBasicMaterial({ color: 0xF0F9FF, blending: THREE.AdditiveBlending, transparent: true, opacity: 0.85 })
    );
    flare.position.copy(origin);
    rig.add(flare);
  });

  return rig;
}

// ----------------------------------------------------------------------------
// 3. PERIMETER PYROTECHNIC SPARK FOUNTAINS
// ----------------------------------------------------------------------------
export function buildPyrotechnicJets(ringRadius = 30.6) {
  const jets = new THREE.Group();
  jets.name = 'PyrotechnicSparkJets';

  const matSpark = new THREE.MeshBasicMaterial({
    color: 0xFBBF24,
    transparent: true,
    opacity: 0.75,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });

  const matSparkCore = new THREE.MeshBasicMaterial({
    color: 0xFFFFFF,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });

  for (let i = 0; i < 8; i++) {
    const angle = (i * Math.PI * 2) / 8 + Math.PI / 8;
    const px = Math.cos(angle) * ringRadius;
    const pz = Math.sin(angle) * ringRadius;

    // Dual spark fountain plumes shooting up from pylon base
    const plumeH = 7.5;
    const plume = new THREE.Mesh(new THREE.ConeGeometry(0.8, plumeH, 12, 1, true), matSpark);
    plume.position.set(px, 4.0 + plumeH / 2, pz);
    jets.add(plume);

    const core = new THREE.Mesh(new THREE.ConeGeometry(0.3, plumeH * 0.9, 8, 1, true), matSparkCore);
    core.position.set(px, 4.0 + plumeH / 2, pz);
    jets.add(core);

    // Emitter base nozzle
    const nozzle = new THREE.Mesh(
      new THREE.CylinderGeometry(0.25, 0.35, 0.6, 8),
      new THREE.MeshStandardMaterial({ color: 0x1E293B, metalness: 0.8, roughness: 0.3 })
    );
    nozzle.position.set(px, 4.2, pz);
    jets.add(nozzle);
  }

  return jets;
}

// ----------------------------------------------------------------------------
// 4. DISTANT LOWER ABYSS METROPOLIS BACKDROP
// ----------------------------------------------------------------------------
export function buildAbyssMetropolisBackdrop() {
  const abyss = new THREE.Group();
  abyss.name = 'AbyssMetropolisBackdrop';

  const matTowerDark = new THREE.MeshStandardMaterial({
    color: 0x050811,
    roughness: 0.7,
    metalness: 0.3
  });

  const matWindowCyan = new THREE.MeshBasicMaterial({ color: 0x00F0FF });
  const matWindowAmber = new THREE.MeshBasicMaterial({ color: 0xF59E0B });

  // Clusters of distant skyscraper spires in the deep void below (Y = -120 to -240)
  const numClusters = 24;
  for (let i = 0; i < numClusters; i++) {
    const angle = (i * Math.PI * 2) / numClusters + (i * 0.15);
    const dist = 90.0 + (i % 5) * 35.0;
    const tx = Math.cos(angle) * dist;
    const tz = Math.sin(angle) * dist;
    const th = 80.0 + (i % 6) * 45.0;
    const tw = 12.0 + (i % 4) * 6.0;

    const tower = new THREE.Mesh(new THREE.BoxGeometry(tw, th, tw), matTowerDark);
    tower.position.set(tx, -180.0 + th / 2, tz);
    abyss.add(tower);

    // Rooftop cyber beacon / antenna
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.2, 0.4, 25.0, 6), matTowerDark);
    antenna.position.set(tx, -180.0 + th + 12.5, tz);
    abyss.add(antenna);

    const beacon = new THREE.Mesh(
      new THREE.SphereGeometry(0.8, 8, 8),
      i % 2 === 0 ? matWindowCyan : matWindowAmber
    );
    beacon.position.set(tx, -180.0 + th + 25.0, tz);
    abyss.add(beacon);
  }

  // Deep cloud / fog strata floor
  const cloudGeo = new THREE.RingGeometry(60, 350, 32);
  const cloudMat = new THREE.MeshBasicMaterial({
    color: 0x070D1E,
    transparent: true,
    opacity: 0.65,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const cloudDeck = new THREE.Mesh(cloudGeo, cloudMat);
  cloudDeck.rotation.x = -Math.PI / 2;
  cloudDeck.position.set(0, -95.0, 0);
  abyss.add(cloudDeck);

  return abyss;
}

