// ============================================================================
// BATCH D TURNAROUND & ASSET AUDIT: BATTLE SCARS & ARENA ATMOSPHERE
// 5 Targeted Angles for Strict Visual Verification
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { setupStage } from './core/stage.js';
import { createSkySphere } from './core/geo.js';
import {
  buildImpactCrater,
  buildVolumetricSpotlights,
  buildPyrotechnicJets,
  buildAbyssMetropolisBackdrop
} from './arena_effects.js';
import { buildColosseumArena } from './colosseum_arena.js';

const { scene, renderer, camera } = setupStage({
  antialias: true,
  shadows: true,
  cameraPos: [0, 10, 25],
  lookAt: [0, 2, 0],
  fov: 50
});

// Ambient & Core Lighting
const hemiLight = new THREE.HemisphereLight(0x38BDF8, 0x05070F, 0.6);
scene.add(hemiLight);

const dirLight = new THREE.DirectionalLight(0xF8FAFC, 1.2);
dirLight.position.set(25, 45, 20);
scene.add(dirLight);

// Backdrop & Stars
scene.add(createSkySphere(380));

// Build Arena Base Structure (for context)
const arena = buildColosseumArena();
scene.add(arena);

// Add Batch D Assets
const crater = buildImpactCrater(14.0);
crater.position.set(4, 0, -2);
scene.add(crater);

const spotlights = buildVolumetricSpotlights();
scene.add(spotlights);

const pyrojets = buildPyrotechnicJets(30.6);
scene.add(pyrojets);

const abyss = buildAbyssMetropolisBackdrop();
scene.add(abyss);

// Turnaround Camera Angles
export const VIEWS = {
  view_1_crater: {
    name: 'Impact Crater & Scorch Fissures (Macro Hero)',
    pos: [4, 7.5, 4.5],
    look: [4, 0.1, -2],
    fov: 45
  },
  view_2_spotlights: {
    name: 'Volumetric Stadium God Rays (Atmospheric)',
    pos: [-28, 22, 28],
    look: [0, 5, 0],
    fov: 52
  },
  view_3_pyrotechnics: {
    name: 'Perimeter Pyrotechnic Spark Plumes',
    pos: [22, 9, 24],
    look: [28, 6, 12],
    fov: 48
  },
  view_4_abyss: {
    name: 'Distant Abyss Metropolis & Fog Strata',
    pos: [-45, 12, -45],
    look: [0, -35, 0],
    fov: 55
  },
  view_5_master: {
    name: 'Batch D Full Effects Master Integration',
    pos: [0, 16, 42],
    look: [0, 4, 0],
    fov: 50
  }
};

window.renderTurnaroundView = function(viewKey) {
  const cfg = VIEWS[viewKey] || VIEWS.view_1_crater;
  camera.fov = cfg.fov || 50;
  camera.position.set(...cfg.pos);
  camera.lookAt(new THREE.Vector3(...cfg.look));
  camera.updateProjectionMatrix();
  renderer.render(scene, camera);
  return { key: viewKey, name: cfg.name, camera: cfg };
};

// Initial render
renderer.render(scene, camera);
console.log('Batch D Effects Turnaround ready.');

