// ============================================================================
// BATCH D PRODUCTION TURNAROUND & 5-ANGLE ASSET AUDIT
// Category D: Combat Deck Battle Scars & Atmospheric VFX
// ============================================================================

import * as THREE from '../vendor/three.module.js';
import { createSkySphere } from './core/geo.js';
import {
  buildImpactCrater,
  buildVolumetricSpotlights,
  buildPyrotechnicJets,
  buildAbyssMetropolisBackdrop
} from './arena_effects.js';
import { buildColosseumArena } from './colosseum_arena.js';

const ANGLES = [
  {
    id: 'effects_angle_1_crater',
    title: 'D-01 // CRACKED OBSIDIAN IMPACT CRATER & EMBER SCARS',
    desc: 'Radial jagged fissures, glowing molten amber/red ember cores, 3D obsidian rubble',
    pos: [4, 6.5, 4.0],
    target: [4, 0.1, -2.0],
    fov: 46
  },
  {
    id: 'effects_angle_2_spotlights',
    title: 'D-02 // VOLUMETRIC STADIUM SPOTLIGHT BEAMS',
    desc: '4x Additive semi-transparent god ray cones illuminating the combat ring from gantry floodlights',
    pos: [-28, 20, 26],
    target: [0, 4, 0],
    fov: 52
  },
  {
    id: 'effects_angle_3_pyrojets',
    title: 'D-03 // PERIMETER PYROTECHNIC SPARK FOUNTAINS',
    desc: '8x Gold/white dual-plume firework spark jets bursting upwards from pylon bases',
    pos: [22, 8.5, 22],
    target: [28, 6.5, 12],
    fov: 48
  },
  {
    id: 'effects_angle_4_abyss',
    title: 'D-04 // DISTANT ABYSS METROPOLIS & STRATOSPHERE FLOOR',
    desc: '24 Skyscraper spires with cyan/amber beacons & deep fog strata floor (Y = -95 to -240)',
    pos: [-42, 10, -42],
    target: [0, -32, 0],
    fov: 54
  },
  {
    id: 'effects_angle_5_master',
    title: 'BATCH D // FULL ATMOSPHERIC & BATTLE SCAR INTEGRATION',
    desc: 'Duel-stage viewpoint with impact crater, god rays, pyrotechnic jets, and deep abyss towers',
    pos: [0, 14, 38],
    target: [0, 3.5, 0],
    fov: 50
  }
];

function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // Hidden offscreen WebGL renderer
  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const renderer = new THREE.WebGLRenderer({
    canvas: glCanvas,
    antialias: true,
    alpha: false,
    preserveDrawingBuffer: true
  });
  renderer.setSize(1280, 760);
  renderer.setPixelRatio(1);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.25;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x030712);

  // Deep Starfield Sky Sphere
  scene.add(createSkySphere(380));

  // Core Lighting Rig
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x070C1A, 0.7);
  scene.add(hemi);

  const mainLight = new THREE.DirectionalLight(0xF8FAFC, 1.4);
  mainLight.position.set(25, 45, 20);
  scene.add(mainLight);

  const cyanRim = new THREE.DirectionalLight(0x00F0FF, 2.5);
  cyanRim.position.set(-30, 20, -25);
  scene.add(cyanRim);

  // 1. Build Base Colosseum Arena for spatial anchoring
  const arena = buildColosseumArena();
  scene.add(arena);

  // 2. Build Batch D Assets
  // D-01: Impact Crater
  const crater = buildImpactCrater(14.0);
  crater.position.set(4, 0, -2);
  scene.add(crater);

  // D-02: Volumetric Spotlights
  const spotlights = buildVolumetricSpotlights();
  scene.add(spotlights);

  // D-03: Perimeter Pyrotechnic Jets
  const pyrojets = buildPyrotechnicJets(30.6);
  scene.add(pyrojets);

  // D-04: Distant Abyss Metropolis Backdrop
  const abyss = buildAbyssMetropolisBackdrop();
  scene.add(abyss);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 450);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    renderer.render(scene, cam);

    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = 1280;
    angleCanvas.height = 760;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Overlay HUD Title
    actx.fillStyle = 'rgba(3, 7, 18, 0.75)';
    actx.fillRect(20, 20, 620, 54);
    actx.strokeStyle = '#00F0FF';
    actx.lineWidth = 1.5;
    actx.strokeRect(20, 20, 620, 54);

    actx.fillStyle = '#00F0FF';
    actx.font = 'bold 18px monospace';
    actx.fillText(cfg.title, 34, 44);

    actx.fillStyle = '#94A3B8';
    actx.font = '12px monospace';
    actx.fillText(cfg.desc, 34, 62);

    renderedCanvases.push(angleCanvas);

    // Upload individual angle
    const blob = await canvasToBlob(angleCanvas);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png`);
  }

  // --------------------------------------------------------------------------
  // ASSEMBLE 2400 × 1350 MASTER PRODUCTION SHEET
  // --------------------------------------------------------------------------
  masterCtx.fillStyle = '#030712';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Cyber Grid Backdrop
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.05)';
  masterCtx.lineWidth = 1;
  for (let x = 0; x < 2400; x += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += 60) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Master Header
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 34px sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // SHOT 2 BATTLE SCARS & ATMOSPHERE', 45, 55);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText('BATCH D: 4 COMBAT DECK BATTLE SCAR & ATMOSPHERIC ASSETS — 5-ANGLE AUDIT', 45, 85);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('ASSETS: IMPACT CRATER • VOLUMETRIC SPOTLIGHTS • PYRO SPARK JETS • ABYSS TOWERS', 2355, 55);
  masterCtx.fillText('SECTOR 04 STRATOSPHERE ENVIRONMENT • FULL IN-ENGINE THREE.JS PRODUCTION', 2355, 78);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath(); masterCtx.moveTo(45, 105); masterCtx.lineTo(2355, 105); masterCtx.stroke();

  // Grid Layout:
  // Large Hero on Left: 1420 × 840
  const heroX = 45;
  const heroY = 130;
  const heroW = 1420;
  const heroH = 840;

  masterCtx.drawImage(renderedCanvases[0], heroX, heroY, heroW, heroH);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(heroX, heroY, heroW, heroH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(heroX + 16, heroY + 16, 520, 60);
  masterCtx.strokeStyle = '#F59E0B';
