// ----------------------------------------------------------------------------
// 1. PROCEDURAL CRACKED OBSIDIAN CRATER DECAL
// ----------------------------------------------------------------------------
export function createCraterDecalTexture() {
  return canvasTex('arena_crater_scorch', 1024, 1024, (g, w, h) => {
    g.clearRect(0, 0, w, h);

    const cx = w / 2;
    const cy = h / 2;

    // Dark scorched carbon radial falloff
    const grad = g.createRadialGradient(cx, cy, 20, cx, cy, 480);
    grad.addColorStop(0, 'rgba(4, 6, 12, 0.98)');
    grad.addColorStop(0.35, 'rgba(10, 14, 24, 0.90)');
    grad.addColorStop(0.7, 'rgba(15, 23, 42, 0.55)');
    grad.addColorStop(1, 'rgba(15, 23, 42, 0)');
    g.fillStyle = grad;
    g.beginPath(); g.arc(cx, cy, 480, 0, Math.PI * 2); g.fill();

    // Central Heavy Impact Blast Pit (Scorched jagged pit)
    g.fillStyle = '#020306';
    g.beginPath();
    for (let a = 0; a < Math.PI * 2; a += 0.2) {
      const r = 85 + Math.sin(a * 6) * 25 + Math.cos(a * 4) * 16;
      const x = cx + r * Math.cos(a);
      const y = cy + r * Math.sin(a);
      if (a === 0) g.moveTo(x, y);
      else g.lineTo(x, y);
    }
    g.closePath(); g.fill();

    // Radial Jagged Fractures with Glowing Molten Embers
    const numCracks = 18;
    for (let c = 0; c < numCracks; c++) {
      const baseAngle = (c * Math.PI * 2) / numCracks + (Math.sin(c * 1.5) * 0.25);
      let curX = cx;
      let curY = cy;
      const maxDist = 160 + (c % 4) * 85 + ((c * 13) % 90);

      // Draw dark deep crevice
      g.strokeStyle = '#020408';
      g.lineWidth = 10;
      g.lineCap = 'round';
      g.beginPath();
      g.moveTo(curX, curY);

      const segments = 7;
      const pts = [{ x: curX, y: curY }];
      for (let s = 1; s <= segments; s++) {
        const segDist = (maxDist / segments) * s;
        const angleJitter = (Math.sin(s * 2.1 + c) - 0.5) * 0.45;
        const nx = cx + segDist * Math.cos(baseAngle + angleJitter);
        const ny = cy + segDist * Math.sin(baseAngle + angleJitter);
        pts.push({ x: nx, y: ny });
        g.lineTo(nx, ny);
      }
      g.stroke();

      // Outer glow for magma vein
      g.strokeStyle = (c % 2 === 0) ? 'rgba(245, 158, 11, 0.4)' : 'rgba(239, 68, 68, 0.4)';
      g.lineWidth = 5.5;
      g.beginPath();
      g.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) {
        g.lineTo(pts[i].x, pts[i].y);
      }
      g.stroke();

      // Core intense glowing molten orange/amber vein
      g.strokeStyle = (c % 2 === 0) ? '#FCD34D' : '#F87171';
      g.lineWidth = 2.4;
      g.beginPath();
      g.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) {
        g.lineTo(pts[i].x, pts[i].y);
      }
      g.stroke();

      // Branching secondary fissures
      if (c % 2 === 0 && pts.length > 3) {
        g.strokeStyle = '#F59E0B';
        g.lineWidth = 1.8;
        g.beginPath();
        g.moveTo(pts[2].x, pts[2].y);
        const branchX = pts[2].x + Math.cos(baseAngle + 0.85) * 65;
        const branchY = pts[2].y + Math.sin(baseAngle + 0.85) * 65;
        g.lineTo(branchX, branchY);
        g.stroke();
      }
    }
  }, [1, 1]);
}

/**
 * Builds the 3D Cracked Impact Crater object with rubble chunks
 */
export function buildImpactCrater(radius = 12.0) {
  const crater = new THREE.Group();
  crater.name = 'ImpactCrater';

  // Flat decal plane flush with the combat deck
  const matDecal = new THREE.MeshBasicMaterial({
    map: createCraterDecalTexture(),
    transparent: true,
    depthWrite: false,
    polygonOffset: true,
    polygonOffsetFactor: -2,
    polygonOffsetUnits: -2,
    opacity: 0.96
  });

  const decalMesh = new THREE.Mesh(new THREE.PlaneGeometry(radius, radius), matDecal);
  decalMesh.rotation.x = -Math.PI / 2;
  decalMesh.position.set(0, 0.02, 0);
  crater.add(decalMesh);

  // 3D Broken Obsidian Rubble Chunks scattered around impact center
  const matRubble = new THREE.MeshStandardMaterial({
    color: 0x090D16,
    roughness: 0.85,
    metalness: 0.25
  });
  const matEmber = new THREE.MeshBasicMaterial({ color: 0xF59E0B });

  for (let i = 0; i < 18; i++) {
    const angle = (i * Math.PI * 2) / 18 + (i * 0.35);
    const dist = 1.0 + (i % 5) * 0.95;
    const rx = Math.cos(angle) * dist;
    const rz = Math.sin(angle) * dist;

    const rw = 0.4 + (i % 3) * 0.18;
    const rh = 0.22 + (i % 2) * 0.14;
    const rd = 0.35 + ((i * 3) % 3) * 0.16;

    const rock = createBeveledBox(rw, rh, rd, 0.02, 1, matRubble);
    rock.position.set(rx, rh / 2 + 0.03, rz);
    rock.rotation.set((i * 0.4) % 0.8, (i * 0.7) % 3.14, (i * 0.3) % 0.8);
    crater.add(rock);

    // Glowing ember micro-fragment
    if (i % 2 === 0) {
      const ember = new THREE.Mesh(new THREE.BoxGeometry(0.1, 0.1, 0.1), matEmber);
      ember.position.set(rx * 0.88, 0.08, rz * 0.88);
      crater.add(ember);
    }
  }

  return crater;
}

