        const branchX = pts[2].x + Math.cos(baseAngle + 0.8) * 35;
        const branchY = pts[2].y + Math.sin(baseAngle + 0.8) * 35;
        g.lineTo(branchX, branchY);
        g.stroke();
      }
    }
  }, [1, 1]);
}

/**
 * Builds the 3D Cracked Impact Crater object with rubble chunks
 */
export function buildImpactCrater(radius = 12.0) {
  const crater = new THREE.Group();
  crater.name = 'ImpactCrater';

  // Flat decal plane flush with the combat deck
  const matDecal = new THREE.MeshBasicMaterial({
    map: createCraterDecalTexture(),
    transparent: true,
    depthWrite: false,
    opacity: 0.95
  });

  const decalMesh = new THREE.Mesh(new THREE.PlaneGeometry(radius, radius), matDecal);
  decalMesh.rotation.x = -Math.PI / 2;
  decalMesh.position.set(0, 0.06, 0);
  crater.add(decalMesh);

  // 3D Broken Obsidian Rubble Chunks scattered around impact center
  const matRubble = new THREE.MeshStandardMaterial({
    color: 0x090D16,
    roughness: 0.8,
    metalness: 0.2
  });
  const matEmber = new THREE.MeshBasicMaterial({ color: 0xF59E0B });

  for (let i = 0; i < 14; i++) {
    const angle = (i * Math.PI * 2) / 14 + (i * 0.3);
    const dist = 1.2 + (i % 4) * 0.9;
    const rx = Math.cos(angle) * dist;
    const rz = Math.sin(angle) * dist;

    const rw = 0.35 + (i % 3) * 0.15;
    const rh = 0.18 + (i % 2) * 0.12;
    const rd = 0.3 + ((i * 3) % 3) * 0.15;

    const rock = createBeveledBox(rw, rh, rd, 0.02, 1, matRubble);
    rock.position.set(rx, rh / 2 + 0.06, rz);
    rock.rotation.set((i * 0.4) % 0.8, (i * 0.7) % 3.14, (i * 0.3) % 0.8);
    crater.add(rock);

    // Glowing ember micro-fragment
    if (i % 3 === 0) {
      const ember = new THREE.Mesh(new THREE.BoxGeometry(0.08, 0.08, 0.08), matEmber);
      ember.position.set(rx * 0.85, 0.08, rz * 0.85);
      crater.add(ember);
    }
  }

  return crater;
}

