// ----------------------------------------------------------------------------
// 4. DISTANT LOWER ABYSS METROPOLIS BACKDROP
// ----------------------------------------------------------------------------
export function buildAbyssMetropolisBackdrop() {
  const abyss = new THREE.Group();
  abyss.name = 'AbyssMetropolisBackdrop';

  const matTowerDark = new THREE.MeshStandardMaterial({
    color: 0x070B18,
    roughness: 0.7,
    metalness: 0.3
  });

  const matWindowCyan = new THREE.MeshBasicMaterial({ color: 0x00F0FF });
  const matWindowAmber = new THREE.MeshBasicMaterial({ color: 0xF59E0B });
  const matWindowMagenta = new THREE.MeshBasicMaterial({ color: 0xEC4899 });

  // Clusters of distant skyscraper spires in the deep void below (Y = -50 to -220)
  const numClusters = 28;
  for (let i = 0; i < numClusters; i++) {
    const angle = (i * Math.PI * 2) / numClusters + (i * 0.18);
    const dist = 75.0 + (i % 6) * 28.0;
    const tx = Math.cos(angle) * dist;
    const tz = Math.sin(angle) * dist;
    const th = 60.0 + (i % 5) * 24.0; // 60m to 156m tall
    const tw = 12.0 + (i % 4) * 6.0;

    const baseY = -210.0;
    const topY = baseY + th;

    const tower = new THREE.Mesh(new THREE.BoxGeometry(tw, th, tw), matTowerDark);
    tower.position.set(tx, baseY + th / 2, tz);
    abyss.add(tower);

    // Glowing window bands on tower facade
    const numBands = 3 + (i % 3);
    for (let b = 1; b <= numBands; b++) {
      const bandY = baseY + (th / (numBands + 1)) * b;
      const bandMat = (b + i) % 2 === 0 ? matWindowCyan : matWindowAmber;
      const band = new THREE.Mesh(new THREE.BoxGeometry(tw + 0.3, 0.8, tw + 0.3), bandMat);
      band.position.set(tx, bandY, tz);
      abyss.add(band);
    }

    // Rooftop cyber beacon / antenna mast
    const antennaH = 18.0 + (i % 4) * 6.0;
    const antenna = new THREE.Mesh(new THREE.CylinderGeometry(0.25, 0.45, antennaH, 6), matTowerDark);
    antenna.position.set(tx, topY + antennaH / 2, tz);
    abyss.add(antenna);

    const beaconMat = i % 3 === 0 ? matWindowMagenta : (i % 2 === 0 ? matWindowCyan : matWindowAmber);
    const beacon = new THREE.Mesh(
      new THREE.SphereGeometry(1.2, 8, 8),
      beaconMat
    );
    beacon.position.set(tx, topY + antennaH, tz);
    abyss.add(beacon);
  }

  // Deep cloud / fog strata floor
  const cloudGeo = new THREE.RingGeometry(55, 360, 36);
  const cloudMat = new THREE.MeshBasicMaterial({
    color: 0x050B1B,
    transparent: true,
    opacity: 0.72,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const cloudDeck = new THREE.Mesh(cloudGeo, cloudMat);
  cloudDeck.rotation.x = -Math.PI / 2;
  cloudDeck.position.set(0, -95.0, 0);
  abyss.add(cloudDeck);

  return abyss;
}

