      beaconMat
    );
    beacon.position.set(tx, topY + antennaH, tz);
    abyss.add(beacon);
  }

  // Deep cloud / fog strata floor
  const cloudGeo = new THREE.RingGeometry(48, 380, 36);
  const cloudMat = new THREE.MeshBasicMaterial({
