// ============================================================================
// THE GLITCH MARKET — SHOT 2 MASTER PRODUCTION SCENE & INTEGRATION
// SECTOR 04: THE COLOSSEUM DEATHMATCH ARENA (FLOATING PVP RING)
//
// Full Integration of All 4 Completed Batches:
// - Batch A: Core Colosseum Architecture (60m deck, 8 pylons, forcefield, jumbotron HUD, repulsors)
// - Batch B: 3D Spectator Audience (60+ avatars: Noobs, Pros, Bacon Hairs, VIPs, Lightsticks, Banners)
// - Batch C: Periphery & Background (Broadcaster Sky-Tower, Docking Pad, 3 Billboards, Skiff, Drones)
// - Batch D: Battle Scars & Atmosphere (Cracked Crater, Volumetric God Rays, Pyrotechnics, Abyss City)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import { buildColosseumArena } from './colosseum_arena.js';
import { buildNoobAvatar } from './noob_avatar.js';
import {
  buildProSpectator,
  buildBaconHairSpectator,
  buildVipSpectator,
  buildCheeringBanner
} from './spectator_avatars.js';
import {
  buildBroadcasterTower,
  buildDockingPlatform,
  buildSponsorBillboard,
  buildMicroDrone,
  buildSecuritySkiff
} from './arena_periphery.js';
import {
  buildImpactCrater,
  buildVolumetricSpotlights,
  buildPyrotechnicJets,
  buildAbyssMetropolisBackdrop
} from './arena_effects.js';

// Camera Angles Configuration
export const MASTER_ANGLES = [
  {
    id: 'shot2_angle_1_hero_vertical',
