function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

/**
 * Builds and populates the 3D crowd into the arena grandstands
 */
export function populateSpectatorAudience() {
  const crowdGroup = new THREE.Group();
  crowdGroup.name = 'PopulatedSpectatorAudience';

  const lightstickColors = ['#00F0FF', '#EC4899', '#FBBF24', '#00FF88'];

  // Populate 5 Bleacher Tiers
  const standTiers = 5;
  for (let s = 0; s < standTiers; s++) {
    const innerRadius = 34.0 + s * 4.8;
    const tierR = innerRadius + 2.4;
    const tierY = 1.2 + s * 2.2;

    // Number of avatars per tier (increasing outwards)
    const count = 10 + s * 3; // 10, 13, 16, 19, 22 -> 80 avatars total!
    for (let i = 0; i < count; i++) {
      // Angular spacing around amphitheater (leave small gap near docking skybridge)
      const angle = (i * Math.PI * 2) / count + (s * 0.18);
      // Skip quadrant near docking pad gantry (around angle ~ 5.5 to 6.0 rad)
      if (angle > 5.4 && angle < 6.1) continue;

      const px = Math.cos(angle) * tierR;
      const pz = Math.sin(angle) * tierR;

      let avatar;
      const roll = (i + s * 7) % 10;
      const lsCol = lightstickColors[(i + s) % lightstickColors.length];

      if (roll < 4) {
        // Classic Noob Fan (40% of crowd)
        const isSeated = (i % 2 === 0);
        avatar = buildNoobAvatar({ seated: isSeated, lightstickColor: lsCol });
      } else if (roll < 7) {
        // Bacon Hair Starter Spectator (30% of crowd)
        avatar = buildBaconHairSpectator({ lightstickColor: lsCol });
      } else {
        // Rich / Pro Spectator (30% of crowd)
        avatar = buildProSpectator({ lightstickColor: lsCol });
      }

      avatar.position.set(px, tierY, pz);
      // Face toward center ring
      avatar.lookAt(0, tierY, 0);

      // Slight natural orientation jitter
      avatar.rotation.y += (Math.sin(i * 3 + s) * 0.15);
      crowdGroup.add(avatar);
    }
  }

  // Place Holographic Cheering Banners across the bleachers
  const bannerPositions = [
    { tier: 2, angle: 0.5, type: 1 },  // RICH_BULLY #1
    { tier: 3, angle: 1.8, type: 2 },  // BACON HAIR CLUTCH UP
    { tier: 2, angle: 2.9, type: 1 },  // RICH_BULLY #1
    { tier: 4, angle: 3.8, type: 2 },  // BACON HAIR CLUTCH UP
    { tier: 1, angle: 4.8, type: 1 },  // RICH_BULLY #1
  ];

  bannerPositions.forEach(b => {
    const tierR = (34.0 + b.tier * 4.8) + 2.4;
    const tierY = 1.2 + b.tier * 2.2;
    const bx = Math.cos(b.angle) * tierR;
    const bz = Math.sin(b.angle) * tierR;

    const banner = buildCheeringBanner(b.type);
    banner.position.set(bx, tierY, bz);
    banner.lookAt(0, tierY, 0);
    crowdGroup.add(banner);
  });

  // Populate VIP Patrons in the 4 Skyboxes
  for (let i = 0; i < 4; i++) {
    const angle = (i * Math.PI) / 2 + Math.PI / 4;
    const vx = Math.cos(angle) * 44.0;
    const vz = Math.sin(angle) * 44.0;

    const vip1 = buildVipSpectator();
    vip1.position.set(vx - Math.sin(angle) * 1.5, 28.2, vz + Math.cos(angle) * 1.5);
    vip1.lookAt(0, 8.0, 0);
    crowdGroup.add(vip1);

    const vip2 = buildVipSpectator();
    vip2.position.set(vx + Math.sin(angle) * 1.5, 28.2, vz - Math.cos(angle) * 1.5);
    vip2.lookAt(0, 8.0, 0);
    crowdGroup.add(vip2);
  }

  return crowdGroup;
}

/**
 * Builds the complete integrated Shot 2 Colosseum Arena scene
 */
export function buildMasterColosseumScene() {
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x030712);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(500, 500, 420, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 90, 0);
  scene.add(skyDome);

  // Lighting Rig
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x070C1A, 0.85);
  scene.add(hemi);

  const mainSun = new THREE.DirectionalLight(0xF8FAFC, 1.35);
  mainSun.position.set(30, 50, 25);
  scene.add(mainSun);

  const cyanRim = new THREE.DirectionalLight(0x00F0FF, 2.6);
  cyanRim.position.set(-35, 25, -30);
  scene.add(cyanRim);

  const amberWarm = new THREE.DirectionalLight(0xF59E0B, 1.8);
  amberWarm.position.set(30, 20, -35);
  scene.add(amberWarm);

  // ==========================================================================
  // 1. CORE ARENA ARCHITECTURE (BATCH A)
  // ==========================================================================
  const arena = buildColosseumArena();
  scene.add(arena);

  // ==========================================================================
  // 2. POPULATED SPECTATOR AUDIENCE & BANNERS (BATCH B)
  // ==========================================================================
  const crowd = populateSpectatorAudience();
  scene.add(crowd);

  // ==========================================================================
  // 3. ARENA PERIPHERY & BACKGROUND INFRASTRUCTURE (BATCH C)
  // ==========================================================================
  // C-01: Broadcaster Anchor Sky-Tower
  const tower = buildBroadcasterTower();
  tower.position.set(-46.0, 0.0, 30.0);
  tower.rotation.y = -Math.PI / 6;
  scene.add(tower);

  // C-02: Sky-Taxi & VIP Shuttle Docking Platform
  const dock = buildDockingPlatform();
  dock.position.set(44.0, 0.0, -36.0);
  dock.rotation.y = Math.PI * 0.72;
  scene.add(dock);

  // C-03: Floating Holographic Stadium Sponsor Billboards (3 Monoliths)
  const bb1 = buildSponsorBillboard(1); // Blox-Cola
  bb1.position.set(-36.0, 32.0, -28.0);
  bb1.rotation.y = 0.35;
  scene.add(bb1);

  const bb2 = buildSponsorBillboard(2); // Dominus Bank
  bb2.position.set(6.0, 36.0, -48.0);
  bb2.rotation.y = 0.05;
  scene.add(bb2);

  const bb3 = buildSponsorBillboard(3); // Apex Shadow Gear
  bb3.position.set(42.0, 32.0, -22.0);
  bb3.rotation.y = -0.38;
  scene.add(bb3);

  // C-04: Broadcast Micro-Drone Tracking Swarm
  const drone1 = buildMicroDrone('#00F0FF');
  drone1.position.set(10.0, 18.0, 12.0);
  drone1.rotation.y = Math.PI / 4;
  scene.add(drone1);

  const drone2 = buildMicroDrone('#EC4899');
  drone2.position.set(-12.0, 15.0, 16.0);
  drone2.rotation.y = -Math.PI / 3;
  scene.add(drone2);

  const drone3 = buildMicroDrone('#FBBF24');
  drone3.position.set(4.0, 24.0, -14.0);
  drone3.rotation.y = Math.PI / 6;
  scene.add(drone3);

  // C-05: Heavy Security Enforcer Skiff
  const skiff = buildSecuritySkiff();
  skiff.position.set(34.0, 22.0, 24.0);
  skiff.rotation.y = -Math.PI * 0.42;
  scene.add(skiff);

  // ==========================================================================
  // 4. BATTLE SCARS & ARENA ATMOSPHERE (BATCH D)
  // ==========================================================================
  // D-01: Cracked Obsidian Impact Crater
  const crater = buildImpactCrater(14.0);
  crater.position.set(4.0, 4.12, -2.0);
  scene.add(crater);

  // D-02: Volumetric Stadium Spotlight Cones
  const spotlights = buildVolumetricSpotlights();
  scene.add(spotlights);

  // D-03: Perimeter Pyrotechnic Spark Plumes
  const pyrojets = buildPyrotechnicJets(30.6);
  scene.add(pyrojets);

  // D-04: Distant Abyss Metropolis Backdrop
  const abyss = buildAbyssMetropolisBackdrop();
  scene.add(abyss);

  return scene;
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  const scene = buildMasterColosseumScene();

  const renderedCanvases = [];

  // Render All 5 Master Angles
  for (const cfg of MASTER_ANGLES) {
    const glCanvas = document.createElement('canvas');
    glCanvas.width = cfg.width;
    glCanvas.height = cfg.height;

    const renderer = new THREE.WebGLRenderer({
      canvas: glCanvas,
      antialias: true,
      alpha: false,
      preserveDrawingBuffer: true
    });
    renderer.setSize(cfg.width, cfg.height);
    renderer.setPixelRatio(1);
    renderer.toneMapping = THREE.ACESFilmicToneMapping;
    renderer.toneMappingExposure = 1.3;

    const cam = new THREE.PerspectiveCamera(cfg.fov, cfg.width / cfg.height, 0.1, 550);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    renderer.render(scene, cam);

    // Overlay Badge
    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = cfg.width;
    angleCanvas.height = cfg.height;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Semi-transparent badge
    actx.fillStyle = 'rgba(3, 7, 18, 0.78)';
    const badgeW = cfg.aspect === '9:16' ? 720 : 640;
    actx.fillRect(24, 24, badgeW, 64);
    actx.strokeStyle = '#00F0FF';
    actx.lineWidth = 1.8;
    actx.strokeRect(24, 24, badgeW, 64);

    actx.fillStyle = '#00F0FF';
    actx.font = cfg.aspect === '9:16' ? 'bold 22px monospace' : 'bold 18px monospace';
    actx.fillText(cfg.title, 40, 52);

    actx.fillStyle = '#94A3B8';
    actx.font = cfg.aspect === '9:16' ? '14px monospace' : '12px monospace';
    actx.fillText(cfg.desc, 40, 74);

    renderedCanvases.push({ canvas: angleCanvas, cfg });

    // Upload individual angle PNG
    const blob = await canvasToBlob(angleCanvas);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png (${cfg.width}x${cfg.height})`);

    // If it's the vertical hero keyframe, also save as shot2_keyframe_01.png
    if (cfg.id === 'shot2_angle_1_hero_vertical') {
      await uploadImage('shot2_keyframe_01.png', blob);
      console.log('SAVED: shot2_keyframe_01.png');
    }
  }

  // --------------------------------------------------------------------------
  // ASSEMBLE 2400 × 1350 MASTER PRODUCTION SHEET
  // --------------------------------------------------------------------------
  masterCtx.fillStyle = '#030712';
