    { idx: 1, c: 0, r: 0, title: 'ANGLE 2: GRANDSTAND & CROWD PANORAMIC', desc: '60m Arena ring, 60+ avatars, 8 pylons & sky-tower' },
    { idx: 2, c: 1, r: 0, title: 'ANGLE 3: RING-LEVEL DUEL PERSPECTIVE', desc: 'Combat floor, cracked obsidian crater & god rays' },
