// ============================================================================
// THE GLITCH MARKET — 3D ASSETS: THE ARENA CLASH COMBATANTS
//
// 1. LORD KAELEN (The Gilded Dominus Champion // Level 99 Diamond Rank)
//    - Golden Dominus Empyreus Hood with glowing golden eyes
//    - 4-Meter Archangel Feathered Wings & flowing royal crimson cape
//    - Gilded Sunfire Greatsword (radiant white-gold solar blade)
//    - Mid-air dynamic downward diving execution strike pose
//
// 2. VULCAN-99 (The Magma Berserker // Level 99 Grandmaster)
//    - Heavy basalt & obsidian armor with glowing molten red/amber veins
//    - Curved demonic battle horns & blazing molten visor slit
//    - Hellfire Colossus Warhammer (massive basalt hammer with flame sheath)
//    - Deep braced power stance with two-handed overhead parry block
//
// 3. THE CLASH SHOCKWAVE VFX (Ground Zero Impact Point)
//    - Expanding gold/crimson additive shockwave rings
//    - Blinding white contact flash flare & explosive spark debris
// ============================================================================

import * as THREE from 'three';
import { createBeveledBox, canvasTex } from './core/geo.js';

// ----------------------------------------------------------------------------
// PROCEDURAL TEXTURES
// ----------------------------------------------------------------------------

export function createMagmaArmorTexture() {
  return canvasTex('magma_armor_fissures', 512, 512, (g, w, h) => {
    // Dark volcanic basalt base
    g.fillStyle = '#090D18';
    g.fillRect(0, 0, w, h);

    // Subtle basalt texture grain
    g.fillStyle = '#111827';
    for (let i = 0; i < 200; i++) {
      const rx = (i * 37) % w;
      const ry = (i * 73) % h;
      g.fillRect(rx, ry, 3, 3);
    }

    // Glowing Molten Magma Veins
    const numVeins = 10;
    for (let v = 0; v < numVeins; v++) {
      let x = (v * w) / numVeins + 20;
      let y = 0;

      // Dark crevice background
      g.strokeStyle = '#450A0A';
      g.lineWidth = 8;
      g.beginPath();
      g.moveTo(x, y);

      const segments = 8;
      const pts = [{ x, y }];
      for (let s = 1; s <= segments; s++) {
        const ny = (h / segments) * s;
        const nx = x + Math.sin(s * 1.8 + v) * 28;
        pts.push({ x: nx, y: ny });
        g.lineTo(nx, ny);
      }
      g.stroke();

      // Outer orange lava glow
      g.strokeStyle = '#EA580C';
      g.lineWidth = 4.5;
      g.beginPath();
      g.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) g.lineTo(pts[i].x, pts[i].y);
      g.stroke();

      // Molten yellow core vein
      g.strokeStyle = '#FDE047';
      g.lineWidth = 1.8;
      g.beginPath();
      g.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) g.lineTo(pts[i].x, pts[i].y);
      g.stroke();
    }
  }, [1, 1]);
}

export function createGildedFiligreeTexture() {
  return canvasTex('gilded_filigree', 512, 512, (g, w, h) => {
    // Rich royal obsidian & gold plate
    g.fillStyle = '#17130A';
    g.fillRect(0, 0, w, h);

    // Gold borders
    g.strokeStyle = '#F59E0B';
    g.lineWidth = 8;
    g.strokeRect(8, 8, w - 16, h - 16);

    g.strokeStyle = '#FDE047';
    g.lineWidth = 3;
    g.strokeRect(16, 16, w - 32, h - 32);

    // Center imperial crest diamond
    const cx = w / 2;
    const cy = h / 2;
    g.fillStyle = '#F59E0B';
    g.beginPath();
    g.moveTo(cx, cy - 80);
    g.lineTo(cx + 60, cy);
    g.lineTo(cx, cy + 80);
    g.lineTo(cx - 60, cy);
    g.closePath();
    g.fill();

    g.fillStyle = '#FEF08A';
    g.beginPath();
    g.moveTo(cx, cy - 40);
    g.lineTo(cx + 30, cy);
    g.lineTo(cx, cy + 40);
    g.lineTo(cx - 30, cy);
    g.closePath();
    g.fill();
  }, [1, 1]);
}

// ----------------------------------------------------------------------------
// 1. FIGHTER 1: LORD KAELEN (THE GILDED DOMINUS CHAMPION)
// ----------------------------------------------------------------------------
export function buildLordKaelen() {
  const root = new THREE.Group();
  root.name = 'LordKaelen_DominusChampion';

  // Materials
  const matGoldPlate = new THREE.MeshStandardMaterial({
    color: 0xF59E0B,
    metalness: 0.9,
    roughness: 0.18,
    map: createGildedFiligreeTexture()
  });

  const matGoldBright = new THREE.MeshStandardMaterial({
    color: 0xFDE047,
    metalness: 0.92,
    roughness: 0.14
  });

  const matDominusHood = new THREE.MeshStandardMaterial({
    color: 0xD97706,
    metalness: 0.75,
    roughness: 0.25
  });

  const matDeepVoid = new THREE.MeshBasicMaterial({ color: 0x030712 });
  const matGlowGold = new THREE.MeshBasicMaterial({ color: 0xFEF08A });
  const matRoyalCape = new THREE.MeshStandardMaterial({
    color: 0x991B1B,
    roughness: 0.45,
    side: THREE.DoubleSide
  });

  // Base R6 Dimensions: Head 1.25x1.25, Torso 2x2x1, Limbs 1x2x1
  const torso = new THREE.Group();
  torso.name = 'Torso';

  // Torso Block with Gilded Plate
  const torsoMesh = createBeveledBox(2.0, 2.0, 1.0, 0.04, 2, matGoldPlate);
  torso.add(torsoMesh);

  // Diamond Chest Crest
  const crest = new THREE.Mesh(new THREE.OctahedronGeometry(0.35, 0), matGoldBright);
  crest.position.set(0, 0.25, 0.55);
  torso.add(crest);

  // Royal Golden Belt & Buckle
  const belt = new THREE.Mesh(new THREE.BoxGeometry(2.08, 0.25, 1.08), matGoldBright);
  belt.position.set(0, -0.85, 0);
  torso.add(belt);

  // --------------------------------------------------------------------------
  // HEAD & DOMINUS HOOD
  // --------------------------------------------------------------------------
  const headGroup = new THREE.Group();
  headGroup.position.set(0, 1.45, 0);

  // Inner Head Block (Deep shadow inside hood)
  const innerHead = new THREE.Mesh(new THREE.BoxGeometry(1.2, 1.2, 1.2), matDeepVoid);
  headGroup.add(innerHead);

  // Dominus Empyreus Hood (Outer Shell)
  const hoodTop = createBeveledBox(1.5, 0.45, 1.5, 0.05, 2, matDominusHood);
  hoodTop.position.set(0, 0.65, 0);
  headGroup.add(hoodTop);

  const hoodSideL = createBeveledBox(0.2, 1.3, 1.5, 0.04, 2, matDominusHood);
  hoodSideL.position.set(-0.7, 0.05, 0);
  headGroup.add(hoodSideL);

  const hoodSideR = createBeveledBox(0.2, 1.3, 1.5, 0.04, 2, matDominusHood);
  hoodSideR.position.set(0.7, 0.05, 0);
  headGroup.add(hoodSideR);

  const hoodBack = createBeveledBox(1.5, 1.3, 0.25, 0.04, 2, matDominusHood);
  hoodBack.position.set(0, 0.05, -0.65);
  headGroup.add(hoodBack);

  // Front Pointed Peak of Hood
  const peak = new THREE.Mesh(new THREE.ConeGeometry(0.35, 0.6, 4), matGoldBright);
  peak.rotation.y = Math.PI / 4;
  peak.position.set(0, 0.9, 0.45);
  headGroup.add(peak);

  // Piercing Glowing Golden Eyes inside Hood Recess
  const eyeL = new THREE.Mesh(new THREE.SphereGeometry(0.1, 8, 8), matGlowGold);
  eyeL.position.set(-0.28, 0.08, 0.48);
  headGroup.add(eyeL);

  const eyeR = new THREE.Mesh(new THREE.SphereGeometry(0.1, 8, 8), matGlowGold);
  eyeR.position.set(0.28, 0.08, 0.48);
  headGroup.add(eyeR);

  // Golden Eye Flare Trails (Subtle anime glow)
  const eyeTrailL = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.5, 6), matGlowGold);
  eyeTrailL.rotation.x = Math.PI / 2;
  eyeTrailL.position.set(-0.28, 0.08, 0.72);
  headGroup.add(eyeTrailL);

  const eyeTrailR = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.5, 6), matGlowGold);
  eyeTrailR.rotation.x = Math.PI / 2;
  eyeTrailR.position.set(0.28, 0.08, 0.72);
  headGroup.add(eyeTrailR);

  torso.add(headGroup);

  // --------------------------------------------------------------------------
  // 4-METER ARCHANGEL FEATHERED WINGS
  // --------------------------------------------------------------------------
  const wingsGroup = new THREE.Group();
  wingsGroup.position.set(0, 0.4, -0.6);

  const matFeather = new THREE.MeshStandardMaterial({
    color: 0xFFFAED,
    metalness: 0.3,
    roughness: 0.35
  });

  // Build Left and Right Wings
  [-1, 1].forEach(side => {
    const wing = new THREE.Group();
    wing.position.set(side * 0.4, 0, 0);

    // 6 Layered Feathers per wing
    for (let f = 0; f < 6; f++) {
      const featherLen = 1.6 + f * 0.42;
      const featherW = 0.28;
      const fGeo = new THREE.ConeGeometry(featherW, featherLen, 4);
      fGeo.rotateX(-Math.PI / 2);

      const feather = new THREE.Mesh(fGeo, (f % 2 === 0) ? matFeather : matGoldBright);
      feather.position.set(side * (0.4 + f * 0.45), 0.3 + f * 0.32, -f * 0.15);
      feather.rotation.z = side * (-0.35 - f * 0.18);
      feather.rotation.y = side * 0.25;
      wing.add(feather);
    }

    // Wing Shoulder Joint
    const joint = new THREE.Mesh(new THREE.SphereGeometry(0.3, 8, 8), matGoldBright);
    wing.add(joint);

    wingsGroup.add(wing);
  });
  torso.add(wingsGroup);

  // --------------------------------------------------------------------------
  // FLOWING ROYAL CRIMSON CAPE
  // --------------------------------------------------------------------------
  const capeGeo = new THREE.PlaneGeometry(1.6, 3.2, 4, 8);
  // Curve cape backwards as if trailing in a high-speed dive
  const posAttr = capeGeo.attributes.position;
  for (let i = 0; i < posAttr.count; i++) {
    const y = posAttr.getY(i);
    const zOffset = Math.sin((y - 1.6) * 1.2) * 0.45 - (1.6 - y) * 0.25;
    posAttr.setZ(i, zOffset);
  }
  capeGeo.computeVertexNormals();

  const cape = new THREE.Mesh(capeGeo, matRoyalCape);
  cape.position.set(0, -0.4, -0.62);
  cape.rotation.x = 0.35; // Billowing backwards
  torso.add(cape);

  // --------------------------------------------------------------------------
  // DIAMOND PAULDRONS (SHOULDER ARMOR)
  // --------------------------------------------------------------------------
  [-1, 1].forEach(side => {
    const pauldron = new THREE.Group();
    pauldron.position.set(side * 1.35, 0.85, 0);

    const plate = createBeveledBox(0.9, 0.5, 1.1, 0.04, 2, matGoldBright);
    pauldron.add(plate);

    // Upward Spike Flange
    const spike = new THREE.Mesh(new THREE.ConeGeometry(0.2, 0.6, 4), matGoldBright);
    spike.position.set(0, 0.45, 0);
    spike.rotation.z = side * -0.4;
    pauldron.add(spike);

    torso.add(pauldron);
  });

  // --------------------------------------------------------------------------
  // ARMS & DUAL-HANDED SUNFIRE GREATSWORD STRIKE POSE
  // --------------------------------------------------------------------------
  // Left Arm (gripping upper hilt)
  const armL = new THREE.Group();
  armL.position.set(-1.15, 0.75, 0);
  const armLMesh = createBeveledBox(0.85, 1.9, 0.85, 0.035, 2, matGoldPlate);
  armLMesh.position.set(0, -0.75, 0);
  armL.add(armLMesh);

  // Forward strike rotation
  armL.rotation.x = -Math.PI * 0.42;
  armL.rotation.z = -0.35;
  armL.rotation.y = 0.2;
  torso.add(armL);

  // Right Arm (gripping main hilt)
  const armR = new THREE.Group();
  armR.position.set(1.15, 0.75, 0);
  const armRMesh = createBeveledBox(0.85, 1.9, 0.85, 0.035, 2, matGoldPlate);
  armRMesh.position.set(0, -0.75, 0);
  armR.add(armRMesh);

  armR.rotation.x = -Math.PI * 0.48;
  armR.rotation.z = 0.3;
  armR.rotation.y = -0.25;
  torso.add(armR);

  // --------------------------------------------------------------------------
  // WEAPON: GILDED SUNFIRE GREATSWORD
  // --------------------------------------------------------------------------
  const sword = new THREE.Group();
  sword.name = 'SunfireGreatsword';

  // Crossguard with winged quillons
  const crossguard = createBeveledBox(1.8, 0.22, 0.35, 0.03, 2, matGoldBright);
  sword.add(crossguard);

  // Ruby Core Jewel
  const jewel = new THREE.Mesh(
    new THREE.OctahedronGeometry(0.18, 0),
    new THREE.MeshBasicMaterial({ color: 0xEF4444 })
  );
  jewel.position.set(0, 0, 0.2);
  sword.add(jewel);

  // Hilt & Pommel
  const hilt = new THREE.Mesh(
    new THREE.CylinderGeometry(0.1, 0.1, 1.1, 8),
    new THREE.MeshStandardMaterial({ color: 0x1E293B, roughness: 0.6 })
  );
  hilt.position.set(0, -0.65, 0);
  sword.add(hilt);

  const pommel = new THREE.Mesh(new THREE.SphereGeometry(0.2, 8, 8), matGoldBright);
  pommel.position.set(0, -1.25, 0);
  sword.add(pommel);

  // 3.4m Radiant Blade Body
  const bladeMat = new THREE.MeshStandardMaterial({
    color: 0xFEF08A,
    emissive: 0xF59E0B,
    emissiveIntensity: 0.8,
    metalness: 0.8,
    roughness: 0.15
  });
  const blade = createBeveledBox(0.48, 3.4, 0.12, 0.02, 2, bladeMat);
  blade.position.set(0, 1.8, 0);
  sword.add(blade);

  // Blade Tip Point
  const tipGeo = new THREE.ConeGeometry(0.34, 0.8, 4);
  tipGeo.rotateY(Math.PI / 4);
  const tip = new THREE.Mesh(tipGeo, bladeMat);
  tip.position.set(0, 3.8, 0);
  sword.add(tip);

  // Additive Solar Flame Sheath Aura around blade
  const auraMat = new THREE.MeshBasicMaterial({
    color: 0xFBBF24,
    transparent: true,
    opacity: 0.35,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide
  });
  const auraBlade = new THREE.Mesh(new THREE.PlaneGeometry(0.85, 3.8), auraMat);
  auraBlade.position.set(0, 1.9, 0);
  sword.add(auraBlade);

  // Mount Greatsword angled downward in strike orientation
  sword.position.set(0.1, 0.4, 1.2);
  sword.rotation.x = Math.PI * 0.62; // Pointing blade diagonally forward and down
  sword.rotation.z = -0.15;
  torso.add(sword);

  // --------------------------------------------------------------------------
  // LEGS (Diving Tucked Posture)
  // --------------------------------------------------------------------------
  const legL = new THREE.Group();
  legL.position.set(-0.55, -1.0, 0);
  const legLMesh = createBeveledBox(0.9, 2.0, 0.9, 0.035, 2, matGoldPlate);
  legLMesh.position.set(0, -1.0, 0);
  legL.add(legLMesh);
  legL.rotation.x = 0.45; // trailing behind dive
  torso.add(legL);

  const legR = new THREE.Group();
  legR.position.set(0.55, -1.0, 0);
  const legRMesh = createBeveledBox(0.9, 2.0, 0.9, 0.035, 2, matGoldPlate);
  legRMesh.position.set(0, -1.0, 0);
  legR.add(legRMesh);
  legR.rotation.x = 0.6; // slightly offset trailing leg
  torso.add(legR);

  // Attach torso to root
  root.add(torso);

  // Tilt entire body into forward diving strike trajectory
  torso.rotation.x = 0.42;

  return root;
}

