    const plate = createBeveledBox(1.15, 0.65, 1.3, 0.05, 2, matBasaltPlate);
    pauldron.add(plate);

    // Dual Basalt Spikes
    for (let s = -1; s <= 1; s += 2) {
      const spike = new THREE.Mesh(new THREE.ConeGeometry(0.2, 0.7, 4), matCharredSteel);
      spike.position.set(s * 0.25, 0.55, 0);
      spike.rotation.z = side * -0.3;
      pauldron.add(spike);
    }

    // Glowing Lava Crevice on Pauldron
    const pauldronVent = new THREE.Mesh(new THREE.BoxGeometry(0.5, 0.1, 0.7), matLavaAmber);
    pauldronVent.position.set(0, 0.35, 0);
    pauldron.add(pauldronVent);

    torso.add(pauldron);
