  // Left Arm (holding hammer haft overhead)
  const armL = new THREE.Group();
  armL.position.set(-1.3, 0.75, 0);
  const armLMesh = createBeveledBox(0.95, 1.9, 0.95, 0.04, 2, matBasaltPlate);
  armLMesh.position.set(0, -0.75, 0);
  armL.add(armLMesh);

  armL.rotation.x = Math.PI * 0.52;
  armL.rotation.z = -0.45;
  armL.rotation.y = -0.2;
  torso.add(armL);

  // Right Arm (holding hammer head base overhead)
  const armR = new THREE.Group();
  armR.position.set(1.3, 0.75, 0);
  const armRMesh = createBeveledBox(0.95, 1.9, 0.95, 0.04, 2, matBasaltPlate);
  armRMesh.position.set(0, -0.75, 0);
  armR.add(armRMesh);

  armR.rotation.x = Math.PI * 0.48;
  armR.rotation.z = 0.42;
  armR.rotation.y = 0.25;
  torso.add(armR);

  // --------------------------------------------------------------------------
  // WEAPON: HELLFIRE COLOSSUS WARHAMMER
