  const haft = new THREE.Mesh(
    new THREE.CylinderGeometry(0.16, 0.18, 4.2, 8),
    matCharredSteel
  );
  haft.rotation.z = Math.PI / 2; // Horizontal overhead parry bar
  hammer.add(haft);

  // Colossal Basalt Hammerhead (1.6m x 1.4m x 2.2m)
  const hammerhead = new THREE.Group();
  hammerhead.position.set(1.8, 0, 0);

  const block = createBeveledBox(1.5, 1.3, 2.0, 0.06, 2, matBasaltPlate);
  hammerhead.add(block);

  // Front Smashing Face (Magma glowing teeth)
  const faceMat = new THREE.MeshBasicMaterial({ color: 0xFF5722 });
  const faceGlow = new THREE.Mesh(new THREE.BoxGeometry(0.1, 1.1, 1.7), faceMat);
  faceGlow.position.set(0.76, 0, 0);
  hammerhead.add(faceGlow);

  // Rear Basalt Armor-Piercing Spike
  const rearSpike = new THREE.Mesh(new THREE.ConeGeometry(0.45, 1.1, 4), matCharredSteel);
  rearSpike.rotation.z = Math.PI / 2;
  rearSpike.position.set(-1.25, 0, 0);
