    new THREE.ConeGeometry(1.2, 2.4, 8),
    new THREE.MeshBasicMaterial({
      color: 0xF97316,
      transparent: true,
      opacity: 0.55,
      blending: THREE.AdditiveBlending
    })
  );
  firePlume.position.set(0, 1.2, 0);
  hammerhead.add(firePlume);

  hammer.add(hammerhead);

  // Position hammer horizontally above head in defensive brace
  hammer.position.set(-0.2, 2.65, 0.65);
  hammer.rotation.y = 0.22;
  torso.add(hammer);

  // --------------------------------------------------------------------------
  // LEGS IN WIDE BRACED POWER STANCE
  // --------------------------------------------------------------------------
  // Left Leg (braced outward)
  const legL = new THREE.Group();
  legL.position.set(-0.7, -1.0, 0);
  const legLMesh = createBeveledBox(1.0, 2.1, 1.0, 0.04, 2, matBasaltPlate);
  legLMesh.position.set(0, -1.0, 0);
  legL.add(legLMesh);
  legL.rotation.z = 0.28; // splayed outward
  legL.rotation.x = -0.22; // planted back
  torso.add(legL);

  // Right Leg (forward anchor)
  const legR = new THREE.Group();
  legR.position.set(0.7, -1.0, 0);
  const legRMesh = createBeveledBox(1.0, 2.1, 1.0, 0.04, 2, matBasaltPlate);
  legRMesh.position.set(0, -1.0, 0);
  legR.add(legRMesh);
  legR.rotation.z = -0.26;
  legR.rotation.x = 0.32; // braced forward
  torso.add(legR);

  root.add(torso);

  // Deep stance tilt
  torso.position.y = 0.2;
  torso.rotation.x = -0.15; // leaning into the impact

  return root;
}

// ----------------------------------------------------------------------------
// 3. THE CLASH SHOCKWAVE VFX (EXPLOSIVE CONTACT SYSTEM)
// ----------------------------------------------------------------------------
export function buildClashShockwave() {
  const shock = new THREE.Group();
  shock.name = 'ClashShockwaveSystem';

  // 1. Primary Blinding Impact Contact Core (White-Hot)
  const coreFlash = new THREE.Mesh(
    new THREE.SphereGeometry(0.75, 16, 16),
    new THREE.MeshBasicMaterial({ color: 0xFFFFFF })
  );
  shock.add(coreFlash);

  // 2. High-Energy Spherical Plasma Halo (Golden Solar + Flame Red)
  const haloMat = new THREE.MeshBasicMaterial({
    color: 0xFDE047,
    transparent: true,
    opacity: 0.85,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });
  const halo = new THREE.Mesh(new THREE.SphereGeometry(1.6, 16, 16), haloMat);
  shock.add(halo);

  // 3. Expanding Horizontal Shockwave Ring (Ground Zero Ripple)
  const ringMatGold = new THREE.MeshBasicMaterial({
    color: 0xF59E0B,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const shockRing1 = new THREE.Mesh(new THREE.RingGeometry(2.2, 3.8, 32), ringMatGold);
  shockRing1.rotation.x = Math.PI / 2;
  shock.add(shockRing1);

  const ringMatRed = new THREE.MeshBasicMaterial({
    color: 0xEF4444,
    transparent: true,
    opacity: 0.75,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const shockRing2 = new THREE.Mesh(new THREE.RingGeometry(3.6, 5.4, 32), ringMatRed);
  shockRing2.rotation.x = Math.PI / 2;
  shock.add(shockRing2);

  // 4. Vertical Lens Flare Cross / Star Spikes
  const spikeMat = new THREE.MeshBasicMaterial({
    color: 0xFEF08A,
    transparent: true,
    opacity: 0.8,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const spikeH = new THREE.Mesh(new THREE.PlaneGeometry(7.0, 0.45), spikeMat);
  shock.add(spikeH);

  const spikeV = new THREE.Mesh(new THREE.PlaneGeometry(0.45, 7.0), spikeMat);
  shock.add(spikeV);

  // 5. Radial Flying Spark Shards & Magma Splinters
  const sparkMat = new THREE.MeshBasicMaterial({
    color: 0xFCD34D,
    blending: THREE.AdditiveBlending
  });
  for (let i = 0; i < 28; i++) {
    const angle = (i * Math.PI * 2) / 28 + (i * 0.2);
    const dist = 1.4 + (i % 5) * 0.7;
    const sx = Math.cos(angle) * dist;
    const sy = ((i % 4) - 1.5) * 0.6;
    const sz = Math.sin(angle) * dist;

    const spark = new THREE.Mesh(new THREE.BoxGeometry(0.12, 0.12, 0.5), sparkMat);
    spark.position.set(sx, sy, sz);
    spark.lookAt(0, 0, 0);
    shock.add(spark);
  }

  return shock;
}

// ----------------------------------------------------------------------------
// 4. MASTER COMBAT CLASH DUO RIG
// Combines Lord Kaelen, Vulcan-99, and the Clash Shockwave at Ground Zero
// ----------------------------------------------------------------------------
export function buildArenaClashDuo() {
  const duelRig = new THREE.Group();
  duelRig.name = 'ArenaClashDuo';

  // Position Vulcan planted in the crater center
  const vulcan = buildVulcanBerserker();
  vulcan.position.set(0, 0, -0.6);
  vulcan.rotation.y = 0.15; // Facing toward Kaelen's dive
  duelRig.add(vulcan);

  // Position Lord Kaelen diving from above
  const kaelen = buildLordKaelen();
  kaelen.position.set(0.15, 2.75, 1.45);
  kaelen.rotation.y = Math.PI - 0.15; // Facing toward Vulcan
  duelRig.add(kaelen);

  // Position the Clash Shockwave right at the weapon collision point
  const shockwave = buildClashShockwave();
  shockwave.position.set(0.08, 2.85, 0.35);
  duelRig.add(shockwave);

  // High-Intensity Clash Point Light (illuminates both combatants)
  const clashLight = new THREE.PointLight(0xFDE047, 4.5, 18.0);
  clashLight.position.set(0.08, 2.85, 0.35);
  duelRig.add(clashLight);

  return duelRig;
}

