args.Content:
// ============================================================================
// THE GLITCH MARKET — 3D ASSETS: DYNAMIC ARENA SPRINT & MID-AIR CLASH
//
// BATCH 1: LORD KAELEN — THE GILDED ARCHON
// - K-01: Celestial Archon Halo & Sunfire Spikes (Floating radiant torus + 8 rays)
// - K-02: Dominus Empyreus Hood & Glowing Gold Eyes with Anime Flare Trails
// - K-03: Gilded Emperor Plate Armor, Diamond Pauldrons & Flowing Crimson Cape
// - K-04: 6-Tier Archangel Seraphim Wings (4.6m wingspan with gold borders)
// - K-05: Gilded Sunfire Greatsword & Swirling Solar Flare Vortex VFX
// - K-06: Golden Kinetic Sprint Trail & Takeoff Launch Shockwave Ring
//
// BATCH 2: VULCAN-99 — THE MAGMA BERSERKER
// - V-01: Demonic Horned Juggernaut Battle Helm & Pulsing Molten Visor Slit
// - V-02: Volcanic Basalt Plate Armor with Glowing Molten Fissures & Lava Core
// - V-03: Spiked Magma Pauldrons with Active Fire Plume Emitters
// - V-04: Hellfire Colossus Warhammer with Swirling Magma Flame Vortex VFX
// - V-05: Molten Kinetic Sprint Trail & Cracked Basalt Takeoff Pit
//
// BATCH 3: MID-AIR KINETIC COLLISION & ARENA CLASH VFX
// - C-01: Blinding Contact Point Flash & 8m Lens Flare Star Spikes
// - C-02: Dual-Tone Expanding Spherical Clash Shockwave (Gold + Crimson)
// - C-03: 36 Radial Flying Solar Shards & Magma Splinters
// - C-04: Ground-Level Impact Ripple propagating onto the Crater
// - C-05: Dynamic Opposing Clash Point Lighting (Gold vs Fire)
// ============================================================================

import * as THREE from 'three';
import { createBeveledBox, canvasTex } from './core/geo.js';

// ----------------------------------------------------------------------------
// PROCEDURAL TEXTURES
// ----------------------------------------------------------------------------

export function createMagmaArmorTexture() {
  return canvasTex('magma_armor_fissures', 512, 512, (g, w, h) => {
    // Dark volcanic basalt bedrock
    g.fillStyle = '#080C16';
    g.fillRect(0, 0, w, h);

    // Basalt grain texture
    g.fillStyle = '#0F172A';
    for (let i = 0; i < 300; i++) {
      const rx = (i * 43) % w;
      const ry = (i * 67) % h;
      g.fillRect(rx, ry, 3, 3);
    }

    // Glowing Molten Magma Veins
    const numVeins = 12;
    for (let v = 0; v < numVeins; v++) {
      let x = (v * w) / numVeins + 15;
      let y = 0;

      // Dark crevice background
      g.strokeStyle = '#3E0808';
      g.lineWidth = 10;
      g.beginPath();
      g.moveTo(x, y);

      const segments = 8;
      const pts = [{ x, y }];
      for (let s = 1; s <= segments; s++) {
        const ny = (h / segments) * s;
        const nx = x + Math.sin(s * 1.9 + v) * 32;
        pts.push({ x: nx, y: ny });
        g.lineTo(nx, ny);
      }
      g.stroke();

      // Outer crimson/orange lava glow
      g.strokeStyle = '#EA580C';
      g.lineWidth = 5.0;
      g.beginPath();
      g.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) g.lineTo(pts[i].x, pts[i].y);
      g.stroke();

      // Core molten yellow/white heat vein
      g.strokeStyle = '#FDE047';
      g.lineWidth = 2.0;
      g.beginPath();
      g.moveTo(pts[0].x, pts[0].y);
      for (let i = 1; i < pts.length; i++) g.lineTo(pts[i].x, pts[i].y);
      g.stroke();
    }
  }, [1, 1]);
}

export function createGildedFiligreeTexture() {
  return canvasTex('gilded_filigree', 512, 512, (g, w, h) => {
    // Deep obsidian gold background
    g.fillStyle = '#141008';
    g.fillRect(0, 0, w, h);

    // Outer double gold border
    g.strokeStyle = '#F59E0B';
    g.lineWidth = 8;
    g.strokeRect(8, 8, w - 16, h - 16);

    g.strokeStyle = '#FEF08A';
    g.lineWidth = 2.5;
    g.strokeRect(18, 18, w - 36, h - 36);

    // Center imperial sun diamond
    const cx = w / 2;
    const cy = h / 2;
    g.fillStyle = '#F59E0B';
    g.beginPath();
    g.moveTo(cx, cy - 90);
    g.lineTo(cx + 65, cy);
    g.lineTo(cx, cy + 90);
    g.lineTo(cx - 65, cy);
    g.closePath();
    g.fill();

    g.fillStyle = '#FEF08A';
    g.beginPath();
    g.moveTo(cx, cy - 45);
    g.lineTo(cx + 32, cy);
    g.lineTo(cx, cy + 45);
    g.lineTo(cx - 32, cy);
    g.closePath();
    g.fill();
  }, [1, 1]);
}

// ----------------------------------------------------------------------------
// BATCH 1: LORD KAELEN — THE GILDED ARCHON
// ----------------------------------------------------------------------------

/**
 * K-01: Celestial Archon Halo & Sunfire Ray Spikes
 */
export function buildCelestialHalo() {
  const haloGroup = new THREE.Group();
  haloGroup.name = 'CelestialArchonHalo';

  // Floating Golden Torus Ring
  const torusGeo = new THREE.TorusGeometry(0.85, 0.07, 12, 36);
  const matHalo = new THREE.MeshBasicMaterial({
    color: 0xFEF08A,
    transparent: true,
    opacity: 0.95
  });
  const torus = new THREE.Mesh(torusGeo, matHalo);
  torus.rotation.x = Math.PI / 2;
  haloGroup.add(torus);

  // 8 Orbital Sunfire Ray Spikes radiating outward
  const matRay = new THREE.MeshBasicMaterial({
    color: 0xFDE047,
    blending: THREE.AdditiveBlending
  });
  for (let i = 0; i < 8; i++) {
    const angle = (i * Math.PI * 2) / 8;
    const spike = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.45, 4), matRay);
    spike.position.set(Math.cos(angle) * 1.05, 0, Math.sin(angle) * 1.05);
    spike.rotation.z = -angle + Math.PI / 2;
    spike.rotation.x = Math.PI / 2;
    haloGroup.add(spike);
  }

  // Inner Additive Solar Bloom Disc
  const bloomMat = new THREE.MeshBasicMaterial({
    color: 0xF59E0B,
    transparent: true,
    opacity: 0.35,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide
  });
  const bloomDisc = new THREE.Mesh(new THREE.RingGeometry(0.2, 0.85, 24), bloomMat);
  bloomDisc.rotation.x = Math.PI / 2;
  haloGroup.add(bloomDisc);

  return haloGroup;
}

/**
 * Builds Full Lord Kaelen Character Rig
 */
export function buildLordKaelen(options = {}) {
  const root = new THREE.Group();
  root.name = 'LordKaelen_GildedArchon';

  // Materials
  const matGoldPlate = new THREE.MeshStandardMaterial({
    color: 0xF59E0B,
    metalness: 0.94,
    roughness: 0.14,
    map: createGildedFiligreeTexture()
  });

  const matGoldBright = new THREE.MeshStandardMaterial({
    color: 0xFDE047,
    metalness: 0.92,
    roughness: 0.12
  });

  const matDominusHood = new THREE.MeshStandardMaterial({
    color: 0xD97706,
    metalness: 0.78,
    roughness: 0.22
  });

  const matDeepVoid = new THREE.MeshBasicMaterial({ color: 0x020408 });
  const matGlowGold = new THREE.MeshBasicMaterial({ color: 0xFEF08A });
  const matRoyalCape = new THREE.MeshStandardMaterial({
    color: 0x991B1B,
    roughness: 0.4,
    side: THREE.DoubleSide
  });

  const torso = new THREE.Group();
  torso.name = 'Torso';

  // Torso Block
  const torsoMesh = createBeveledBox(2.0, 2.0, 1.0, 0.04, 2, matGoldPlate);
  torso.add(torsoMesh);

  // Imperial Diamond Crest
  const crest = new THREE.Mesh(new THREE.OctahedronGeometry(0.38, 0), matGoldBright);
  crest.position.set(0, 0.25, 0.55);
  torso.add(crest);

  // Layered Hip Faulds (Waist Tassets)
  [-1, 1].forEach(side => {
    const fauld = createBeveledBox(0.45, 0.85, 0.2, 0.03, 2, matGoldBright);
    fauld.position.set(side * 1.05, -0.95, 0);
    fauld.rotation.z = side * -0.18;
    torso.add(fauld);
  });

  // --------------------------------------------------------------------------
  // K-02: HEAD & DOMINUS EMPYREUS HOOD
  // --------------------------------------------------------------------------
  const headGroup = new THREE.Group();
  headGroup.position.set(0, 1.45, 0);

  // Inner Deep Void
  const innerHead = new THREE.Mesh(new THREE.BoxGeometry(1.2, 1.2, 1.2), matDeepVoid);
  headGroup.add(innerHead);

  // Hood Outer Shell
  const hoodTop = createBeveledBox(1.5, 0.45, 1.5, 0.05, 2, matDominusHood);
  hoodTop.position.set(0, 0.65, 0);
  headGroup.add(hoodTop);

  const hoodSideL = createBeveledBox(0.22, 1.3, 1.5, 0.04, 2, matDominusHood);
  hoodSideL.position.set(-0.7, 0.05, 0);
  headGroup.add(hoodSideL);

  const hoodSideR = createBeveledBox(0.22, 1.3, 1.5, 0.04, 2, matDominusHood);
  hoodSideR.position.set(0.7, 0.05, 0);
  headGroup.add(hoodSideR);

  const hoodBack = createBeveledBox(1.5, 1.3, 0.25, 0.04, 2, matDominusHood);
  hoodBack.position.set(0, 0.05, -0.65);
  headGroup.add(hoodBack);

  // Front Pointed Peak
  const peak = new THREE.Mesh(new THREE.ConeGeometry(0.35, 0.65, 4), matGoldBright);
  peak.rotation.y = Math.PI / 4;
  peak.position.set(0, 0.92, 0.48);
  headGroup.add(peak);

  // Glowing Golden Eyes inside Hood Recess
  const eyeL = new THREE.Mesh(new THREE.SphereGeometry(0.11, 8, 8), matGlowGold);
  eyeL.position.set(-0.28, 0.1, 0.5);
  headGroup.add(eyeL);

  const eyeR = new THREE.Mesh(new THREE.SphereGeometry(0.11, 8, 8), matGlowGold);
  eyeR.position.set(0.28, 0.1, 0.5);
  headGroup.add(eyeR);

  // Anime Eye Flare Beams streaming forward
  const eyeTrailL = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.6, 6), matGlowGold);
  eyeTrailL.rotation.x = Math.PI / 2;
  eyeTrailL.position.set(-0.28, 0.1, 0.8);
  headGroup.add(eyeTrailL);

  const eyeTrailR = new THREE.Mesh(new THREE.ConeGeometry(0.08, 0.6, 6), matGlowGold);
  eyeTrailR.rotation.x = Math.PI / 2;
  eyeTrailR.position.set(0.28, 0.1, 0.8);
  headGroup.add(eyeTrailR);

  // K-01: Celestial Archon Halo floating above hood
  const halo = buildCelestialHalo();
  halo.position.set(0, 1.35, -0.1);
  halo.rotation.x = -0.25; // angled with dive
  headGroup.add(halo);

  torso.add(headGroup);

  // --------------------------------------------------------------------------
  // K-04: 6-TIER ARCHANGEL SERAPHIM WINGS (4.6m WINGSPAN)
  // --------------------------------------------------------------------------
  const wingsGroup = new THREE.Group();
  wingsGroup.position.set(0, 0.45, -0.62);

  const matFeather = new THREE.MeshStandardMaterial({
    color: 0xFFFBF0,
    metalness: 0.25,
    roughness: 0.3
  });

  [-1, 1].forEach(side => {
    const wing = new THREE.Group();
    wing.position.set(side * 0.42, 0, 0);

    // 6 Layered Articulated Feathers
    for (let f = 0; f < 6; f++) {
      const featherLen = 1.8 + f * 0.45;
      const featherW = 0.3;
      const fGeo = new THREE.ConeGeometry(featherW, featherLen, 4);
      fGeo.rotateX(-Math.PI / 2);

      const feather = new THREE.Mesh(fGeo, (f % 2 === 0) ? matFeather : matGoldBright);
      feather.position.set(side * (0.45 + f * 0.48), 0.35 + f * 0.35, -f * 0.18);
      feather.rotation.z = side * (-0.38 - f * 0.16);
      feather.rotation.y = side * 0.28;
      wing.add(feather);
    }

    const joint = new THREE.Mesh(new THREE.SphereGeometry(0.32, 8, 8), matGoldBright);
    wing.add(joint);

    wingsGroup.add(wing);
  });
  torso.add(wingsGroup);

  // --------------------------------------------------------------------------
  // FLOWING ROYAL CRIMSON CAPE
  // --------------------------------------------------------------------------
  const capeGeo = new THREE.PlaneGeometry(1.6, 3.4, 4, 8);
  const posAttr = capeGeo.attributes.position;
  for (let i = 0; i < posAttr.count; i++) {
    const y = posAttr.getY(i);
    const zOffset = Math.sin((y - 1.7) * 1.2) * 0.5 - (1.7 - y) * 0.3;
    posAttr.setZ(i, zOffset);
  }
  capeGeo.computeVertexNormals();
  const cape = new THREE.Mesh(capeGeo, matRoyalCape);
  cape.position.set(0, -0.4, -0.65);
  cape.rotation.x = 0.45;
  torso.add(cape);

  // --------------------------------------------------------------------------
  // DIAMOND PAULDRONS (SHOULDER GUARDS)
  // --------------------------------------------------------------------------
  [-1, 1].forEach(side => {
    const pauldron = new THREE.Group();
    pauldron.position.set(side * 1.35, 0.85, 0);

    const plate = createBeveledBox(0.95, 0.55, 1.15, 0.04, 2, matGoldBright);
    pauldron.add(plate);

    const spike = new THREE.Mesh(new THREE.ConeGeometry(0.22, 0.7, 4), matGoldBright);
    spike.position.set(0, 0.5, 0);
    spike.rotation.z = side * -0.4;
    pauldron.add(spike);

    torso.add(pauldron);
  });

  // --------------------------------------------------------------------------
  // K-05: GILDED SUNFIRE GREATSWORD & SWIRLING SOLAR FLARE VFX
  // --------------------------------------------------------------------------
  const sword = new THREE.Group();
  sword.name = 'SunfireGreatsword_SolarVFX';

  // Crossguard with winged quillons
  const crossguard = createBeveledBox(1.9, 0.24, 0.38, 0.03, 2, matGoldBright);
  sword.add(crossguard);

  // Ruby Core Heart Jewel
  const jewel = new THREE.Mesh(
    new THREE.OctahedronGeometry(0.2, 0),
    new THREE.MeshBasicMaterial({ color: 0xEF4444 })
  );
  jewel.position.set(0, 0, 0.22);
  sword.add(jewel);

  // Hilt & Pommel
  const hilt = new THREE.Mesh(
    new THREE.CylinderGeometry(0.1, 0.1, 1.2, 8),
    new THREE.MeshStandardMaterial({ color: 0x1E293B, roughness: 0.6 })
  );
  hilt.position.set(0, -0.7, 0);
  sword.add(hilt);

  const pommel = new THREE.Mesh(new THREE.SphereGeometry(0.22, 8, 8), matGoldBright);
  pommel.position.set(0, -1.35, 0);
  sword.add(pommel);

  // 3.6m Radiant Blade Body
  const bladeMat = new THREE.MeshStandardMaterial({
    color: 0xFEF08A,
    emissive: 0xF59E0B,
    emissiveIntensity: 0.9,
    metalness: 0.85,
    roughness: 0.12
  });
  const blade = createBeveledBox(0.5, 3.6, 0.13, 0.02, 2, bladeMat);
  blade.position.set(0, 1.9, 0);
  sword.add(blade);

  // Blade Tip Point
  const tipGeo = new THREE.ConeGeometry(0.36, 0.85, 4);
  tipGeo.rotateY(Math.PI / 4);
  const tip = new THREE.Mesh(tipGeo, bladeMat);
  tip.position.set(0, 4.0, 0);
  sword.add(tip);

  // Swirling Solar Flare Ribbons (Additive VFX Aura)
  const auraMat = new THREE.MeshBasicMaterial({
    color: 0xFBBF24,
    transparent: true,
    opacity: 0.42,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide
  });
  const auraBlade = new THREE.Mesh(new THREE.PlaneGeometry(0.9, 4.0), auraMat);
  auraBlade.position.set(0, 2.0, 0);
  sword.add(auraBlade);

  // Orbiting Solar Flare Energy Orbs
  const matSolarOrb = new THREE.MeshBasicMaterial({ color: 0xFEF08A, blending: THREE.AdditiveBlending });
  for (let i = 0; i < 4; i++) {
    const orb = new THREE.Mesh(new THREE.SphereGeometry(0.14, 8, 8), matSolarOrb);
    orb.position.set(Math.sin(i * 1.6) * 0.45, 1.0 + i * 0.8, Math.cos(i * 1.6) * 0.45);
    sword.add(orb);
  }

  // Arms gripping sword in mid-air strike
  const armL = new THREE.Group();
  armL.position.set(-1.15, 0.75, 0);
  const armLMesh = createBeveledBox(0.85, 1.9, 0.85, 0.035, 2, matGoldPlate);
  armLMesh.position.set(0, -0.75, 0);
  armL.add(armLMesh);
  armL.rotation.x = -Math.PI * 0.44;
  armL.rotation.z = -0.32;
  armL.rotation.y = 0.18;
  torso.add(armL);

  const armR = new THREE.Group();
  armR.position.set(1.15, 0.75, 0);
  const armRMesh = createBeveledBox(0.85, 1.9, 0.85, 0.035, 2, matGoldPlate);
  armRMesh.position.set(0, -0.75, 0);
  armR.add(armRMesh);
  armR.rotation.x = -Math.PI * 0.50;
  armR.rotation.z = 0.28;
  armR.rotation.y = -0.22;
  torso.add(armR);

  // Mount Greatsword
  sword.position.set(0.1, 0.4, 1.25);
  sword.rotation.x = Math.PI * 0.62;
  sword.rotation.z = -0.15;
  torso.add(sword);

  // Legs trailing in jump vault
  const legL = new THREE.Group();
  legL.position.set(-0.55, -1.0, 0);
  const legLMesh = createBeveledBox(0.9, 2.0, 0.9, 0.035, 2, matGoldPlate);
  legLMesh.position.set(0, -1.0, 0);
  legL.add(legLMesh);
  legL.rotation.x = 0.48;
  torso.add(legL);

  const legR = new THREE.Group();
  legR.position.set(0.55, -1.0, 0);
  const legRMesh = createBeveledBox(0.9, 2.0, 0.9, 0.035, 2, matGoldPlate);
  legRMesh.position.set(0, -1.0, 0);
  legR.add(legRMesh);
  legR.rotation.x = 0.65;
  torso.add(legR);

  root.add(torso);
  torso.rotation.x = 0.44; // Forward dive tilt

  return root;
}

/**
 * K-06: Golden Kinetic Sprint Trail & Jump Launch Ring
 */
export function buildGoldenSprintTrail(startX = 18.0, startZ = 12.0, launchX = 6.5, launchZ = 3.5) {
  const trail = new THREE.Group();
  trail.name = 'GoldenSprintTrail';

  // Ribbon connecting start point to takeoff point
  const dist = Math.hypot(launchX - startX, launchZ - startZ);
  const angle = Math.atan2(launchZ - startZ, launchX - startX);

  const ribbonGeo = new THREE.PlaneGeometry(dist, 0.9);
  const ribbonMat = new THREE.MeshBasicMaterial({
    color: 0xFDE047,
    transparent: true,
    opacity: 0.6,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const ribbon = new THREE.Mesh(ribbonGeo, ribbonMat);
  ribbon.rotation.x = -Math.PI / 2;
  ribbon.rotation.z = angle;
  ribbon.position.set((startX + launchX) / 2, 0.04, (startZ + launchZ) / 2);
  trail.add(ribbon);

  // Golden Takeoff Launch Shockwave Ring
  const launchRing = new THREE.Mesh(
    new THREE.RingGeometry(1.2, 2.4, 24),
    new THREE.MeshBasicMaterial({
