      transparent: true,
      opacity: 0.85,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  launchRing.rotation.x = -Math.PI / 2;
  launchRing.position.set(launchX, 0.06, launchZ);
  trail.add(launchRing);

  return trail;
}

