  rearSpike.rotation.z = Math.PI / 2;
  rearSpike.position.set(-1.45, 0, 0);
  hammerhead.add(rearSpike);

  // Swirling Magma Flame Vortex Rings around Hammerhead
  const matLavaRing = new THREE.MeshBasicMaterial({
    color: 0xF97316,
    transparent: true,
    opacity: 0.65,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide
  });

  for (let r = 0; r < 3; r++) {
    const ring = new THREE.Mesh(new THREE.TorusGeometry(1.4 + r * 0.25, 0.08, 8, 24), matLavaRing);
    ring.rotation.x = 0.4 * r;
    ring.rotation.y = 0.6 * r;
