/**
 * V-05: Molten Magma Kinetic Sprint Trail & Takeoff Crater Pit
 */
export function buildMagmaSprintTrail(startX = -16.0, startZ = -14.0, launchX = -2.0, launchZ = -5.0) {
  const trail = new THREE.Group();
  trail.name = 'MagmaSprintTrail';

  const dist = Math.hypot(launchX - startX, launchZ - startZ);
  const angle = Math.atan2(launchZ - startZ, launchX - startX);

  // Scorched asphalt trail with molten orange center
  const ribbonGeo = new THREE.PlaneGeometry(dist, 1.2);
  const ribbonMat = new THREE.MeshBasicMaterial({
    color: 0xEF4444,
    transparent: true,
    opacity: 0.65,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const ribbon = new THREE.Mesh(ribbonGeo, ribbonMat);
  ribbon.rotation.x = -Math.PI / 2;
  ribbon.rotation.z = angle;
  ribbon.position.set((startX + launchX) / 2, 0.04, (startZ + launchZ) / 2);
  trail.add(ribbon);

  // Scorched Basalt Takeoff Launch Pit
  const launchPit = new THREE.Mesh(
    new THREE.RingGeometry(1.4, 2.8, 24),
    new THREE.MeshBasicMaterial({
      color: 0xF97316,
      transparent: true,
      opacity: 0.85,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  launchPit.rotation.x = -Math.PI / 2;
  launchPit.position.set(launchX, 0.06, launchZ);
  trail.add(launchPit);

  return trail;
}

