export function buildClashShockwave() {
  const shock = new THREE.Group();
  shock.name = 'ClashShockwaveSystem';

  // C-01: Blinding Contact Point Flash (Additive White-Hot Core)
  const coreFlash = new THREE.Mesh(
    new THREE.SphereGeometry(0.35, 16, 16),
    new THREE.MeshBasicMaterial({
      color: 0xFFFFFF,
      transparent: true,
      opacity: 0.9,
      blending: THREE.AdditiveBlending,
      depthWrite: false
    })
  );
  shock.add(coreFlash);

  // C-02: Dual-Tone Expanding Spherical Clash Shockwave Rings
  const ringMatGold = new THREE.MeshBasicMaterial({
    color: 0xF59E0B,
    transparent: true,
    opacity: 0.8,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const shockRingGold = new THREE.Mesh(new THREE.RingGeometry(1.8, 3.2, 32), ringMatGold);
  shockRingGold.rotation.x = Math.PI / 2;
  shock.add(shockRingGold);

  const ringMatRed = new THREE.MeshBasicMaterial({
    color: 0xEF4444,
    transparent: true,
    opacity: 0.65,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const shockRingRed = new THREE.Mesh(new THREE.RingGeometry(3.0, 4.8, 32), ringMatRed);
  shockRingRed.rotation.x = Math.PI / 2;
  shock.add(shockRingRed);

  // 8m Lens Flare Star Spikes
  const spikeMat = new THREE.MeshBasicMaterial({
    color: 0xFEF08A,
    transparent: true,
    opacity: 0.7,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const spikeH = new THREE.Mesh(new THREE.PlaneGeometry(8.0, 0.28), spikeMat);
  shock.add(spikeH);

  const spikeV = new THREE.Mesh(new THREE.PlaneGeometry(0.28, 8.0), spikeMat);
  shock.add(spikeV);

  // C-03: 36 Radial Flying Solar Shards & Magma Splinters
  const sparkMatGold = new THREE.MeshBasicMaterial({ color: 0xFCD34D, blending: THREE.AdditiveBlending });
  const sparkMatRed = new THREE.MeshBasicMaterial({ color: 0xFF3D00, blending: THREE.AdditiveBlending });

  for (let i = 0; i < 36; i++) {
    const angle = (i * Math.PI * 2) / 36 + (i * 0.18);
    const dist = 1.2 + (i % 6) * 0.6;
    const sx = Math.cos(angle) * dist;
    const sy = ((i % 5) - 2.0) * 0.5;
    const sz = Math.sin(angle) * dist;

    const spark = new THREE.Mesh(
      new THREE.BoxGeometry(0.09, 0.09, 0.4),
      (i % 2 === 0) ? sparkMatGold : sparkMatRed
    );
    spark.position.set(sx, sy, sz);
    spark.lookAt(0, 0, 0);
    shock.add(spark);
  }

  // C-04: Ground-Level Impact Ripple Ring
  const groundRipple = new THREE.Mesh(
    new THREE.RingGeometry(3.5, 6.0, 32),
    new THREE.MeshBasicMaterial({
      color: 0xF59E0B,
      transparent: true,
      opacity: 0.45,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
      depthWrite: false
    })
  );
  groundRipple.rotation.x = -Math.PI / 2;
  groundRipple.position.set(0, -2.75, 0); // flush with floor below
  shock.add(groundRipple);

  return shock;
}

