// ============================================================================
// THE GLITCH MARKET — 5-ANGLE STUDIO AUDIT RENDERER
// BATCH 1: LORD KAELEN — THE GILDED ARCHON (CHAMPION RIG)
//
// Produces:
// 1. kaelen_angle_1_hero.png (View 01: Full Hero 3/4 Perspective & Aura)
// 2. kaelen_angle_2_halo_hood.png (View 02: Celestial Archon Halo & Dominus Hood)
// 3. kaelen_angle_3_wings_cape.png (View 03: 4.6m Seraphim Wings & Crimson Cape)
// 4. kaelen_angle_4_sword_solar.png (View 04: Sunfire Greatsword & Solar Flare VFX)
// 5. kaelen_angle_5_sprint_trail.png (View 05: Golden Kinetic Sprint Trail & Launch Ring)
// 6. kaelen_master_sheet.png (2400x1350 5-Panel Production Audit Sheet)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import {
  buildLordKaelen,
  buildGoldenSprintTrail
} from './arena_combatants.js';
import { buildImpactCrater } from './arena_effects.js';

const ANGLES = [
  {
    id: 'kaelen_angle_1_hero',
    title: 'VIEW 01: LORD KAELEN // FULL HERO PERSPECTIVE',
    desc: 'Rank #1 Diamond Champion: Celestial Halo, 4.6m Seraphim wings, Dominus hood & Sunfire Greatsword',
    pos: [4.6, 3.2, 4.8],
    target: [0.0, 2.2, 0.4],
    fov: 46
  },
  {
    id: 'kaelen_angle_2_halo_hood',
    title: 'VIEW 02: CELESTIAL ARCHON HALO & DOMINUS HOOD',
    desc: '1.2m floating radiant torus with 8 orbital sunfire ray spikes, inner bloom disc & glowing gold anime eyes',
    pos: [1.8, 3.6, 2.4],
    target: [0.0, 3.4, 0.4],
    fov: 34
  },
  {
    id: 'kaelen_angle_3_wings_cape',
    title: 'VIEW 03: 4.6m SERAPHIM WINGS & CRIMSON SILK CAPE',
    desc: 'Rear 3/4 perspective: 12 layered geometric feather blades with gold trims, diamond pauldrons & billowing cape',
    pos: [-3.8, 2.8, -4.5],
    target: [0.0, 2.2, -0.2],
    fov: 44
  },
  {
    id: 'kaelen_angle_4_sword_solar',
    title: 'VIEW 04: GILDED SUNFIRE GREATSWORD & SOLAR FLARE VFX',
    desc: '3.6m radiant blade, winged crossguard with ruby jewel, additive solar flame aura & 4 orbiting energy orbs',
    pos: [2.2, 2.0, 3.0],
    target: [0.1, 1.5, 0.8],
