function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const renderer = new THREE.WebGLRenderer({
    canvas: glCanvas,
    antialias: true,
    alpha: false,
    preserveDrawingBuffer: true
  });
  renderer.setSize(1280, 760);
  renderer.setPixelRatio(1);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.35;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x030712);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(400, 400, 320, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 50, 0);
  scene.add(skyDome);

  // Studio Lighting Rig
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x0A0F1E, 0.9);
  scene.add(hemi);

  const keySun = new THREE.DirectionalLight(0xFFFBEB, 1.8);
  keySun.position.set(12, 16, 12);
  scene.add(keySun);

  const frontCamKey = new THREE.DirectionalLight(0xFFFFFF, 1.5);
  frontCamKey.position.set(14, 10, 8);
  scene.add(frontCamKey);

  const goldRim = new THREE.DirectionalLight(0xF59E0B, 2.5);
  goldRim.position.set(-14, 12, -10);
  scene.add(goldRim);

  const cyanFill = new THREE.DirectionalLight(0x00F0FF, 1.8);
  cyanFill.position.set(10, 8, -14);
  scene.add(cyanFill);

  // Solar Aura PointLight
  const solarLight = new THREE.PointLight(0xFDE047, 4.5, 18.0);
  solarLight.position.set(0.5, 3.8, 1.0);
  scene.add(solarLight);

  // Ground Platform & Impact Crater
  const floorGeo = new THREE.CylinderGeometry(20, 20, 0.5, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x080C14,
    roughness: 0.6,
    metalness: 0.3
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.position.set(0, -0.25, 0);
  scene.add(floor);

  const crater = buildImpactCrater(10.0);
  crater.position.set(0, 0.02, 0);
  scene.add(crater);

  // Build Lord Kaelen Hero Rig
  const kaelenGroup = new THREE.Group();
  kaelenGroup.name = 'LordKaelen_HeroShowcase';

  const kaelen = buildLordKaelen();
  kaelen.position.set(0.0, 2.2, 0.5);
  kaelen.rotation.y = -0.25; // slight 3/4 turn
  kaelenGroup.add(kaelen);

  // K-06: Golden Kinetic Sprint Trail & Takeoff Launch Shockwave Ring
  const sprintTrail = buildGoldenSprintTrail(12.0, 10.0, 0.0, 1.5);
  kaelenGroup.add(sprintTrail);

  scene.add(kaelenGroup);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 350);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    renderer.render(scene, cam);

    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = 1280;
    angleCanvas.height = 760;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Overlay Badge
    actx.fillStyle = 'rgba(3, 7, 18, 0.78)';
    actx.fillRect(24, 24, 660, 68);
    actx.strokeStyle = '#00F0FF';
    actx.lineWidth = 1.5;
    actx.strokeRect(24, 24, 660, 68);

    actx.fillStyle = '#00F0FF';
    actx.font = 'bold 18px monospace';
    actx.fillText(cfg.title, 42, 52);

    actx.fillStyle = '#94A3B8';
    actx.font = '13px monospace';
    actx.fillText(cfg.desc, 42, 74);

    renderedCanvases.push(angleCanvas);

    // Upload individual angle
    const blob = await canvasToBlob(angleCanvas);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png`);
  }

  // ==========================================================================
  // COMPOSITE MASTER AUDIT SHEET (2400 × 1350)
  // ==========================================================================
  masterCtx.fillStyle = '#030712';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Cyber Grid Backdrop
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.05)';
  masterCtx.lineWidth = 1;
  const gridSize = 40;
  for (let x = 0; x < 2400; x += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Master Title Header
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 34px sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // BATCH 1: LORD KAELEN (THE GILDED ARCHON)', 45, 55);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText('ROBLOX UGC 3D COMBATANT RIG — 6 CORE ASSETS VERIFIED (K-01 THROUGH K-06)', 45, 85);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('SECTOR 04 COLOSSEUM DEATHMATCH • RANK #1 DIAMOND CHAMPION', 2355, 55);
  masterCtx.fillText('CELESTIAL HALO • 4.6m WINGS • DOMINUS HOOD • SUNFIRE BLADE • FULL RIG', 2355, 78);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath(); masterCtx.moveTo(45, 105); masterCtx.lineTo(2355, 105); masterCtx.stroke();

  // Layout:
  // Large Hero on Left (1420 × 840)
  const heroX = 45;
  const heroY = 130;
  const heroW = 1420;
  const heroH = 840;

  masterCtx.drawImage(renderedCanvases[0], heroX, heroY, heroW, heroH);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(heroX, heroY, heroW, heroH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(heroX, heroY + heroH - 48, heroW, 48);
  masterCtx.fillStyle = '#F59E0B';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.fillText('VIEW 01: LORD KAELEN (THE GILDED ARCHON HERO DISPLAY)', heroX + 16, heroY + heroH - 18);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('Full rig with Celestial Halo, 4.6m Seraphim wings, Dominus hood, Sunfire blade & golden sprint trail', heroX + heroW - 16, heroY + heroH - 18);
  masterCtx.textAlign = 'left';

  // 4 Thumbnails on Right (2x2 Grid)
  const rightColX1 = 1500;
  const rightColX2 = 1940;
  const rowY1 = 130;
  const rowY2 = 572;
  const thumbW = 415;
  const thumbH = 398;

  const thumbs = [
    { idx: 1, x: rightColX1, y: rowY1, title: 'ANGLE 2: CELESTIAL HALO & HOOD', desc: '1.2m radiant torus + 8 orbital rays' },
    { idx: 2, x: rightColX2, y: rowY1, title: 'ANGLE 3: 4.6m SERAPHIM WINGS', desc: '12 layered geometric feathers & cape' },
    { idx: 3, x: rightColX1, y: rowY2, title: 'ANGLE 4: SUNFIRE GREATSWORD', desc: '3.6m blade + solar flare aura & orbs' },
    { idx: 4, x: rightColX2, y: rowY2, title: 'ANGLE 5: GOLDEN SPRINT TRAIL', desc: 'High-speed light ribbon & launch ring' }
  ];

  thumbs.forEach(t => {
    masterCtx.drawImage(renderedCanvases[t.idx], t.x, t.y, thumbW, thumbH);
    masterCtx.strokeStyle = '#00F0FF';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(t.x, t.y, thumbW, thumbH);

    masterCtx.fillStyle = 'rgba(7, 13, 27, 0.9)';
    masterCtx.fillRect(t.x + 8, t.y + 8, thumbW - 16, 44);
    masterCtx.strokeStyle = '#38BDF8';
    masterCtx.lineWidth = 1;
    masterCtx.strokeRect(t.x + 8, t.y + 8, thumbW - 16, 44);

    masterCtx.fillStyle = '#00F0FF';
    masterCtx.font = 'bold 12px monospace';
    masterCtx.fillText(t.title, t.x + 16, t.y + 26);
    masterCtx.fillStyle = '#94A3B8';
    masterCtx.font = '10px monospace';
    masterCtx.fillText(t.desc, t.x + 16, t.y + 42);
  });

  // Bottom Technical Spec Panel
  const specY = 1000;
  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(45, specY, 2310, 315);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(45, specY, 2310, 315);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillText('BATCH 1: LORD KAELEN ASSET VERIFICATION AUDIT (K-01 THROUGH K-06)', 65, specY + 38);

  masterCtx.strokeStyle = '#334155';
  masterCtx.lineWidth = 1;
  masterCtx.beginPath(); masterCtx.moveTo(65, specY + 52); masterCtx.lineTo(2335, specY + 52); masterCtx.stroke();

  masterCtx.font = '12px monospace';
  masterCtx.fillStyle = '#E2E8F0';
  const lineH = 26;
  const col1X = 65;
  const col2X = 840;
  const col3X = 1600;

  // Column 1: Halo, Hood, Armor
  masterCtx.fillText('• ASSET K-01: CELESTIAL ARCHON HALO & SUNFIRE SPIKES', col1X, specY + 80);
  masterCtx.fillText('  - 1.2m floating radiant golden torus (color: #FFFBEB, opacity: 0.95) hovered at Y = 1.7m above hood.', col1X, specY + 80 + lineH);
  masterCtx.fillText('  - 8 orbital sunfire ray spikes (ConeGeometry, additive #FDE047) + 1.35m inner solar bloom disc.', col1X, specY + 80 + lineH * 2);
  masterCtx.fillText('• ASSET K-02: DOMINUS EMPYREUS HOOD & ANIME EYE FLARES', col1X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Golden hood shell with deep shadow recess, pointed golden front peak, and dual glowing eyes with flare trails.', col1X, specY + 80 + lineH * 4);

  // Column 2: Armor, Cape, Wings
  masterCtx.fillText('• ASSET K-03: GILDED EMPEROR PLATE & CRIMSON CAPE', col2X, specY + 80);
  masterCtx.fillText('  - Procedural 24K filigree chestplate decal, diamond pauldron crests, and 3.4m billowing crimson silk cape.', col2X, specY + 80 + lineH);
  masterCtx.fillText('• ASSET K-04: 6-TIER ARCHANGEL SERAPHIM WINGS (4.6m WINGSPAN)', col2X, specY + 80 + lineH * 2);
  masterCtx.fillText('  - 12 layered geometric feather blades (6 per side) featuring polished gold borders and ivory chassis.', col2X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Articulated wing joints mounted to thoracic armor frame with dynamic outward fan rotation.', col2X, specY + 80 + lineH * 4);

  // Column 3: Weapon, Sprint Trail & Status
  masterCtx.fillText('• ASSET K-05: GILDED SUNFIRE GREATSWORD & SOLAR FLARE VFX', col3X, specY + 80);
  masterCtx.fillText('  - 3.6m radiant blade, winged crossguard with ruby jewel, additive solar flame aura & 4 orbiting energy orbs.', col3X, specY + 80 + lineH);
  masterCtx.fillText('• ASSET K-06: GOLDEN KINETIC SPRINT TRAIL & LAUNCH SHOCKWAVE', col3X, specY + 80 + lineH * 2);
  masterCtx.fillText('  - High-velocity light ribbon skid marks (#FDE047) leading into circular expanding takeoff launch ring on deck.', col3X, specY + 80 + lineH * 3);
  masterCtx.fillText('• BATCH 1 PRODUCTION STATUS: 100% COMPLETE & VERIFIED — READY FOR BATCH 2 (VULCAN-99)', col3X, specY + 80 + lineH * 4);

  // Upload Master Sheet
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('kaelen_master_sheet.png', masterBlob);
  console.log('SAVED: kaelen_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('KAELEN_BATCH_1_AUDIT_COMPLETE');
}

window.onload = init;

