/**
 * Builds Full Vulcan-99 Character Rig
 */
export function buildVulcanBerserker(options = {}) {
  const root = new THREE.Group();
  root.name = 'Vulcan99_MagmaBerserker';

  // Materials
  const matBasaltPlate = new THREE.MeshStandardMaterial({
    color: 0x090D18,
    metalness: 0.45,
    roughness: 0.72,
    map: createMagmaArmorTexture()
  });

  const matCharredSteel = new THREE.MeshStandardMaterial({
    color: 0x1A1F2E,
    metalness: 0.72,
    roughness: 0.45
  });

  const matMoltenGlow = new THREE.MeshBasicMaterial({ color: 0xFF2200 });
  const matLavaAmber = new THREE.MeshBasicMaterial({ color: 0xFBBF24 });
  const matDemonHorn = new THREE.MeshStandardMaterial({ color: 0x2A0A0A, roughness: 0.6 });

  const torso = new THREE.Group();
  torso.name = 'Torso';

  // Heavy Basalt Chestplate (2.2 x 2.1 x 1.3)
  const torsoMesh = createBeveledBox(2.2, 2.1, 1.3, 0.05, 2, matBasaltPlate);
  torso.add(torsoMesh);

  // Glowing Molten Lava Core Vent on Chest
  const vent = new THREE.Mesh(new THREE.BoxGeometry(0.85, 0.85, 0.12), matMoltenGlow);
  vent.position.set(0, 0.22, 0.68);
  torso.add(vent);

  // --------------------------------------------------------------------------
  // V-01: HEAD & DEMONIC HORNED BATTLE HELM
  // --------------------------------------------------------------------------
  const headGroup = new THREE.Group();
  headGroup.position.set(0, 1.52, 0);

  const helmMesh = createBeveledBox(1.38, 1.38, 1.38, 0.05, 2, matCharredSteel);
  headGroup.add(helmMesh);

  // Pulsing Molten Visor Slit
  const visor = new THREE.Mesh(new THREE.BoxGeometry(1.08, 0.2, 0.16), matMoltenGlow);
  visor.position.set(0, 0.1, 0.72);
  headGroup.add(visor);

  // Curved Demonic Battle Horns (4 Segments with red tips)
  [-1, 1].forEach(side => {
    const hornGroup = new THREE.Group();
    hornGroup.position.set(side * 0.78, 0.48, 0.1);

    for (let h = 0; h < 4; h++) {
      const segW = 0.24 - h * 0.04;
      const seg = new THREE.Mesh(
        new THREE.ConeGeometry(segW, 0.48, 5),
        h === 3 ? matMoltenGlow : matDemonHorn
      );
      seg.position.set(side * (h * 0.2), h * 0.35, -h * 0.1);
      seg.rotation.z = side * (-0.38 - h * 0.15);
      seg.rotation.x = -0.15;
      hornGroup.add(seg);
    }
    headGroup.add(hornGroup);
  });
  torso.add(headGroup);

  // --------------------------------------------------------------------------
  // V-03: SPIKED MAGMA PAULDRONS WITH FLAME EMITTERS
  // --------------------------------------------------------------------------
  [-1, 1].forEach(side => {
    const pauldron = new THREE.Group();
    pauldron.position.set(side * 1.6, 0.95, 0);

    const plate = createBeveledBox(1.2, 0.7, 1.35, 0.05, 2, matBasaltPlate);
    pauldron.add(plate);

    // Armor-Piercing Spikes
    for (let s = -1; s <= 1; s += 2) {
      const spike = new THREE.Mesh(new THREE.ConeGeometry(0.22, 0.75, 4), matCharredSteel);
      spike.position.set(s * 0.28, 0.6, 0);
      spike.rotation.z = side * -0.32;
      pauldron.add(spike);
    }

    // Active Orange Fire Plume Emitter on shoulder
    const firePlume = new THREE.Mesh(
      new THREE.ConeGeometry(0.35, 1.1, 6),
      new THREE.MeshBasicMaterial({
        color: 0xF97316,
        transparent: true,
        opacity: 0.8,
        blending: THREE.AdditiveBlending
      })
    );
    firePlume.position.set(0, 0.75, 0);
    pauldron.add(firePlume);

    torso.add(pauldron);
  });

  // --------------------------------------------------------------------------
  // V-04: HELLFIRE COLOSSUS WARHAMMER & OVERHEAD PARRY STANCE
  // --------------------------------------------------------------------------
  const hammer = buildHellfireWarhammer();
  torso.add(hammer);

  // Arms & Legs Hierarchies
  const armL = new THREE.Group();
  armL.position.set(-1.3, 0.75, 0);
  const armLMesh = createBeveledBox(0.95, 1.9, 0.95, 0.04, 2, matBasaltPlate);
  armLMesh.position.set(0, -0.75, 0);
  armL.add(armLMesh);
  torso.add(armL);

  const armR = new THREE.Group();
  armR.position.set(1.3, 0.75, 0);
  const armRMesh = createBeveledBox(0.95, 1.9, 0.95, 0.04, 2, matBasaltPlate);
  armRMesh.position.set(0, -0.75, 0);
  armR.add(armRMesh);
  torso.add(armR);

  const legL = new THREE.Group();
  legL.position.set(-0.72, -0.95, 0);
  const legLMesh = createBeveledBox(1.02, 2.0, 1.02, 0.04, 2, matBasaltPlate);
  legLMesh.position.set(0, -0.95, 0);
  legL.add(legLMesh);
  torso.add(legL);

  const legR = new THREE.Group();
  legR.position.set(0.72, -0.95, 0);
  const legRMesh = createBeveledBox(1.02, 2.0, 1.02, 0.04, 2, matBasaltPlate);
  legRMesh.position.set(0, -0.95, 0);
  legR.add(legRMesh);
  torso.add(legR);

  // Pose Configuration
  const isStanding = (options.pose === 'standing');

  if (isStanding) {
    // Imposing Grounded Raid-Boss Stance: Hammer resting upright, arms braced
    armL.rotation.set(0.15, 0, -0.25);
    armR.rotation.set(-0.65, 0.22, 0.36); // gripping hammer haft
    hammer.position.set(1.4, 0.55, 0.35);
    hammer.rotation.set(0.12, 0.1, -0.06);
    legL.rotation.set(0, 0, 0.15); // wide planted feet
    legR.rotation.set(0, 0, -0.15);
    torso.rotation.x = 0.0;
  } else {
    // Default Mid-Air Power Leap Parry Stance
    hammer.position.set(-1.8, 2.1, 1.25);
    hammer.rotation.set(0, 0.15, -0.08);
    armL.rotation.set(Math.PI * 0.48, -0.15, -0.38);
    armR.rotation.set(Math.PI * 0.45, 0.18, 0.35);
    legL.rotation.set(-0.62, 0, 0.22); // bent backward in jump
    legR.rotation.set(-0.42, 0, -0.22); // trailing kick
    torso.rotation.x = -0.18; // leaning back into upward jump parry
  }

  root.add(torso);
  torso.position.y = 0.22;
  return root;
}

