// ============================================================================
// THE GLITCH MARKET — 5-ANGLE STUDIO AUDIT RENDERER
// BATCH 2: VULCAN-99 — THE MAGMA BERSERKER (RAID BOSS RIG)
//
// Produces:
// 1. vulcan_angle_1_hero.png (View 01: Full Hero 3/4 Perspective & Magma Chassis)
// 2. vulcan_angle_2_horns_visor.png (View 02: Demonic Horned Helm & Molten Visor Slit)
// 3. vulcan_angle_3_pauldrons_fire.png (View 03: Spiked Magma Pauldrons & Fire Plumes)
// 4. vulcan_angle_4_warhammer_vortex.png (View 04: Hellfire Warhammer & Magma Flame Vortex)
// 5. vulcan_angle_5_sprint_trail.png (View 05: Molten Kinetic Sprint Trail & Cracked Pit)
// 6. vulcan_master_sheet.png (2400x1350 5-Panel Production Audit Sheet)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import {
  buildVulcanBerserker,
  buildMagmaSprintTrail
} from './arena_combatants.js';
import { buildImpactCrater } from './arena_effects.js';

const ANGLES = [
  {
    id: 'vulcan_angle_1_hero',
    title: 'VIEW 01: VULCAN-99 // FULL HERO PERSPECTIVE',
    desc: 'Rank #2 Grandmaster Raid Boss: Demonic horns, basalt magma plate, fire pauldrons & Hellfire Warhammer',
    pos: [4.6, 2.8, 5.2],
    target: [0.0, 2.0, 0.0],
    fov: 46
  },
  {
    id: 'vulcan_angle_2_horns_visor',
    title: 'VIEW 02: DEMONIC HORNED HELM & MOLTEN VISOR',
    desc: 'Charred titanium helm flanked by 4-segment curved demon horns & pulsing glowing red visor slit (#FF2200)',
    pos: [1.2, 3.4, 2.5],
    target: [0.0, 3.3, 0.1],
    fov: 34
  },
  {
    id: 'vulcan_angle_3_pauldrons_fire',
    title: 'VIEW 03: SPIKED MAGMA PAULDRONS & FIRE JETS',
    desc: 'Heavy basalt shoulder guards with dual armor-piercing spikes & active orange fire plume cones (#F97316)',
    pos: [-2.8, 3.0, 2.4],
    target: [-1.4, 2.8, 0.1],
    fov: 38
  },
  {
    id: 'vulcan_angle_4_warhammer_vortex',
    title: 'VIEW 04: HELLFIRE WARHAMMER & MAGMA VORTEX VFX',
    desc: '4.5m carbon haft, 1.8m basalt head with magma face, rear spike & 3 swirling magma flame vortex rings',
    pos: [2.6, 2.0, 2.8],
    target: [1.3, 1.8, 0.4],
    fov: 38
  },
  {
    id: 'vulcan_angle_5_sprint_trail',
    title: 'VIEW 05: MOLTEN SPRINT TRAIL & CRACKED LAUNCH PIT',
    desc: 'Low action perspective: smoldering scorched basalt skid marks & cracked bubbling magma takeoff pit',
    pos: [-9.5, 4.5, -8.0],
    target: [-1.5, 1.2, -1.5],
    fov: 50
  }
];

function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const renderer = new THREE.WebGLRenderer({
    canvas: glCanvas,
    antialias: true,
    alpha: false,
    preserveDrawingBuffer: true
  });
  renderer.setSize(1280, 760);
  renderer.setPixelRatio(1);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.35;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x030712);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(400, 400, 320, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 50, 0);
  scene.add(skyDome);

  // Dramatic Studio Lighting Rig (Molten Red / Amber / Cyan Accent)
  const hemi = new THREE.HemisphereLight(0xF97316, 0x0A0F1E, 0.85);
  scene.add(hemi);

  const keySun = new THREE.DirectionalLight(0xFFFBEB, 1.6);
  keySun.position.set(12, 16, 12);
  scene.add(keySun);

  const frontCamKey = new THREE.DirectionalLight(0xFFFFFF, 1.5);
  frontCamKey.position.set(14, 10, 8);
  scene.add(frontCamKey);

  const magmaRim = new THREE.DirectionalLight(0xEF4444, 3.2);
  magmaRim.position.set(-14, 12, -10);
  scene.add(magmaRim);

  const amberFill = new THREE.DirectionalLight(0xF59E0B, 2.2);
  amberFill.position.set(10, 8, -14);
  scene.add(amberFill);

  // Lava Core PointLight
  const lavaLight = new THREE.PointLight(0xEF4444, 4.8, 18.0);
  lavaLight.position.set(0.0, 2.4, 1.2);
  scene.add(lavaLight);

  // Ground Platform & Impact Crater
  const floorGeo = new THREE.CylinderGeometry(20, 20, 0.5, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x080C14,
    roughness: 0.6,
    metalness: 0.3
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.position.set(0, -0.25, 0);
  scene.add(floor);

  const crater = buildImpactCrater(10.0);
  crater.position.set(0, 0.02, 0);
  scene.add(crater);

  // Build Vulcan-99 Hero Rig
  const vulcanGroup = new THREE.Group();
  vulcanGroup.name = 'Vulcan99_HeroShowcase';

  const vulcan = buildVulcanBerserker({ pose: 'standing' });
  vulcan.position.set(0.0, 1.95, 0.0);
  vulcan.rotation.y = -0.22; // slight 3/4 angle
  vulcanGroup.add(vulcan);

  // V-05: Molten Kinetic Sprint Trail & Cracked Takeoff Launch Pit
  const sprintTrail = buildMagmaSprintTrail(-12.0, -10.0, 0.0, -1.2);
  vulcanGroup.add(sprintTrail);

  scene.add(vulcanGroup);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 350);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    renderer.render(scene, cam);

    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = 1280;
    angleCanvas.height = 760;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Overlay Badge
    actx.fillStyle = 'rgba(3, 7, 18, 0.78)';
    actx.fillRect(24, 24, 660, 68);
    actx.strokeStyle = '#EF4444';
    actx.lineWidth = 1.5;
    actx.strokeRect(24, 24, 660, 68);

    actx.fillStyle = '#EF4444';
    actx.font = 'bold 18px monospace';
    actx.fillText(cfg.title, 42, 52);

    actx.fillStyle = '#94A3B8';
    actx.font = '13px monospace';
    actx.fillText(cfg.desc, 42, 74);

    renderedCanvases.push(angleCanvas);

    // Upload individual angle
    const blob = await canvasToBlob(angleCanvas);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png`);
  }

  // ==========================================================================
  // COMPOSITE MASTER AUDIT SHEET (2400 × 1350)
  // ==========================================================================
  masterCtx.fillStyle = '#030712';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Cyber Grid Backdrop
  masterCtx.strokeStyle = 'rgba(239, 68, 68, 0.06)';
  masterCtx.lineWidth = 1;
  const gridSize = 40;
  for (let x = 0; x < 2400; x += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Master Title Header
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 34px sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // BATCH 2: VULCAN-99 (THE MAGMA BERSERKER)', 45, 55);

  masterCtx.fillStyle = '#EF4444';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText('ROBLOX UGC 3D RAID BOSS RIG — 5 CORE ASSETS VERIFIED (V-01 THROUGH V-05)', 45, 85);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('SECTOR 04 COLOSSEUM DEATHMATCH • RANK #2 GRANDMASTER RAID BOSS', 2355, 55);
  masterCtx.fillText('DEMON HORNS • BASALT PLATE • FIRE PAULDRONS • MAGMA VORTEX HAMMER • FULL RIG', 2355, 78);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#EF4444';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath(); masterCtx.moveTo(45, 105); masterCtx.lineTo(2355, 105); masterCtx.stroke();

  // Layout:
  // Large Hero on Left (1420 × 840)
  const heroX = 45;
  const heroY = 130;
  const heroW = 1420;
  const heroH = 840;

  masterCtx.drawImage(renderedCanvases[0], heroX, heroY, heroW, heroH);
  masterCtx.strokeStyle = '#EF4444';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(heroX, heroY, heroW, heroH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(heroX, heroY + heroH - 48, heroW, 48);
  masterCtx.fillStyle = '#F97316';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.fillText('VIEW 01: VULCAN-99 (THE MAGMA BERSERKER HERO DISPLAY)', heroX + 16, heroY + heroH - 18);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('Full rig with demonic horns, glowing visor, basalt magma plate, Hellfire hammer with vortex & scorched trail', heroX + heroW - 16, heroY + heroH - 18);
  masterCtx.textAlign = 'left';

  // 4 Thumbnails on Right (2x2 Grid)
  const rightColX1 = 1500;
  const rightColX2 = 1940;
  const rowY1 = 130;
  const rowY2 = 572;
  const thumbW = 415;
  const thumbH = 398;

  const thumbs = [
    { idx: 1, x: rightColX1, y: rowY1, title: 'ANGLE 2: DEMONIC HORNS & VISOR', desc: '4-segment horns with glowing red tips' },
    { idx: 2, x: rightColX2, y: rowY1, title: 'ANGLE 3: FIRE PAULDRONS', desc: 'Armor-piercing spikes & fire plumes' },
    { idx: 3, x: rightColX1, y: rowY2, title: 'ANGLE 4: MAGMA VORTEX HAMMER', desc: '4.5m haft + 3 swirling flame vortex rings' },
    { idx: 4, x: rightColX2, y: rowY2, title: 'ANGLE 5: MOLTEN SPRINT TRAIL', desc: 'Scorched basalt skid trail & launch pit' }
  ];

  thumbs.forEach(t => {
    masterCtx.drawImage(renderedCanvases[t.idx], t.x, t.y, thumbW, thumbH);
    masterCtx.strokeStyle = '#EF4444';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(t.x, t.y, thumbW, thumbH);

    masterCtx.fillStyle = 'rgba(7, 13, 27, 0.9)';
    masterCtx.fillRect(t.x + 8, t.y + 8, thumbW - 16, 44);
