  masterCtx.fillText('  - Horizontal glowing molten red visor slit (#FF2200, emissive 3.5) with internal heat glow.', col1X, specY + 80 + lineH * 2);
  masterCtx.fillText('• ASSET V-02: VOLCANIC BASALT PLATE & LAVA CORE VENT', col1X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Heavy 2.2m x 2.1m basalt plate etched with procedural glowing magma fissure channels & chest lava vent.', col1X, specY + 80 + lineH * 4);

  // Column 2: Pauldrons, Fire Jets, Warhammer
  masterCtx.fillText('• ASSET V-03: SPIKED MAGMA PAULDRONS & FIRE PLUME EMITTERS', col2X, specY + 80);
  masterCtx.fillText('  - Dual heavy basalt shoulder guards with armor-piercing spikes and active orange fire plume jets (#F97316).', col2X, specY + 80 + lineH);
  masterCtx.fillText('• ASSET V-04: HELLFIRE COLOSSUS WARHAMMER & MAGMA VORTEX VFX', col2X, specY + 80 + lineH * 2);
  masterCtx.fillText('  - 4.5m dark carbon steel haft + colossal 1.8m x 1.5m x 2.2m basalt hammerhead with glowing magma face.', col2X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - 3 swirling magma flame vortex rings (additive #F97316) + 12 orbiting ember particles around hammerhead.', col2X, specY + 80 + lineH * 4);

  // Column 3: Sprint Trail & Status
  masterCtx.fillText('• ASSET V-05: MOLTEN KINETIC SPRINT TRAIL & CRACKED LAUNCH PIT', col3X, specY + 80);
  masterCtx.fillText('  - Smoldering scorched basalt skid trail (#EF4444) on arena deck leading into cracked bubbling magma takeoff pit.', col3X, specY + 80 + lineH);
  masterCtx.fillText('  - Integrated launch ring with additive orange lava core marking dynamic jump takeoff point.', col3X, specY + 80 + lineH * 2);
  masterCtx.fillText('• BATCH 2 PRODUCTION STATUS: 100% COMPLETE & VERIFIED — READY FOR BATCH 3 (COLLISION VFX)', col3X, specY + 80 + lineH * 3);
  masterCtx.fillText('• PIPELINE READINESS: FULL RIG RIGGED FOR BOTH HERO STANDING & MID-AIR CLASH POSES', col3X, specY + 80 + lineH * 4);

  // Upload Master Sheet
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('vulcan_master_sheet.png', masterBlob);
  console.log('SAVED: vulcan_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('VULCAN_BATCH_2_AUDIT_COMPLETE');
}

