// ============================================================================
// THE GLITCH MARKET — 5-ANGLE STUDIO AUDIT RENDERER
// BATCH 3: MID-AIR KINETIC COLLISION & ARENA CLASH VFX (ASSETS C-01 TO C-05)
//
// Produces:
// 1. clash_vfx_angle_1_hero.png (View 01: Hero Weapon Collision & Shockwave Point)
// 2. clash_vfx_angle_2_core_flash.png (View 02: Blinding White Core & 8m Star Spikes)
// 3. clash_vfx_angle_3_shockwaves_shards.png (View 03: Dual Shockwaves & 36 Flying Debris)
// 4. clash_vfx_angle_4_ground_ripple.png (View 04: Ground-Level Impact Ripple & Crater)
// 5. clash_vfx_angle_5_opposing_lights.png (View 05: Opposing Holy Gold vs Hellfire Lighting)
// 6. clash_vfx_master_sheet.png (2400x1350 5-Panel Production Audit Sheet)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import { buildDynamicArenaClash } from './arena_combatants.js';
import { buildImpactCrater } from './arena_effects.js';

const ANGLES = [
  {
    id: 'clash_vfx_angle_1_hero',
    title: 'VIEW 01: MID-AIR WEAPON COLLISION HERO (GROUND ZERO)',
    desc: 'Sunfire Greatsword diving slam meeting Hellfire Warhammer parry: white-hot core, star cross & shockwaves',
    pos: [5.5, 3.4, 4.2],
    target: [0.0, 2.85, 0.05],
    fov: 44
  },
  {
    id: 'clash_vfx_angle_2_core_flash',
    title: 'VIEW 02: BLINDING WHITE CORE & 8m STAR SPIKES',
    desc: 'High-luminance contact singularity sphere (opacity 0.9) with 8m horizontal and vertical lens flare star spikes',
    pos: [0.0, 2.85, 4.5],
    target: [0.0, 2.85, 0.05],
    fov: 36
  },
  {
    id: 'clash_vfx_angle_3_shockwaves_shards',
    title: 'VIEW 03: DUAL SHOCKWAVE DISCS & 36 FLYING SHARDS',
    desc: 'High isometric view: inner gold ring (3.2m), outer carmine ring (4.8m) & 36 radial solar/magma splinters',
    pos: [4.5, 5.8, 3.5],
    target: [0.0, 2.85, 0.05],
    fov: 46
  },
  {
    id: 'clash_vfx_angle_4_ground_ripple',
    title: 'VIEW 04: GROUND IMPACT RIPPLE & CRATER CAVITATION',
    desc: 'Low gladiator deck angle: expanding secondary shockwave ring (6.0m) radiating across cracked obsidian crater',
    pos: [5.8, 0.8, 5.2],
    target: [0.0, 1.4, 0.0],
    fov: 48
  },
  {
    id: 'clash_vfx_angle_5_opposing_lights',
    title: 'VIEW 05: DUAL OPPOSING LIGHTING RIG (GOLD VS FIRE)',
    desc: 'Side-profile duel lighting: Holy Gold point light (5.0 intensity) vs Hellfire Red point light (4.5 intensity)',
    pos: [8.8, 3.6, 0.1],
    target: [0.0, 2.85, 0.05],
    fov: 46
  }
];

function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const renderer = new THREE.WebGLRenderer({
    canvas: glCanvas,
    antialias: true,
    alpha: false,
    preserveDrawingBuffer: true
  });
  renderer.setSize(1280, 760);
  renderer.setPixelRatio(1);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.35;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x030712);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(400, 400, 320, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 50, 0);
  scene.add(skyDome);

  // Ambient Fill Lighting Rig
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x0A0F1E, 0.75);
  scene.add(hemi);

  const keySun = new THREE.DirectionalLight(0xFFFBEB, 1.4);
  keySun.position.set(12, 16, 12);
  scene.add(keySun);

  const frontCamKey = new THREE.DirectionalLight(0xFFFFFF, 1.4);
  frontCamKey.position.set(16, 10, 4);
  scene.add(frontCamKey);

  // Ground Platform & Cracked Obsidian Impact Crater
  const floorGeo = new THREE.CylinderGeometry(20, 20, 0.5, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x080C14,
    roughness: 0.6,
    metalness: 0.3
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.position.set(0, -0.25, 0);
  scene.add(floor);

  const crater = buildImpactCrater(10.0);
  crater.position.set(0, 0.02, 0);
  scene.add(crater);

  // Dynamic Mid-Air Clash Ensemble (Kaelen, Vulcan, Trails, Shockwave, Opposing Lights)
  const clashEnsemble = buildDynamicArenaClash();
  scene.add(clashEnsemble);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 350);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    renderer.render(scene, cam);

    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = 1280;
    angleCanvas.height = 760;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Overlay Badge
    actx.fillStyle = 'rgba(3, 7, 18, 0.78)';
    actx.fillRect(24, 24, 660, 68);
    actx.strokeStyle = '#F59E0B';
    actx.lineWidth = 1.5;
    actx.strokeRect(24, 24, 660, 68);

    actx.fillStyle = '#F59E0B';
    actx.font = 'bold 18px monospace';
    actx.fillText(cfg.title, 42, 52);

    actx.fillStyle = '#94A3B8';
    actx.font = '13px monospace';
    actx.fillText(cfg.desc, 42, 74);

    renderedCanvases.push(angleCanvas);

    // Upload individual angle
    const blob = await canvasToBlob(angleCanvas);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png`);
  }

  // ==========================================================================
  // COMPOSITE MASTER AUDIT SHEET (2400 × 1350)
  // ==========================================================================
  masterCtx.fillStyle = '#030712';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Cyber Grid Backdrop
  masterCtx.strokeStyle = 'rgba(245, 158, 11, 0.06)';
  masterCtx.lineWidth = 1;
  const gridSize = 40;
  for (let x = 0; x < 2400; x += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Master Title Header
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 34px sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // BATCH 3: MID-AIR KINETIC COLLISION & CLASH VFX', 45, 55);

  masterCtx.fillStyle = '#F59E0B';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText('EXPLOSIVE ARENA CONTACT SYSTEM — 5 CORE ASSETS VERIFIED (C-01 THROUGH C-05)', 45, 85);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('SECTOR 04 COLOSSEUM DEATHMATCH • GROUND ZERO CONTACT AT Y = 2.85m', 2355, 55);
  masterCtx.fillText('WHITE CORE • 8m STAR SPIKES • DUAL SHOCKWAVES • 36 SPLINTERS • DUAL LIGHTS', 2355, 78);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#F59E0B';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath(); masterCtx.moveTo(45, 105); masterCtx.lineTo(2355, 105); masterCtx.stroke();

  // Layout:
  // Large Hero on Left (1420 × 840)
  const heroX = 45;
  const heroY = 130;
  const heroW = 1420;
  const heroH = 840;

  masterCtx.drawImage(renderedCanvases[0], heroX, heroY, heroW, heroH);
  masterCtx.strokeStyle = '#F59E0B';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(heroX, heroY, heroW, heroH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(heroX, heroY + heroH - 48, heroW, 48);
  masterCtx.fillStyle = '#F59E0B';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.fillText('VIEW 01: GROUND ZERO COLLISION HERO (WEAPON IMPACT POINT)', heroX + 16, heroY + heroH - 18);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('Sunfire blade vs Hellfire hammer: white-hot core, 8m star spikes, gold & red shockwaves, 36 flying debris shards', heroX + heroW - 16, heroY + heroH - 18);
  masterCtx.textAlign = 'left';

  // 4 Thumbnails on Right (2x2 Grid)
  const rightColX1 = 1500;
  const rightColX2 = 1940;
  const rowY1 = 130;
  const rowY2 = 572;
  const thumbW = 415;
  const thumbH = 398;

  const thumbs = [
    { idx: 1, x: rightColX1, y: rowY1, title: 'ANGLE 2: CORE FLASH & STAR SPIKES', desc: 'White core sphere + 8m star cross' },
    { idx: 2, x: rightColX2, y: rowY1, title: 'ANGLE 3: DUAL SHOCKWAVES & SHARDS', desc: 'Gold & red rings + 36 flying debris' },
    { idx: 3, x: rightColX1, y: rowY2, title: 'ANGLE 4: GROUND IMPACT RIPPLE', desc: 'Secondary shockwave on crater floor' },
    { idx: 4, x: rightColX2, y: rowY2, title: 'ANGLE 5: OPPOSING LIGHTING RIG', desc: 'Holy Gold vs Hellfire Red lights' }
  ];

  thumbs.forEach(t => {
    masterCtx.drawImage(renderedCanvases[t.idx], t.x, t.y, thumbW, thumbH);
    masterCtx.strokeStyle = '#F59E0B';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(t.x, t.y, thumbW, thumbH);

    masterCtx.fillStyle = 'rgba(7, 13, 27, 0.9)';
    masterCtx.fillRect(t.x + 8, t.y + 8, thumbW - 16, 44);
    masterCtx.strokeStyle = '#FDE047';
    masterCtx.lineWidth = 1;
    masterCtx.strokeRect(t.x + 8, t.y + 8, thumbW - 16, 44);

    masterCtx.fillStyle = '#FDE047';
    masterCtx.font = 'bold 12px monospace';
    masterCtx.fillText(t.title, t.x + 16, t.y + 26);
    masterCtx.fillStyle = '#94A3B8';
    masterCtx.font = '10px monospace';
    masterCtx.fillText(t.desc, t.x + 16, t.y + 42);
  });

  // Bottom Technical Spec Panel
  const specY = 1000;
  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(45, specY, 2310, 315);
  masterCtx.strokeStyle = '#F59E0B';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(45, specY, 2310, 315);

  masterCtx.fillStyle = '#F59E0B';
  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillText('BATCH 3: MID-AIR KINETIC COLLISION & CLASH VFX AUDIT (C-01 THROUGH C-05)', 65, specY + 38);

  masterCtx.strokeStyle = '#334155';
  masterCtx.lineWidth = 1;
  masterCtx.beginPath(); masterCtx.moveTo(65, specY + 52); masterCtx.lineTo(2335, specY + 52); masterCtx.stroke();

  masterCtx.font = '12px monospace';
  masterCtx.fillStyle = '#E2E8F0';
  const lineH = 26;
  const col1X = 65;
  const col2X = 840;
  const col3X = 1600;

  // Column 1: Core Flash & Star Spikes
  masterCtx.fillText('• ASSET C-01: BLINDING CONTACT FLASH & 8m LENS FLARE STAR SPIKES', col1X, specY + 80);
  masterCtx.fillText('  - Centered at Y = 2.85m weapon impact intersection: additive white luminance sphere (#FFFFFF, opacity 0.9).', col1X, specY + 80 + lineH);
  masterCtx.fillText('  - 8m cross-axis lens flare star spikes (PlaneGeometry, additive #FEF08A) radiating along contact vector.', col1X, specY + 80 + lineH * 2);
  masterCtx.fillText('• ASSET C-02: DUAL-TONE EXPANDING SPHERICAL SHOCKWAVE RINGS', col1X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Inner Holy Gold shockwave ring (#F59E0B, radius 1.8m-3.2m) + Outer Hellfire Carmine shockwave ring (#EF4444, radius 3.0m-4.8m).', col1X, specY + 80 + lineH * 4);

  // Column 2: Flying Debris & Ground Ripple
  masterCtx.fillText('• ASSET C-03: 36 RADIAL FLYING SOLAR SHARDS & MAGMA SPLINTERS', col2X, specY + 80);
  masterCtx.fillText('  - High-velocity angular debris splinters flung radially in 360 degrees: 18 solar gold shards + 18 molten magma embers.', col2X, specY + 80 + lineH);
  masterCtx.fillText('• ASSET C-04: GROUND-LEVEL IMPACT RIPPLE PROPAGATING ONTO CRATER', col2X, specY + 80 + lineH * 2);
  masterCtx.fillText('  - Concentric planar shockwave ripple ring (RingGeometry 3.5m-6.0m, #F59E0B) projected flush onto crater deck below.', col2X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Simulates downward atmospheric shockwave concussive blast rattling the obsidian ground tiles.', col2X, specY + 80 + lineH * 4);

  // Column 3: Lighting & Pipeline Verification
  masterCtx.fillText('• ASSET C-05: DYNAMIC OPPOSING CLASH POINT LIGHTING (GOLD VS FIRE)', col3X, specY + 80);
  masterCtx.fillText('  - Holy Solar Gold point light (#FDE047, intensity 5.0, distance 20m) casting golden wash on Kaelen.', col3X, specY + 80 + lineH);
  masterCtx.fillText('  - Hellfire Red point light (#EF4444, intensity 4.5, distance 20m) casting fiery crimson wash on Vulcan.', col3X, specY + 80 + lineH * 2);
  masterCtx.fillText('  - Central white-hot impact strobe (#FFFFFF, intensity 3.5, distance 12m) at exact weapon collision point.', col3X, specY + 80 + lineH * 3);
  masterCtx.fillText('• PRODUCTION READINESS: ALL 3 BATCHES (16 ASSETS) VERIFIED & READY FOR COMBINED KEYFRAME 02', col3X, specY + 80 + lineH * 4);

  // Upload Master Sheet
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('clash_vfx_master_sheet.png', masterBlob);
  console.log('SAVED: clash_vfx_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('CLASH_VFX_BATCH_3_AUDIT_COMPLETE');
}

