// ============================================================================
// THE GLITCH MARKET — 3D CHARACTER RIG: TOBY (BACON HAIR MC)
// BATCH 1: THE PROTAGONIST HERO RIG (SHOT 4 INTRO & ACT I)
//
// Assets:
// - T-01: Universal R6 Anatomy Rig with Authentic Roblox Studs & Bevels
// - T-02: 12-Segment Volumetric 3D Bacon Hair Mesh ("Pal Hair Reforged")
// - T-03: Multi-Expression Face Decal System (Glassy Eyes, Cheek Bandage, Grime)
// - T-04: Tattered Starter Teal Hoodie & Worn Denim Jeans with Frayed Rips
// - T-05: Bruised Scuffed Skin Decal Layer & Charred Work Boots
// - Auxiliary Props: Snapped Starter Oak Club & Floating Holographic Level 1 Stat Card
// ============================================================================

import * as THREE from 'three';
import { createBeveledBox, canvasTex } from './core/geo.js';

// ----------------------------------------------------------------------------
// PROCEDURAL TEXTURES
// ----------------------------------------------------------------------------

/**
 * T-03: Expressive Face Decal with Glassy Eyes, Cheek Bandage & Scratches
 */
export function createTobyFaceTexture(expression = 'bruised') {
  return canvasTex(`toby_face_${expression}`, 512, 512, (g, w, h) => {
    // Pale classic Roblox yellow skin base
    g.fillStyle = '#F8EE89';
    g.fillRect(0, 0, w, h);

    // Subtle skin ambient warmth & dirt smudges
    g.fillStyle = 'rgba(217, 119, 6, 0.08)';
    g.fillRect(40, 180, w - 80, 220);

    // Dirt smudge on left cheek and forehead
    g.fillStyle = 'rgba(74, 48, 28, 0.18)';
    g.beginPath();
    g.arc(120, 360, 48, 0, Math.PI * 2);
    g.fill();

    g.beginPath();
    g.arc(380, 140, 35, 0, Math.PI * 2);
    g.fill();

    // Bruise under left eye (purple/amber swelling)
    g.fillStyle = 'rgba(126, 34, 206, 0.22)';
    g.beginPath();
    g.ellipse(170, 275, 45, 25, 0.15, 0, Math.PI * 2);
    g.fill();

    g.fillStyle = 'rgba(180, 83, 9, 0.25)';
    g.beginPath();
    g.ellipse(170, 278, 32, 16, 0.1, 0, Math.PI * 2);
    g.fill();

    // EYEBROWS
    g.strokeStyle = '#3E2718';
    g.lineWidth = 14;
    g.lineCap = 'round';

    if (expression === 'defiant') {
      // Fierce angled down brow
      g.beginPath(); g.moveTo(130, 185); g.lineTo(215, 205); g.stroke();
      g.beginPath(); g.moveTo(382, 185); g.lineTo(297, 205); g.stroke();
    } else {
      // Bruised / Melancholic underdog brow (raised in center)
      g.beginPath(); g.moveTo(130, 215); g.lineTo(215, 180); g.stroke();
      g.beginPath(); g.moveTo(382, 215); g.lineTo(297, 180); g.stroke();
    }

    // EYES
    // Sclera / Whites
    g.fillStyle = '#FFFFFF';
    g.beginPath(); g.ellipse(175, 235, 38, 48, 0, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.ellipse(337, 235, 38, 48, 0, 0, Math.PI * 2); g.fill();

    // Iris (Deep warm anime hazel-brown)
    g.fillStyle = '#451A03';
    g.beginPath(); g.arc(175, 238, 26, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(337, 238, 26, 0, Math.PI * 2); g.fill();

    g.fillStyle = '#78350F';
    g.beginPath(); g.arc(175, 240, 18, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(337, 240, 18, 0, Math.PI * 2); g.fill();

    // Pupil
    g.fillStyle = '#0F0703';
    g.beginPath(); g.arc(175, 240, 11, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(337, 240, 11, 0, Math.PI * 2); g.fill();

    // Glassy Specular Catchlights (Anime tears / reflection)
    g.fillStyle = '#FFFFFF';
    g.beginPath(); g.arc(163, 224, 9, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(325, 224, 9, 0, Math.PI * 2); g.fill();

    g.beginPath(); g.arc(186, 248, 5, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(348, 248, 5, 0, Math.PI * 2); g.fill();

    // Tear welling in right eye lower lid
    if (expression === 'bruised') {
      g.fillStyle = 'rgba(255, 255, 255, 0.75)';
      g.beginPath(); g.ellipse(342, 275, 16, 8, 0, 0, Math.PI * 2); g.fill();
    }

    // NOSE SCRATCH (Linear red scrape)
    g.strokeStyle = '#B91C1C';
    g.lineWidth = 4;
    g.beginPath();
    g.moveTo(238, 280);
    g.lineTo(274, 272);
    g.stroke();

    // CHEEK BANDAGE (White cross-stitch gauze on right cheek)
    g.save();
    g.translate(355, 340);
    g.rotate(-0.2);

    // Bandage Tape Base
    g.fillStyle = '#F8FAFC';
    g.shadowColor = 'rgba(0, 0, 0, 0.15)';
    g.shadowBlur = 6;
    g.fillRect(-42, -18, 84, 36);

    // Inner gauze pad
    g.fillStyle = '#E2E8F0';
    g.fillRect(-22, -14, 44, 28);

    // Perforated edge dots
    g.fillStyle = '#94A3B8';
    [-34, 34].forEach(x => {
      for (let y = -10; y <= 10; y += 7) {
        g.fillRect(x, y, 2, 2);
      }
    });

    g.restore();

    // MOUTH
    g.lineWidth = 8;
    g.lineCap = 'round';
    if (expression === 'defiant') {
      // Clenched determined grit
      g.strokeStyle = '#1F1108';
      g.beginPath();
      g.moveTo(215, 385);
      g.lineTo(297, 380);
      g.stroke();
    } else {
      // Quivering, slightly downturned hurt mouth
      g.strokeStyle = '#1F1108';
      g.beginPath();
      g.moveTo(215, 395);
      g.quadraticCurveTo(256, 375, 297, 392);
      g.stroke();

      // Lower lip tremble notch
      g.strokeStyle = 'rgba(185, 28, 28, 0.6)';
      g.lineWidth = 4;
      g.beginPath();
      g.moveTo(246, 404);
      g.lineTo(266, 404);
      g.stroke();
    }
  }, [1, 1]);
}

/**
 * T-04: Tattered Starter Teal Hoodie Texture
 */
export function createTatteredHoodieTexture() {
  return canvasTex('toby_hoodie_tattered', 512, 512, (g, w, h) => {
    // Faded vintage teal fabric base
    g.fillStyle = '#0F766E';
    g.fillRect(0, 0, w, h);

    // Procedural cotton canvas fabric weave
    g.fillStyle = '#115E59';
    for (let x = 0; x < w; x += 4) {
      g.fillRect(x, 0, 1.5, h);
    }
    for (let y = 0; y < h; y += 4) {
      g.fillRect(0, y, w, 1.5);
    }

    // Kangaroo Pocket outline in center
    g.fillStyle = '#0D9488';
    g.fillRect(90, 290, 332, 160);
    g.strokeStyle = '#042F2E';
    g.lineWidth = 6;
    g.strokeRect(90, 290, 332, 160);

    // Pocket side diagonal entry slits
    g.strokeStyle = '#134E4A';
    g.lineWidth = 10;
    g.beginPath(); g.moveTo(90, 290); g.lineTo(150, 450); g.stroke();
    g.beginPath(); g.moveTo(422, 290); g.lineTo(362, 450); g.stroke();

    // Drawstrings dangling from collar
    g.strokeStyle = '#E2E8F0';
    g.lineWidth = 6;
    g.beginPath(); g.moveTo(225, 60); g.lineTo(215, 210); g.stroke();
    g.beginPath(); g.moveTo(287, 60); g.lineTo(297, 225); g.stroke();

    // Metal aglets on drawstrings
    g.fillStyle = '#CBD5E1';
    g.fillRect(211, 205, 8, 18);
    g.fillRect(293, 220, 8, 18);

    // Weathered dirt smudges and mud stains
    g.fillStyle = 'rgba(40, 24, 12, 0.35)';
    g.beginPath(); g.ellipse(140, 380, 55, 30, 0.3, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.ellipse(350, 420, 65, 35, -0.2, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.ellipse(280, 180, 40, 20, 0.4, 0, Math.PI * 2); g.fill();

    // Ripped fabric tear with exposed frayed white stitching
    g.strokeStyle = '#042F2E';
    g.lineWidth = 5;
    g.beginPath(); g.moveTo(330, 210); g.lineTo(365, 235); g.lineTo(350, 260); g.stroke();

    g.strokeStyle = '#F8FAFC';
    g.lineWidth = 2;
    for (let i = 0; i < 6; i++) {
      const rx = 335 + i * 4;
      const ry = 220 + i * 5;
      g.beginPath(); g.moveTo(rx - 4, ry - 3); g.lineTo(rx + 4, ry + 3); g.stroke();
    }
  }, [1, 1]);
}

/**
 * T-04: Faded Starter Denim Jeans Texture with Ripped Knee Threads
 */
export function createDenimJeansTexture() {
  return canvasTex('toby_denim_jeans', 512, 512, (g, w, h) => {
    // Dark indigo denim base
    g.fillStyle = '#1E3A8A';
    g.fillRect(0, 0, w, h);

    // Diagonal twill denim texture
    g.strokeStyle = '#2563EB';
    g.lineWidth = 1;
    for (let i = -w; i < w * 2; i += 5) {
      g.beginPath();
      g.moveTo(i, 0);
      g.lineTo(i + h, h);
      g.stroke();
    }

    // Faded wash on thighs and knees
    g.fillStyle = 'rgba(147, 197, 253, 0.18)';
    g.fillRect(40, 60, w - 80, 320);

    // Orange copper seam stitching
    g.strokeStyle = '#D97706';
    g.lineWidth = 3;
    g.beginPath(); g.moveTo(30, 0); g.lineTo(30, h); g.stroke();
    g.beginPath(); g.moveTo(w - 30, 0); g.lineTo(w - 30, h); g.stroke();

    // Big Ripped Knee Hole with frayed white threads
    g.fillStyle = '#F8EE89'; // exposed yellow knee plastic beneath rip
    g.fillRect(180, 220, 150, 75);

    g.fillStyle = '#0F172A'; // deep hole shadow
    g.fillRect(190, 230, 130, 55);

    // Frayed horizontal white cotton denim threads across the tear
    g.strokeStyle = '#F8FAFC';
    g.lineWidth = 2.5;
    for (let y = 235; y <= 280; y += 6) {
      const xStart = 175 + Math.random() * 10;
      const xEnd = 330 - Math.random() * 10;
      g.beginPath(); g.moveTo(xStart, y); g.lineTo(xEnd, y); g.stroke();
    }

    // Mud splatter on hem
    g.fillStyle = 'rgba(56, 32, 14, 0.45)';
    g.beginPath(); g.ellipse(256, 480, 180, 45, 0, 0, Math.PI * 2); g.fill();
  }, [1, 1]);
}

// ----------------------------------------------------------------------------
// ASSET T-02: 12-SEGMENT VOLUMETRIC 3D BACON HAIR MESH ("PAL HAIR REFORGED")
// ----------------------------------------------------------------------------

export function buildBaconHairMesh() {
  const hairGroup = new THREE.Group();
  hairGroup.name = 'VolumetricBaconHair_3D';

  const matBaseBrown = new THREE.MeshStandardMaterial({
    color: 0x5C3317,
    roughness: 0.75,
    metalness: 0.1
  });

  const matMidBrown = new THREE.MeshStandardMaterial({
    color: 0x78350F,
    roughness: 0.7,
    metalness: 0.12
  });

  const matLightToffee = new THREE.MeshStandardMaterial({
    color: 0x92400E,
    roughness: 0.65,
    metalness: 0.15
  });

  const matGoldenHighlight = new THREE.MeshStandardMaterial({
    color: 0xB45309,
    roughness: 0.6,
    metalness: 0.18
  });

  // Layer 1: Scalp Cap Base
  const cap = createBeveledBox(1.36, 0.4, 1.36, 0.04, 2, matBaseBrown);
  cap.position.set(0, 0.55, 0);
  hairGroup.add(cap);

  // Layer 2: 3 Iconic Front Wavy Bacon Strips (Swept across forehead)
  const frontStrips = [
    { x: -0.32, y: 0.38, z: 0.68, w: 0.38, l: 0.72, rotZ: 0.22, rotX: -0.15, mat: matLightToffee },
    { x: 0.06,  y: 0.42, z: 0.72, w: 0.42, l: 0.85, rotZ: -0.12, rotX: -0.18, mat: matGoldenHighlight },
    { x: 0.42,  y: 0.36, z: 0.66, w: 0.36, l: 0.68, rotZ: -0.32, rotX: -0.12, mat: matMidBrown }
  ];

  frontStrips.forEach(s => {
    const strip = createBeveledBox(s.w, s.l, 0.22, 0.03, 2, s.mat);
    strip.position.set(s.x, s.y, s.z);
    strip.rotation.z = s.rotZ;
    strip.rotation.x = s.rotX;
    hairGroup.add(strip);
  });

  // Layer 3: Left & Right Flared Ear Wings (Classic Bacon Hair side volume)
  [-1, 1].forEach(side => {
    const sideSlab1 = createBeveledBox(0.28, 0.95, 0.85, 0.04, 2, matMidBrown);
    sideSlab1.position.set(side * 0.75, 0.25, 0.12);
    sideSlab1.rotation.z = side * -0.18;
    hairGroup.add(sideSlab1);

    const sideSlab2 = createBeveledBox(0.24, 0.75, 0.65, 0.03, 2, matLightToffee);
    sideSlab2.position.set(side * 0.82, 0.18, 0.05);
    sideSlab2.rotation.z = side * -0.28;
    sideSlab2.rotation.y = side * 0.12;
    hairGroup.add(sideSlab2);
  });

  // Layer 4: Disheveled Crown Cowlicks on Top (Anime protag texture)
  const cowlicks = [
    { x: -0.15, y: 0.82, z: 0.1,  w: 0.32, h: 0.35, d: 0.55, rz: 0.28, rx: 0.15, mat: matGoldenHighlight },
    { x: 0.2,   y: 0.85, z: -0.15, w: 0.35, h: 0.38, d: 0.6,  rz: -0.22, rx: -0.1, mat: matLightToffee },
    { x: -0.05, y: 0.88, z: -0.25, w: 0.28, h: 0.32, d: 0.5,  rz: 0.1,   rx: -0.25, mat: matMidBrown }
  ];

  cowlicks.forEach(c => {
    const t = createBeveledBox(c.w, c.h, c.d, 0.03, 2, c.mat);
    t.position.set(c.x, c.y, c.z);
    t.rotation.z = c.rz;
    t.rotation.x = c.rx;
    hairGroup.add(t);
  });

  // Layer 5: Rear Tapered Cascade (Curving down back of head)
  const rearTaper1 = createBeveledBox(1.15, 0.75, 0.28, 0.04, 2, matBaseBrown);
  rearTaper1.position.set(0, 0.25, -0.72);
  rearTaper1.rotation.x = 0.15;
  hairGroup.add(rearTaper1);

  const rearTaper2 = createBeveledBox(0.95, 0.6, 0.24, 0.03, 2, matMidBrown);
  rearTaper2.position.set(0, -0.15, -0.76);
  rearTaper2.rotation.x = 0.25;
  hairGroup.add(rearTaper2);

  return hairGroup;
}

// ----------------------------------------------------------------------------
// ASSET P-01: SNAPPED BEGINNER WOODEN CLUB
// ----------------------------------------------------------------------------

export function buildSnappedClub() {
  const club = new THREE.Group();
  club.name = 'SnappedStarterClub';

  const matOak = new THREE.MeshStandardMaterial({
    color: 0x78350F,
    roughness: 0.85,
    metalness: 0.05
  });

  const matSplinter = new THREE.MeshStandardMaterial({
    color: 0xD97706,
    roughness: 0.9,
    metalness: 0.0
  });

  // Chunk 1: The Handle & Grip (Lying flat on ground)
  const handleGroup = new THREE.Group();
  const handleShaft = new THREE.Mesh(new THREE.CylinderGeometry(0.08, 0.1, 1.2, 8), matOak);
  handleShaft.rotation.z = Math.PI / 2;
  handleGroup.add(handleShaft);

  // Splintered jagged break at tip
  for (let s = 0; s < 5; s++) {
    const sp = new THREE.Mesh(new THREE.ConeGeometry(0.04, 0.25, 4), matSplinter);
    sp.position.set(0.6, (s - 2) * 0.03, (s % 2) * 0.03);
    sp.rotation.z = -Math.PI / 2;
    handleGroup.add(sp);
  }
  handleGroup.position.set(0.6, 0.08, 0.3);
  handleGroup.rotation.y = 0.45;
  club.add(handleGroup);

  // Chunk 2: The Broken Club Head (Cracked away 0.4m away)
  const headGroup = new THREE.Group();
  const headShaft = new THREE.Mesh(new THREE.CylinderGeometry(0.18, 0.11, 0.95, 8), matOak);
  headShaft.rotation.z = Math.PI / 2;
  headGroup.add(headShaft);

  // Splinters on head side
  for (let s = 0; s < 4; s++) {
    const sp = new THREE.Mesh(new THREE.ConeGeometry(0.04, 0.22, 4), matSplinter);
    sp.position.set(-0.48, (s - 1.5) * 0.04, 0);
    sp.rotation.z = Math.PI / 2;
    headGroup.add(sp);
  }
  headGroup.position.set(1.45, 0.12, 0.65);
  headGroup.rotation.y = -0.35;
  headGroup.rotation.z = 0.12;
  club.add(headGroup);

  return club;
}

// ----------------------------------------------------------------------------
// ASSET P-02: HOLOGRAPHIC LEVEL 1 PLAYER STAT CARD
// ----------------------------------------------------------------------------

export function buildLevel1StatCard() {
  const cardGroup = new THREE.Group();
  cardGroup.name = 'HolographicLevel1StatCard';

  const cardTex = canvasTex('toby_level1_stat_card', 512, 256, (g, w, h) => {
    // Semi-transparent dark slate backdrop
    g.fillStyle = 'rgba(15, 23, 42, 0.88)';
    g.fillRect(0, 0, w, h);

    // Flashing red/amber alert border
    g.strokeStyle = '#EF4444';
    g.lineWidth = 6;
    g.strokeRect(6, 6, w - 12, h - 12);

    // Inner subtle grid
    g.strokeStyle = 'rgba(239, 68, 68, 0.15)';
    g.lineWidth = 1;
    for (let x = 20; x < w; x += 20) {
      g.beginPath(); g.moveTo(x, 10); g.lineTo(x, h - 10); g.stroke();
    }

    // Title Bar
    g.fillStyle = '#EF4444';
    g.font = 'bold 22px monospace';
    g.fillText('⚠ DIEGETIC PLAYER STATUS // SECTOR 04', 24, 38);

    g.strokeStyle = '#EF4444';
    g.lineWidth = 2;
    g.beginPath(); g.moveTo(24, 48); g.lineTo(w - 24, 48); g.stroke();

    // Player Header
    g.fillStyle = '#FFFFFF';
    g.font = '900 28px sans-serif';
    g.fillText('TOBY [STARTER NOOB]', 24, 85);

    g.fillStyle = '#94A3B8';
    g.font = 'bold 18px monospace';
    g.fillText('CLASS: COMMON BACON HAIR', 24, 112);

    // Level & Robux
    g.fillStyle = '#EF4444';
    g.font = 'bold 24px monospace';
    g.fillText('LEVEL: 1', 24, 150);
    g.fillText('ROBUX: 0 R$', 24, 180);

    // Right Column Stats
    g.fillStyle = '#94A3B8';
    g.font = '16px monospace';
    g.fillText('HP: 100 / 100', 280, 85);
    g.fillText('STR: 1  | AGI: 1', 280, 115);
    g.fillText('DEF: 1  | LUCK: 0', 280, 145);

    // Humiliating Rank Badge
    g.fillStyle = '#EF4444';
    g.fillRect(280, 165, 200, 42);
    g.fillStyle = '#FFFFFF';
    g.font = 'bold 18px monospace';
    g.fillText('RANK: TRASH (F-)', 295, 192);
  }, [1, 1]);

  const cardGeo = new THREE.PlaneGeometry(2.4, 1.2);
  const cardMat = new THREE.MeshBasicMaterial({
    map: cardTex,
    transparent: true,
    opacity: 0.92,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const mesh = new THREE.Mesh(cardGeo, cardMat);
  cardGroup.add(mesh);

  // Holographic blue/red edge frame
  const frameGeo = new THREE.RingGeometry(1.2, 1.24, 4);
  const frameMat = new THREE.MeshBasicMaterial({
    color: 0xEF4444,
    transparent: true,
    opacity: 0.6,
    side: THREE.DoubleSide
  });
  const frame = new THREE.Mesh(frameGeo, frameMat);
  frame.scale.set(1.0, 0.5, 1.0);
  cardGroup.add(frame);

  return cardGroup;
}

// ----------------------------------------------------------------------------
// ASSET T-01: MASTER UNIVERSAL R6 TOBY AVATAR RIG
// ----------------------------------------------------------------------------

export function buildTobyAvatar(options = {}) {
  const root = new THREE.Group();
  root.name = 'Toby_BaconHair_MC';

  const expression = options.expression || 'bruised';
  const pose = options.pose || 'kneeling'; // 'standing' or 'kneeling'

  // Standard Skin Material (Pale classic Roblox yellow with slight warmth)
  const matSkin = new THREE.MeshStandardMaterial({
    color: 0xF8EE89,
    roughness: 0.55,
    metalness: 0.08
  });

  // Tattered Hoodie Material
  const matHoodie = new THREE.MeshStandardMaterial({
    color: 0x0F766E,
    roughness: 0.8,
    metalness: 0.05,
    map: createTatteredHoodieTexture()
  });

  // Denim Jeans Material
  const matDenim = new THREE.MeshStandardMaterial({
    color: 0x1E3A8A,
    roughness: 0.75,
    metalness: 0.1,
    map: createDenimJeansTexture()
  });

  // Charred Work Boots Material
  const matBoot = new THREE.MeshStandardMaterial({
    color: 0x18181B,
    roughness: 0.85,
    metalness: 0.2
  });

  // Head Materials (Face Decal on Front, Skin on others)
  const faceDecal = createTobyFaceTexture(expression);
  const matHeadFront = new THREE.MeshStandardMaterial({
    map: faceDecal,
    roughness: 0.5,
    metalness: 0.05
  });
  const headMaterials = [
    matSkin,       // +X Right
    matSkin,       // -X Left
    matSkin,       // +Y Top
    matSkin,       // -Y Bottom
    matHeadFront,  // +Z Front (Face Decal!)
    matSkin        // -Z Back
  ];

  // --------------------------------------------------------------------------
  // TORSO
  // --------------------------------------------------------------------------
  const torso = new THREE.Group();
  torso.name = 'Torso';

  const torsoMesh = createBeveledBox(2.0, 2.0, 1.0, 0.04, 2, matHoodie);
  torso.add(torsoMesh);

  // Authentic Neck Stud on Top of Torso
  const neckStud = new THREE.Mesh(
    new THREE.CylinderGeometry(0.32, 0.32, 0.25, 16),
    matSkin
  );
  neckStud.position.set(0, 1.1, 0);
  torso.add(neckStud);

  // --------------------------------------------------------------------------
  // HEAD & 3D BACON HAIR MESH
  // --------------------------------------------------------------------------
  const headGroup = new THREE.Group();
  headGroup.name = 'Head';
  headGroup.position.set(0, 1.72, 0);

  const headMesh = createBeveledBox(1.2, 1.2, 1.2, 0.04, 2, headMaterials);
  headGroup.add(headMesh);

  // Authentic Roblox Top Stud
  const topStud = new THREE.Mesh(
    new THREE.CylinderGeometry(0.24, 0.24, 0.15, 16),
    matSkin
  );
  topStud.position.set(0, 0.67, 0);
  headGroup.add(topStud);

  // Mount 3D Layered Bacon Hair
  const hair = buildBaconHairMesh();
  hair.position.set(0, 0.18, 0);
  headGroup.add(hair);

  torso.add(headGroup);

  // --------------------------------------------------------------------------
  // ARMS
  // --------------------------------------------------------------------------
  // Left Arm (Ripped sleeve exposing yellow plastic forearm)
  const armL = new THREE.Group();
  armL.name = 'LeftArm';
  armL.position.set(-1.5, 0.75, 0);

  const armLMesh = createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, matHoodie);
  armLMesh.position.set(0, -0.75, 0);
  armL.add(armLMesh);

  // Bare skin exposed below rip
  const bareHandL = createBeveledBox(0.96, 0.5, 0.96, 0.03, 2, matSkin);
  bareHandL.position.set(0, -1.5, 0);
  armL.add(bareHandL);

  torso.add(armL);

  // Right Arm (Scuffed starter sleeve)
  const armR = new THREE.Group();
  armR.name = 'RightArm';
  armR.position.set(1.5, 0.75, 0);

  const armRMesh = createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, matHoodie);
  armRMesh.position.set(0, -0.75, 0);
  armR.add(armRMesh);

  const bareHandR = createBeveledBox(0.96, 0.5, 0.96, 0.03, 2, matSkin);
  bareHandR.position.set(0, -1.5, 0);
  armR.add(bareHandR);

  torso.add(armR);

  // --------------------------------------------------------------------------
  // LEGS & BOOTS
  // --------------------------------------------------------------------------
  const legL = new THREE.Group();
  legL.name = 'LeftLeg';
  legL.position.set(-0.52, -1.0, 0);

  const legLMesh = createBeveledBox(1.0, 1.6, 1.0, 0.04, 2, matDenim);
  legLMesh.position.set(0, -0.6, 0);
  legL.add(legLMesh);

  const bootL = createBeveledBox(1.04, 0.55, 1.2, 0.04, 2, matBoot);
  bootL.position.set(0, -1.5, 0.08);
  legL.add(bootL);

  torso.add(legL);

  const legR = new THREE.Group();
  legR.name = 'RightLeg';
  legR.position.set(0.52, -1.0, 0);

  const legRMesh = createBeveledBox(1.0, 1.6, 1.0, 0.04, 2, matDenim);
  legRMesh.position.set(0, -0.6, 0);
  legR.add(legRMesh);

  const bootR = createBeveledBox(1.04, 0.55, 1.2, 0.04, 2, matBoot);
  bootR.position.set(0, -1.5, 0.08);
  legR.add(bootR);

  torso.add(legR);

  // --------------------------------------------------------------------------
  // POSE CONFIGURATION
  // --------------------------------------------------------------------------
  if (pose === 'kneeling') {
    // Cinematic Shot 4 Defeat Pose: Kneeling on one knee, hands drooping, head bowed
    torso.position.y = 1.15;
    torso.rotation.x = 0.28; // tilted forward in sorrow

    headGroup.rotation.x = 0.35; // head hung low looking down at broken club
    headGroup.rotation.y = -0.12;

    // Left knee planted forward, supporting left elbow
    legL.position.set(-0.55, -0.85, 0.45);
    legL.rotation.x = -1.15; // deeply bent knee
    legL.rotation.z = -0.12;

    // Right leg bent back, knee touching ground
    legR.position.set(0.55, -0.9, -0.35);
    legR.rotation.x = 1.35; // tucked behind
    legR.rotation.z = 0.18;

    // Arms hanging down towards the mud
    armL.rotation.set(-0.65, 0.15, -0.25);
    armR.rotation.set(-0.45, -0.12, 0.22);
  } else {
    // Default Hero Standing Stance (Solid, resilient, defiant)
    torso.position.y = 2.05;
    torso.rotation.x = 0.0;

    headGroup.rotation.x = -0.08; // chin up, looking straight ahead
    headGroup.rotation.y = 0.05;

    legL.rotation.set(0, 0, 0.06);
    legR.rotation.set(0, 0, -0.06);

    armL.rotation.set(-0.15, 0, -0.18);
    armR.rotation.set(-0.25, 0, 0.22);
  }

  root.add(torso);
  return root;
}

