// ============================================================================
// THE GLITCH MARKET — 5-ANGLE STUDIO AUDIT RENDERER
// BATCH 1: TOBY (BACON HAIR MC HERO RIG) — PROTAGONIST ASSET AUDIT
//
// Produces:
// 1. toby_angle_1_hero_standing.png (View 01: Hero 3/4 Standing Showcase & Silhouette)
// 2. toby_angle_2_hair_face_macro.png (View 02: 12-Segment Volumetric Bacon Hair & Bandaged Face)
// 3. toby_angle_3_hoodie_denim_details.png (View 03: Tattered Teal Hoodie, Frayed Denim & Scuffs)
// 4. toby_angle_4_kneeling_defeat.png (View 04: Shot 4 Kneeling Defeat Pose on Arena Curb)
// 5. toby_angle_5_props_stat_card.png (View 05: Snapped Oak Club & Holographic Level 1 Stat Card)
// 6. toby_master_sheet.png (2400x1350 5-Panel Production Audit Sheet)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import {
  buildTobyAvatar,
  buildSnappedClub,
  buildLevel1StatCard
} from './toby_avatar.js';

const ANGLES = [
  {
    id: 'toby_angle_1_hero_standing',
    title: 'VIEW 01: TOBY HERO RIG // FULL STANDING PERSPECTIVE',
    desc: 'Universal R6 anatomy: Authentic Roblox neck/shoulder studs, beveled joints, volumetric bacon hair & starter outfit',
    pos: [3.4, 2.6, 4.2],
    target: [0.0, 2.0, 0.0],
    fov: 42,
    mode: 'standing'
  },
  {
    id: 'toby_angle_2_hair_face_macro',
    title: 'VIEW 02: VOLUMETRIC 3D BACON HAIR & BANDAGED FACE MACRO',
    desc: '12-segment layered hair mesh with front sweeps & cowlicks, glassy anime eyes, cheek bandage & bruised cheek',
    pos: [0.95, 2.85, 1.85],
    target: [0.0, 2.8, 0.1],
    fov: 34,
    mode: 'macro_head'
  },
  {
    id: 'toby_angle_3_hoodie_denim_details',
    title: 'VIEW 03: TATTERED HOODIE, KANGAROO POCKET & FRAYED DENIM',
    desc: 'Procedural canvas hoodie with drawstrings, dirt smudges, indigo twill jeans with knee rip & charred work boots',
    pos: [-2.2, 1.8, 2.4],
    target: [-0.1, 1.6, 0.0],
    fov: 38,
    mode: 'standing'
  },
  {
    id: 'toby_angle_4_kneeling_defeat',
    title: 'VIEW 04: SHOT 4 SIGNATURE KNEELING DEFEAT POSE',
    desc: 'Sorrowful posture outside gates: left knee forward, right knee down in mud, head bowed over broken starter club',
    pos: [3.2, 1.9, 3.6],
    target: [0.0, 1.1, 0.0],
    fov: 40,
    mode: 'kneeling'
  },
  {
    id: 'toby_angle_5_props_stat_card',
    title: 'VIEW 05: SNAPPED STARTER CLUB & HOLOGRAPHIC STAT CARD',
    desc: 'Splintered oak weapon fragments on rain-slicked curb + semi-transparent diegetic UI card [LEVEL 1 | STATS: 0 | ROBUX: 0]',
    pos: [1.8, 1.4, 2.4],
    target: [0.3, 1.0, 0.2],
    fov: 38,
    mode: 'props'
  }
];

function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const renderer = new THREE.WebGLRenderer({
    canvas: glCanvas,
    antialias: true,
    alpha: false,
    preserveDrawingBuffer: true
  });
  renderer.setSize(1280, 760);
  renderer.setPixelRatio(1);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.3;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050811);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(400, 400, 320, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 50, 0);
  scene.add(skyDome);

  // Lighting Rig: Moody arena alley / studio lighting
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x0A0F1E, 0.85);
  scene.add(hemi);

  const keyLight = new THREE.DirectionalLight(0xFFFBEB, 1.7);
  keyLight.position.set(10, 14, 10);
  scene.add(keyLight);

  const fillCyan = new THREE.DirectionalLight(0x00F0FF, 1.2);
  fillCyan.position.set(-10, 8, -6);
  scene.add(fillCyan);

  const amberWarmRim = new THREE.DirectionalLight(0xF59E0B, 1.6);
  amberWarmRim.position.set(8, 6, -10);
  scene.add(amberWarmRim);

  const softHeadLight = new THREE.PointLight(0xFFFFFF, 1.2, 6.0);
  softHeadLight.position.set(0, 3.2, 1.5);
  scene.add(softHeadLight);

  // Rain-Slicked Stone Curb / Alley Floor
  const floorGeo = new THREE.CylinderGeometry(16, 16, 0.4, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x0B0F19,
    roughness: 0.35, // wet sheen
    metalness: 0.4
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.position.set(0, -0.2, 0);
  scene.add(floor);

  // Puddle Sheen Disc
  const puddleGeo = new THREE.CircleGeometry(3.5, 32);
  puddleGeo.rotateX(-Math.PI / 2);
  const puddleMat = new THREE.MeshStandardMaterial({
    color: 0x050A14,
    roughness: 0.1, // mirror-like water puddle
    metalness: 0.8,
    transparent: true,
    opacity: 0.85
  });
  const puddle = new THREE.Mesh(puddleGeo, puddleMat);
  puddle.position.set(0, 0.01, 0.3);
  scene.add(puddle);

  // Concrete Curb Edge
  const curbGeo = new THREE.BoxGeometry(12, 0.3, 0.8);
  const curbMat = new THREE.MeshStandardMaterial({
    color: 0x1E293B,
    roughness: 0.85,
    metalness: 0.1
  });
  const curb = new THREE.Mesh(curbGeo, curbMat);
  curb.position.set(0, 0.1, -1.8);
  scene.add(curb);

  // Rusted Colosseum Gate Bars in background
  const gateGroup = new THREE.Group();
  gateGroup.position.set(0, 0, -2.4);
  const barMat = new THREE.MeshStandardMaterial({
    color: 0x1E2430,
    metalness: 0.85,
    roughness: 0.6
  });
  for (let i = -7; i <= 7; i++) {
    const barGeo = new THREE.CylinderGeometry(0.045, 0.045, 6, 8);
    const bar = new THREE.Mesh(barGeo, barMat);
    bar.position.set(i * 0.7, 3, 0);
    gateGroup.add(bar);
  }
  const horizontalRailGeo = new THREE.BoxGeometry(11, 0.1, 0.1);
  const railBottom = new THREE.Mesh(horizontalRailGeo, barMat);
  railBottom.position.set(0, 0.8, 0);
  gateGroup.add(railBottom);
  const railTop = new THREE.Mesh(horizontalRailGeo, barMat);
  railTop.position.set(0, 5.0, 0);
  gateGroup.add(railTop);
  scene.add(gateGroup);

  // --------------------------------------------------------------------------
  // RIG 1: STANDING TOBY (HERO SHOWCASE & CLOSEUPS)
  // --------------------------------------------------------------------------
  const tobyStanding = buildTobyAvatar({
    pose: 'standing',
    expression: 'defiant'
  });
  tobyStanding.position.set(0, 0, 0);
  scene.add(tobyStanding);

  // --------------------------------------------------------------------------
  // RIG 2: KNEELING TOBY (SHOT 4 SIGNATURE DEFEAT POSE)
  // --------------------------------------------------------------------------
  const tobyKneeling = buildTobyAvatar({
    pose: 'kneeling',
    expression: 'bruised'
  });
  tobyKneeling.position.set(0, 0, 0);
  scene.add(tobyKneeling);

  // --------------------------------------------------------------------------
  // PROPS: SNAPPED OAK STARTER CLUB
  // --------------------------------------------------------------------------
  const snappedClub = buildSnappedClub();
  snappedClub.position.set(0.1, 0.05, 0.75);
  scene.add(snappedClub);

  // --------------------------------------------------------------------------
  // PROPS: HOLOGRAPHIC LEVEL 1 STAT CARD
  // --------------------------------------------------------------------------
  const statCard = buildLevel1StatCard();
  statCard.position.set(0.7, 1.45, 0.55);
  statCard.rotation.y = -0.35;
  scene.add(statCard);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    // Configure scene visibility per mode
    if (cfg.mode === 'standing' || cfg.mode === 'macro_head') {
      tobyStanding.visible = true;
      tobyKneeling.visible = false;
      snappedClub.visible = false;
      statCard.visible = false;
    } else if (cfg.mode === 'kneeling') {
      tobyStanding.visible = false;
      tobyKneeling.visible = true;
      snappedClub.visible = true;
      statCard.visible = false;
    } else if (cfg.mode === 'props') {
      tobyStanding.visible = false;
      tobyKneeling.visible = true;
      snappedClub.visible = true;
      statCard.visible = true;
    }

    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 350);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    renderer.render(scene, cam);

    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = 1280;
    angleCanvas.height = 760;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Overlay Badge
    actx.fillStyle = 'rgba(5, 8, 17, 0.82)';
    actx.fillRect(24, 24, 720, 68);
    actx.strokeStyle = '#00F0FF';
    actx.lineWidth = 1.5;
    actx.strokeRect(24, 24, 720, 68);

    actx.fillStyle = '#00F0FF';
    actx.font = 'bold 18px monospace';
    actx.fillText(cfg.title, 42, 52);

    actx.fillStyle = '#94A3B8';
    actx.font = '13px monospace';
    actx.fillText(cfg.desc, 42, 74);

    renderedCanvases.push(angleCanvas);

    // Upload individual angle
    const blob = await canvasToBlob(angleCanvas);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png`);
  }

  // ==========================================================================
  // COMPOSITE MASTER AUDIT SHEET (2400 × 1350)
  // ==========================================================================
  masterCtx.fillStyle = '#050811';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Cyber Grid Backdrop
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.05)';
  masterCtx.lineWidth = 1;
  const gridSize = 40;
  for (let x = 0; x < 2400; x += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Master Title Header
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 34px sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // BATCH 1: TOBY (BACON HAIR MC HERO RIG)', 45, 55);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText('ROBLOX UGC 3D CHARACTER ASSETS — 5 CORE ASSETS VERIFIED (T-01 THROUGH T-05 & AUX PROPS)', 45, 85);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('SHOT 4 HERO INTRODUCTION • "AND THAT\'S ME..."', 2355, 55);
  masterCtx.fillText('12-SEGMENT VOLUMETRIC BACON HAIR • TATTERED HOODIE • LEVEL 1 STAT CARD • SNAPPED CLUB', 2355, 78);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath(); masterCtx.moveTo(45, 105); masterCtx.lineTo(2355, 105); masterCtx.stroke();

  // Layout:
  // Large Hero on Left (1420 × 840)
  const heroX = 45;
  const heroY = 130;
  const heroW = 1420;
  const heroH = 840;

  masterCtx.drawImage(renderedCanvases[0], heroX, heroY, heroW, heroH);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(heroX, heroY, heroW, heroH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(heroX, heroY + heroH - 48, heroW, 48);
  masterCtx.fillStyle = '#38BDF8';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.fillText('VIEW 01: TOBY (PROTAGONIST R6 HERO RIG DISPLAY)', heroX + 16, heroY + heroH - 18);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('Authentic R6 block proportions with studs, bevels, 3D bacon hair, tattered teal hoodie & defiant expression', heroX + heroW - 16, heroY + heroH - 18);
  masterCtx.textAlign = 'left';

  // 4 Thumbnails on Right (2x2 Grid)
  const rightColX1 = 1500;
  const rightColX2 = 1940;
  const rowY1 = 130;
  const rowY2 = 572;
  const thumbW = 415;
  const thumbH = 398;

  const thumbs = [
    { idx: 1, x: rightColX1, y: rowY1, title: 'ANGLE 2: 3D BACON HAIR & FACE', desc: '12-segment mesh + anime eye gloss & bandage' },
    { idx: 2, x: rightColX2, y: rowY1, title: 'ANGLE 3: HOODIE & DENIM WEAR', desc: 'Pocket, drawstrings, knee rip & scuffed boots' },
    { idx: 3, x: rightColX1, y: rowY2, title: 'ANGLE 4: KNEELING DEFEAT POSE', desc: 'Signature Shot 4 bowed posture on arena curb' },
    { idx: 4, x: rightColX2, y: rowY2, title: 'ANGLE 5: PROPS & STAT CARD', desc: 'Snapped starter club & holographic Level 1 UI' }
  ];

  thumbs.forEach(t => {
    masterCtx.drawImage(renderedCanvases[t.idx], t.x, t.y, thumbW, thumbH);
    masterCtx.strokeStyle = '#00F0FF';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(t.x, t.y, thumbW, thumbH);

    masterCtx.fillStyle = 'rgba(7, 13, 27, 0.9)';
    masterCtx.fillRect(t.x + 8, t.y + 8, thumbW - 16, 44);
    masterCtx.strokeStyle = '#38BDF8';
    masterCtx.lineWidth = 1;
