// ============================================================================
// THE GLITCH MARKET — 3D CHARACTER RIG: CHAD_ROBUX (RICH BULLY PRO)
// BATCH 2: THE ANTAGONIST RIG (SHOT 4 BULLY & STREET SCENE)
//
// Assets:
// - B-01: Elite R6 Avatar Rig & Designer Drip (Glossy Black Tuxedo & Gold Lapels)
// - B-02: High-Tier Limited Headgear (Void Dominus Hood, Cyan Slits & Diamond Crown)
// - B-03: Floating VIP Flex Accessories (Shoulder Cyber-Dragon & Cuban Link Chain)
// - B-04: Gilded Frostfire Rapier (Hip Sheath with Cold Blue Embers)
// - B-05: Smug Arrogant Decals & Holographic VIP Status Tag [ROBUX: 2,500,000 R$]
// ============================================================================

import * as THREE from 'three';
import { createBeveledBox, canvasTex } from './core/geo.js';

// ----------------------------------------------------------------------------
// PROCEDURAL TEXTURES
// ----------------------------------------------------------------------------

/**
 * B-01: Designer Tuxedo Suit Texture with Gold Filigree Lapels & Cyan Pinstripes
 */
export function createDesignerTuxedoTexture() {
  return canvasTex('bully_designer_tuxedo', 512, 512, (g, w, h) => {
    // Ultra-rich dark obsidian silk suit base
    g.fillStyle = '#090D16';
    g.fillRect(0, 0, w, h);

    // Subtle cyan pinstripes
    g.strokeStyle = 'rgba(0, 240, 255, 0.12)';
    g.lineWidth = 1.5;
    for (let x = 15; x < w; x += 22) {
      g.beginPath();
      g.moveTo(x, 0);
      g.lineTo(x, h);
      g.stroke();
    }

    // Crisp white dress shirt V-inset
    g.fillStyle = '#F8FAFC';
    g.beginPath();
    g.moveTo(190, 0);
    g.lineTo(322, 0);
    g.lineTo(256, 185);
    g.closePath();
    g.fill();

    // Black silk bowtie
    g.fillStyle = '#0F172A';
    g.beginPath();
    g.moveTo(225, 40);
    g.lineTo(287, 40);
    g.lineTo(262, 55);
    g.lineTo(287, 70);
    g.lineTo(225, 70);
    g.lineTo(250, 55);
    g.closePath();
    g.fill();

    // Gold bowtie center knot
    g.fillStyle = '#F59E0B';
    g.fillRect(252, 50, 8, 10);

    // 24K Gold Filigree Tuxedo Lapels
    g.strokeStyle = '#F59E0B';
    g.lineWidth = 8;
    g.beginPath();
    g.moveTo(180, 0);
    g.lineTo(250, 240);
    g.stroke();

    g.beginPath();
    g.moveTo(332, 0);
    g.lineTo(262, 240);
    g.stroke();

    // Lapel inner shadow / contrast
    g.strokeStyle = '#D97706';
    g.lineWidth = 3;
    g.beginPath();
    g.moveTo(174, 0);
