/**
 * Builds the ultra-rare Void Dominus Hood with glowing cyan eye slits and floating crown
 */
export function buildBullyHeadgear() {
  const headgearGroup = new THREE.Group();
  headgearGroup.name = 'BullyHeadgear';

  // Obsidian Fabric Material
  const matDominus = new THREE.MeshStandardMaterial({
    color: 0x07090F,
    roughness: 0.35,
    metalness: 0.4
  });

  // Polished 24K Gold Trim Material
  const matGold = new THREE.MeshStandardMaterial({
    color: 0xF59E0B,
    roughness: 0.25,
    metalness: 0.85
  });

  // 1. Dominus Outer Hood Cowl (Surrounding top, back, sides)
  const cowlGeo = new THREE.BoxGeometry(1.5, 1.45, 1.5);
  const cowl = new THREE.Mesh(cowlGeo, matDominus);
  cowl.position.set(0, 0.12, -0.05);
  headgearGroup.add(cowl);

  // 2. Pointed Front Peak Brow
  const peakGeo = new THREE.ConeGeometry(0.35, 0.4, 4);
  const peak = new THREE.Mesh(peakGeo, matGold);
  peak.rotation.z = Math.PI;
  peak.rotation.y = Math.PI / 4;
  peak.position.set(0, 0.72, 0.72);
  headgearGroup.add(peak);

  // 3. Gold Trim Rim around Face Opening
  const trimGeo = new THREE.TorusGeometry(0.72, 0.05, 8, 24);
  const trim = new THREE.Mesh(trimGeo, matGold);
  trim.position.set(0, 0, 0.68);
  trim.scale.set(0.9, 1.05, 1.0);
  headgearGroup.add(trim);

  // 4. Glowing Cyan Eye Slits (Dominus Empyreus style)
  [-0.24, 0.24].forEach(side => {
    const eyeGeo = new THREE.BoxGeometry(0.22, 0.055, 0.08);
    const eyeMat = new THREE.MeshBasicMaterial({
      color: 0x00F0FF
    });
    const eye = new THREE.Mesh(eyeGeo, eyeMat);
    eye.position.set(side, 0.05, 0.69);
    eye.rotation.z = side * -0.22;
    headgearGroup.add(eye);

    // Glowing cyan eye flare halo
    const flareGeo = new THREE.PlaneGeometry(0.45, 0.15);
    const flareMat = new THREE.MeshBasicMaterial({
      color: 0x38BDF8,
      transparent: true,
      opacity: 0.65,
      blending: THREE.AdditiveBlending,
      side: THREE.DoubleSide,
      depthWrite: false
    });
    const flare = new THREE.Mesh(flareGeo, flareMat);
    flare.position.set(side * 1.05, 0.05, 0.70);
    headgearGroup.add(flare);
  });

  // 5. Floating Gilded Diamond Crown (Hovering over hood)
  const crownGroup = new THREE.Group();
  crownGroup.name = 'FloatingCrown';
  crownGroup.position.set(0, 1.15, 0);

  // Crown Base Ring
  const crownRingGeo = new THREE.CylinderGeometry(0.55, 0.58, 0.18, 16, 1, true);
  const crownRing = new THREE.Mesh(crownRingGeo, matGold);
  crownGroup.add(crownRing);

  // 5 Crown Points with Cyan Diamonds
  for (let i = 0; i < 5; i++) {
    const angle = (i / 5) * Math.PI * 2;
    const px = Math.cos(angle) * 0.56;
    const pz = Math.sin(angle) * 0.56;

    const pointGeo = new THREE.ConeGeometry(0.12, 0.35, 4);
    const point = new THREE.Mesh(pointGeo, matGold);
    point.position.set(px, 0.22, pz);
    point.rotation.y = angle;
    crownGroup.add(point);

    // Diamond gem tip
    const gemGeo = new THREE.OctahedronGeometry(0.065);
    const gemMat = new THREE.MeshBasicMaterial({ color: 0x00F0FF });
    const gem = new THREE.Mesh(gemGeo, gemMat);
    gem.position.set(px, 0.42, pz);
    crownGroup.add(gem);
  }

  // Floating Crown Glow Disc
  const glowDiscGeo = new THREE.RingGeometry(0.45, 0.65, 16);
  const glowDiscMat = new THREE.MeshBasicMaterial({
    color: 0xFDE047,
    transparent: true,
    opacity: 0.35,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const glowDisc = new THREE.Mesh(glowDiscGeo, glowDiscMat);
  glowDisc.rotation.x = Math.PI / 2;
  glowDisc.position.set(0, -0.05, 0);
  crownGroup.add(glowDisc);

  headgearGroup.add(crownGroup);
  return headgearGroup;
}

