  const headgear = buildBullyHeadgear();
  headGroup.add(headgear);

  torso.add(headGroup);

  // --------------------------------------------------------------------------
  // ARMS
  // --------------------------------------------------------------------------
  const armL = new THREE.Group();
  armL.name = 'LeftArm';
  armL.position.set(-1.5, 0.75, 0);

  const armLMesh = createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, matSleeve);
  armLMesh.position.set(0, -0.75, 0);
  armL.add(armLMesh);

  const handL = createBeveledBox(0.96, 0.5, 0.96, 0.03, 2, matSkin);
  handL.position.set(0, -1.5, 0);
  armL.add(handL);

  torso.add(armL);

  const armR = new THREE.Group();
  armR.name = 'RightArm';
  armR.position.set(1.5, 0.75, 0);

  const armRMesh = createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, matSleeve);
  armRMesh.position.set(0, -0.75, 0);
  armR.add(armRMesh);

  const handR = createBeveledBox(0.96, 0.5, 0.96, 0.03, 2, matSkin);
  handR.position.set(0, -1.5, 0);
  armR.add(handR);

  torso.add(armR);

  // Mount Shoulder Cyber-Dragon Pet hovering over right shoulder
  const dragon = buildShoulderDragonPet();
  dragon.position.set(1.7, 1.85, 0.2);
  dragon.rotation.y = -0.3;
  torso.add(dragon);

  // --------------------------------------------------------------------------
  // HIP-MOUNTED GILDED FROSTFIRE RAPIER
  // --------------------------------------------------------------------------
  const rapier = buildGildedRapier();
  rapier.position.set(-1.18, -0.35, 0.15);
  rapier.rotation.z = 0.25; // angled slung against hip
  rapier.rotation.y = 0.15;
  torso.add(rapier);

  // --------------------------------------------------------------------------
  // LEGS & PATENT LEATHER SHOES
  // --------------------------------------------------------------------------
  const legL = new THREE.Group();
  legL.name = 'LeftLeg';
  legL.position.set(-0.52, -1.0, 0);

  const legLMesh = createBeveledBox(1.0, 1.6, 1.0, 0.04, 2, matSlacks);
  legLMesh.position.set(0, -0.6, 0);
  legL.add(legLMesh);

  const shoeL = createBeveledBox(1.04, 0.55, 1.25, 0.04, 2, matShoe);
  shoeL.position.set(0, -1.5, 0.08);
  legL.add(shoeL);

  torso.add(legL);

  const legR = new THREE.Group();
  legR.name = 'RightLeg';
  legR.position.set(0.52, -1.0, 0);

  const legRMesh = createBeveledBox(1.0, 1.6, 1.0, 0.04, 2, matSlacks);
  legRMesh.position.set(0, -0.6, 0);
  legR.add(legRMesh);

  const shoeR = createBeveledBox(1.04, 0.55, 1.25, 0.04, 2, matShoe);
  shoeR.position.set(0, -1.5, 0.08);
  legR.add(shoeR);

  torso.add(legR);

  // --------------------------------------------------------------------------
  // KINEMATICS & POSE
  // --------------------------------------------------------------------------
  torso.position.y = 2.05;

  if (pose === 'pointing_mock') {
    // Shot 4 Mocking Pose: Right arm extended pointing down at Toby, laughing
    headGroup.rotation.set(-0.15, -0.22, 0.1); // chin up, smirk angled down
    armR.rotation.set(1.2, -0.3, 0.25); // pointing forward/down
    armL.rotation.set(-0.35, 0.15, -0.2); // hand casually at side/hip
    legL.rotation.set(-0.12, 0, 0.08);
    legR.rotation.set(0.15, 0, -0.06);
  } else if (pose === 'arms_crossed') {
    // Arrogant folded arms
    armL.rotation.set(0.85, 0.6, -0.4);
    armR.rotation.set(0.85, -0.6, 0.4);
    headGroup.rotation.set(-0.1, 0.1, 0);
  } else {
    // Default Swagger Stance (Hands slightly back, chest pushed forward)
    torso.rotation.x = -0.06; // slight haughty lean back
    headGroup.rotation.set(-0.12, -0.08, 0.05); // tilted head
    armL.rotation.set(-0.25, 0.1, -0.22);
    armR.rotation.set(-0.18, -0.08, 0.18);
    legL.rotation.set(0, 0, 0.08);
    legR.rotation.set(0, 0, -0.08);
  }

  root.add(torso);
  return root;
}

// ============================================================================
// THE GLITCH MARKET — 5-ANGLE STUDIO AUDIT RENDERER
// BATCH 2: CHAD_ROBUX (RICH BULLY PRO RIG) — ANTAGONIST ASSET AUDIT
//
// Produces:
// 1. bully_angle_1_hero_standing.png (View 01: Hero 3/4 Standing Showcase & Swagger Drip)
// 2. bully_angle_2_headgear_crown.png (View 02: Void Dominus Hood, Cyan Slits & Diamond Crown)
// 3. bully_angle_3_shoulder_dragon.png (View 03: Floating Shoulder Cyber-Dragon & Cuban Link Chain)
// 4. bully_angle_4_rapier_drip.png (View 04: Gilded Frostfire Rapier Sheath & Blue Flame Embers)
// 5. bully_angle_5_mocking_stance.png (View 05: Shot 4 Mocking Pointing Pose & VIP Status Tag)
// 6. bully_master_sheet.png (2400x1350 5-Panel Production Audit Sheet)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import {
  buildBullyAvatar,
  buildVIPStatusTag
} from './bully_avatar.js';

const ANGLES = [
  {
    id: 'bully_angle_1_hero_standing',
    title: 'VIEW 01: CHAD_ROBUX // FULL SWAGGER PERSPECTIVE',
    desc: 'Elite Pro Rig: Glossy obsidian tuxedo with gold lapels, Dominus cowl, diamond crown, dragon pet & gilded rapier',
    pos: [4.2, 2.5, 5.0],
    target: [0.0, 2.2, 0.0],
    fov: 46,
    mode: 'standing'
  },
  {
    id: 'bully_angle_2_headgear_crown',
    title: 'VIEW 02: VOID DOMINUS HOOD & FLOATING DIAMOND CROWN MACRO',
    desc: 'Deep black cowl with gold trim, glowing cyan eye slits, 5-point diamond crown with levitation aura disc',
    pos: [0.8, 4.0, 2.6],
    target: [0.0, 3.8, 0.4],
    fov: 36,
    mode: 'standing'
  },
  {
    id: 'bully_angle_3_shoulder_dragon',
    title: 'VIEW 03: CYBER-DRAGON PET & CHUNKY CUBAN LINK CHAIN',
    desc: 'Articulated low-poly shoulder dragon with cyan wing blades + heavy gold chain with diamond [R$] dollar pendant',
    pos: [2.8, 3.2, 2.6],
    target: [0.9, 2.9, 0.3],
    fov: 38,
    mode: 'standing'
  },
  {
    id: 'bully_angle_4_rapier_drip',
    title: 'VIEW 04: GILDED FROSTFIRE RAPIER & OBSIDIAN SCABBARD',
    desc: '1.4m rapier in gold-banded hip sheath with swept cup hilt, cyan embers, tailored slacks & patent leather shoes',
    pos: [-2.5, 1.8, 2.4],
    target: [-0.8, 1.6, 0.1],
    fov: 38,
    mode: 'standing'
  },
  {
    id: 'bully_angle_5_mocking_stance',
    title: 'VIEW 05: SHOT 4 MOCKING POSE & HOLOGRAPHIC VIP TAG',
    desc: 'Right arm pointing in mockery + glowing luxury status tag [ROBUX: 2,500,000 R$ | GUILD: APEX SOVEREIGNS]',
    pos: [3.4, 2.2, 4.2],
    target: [0.4, 1.9, 0.2],
    fov: 44,
    mode: 'pointing'
  }
];

function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const renderer = new THREE.WebGLRenderer({
    canvas: glCanvas,
    antialias: true,
    alpha: false,
    preserveDrawingBuffer: true
  });
  renderer.setSize(1280, 760);
  renderer.setPixelRatio(1);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.35;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x060913);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(400, 400, 320, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 50, 0);
  scene.add(skyDome);

  // Studio Lighting Rig: High-contrast luxury key & cyan rims
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x0A0F1E, 1.0);
  scene.add(hemi);

  const keyLight = new THREE.DirectionalLight(0xFFFBEB, 2.2);
  keyLight.position.set(8, 12, 10);
  scene.add(keyLight);

  const frontCamKey = new THREE.DirectionalLight(0xFFFFFF, 1.8);
  frontCamKey.position.set(2, 4, 7);
  scene.add(frontCamKey);

  const fillCyan = new THREE.DirectionalLight(0x00F0FF, 1.6);
  fillCyan.position.set(-8, 6, 4);
  scene.add(fillCyan);

  const goldRim = new THREE.DirectionalLight(0xF59E0B, 2.4);
  goldRim.position.set(-8, 8, -8);
  scene.add(goldRim);

  const headGlow = new THREE.PointLight(0x00F0FF, 2.0, 5.0);
  headGlow.position.set(0, 3.8, 1.2);
  scene.add(headGlow);

  // Floating Luxury Orbit Rings around waist
  const orbitGroup = new THREE.Group();
  orbitGroup.position.set(0, 2.0, 0);
  for (let r = 0; r < 2; r++) {
    const ringGeo = new THREE.TorusGeometry(1.4 + r * 0.35, 0.025, 8, 32);
    const ringMat = new THREE.MeshBasicMaterial({
      color: r === 0 ? 0xF59E0B : 0x00F0FF,
      transparent: true,
      opacity: 0.7,
      blending: THREE.AdditiveBlending
    });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.rotation.x = Math.PI / 2 + 0.15 * (r === 0 ? 1 : -1);
    ring.rotation.y = 0.2 * r;
    orbitGroup.add(ring);
  }
  scene.add(orbitGroup);

  // Rain-Slicked Stone Floor
  const floorGeo = new THREE.CylinderGeometry(16, 16, 0.4, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x090D18,
    roughness: 0.25, // reflective wet sheen
    metalness: 0.5
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.position.set(0, -0.2, 0);
  scene.add(floor);

  // Puddle reflection
  const puddleGeo = new THREE.CircleGeometry(3.6, 32);
  puddleGeo.rotateX(-Math.PI / 2);
  const puddleMat = new THREE.MeshStandardMaterial({
    color: 0x050A14,
    roughness: 0.08,
    metalness: 0.85,
    transparent: true,
    opacity: 0.88
  });
  const puddle = new THREE.Mesh(puddleGeo, puddleMat);
  puddle.position.set(0, 0.01, 0);
  scene.add(puddle);

  // --------------------------------------------------------------------------
  // RIG 1: STANDING SWAGGER BULLY
  // --------------------------------------------------------------------------
  const bullyStanding = buildBullyAvatar({ pose: 'standing' });
  bullyStanding.position.set(0, 0, 0);
  scene.add(bullyStanding);

  // --------------------------------------------------------------------------
  // RIG 2: POINTING MOCKERY BULLY (SHOT 4 POSE)
  // --------------------------------------------------------------------------
  const bullyPointing = buildBullyAvatar({ pose: 'pointing_mock' });
  bullyPointing.position.set(0, 0, 0);
  scene.add(bullyPointing);

  // --------------------------------------------------------------------------
  // PROPS: HOLOGRAPHIC VIP STATUS TAG [ROBUX: 2,500,000 R$]
  // --------------------------------------------------------------------------
  const vipTag = buildVIPStatusTag();
  vipTag.position.set(1.4, 2.6, 0.6);
  vipTag.rotation.y = -0.3;
  scene.add(vipTag);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    if (cfg.mode === 'standing') {
      bullyStanding.visible = true;
      bullyPointing.visible = false;
      vipTag.visible = false;
      orbitGroup.visible = true;
    } else if (cfg.mode === 'pointing') {
      bullyStanding.visible = false;
      bullyPointing.visible = true;
      vipTag.visible = true;
      orbitGroup.visible = true;
    }

    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 350);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    renderer.render(scene, cam);

    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = 1280;
    angleCanvas.height = 760;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Overlay Badge
    actx.fillStyle = 'rgba(6, 9, 19, 0.85)';
    actx.fillRect(24, 24, 730, 68);
    actx.strokeStyle = '#F59E0B';
    actx.lineWidth = 1.5;
    actx.strokeRect(24, 24, 730, 68);

    actx.fillStyle = '#F59E0B';
    actx.font = 'bold 18px monospace';
    actx.fillText(cfg.title, 42, 52);

    actx.fillStyle = '#94A3B8';
    actx.font = '13px monospace';
    actx.fillText(cfg.desc, 42, 74);

    renderedCanvases.push(angleCanvas);

    // Upload individual angle
    const blob = await canvasToBlob(angleCanvas);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png`);
  }

  // ==========================================================================
  // COMPOSITE MASTER AUDIT SHEET (2400 × 1350)
  // ==========================================================================
  masterCtx.fillStyle = '#060913';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Cyber Grid Backdrop
  masterCtx.strokeStyle = 'rgba(245, 158, 11, 0.05)';
  masterCtx.lineWidth = 1;
  const gridSize = 40;
  for (let x = 0; x < 2400; x += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Master Title Header
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 34px sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // BATCH 2: CHAD_ROBUX (RICH BULLY PRO RIG)', 45, 55);

  masterCtx.fillStyle = '#F59E0B';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText('ROBLOX UGC 3D ANTAGONIST ASSETS — 5 CORE ASSETS VERIFIED (B-01 THROUGH B-05)', 45, 85);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('SHOT 4 STREET ENCOUNTER • "NICE STICK, NOOB..."', 2355, 55);
  masterCtx.fillText('DESIGNER TUXEDO • VOID DOMINUS HOOD • SHOULDER DRAGON PET • GILDED RAPIER • VIP TAG', 2355, 78);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#F59E0B';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath(); masterCtx.moveTo(45, 105); masterCtx.lineTo(2355, 105); masterCtx.stroke();

  // Layout:
  // Large Hero on Left (1420 × 840)
  const heroX = 45;
  const heroY = 130;
  const heroW = 1420;
  const heroH = 840;

  masterCtx.drawImage(renderedCanvases[0], heroX, heroY, heroW, heroH);
  masterCtx.strokeStyle = '#F59E0B';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(heroX, heroY, heroW, heroH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(heroX, heroY + heroH - 48, heroW, 48);
  masterCtx.fillStyle = '#F59E0B';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.fillText('VIEW 01: CHAD_ROBUX (ELITE PRO AVATAR HERO DISPLAY)', heroX + 16, heroY + heroH - 18);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('Glossy black tuxedo, gold filigree lapels, Void Dominus cowl, diamond crown, dragon pet & gilded rapier', heroX + heroW - 16, heroY + heroH - 18);
  masterCtx.textAlign = 'left';

  // 4 Thumbnails on Right (2x2 Grid)
  const rightColX1 = 1500;
  const rightColX2 = 1940;
  const rowY1 = 130;
  const rowY2 = 572;
  const thumbW = 415;
  const thumbH = 398;

  const thumbs = [
    { idx: 1, x: rightColX1, y: rowY1, title: 'ANGLE 2: DOMINUS HOOD & CROWN', desc: 'Glowing cyan eye slits + 5-point diamond crown' },
    { idx: 2, x: rightColX2, y: rowY1, title: 'ANGLE 3: CYBER-DRAGON & CHAIN', desc: 'Low-poly winged pet + Cuban link [R$] pendant' },
    { idx: 3, x: rightColX1, y: rowY2, title: 'ANGLE 4: GILDED RAPIER & DRIP', desc: '1.4m sheathed rapier + cold cyan embers & shoes' },
    { idx: 4, x: rightColX2, y: rowY2, title: 'ANGLE 5: SHOT 4 MOCKING POSE', desc: 'Pointing mock posture & 2.5M Robux VIP status tag' }
  ];

  thumbs.forEach(t => {
    masterCtx.drawImage(renderedCanvases[t.idx], t.x, t.y, thumbW, thumbH);
    masterCtx.strokeStyle = '#F59E0B';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(t.x, t.y, thumbW, thumbH);

    masterCtx.fillStyle = 'rgba(7, 13, 27, 0.9)';
    masterCtx.fillRect(t.x + 8, t.y + 8, thumbW - 16, 44);
    masterCtx.strokeStyle = '#F59E0B';
    masterCtx.lineWidth = 1;
    masterCtx.strokeRect(t.x + 8, t.y + 8, thumbW - 16, 44);

    masterCtx.fillStyle = '#F59E0B';
    masterCtx.font = 'bold 12px monospace';
    masterCtx.fillText(t.title, t.x + 16, t.y + 26);
    masterCtx.fillStyle = '#94A3B8';
    masterCtx.font = '10px monospace';
    masterCtx.fillText(t.desc, t.x + 16, t.y + 42);
  });

  // Bottom Technical Spec Panel
  const specY = 1000;
  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(45, specY, 2310, 315);
  masterCtx.strokeStyle = '#F59E0B';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(45, specY, 2310, 315);

  masterCtx.fillStyle = '#F59E0B';
  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillText('BATCH 2: CHAD_ROBUX ASSET VERIFICATION AUDIT (B-01 THROUGH B-05)', 65, specY + 38);

  masterCtx.strokeStyle = '#334155';
  masterCtx.lineWidth = 1;
  masterCtx.beginPath(); masterCtx.moveTo(65, specY + 52); masterCtx.lineTo(2335, specY + 52); masterCtx.stroke();

  masterCtx.font = '12px monospace';
  masterCtx.fillStyle = '#E2E8F0';
  const lineH = 26;
  const col1X = 65;
  const col2X = 840;
  const col3X = 1600;

  // Column 1: Rig & Headgear
  masterCtx.fillText('• ASSET B-01: ELITE PRO AVATAR RIG & DESIGNER TUXEDO DRIP', col1X, specY + 80);
  masterCtx.fillText('  - Glossy obsidian silk tuxedo (#090D16) with 24K gold filigree lapels, white V-collar, black bowtie & gold buttons.', col1X, specY + 80 + lineH);
  masterCtx.fillText('  - French dress cuffs with gold cufflinks, gold-striped slacks and ultra-glossy mirror patent leather dress shoes.', col1X, specY + 80 + lineH * 2);
  masterCtx.fillText('• ASSET B-02: VOID DOMINUS HOOD & FLOATING DIAMOND CROWN', col1X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Deep void-black cowl with polished gold trim, glowing cyan eye slits (#00F0FF) & 5-point floating diamond crown.', col1X, specY + 80 + lineH * 4);

  // Column 2: VIP Accessories & Weapon
  masterCtx.fillText('• ASSET B-03: FLOATING SHOULDER CYBER-DRAGON PET & CUBAN LINK CHAIN', col2X, specY + 80);
  masterCtx.fillText('  - Stylized low-poly cyber-dragon hovering over right shoulder with gold horns, cyan wing blades & levitating ring.', col2X, specY + 80 + lineH);
  masterCtx.fillText('  - Heavy gold Cuban link necklace with oversized diamond [R$] Robux pendant resting on chest.', col2X, specY + 80 + lineH * 2);
  masterCtx.fillText('• ASSET B-04: GILDED FROSTFIRE RAPIER (SHEATHED SIDE WEAPON)', col2X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - 1.4m rapier slung on hip in gold-banded obsidian scabbard, gold cup basket hilt & orbiting cold blue fire embers.', col2X, specY + 80 + lineH * 4);

  // Column 3: Decals & Shot 4 Stance
  masterCtx.fillText('• ASSET B-05: SMUG ARROGANT DECALS & HOLOGRAPHIC VIP STATUS TAG', col3X, specY + 80);
  masterCtx.fillText('  - Arrogant cocked eyebrows, gold tooth glint, and mirrored aviator sunglasses reflecting neon cyan cyber skyline.', col3X, specY + 80 + lineH);
  masterCtx.fillText('  - Diegetic floating VIP card: [LEVEL 100 MAX | ROBUX: 2,500,000 R$ | GUILD: APEX SOVEREIGNS | PAY-TO-WIN GOD].', col3X, specY + 80 + lineH * 2);
  masterCtx.fillText('• SHOT 4 MOCKING POSE & DUAL ORBITAL GOLDEN RINGS (VIEW 05):', col3X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Extended right arm pointing in mocking laughter at kneeling Toby — setting up the wager and duel inciting incident.', col3X, specY + 80 + lineH * 4);

  // Upload Master Sheet
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('bully_master_sheet.png', masterBlob);
  console.log('SAVED: bully_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('BULLY_BATCH_2_AUDIT_COMPLETE');
}

window.onload = init;

