// ============================================================================
// THE GLITCH MARKET — SHOT 4 ENVIRONMENT & DIEGETIC PROPS
// BATCH 3: ARENA CURB, RAIN PUDDLES, GATES & MOCKING PASSERBYS
//
// Assets:
// - P-01: Snapped Beginner Wooden Club (Jagged Fractures & Splinters in Puddle)
// - P-02: Holographic Level 1 Player Stat Card [LEVEL 1 | STATS: 0 | ROBUX: 0]
// - P-03: Tarnished Beginner [NOOB] Bronze Badge Medallion
// - P-04: Colosseum Outer Curb, Reflective Rain Puddles & Rusted Security Gates
// - P-05: Mocking High-Tier Passerby Avatars (Cyber-Ninja & Neon Streetwear)
// ============================================================================

import * as THREE from 'three';
import { createBeveledBox, canvasTex } from './core/geo.js';

// ----------------------------------------------------------------------------
// ASSET P-03: TARNISHED BEGINNER [NOOB] BRONZE BADGE
// ----------------------------------------------------------------------------

export function buildTarnishedNoobBadge() {
  const badge = new THREE.Group();
  badge.name = 'TarnishedNoobBadge';

  const badgeTex = canvasTex('badge_noob_bronze', 256, 256, (g, w, h) => {
    // Weathered bronze / copper base
    g.fillStyle = '#78350F';
    g.beginPath();
    g.arc(w / 2, h / 2, 115, 0, Math.PI * 2);
    g.fill();

    // Tarnished bronze rim
    g.strokeStyle = '#B45309';
    g.lineWidth = 14;
    g.beginPath();
    g.arc(w / 2, h / 2, 105, 0, Math.PI * 2);
    g.stroke();

    // Rivets around rim
    g.fillStyle = '#451A03';
    for (let i = 0; i < 8; i++) {
      const angle = (i / 8) * Math.PI * 2;
      const rx = w / 2 + Math.cos(angle) * 105;
      const ry = h / 2 + Math.sin(angle) * 105;
      g.beginPath(); g.arc(rx, ry, 5, 0, Math.PI * 2); g.fill();
    }

    // Classic Roblox Noob Icon (Yellow head, Blue torso, Green legs)
    const cx = w / 2;
    const cy = h / 2 - 10;

    // Head
    g.fillStyle = '#FACC15';
    g.fillRect(cx - 24, cy - 42, 48, 38);
    // Smile & eyes
    g.fillStyle = '#1E293B';
    g.fillRect(cx - 15, cy - 30, 8, 8);
    g.fillRect(cx + 7, cy - 30, 8, 8);
    g.beginPath();
    g.arc(cx, cy - 18, 10, 0, Math.PI);
    g.stroke();

    // Blue Torso
    g.fillStyle = '#0284C7';
    g.fillRect(cx - 32, cy - 2, 64, 46);

    // Green Legs
    g.fillStyle = '#16A34A';
    g.fillRect(cx - 30, cy + 46, 28, 40);
    g.fillRect(cx + 2, cy + 46, 28, 40);

    // Diagonal Scratches across badge (wear and tear)
    g.strokeStyle = 'rgba(30, 15, 5, 0.6)';
    g.lineWidth = 4;
    g.beginPath(); g.moveTo(40, 60); g.lineTo(210, 200); g.stroke();
    g.beginPath(); g.moveTo(70, 40); g.lineTo(190, 170); g.stroke();

    // "NOOB" Text ribbon
    g.fillStyle = '#EF4444';
    g.fillRect(cx - 55, cy + 65, 110, 26);
    g.fillStyle = '#FFFFFF';
    g.font = 'bold 18px monospace';
    g.textAlign = 'center';
    g.fillText('NOOB', cx, cy + 84);
  });

  const disc = new THREE.Mesh(
    new THREE.CylinderGeometry(0.24, 0.24, 0.035, 24),
    new THREE.MeshStandardMaterial({
      color: 0xB45309,
      metalness: 0.8,
      roughness: 0.4
    })
  );
  disc.rotation.x = Math.PI / 2;
  badge.add(disc);

  const decal = new THREE.Mesh(
    new THREE.PlaneGeometry(0.44, 0.44),
    new THREE.MeshBasicMaterial({ map: badgeTex, transparent: true })
  );
  decal.position.set(0, 0, 0.02);
  badge.add(decal);

  return badge;
}

// ----------------------------------------------------------------------------
// ASSET P-04: COLOSSEUM OUTER CURB & ENVIRONMENT
// ----------------------------------------------------------------------------

export function buildArenaCurbEnvironment() {
  const env = new THREE.Group();
  env.name = 'ArenaCurbEnvironment';

  // 1. Wet Asphalt / Cobblestone Street Deck (Reflective ground)
  const streetGeo = new THREE.BoxGeometry(24, 0.4, 18);
  const streetTex = canvasTex('curb_wet_cobblestone', 512, 512, (g, w, h) => {
    g.fillStyle = '#090D16';
    g.fillRect(0, 0, w, h);

    // Wet pavers / cobblestone grid
    g.strokeStyle = '#1E293B';
    g.lineWidth = 2;
    for (let x = 0; x < w; x += 32) {
      g.beginPath(); g.moveTo(x, 0); g.lineTo(x, h); g.stroke();
    }
    for (let y = 0; y < h; y += 18) {
      const offset = (Math.floor(y / 18) % 2) * 16;
      for (let x = -16; x < w + 16; x += 32) {
        g.strokeRect(x + offset, y, 32, 18);
      }
    }
    // Neon puddle reflection wash (Electric cyan & hot magenta)
    const grad = g.createLinearGradient(0, 0, w, h);
    grad.addColorStop(0, 'rgba(0, 240, 255, 0.08)');
    grad.addColorStop(0.5, 'rgba(168, 85, 247, 0.06)');
    grad.addColorStop(1, 'rgba(239, 68, 68, 0.08)');
    g.fillStyle = grad;
    g.fillRect(0, 0, w, h);
  }, [4, 4]);

  const streetMat = new THREE.MeshStandardMaterial({
    map: streetTex,
    color: 0xFFFFFF,
    roughness: 0.35,
    metalness: 0.5
  });
  const street = new THREE.Mesh(streetGeo, streetMat);
  street.position.set(0, -0.2, 2.5);
  env.add(street);

  // 2. Concrete Sidewalk Curb Step
  const curbGeo = new THREE.BoxGeometry(24, 0.45, 4.5);
  const curbMat = new THREE.MeshStandardMaterial({
    color: 0x1E293B,
    roughness: 0.75,
    metalness: 0.2
  });
  const curb = new THREE.Mesh(curbGeo, curbMat);
  curb.position.set(0, 0.05, -3.2);
  env.add(curb);

  // Curb Ledge Lip (The stone edge Toby sits against)
  const lipGeo = new THREE.BoxGeometry(24, 0.12, 0.35);
  const lipMat = new THREE.MeshStandardMaterial({
    color: 0x334155,
    roughness: 0.6,
    metalness: 0.3
  });
  const lip = new THREE.Mesh(lipGeo, lipMat);
  lip.position.set(0, 0.25, -1.0);
  env.add(lip);

  // 3. Mirror-Like Water Puddles (Reflecting arena lights)
  const puddles = [
    { x: 0.2, z: 0.7, r: 3.4, rot: 0.2 },
    { x: -3.8, z: 2.2, r: 2.2, rot: -0.4 },
    { x: 4.2, z: 1.8, r: 2.6, rot: 0.5 }
  ];

  puddles.forEach(p => {
    const puddleGeo = new THREE.CircleGeometry(p.r, 32);
    puddleGeo.rotateX(-Math.PI / 2);
    const puddleMat = new THREE.MeshStandardMaterial({
      color: 0x050811,
      roughness: 0.06, // ultra glossy water mirror
      metalness: 0.9,
      transparent: true,
      opacity: 0.92
    });
    const mesh = new THREE.Mesh(puddleGeo, puddleMat);
    mesh.position.set(p.x, 0.015, p.z);
    mesh.rotation.y = p.rot;
    env.add(mesh);

    // Concentric Ripple Ring
    const rippleGeo = new THREE.RingGeometry(p.r * 0.4, p.r * 0.44, 24);
    rippleGeo.rotateX(-Math.PI / 2);
    const rippleMat = new THREE.MeshBasicMaterial({
      color: 0x38BDF8,
      transparent: true,
      opacity: 0.35,
      side: THREE.DoubleSide
    });
    const ripple = new THREE.Mesh(rippleGeo, rippleMat);
    ripple.position.set(p.x, 0.02, p.z);
    env.add(ripple);
  });

  // 4. Heavy Rusted Security Gate Bars (Colosseum Arena Gates)
  const gate = new THREE.Group();
  gate.position.set(0, 0, -4.5);

  const barMat = new THREE.MeshStandardMaterial({
    color: 0x1E2430,
    metalness: 0.85,
    roughness: 0.55
  });

  // Vertical security bars (7m tall)
  for (let i = -16; i <= 16; i++) {
    const barGeo = new THREE.CylinderGeometry(0.065, 0.065, 7.5, 8);
    const bar = new THREE.Mesh(barGeo, barMat);
    bar.position.set(i * 0.68, 3.75, 0);
    gate.add(bar);

    // Spear point top
    const spikeGeo = new THREE.ConeGeometry(0.09, 0.35, 4);
    const spike = new THREE.Mesh(spikeGeo, barMat);
    spike.position.set(i * 0.68, 7.6, 0);
    gate.add(spike);
  }

  // Horizontal structural cross-beams
  [1.0, 3.8, 6.6].forEach(y => {
    const beamGeo = new THREE.BoxGeometry(23.5, 0.22, 0.18);
    const beam = new THREE.Mesh(beamGeo, barMat);
    beam.position.set(0, y, 0);
    gate.add(beam);
  });

  // Diegetic Warning Placard on Gate: [SECTOR 04 ARENA // NO UNRANKED ALLOWED]
  const signTex = canvasTex('gate_warning_sign', 512, 256, (g, w, h) => {
    // Yellow & black hazard stripes border
    g.fillStyle = '#F59E0B';
    g.fillRect(0, 0, w, h);
    g.fillStyle = '#0F172A';
    for (let x = -w; x < w * 2; x += 40) {
      g.beginPath();
      g.moveTo(x, 0);
      g.lineTo(x + 25, 0);
      g.lineTo(x - 15, h);
      g.lineTo(x - 40, h);
      g.closePath();
      g.fill();
    }
    // Dark center sign board
    g.fillStyle = '#0F172A';
    g.fillRect(20, 20, w - 40, h - 40);
    g.strokeStyle = '#EF4444';
    g.lineWidth = 4;
    g.strokeRect(20, 20, w - 40, h - 40);

    g.fillStyle = '#EF4444';
    g.font = 'bold 24px monospace';
    g.textAlign = 'center';
    g.fillText('⚠ SECTOR 04 COMBAT ZONE ⚠', w / 2, 60);

    g.fillStyle = '#FFFFFF';
    g.font = '900 28px sans-serif';
    g.fillText('RESTRICTED ACCESS', w / 2, 110);

    g.fillStyle = '#F59E0B';
    g.font = 'bold 18px monospace';
    g.fillText('MINIMUM RANK: DIAMOND TIER', w / 2, 150);

    g.fillStyle = '#94A3B8';
    g.font = 'bold 15px monospace';
    g.fillText('NOOBS & LEVEL 1 PROHIBITED', w / 2, 195);
  });

  const sign = new THREE.Mesh(
    new THREE.PlaneGeometry(2.4, 1.2),
    new THREE.MeshStandardMaterial({
      map: signTex,
      roughness: 0.4,
      metalness: 0.2
    })
  );
  sign.position.set(0, 3.8, 0.12);
  gate.add(sign);

  env.add(gate);

  // 5. Overhead Industrial Arena Floodlight Lamp Post
  const postGroup = new THREE.Group();
  postGroup.position.set(-6.5, 0, -2.5);

  const postPole = new THREE.Mesh(
    new THREE.CylinderGeometry(0.14, 0.18, 8, 12),
    barMat
  );
  postPole.position.set(0, 4, 0);
  postGroup.add(postPole);

  const lampArm = new THREE.Mesh(
    new THREE.BoxGeometry(2.2, 0.16, 0.16),
    barMat
  );
  lampArm.position.set(0.9, 7.8, 0);
  lampArm.rotation.z = -0.15;
  postGroup.add(lampArm);

  const lampHousing = new THREE.Mesh(
    new THREE.BoxGeometry(1.2, 0.35, 0.65),
    barMat
  );
  lampHousing.position.set(1.9, 7.5, 0);
  postGroup.add(lampHousing);

  const lampLens = new THREE.Mesh(
    new THREE.PlaneGeometry(1.1, 0.55),
    new THREE.MeshBasicMaterial({ color: 0xFFFBEB })
  );
  lampLens.rotation.x = Math.PI / 2;
  lampLens.position.set(1.9, 7.32, 0);
  postGroup.add(lampLens);

  // Actual Spotlight shining down onto curb
  const spot = new THREE.SpotLight(0xFFFBEB, 4.5, 22.0, Math.PI / 4, 0.3);
  spot.position.set(1.9, 7.3, 0);
  spot.target.position.set(0, 0, 1.0);
  postGroup.add(spot);
  postGroup.add(spot.target);

  env.add(postGroup);

  return env;
}

