  const thumbs = [
    { idx: 1, x: rightColX1, y: rowY1, title: 'ANGLE 2: SNAPPED CLUB MACRO', desc: 'Fractured oak cudgel & water ripples' },
    { idx: 2, x: rightColX2, y: rowY1, title: 'ANGLE 3: STAT CARD & NOOB BADGE', desc: 'Diegetic Level 1 UI + chipped bronze badge' },
    { idx: 3, x: rightColX1, y: rowY2, title: 'ANGLE 4: COBBLESTONE & WARNING SIGN', desc: 'Reflective paver sheen & gate placard' },
    { idx: 4, x: rightColX2, y: rowY2, title: 'ANGLE 5: MOCKING PASSERBYS', desc: 'Cyber-ninja & laughing neon streetwear' }
  ];

  thumbs.forEach(t => {
    masterCtx.drawImage(renderedCanvases[t.idx], t.x, t.y, thumbW, thumbH);
    masterCtx.strokeStyle = '#38BDF8';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(t.x, t.y, thumbW, thumbH);

    masterCtx.fillStyle = 'rgba(7, 13, 27, 0.9)';
    masterCtx.fillRect(t.x + 8, t.y + 8, thumbW - 16, 44);
    masterCtx.strokeStyle = '#38BDF8';
    masterCtx.lineWidth = 1;
    masterCtx.strokeRect(t.x + 8, t.y + 8, thumbW - 16, 44);

    masterCtx.fillStyle = '#38BDF8';
    masterCtx.font = 'bold 12px monospace';
    masterCtx.fillText(t.title, t.x + 16, t.y + 26);
    masterCtx.fillStyle = '#94A3B8';
    masterCtx.font = '10px monospace';
    masterCtx.fillText(t.desc, t.x + 16, t.y + 42);
  });

  // Bottom Technical Spec Panel
  const specY = 1000;
  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(45, specY, 2310, 315);
  masterCtx.strokeStyle = '#38BDF8';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(45, specY, 2310, 315);

  masterCtx.fillStyle = '#38BDF8';
  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillText('BATCH 3: SHOT 4 ENVIRONMENT & PROPS VERIFICATION AUDIT (P-01 THROUGH P-05)', 65, specY + 38);

  masterCtx.strokeStyle = '#334155';
  masterCtx.lineWidth = 1;
  masterCtx.beginPath(); masterCtx.moveTo(65, specY + 52); masterCtx.lineTo(2335, specY + 52); masterCtx.stroke();

  masterCtx.font = '12px monospace';
  masterCtx.fillStyle = '#E2E8F0';
  const lineH = 26;
  const col1X = 65;
  const col2X = 840;
  const col3X = 1600;

  // Column 1: Snapped Club & Stat Card
  masterCtx.fillText('• ASSET P-01: SNAPPED BEGINNER WOODEN CLUB', col1X, specY + 80);
  masterCtx.fillText('  - Level 1 oak cudgel broken in two splintered chunks (#78350F) with jagged fracture fibers & leather wrap.', col1X, specY + 80 + lineH);
  masterCtx.fillText('• ASSET P-02: HOLOGRAPHIC LEVEL 1 PLAYER STAT CARD', col1X, specY + 80 + lineH * 2);
  masterCtx.fillText('  - Floating diegetic UI card: semi-transparent slate backing, pulsing red border: [LEVEL 1 | STATS: 0 | ROBUX: 0].', col1X, specY + 80 + lineH * 3);
  masterCtx.fillText('• ASSET P-03: TARNISHED BEGINNER [NOOB] BRONZE BADGE', col1X, specY + 80 + lineH * 4);

  // Column 2: Curb, Puddles & Gates
  masterCtx.fillText('• ASSET P-04: COLOSSEUM OUTER CURB & RAIN-SLICKED PAVEMENT', col2X, specY + 80);
  masterCtx.fillText('  - Wet reflective cobblestone pavers with cyan/magenta neon reflection gradient, concrete curb step & ledge.', col2X, specY + 80 + lineH);
  masterCtx.fillText('  - 3 mirror-finish water puddles (roughness 0.06) with concentric light-blue ripple rings.', col2X, specY + 80 + lineH * 2);
  masterCtx.fillText('  - 7.5m rusted steel security gate bars with spear points and hazard warning sign: [NO UNRANKED ALLOWED].', col2X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Overhead industrial arena floodlight post with spot lamp illuminating the curb staging.', col2X, specY + 80 + lineH * 4);

  // Column 3: Bystanders & Status
  masterCtx.fillText('• ASSET P-05: MOCKING HIGH-TIER PASSERBY AVATARS', col3X, specY + 80);
  masterCtx.fillText('  - Passerby 1 (Cyber-Ninja): Dark armor, glowing red visor, dual sheathed katanas, pointing right arm at Toby.', col3X, specY + 80 + lineH);
  masterCtx.fillText('  - Passerby 2 (Streetwear Pro): Purple hoodie, neon DJ headphones, wide laughing face decal, doubled over in laughter.', col3X, specY + 80 + lineH * 2);
  masterCtx.fillText('• MILESTONE 5 PRODUCTION STATUS: ALL 3 BATCHES 100% COMPLETE & VERIFIED', col3X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Ready for Final Assembly: Official Vertical 9:16 Master Keyframe 03 (Shot 4)', col3X, specY + 80 + lineH * 4);

  // Upload Master Sheet
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('props_master_sheet.png', masterBlob);
  console.log('SAVED: props_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('PROPS_BATCH_3_AUDIT_COMPLETE');
}

window.onload = init;

