// ============================================================================
// THE GLITCH MARKET — SHOT 4 MASTER PRODUCTION SCENE
// THE INTRODUCTION OF TOBY: "AND THAT'S ME..." (STREET CURB INCITING INCIDENT)
//
// Complete Assembly of Milestone 5:
// - Batch 1: Toby (Bacon Hair MC Hero Rig) in Kneeling Defeat Pose
// - Batch 2: Chad_Robux (Rich Bully Pro Rig) in Pointing Mockery Swagger Stance
// - Batch 3: Shot 4 Environment (Rain-slicked curb, puddles, rusted gates, warning sign, lamp post)
// - Diegetic Props: Snapped oak club in puddle, Level 1 stat card, 2.5M Robux VIP tag, Noob badge
// - Background: 2 Mocking Bystander Avatars (Cyber-Ninja & Streetwear Pro)
//
// Produces:
// 1. shot4_angle_1_hero_vertical.png (1080x1920 Vertical 9:16 Master Keyframe 03)
// 2. shot4_keyframe_01.png (Official Keyframe 03 alias)
// 3. shot4_angle_2_alley_tiltup.png (Low-angle street perspective)
// 4. shot4_angle_3_toby_character_study.png (Protagonist closeup)
// 5. shot4_angle_4_bully_mockery_macro.png (Antagonist dominance closeup)
// 6. shot4_angle_5_passerby_street_depth.png (Sidewalk depth & crowd)
// 7. shot4_master_sheet.png (2400x1350 5-Panel Production Master Sheet)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import {
  buildTobyAvatar,
  buildSnappedClub,
  buildLevel1StatCard
} from './toby_avatar.js';
import {
  buildBullyAvatar,
  buildVIPStatusTag
} from './bully_avatar.js';
import {
  buildArenaCurbEnvironment,
  buildTarnishedNoobBadge,
  buildMockingPasserbyAvatars
} from './shot4_environment.js';

export const MASTER_ANGLES = [
  {
    id: 'shot4_angle_1_hero_vertical',
    title: 'SHOT 4 // OFFICIAL VERTICAL 9:16 MASTER HERO KEYFRAME',
    desc: '"And that\'s me...": Low-angle tilt-up framing bruised kneeling Toby, broken club, Chad_Robux mocking & gates',
    aspect: '9:16',
    width: 1080,
    height: 1920,
    pos: [0.95, 0.72, 3.45],
    target: [0.75, 1.85, 0.1],
    fov: 54
  },
  {
    id: 'shot4_angle_2_alley_tiltup',
    title: 'ANGLE 2 // CINEMATIC LOW-ANGLE ALLEY TILT-UP',
    desc: 'Wide ground-level perspective across water puddles, snapped club, clashing player tiers & Colosseum bars',
    aspect: '16:9',
    width: 1280,
    height: 760,
    pos: [-1.8, 0.95, 3.8],
    target: [1.2, 1.85, -0.2],
    fov: 52
  },
  {
    id: 'shot4_angle_3_toby_character_study',
    title: 'ANGLE 3 // TOBY PROTAGONIST CLOSEUP & LEVEL 1 UI',
    desc: 'Close 3/4 perspective on Toby\'s bruised face, 3D bacon hair, tattered hoodie, broken stick & stat card',
    aspect: '16:9',
    width: 1280,
    height: 760,
    pos: [1.2, 1.45, 1.95],
    target: [0.0, 1.25, 0.35],
    fov: 42
  },
  {
    id: 'shot4_angle_4_bully_mockery_macro',
    title: 'ANGLE 4 // CHAD_ROBUX DOMINANCE & 2.5M ROBUX TAG',
    desc: 'Upward look at Chad_Robux pointing in mockery, obsidian tuxedo, Dominus hood, diamond crown & dragon pet',
    aspect: '16:9',
    width: 1280,
    height: 760,
    pos: [1.1, 1.5, 1.8],
    target: [2.0, 2.5, -0.2],
    fov: 46
  },
  {
    id: 'shot4_angle_5_passerby_street_depth',
    title: 'ANGLE 5 // STREET DEPTH & MOCKING PASSERBYS',
    desc: 'Sidewalk perspective looking past the laughing Cyber-Ninja & Streetwear avatar towards the arena gates',
    aspect: '16:9',
    width: 1280,
    height: 760,
    pos: [6.8, 2.2, 3.6],
    target: [2.2, 1.7, -0.4],
    fov: 46
  }
];

function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

export function buildMasterShot4Scene() {
  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050811);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(400, 400, 320, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 50, 0);
  scene.add(skyDome);

  // Studio / Cinematic Lighting Rig
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x0A0F1E, 1.15);
  scene.add(hemi);

  const keySun = new THREE.DirectionalLight(0xFFFBEB, 2.2);
  keySun.position.set(10, 14, 12);
  scene.add(keySun);

  const fillCyan = new THREE.DirectionalLight(0x00F0FF, 1.5);
  fillCyan.position.set(-10, 8, 6);
  scene.add(fillCyan);

  const warmRim = new THREE.DirectionalLight(0xF59E0B, 2.0);
  warmRim.position.set(8, 6, -10);
  scene.add(warmRim);

  // Soft Front Camera Key for characters
  const charKey = new THREE.DirectionalLight(0xFFFFFF, 1.6);
  charKey.position.set(1, 3, 5);
  scene.add(charKey);

  // Dedicated soft spotlight on Toby
  const tobySpot = new THREE.PointLight(0xFFE4B5, 2.4, 5.5);
  tobySpot.position.set(0.0, 1.8, 1.2);
  scene.add(tobySpot);

  // Dedicated spotlight on Chad_Robux
  const chadSpot = new THREE.PointLight(0x00F0FF, 2.0, 6.0);
  chadSpot.position.set(2.0, 3.5, 1.2);
  scene.add(chadSpot);

  // --------------------------------------------------------------------------
  // 1. ENVIRONMENT STAGING (BATCH 3)
  // --------------------------------------------------------------------------
  const env = buildArenaCurbEnvironment();
  scene.add(env);

  // --------------------------------------------------------------------------
  // 2. PROTAGONIST: TOBY (BACON HAIR MC) (BATCH 1)
  // --------------------------------------------------------------------------
  const toby = buildTobyAvatar({
    pose: 'kneeling',
    expression: 'bruised'
  });
  toby.position.set(0.0, 0.05, 0.4);
  scene.add(toby);

  // Snapped Oak Starter Club in Puddle
  const club = buildSnappedClub();
  club.position.set(0.1, 0.05, 1.25);
  scene.add(club);

  // Holographic Level 1 Stat Card
  const statCard = buildLevel1StatCard();
  statCard.position.set(-0.95, 1.75, 0.65);
  statCard.rotation.y = 0.28;
  scene.add(statCard);

  // Tarnished Beginner Noob Badge pinned to Toby's hoodie
  const badge = buildTarnishedNoobBadge();
  badge.position.set(0.12, 1.35, 0.65);
  badge.scale.set(0.65, 0.65, 0.65);
  scene.add(badge);

  // --------------------------------------------------------------------------
  // 3. ANTAGONIST: CHAD_ROBUX (RICH BULLY PRO) (BATCH 2)
  // --------------------------------------------------------------------------
  const bully = buildBullyAvatar({
    pose: 'pointing_mock'
  });
  bully.position.set(2.0, 0.05, -0.2);
  bully.rotation.y = -0.55; // turned mockingly toward Toby
  scene.add(bully);

  // Holographic VIP Status Tag [ROBUX: 2,500,000 R$]
  const vipTag = buildVIPStatusTag();
  vipTag.position.set(3.25, 2.75, -0.1);
  vipTag.rotation.y = -0.45;
  scene.add(vipTag);

  // Floating Luxury Orbit Rings around Chad's waist
  const orbitGroup = new THREE.Group();
  orbitGroup.position.set(2.0, 2.05, -0.2);
  for (let r = 0; r < 2; r++) {
    const ringGeo = new THREE.TorusGeometry(1.4 + r * 0.35, 0.025, 8, 32);
    const ringMat = new THREE.MeshBasicMaterial({
      color: r === 0 ? 0xF59E0B : 0x00F0FF,
      transparent: true,
      opacity: 0.75,
      blending: THREE.AdditiveBlending
    });
    const ring = new THREE.Mesh(ringGeo, ringMat);
    ring.rotation.x = Math.PI / 2 + 0.15 * (r === 0 ? 1 : -1);
    ring.rotation.y = 0.2 * r;
    orbitGroup.add(ring);
  }
  scene.add(orbitGroup);

  // --------------------------------------------------------------------------
  // 4. MOCKING PASSERBY AVATARS (BATCH 3)
  // --------------------------------------------------------------------------
  const passerbys = buildMockingPasserbyAvatars();
  scene.add(passerbys);

  return scene;
}

