// ============================================================================
// THE GLITCH MARKET — DUEL COMBAT RIGS & ACTIVE WEAPONS
// MILESTONE 5.5 // BATCH 1: COMBAT RIGS & WEAPONS (F-01 THROUGH F-05)
//
// Assets:
// - F-01: Chad_Robux Active Combat Rig (Aggressive Fencing Lunge & Execution Stance)
// - F-02: Gilded Frostfire Rapier (Active 1.4m Blade with Additive Flame & Embers)
// - F-03: Toby Makeshift Combat Rig (2-Handed Charge & Gate Recoil Poses)
// - F-04: Makeshift Oak Stake Weapon (0.65m Splintered Jagged Shard & Leather Grip)
// - F-05: Combat Face Decals (Toby Terror/Shock & Chad Sadistic Predatory Sneer)
// ============================================================================

import * as THREE from 'three';
import { createBeveledBox, canvasTex } from './core/geo.js';
import {
  createDesignerTuxedoTexture,
  createTuxedoSleeveTexture,
  createTuxedoSlacksTexture,
  buildBullyHeadgear,
  buildShoulderDragonPet,
  buildCubanLinkNecklace
} from './bully_avatar.js';
import {
  buildBaconHairMesh,
  createDenimJeansTexture
} from './toby_avatar.js';

// ----------------------------------------------------------------------------
// ASSET F-05: PROCEDURAL COMBAT FACE DECALS
// ----------------------------------------------------------------------------

/**
 * Toby's Combat Expressions: 'charge' (fierce grit) & 'shock' (wide dilated terror)
 */
export function createTobyCombatFace(expression = 'shock') {
  return canvasTex(`toby_combat_face_${expression}`, 512, 512, (g, w, h) => {
    // Pale classic Roblox yellow skin
    g.fillStyle = '#F8EE89';
    g.fillRect(0, 0, w, h);

    // Grime & battle smudges
    g.fillStyle = 'rgba(74, 48, 28, 0.22)';
    g.beginPath(); g.arc(110, 360, 48, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(380, 140, 35, 0, Math.PI * 2); g.fill();

    // Swollen bruise under left eye
    g.fillStyle = 'rgba(126, 34, 206, 0.3)';
    g.beginPath(); g.ellipse(170, 275, 48, 26, 0.15, 0, Math.PI * 2); g.fill();
    g.fillStyle = 'rgba(180, 83, 9, 0.35)';
    g.beginPath(); g.ellipse(170, 278, 34, 18, 0.1, 0, Math.PI * 2); g.fill();

    // Eyebrows
    g.strokeStyle = '#3E2718';
    g.lineWidth = 15;
    g.lineCap = 'round';

    if (expression === 'charge') {
      // Fierce aggressive V-brow
      g.beginPath(); g.moveTo(120, 195); g.lineTo(220, 225); g.stroke();
      g.beginPath(); g.moveTo(392, 195); g.lineTo(292, 225); g.stroke();
    } else {
      // High-arched horrified shock brow (raised in center)
      g.beginPath(); g.moveTo(115, 230); g.lineTo(215, 175); g.stroke();
      g.beginPath(); g.moveTo(397, 230); g.lineTo(297, 175); g.stroke();
    }

    // Eyes
    if (expression === 'shock') {
      // Massive dilated eyes (Terror)
      g.fillStyle = '#FFFFFF';
      g.beginPath(); g.ellipse(175, 245, 45, 54, 0, 0, Math.PI * 2); g.fill();
      g.beginPath(); g.ellipse(337, 245, 45, 54, 0, 0, Math.PI * 2); g.fill();

      // Constricted Pinprick Pupils (Shock)
      g.fillStyle = '#0F0703';
      g.beginPath(); g.arc(175, 245, 12, 0, Math.PI * 2); g.fill();
      g.beginPath(); g.arc(337, 245, 12, 0, Math.PI * 2); g.fill();

      // Quivering shock rings around pupils
      g.strokeStyle = '#78350F';
      g.lineWidth = 3;
      g.beginPath(); g.arc(175, 245, 24, 0, Math.PI * 2); g.stroke();
      g.beginPath(); g.arc(337, 245, 24, 0, Math.PI * 2); g.stroke();

      // Cold sweat beads trickling down forehead/temple
      g.fillStyle = '#38BDF8';
      const sweatDrops = [
        { x: 105, y: 190, r: 8 },
        { x: 115, y: 220, r: 6 },
        { x: 395, y: 200, r: 7 }
      ];
      sweatDrops.forEach(d => {
        g.beginPath(); g.arc(d.x, d.y, d.r, 0, Math.PI * 2); g.fill();
      });

      // Frostbite creeping on cheek (cyan crystalline frost)
      g.strokeStyle = '#00F0FF';
      g.lineWidth = 3;
      const fx = 120, fy = 310;
      for (let i = 0; i < 6; i++) {
        const ang = (i / 6) * Math.PI * 2;
        g.beginPath();
        g.moveTo(fx, fy);
        g.lineTo(fx + Math.cos(ang) * 35, fy + Math.sin(ang) * 35);
        g.stroke();
      }
    } else {
      // Determined Charge Eyes
      g.fillStyle = '#FFFFFF';
      g.beginPath(); g.ellipse(175, 235, 38, 48, 0, 0, Math.PI * 2); g.fill();
      g.beginPath(); g.ellipse(337, 235, 38, 48, 0, 0, Math.PI * 2); g.fill();

      g.fillStyle = '#451A03';
      g.beginPath(); g.arc(175, 238, 25, 0, Math.PI * 2); g.fill();
      g.beginPath(); g.arc(337, 238, 25, 0, Math.PI * 2); g.fill();

      g.fillStyle = '#FFFFFF';
      g.beginPath(); g.arc(165, 225, 8, 0, Math.PI * 2); g.fill();
      g.beginPath(); g.arc(327, 225, 8, 0, Math.PI * 2); g.fill();
    }

    // Nose Scratch
    g.strokeStyle = '#B91C1C';
    g.lineWidth = 4;
    g.beginPath(); g.moveTo(238, 280); g.lineTo(274, 272); g.stroke();

    // Cheek Bandage
    g.save();
    g.translate(355, 340);
    g.rotate(-0.2);
    g.fillStyle = '#F8FAFC';
    g.fillRect(-42, -18, 84, 36);
    g.fillStyle = '#E2E8F0';
    g.fillRect(-22, -14, 44, 28);
    g.restore();

    // Mouth
    g.lineWidth = 8;
    g.lineCap = 'round';
    if (expression === 'charge') {
      // Gritted teeth grit
      g.strokeStyle = '#1F1108';
      g.strokeRect(210, 375, 92, 28);
      g.fillStyle = '#FFFFFF';
      g.fillRect(212, 377, 88, 24);
      g.beginPath(); g.moveTo(212, 389); g.lineTo(300, 389); g.stroke();
      for (let x = 230; x < 300; x += 15) {
        g.beginPath(); g.moveTo(x, 377); g.lineTo(x, 401); g.stroke();
      }
    } else {
      // Quivering agape mouth in shock/horror
      g.fillStyle = '#3F1515';
      g.beginPath();
      g.ellipse(256, 395, 32, 22, 0, 0, Math.PI * 2);
      g.fill();
      g.strokeStyle = '#1F1108';
      g.stroke();
    }
  });
}

/**
 * Chad's Predatory Combat Smirk Decal with Blue Frostfire Reflection
 */
export function createChadCombatFace() {
  return canvasTex('chad_combat_smirk', 512, 512, (g, w, h) => {
    g.fillStyle = '#FFF7ED';
    g.fillRect(0, 0, w, h);

    // Arrogant cocked eyebrows
    g.strokeStyle = '#18181B';
    g.lineWidth = 14;
    g.lineCap = 'round';
    g.beginPath(); g.moveTo(110, 165); g.quadraticCurveTo(165, 120, 220, 155); g.stroke();
    g.beginPath(); g.moveTo(292, 175); g.lineTo(395, 160); g.stroke();

    // Designer Aviators (Gold Frame)
    g.strokeStyle = '#F59E0B';
    g.lineWidth = 7;
    g.beginPath(); g.moveTo(215, 230); g.lineTo(297, 230); g.stroke();
    g.beginPath(); g.moveTo(130, 205); g.lineTo(382, 205); g.stroke();

    // Obsidian Lenses
    g.fillStyle = '#090D16';
    g.beginPath(); g.roundRect(110, 215, 105, 85, [18, 18, 42, 42]); g.fill(); g.stroke();
    g.beginPath(); g.roundRect(297, 215, 105, 85, [18, 18, 42, 42]); g.fill(); g.stroke();

    // Blue Frostfire Blade Reflection in Aviators!
    const drawFrostBladeRef = (lx) => {
      g.save();
      g.beginPath(); g.roundRect(lx, 215, 105, 85, [18, 18, 42, 42]); g.clip();

      // Slanted glowing cyan blade reflection
      g.fillStyle = '#00F0FF';
      g.beginPath();
      g.moveTo(lx + 20, 290);
      g.lineTo(lx + 55, 215);
      g.lineTo(lx + 75, 215);
      g.lineTo(lx + 40, 290);
      g.closePath();
      g.fill();

      // White-hot core gleam
      g.fillStyle = '#FFFFFF';
      g.beginPath();
      g.moveTo(lx + 32, 280);
      g.lineTo(lx + 58, 225);
      g.lineTo(lx + 64, 225);
      g.lineTo(lx + 38, 280);
      g.closePath();
      g.fill();

      g.restore();
    };
    drawFrostBladeRef(110);
    drawFrostBladeRef(297);

    // Sadistic Tilted Smirk showing gold tooth
    g.strokeStyle = '#18181B';
    g.lineWidth = 9;
    g.lineCap = 'round';
    g.beginPath();
    g.moveTo(205, 395);
    g.quadraticCurveTo(270, 400, 355, 348);
    g.stroke();

    // Gold Tooth Glint
    g.fillStyle = '#F59E0B';
    g.beginPath(); g.arc(335, 360, 8, 0, Math.PI * 2); g.fill();
    g.fillStyle = '#FFFFFF';
    g.beginPath(); g.arc(333, 358, 3, 0, Math.PI * 2); g.fill();
  });
}

/**
 * Toby's Frostbitten Teal Hoodie Texture
 */
export function createTatteredHoodieWithFrostbite() {
  return canvasTex('toby_frostbite_hoodie', 512, 512, (g, w, h) => {
    // Teal canvas base
    g.fillStyle = '#0D9488';
    g.fillRect(0, 0, w, h);

    // Subtle fabric grain
    g.fillStyle = 'rgba(15, 118, 110, 0.4)';
    for (let y = 0; y < h; y += 4) g.fillRect(0, y, w, 2);

    // Kangaroo Pocket
    g.fillStyle = '#0F766E';
    g.beginPath();
    g.moveTo(90, 260); g.lineTo(422, 260); g.lineTo(442, 450); g.lineTo(70, 450);
    g.closePath(); g.fill();

    // Drawstrings
    g.strokeStyle = '#E2E8F0';
    g.lineWidth = 6;
    g.beginPath(); g.moveTo(225, 60); g.lineTo(215, 210); g.stroke();
    g.beginPath(); g.moveTo(287, 60); g.lineTo(297, 225); g.stroke();

    // FROSTBITE CRYSTAL ENCROACHMENT (Where Chad's rapier grazed him!)
    g.fillStyle = 'rgba(0, 240, 255, 0.35)';
    g.beginPath();
    g.ellipse(360, 220, 110, 70, 0.4, 0, Math.PI * 2);
    g.fill();

    // Sharp ice crystals
    g.strokeStyle = '#FFFFFF';
    g.lineWidth = 4;
    const crystalCenters = [
      { x: 360, y: 220 },
      { x: 390, y: 190 },
      { x: 340, y: 250 }
    ];
    crystalCenters.forEach(c => {
      for (let i = 0; i < 6; i++) {
        const a = (i / 6) * Math.PI * 2;
        g.beginPath();
        g.moveTo(c.x, c.y);
        g.lineTo(c.x + Math.cos(a) * 35, c.y + Math.sin(a) * 35);
        g.stroke();
      }
    });

    // Mud stains
    g.fillStyle = 'rgba(40, 24, 12, 0.35)';
    g.beginPath(); g.ellipse(140, 380, 55, 30, 0.3, 0, Math.PI * 2); g.fill();
  }, [1, 1]);
}

// ----------------------------------------------------------------------------
// ASSET F-02: ACTIVE GILDED FROSTFIRE RAPIER
// ----------------------------------------------------------------------------

export function buildActiveFrostfireRapier() {
  const weapon = new THREE.Group();
  weapon.name = 'ActiveGildedFrostfireRapier';

  const matSteel = new THREE.MeshStandardMaterial({
    color: 0xE2E8F0,
    metalness: 0.95,
    roughness: 0.1
  });

  const matGold = new THREE.MeshStandardMaterial({
    color: 0xF59E0B,
    metalness: 0.9,
    roughness: 0.2
  });

  const matCyanFlame = new THREE.MeshBasicMaterial({
    color: 0x00F0FF,
    transparent: true,
    opacity: 0.75,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide
  });

  const matCoreWhite = new THREE.MeshBasicMaterial({
    color: 0xFFFFFF,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending
  });

  // 1. Ornate Swept Cup Hilt (Basket)
  const basket = new THREE.Mesh(
    new THREE.SphereGeometry(0.24, 16, 10, 0, Math.PI * 2, 0, Math.PI / 2),
    matGold
  );
  basket.rotation.x = Math.PI;
  basket.position.set(0, 0, 0);
  weapon.add(basket);

  // Grip & Pommel
  const grip = new THREE.Mesh(new THREE.CylinderGeometry(0.04, 0.045, 0.32, 8), matGold);
  grip.position.set(0, -0.22, 0);
  weapon.add(grip);

  const pommel = new THREE.Mesh(new THREE.OctahedronGeometry(0.08), matGold);
  pommel.position.set(0, -0.4, 0);
  weapon.add(pommel);

  // 2. Razor-Sharp Steel Rapier Blade (1.4m long diamond cross-section)
  const bladeGeo = new THREE.CylinderGeometry(0.015, 0.035, 1.45, 4);
  const blade = new THREE.Mesh(bladeGeo, matSteel);
  blade.position.set(0, 0.75, 0);
  weapon.add(blade);

  // 3. Additive Frostfire Flame Sheath (Cyan outer energy envelope)
  const flameGeo = new THREE.CylinderGeometry(0.035, 0.07, 1.48, 8);
  const flame = new THREE.Mesh(flameGeo, matCyanFlame);
  flame.position.set(0, 0.75, 0);
  weapon.add(flame);

  // Inner White-Hot Energy Core
  const coreGeo = new THREE.CylinderGeometry(0.018, 0.04, 1.46, 6);
  const core = new THREE.Mesh(coreGeo, matCoreWhite);
  core.position.set(0, 0.75, 0);
  weapon.add(core);

  // 4. Orbiting Frostfire Cold Blue Embers
  const emberMat = new THREE.MeshBasicMaterial({
    color: 0x38BDF8,
    transparent: true,
    opacity: 0.85,
    blending: THREE.AdditiveBlending
  });
  for (let i = 0; i < 10; i++) {
    const ember = new THREE.Mesh(new THREE.SphereGeometry(0.03, 4, 4), emberMat);
    const angle = (i / 10) * Math.PI * 2;
    ember.position.set(
      Math.cos(angle) * (0.12 + (i % 2) * 0.06),
      0.2 + i * 0.12,
      Math.sin(angle) * (0.12 + (i % 2) * 0.06)
    );
    weapon.add(ember);
  }

  // Active Frostfire Light Emitter
  const light = new THREE.PointLight(0x00F0FF, 3.5, 6.0);
  light.position.set(0, 0.8, 0);
  weapon.add(light);

  return weapon;
}

/**
 * Empty Obsidian Scabbard (Mounted on Chad's left hip since weapon is drawn!)
 */
export function buildEmptyScabbard() {
  const scabbard = new THREE.Group();
  scabbard.name = 'EmptyScabbard';

  const matObsidian = new THREE.MeshStandardMaterial({
    color: 0x090D16,
    metalness: 0.6,
    roughness: 0.3
  });
  const matGold = new THREE.MeshStandardMaterial({
    color: 0xF59E0B,
    metalness: 0.9,
    roughness: 0.2
  });

  const sheathGeo = new THREE.BoxGeometry(0.12, 1.45, 0.07);
  const sheath = new THREE.Mesh(sheathGeo, matObsidian);
  sheath.position.set(0, -0.6, 0);
  scabbard.add(sheath);

  // Gold Bands
  [-0.1, -0.5, -1.0, -1.3].forEach(y => {
    const band = new THREE.Mesh(new THREE.BoxGeometry(0.135, 0.045, 0.085), matGold);
    band.position.set(0, y, 0);
    scabbard.add(band);
  });

  // Empty opening mouth collar
  const collar = new THREE.Mesh(new THREE.BoxGeometry(0.14, 0.06, 0.09), matGold);
  collar.position.set(0, 0.12, 0);
  scabbard.add(collar);

  return scabbard;
}

