// ASSET F-04: TOBY'S MAKESHIFT OAK STAKE WEAPON
// ----------------------------------------------------------------------------

export function buildMakeshiftOakStake() {
  const stake = new THREE.Group();
  stake.name = 'MakeshiftOakStake';

  const matWood = new THREE.MeshStandardMaterial({
    color: 0x78350F,
    roughness: 0.85,
    metalness: 0.05
  });

  const matSplinter = new THREE.MeshStandardMaterial({
    color: 0xB45309,
    roughness: 0.7,
    metalness: 0.1
  });

  const matGrip = new THREE.MeshStandardMaterial({
    color: 0x27170E,
    roughness: 0.9
  });

  // 1. Main Oak Cudgel Body (0.65m shaft)
  const shaftGeo = new THREE.CylinderGeometry(0.075, 0.085, 0.65, 8);
  const shaft = new THREE.Mesh(shaftGeo, matWood);
  shaft.position.set(0, 0.15, 0);
  stake.add(shaft);

  // 2. Leather Handle Grip Wrapping
  const gripGeo = new THREE.CylinderGeometry(0.088, 0.088, 0.28, 8);
