  const subSpike2 = new THREE.Mesh(new THREE.ConeGeometry(0.025, 0.18, 4), matSplinter);
  subSpike2.position.set(0.03, 0.49, -0.03);
  subSpike2.rotation.x = 0.22;
  stake.add(subSpike2);

  return stake;
}

