// ASSET F-01: CHAD_ROBUX ACTIVE COMBAT RIG
// ----------------------------------------------------------------------------

export function buildChadCombatRig(options = {}) {
  const root = new THREE.Group();
  root.name = 'Chad_Robux_CombatRig';

  const pose = options.pose || 'lunge_slash'; // 'lunge_slash', 'execution_standoff', 'standing'

  const matSkin = new THREE.MeshStandardMaterial({
    color: 0xFFF7ED,
    roughness: 0.45,
    metalness: 0.05
  });
  const matTuxedo = new THREE.MeshStandardMaterial({
    color: 0xFFFFFF,
    roughness: 0.35,
    metalness: 0.25,
    map: createDesignerTuxedoTexture()
  });
  const matSleeve = new THREE.MeshStandardMaterial({
    color: 0xFFFFFF,
    roughness: 0.4,
    metalness: 0.2,
    map: createTuxedoSleeveTexture()
  });
  const matSlacks = new THREE.MeshStandardMaterial({
    color: 0xFFFFFF,
    roughness: 0.45,
    metalness: 0.15,
    map: createTuxedoSlacksTexture()
  });
  const matShoe = new THREE.MeshStandardMaterial({
    color: 0x05070B,
    roughness: 0.15,
    metalness: 0.8
  });

  // Torso
  const torso = new THREE.Group();
  torso.name = 'Torso';
  const torsoMesh = createBeveledBox(2.0, 2.0, 1.0, 0.04, 2, matTuxedo);
  torso.add(torsoMesh);

  // Neck Stud & Gold Chain
  const neckStud = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.32, 0.25, 16), matSkin);
  neckStud.position.set(0, 1.1, 0);
  torso.add(neckStud);
  torso.add(buildCubanLinkNecklace());

  // Head with Combat Smirk Decal & Dominus Hood + Crown
  const headGroup = new THREE.Group();
  headGroup.position.set(0, 1.72, 0);
  headGroup.add(createBeveledBox(1.2, 1.2, 1.2, 0.04, 2, matSkin));

  const facePlane = new THREE.Mesh(
    new THREE.PlaneGeometry(1.18, 1.18),
    new THREE.MeshBasicMaterial({ map: createChadCombatFace(), transparent: true })
  );
  facePlane.position.set(0, 0, 0.605);
  headGroup.add(facePlane);

  headGroup.add(buildBullyHeadgear());
  torso.add(headGroup);

  // Arms
  const armL = new THREE.Group();
  armL.position.set(-1.5, 0.75, 0);
  armL.add(createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, matSleeve));
  armL.add(createBeveledBox(0.96, 0.5, 0.96, 0.03, 2, matSkin).translateY(-1.5));
  torso.add(armL);

  const armR = new THREE.Group();
  armR.position.set(1.5, 0.75, 0);
  armR.add(createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, matSleeve));
  armR.add(createBeveledBox(0.96, 0.5, 0.96, 0.03, 2, matSkin).translateY(-1.5));
  torso.add(armR);

  // MOUNT ACTIVE DRAWN FROSTFIRE RAPIER IN CHAD'S RIGHT HAND
  const rapier = buildActiveFrostfireRapier();
  rapier.position.set(0, -1.75, 0.1);
  rapier.rotation.x = Math.PI / 2; // pointed forward
  armR.add(rapier);

  // MOUNT EMPTY SCABBARD ON CHAD'S LEFT HIP
  const emptyScabbard = buildEmptyScabbard();
  emptyScabbard.position.set(-1.15, -0.25, 0.18);
  emptyScabbard.rotation.z = 0.22;
  emptyScabbard.rotation.y = 0.2;
  torso.add(emptyScabbard);

  // Mount Shoulder Cyber-Dragon Pet
  const dragon = buildShoulderDragonPet();
  dragon.scale.set(1.3, 1.3, 1.3);
  dragon.position.set(1.45, 1.95, 0.25);
  dragon.rotation.y = -0.35;
  torso.add(dragon);

  // Legs & Patent Leather Shoes
  const legL = new THREE.Group();
  legL.position.set(-0.52, -1.0, 0);
  legL.add(createBeveledBox(1.0, 1.6, 1.0, 0.04, 2, matSlacks).translateY(-0.6));
  legL.add(createBeveledBox(1.04, 0.55, 1.25, 0.04, 2, matShoe).setPosition(0, -1.5, 0.08));
  torso.add(legL);

  const legR = new THREE.Group();
  legR.position.set(0.52, -1.0, 0);
  legR.add(createBeveledBox(1.0, 1.6, 1.0, 0.04, 2, matSlacks).translateY(-0.6));
  legR.add(createBeveledBox(1.04, 0.55, 1.25, 0.04, 2, matShoe).setPosition(0, -1.5, 0.08));
  torso.add(legR);

  // Kinematics & Poses
  torso.position.y = 2.05;

  if (pose === 'lunge_slash') {
    // Dynamic Fencing Lunge Pose: Right arm thrust forward, left arm back for balance
    torso.rotation.x = 0.22; // forward torso drive
    torso.rotation.y = -0.35;

    headGroup.rotation.set(-0.15, -0.15, 0.05);

    armR.rotation.set(1.45, -0.25, 0.15); // right arm thrust straight forward!
    armL.rotation.set(-0.65, 0.35, -0.45); // left arm swept back dramatically

    legR.position.set(0.52, -1.1, 0.45);
    legR.rotation.set(-0.65, 0, -0.08); // forward bent knee

    legL.position.set(-0.52, -0.9, -0.65);
    legL.rotation.set(0.75, 0, 0.12); // back extended trail leg
  } else if (pose === 'execution_standoff') {
    // Two-handed execution point downward at Toby
    torso.rotation.x = 0.08;
    headGroup.rotation.set(0.15, -0.2, 0);
    armR.rotation.set(1.15, -0.3, 0.2); // rapier pointed down at neck
    armL.rotation.set(-0.25, 0.1, -0.2);
    legL.rotation.set(0, 0, 0.08);
    legR.rotation.set(0, 0, -0.08);
  } else {
    // Default combat ready
    armR.rotation.set(0.45, -0.2, 0.15);
    armL.rotation.set(-0.25, 0.1, -0.15);
  }

  root.add(torso);
  return root;
}

// ----------------------------------------------------------------------------
// ASSET F-03: TOBY MAKESHIFT COMBAT RIG
// ----------------------------------------------------------------------------

export function buildTobyCombatRig(options = {}) {
  const root = new THREE.Group();
  root.name = 'Toby_CombatRig';

  const pose = options.pose || 'desperate_charge'; // 'desperate_charge', 'gate_recoil', 'standing'
  const expression = options.expression || (pose === 'gate_recoil' ? 'shock' : 'charge');

  const matSkin = new THREE.MeshStandardMaterial({ color: 0xF8EE89, roughness: 0.55, metalness: 0.08 });
  const matHoodie = new THREE.MeshStandardMaterial({
    color: 0xFFFFFF,
    roughness: 0.8,
    metalness: 0.05,
    map: createTatteredHoodieWithFrostbite()
  });
  const matSleeve = new THREE.MeshStandardMaterial({
    color: 0xFFFFFF,
    roughness: 0.8,
    metalness: 0.05,
    map: canvasTex('toby_sleeve_plain', 128, 128, (g, w, h) => {
      g.fillStyle = '#0F766E'; g.fillRect(0, 0, w, h);
    })
  });
  const matDenim = new THREE.MeshStandardMaterial({
    color: 0xFFFFFF,
    roughness: 0.75,
    metalness: 0.1,
    map: createDenimJeansTexture()
  });
  const matBoot = new THREE.MeshStandardMaterial({ color: 0x18181B, roughness: 0.85, metalness: 0.2 });

  // Torso
  const torso = new THREE.Group();
  torso.add(createBeveledBox(2.0, 2.0, 1.0, 0.04, 2, matHoodie));

  const neckStud = new THREE.Mesh(new THREE.CylinderGeometry(0.32, 0.32, 0.25, 16), matSkin);
  neckStud.position.set(0, 1.1, 0);
  torso.add(neckStud);

  // Head
  const headGroup = new THREE.Group();
  headGroup.position.set(0, 1.72, 0);
  headGroup.add(createBeveledBox(1.2, 1.2, 1.2, 0.04, 2, matSkin));

  const facePlane = new THREE.Mesh(
    new THREE.PlaneGeometry(1.18, 1.18),
    new THREE.MeshBasicMaterial({ map: createTobyCombatFace(expression), transparent: true })
  );
  facePlane.position.set(0, 0, 0.605);
  headGroup.add(facePlane);

  headGroup.add(buildBaconHairMesh());
  torso.add(headGroup);

  // Arms
  const armL = new THREE.Group();
  armL.position.set(-1.5, 0.75, 0);
  armL.add(createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, matSleeve));
  armL.add(createBeveledBox(0.96, 0.5, 0.96, 0.03, 2, matSkin).translateY(-1.5));
  torso.add(armL);

  const armR = new THREE.Group();
  armR.position.set(1.5, 0.75, 0);
  armR.add(createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, matSleeve));
  armR.add(createBeveledBox(0.96, 0.5, 0.96, 0.03, 2, matSkin).translateY(-1.5));
  torso.add(armR);

  // Makeshift Oak Stake mounted in Toby's hands
  const stake = buildMakeshiftOakStake();
  stake.position.set(0, -1.65, 0.1);
  stake.rotation.x = Math.PI / 2; // pointed forward
  armR.add(stake);

  // Legs & Boots
  const legL = new THREE.Group();
  legL.position.set(-0.52, -1.0, 0);
  legL.add(createBeveledBox(1.0, 1.6, 1.0, 0.04, 2, matDenim).translateY(-0.6));
  legL.add(createBeveledBox(1.04, 0.55, 1.2, 0.04, 2, matBoot).setPosition(0, -1.5, 0.08));
  torso.add(legL);

  const legR = new THREE.Group();
  legR.position.set(0.52, -1.0, 0);
  legR.add(createBeveledBox(1.0, 1.6, 1.0, 0.04, 2, matDenim).translateY(-0.6));
  legR.add(createBeveledBox(1.04, 0.55, 1.2, 0.04, 2, matBoot).setPosition(0, -1.5, 0.08));
  torso.add(legR);

  // Kinematics & Poses
  if (pose === 'desperate_charge') {
    // 2-Handed Forward Charge
    torso.position.y = 1.95;
    torso.rotation.x = 0.35; // aggressive sprint lean
    headGroup.rotation.set(-0.25, 0, 0);

    armR.rotation.set(1.35, -0.3, 0.2); // forward thrust
    armL.rotation.set(1.15, 0.45, -0.2); // two-handed support

    legL.position.set(-0.52, -1.05, 0.4);
    legL.rotation.set(-0.65, 0, 0.06);

    legR.position.set(0.52, -0.95, -0.5);
    legR.rotation.set(0.85, 0, -0.06);
  } else if (pose === 'gate_recoil') {
    // Pinned against gate bars, trembling defensive pose
    torso.position.y = 1.45;
    torso.rotation.x = -0.18; // slammed back against gate
    headGroup.rotation.set(-0.2, 0.1, 0); // head pushed back in horror

    armL.rotation.set(0.95, 0.4, -0.35); // trembling arms raised defensively
    armR.rotation.set(1.05, -0.4, 0.35);

    legL.position.set(-0.52, -0.85, 0.35);
    legL.rotation.set(-0.75, 0, 0.12);

    legR.position.set(0.52, -0.9, -0.15);
    legR.rotation.set(0.45, 0, -0.12);
  } else {
    torso.position.y = 2.05;
  }

  root.add(torso);
  return root;
}

