// ============================================================================
// THE GLITCH MARKET — 5-ANGLE STUDIO AUDIT RENDERER
// MILESTONE 5.5 // BATCH 1: COMBAT RIGS & ACTIVE WEAPONS (F-01 THROUGH F-05)
//
// Produces:
// 1. duel_angle_1_chad_combat_lunge.png (View 01: Chad Active Combat Lunge & Drawn Rapier)
// 2. duel_angle_2_frostfire_rapier_macro.png (View 02: Active Gilded Frostfire Rapier & Embers)
// 3. duel_angle_3_toby_makeshift_charge.png (View 03: Toby Desperate Charge & Makeshift Oak Stake)
// 4. duel_angle_4_combat_face_decals.png (View 04: Combat Face Decals: Predatory Smirk vs Terror)
// 5. duel_angle_5_gate_recoil_standoff.png (View 05: Gate Recoil Defensive Pose & Frostbite Creep)
// 6. duel_batch1_master_sheet.png (2400x1350 5-Panel Production Audit Sheet)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import {
  buildChadCombatRig,
  buildTobyCombatRig,
  buildActiveFrostfireRapier,
  buildMakeshiftOakStake
} from './duel_combatants.js';

const ANGLES = [
  {
    id: 'duel_angle_1_chad_combat_lunge',
    title: 'VIEW 01: CHAD_ROBUX // ACTIVE COMBAT FENCING LUNGE',
    desc: 'Unsheathed 1.4m Frostfire Rapier, forward aggressive lean, empty hip scabbard & shoulder dragon pet',
    pos: [4.2, 2.4, 4.8],
    target: [0.0, 2.0, 0.0],
    fov: 46,
    mode: 'chad_lunge'
  },
  {
    id: 'duel_angle_2_frostfire_rapier_macro',
    title: 'VIEW 02: ACTIVE GILDED FROSTFIRE RAPIER & ENERGY FLAME',
    desc: '1.45m silver blade encased in additive cyan flame sheath (#00F0FF), swept basket hilt & 10 cold blue embers',
    pos: [1.2, 2.2, 2.2],
    target: [0.3, 1.8, 0.4],
    fov: 36,
    mode: 'rapier_macro'
  },
  {
    id: 'duel_angle_3_toby_makeshift_charge',
    title: 'VIEW 03: TOBY MAKESHIFT COMBAT RIG // 2-HANDED CHARGE',
    desc: 'Aggressive forward sprint, gripping 0.65m jagged oak stake with multi-tooth splinter point & gritted teeth',
    pos: [-2.6, 2.1, 3.4],
    target: [0.0, 1.8, 0.3],
    fov: 42,
    mode: 'toby_charge'
  },
  {
    id: 'duel_angle_4_combat_face_decals',
    title: 'VIEW 04: COMBAT DECALS // PREDATORY SMIRK VS TERROR SHOCK',
    desc: 'Chad\'s aviators reflecting blue frostfire flame vs Toby\'s wide dilated pupils, sweat beads & frostbite',
    pos: [0.8, 3.8, 2.6],
    target: [0.0, 3.75, 0.4],
    fov: 34,
    mode: 'chad_face'
  },
  {
    id: 'duel_angle_5_gate_recoil_standoff',
    title: 'VIEW 05: TOBY GATE RECOIL POSE // PINNED & TREMBLING',
    desc: 'Slammed against iron gate bars, trembling arms raised defensively, quivering mouth & frostbite on teal hoodie',
    pos: [-2.2, 1.8, 3.2],
    target: [0.0, 1.4, 0.2],
    fov: 42,
    mode: 'toby_recoil'
  }
];

function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const renderer = new THREE.WebGLRenderer({
    canvas: glCanvas,
    antialias: true,
    alpha: false,
    preserveDrawingBuffer: true
  });
  renderer.setSize(1280, 760);
  renderer.setPixelRatio(1);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.35;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050811);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(400, 400, 320, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 50, 0);
  scene.add(skyDome);

  // Lighting Rig
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x0A0F1E, 1.1);
  scene.add(hemi);

  const keyLight = new THREE.DirectionalLight(0xFFFBEB, 2.2);
  keyLight.position.set(8, 12, 10);
  scene.add(keyLight);

  const fillCyan = new THREE.DirectionalLight(0x00F0FF, 1.6);
  fillCyan.position.set(-8, 6, 4);
  scene.add(fillCyan);

  const goldRim = new THREE.DirectionalLight(0xF59E0B, 2.2);
  goldRim.position.set(-8, 8, -8);
  scene.add(goldRim);

  const frontCamKey = new THREE.DirectionalLight(0xFFFFFF, 1.8);
  frontCamKey.position.set(2, 4, 7);
  scene.add(frontCamKey);

  // Rain-Slicked Stone Floor
  const floorGeo = new THREE.CylinderGeometry(16, 16, 0.4, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x090D18,
    roughness: 0.25,
    metalness: 0.5
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.position.set(0, -0.2, 0);
  scene.add(floor);

  // Reflective puddle
  const puddleGeo = new THREE.CircleGeometry(3.6, 32);
  puddleGeo.rotateX(-Math.PI / 2);
  const puddleMat = new THREE.MeshStandardMaterial({
    color: 0x050A14,
    roughness: 0.08,
    metalness: 0.85,
    transparent: true,
    opacity: 0.88
  });
  const puddle = new THREE.Mesh(puddleGeo, puddleMat);
  puddle.position.set(0, 0.01, 0);
  scene.add(puddle);

  // Rusted gate bars in background
  const gateGroup = new THREE.Group();
  gateGroup.position.set(0, 0, -2.4);
  const barMat = new THREE.MeshStandardMaterial({ color: 0x1E2430, metalness: 0.85, roughness: 0.6 });
  for (let i = -7; i <= 7; i++) {
    const bar = new THREE.Mesh(new THREE.CylinderGeometry(0.045, 0.045, 6, 8), barMat);
    bar.position.set(i * 0.7, 3, 0);
    gateGroup.add(bar);
  }
  scene.add(gateGroup);

  // --------------------------------------------------------------------------
  // RIGS
  // --------------------------------------------------------------------------
  // 1. Chad Combat Lunge
  const chadLunge = buildChadCombatRig({ pose: 'lunge_slash' });
  scene.add(chadLunge);

  // 2. Toby Desperate Charge
  const tobyCharge = buildTobyCombatRig({ pose: 'desperate_charge', expression: 'charge' });
  scene.add(tobyCharge);

  // 3. Toby Gate Recoil
  const tobyRecoil = buildTobyCombatRig({ pose: 'gate_recoil', expression: 'shock' });
  scene.add(tobyRecoil);

  // 4. Standalone Floating Active Rapier (For macro inspect)
  const standaloneRapier = buildActiveFrostfireRapier();
  standaloneRapier.position.set(0.3, 1.8, 0.4);
  standaloneRapier.rotation.z = -0.35;
  scene.add(standaloneRapier);

  // 5. Standalone Makeshift Stake (For macro inspect)
  const standaloneStake = buildMakeshiftOakStake();
  standaloneStake.position.set(0, 1.5, 0.4);
  standaloneStake.rotation.z = 0.4;
  scene.add(standaloneStake);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    // Visibility toggle per mode
    chadLunge.visible = (cfg.mode === 'chad_lunge' || cfg.mode === 'chad_face');
    tobyCharge.visible = (cfg.mode === 'toby_charge');
    tobyRecoil.visible = (cfg.mode === 'toby_recoil');
    standaloneRapier.visible = (cfg.mode === 'rapier_macro');
    standaloneStake.visible = false;

    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 350);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    renderer.render(scene, cam);

    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = 1280;
    angleCanvas.height = 760;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Overlay Badge
    actx.fillStyle = 'rgba(5, 8, 17, 0.85)';
    actx.fillRect(24, 24, 730, 68);
    actx.strokeStyle = '#00F0FF';
    actx.lineWidth = 1.5;
    actx.strokeRect(24, 24, 730, 68);

    actx.fillStyle = '#00F0FF';
    actx.font = 'bold 18px monospace';
    actx.fillText(cfg.title, 42, 52);

    actx.fillStyle = '#94A3B8';
    actx.font = '13px monospace';
    actx.fillText(cfg.desc, 42, 74);

    renderedCanvases.push(angleCanvas);

    // Upload individual angle
    const blob = await canvasToBlob(angleCanvas);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png`);
  }

  // ==========================================================================
  // COMPOSITE MASTER AUDIT SHEET (2400 × 1350)
  // ==========================================================================
  masterCtx.fillStyle = '#050811';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Cyber Grid
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.05)';
  masterCtx.lineWidth = 1;
  const gridSize = 40;
  for (let x = 0; x < 2400; x += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Header
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 34px sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // MILESTONE 5.5: THE PRE-AWAKENING DUEL', 45, 55);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText('BATCH 1: COMBAT RIGS & ACTIVE DRAWN WEAPONS — 5 CORE ASSETS VERIFIED (F-01 THROUGH F-05)', 45, 85);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('THE BEATDOWN BEFORE THE AWAKENING • CHAD_ROBUX VS TOBY', 2355, 55);
  masterCtx.fillText('FENCING LUNGE • DRAWN FROSTFIRE RAPIER • MAKESHIFT OAK STAKE • GATE RECOIL • COMBAT DECALS', 2355, 78);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath(); masterCtx.moveTo(45, 105); masterCtx.lineTo(2355, 105); masterCtx.stroke();

  // Layout:
  // Large Hero on Left (1420 × 840)
  const heroX = 45;
  const heroY = 130;
  const heroW = 1420;
  const heroH = 840;

  masterCtx.drawImage(renderedCanvases[0], heroX, heroY, heroW, heroH);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(heroX, heroY, heroW, heroH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(heroX, heroY + heroH - 48, heroW, 48);
  masterCtx.fillStyle = '#38BDF8';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.fillText('VIEW 01: CHAD_ROBUX (ACTIVE COMBAT FENCING LUNGE RIG)', heroX + 16, heroY + heroH - 18);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('Unsheathed 1.4m Frostfire Rapier with cyan flame sheath, empty hip scabbard & forward aggressive drive', heroX + heroW - 16, heroY + heroH - 18);
  masterCtx.textAlign = 'left';

  // 4 Thumbnails on Right (2x2 Grid)
  const rightColX1 = 1500;
  const rightColX2 = 1940;
  const rowY1 = 130;
  const rowY2 = 572;
  const thumbW = 415;
  const thumbH = 398;

  const thumbs = [
    { idx: 1, x: rightColX1, y: rowY1, title: 'ANGLE 2: ACTIVE FROSTFIRE RAPIER', desc: '1.45m silver blade, cyan flame & embers' },
    { idx: 2, x: rightColX2, y: rowY1, title: 'ANGLE 3: TOBY MAKESHIFT CHARGE', desc: '2-handed sprint & jagged oak stake' },
    { idx: 3, x: rightColX1, y: rowY2, title: 'ANGLE 4: COMBAT FACE DECALS', desc: 'Predatory sneer vs terror shock & frost' },
    { idx: 4, x: rightColX2, y: rowY2, title: 'ANGLE 5: GATE RECOIL POSE', desc: 'Pinned trembling stance & torn hoodie' }
  ];

  thumbs.forEach(t => {
    masterCtx.drawImage(renderedCanvases[t.idx], t.x, t.y, thumbW, thumbH);
    masterCtx.strokeStyle = '#00F0FF';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(t.x, t.y, thumbW, thumbH);

    masterCtx.fillStyle = 'rgba(7, 13, 27, 0.9)';
    masterCtx.fillRect(t.x + 8, t.y + 8, thumbW - 16, 44);
    masterCtx.strokeStyle = '#38BDF8';
    masterCtx.lineWidth = 1;
    masterCtx.strokeRect(t.x + 8, t.y + 8, thumbW - 16, 44);

    masterCtx.fillStyle = '#00F0FF';
    masterCtx.font = 'bold 12px monospace';
    masterCtx.fillText(t.title, t.x + 16, t.y + 26);
    masterCtx.fillStyle = '#94A3B8';
    masterCtx.font = '10px monospace';
    masterCtx.fillText(t.desc, t.x + 16, t.y + 42);
  });

  // Bottom Technical Spec Panel
  const specY = 1000;
  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(45, specY, 2310, 315);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(45, specY, 2310, 315);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillText('MILESTONE 5.5 // BATCH 1: COMBAT RIGS & ACTIVE WEAPONS AUDIT (F-01 THROUGH F-05)', 65, specY + 38);

  masterCtx.strokeStyle = '#334155';
  masterCtx.lineWidth = 1;
  masterCtx.beginPath(); masterCtx.moveTo(65, specY + 52); masterCtx.lineTo(2335, specY + 52); masterCtx.stroke();

  masterCtx.font = '12px monospace';
  masterCtx.fillStyle = '#E2E8F0';
  const lineH = 26;
  const col1X = 65;
  const col2X = 840;
  const col3X = 1600;

  // Column 1: Chad Rig & Rapier
  masterCtx.fillText('• ASSET F-01: CHAD_ROBUX ACTIVE COMBAT RIG (FENCING LUNGE)', col1X, specY + 80);
  masterCtx.fillText('  - Right arm extended holding drawn rapier, left arm swept back, torso rotated 0.35 rad in forward attack drive.', col1X, specY + 80 + lineH);
  masterCtx.fillText('  - Empty obsidian hip scabbard with gold bands & mouth collar mounted on left hip.', col1X, specY + 80 + lineH * 2);
  masterCtx.fillText('• ASSET F-02: ACTIVE GILDED FROSTFIRE RAPIER WEAPON', col1X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - 1.45m razor-sharp diamond steel blade encased in additive cyan flame envelope (#00F0FF) & 10 cold blue embers.', col1X, specY + 80 + lineH * 4);

  // Column 2: Toby Rig & Stake
  masterCtx.fillText('• ASSET F-03: TOBY MAKESHIFT COMBAT RIG (DUAL-POSE SUPPORT)', col2X, specY + 80);
  masterCtx.fillText('  - Pose A: 2-handed forward charge lean with gritted teeth grit holding makeshift wooden stake.', col2X, specY + 80 + lineH);
  masterCtx.fillText('  - Pose B: Slammed against iron gate bars in terror recoil, trembling arms raised, coughing digital glitch.', col2X, specY + 80 + lineH * 2);
  masterCtx.fillText('• ASSET F-04: MAKESHIFT OAK STAKE WEAPON (0.65m CUDGEL SHARD)', col2X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Fractured oak shaft with leather grip & lethal multi-tooth jagged splinter point (#B45309).', col2X, specY + 80 + lineH * 4);

  // Column 3: Combat Decals & Status
  masterCtx.fillText('• ASSET F-05: HIGH-INTENSITY COMBAT FACE DECALS', col3X, specY + 80);
  masterCtx.fillText('  - Chad: Mirrored aviators reflecting blue frostfire flame blade & sadistic upward smirk showing gold tooth.', col3X, specY + 80 + lineH);
  masterCtx.fillText('  - Toby: Wide dilated pupils, quivering teeth, cold sweat beads & cyan crystalline frostbite on bruised cheek.', col3X, specY + 80 + lineH * 2);
  masterCtx.fillText('• BATCH 1 STATUS: 100% COMPLETE & VERIFIED — READY FOR BATCH 2 (KINETIC COMBAT VFX)', col3X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Next: 2.5m Crescent Slash Wave, Wood Splinter Explosion, Cobblestone Skid Marks & Critical [1 HP] HUD.', col3X, specY + 80 + lineH * 4);

  // Upload Master Sheet
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('duel_batch1_master_sheet.png', masterBlob);
  console.log('SAVED: duel_batch1_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('DUEL_BATCH_1_AUDIT_COMPLETE');
}

window.onload = init;

