args.Content:
// ============================================================================
// THE GLITCH MARKET — DUEL KINETIC COMBAT VFX & CRITICAL DAMAGE
// MILESTONE 5.5 // BATCH 2: KINETIC COMBAT VFX (FX-01 THROUGH FX-05)
//
// Assets:
// - FX-01: 2.5m Frostfire Crescent Slash Wave (Additive Cyan/White Blade Arc)
// - FX-02: Wood Shatter Singularity (24 Radial Flying Oak Splinters & Sawdust)
// - FX-03: Wet Cobblestone Skid Marks & Water Mud Spray (4.2m Churned Scrape)
// - FX-04: Flashing Critical [1 HP] System Error HUD Bar & Glitch Scanlines
// - FX-05: Crystalline Frostbite Encroachment Clusters (Ice Spikes & Frost)
// ============================================================================

import * as THREE from 'three';
import { canvasTex } from './core/geo.js';

// ----------------------------------------------------------------------------
// ASSET FX-01: 2.5m FROSTFIRE CRESCENT SLASH WAVE
// ----------------------------------------------------------------------------

export function buildFrostfireCrescentWave(radius = 2.5) {
  const wave = new THREE.Group();
  wave.name = 'FrostfireCrescentWave';

  // 1. Curved Aerodynamic Slash Arc Blade Mesh
  const arcGeo = new THREE.RingGeometry(radius - 0.45, radius, 36, 1, 0, Math.PI * 0.75);
  const arcMatCyan = new THREE.MeshBasicMaterial({
    color: 0x00F0FF,
    transparent: true,
    opacity: 0.85,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });
  const arcMesh = new THREE.Mesh(arcGeo, arcMatCyan);
  wave.add(arcMesh);

  // 2. White-Hot Razor Cutting Edge (Inner concentric rim)
  const coreGeo = new THREE.RingGeometry(radius - 0.12, radius, 36, 1, 0, Math.PI * 0.75);
  const coreMatWhite = new THREE.MeshBasicMaterial({
    color: 0xFFFFFF,
    transparent: true,
    opacity: 0.95,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });
  const coreMesh = new THREE.Mesh(coreGeo, coreMatWhite);
  coreMesh.position.set(0, 0, 0.01);
  wave.add(coreMesh);

  // 3. Trailing Motion Streak Ribbons
  for (let i = 1; i <= 3; i++) {
    const trailGeo = new THREE.RingGeometry(radius - 0.65 - i * 0.12, radius - 0.45, 24, 1, 0, Math.PI * (0.75 - i * 0.15));
    const trailMat = new THREE.MeshBasicMaterial({
      color: 0x38BDF8,
      transparent: true,
      opacity: 0.45 / i,
      side: THREE.DoubleSide,
      blending: THREE.AdditiveBlending,
      depthWrite: false
    });
    const trail = new THREE.Mesh(trailGeo, trailMat);
    trail.position.set(0, 0, -0.015 * i);
    wave.add(trail);
  }

  // 4. Kinetic Frostfire Embers along slash trajectory
  const emberMat = new THREE.MeshBasicMaterial({
    color: 0x00F0FF,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending
  });
  for (let i = 0; i < 16; i++) {
    const angle = (i / 16) * Math.PI * 0.75;
    const r = radius - 0.15 + (Math.random() - 0.5) * 0.4;
    const ember = new THREE.Mesh(new THREE.SphereGeometry(0.04, 4, 4), emberMat);
    ember.position.set(Math.cos(angle) * r, Math.sin(angle) * r, (Math.random() - 0.5) * 0.25);
    wave.add(ember);
  }

  // Active Light
  const waveLight = new THREE.PointLight(0x00F0FF, 3.0, 8.0);
  waveLight.position.set(Math.cos(Math.PI * 0.375) * radius, Math.sin(Math.PI * 0.375) * radius, 0.5);
  wave.add(waveLight);

  return wave;
}

// ----------------------------------------------------------------------------
// ASSET FX-02: WOOD SHATTER SINGULARITY & EXPLODING SPLINTERS
// ----------------------------------------------------------------------------

export function buildWoodShatterExplosion() {
  const shatter = new THREE.Group();
  shatter.name = 'WoodShatterExplosion';

  const matDarkWood = new THREE.MeshStandardMaterial({
    color: 0x78350F,
    roughness: 0.8,
    metalness: 0.05
  });

  const matLightFiber = new THREE.MeshStandardMaterial({
    color: 0xB45309,
    roughness: 0.7,
    metalness: 0.1
  });

  const matEnergyFlash = new THREE.MeshBasicMaterial({
    color: 0xFFFFFF,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending
  });

  // 1. Central Impact Energy Core (The cut singularity)
  const coreSphere = new THREE.Mesh(new THREE.SphereGeometry(0.18, 12, 12), matEnergyFlash);
  shatter.add(coreSphere);

  const coreGlow = new THREE.Mesh(
    new THREE.SphereGeometry(0.35, 12, 12),
    new THREE.MeshBasicMaterial({
      color: 0x00F0FF,
      transparent: true,
      opacity: 0.6,
      blending: THREE.AdditiveBlending
    })
  );
  shatter.add(coreGlow);

  // 2. 24 Radial Flying Geometric Oak Splinters
  for (let i = 0; i < 24; i++) {
    const angleTheta = Math.random() * Math.PI * 2;
    const anglePhi = (Math.random() - 0.5) * Math.PI;
    const dist = 0.35 + Math.random() * 0.85;

    const length = 0.15 + Math.random() * 0.35;
    const width = 0.025 + Math.random() * 0.04;

    const splinterGeo = new THREE.ConeGeometry(width, length, 4);
    const splinter = new THREE.Mesh(splinterGeo, (i % 2 === 0) ? matLightFiber : matDarkWood);

    const px = Math.cos(angleTheta) * Math.cos(anglePhi) * dist;
    const py = Math.sin(anglePhi) * dist;
    const pz = Math.sin(angleTheta) * Math.cos(anglePhi) * dist;

    splinter.position.set(px, py, pz);
    splinter.lookAt(px * 2, py * 2, pz * 2);
    splinter.rotateX(Math.PI / 2);
    shatter.add(splinter);
  }

  // 3. Floating Sawdust Particle Cloud
  const dustMat = new THREE.MeshBasicMaterial({
    color: 0xD97706,
    transparent: true,
    opacity: 0.7
  });
  for (let i = 0; i < 18; i++) {
    const dust = new THREE.Mesh(new THREE.OctahedronGeometry(0.035), dustMat);
    dust.position.set(
      (Math.random() - 0.5) * 1.4,
      (Math.random() - 0.5) * 1.4,
      (Math.random() - 0.5) * 1.4
    );
    shatter.add(dust);
  }

  return shatter;
}

// ----------------------------------------------------------------------------
// ASSET FX-03: WET COBBLESTONE SKID MARKS & MUD SPRAY
// ----------------------------------------------------------------------------

export function buildWetSkidTrail(length = 4.2) {
  const skid = new THREE.Group();
  skid.name = 'WetSkidTrail';

  // 1. Dual Tire / Boot Churned Mud Scrape Ribbons on Street
  const skidTex = canvasTex('skid_churned_mud', 512, 128, (g, w, h) => {
    // Transparent base
    g.clearRect(0, 0, w, h);

    // Churned black mud skid tracks
    g.fillStyle = 'rgba(11, 15, 25, 0.88)';
    g.fillRect(0, 15, w, 35);
    g.fillRect(0, 78, w, 35);

    // Water displacement streaks
    g.fillStyle = 'rgba(0, 240, 255, 0.25)';
    g.fillRect(0, 48, w, 6);
    g.fillRect(0, 110, w, 6);

    // Mud spray splatter specks
    g.fillStyle = '#1C1917';
    for (let i = 0; i < 150; i++) {
      const rx = Math.random() * w;
      const ry = Math.random() * h;
      g.fillRect(rx, ry, 2 + Math.random() * 4, 2 + Math.random() * 4);
    }
  }, [1, 1]);

  const skidGeo = new THREE.PlaneGeometry(length, 0.95);
  skidGeo.rotateX(-Math.PI / 2);
  const skidMat = new THREE.MeshStandardMaterial({
    map: skidTex,
    transparent: true,
    opacity: 0.92,
    roughness: 0.2, // wet sheen
    metalness: 0.6
  });
  const skidMesh = new THREE.Mesh(skidGeo, skidMat);
  skidMesh.position.set(0, 0.015, 0);
  skid.add(skidMesh);

  // 2. 3D Low-Poly Splashing Water Droplets
  const waterMat = new THREE.MeshStandardMaterial({
    color: 0x38BDF8,
    roughness: 0.1,
    metalness: 0.8,
    transparent: true,
    opacity: 0.85
  });
  for (let i = 0; i < 20; i++) {
    const drop = new THREE.Mesh(new THREE.DodecahedronGeometry(0.04), waterMat);
    const progress = (i / 20) * length - length / 2;
    drop.position.set(
      progress + (Math.random() - 0.5) * 0.3,
      0.05 + Math.random() * 0.22,
      (Math.random() - 0.5) * 0.75
    );
    skid.add(drop);
  }

  return skid;
}

// ----------------------------------------------------------------------------
// ASSET FX-04: FLASHING CRITICAL [1 HP] SYSTEM ERROR HUD
// ----------------------------------------------------------------------------

export function buildCriticalHealthBar() {
  const hud = new THREE.Group();
  hud.name = 'CriticalHealthHUD';

  const hudTex = canvasTex('hud_critical_1hp', 512, 256, (g, w, h) => {
    // Dark translucent emergency slate backdrop
    g.fillStyle = 'rgba(15, 7, 7, 0.92)';
    g.fillRect(0, 0, w, h);

    // Flashing red hazard border
    g.strokeStyle = '#EF4444';
    g.lineWidth = 8;
    g.strokeRect(8, 8, w - 16, h - 16);

    // Hazard Stripes in top header
    g.fillStyle = '#EF4444';
    g.fillRect(16, 16, w - 32, 38);
    g.fillStyle = '#0F0505';
    for (let x = 0; x < w; x += 30) {
      g.beginPath();
      g.moveTo(x, 16);
      g.lineTo(x + 15, 16);
      g.lineTo(x - 5, 54);
      g.lineTo(x - 20, 54);
      g.closePath();
      g.fill();
    }

    // Title
    g.fillStyle = '#FFFFFF';
    g.font = '900 20px monospace';
    g.textAlign = 'center';
    g.fillText('⚠ SYSTEM WARNING: CRITICAL FAILURE ⚠', w / 2, 42);

    // Player Line
    g.textAlign = 'left';
    g.fillStyle = '#94A3B8';
    g.font = 'bold 18px monospace';
    g.fillText('PLAYER: TOBY [BACON HAIR]', 24, 82);

    // Critical 1 HP Text
    g.fillStyle = '#EF4444';
    g.font = '900 32px monospace';
    g.fillText('HP: 1 / 100', 24, 124);

    // Health Bar Frame
    g.strokeStyle = '#450A0A';
    g.lineWidth = 4;
    g.strokeRect(24, 140, w - 48, 32);

    g.fillStyle = '#1C0606';
    g.fillRect(26, 142, w - 52, 28);

    // 1% Red Health Sliver
    g.fillStyle = '#EF4444';
    g.fillRect(26, 142, (w - 52) * 0.015, 28);

    // Warning Tag
    g.fillStyle = '#F59E0B';
    g.font = 'bold 15px monospace';
    g.fillText('STATUS: FATAL BLOW IMMINENT', 24, 198);

    g.fillStyle = '#EF4444';
    g.font = 'bold 15px monospace';
    g.fillText('STAKE: PERMANENT AVATAR WIPEOUT', 24, 222);
  }, [1, 1]);

  const cardGeo = new THREE.PlaneGeometry(2.4, 1.2);
  const cardMat = new THREE.MeshBasicMaterial({
    map: hudTex,
    transparent: true,
    opacity: 0.95,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const card = new THREE.Mesh(cardGeo, cardMat);
  hud.add(card);

  // Red Pulsing Glow Frame
  const frameGeo = new THREE.RingGeometry(1.2, 1.25, 4);
  const frameMat = new THREE.MeshBasicMaterial({
    color: 0xEF4444,
    transparent: true,
    opacity: 0.8,
    side: THREE.DoubleSide
  });
  const frame = new THREE.Mesh(frameGeo, frameMat);
  frame.scale.set(1.0, 0.5, 1.0);
  hud.add(frame);

  return hud;
}

// ----------------------------------------------------------------------------
// ASSET FX-05: CRYSTALLINE FROSTBITE ICE SPIKES
// ----------------------------------------------------------------------------

export function buildFrostbiteCrystals() {
  const frost = new THREE.Group();
  frost.name = 'FrostbiteCrystals';

  const matIce = new THREE.MeshStandardMaterial({
    color: 0x00F0FF,
    roughness: 0.15,
    metalness: 0.8,
    transparent: true,
    opacity: 0.85
  });

  const matIceWhite = new THREE.MeshStandardMaterial({
    color: 0xFFFFFF,
    roughness: 0.1,
    metalness: 0.9,
    transparent: true,
    opacity: 0.92
  });

  // Cluster of 14 Sharp Geometric Ice Spikes
  for (let i = 0; i < 14; i++) {
    const angle = (i / 14) * Math.PI * 2;
    const r = 0.2 + (i % 3) * 0.18;
    const height = 0.25 + Math.random() * 0.45;

    const spikeGeo = new THREE.ConeGeometry(0.06, height, 5);
    const spike = new THREE.Mesh(spikeGeo, (i % 2 === 0) ? matIce : matIceWhite);

    spike.position.set(
      Math.cos(angle) * r,
      height / 2,
      Math.sin(angle) * r
    );
    spike.rotation.x = (Math.random() - 0.5) * 0.35;
    spike.rotation.z = (Math.random() - 0.5) * 0.35;
    frost.add(spike);
  }

  // Floating Ice Mist
  const mistMat = new THREE.MeshBasicMaterial({
    color: 0x38BDF8,
    transparent: true,
    opacity: 0.35,
    blending: THREE.AdditiveBlending,
    depthWrite: false
  });
  const mist = new THREE.Mesh(new THREE.RingGeometry(0.4, 0.75, 16), mistMat);
  mist.rotation.x = -Math.PI / 2;
  mist.position.set(0, 0.05, 0);
  frost.add(mist);

  return frost;
}

