// ============================================================================
// THE GLITCH MARKET — 5-ANGLE STUDIO AUDIT RENDERER
// MILESTONE 5.5 // BATCH 2: KINETIC COMBAT VFX (FX-01 THROUGH FX-05)
//
// Produces:
// 1. duel_fx_angle_1_composite_suite.png (View 01: Composite Duel Combat VFX Suite)
// 2. duel_fx_angle_2_frostfire_slash_macro.png (View 02: 2.5m Frostfire Crescent Slash Wave)
// 3. duel_fx_angle_3_wood_shatter_macro.png (View 03: Wood Shatter Singularity & 24 Splinters)
// 4. duel_fx_angle_4_critical_hud_macro.png (View 04: Flashing Critical [1 HP] Error HUD)
// 5. duel_fx_angle_5_skid_and_frostbite_macro.png (View 05: Wet Skid Trail & Frostbite Crystals)
// 6. duel_batch2_master_sheet.png (2400x1350 5-Panel Production Audit Sheet)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import {
  buildFrostfireCrescentWave,
  buildWoodShatterExplosion,
  buildWetSkidTrail,
  buildCriticalHealthBar,
  buildFrostbiteCrystals
} from './duel_effects.js';

const ANGLES = [
  {
    id: 'duel_fx_angle_1_composite_suite',
    title: 'VIEW 01: COMPOSITE COMBAT VFX SUITE (DYNAMIC ARRANGEMENT)',
    desc: '2.5m Frostfire slash slicing wood singularity, 4.2m churned mud skid trail, frostbite & [1 HP] HUD',
    pos: [3.8, 2.5, 4.6],
    target: [0.0, 1.3, 0.0],
    fov: 46,
    mode: 'composite'
  },
  {
    id: 'duel_fx_angle_2_frostfire_slash_macro',
    title: 'VIEW 02: ASSET FX-01 // 2.5m FROSTFIRE CRESCENT SLASH WAVE',
    desc: 'Additive cyan (#00F0FF) blade arc, white-hot cutting razor core, 3-tier motion streaks & 16 cold embers',
    pos: [1.2, 1.8, 3.2],
    target: [0.0, 1.5, 0.0],
    fov: 44,
    mode: 'slash_wave'
  },
  {
    id: 'duel_fx_angle_3_wood_shatter_macro',
    title: 'VIEW 03: ASSET FX-02 // WOOD SHATTER SINGULARITY & 24 SPLINTERS',
    desc: 'Impact singularity: 24 radial oak splinters (#B45309), blue flash core & amber sawdust particle field',
    pos: [1.3, 1.4, 2.0],
    target: [0.0, 1.1, 0.0],
    fov: 38,
    mode: 'wood_shatter'
  },
  {
    id: 'duel_fx_angle_4_critical_hud_macro',
    title: 'VIEW 04: ASSET FX-04 // FLASHING CRITICAL [1 HP] SYSTEM ERROR HUD',
    desc: 'Translucent emergency hazard plate, red warning stripes, 1% red health sliver & fatal blow warning',
    pos: [0.0, 1.6, 2.4],
    target: [0.0, 1.6, 0.0],
    fov: 38,
    mode: 'critical_hud'
  },
  {
    id: 'duel_fx_angle_5_skid_and_frostbite_macro',
    title: 'VIEW 05: ASSETS FX-03 & FX-05 // WET SKID TRAIL & FROSTBITE CRYSTALS',
    desc: '4.2m churned mud tire/boot scrape, wet water sheen, 20 splashing droplets & 14 sharp crystalline ice spikes',
    pos: [-2.4, 1.3, 2.2],
    target: [0.0, 0.2, 0.0],
    fov: 42,
    mode: 'skid_frost'
  }
];

function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const renderer = new THREE.WebGLRenderer({
    canvas: glCanvas,
    antialias: true,
    alpha: false,
    preserveDrawingBuffer: true
  });
  renderer.setSize(1280, 760);
  renderer.setPixelRatio(1);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.35;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050811);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(400, 400, 320, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 50, 0);
  scene.add(skyDome);

  // Lighting Rig
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x0A0F1E, 1.1);
  scene.add(hemi);

  const keyLight = new THREE.DirectionalLight(0xFFFBEB, 2.0);
  keyLight.position.set(8, 12, 10);
  scene.add(keyLight);

  const fillCyan = new THREE.DirectionalLight(0x00F0FF, 1.8);
  fillCyan.position.set(-8, 6, 4);
  scene.add(fillCyan);

  const crimsonRim = new THREE.DirectionalLight(0xEF4444, 2.2);
  crimsonRim.position.set(-6, 8, -6);
  scene.add(crimsonRim);

  const frontCamKey = new THREE.DirectionalLight(0xFFFFFF, 1.6);
  frontCamKey.position.set(2, 4, 7);
  scene.add(frontCamKey);

  // Rain-Slicked Stone Floor
  const floorGeo = new THREE.CylinderGeometry(16, 16, 0.4, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x090D18,
    roughness: 0.25,
    metalness: 0.5
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.position.set(0, -0.2, 0);
  scene.add(floor);

  // Reflective puddle
  const puddleGeo = new THREE.CircleGeometry(4.2, 32);
  puddleGeo.rotateX(-Math.PI / 2);
  const puddleMat = new THREE.MeshStandardMaterial({
    color: 0x050A14,
    roughness: 0.08,
    metalness: 0.85,
    transparent: true,
    opacity: 0.88
  });
  const puddle = new THREE.Mesh(puddleGeo, puddleMat);
  puddle.position.set(0, 0.01, 0);
  scene.add(puddle);

  // --------------------------------------------------------------------------
  // ASSET INSTANCES
  // --------------------------------------------------------------------------
  // 1. Composite Scene Group
  const compositeGroup = new THREE.Group();
  scene.add(compositeGroup);

  const compSkid = buildWetSkidTrail(4.5);
  compSkid.position.set(0, 0, 0);
  compositeGroup.add(compSkid);

  const compSlash = buildFrostfireCrescentWave(2.4);
  compSlash.position.set(0.3, 1.2, 0.1);
  compSlash.rotation.set(0.2, 0.3, -0.25);
  compositeGroup.add(compSlash);

  const compShatter = buildWoodShatterExplosion();
  compShatter.position.set(0.2, 1.15, 0.15);
  compositeGroup.add(compShatter);

  const compFrost = buildFrostbiteCrystals();
  compFrost.position.set(-0.8, 0.0, 0.3);
  compositeGroup.add(compFrost);

  const compHud = buildCriticalHealthBar();
  compHud.position.set(0.0, 2.5, 0.0);
  compHud.scale.set(0.85, 0.85, 0.85);
  compositeGroup.add(compHud);

  // 2. Standalone Slash Wave (View 02)
  const standSlash = buildFrostfireCrescentWave(2.5);
  standSlash.position.set(0, 1.4, 0);
  standSlash.rotation.set(0, 0.2, -0.15);
  scene.add(standSlash);

  // 3. Standalone Wood Shatter (View 03)
  const standShatter = buildWoodShatterExplosion();
  standShatter.position.set(0, 1.1, 0);
  scene.add(standShatter);

  // 4. Standalone Critical HUD (View 04)
  const standHud = buildCriticalHealthBar();
  standHud.position.set(0, 1.6, 0);
  scene.add(standHud);

  // 5. Standalone Skid & Frostbite (View 05)
  const standSkidGroup = new THREE.Group();
  const standSkid = buildWetSkidTrail(4.2);
  standSkidGroup.add(standSkid);
  const standFrost = buildFrostbiteCrystals();
  standFrost.position.set(-0.6, 0.0, 0.2);
  standSkidGroup.add(standFrost);
  scene.add(standSkidGroup);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    // Visibility toggle per mode
    compositeGroup.visible = (cfg.mode === 'composite');
    standSlash.visible = (cfg.mode === 'slash_wave');
    standShatter.visible = (cfg.mode === 'wood_shatter');
    standHud.visible = (cfg.mode === 'critical_hud');
    standSkidGroup.visible = (cfg.mode === 'skid_frost');

    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 350);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    renderer.render(scene, cam);

    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = 1280;
    angleCanvas.height = 760;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Overlay Badge
    actx.fillStyle = 'rgba(5, 8, 17, 0.85)';
    actx.fillRect(24, 24, 760, 68);
