// ============================================================================
// THE GLITCH MARKET — SHOT 4.5 MASTER PRODUCTION SCENE
// THE PRE-AWAKENING DUEL & BEATDOWN: "THE EXECUTION STAND-OFF"
//
// MILESTONE 5.5 MASTER KEYFRAME (1080x1920 Vertical 9:16)
//
// Produces:
// 1. shot4_5_keyframe_01.png (Official Vertical 9:16 Master Keyframe)
// 2. shot4_5_duel_master_sheet.png (2400x1350 Production Director Master Sheet)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import {
  buildClashScene1_TheShatter,
  buildClashScene2_ReflectionMacro,
