// ============================================================================
// THE GLITCH MARKET — SHADOW MONARCH AWAKENING RIG & SHADER VFX
// MILESTONE 6 // BATCH 1: CORRUPTED HERO RIG & SOVEREIGN SYSTEM HUD
//
// Assets:
// - C-01: Toby 10% Shadow Arm Rig (Liquid Void Core, Cyber-Claws & Coiling Tendrils)
// - C-02: Monarch Sovereign Awakening Face Decal (Laser Pupil Eye Flare & Smirk)
// - C-03: 10% Soul Corruption Sovereign System HUD ([SYSTEM OVERRIDE] & 10% Bar)
// ============================================================================

import * as THREE from 'three';
import { createBeveledBox, canvasTex } from './core/geo.js';
import {
  buildBaconHairMesh,
  createDenimJeansTexture
} from './toby_avatar.js';

// ----------------------------------------------------------------------------
// ASSET C-02: MONARCH SOVEREIGN AWAKENING FACE DECAL
// ----------------------------------------------------------------------------
export function createMonarchAwakenedFace() {
  return canvasTex('toby_monarch_awakened_face', 512, 512, (g, w, h) => {
    // Classic Roblox Yellow Base
    g.fillStyle = '#F8EE89';
    g.fillRect(0, 0, w, h);

    // Subtle battle grime smudges
    g.fillStyle = 'rgba(74, 48, 28, 0.18)';
    g.beginPath(); g.arc(110, 360, 44, 0, Math.PI * 2); g.fill();
    g.beginPath(); g.arc(390, 130, 32, 0, Math.PI * 2); g.fill();

    // White Gauze Bandage on left cheek
    g.fillStyle = '#FFFFFF';
    g.fillRect(305, 235, 62, 28);
    g.strokeStyle = '#D1D5DB';
    g.lineWidth = 2;
    g.strokeRect(305, 235, 62, 28);

    // Left Eyebrow: Resolute, focused, steady
    g.strokeStyle = '#3E2718';
    g.lineWidth = 14;
    g.lineCap = 'round';
    g.beginPath(); g.moveTo(295, 195); g.lineTo(210, 208); g.stroke();

    // Left Eye: Classic glassy anime eye (resolute and calm)
    const lx = 260, ly = 248;
    g.fillStyle = '#FFFFFF';
    g.beginPath(); g.arc(lx, ly, 38, 0, Math.PI * 2); g.fill();
    g.strokeStyle = '#1E1B18';
    g.lineWidth = 4;
    g.stroke();

    // Left Iris: Warm brown with specular reflection
    g.fillStyle = '#451A03';
    g.beginPath(); g.arc(lx, ly, 22, 0, Math.PI * 2); g.fill();
    g.fillStyle = '#0F0502';
    g.beginPath(); g.arc(lx, ly, 12, 0, Math.PI * 2); g.fill();
    g.fillStyle = '#FFFFFF';
    g.beginPath(); g.arc(lx - 7, ly - 8, 7, 0, Math.PI * 2); g.fill();

    // ------------------------------------------------------------------------
    // RIGHT EYE: THE AWAKENED SOVEREIGN'S EYE (CYAN & MONARCH PURPLE FLARE)
    // ------------------------------------------------------------------------
    const rx = 150, ry = 248;

    // Dark corruption fissure creeping down right temple towards eye
    g.strokeStyle = '#4C1D95';
    g.lineWidth = 5;
    g.beginPath();
    g.moveTo(110, 130);
    g.lineTo(135, 185);
    g.lineTo(145, 215);
    g.stroke();

    // Right Eyebrow: Aggressive sharp V-angle
    g.strokeStyle = '#1E1B18';
    g.lineWidth = 15;
    g.beginPath(); g.moveTo(95, 205); g.lineTo(185, 190); g.stroke();

    // Sclera: Tinted deep indigo shadow
    g.fillStyle = '#1E1035';
    g.beginPath(); g.arc(rx, ry, 38, 0, Math.PI * 2); g.fill();
    g.strokeStyle = '#6A0DAD';
    g.lineWidth = 5;
    g.stroke();

    // Iris: Radiant Electric Cyan (#00F0FF) with Monarch Violet Outer Ring
    g.fillStyle = '#7C3AED';
    g.beginPath(); g.arc(rx, ry, 26, 0, Math.PI * 2); g.fill();

    g.fillStyle = '#00F0FF';
    g.beginPath(); g.arc(rx, ry, 19, 0, Math.PI * 2); g.fill();

    // Needle-Sharp White Core Pupil
    g.fillStyle = '#FFFFFF';
    g.beginPath(); g.arc(rx, ry, 8, 0, Math.PI * 2); g.fill();

    // Sovereign Laser Eye Flare: Horizontal energy beam streaking to the right
    const flareGrad = g.createLinearGradient(rx, ry, 0, ry);
    flareGrad.addColorStop(0, 'rgba(0, 240, 255, 0.95)');
    flareGrad.addColorStop(0.35, 'rgba(168, 85, 247, 0.85)');
    flareGrad.addColorStop(1, 'rgba(106, 13, 173, 0.0)');
    g.fillStyle = flareGrad;
    g.beginPath();
    g.moveTo(rx, ry - 6);
    g.lineTo(0, ry - 14);
    g.lineTo(0, ry + 14);
    g.lineTo(rx, ry + 6);
    g.closePath();
    g.fill();

    // ------------------------------------------------------------------------
    // MOUTH: PREDATORY GRIM SMIRK (FEARLESS RESOLVE)
    // ------------------------------------------------------------------------
    g.fillStyle = '#18181B';
    g.beginPath();
    g.moveTo(180, 355);
    g.quadraticCurveTo(256, 340, 315, 362);
    g.quadraticCurveTo(256, 385, 180, 355);
    g.fill();

    // Clenched White Teeth
    g.fillStyle = '#FFFFFF';
    g.beginPath();
    g.moveTo(195, 354);
    g.quadraticCurveTo(256, 344, 305, 360);
    g.lineTo(298, 366);
    g.quadraticCurveTo(256, 352, 202, 360);
    g.closePath();
    g.fill();

    // Shattering Frostbite: Frost crystals turning into glowing purple glitch sparks
    g.fillStyle = '#A855F7';
    for (let i = 0; i < 8; i++) {
      const fx = 120 + Math.random() * 50;
      const fy = 300 + Math.random() * 40;
      g.fillRect(fx, fy, 4, 4);
    }
  }, [1, 1]);
}

// ----------------------------------------------------------------------------
// ASSET C-01: TOBY 10% SHADOW CORRUPTED RIGHT ARM & CLAWS
// ----------------------------------------------------------------------------

export function buildCorruptedRightArm() {
  const arm = new THREE.Group();
  arm.name = 'CorruptedShadowArm';

  // 1. Materials
  // Void Black Core Material (High-gloss wet liquid look)
  const matVoidCore = new THREE.MeshStandardMaterial({
    color: 0x050508,
    roughness: 0.08,
    metalness: 0.92
  });

  // Monarch Purple Plasma Rim Material (Additive glowing fringe)
  const matPlasmaFringe = new THREE.MeshBasicMaterial({
    color: 0x8B5CF6,
    transparent: true,
    opacity: 0.75,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide
  });

  // Electric Cyan Glitch Sparks Material
  const matCyanSparks = new THREE.MeshBasicMaterial({
    color: 0x00F0FF,
    transparent: true,
    opacity: 0.95,
    blending: THREE.AdditiveBlending
  });

  // Upper Arm Sleeve with Creeping Corruption Veins
  const sleeveTex = canvasTex('toby_sleeve_corruption', 256, 256, (g, w, h) => {
    // Upper teal hoodie section
    g.fillStyle = '#0F766E';
    g.fillRect(0, 0, w, 110);

    // Jagged fray hem
    g.fillStyle = '#050508';
    g.beginPath();
    g.moveTo(0, 110);
    for (let x = 0; x <= w; x += 20) {
      g.lineTo(x + 10, 95 + Math.random() * 30);
      g.lineTo(x + 20, 110);
    }
    g.lineTo(w, h);
    g.lineTo(0, h);
    g.closePath();
    g.fill();

    // Creeping Purple Fissures across the teal
    g.strokeStyle = '#A855F7';
    g.lineWidth = 3;
    g.beginPath();
    g.moveTo(35, 115); g.lineTo(55, 45); g.lineTo(80, 20);
    g.moveTo(140, 110); g.lineTo(165, 60); g.lineTo(150, 15);
    g.moveTo(210, 120); g.lineTo(225, 75);
    g.stroke();

    // Cyan Glitch Data Sparks
    g.fillStyle = '#00F0FF';
    for (let i = 0; i < 25; i++) {
      g.fillRect(Math.random() * w, 90 + Math.random() * 160, 3, 3);
    }
  }, [1, 1]);

  const matSleeveCorrupt = new THREE.MeshStandardMaterial({
    color: 0xFFFFFF,
    roughness: 0.5,
    metalness: 0.2,
    map: sleeveTex
  });

  // 2. Arm Geometry
  // Upper Arm Segment (Torn teal sleeve fading to black)
  const upperArmMesh = createBeveledBox(1.0, 1.05, 1.0, 0.04, 2, matSleeveCorrupt);
  upperArmMesh.position.set(0, -0.525, 0);
  arm.add(upperArmMesh);

  // Forearm Segment (Pure Obsidian Liquid Shadow Void)
  const forearmMesh = createBeveledBox(0.98, 1.05, 0.98, 0.035, 2, matVoidCore);
  forearmMesh.position.set(0, -1.45, 0);
  arm.add(forearmMesh);

  // 3. Cyber-Demonic Claws (5 Razor Obsidian Claws)
  const clawGroup = new THREE.Group();
  clawGroup.position.set(0, -1.98, 0);

  const clawMat = new THREE.MeshStandardMaterial({
    color: 0x0A0A10,
    roughness: 0.15,
    metalness: 0.95
  });

  // 4 Finger Claws along bottom face of fist
  [-0.32, -0.11, 0.11, 0.32].forEach((x, idx) => {
    const clawGeo = new THREE.ConeGeometry(0.048, 0.32 + (idx === 1 || idx === 2 ? 0.06 : 0), 4);
    const claw = new THREE.Mesh(clawGeo, clawMat);
    claw.position.set(x, -0.12, 0.15);
    claw.rotation.x = 0.45; // Curved claw forward
    claw.rotation.z = (x > 0 ? -0.1 : 0.1);
    clawGroup.add(claw);

    // Tip Data Spark
    const spark = new THREE.Mesh(new THREE.OctahedronGeometry(0.02), matCyanSparks);
    spark.position.set(x, -0.28, 0.22);
    clawGroup.add(spark);
  });

  // 1 Thumb Claw on the inside flank
  const thumbGeo = new THREE.ConeGeometry(0.048, 0.26, 4);
  const thumbClaw = new THREE.Mesh(thumbGeo, clawMat);
  thumbClaw.position.set(-0.46, -0.06, 0.0);
  thumbClaw.rotation.z = 0.65;
  thumbClaw.rotation.x = 0.35;
  clawGroup.add(thumbClaw);

  arm.add(clawGroup);

  // 4. 12 Coiling Liquid Shadow Tendril Ribbons
  for (let i = 0; i < 12; i++) {
    const angleStart = (i / 12) * Math.PI * 2;
    const heightProgress = (i / 12) * 1.5 - 1.8; // From wrist up towards elbow
    const r = 0.54 + Math.sin(i * 1.2) * 0.06;

    // Tendril core (black spline)
    const curve = new THREE.CubicBezierCurve3(
      new THREE.Vector3(Math.cos(angleStart) * r, heightProgress, Math.sin(angleStart) * r),
      new THREE.Vector3(Math.cos(angleStart + 0.8) * (r + 0.08), heightProgress + 0.25, Math.sin(angleStart + 0.8) * (r + 0.08)),
      new THREE.Vector3(Math.cos(angleStart + 1.4) * (r + 0.05), heightProgress + 0.45, Math.sin(angleStart + 1.4) * (r + 0.05)),
      new THREE.Vector3(Math.cos(angleStart + 2.0) * r, heightProgress + 0.65, Math.sin(angleStart + 2.0) * r)
    );
    const tubeGeo = new THREE.TubeGeometry(curve, 12, 0.028, 5, false);
    const tendril = new THREE.Mesh(tubeGeo, matVoidCore);
    arm.add(tendril);

    // Additive purple plasma outer glow envelope on tendril
    const glowTubeGeo = new THREE.TubeGeometry(curve, 12, 0.042, 5, false);
    const glowTendril = new THREE.Mesh(glowTubeGeo, matPlasmaFringe);
    arm.add(glowTendril);
  }

  // 5. Billowing Monarch Violet Flame Emitters (Along forearm)
  for (let f = 0; f < 6; f++) {
    const flameGeo = new THREE.ConeGeometry(0.065, 0.35, 4);
    const flame = new THREE.Mesh(flameGeo, matPlasmaFringe);
    const fAngle = (f / 6) * Math.PI * 2;
    flame.position.set(
      Math.cos(fAngle) * 0.52,
      -1.35 + (f % 3) * 0.25,
      Math.sin(fAngle) * 0.52
    );
    flame.rotation.set((Math.random() - 0.5) * 0.4, 0, (Math.random() - 0.5) * 0.4);
    arm.add(flame);
  }

  // 6. Dynamic Monarch Purple Arm Light Emitter
  const armLight = new THREE.PointLight(0xA855F7, 4.5, 6.0);
  armLight.position.set(0.1, -1.6, 0.3);
  arm.add(armLight);

  return arm;
}

// ----------------------------------------------------------------------------
// ASSET C-03: 10% SOUL CORRUPTION SOVEREIGN SYSTEM HUD
// ----------------------------------------------------------------------------

export function buildSovereignSystemHUD() {
  const hud = new THREE.Group();
  hud.name = 'SovereignSystemHUD';

  const hudTex = canvasTex('hud_sovereign_10pct', 640, 360, (g, w, h) => {
    // Deep obsidian translucent background
    g.fillStyle = 'rgba(7, 5, 15, 0.94)';
    g.fillRect(0, 0, w, h);

    // Regal Monarch Violet Frame
    g.strokeStyle = '#A855F7';
    g.lineWidth = 6;
    g.strokeRect(6, 6, w - 12, h - 12);

    // Inner subtle cyan hairline border
    g.strokeStyle = 'rgba(0, 240, 255, 0.45)';
    g.lineWidth = 1.5;
    g.strokeRect(12, 12, w - 24, h - 24);

    // Top Header Banner
    g.fillStyle = '#4C1D95';
    g.fillRect(16, 16, w - 32, 42);

    g.fillStyle = '#00F0FF';
    g.font = '900 18px monospace';
    g.textAlign = 'center';
    g.fillText('✦ SYSTEM OVERRIDE // MONARCH SOVEREIGN PROTOCOL ✦', w / 2, 43);

    // Host Identification
    g.textAlign = 'left';
    g.fillStyle = '#E2E8F0';
    g.font = 'bold 16px monospace';
    g.fillText('HOST: TOBY [CLASS: UNRANKED NOOB]', 28, 86);

    // Critical Vitals Warning
    g.fillStyle = '#EF4444';
    g.font = '900 16px monospace';
    g.fillText('VITALS: 0.01% [1 HP / 100 HP] // FATAL STRIKE OVERRIDDEN', 28, 114);

    // The Monarch's Whisper Quote
    g.fillStyle = '#C084FC';
    g.font = 'italic bold 15px monospace';
    g.fillText('"A Monarch does not kneel in the mud."', 28, 146);

    // ------------------------------------------------------------------------
    // SOUL CORRUPTION PROGRESS GAUGE (10.0% COMPLETED)
    // ------------------------------------------------------------------------
    g.fillStyle = '#94A3B8';
    g.font = 'bold 15px monospace';
    g.fillText('SOUL CORRUPTION TOLERANCE: [10.0% COMPLETED]', 28, 182);

    // Progress Bar Frame
    const barX = 28, barY = 196, barW = w - 56, barH = 26;
    g.strokeStyle = '#6D28D9';
    g.lineWidth = 3;
    g.strokeRect(barX, barY, barW, barH);

    g.fillStyle = '#1E1035';
    g.fillRect(barX + 2, barY + 2, barW - 4, barH - 4);

    // 10% Active Fill (Electric Violet & Cyan Gradient)
    const fillW = (barW - 4) * 0.10;
    const fillGrad = g.createLinearGradient(barX, barY, barX + fillW, barY);
    fillGrad.addColorStop(0, '#6A0DAD');
    fillGrad.addColorStop(0.7, '#A855F7');
    fillGrad.addColorStop(1, '#00F0FF');
    g.fillStyle = fillGrad;
    g.fillRect(barX + 2, barY + 2, fillW, barH - 4);

    // Stage 1 Unlocked Skill
    g.fillStyle = '#00F0FF';
    g.font = 'bold 15px monospace';
    g.fillText('STAGE 1 ACTIVE: "MONARCH\'S GRIP" (UNARMED BLADE CATCH)', 28, 252);

    g.fillStyle = '#94A3B8';
    g.font = '13px monospace';
    g.fillText('Right forearm & hand infused with living liquid shadow.', 28, 276);

    // Acceptance Button
    g.fillStyle = '#581C87';
    g.fillRect(28, 296, w - 56, 42);
    g.strokeStyle = '#00F0FF';
    g.lineWidth = 2;
    g.strokeRect(28, 296, w - 56, 42);

    g.fillStyle = '#FFFFFF';
    g.font = '900 17px monospace';
    g.textAlign = 'center';
    g.fillText('>>> SOVEREIGN AUTHORITY: ACCEPTED (HOST ENGAGED) <<<', w / 2, 323);
  }, [1, 1]);

  const cardGeo = new THREE.PlaneGeometry(2.6, 1.45);
  const cardMat = new THREE.MeshBasicMaterial({
    map: hudTex,
    transparent: true,
    opacity: 0.95,
    side: THREE.DoubleSide,
    depthWrite: false
  });
  const cardMesh = new THREE.Mesh(cardGeo, cardMat);
  hud.add(cardMesh);

  // Outer Tech HUD Corner Brackets in Royal Violet (#A855F7)
  const cornerMat = new THREE.MeshBasicMaterial({
    color: 0xA855F7,
    transparent: true,
    opacity: 0.95,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending
  });
  const wHalf = 1.35;
  const hHalf = 0.76;
  const cLen = 0.32;
  const cThick = 0.035;

  const corners = [
    [-wHalf, hHalf, 1, -1],
    [wHalf, hHalf, -1, -1],
    [-wHalf, -hHalf, 1, 1],
    [wHalf, -hHalf, -1, 1],
  ];

  corners.forEach(([cx, cy, dx, dy]) => {
    const hMesh = new THREE.Mesh(new THREE.PlaneGeometry(cLen, cThick), cornerMat);
    hMesh.position.set(cx + (dx * cLen) / 2, cy, 0.01);
    hud.add(hMesh);
    const vMesh = new THREE.Mesh(new THREE.PlaneGeometry(cThick, cLen), cornerMat);
    vMesh.position.set(cx, cy + (dy * cLen) / 2, 0.01);
    hud.add(vMesh);
  });

  return hud;
}

// ----------------------------------------------------------------------------
// FULL TOBY 10% MONARCH AWAKENED COMBAT RIG
// ----------------------------------------------------------------------------

export function buildTobyMonarchRig(options = {}) {
  const root = new THREE.Group();
  root.name = 'Toby_Monarch_Awakened_Rig';

  const matSkin = new THREE.MeshStandardMaterial({
    color: 0xF8EE89,
    roughness: 0.55,
    metalness: 0.08
  });

  // Tattered Hoodie Material with Right Side Corruption
  const hoodieTex = canvasTex('toby_hoodie_corrupted', 512, 512, (g, w, h) => {
    // Teal Base
    g.fillStyle = '#0F766E';
    g.fillRect(0, 0, w, h);

    // Fabric Rib Grain
    g.fillStyle = 'rgba(13, 148, 136, 0.35)';
    for (let y = 0; y < h; y += 4) {
      g.fillRect(0, y, w, 2);
    }

    // White Drawstrings
    g.strokeStyle = '#FFFFFF';
    g.lineWidth = 6;
    g.beginPath(); g.moveTo(220, 20); g.lineTo(220, 160); g.stroke();
