export function buildGroundShadowVortex(radius = 3.2) {
  const vortex = new THREE.Group();
  vortex.name = 'GroundShadowVortex';

  // 1. Swirling Liquid Void Base Texture
  const vortexTex = canvasTex('tex_shadow_vortex', 512, 512, (g, w, h) => {
    // Pitch black liquid base
    g.fillStyle = '#020205';
    g.fillRect(0, 0, w, h);

    // Concentric swirling purple & cyan energy spirals
    const cx = w / 2, cy = h / 2;
    for (let r = 240; r > 10; r -= 15) {
      g.strokeStyle = (r % 30 === 0) ? 'rgba(168, 85, 247, 0.45)' : 'rgba(0, 240, 255, 0.25)';
      g.lineWidth = 6;
      g.beginPath();
      for (let theta = 0; theta < Math.PI * 4; theta += 0.1) {
        const rad = (r / (Math.PI * 4)) * theta;
        const x = cx + Math.cos(theta + r * 0.1) * rad;
        const y = cy + Math.sin(theta + r * 0.1) * rad;
        if (theta === 0) g.moveTo(x, y);
        else g.lineTo(x, y);
      }
      g.stroke();
    }

    // Outer Void Mist Vignette
    const grad = g.createRadialGradient(cx, cy, 60, cx, cy, 250);
    grad.addColorStop(0, 'rgba(2, 2, 5, 0.0)');
    grad.addColorStop(0.7, 'rgba(5, 3, 10, 0.6)');
    grad.addColorStop(1, 'rgba(106, 13, 173, 0.85)');
    g.fillStyle = grad;
    g.beginPath(); g.arc(cx, cy, 256, 0, Math.PI * 2); g.fill();
  }, [1, 1]);

  const discGeo = new THREE.CircleGeometry(radius, 48);
  discGeo.rotateX(-Math.PI / 2);
  const discMat = new THREE.MeshStandardMaterial({
    map: vortexTex,
    roughness: 0.06, // ultra-glossy liquid reflection
    metalness: 0.95,
    transparent: true,
    opacity: 0.95
  });
  const disc = new THREE.Mesh(discGeo, discMat);
  disc.position.set(0, 0.015, 0);
  vortex.add(disc);

  // Outer Blooming Royal Violet Energy Ring
  const ringGeo = new THREE.RingGeometry(radius - 0.25, radius + 0.15, 48);
  ringGeo.rotateX(-Math.PI / 2);
  const ringMat = new THREE.MeshBasicMaterial({
    color: 0x8B5CF6,
    transparent: true,
    opacity: 0.8,
    side: THREE.DoubleSide,
    blending: THREE.AdditiveBlending
  });
  const ring = new THREE.Mesh(ringGeo, ringMat);
  ring.position.set(0, 0.02, 0);
  vortex.add(ring);

  // 2. 24 Bubbling Liquid Shadow Droplets Erupting Upward
  const bubbleMat = new THREE.MeshStandardMaterial({
    color: 0x07050E,
    roughness: 0.1,
    metalness: 0.95
  });

  for (let i = 0; i < 24; i++) {
    const bubbleGeo = new THREE.DodecahedronGeometry(0.04 + Math.random() * 0.05);
    const bubble = new THREE.Mesh(bubbleGeo, bubbleMat);
    const angle = (i / 24) * Math.PI * 2;
    const r = 0.4 + Math.random() * (radius * 0.7);
    bubble.position.set(
      Math.cos(angle) * r,
      0.04 + Math.random() * 0.35,
      Math.sin(angle) * r
    );
    vortex.add(bubble);
  }

  return vortex;
}

// ----------------------------------------------------------------------------
// ASSET VFX-07: 12-RIBBON COILING LIQUID TENDRIL SHADER MESH
// ----------------------------------------------------------------------------

export function buildEruptingShadowTendrils(height = 2.4) {
  const tendrilGroup = new THREE.Group();
  tendrilGroup.name = 'EruptingShadowTendrils';

  const matVoidCore = new THREE.MeshStandardMaterial({
    color: 0x050508,
    roughness: 0.08,
    metalness: 0.94
  });

  const matPlasmaFringe = new THREE.MeshBasicMaterial({
    color: 0x8B5CF6,
    transparent: true,
    opacity: 0.75,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide
  });

  const matCyanSparks = new THREE.MeshBasicMaterial({
    color: 0x00F0FF,
    transparent: true,
    opacity: 0.95,
    blending: THREE.AdditiveBlending
  });

  // 12 3D Spiral Spline Tendril Tubes
  for (let i = 0; i < 12; i++) {
    const baseAngle = (i / 12) * Math.PI * 2;
    const baseRadius = 0.35 + (i % 3) * 0.25;

    // Cubic Bézier Spline twisting upward and converging toward Toby's arm
    const p0 = new THREE.Vector3(Math.cos(baseAngle) * baseRadius, 0.02, Math.sin(baseAngle) * baseRadius);
    const p1 = new THREE.Vector3(Math.cos(baseAngle + 0.9) * (baseRadius * 1.3), height * 0.3, Math.sin(baseAngle + 0.9) * (baseRadius * 1.3));
    const p2 = new THREE.Vector3(Math.cos(baseAngle + 1.8) * (baseRadius * 0.8), height * 0.65, Math.sin(baseAngle + 1.8) * (baseRadius * 0.8));
    const p3 = new THREE.Vector3(Math.cos(baseAngle + 2.7) * 0.35, height * 0.95, Math.sin(baseAngle + 2.7) * 0.35);

    const curve = new THREE.CubicBezierCurve3(p0, p1, p2, p3);

    // Inner Liquid Void Core Tube
    const coreGeo = new THREE.TubeGeometry(curve, 20, 0.038, 6, false);
    const coreMesh = new THREE.Mesh(coreGeo, matVoidCore);
    tendrilGroup.add(coreMesh);

    // Outer Additive Royal Violet Plasma Fringe Envelope
    const fringeGeo = new THREE.TubeGeometry(curve, 20, 0.058, 6, false);
    const fringeMesh = new THREE.Mesh(fringeGeo, matPlasmaFringe);
    tendrilGroup.add(fringeMesh);

    // Cyan Glitch Data Sparks along the tendril crest
    for (let s = 1; s <= 3; s++) {
      const pt = curve.getPoint(s * 0.28);
      const spark = new THREE.Mesh(new THREE.BoxGeometry(0.025, 0.025, 0.025), matCyanSparks);
      spark.position.copy(pt);
      spark.position.x += (Math.random() - 0.5) * 0.04;
      spark.position.z += (Math.random() - 0.5) * 0.04;
      tendrilGroup.add(spark);
    }
  }

  return tendrilGroup;
}

// ----------------------------------------------------------------------------
// ASSET VFX-08: BILLOWING MONARCH PURPLE FLAMES & EMBERS
// ----------------------------------------------------------------------------

export function buildMonarchFlameAura(height = 2.5) {
  const aura = new THREE.Group();
  aura.name = 'MonarchFlameAura';

  const matFlameViolet = new THREE.MeshBasicMaterial({
    color: 0x8B5CF6,
    transparent: true,
    opacity: 0.7,
    blending: THREE.AdditiveBlending
  });

  const matFlameDeepPurple = new THREE.MeshBasicMaterial({
    color: 0x6A0DAD,
    transparent: true,
    opacity: 0.85,
    blending: THREE.AdditiveBlending
  });

  const matCyanCore = new THREE.MeshBasicMaterial({
    color: 0x00F0FF,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending
  });

  // 1. 16 Rising Flame Tongues
  for (let f = 0; f < 16; f++) {
    const fAngle = (f / 16) * Math.PI * 2;
    const fRadius = 0.45 + (f % 4) * 0.18;
    const fHeight = 0.65 + (f % 3) * 0.45;

    const flameGeo = new THREE.ConeGeometry(0.09, fHeight, 4);
    const flameMesh = new THREE.Mesh(flameGeo, (f % 2 === 0) ? matFlameViolet : matFlameDeepPurple);
    flameMesh.position.set(
      Math.cos(fAngle) * fRadius,
      fHeight * 0.45,
      Math.sin(fAngle) * fRadius
    );
    flameMesh.rotation.set((Math.random() - 0.5) * 0.35, 0, (Math.random() - 0.5) * 0.35);
    aura.add(flameMesh);
  }

  // 2. 24 Floating Void Embers Drifting Upward
  const emberMat = new THREE.MeshBasicMaterial({
    color: 0xA855F7,
    transparent: true,
    opacity: 0.9,
    blending: THREE.AdditiveBlending
  });

  for (let e = 0; e < 24; e++) {
    const ember = new THREE.Mesh(new THREE.OctahedronGeometry(0.035), (e % 4 === 0) ? matCyanCore : emberMat);
    const eAngle = (e / 24) * Math.PI * 2;
    const er = 0.2 + Math.random() * 1.2;
    ember.position.set(
      Math.cos(eAngle) * er,
      0.3 + Math.random() * (height * 0.9),
      Math.sin(eAngle) * er
    );
    aura.add(ember);
  }

  // Dynamic Monarch Violet Point Light
  const auraLight = new THREE.PointLight(0x8B5CF6, 5.0, 9.0);
  auraLight.position.set(0, 1.2, 0);
  aura.add(auraLight);

  return aura;
}

// ----------------------------------------------------------------------------
// ASSET VFX-09: TIME-FREEZE SUSPENDED RAINDROPS (35 GLASS SPHERES)
// ----------------------------------------------------------------------------

export function buildSuspendedRaindrops(count = 35) {
  const dropsGroup = new THREE.Group();
  dropsGroup.name = 'SuspendedRaindrops';

  const dropMat = new THREE.MeshStandardMaterial({
    color: 0xE0F2FE,
    roughness: 0.05,
    metalness: 0.92,
    transparent: true,
    opacity: 0.85
  });

  // Additive specular rim
  const rimMat = new THREE.MeshBasicMaterial({
    color: 0x38BDF8,
    transparent: true,
    opacity: 0.65,
    blending: THREE.AdditiveBlending
  });

  for (let i = 0; i < count; i++) {
    const drop = new THREE.Group();

    // Elongated droplet geometry
    const coreMesh = new THREE.Mesh(new THREE.SphereGeometry(0.042, 8, 8), dropMat);
    coreMesh.scale.set(1.0, 1.5, 1.0);
    drop.add(coreMesh);

    // Inner bright refraction highlight
    const highlight = new THREE.Mesh(new THREE.SphereGeometry(0.02, 6, 6), rimMat);
    highlight.position.set(0.015, 0.02, 0.015);
    drop.add(highlight);

    // Scattered in the 3D volume around Toby and Chad
    drop.position.set(
      (Math.random() - 0.5) * 5.5,
      0.4 + Math.random() * 3.8,
      (Math.random() - 0.5) * 4.5
    );
    dropsGroup.add(drop);
  }

  return dropsGroup;
}

