// ============================================================================
// THE GLITCH MARKET — AWAKENING CLIMAX SCENES & KEYFRAME CLASHES
// MILESTONE 6 // BATCH 3: DYNAMIC AWAKENING CLASHES (CLASH-01 THROUGH CLASH-03)
//
// Scenes:
// - Scene 1: The Time-Freeze & Sovereign System Alert (Chad frozen 2" from throat)
// - Scene 2: The Symbiote Infusion Finger Macro (Liquid shadow creeping onto fingers)
// - Scene 3: The Barehanded Blade Catch (Obsidian claw catching golden rapier)
// ============================================================================

import * as THREE from 'three';
import { createBeveledBox, canvasTex } from './core/geo.js';
import {
  buildTobyMonarchRig,
  buildSovereignSystemHUD,
  buildCorruptedRightArm,
  createMonarchAwakenedFace
} from './shadow_combatant.js';
import {
  buildChadCombatRig,
  buildTobyCombatRig,
  buildActiveFrostfireRapier
} from './duel_combatants.js';
import {
  buildGroundShadowVortex,
  buildEruptingShadowTendrils,
  buildMonarchFlameAura,
  buildSuspendedRaindrops
} from './shadow_effects.js';
import {
  buildCriticalHealthBar,
  buildWetSkidTrail
} from './duel_effects.js';
import {
  buildColosseumCurbEnvironment
} from './shot4_environment.js';

// ----------------------------------------------------------------------------
// HELPER: Extinguished Blade Smoke & Quench Particles
// ----------------------------------------------------------------------------
export function buildBladeQuenchVFX() {
  const quenchGroup = new THREE.Group();
  quenchGroup.name = 'BladeQuenchVFX';

  // 1. Quenched Black & Deep Purple Smoke Billows
  const matSmokePurple = new THREE.MeshBasicMaterial({
    color: 0x4C1D95,
    transparent: true,
    opacity: 0.7,
    blending: THREE.AdditiveBlending
  });

  const matSmokeVoid = new THREE.MeshStandardMaterial({
    color: 0x050508,
    roughness: 0.3,
    metalness: 0.8,
    transparent: true,
    opacity: 0.85
  });

  const smokePositions = [
    [0.0, 0.05, 0.0, 0.12],
    [0.06, 0.14, 0.04, 0.16],
    [-0.05, 0.22, -0.03, 0.2],
    [0.08, 0.32, 0.02, 0.24],
    [-0.04, 0.42, 0.05, 0.28],
    [0.05, 0.54, -0.04, 0.32]
  ];

  smokePositions.forEach(([x, y, z, r], idx) => {
    const geo = new THREE.DodecahedronGeometry(r, 1);
    const mesh = new THREE.Mesh(geo, idx % 2 === 0 ? matSmokePurple : matSmokeVoid);
    mesh.position.set(x, y, z);
    quenchGroup.add(mesh);
  });

  // 2. Radial Cyan & Monarch Purple Pinch Sparks (Contact Singularity)
  const matCyanSpark = new THREE.MeshBasicMaterial({
    color: 0x00F0FF,
    transparent: true,
    opacity: 0.95,
    blending: THREE.AdditiveBlending
  });

  const matVioletSpark = new THREE.MeshBasicMaterial({
    color: 0xC084FC,
    transparent: true,
    opacity: 0.95,
    blending: THREE.AdditiveBlending
  });

  for (let i = 0; i < 24; i++) {
    const angle = (i / 24) * Math.PI * 2;
    const dist = 0.08 + Math.random() * 0.28;
    const sparkGeo = new THREE.BoxGeometry(0.025, 0.025, 0.025);
    const spark = new THREE.Mesh(sparkGeo, i % 2 === 0 ? matCyanSpark : matVioletSpark);
    spark.position.set(
      Math.cos(angle) * dist,
      (Math.random() - 0.5) * 0.18,
      Math.sin(angle) * dist
    );
    quenchGroup.add(spark);
  }

  // Intense Contact Flash PointLight
  const flashLight = new THREE.PointLight(0x8B5CF6, 8.0, 6.0);
  flashLight.position.set(0, 0.1, 0);
  quenchGroup.add(flashLight);

  return quenchGroup;
}

// ----------------------------------------------------------------------------
// SCENE 1: THE TIME-FREEZE & SOVEREIGN SYSTEM ALERT
// ----------------------------------------------------------------------------
export function buildClashScene1_TimeFreeze() {
  const sceneGroup = new THREE.Group();
  sceneGroup.name = 'ClashScene1_TimeFreeze';

  // 1. Street Environment & Arena Gate
  const env = buildColosseumCurbEnvironment();
  sceneGroup.add(env);

  // 2. Toby pinned against the gate in desperate shock pose
  const toby = buildTobyCombatRig({ pose: 'gate_recoil', expression: 'shock' });
  toby.position.set(-0.75, 0, -3.2);
  toby.rotation.y = Math.PI / 2; // Facing +X towards Chad
  sceneGroup.add(toby);

  // Critical HP Alert floating above Toby
  const critHp = buildCriticalHealthBar(1);
  critHp.position.set(-0.75, 3.4, -3.2);
  sceneGroup.add(critHp);

  // 3. Chad in full fencing lunge attack drive (thrusting left toward Toby)
  const chad = buildChadCombatRig({ pose: 'lunge_slash' });
  chad.position.set(1.45, 0, -3.15);
  chad.rotation.y = -Math.PI / 2; // Facing -X towards Toby
  sceneGroup.add(chad);

  // 4. Time-Freeze Suspended Glass Raindrops (40 spheres caught mid-air)
  const suspendedRain = buildSuspendedRaindrops(40);
  suspendedRain.position.set(0.3, 0, -3.1);
  sceneGroup.add(suspendedRain);

  // 5. Emerging Shadow Vortex forming beneath Toby's feet
  const nascentVortex = buildGroundShadowVortex(2.0);
  nascentVortex.position.set(-0.75, 0.01, -3.2);
  sceneGroup.add(nascentVortex);

  // 6. Diegetic Sovereign System HUD Card flashing override right in the center
  const hud = buildSovereignSystemHUD();
  hud.position.set(0.25, 2.5, -2.1);
  hud.rotation.y = -0.15;
  hud.scale.set(0.85, 0.85, 0.85);
  sceneGroup.add(hud);

  // Emergency violet override illumination
  const overrideLight = new THREE.PointLight(0x8B5CF6, 5.0, 8.0);
  overrideLight.position.set(0.25, 2.5, -1.8);
  sceneGroup.add(overrideLight);

  return sceneGroup;
}

// ----------------------------------------------------------------------------
// SCENE 2: THE SYMBIOTE INFUSION FINGER MACRO
// ----------------------------------------------------------------------------
export function buildClashScene2_SymbioteInfusionMacro() {
  const sceneGroup = new THREE.Group();
  sceneGroup.name = 'ClashScene2_SymbioteInfusionMacro';

  // 1. Wet Cobblestone Floor Pedestal
  const floorGeo = new THREE.CylinderGeometry(8, 8, 0.3, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x090D18,
    roughness: 0.22,
    metalness: 0.55
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.position.set(0, -0.15, 0);
  sceneGroup.add(floor);

  // Swirling Void Vortex beneath the hand
  const puddle = buildGroundShadowVortex(2.2);
  puddle.position.set(0, 0.01, 0);
  sceneGroup.add(puddle);

  // 2. High-Detail Forearm & Hand mutating on the floor
  const handGroup = new THREE.Group();
  handGroup.name = 'MutatingHandGroup';
  handGroup.position.set(0, 0.15, 0);

  // Tattered Teal Sleeve transitioning to torn black shreds
  const matTeal = new THREE.MeshStandardMaterial({
    color: 0x0F766E,
    roughness: 0.8,
    metalness: 0.05
  });
  const sleeve = createBeveledBox(0.9, 0.6, 0.9, 0.03, 2, matTeal);
  sleeve.position.set(-0.7, 0.25, 0);
  sleeve.rotation.z = Math.PI / 2;
  handGroup.add(sleeve);

  // Arm Void Core Block
  const matVoidCore = new THREE.MeshStandardMaterial({
    color: 0x050508,
    roughness: 0.08,
    metalness: 0.94
  });
  const palm = createBeveledBox(0.85, 0.5, 0.85, 0.03, 2, matVoidCore);
  palm.position.set(0.0, 0.25, 0);
  palm.rotation.z = Math.PI / 2;
  handGroup.add(palm);

  // 5 Razor Obsidian Claws curling outward
  const matClaw = new THREE.MeshStandardMaterial({
    color: 0x020204,
    metalness: 0.98,
    roughness: 0.04
  });
  const matCyanTip = new THREE.MeshBasicMaterial({
    color: 0x00F0FF,
    transparent: true,
    opacity: 0.95,
    blending: THREE.AdditiveBlending
  });

  for (let f = 0; f < 5; f++) {
    const finger = new THREE.Group();
    const fZ = -0.3 + f * 0.15;

    // Claw segment
    const clawGeo = new THREE.ConeGeometry(0.055, 0.38, 4);
    clawGeo.rotateX(Math.PI / 2);
    const claw = new THREE.Mesh(clawGeo, matClaw);
    claw.position.set(0.55, 0.24, fZ);
    claw.rotation.y = 0.2 - f * 0.1;
    finger.add(claw);

    // Cyan spark tip
    const tip = new THREE.Mesh(new THREE.BoxGeometry(0.03, 0.03, 0.03), matCyanTip);
    tip.position.set(0.74, 0.24, fZ);
    finger.add(tip);

    handGroup.add(finger);
  }

  // 3. Symbiote Micro-Tendrils winding around fingers
  const matPlasmaFringe = new THREE.MeshBasicMaterial({
    color: 0x8B5CF6,
    transparent: true,
    opacity: 0.8,
    blending: THREE.AdditiveBlending,
    side: THREE.DoubleSide
  });

  for (let t = 0; t < 8; t++) {
    const tAngle = (t / 8) * Math.PI * 2;
    const p0 = new THREE.Vector3(Math.cos(tAngle) * 0.7, 0.02, Math.sin(tAngle) * 0.7);
    const p1 = new THREE.Vector3(Math.cos(tAngle + 0.8) * 0.5, 0.15, Math.sin(tAngle + 0.8) * 0.5);
    const p2 = new THREE.Vector3(0.2 + (t % 3) * 0.1, 0.28, -0.25 + (t % 4) * 0.15);
    const curve = new THREE.QuadraticBezierCurve3(p0, p1, p2);
    const tendril = new THREE.Mesh(new THREE.TubeGeometry(curve, 12, 0.025, 6, false), matPlasmaFringe);
    handGroup.add(tendril);
  }

  // 4. Rising Violet Flame Tongues off the knuckles
  for (let fl = 0; fl < 6; fl++) {
    const flameGeo = new THREE.ConeGeometry(0.07, 0.32 + (fl % 3) * 0.15, 4);
    const flame = new THREE.Mesh(flameGeo, matPlasmaFringe);
    flame.position.set(0.35 + (fl % 2) * 0.15, 0.45, -0.25 + fl * 0.1);
    flame.rotation.set((Math.random() - 0.5) * 0.2, 0, (Math.random() - 0.5) * 0.2);
    handGroup.add(flame);
  }

  sceneGroup.add(handGroup);

  // 5. Floating Mini Infusion HUD Badge
  const miniBadgeTex = canvasTex('mini_infusion_badge', 512, 160, (g, w, h) => {
    g.fillStyle = 'rgba(7, 13, 27, 0.92)';
    g.fillRect(0, 0, w, h);
    g.strokeStyle = '#00F0FF';
    g.lineWidth = 4;
    g.strokeRect(4, 4, w - 8, h - 8);

    g.fillStyle = '#00F0FF';
    g.font = 'bold 22px monospace';
    g.fillText('SOUL CORRUPTION: 10.0% COMPLETED', 20, 48);

    g.fillStyle = '#C084FC';
    g.font = 'bold 18px monospace';
    g.fillText('MONARCH\'S GRIP // RIGHT ARM ACTIVE', 20, 85);

    // Progress Bar
    g.fillStyle = '#1E1035';
    g.fillRect(20, 105, w - 40, 22);
    const grad = g.createLinearGradient(20, 105, 120, 105);
    grad.addColorStop(0, '#6A0DAD');
    grad.addColorStop(1, '#00F0FF');
    g.fillStyle = grad;
    g.fillRect(20, 105, (w - 40) * 0.1, 22);
  }, [1, 1]);

  const miniCard = new THREE.Mesh(
    new THREE.PlaneGeometry(1.4, 0.45),
    new THREE.MeshBasicMaterial({ map: miniBadgeTex, transparent: true, side: THREE.DoubleSide })
  );
  miniCard.position.set(0.1, 0.85, 0.35);
  miniCard.rotation.x = -0.45;
  sceneGroup.add(miniCard);

  // Dynamic hand light
  const handLight = new THREE.PointLight(0x8B5CF6, 6.0, 4.0);
  handLight.position.set(0.3, 0.6, 0.2);
  sceneGroup.add(handLight);

  return sceneGroup;
}

