  floor.position.set(0, -0.2, 0);
  sceneGroup.add(floor);

  // 2. Swirling Ground Shadow Vortex (3.4m radius)
  const shadowVortex = buildGroundShadowVortex(3.4);
  sceneGroup.add(shadowVortex);

  // 3. Churned Mud Skid Trail beneath the clash
  const skid = buildWetSkidTrail(5.5);
  skid.position.set(0.2, 0, 0.0);
