  // 4. TOBY 10% MONARCH AWAKENED HERO RIG (IN UPRIGHT BLADE CATCH STANCE)
  const toby = buildTobyMonarchRig({ pose: 'blade_catch', includeHUD: false });
  toby.position.set(-1.25, 0, 0.0);
  toby.rotation.y = Math.PI / 2; // Facing +X towards Chad
  sceneGroup.add(toby);

  // 5. CHAD_ROBUX IN FULL LUNGE ATTACK (THRUSTING FORWARD TOWARDS TOBY)
  const chad = buildChadCombatRig({ pose: 'lunge_slash' });
  chad.position.set(1.65, 0, 0.0);
  chad.rotation.y = -Math.PI / 2; // Facing -X towards Toby
  sceneGroup.add(chad);

  // 6. CONTACT SINGULARITY: The precise point where claws grip the golden rapier blade!
  // In world space, Toby's hand meets Chad's blade at x = 0.15, y = 1.85, z = 0.05
  const catchPoint = new THREE.Vector3(0.15, 1.85, 0.05);

  const quenchVFX = buildBladeQuenchVFX();
  quenchVFX.position.copy(catchPoint);
  sceneGroup.add(quenchVFX);

  // 7. Erupting 12-Ribbon Coiling Shadow Tendrils surging around Toby
  const tendrils = buildEruptingShadowTendrils(2.4);
  tendrils.position.set(-1.25, 0, 0.0);
  sceneGroup.add(tendrils);

  // 8. Billowing Monarch Purple Flames & Void Embers around Toby
  const flames = buildMonarchFlameAura(2.5);
  flames.position.set(-1.25, 0, 0.0);
  sceneGroup.add(flames);

  // 9. Time-Freeze Suspended Glass Raindrops (40 spheres caught mid-air)
  const suspendedRain = buildSuspendedRaindrops(40);
  suspendedRain.position.set(0.2, 0, 0.0);
  sceneGroup.add(suspendedRain);

  // 10. Diegetic Sovereign System HUD floating proudly above Toby's shoulder
  const hud = buildSovereignSystemHUD();
  hud.position.set(-0.85, 3.4, 1.15);
  hud.rotation.y = 0.22;
  hud.scale.set(0.9, 0.9, 0.9);
  sceneGroup.add(hud);

  // Opposing Dual Lighting: Warm golden glow behind Chad, Deep violet/cyan behind Toby
  const chadSunfireGlow = new THREE.PointLight(0xF59E0B, 3.5, 7.0);
  chadSunfireGlow.position.set(2.4, 2.5, 0.5);
  sceneGroup.add(chadSunfireGlow);

  const tobyMonarchGlow = new THREE.PointLight(0x8B5CF6, 7.0, 9.0);
  tobyMonarchGlow.position.set(-1.8, 2.2, 0.4);
  sceneGroup.add(tobyMonarchGlow);

  return sceneGroup;
}

