  chadSunfireGlow.position.set(2.4, 2.5, 0.8);
  sceneGroup.add(chadSunfireGlow);

  const tobyMonarchGlow = new THREE.PointLight(0x8B5CF6, 7.0, 9.0);
  tobyMonarchGlow.position.set(-1.8, 2.2, 0.4);
  sceneGroup.add(tobyMonarchGlow);

  return sceneGroup;
}

