// SCENE 1: THE TIME-FREEZE & SOVEREIGN SYSTEM ALERT
// ----------------------------------------------------------------------------
export function buildClashScene1_TimeFreeze() {
  const sceneGroup = new THREE.Group();
  sceneGroup.name = 'ClashScene1_TimeFreeze';

  // 1. Street Environment & Arena Gate
  const env = buildArenaCurbEnvironment();
  sceneGroup.add(env);

  // 2. Toby pinned against the gate in desperate shock pose
  const toby = buildTobyCombatRig({ pose: 'gate_recoil', expression: 'shock' });
  toby.position.set(-1.1, 0, -3.2);
  toby.rotation.y = 1.25; // Angled towards Chad and camera
  sceneGroup.add(toby);

  // Critical HP Alert floating above Toby
  const critHp = buildCriticalHealthBar(1);
  critHp.position.set(-1.1, 3.4, -3.2);
  sceneGroup.add(critHp);

  // 3. Chad in full fencing lunge attack drive (thrusting left toward Toby)
  const chad = buildChadCombatRig({ pose: 'lunge_slash' });
  chad.position.set(1.3, 0, -3.0);
  chad.rotation.y = -1.85; // Angled towards Toby and camera
  sceneGroup.add(chad);

  // 4. Time-Freeze Suspended Glass Raindrops (40 spheres caught mid-air)
  const suspendedRain = buildSuspendedRaindrops(40);
  suspendedRain.position.set(0.0, 0, -3.1);
  sceneGroup.add(suspendedRain);

  // 5. Emerging Shadow Vortex forming beneath Toby's feet
  const nascentVortex = buildGroundShadowVortex(2.0);
  nascentVortex.position.set(-1.1, 0.01, -3.2);
  sceneGroup.add(nascentVortex);

  // 6. Diegetic Sovereign System HUD Card flashing override right in the center
  const hud = buildSovereignSystemHUD();
  hud.position.set(0.0, 2.7, -2.4);
  hud.rotation.y = 0.0;
  hud.scale.set(0.8, 0.8, 0.8);
  sceneGroup.add(hud);

  // Emergency violet override illumination
  const overrideLight = new THREE.PointLight(0x8B5CF6, 4.5, 7.0);
  overrideLight.position.set(0.0, 2.7, -2.1);
  sceneGroup.add(overrideLight);

  return sceneGroup;
}

