export function buildClashScene3_BladeCatchClimax() {
  const sceneGroup = new THREE.Group();
  sceneGroup.name = 'ClashScene3_BladeCatchClimax';

  // 1. Wet Cobblestone Floor Pedestal
  const floorGeo = new THREE.CylinderGeometry(14, 14, 0.4, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x090D18,
    roughness: 0.25,
    metalness: 0.5
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.position.set(0, -0.2, 0);
  sceneGroup.add(floor);

  // 2. Swirling Ground Shadow Vortex (3.4m radius)
  const shadowVortex = buildGroundShadowVortex(3.4);
  shadowVortex.position.set(-0.5, 0.01, 0.2);
  sceneGroup.add(shadowVortex);

  // 3. Churned Mud Skid Trail beneath the clash
  const skid = buildWetSkidTrail(5.5);
  skid.position.set(0.6, 0, 0.1);
  sceneGroup.add(skid);

  // 4. TOBY 10% MONARCH AWAKENED HERO RIG (IN UPRIGHT BLADE CATCH STANCE)
  // Positioned at x = -1.6, z = 0.9, facing +X (Math.PI / 2) towards Chad
  const toby = buildTobyMonarchRig({ pose: 'blade_catch', includeHUD: false });
  toby.position.set(-1.6, 0, 0.9);
  toby.rotation.y = Math.PI / 2;
  sceneGroup.add(toby);

  // 5. CHAD_ROBUX IN FULL LUNGE ATTACK (THRUSTING FORWARD TOWARDS TOBY)
  // Positioned at x = 2.8, z = -0.7, facing -X (-Math.PI / 2) towards Toby
  const chad = buildChadCombatRig({ pose: 'lunge_slash' });
  chad.position.set(2.8, 0, -0.7);
  chad.rotation.y = -Math.PI / 2;
  sceneGroup.add(chad);

  // 6. CONTACT SINGULARITY: Precise geometric intersection of claws and blade
  const catchPoint = new THREE.Vector3(0.25, 2.05, 0.1);

  const quenchVFX = buildBladeQuenchVFX();
  quenchVFX.position.copy(catchPoint);
  sceneGroup.add(quenchVFX);

  // 7. Erupting 12-Ribbon Coiling Shadow Tendrils surging around Toby
  const tendrils = buildEruptingShadowTendrils(2.4);
  tendrils.position.set(-1.6, 0, 0.9);
  sceneGroup.add(tendrils);

  // 8. Billowing Monarch Purple Flames & Void Embers around Toby
  const flames = buildMonarchFlameAura(2.5);
  flames.position.set(-1.6, 0, 0.9);
  sceneGroup.add(flames);

  // 9. Time-Freeze Suspended Glass Raindrops (40 spheres caught mid-air)
  const suspendedRain = buildSuspendedRaindrops(40);
  suspendedRain.position.set(0.5, 0, 0.1);
  sceneGroup.add(suspendedRain);

  // 10. Diegetic Sovereign System HUD floating proudly above Toby's shoulder
  const hud = buildSovereignSystemHUD();
  hud.position.set(-1.5, 3.4, 2.1);
  hud.rotation.y = -0.2;
