args.Content:
// ============================================================================
// THE GLITCH MARKET — SHOT 5 MASTER PRODUCTION SCENE
// THE SHADOW MONARCH AWAKENING: "THE BAREHANDED BLADE CATCH"
//
// MILESTONE 6 MASTER KEYFRAME (1080x1920 Vertical 9:16)
//
// Produces:
// 1. shot5_keyframe_01.png (Official Vertical 9:16 Master Keyframe 04)
// 2. shot5_master_sheet.png (2400x1350 Production Director Master Sheet)
// ============================================================================

import * as THREE from 'three';
import { Textures } from './core/geo.js';
import {
  buildClashScene1_TimeFreeze,
  buildClashScene2_SymbioteInfusionMacro,
  buildClashScene3_BladeCatchClimax
} from './shadow_clashes.js';

function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

async function init() {
  const masterCanvas = document.getElementById('viewCanvas');
  const masterCtx = masterCanvas.getContext('2d');

  // --------------------------------------------------------------------------
  // 1. RENDER OFFICIAL VERTICAL KEYFRAME 04 (1080 × 1920)
  // --------------------------------------------------------------------------
  const vertCanvas = document.createElement('canvas');
  vertCanvas.width = 1080;
  vertCanvas.height = 1920;

  const rendererVert = new THREE.WebGLRenderer({
    canvas: vertCanvas,
    antialias: true,
    alpha: false,
    preserveDrawingBuffer: true
  });
  rendererVert.setSize(1080, 1920);
  rendererVert.setPixelRatio(1);
  rendererVert.toneMapping = THREE.ACESFilmicToneMapping;
  rendererVert.toneMappingExposure = 1.35;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050811);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(400, 400, 320, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 50, 0);
  scene.add(skyDome);

  // Studio Lighting Rig
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x0A0F1E, 1.2);
  scene.add(hemi);

  const keyLight = new THREE.DirectionalLight(0xFFFBEB, 2.2);
  keyLight.position.set(8, 12, 10);
  scene.add(keyLight);

  const fillCyan = new THREE.DirectionalLight(0x00F0FF, 1.8);
  fillCyan.position.set(-8, 6, 4);
  scene.add(fillCyan);

  const monarchVioletRim = new THREE.DirectionalLight(0xA855F7, 3.2);
  monarchVioletRim.position.set(6, 6, -6);
  scene.add(monarchVioletRim);

  const frontCamKey = new THREE.DirectionalLight(0xFFFFFF, 1.8);
  frontCamKey.position.set(2, 4, 7);
  scene.add(frontCamKey);

  // Build Scene 3: The Barehanded Blade Catch Climax
  const scene3 = buildClashScene3_BladeCatchClimax();
  scene.add(scene3);

  // Vertical Camera (9:16 Aspect) — Tuned distance for full duel framing
  const vertCam = new THREE.PerspectiveCamera(52, 1080 / 1920, 0.1, 350);
  vertCam.position.set(0.0, 2.4, 8.4);
  vertCam.lookAt(new THREE.Vector3(0.0, 2.1, 0.1));

  rendererVert.render(scene, vertCam);

  // Composite WebGL frame onto 2D Canvas for Diegetic Letterbox Overlay
  const finalVertCanvas = document.createElement('canvas');
  finalVertCanvas.width = 1080;
  finalVertCanvas.height = 1920;
  const vctx = finalVertCanvas.getContext('2d');
  vctx.drawImage(vertCanvas, 0, 0);

  // Top Cinematic Badge
  vctx.fillStyle = 'rgba(5, 8, 17, 0.88)';
  vctx.fillRect(40, 48, 1000, 110);
  vctx.strokeStyle = '#00F0FF';
  vctx.lineWidth = 2.5;
  vctx.strokeRect(40, 48, 1000, 110);

  vctx.fillStyle = '#00F0FF';
  vctx.font = 'bold 24px monospace';
  vctx.fillText('THE GLITCH MARKET // SHOT 5: THE SHADOW\'S AWAKENING', 68, 88);

  vctx.fillStyle = '#C084FC';
  vctx.font = 'bold 18px monospace';
  vctx.fillText('MASTER KEYFRAME 04: "THE BAREHANDED BLADE CATCH" (1080 × 1920)', 68, 118);

  vctx.fillStyle = '#94A3B8';
  vctx.font = '14px monospace';
  vctx.fillText('SOUL CORRUPTION: 10.0% // STAGE 1: MONARCH\'S GRIP ACTIVE', 68, 142);

  // Bottom Subtitle & Stats Bar
  vctx.fillStyle = 'rgba(5, 8, 17, 0.92)';
  vctx.fillRect(40, 1750, 1000, 120);
  vctx.strokeStyle = '#A855F7';
  vctx.lineWidth = 2.5;
  vctx.strokeRect(40, 1750, 1000, 120);

  vctx.fillStyle = '#EF4444';
  vctx.font = 'bold 20px monospace';
  vctx.fillText('CHAD_ROBUX: "IMPOSSIBLE! HE STOPPED MY FROSTFIRE WITH BARE CLAWS?!"', 68, 1790);

  vctx.fillStyle = '#00F0FF';
  vctx.font = 'bold 18px monospace';
  vctx.fillText('SYSTEM OVERRIDE: [AUTHORITY ACCEPTED] // GOLDEN FLAME EXTINGUISHED', 68, 1822);

  vctx.fillStyle = '#94A3B8';
  vctx.font = '14px monospace';
  vctx.fillText('3.4m Shadow Vortex • 12 Coiling Tendrils • 40 Suspended Droplets • Quenched Smoke', 68, 1850);

  // Upload Vertical Master Keyframe 04
  const vertBlob = await canvasToBlob(finalVertCanvas);
  await uploadImage('shot5_keyframe_01.png', vertBlob);
  console.log('SAVED: shot5_keyframe_01.png');

  // --------------------------------------------------------------------------
  // 2. RENDER SUPPORTING AUDIT PANELS (Scene 1 & Scene 2)
  // --------------------------------------------------------------------------
  const panelCanvas = document.createElement('canvas');
  panelCanvas.width = 1280;
  panelCanvas.height = 760;
  const panelRenderer = new THREE.WebGLRenderer({
    canvas: panelCanvas,
    antialias: true,
    preserveDrawingBuffer: true
  });
  panelRenderer.setSize(1280, 760);
  panelRenderer.toneMapping = THREE.ACESFilmicToneMapping;
  panelRenderer.toneMappingExposure = 1.35;

  // Render Scene 1: Time Freeze
  const sc1 = new THREE.Scene();
  sc1.background = new THREE.Color(0x050811);
  sc1.add(skyDome.clone());
  sc1.add(hemi.clone());
  sc1.add(keyLight.clone());
  sc1.add(buildClashScene1_TimeFreeze());
  const cam1 = new THREE.PerspectiveCamera(46, 1280 / 760, 0.1, 350);
  cam1.position.set(0.0, 2.4, 1.2);
  cam1.lookAt(new THREE.Vector3(0.0, 2.0, -3.1));
  panelRenderer.render(sc1, cam1);

  const thumb1 = document.createElement('canvas');
  thumb1.width = 1280; thumb1.height = 760;
  thumb1.getContext('2d').drawImage(panelCanvas, 0, 0);

  // Render Scene 2: Symbiote Finger Macro
  const sc2 = new THREE.Scene();
  sc2.background = new THREE.Color(0x050811);
  sc2.add(skyDome.clone());
  sc2.add(hemi.clone());
  sc2.add(keyLight.clone());
  sc2.add(buildClashScene2_SymbioteInfusionMacro());
  const cam2 = new THREE.PerspectiveCamera(34, 1280 / 760, 0.1, 350);
  cam2.position.set(0.85, 0.85, 1.2);
  cam2.lookAt(new THREE.Vector3(0.2, 0.25, 0.0));
  panelRenderer.render(sc2, cam2);

  const thumb2 = document.createElement('canvas');
  thumb2.width = 1280; thumb2.height = 760;
  thumb2.getContext('2d').drawImage(panelCanvas, 0, 0);

  // --------------------------------------------------------------------------
  // 3. ASSEMBLE MASTER DIRECTOR SHEET (2400 × 1350)
  // --------------------------------------------------------------------------
  masterCtx.fillStyle = '#050811';
  masterCtx.fillRect(0, 0, 2400, 1350);

  // Cyber Grid
  masterCtx.strokeStyle = 'rgba(0, 240, 255, 0.05)';
  masterCtx.lineWidth = 1;
  const gridSize = 40;
  for (let x = 0; x < 2400; x += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(x, 0); masterCtx.lineTo(x, 1350); masterCtx.stroke();
  }
  for (let y = 0; y < 1350; y += gridSize) {
    masterCtx.beginPath(); masterCtx.moveTo(0, y); masterCtx.lineTo(2400, y); masterCtx.stroke();
  }

  // Header
  masterCtx.fillStyle = '#FFFFFF';
  masterCtx.font = '900 34px sans-serif';
  masterCtx.fillText('THE GLITCH MARKET // SHOT 5 MASTER: "THE SHADOW\'S AWAKENING"', 45, 55);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 16px monospace';
  masterCtx.fillText('MILESTONE 6 MASTER PRODUCTION KEYFRAME // 1080×1920 VERTICAL (9:16) CINEMATIC SUITE', 45, 85);

  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = 'bold 13px monospace';
  masterCtx.textAlign = 'right';
  masterCtx.fillText('SOLO LEVELING DARK ANIME TRANSFORMATION • SYMBIOTE INFUSION', 2355, 55);
  masterCtx.fillText('THE BAREHANDED BLADE CATCH • FLAME QUENCHING • SOVEREIGN AUTHORITY ACCEPTED', 2355, 78);
  masterCtx.textAlign = 'left';

  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.beginPath(); masterCtx.moveTo(45, 105); masterCtx.lineTo(2355, 105); masterCtx.stroke();

  // Left Panel: Vertical 9:16 Keyframe (675 × 1200)
  const vertW = 675;
  const vertH = 1200;
  const vertX = 55;
  const vertY = 125;

  masterCtx.drawImage(finalVertCanvas, vertX, vertY, vertW, vertH);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2.5;
  masterCtx.strokeRect(vertX, vertY, vertW, vertH);

  // Right Side: 2 Supporting Scenes + Technical Breakdown Panel
  const rightX = 770;
  const cardW = 760;
  const cardH = 430;

  // Card 1: Scene 1 (Time Freeze)
  masterCtx.drawImage(thumb1, rightX, vertY, cardW, cardH);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(rightX, vertY, cardW, cardH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.9)';
  masterCtx.fillRect(rightX + 12, vertY + 12, cardW - 24, 48);
  masterCtx.strokeStyle = '#38BDF8';
  masterCtx.lineWidth = 1;
  masterCtx.strokeRect(rightX + 12, vertY + 12, cardW - 24, 48);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 14px monospace';
  masterCtx.fillText('SCENE 1: THE TIME-FREEZE & SOVEREIGN SYSTEM ALERT', rightX + 24, vertY + 34);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '11px monospace';
  masterCtx.fillText('Chad frozen mid-lunge 2" from Toby\'s throat, 40 raindrops suspended, [SYSTEM OVERRIDE] HUD flashing', rightX + 24, vertY + 50);

  // Card 2: Scene 2 (Symbiote Finger Macro)
  const card2X = 1570;
  masterCtx.drawImage(thumb2, card2X, vertY, cardW, cardH);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(card2X, vertY, cardW, cardH);

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.9)';
  masterCtx.fillRect(card2X + 12, vertY + 12, cardW - 24, 48);
  masterCtx.strokeStyle = '#38BDF8';
  masterCtx.lineWidth = 1;
  masterCtx.strokeRect(card2X + 12, vertY + 12, cardW - 24, 48);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 14px monospace';
  masterCtx.fillText('SCENE 2: THE SYMBIOTE INFUSION FINGER MACRO', card2X + 24, vertY + 34);
  masterCtx.fillStyle = '#94A3B8';
  masterCtx.font = '11px monospace';
  masterCtx.fillText('Toby\'s hand mutating on wet cobblestones: yellow skin turning to obsidian void, claws extending', card2X + 24, vertY + 50);

  // Bottom Technical Spec Ledger
  const specY = 585;
  const specW = 1560;
  const specH = 740;

  masterCtx.fillStyle = 'rgba(7, 13, 27, 0.95)';
  masterCtx.fillRect(rightX, specY, specW, specH);
  masterCtx.strokeStyle = '#00F0FF';
  masterCtx.lineWidth = 2;
  masterCtx.strokeRect(rightX, specY, specW, specH);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 20px monospace';
  masterCtx.fillText('MASTER KEYFRAME 04 PRODUCTION AUDIT // EPISODE 1 CLIMAX: "THE SHADOW\'S AWAKENING"', rightX + 28, specY + 45);

  masterCtx.strokeStyle = '#334155';
  masterCtx.lineWidth = 1;
  masterCtx.beginPath(); masterCtx.moveTo(rightX + 28, specY + 62); masterCtx.lineTo(rightX + specW - 28, specY + 62); masterCtx.stroke();

  masterCtx.font = '13px monospace';
  masterCtx.fillStyle = '#E2E8F0';
  const lineH = 28;
  const col1X = rightX + 28;
  const col2X = rightX + 800;

  // Left Spec Column
  masterCtx.fillText('• NARRATIVE BEAT & CORE MECHANICS:', col1X, specY + 100);
  masterCtx.fillText('  - Act III Climax: Chad lunges with lethal intent to execute Toby outside the Sector 04 Arena.', col1X, specY + 100 + lineH);
  masterCtx.fillText('  - System Override: At 0.01% [1 HP], the Monarch Sovereign Protocol intervenes and freezes physical time.', col1X, specY + 100 + lineH * 2);
  masterCtx.fillText('  - 10% Soul Corruption: Living liquid darkness surges from the ground puddle into Toby\'s right arm.', col1X, specY + 100 + lineH * 3);
