  masterCtx.fillText('  - Glitch Data Arcs (#00F0FF): High-frequency electric cyan jump sparks on cyber-claw tips.', col1X, specY + 100 + lineH * 10);
  masterCtx.fillText('  - Global Time-Stop: 40 suspended elongated glass droplets with cyan specular rim reflections.', col1X, specY + 100 + lineH * 11);

  // Right Spec Column
  masterCtx.fillText('• PRODUCTION SPECIFICATIONS & ASSET LEDGER:', col2X, specY + 100);
  masterCtx.fillText('  - Resolution: 1080 × 1920 (Vertical 9:16 Full High-Definition Master Keyframe).', col2X, specY + 100 + lineH);
  masterCtx.fillText('  - Asset C-01: Toby 10% Corrupted Shadow Arm Rig (Obsidian forearm, 5 razor claws, 12 tendrils).', col2X, specY + 100 + lineH * 2);
  masterCtx.fillText('  - Asset C-02: Monarch Sovereign Face Decal (Needle pupil, cyan/purple laser flare, predatory smirk).', col2X, specY + 100 + lineH * 3);
  masterCtx.fillText('  - Asset C-03: 10% Soul Corruption Sovereign System HUD ([SYSTEM OVERRIDE] card).', col2X, specY + 100 + lineH * 4);
  masterCtx.fillText('  - Asset VFX-06: Viscous Ground Puddle Shadow Vortex (3.4m radius, concentric glyphs, 24 bubbles).', col2X, specY + 100 + lineH * 5);
  masterCtx.fillText('  - Asset VFX-07: 12-Ribbon Coiling Liquid Tendrils (Dual-tube Bézier splines).', col2X, specY + 100 + lineH * 6);
  masterCtx.fillText('  - Asset VFX-08: Billowing Monarch Purple Flames & Void Embers (28 flame cones, 6.0 cd point light).', col2X, specY + 100 + lineH * 7);
