  masterCtx.fillText('  - Asset CLASH-01: Contact Singularity & Quench VFX (6 smoke dodecahedrons, 24 sparks).', col2X, specY + 100 + lineH * 9);

  masterCtx.fillStyle = '#00F0FF';
  masterCtx.font = 'bold 15px monospace';
  masterCtx.fillText('• MILESTONE 6 STATUS: 100% COMPLETE & PRODUCTION LOCKED', col2X, specY + 100 + lineH * 12);
