import * as THREE from 'three';
import { Textures } from './core/geo.js';
import {
  buildTobyMonarchRig,
  buildSovereignSystemHUD,
  buildCorruptedRightArm
} from './shadow_combatant.js';
import { buildChadCombatRig } from './duel_combatants.js';
import { buildBladeQuenchVFX } from './shadow_clashes.js';
import { buildWetSkidTrail } from './duel_effects.js';
import {
  buildGroundShadowVortex,
  buildEruptingShadowTendrils,
  buildMonarchFlameAura,
  buildSuspendedRaindrops
} from './shadow_effects.js';

function canvasToBlob(canvas) {
  return new Promise((resolve) => canvas.toBlob(resolve, 'image/png'));
}

async function uploadImage(name, blob) {
  const resp = await fetch(`/save?name=${encodeURIComponent(name)}`, {
    method: 'POST',
    body: blob
  });
  if (!resp.ok) throw new Error(`Failed to upload ${name}: ${resp.status}`);
}

async function init() {
  const canvas = document.getElementById('viewCanvas');
  const renderer = new THREE.WebGLRenderer({
    canvas,
    antialias: true,
    preserveDrawingBuffer: true
  });
  renderer.setSize(1080, 1920);
  renderer.toneMapping = THREE.ACESFilmicToneMapping;
  renderer.toneMappingExposure = 1.35;

  const scene = new THREE.Scene();
  scene.background = new THREE.Color(0x050811);

  // Distant Cyber Skybox Dome
  const skyGeo = new THREE.CylinderGeometry(400, 400, 320, 36, 1, true);
  const skyMat = new THREE.MeshBasicMaterial({
    map: Textures.cyberSkyBackdrop(),
    side: THREE.BackSide,
    depthWrite: false
  });
  const skyDome = new THREE.Mesh(skyGeo, skyMat);
  skyDome.position.set(0, 50, 0);
  scene.add(skyDome);

  // Lighting
  const hemi = new THREE.HemisphereLight(0x38BDF8, 0x0A0F1E, 1.2);
  scene.add(hemi);

  const keyLight = new THREE.DirectionalLight(0xFFFBEB, 2.2);
  keyLight.position.set(8, 12, 10);
  scene.add(keyLight);

  const fillCyan = new THREE.DirectionalLight(0x00F0FF, 1.8);
  fillCyan.position.set(-8, 6, 4);
  scene.add(fillCyan);

  const monarchRim = new THREE.DirectionalLight(0xA855F7, 3.2);
  monarchRim.position.set(6, 6, -6);
  scene.add(monarchRim);

  const frontCamKey = new THREE.DirectionalLight(0xFFFFFF, 2.0);
  frontCamKey.position.set(0, 4, 8);
  scene.add(frontCamKey);

  // Floor
  const floorGeo = new THREE.CylinderGeometry(14, 14, 0.4, 32);
  const floorMat = new THREE.MeshStandardMaterial({
    color: 0x090D18,
    roughness: 0.25,
    metalness: 0.5
  });
  const floor = new THREE.Mesh(floorGeo, floorMat);
  floor.position.set(0, -0.2, 0);
  scene.add(floor);

  // Ground Vortex under Toby (placed at x = -1.5, z = 1.4)
  const shadowVortex = buildGroundShadowVortex(3.4);
  shadowVortex.position.set(-1.5, 0.01, 1.4);
  scene.add(shadowVortex);

  // Skid trail
  const skid = buildWetSkidTrail(5.5);
  skid.position.set(0.0, 0, 1.4);
  scene.add(skid);

  // 1. TOBY on LEFT (x = -1.6, z = 0.0), facing +X (Math.PI / 2)
  const toby = buildTobyMonarchRig({ pose: 'blade_catch', includeHUD: false });
  toby.position.set(-1.6, 0, 0.0);
  toby.rotation.y = Math.PI / 2;
  scene.add(toby);

  // Swap corrupted arm to camera-facing arm (local -X, armL)
  const tobyTorso = toby.getObjectByName('Torso');
  if (tobyTorso) {
    const oldArmL = tobyTorso.getObjectByName('NormalLeftArm');
    const oldArmR = tobyTorso.getObjectByName('CorruptedShadowArm');
    if (oldArmL && oldArmR) {
      tobyTorso.remove(oldArmL);
      tobyTorso.remove(oldArmR);

      // Create corrupted arm at -1.5 (camera facing side!)
      const corruptArm = buildCorruptedRightArm();
      corruptArm.name = 'CorruptedCameraArm';
      corruptArm.position.set(-1.5, 0.75, 0);
      // Thrust arm forward to clamp blade: in local coordinates, forward along +Z is -1.48 around X
      corruptArm.rotation.set(-1.48, 0.18, -0.12);
      tobyTorso.add(corruptArm);

      // Put uncorrupted arm on far side (+1.5) pulled back
      oldArmL.name = 'BackArm';
      oldArmL.position.set(1.5, 0.75, 0);
      oldArmL.rotation.set(-0.35, -0.15, 0.22);
      tobyTorso.add(oldArmL);
    }

    const tobyHead = tobyTorso.getObjectByName('Head');
    if (tobyHead) {
      tobyHead.rotation.set(-0.04, -0.22, 0.02); // Focus eye laser forward at Chad
    }
  }

  // Tendrils and purple flame around Toby
  const tendrils = buildEruptingShadowTendrils(2.4);
  tendrils.position.set(-1.6, 0, 1.4);
  scene.add(tendrils);

  const flames = buildMonarchFlameAura(2.5);
  flames.position.set(-1.6, 0, 1.4);
  scene.add(flames);

  // 2. CHAD on RIGHT (x = 1.6, z = 0.0), facing -X (-Math.PI / 2)
  const chad = buildChadCombatRig({ pose: 'lunge_slash' });
  chad.position.set(1.6, 0, 0.0);
  chad.rotation.y = -Math.PI / 2;
  scene.add(chad);

  const chadTorso = chad.getObjectByName('Torso');
  if (chadTorso) {
    chadTorso.children.forEach(c => {
      if (c.children && c.children.some(ch => ch.name === 'ActiveFrostfireRapier')) {
        // Thrust rapier directly forward along arm axis
        c.rotation.set(-1.46, -0.15, 0.12);
      }
    });
  }

  // 3. CONTACT SINGULARITY at (0.0, 2.05, 1.45)
  const catchPoint = new THREE.Vector3(0.0, 2.05, 1.45);
  const quenchVFX = buildBladeQuenchVFX();
  quenchVFX.position.copy(catchPoint);
  scene.add(quenchVFX);

  // 4. SOVEREIGN SYSTEM HUD floating above Toby and clash
  const hud = buildSovereignSystemHUD();
  hud.position.set(-0.8, 3.5, 1.4);
  hud.scale.set(0.85, 0.85, 0.85);
  hud.rotation.y = -0.15; // Slightly angled towards camera
  scene.add(hud);

  // 5. Suspended Raindrops
  const suspendedRain = buildSuspendedRaindrops(40);
  suspendedRain.position.set(0.0, 0, 1.4);
  scene.add(suspendedRain);

  // 6. Camera at +Z looking at the clash
  const cam = new THREE.PerspectiveCamera(48, 1080 / 1920, 0.1, 350);
  cam.position.set(0.0, 2.25, 7.8);
  cam.lookAt(new THREE.Vector3(0.0, 2.08, 1.45));

  renderer.render(scene, cam);

  // Save preview
  const blob = await canvasToBlob(canvas);
  await uploadImage('preview_blade_catch.png', blob);
  console.log('SAVED: preview_blade_catch.png');

  window.ALL_SAVED = true;
}

window.onload = init;

