// ARMS CONFIGURATION (CAMERA-FACING CORRUPTED ARM IN BLADE CATCH POSE)
// --------------------------------------------------------------------------
const pose = options.pose || 'standing_straight';
const isBladeCatch = (pose === 'blade_catch');

let armL, armR;
const leftSleeveMat = new THREE.MeshStandardMaterial({
  color: 0x0F766E,
  roughness: 0.8,
  metalness: 0.05
});

if (isBladeCatch) {
  // In blade catch duel staging (Toby facing +X towards Chad at +X):
  // Local -X rotates to World +Z (facing directly toward the camera).
  // Place the Corrupted Shadow Arm at -X so it is 100% in the foreground!
  armL = buildCorruptedRightArm();
  armL.name = 'CorruptedShadowArm';
  armL.position.set(-1.5, 0.75, 0);
  torso.add(armL);

  // Uncorrupted teal sleeve placed on far side (+X, rotating to -Z)
  armR = new THREE.Group();
  armR.name = 'NormalLeftArm';
  armR.position.set(1.5, 0.75, 0);
  const armRMesh = createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, leftSleeveMat);
  armRMesh.position.set(0, -0.75, 0);
  armR.add(armRMesh);
  const handR = createBeveledBox(0.96, 0.5, 0.96, 0.03, 2, matSkin);
  handR.position.set(0, -1.5, 0);
  armR.add(handR);
  torso.add(armR);
} else {
  // Standard R6 Layout: Uncorrupted Left Arm at -X, Corrupted Arm at +X
  armL = new THREE.Group();
  armL.name = 'NormalLeftArm';
  armL.position.set(-1.5, 0.75, 0);
  const armLMesh = createBeveledBox(1.0, 2.0, 1.0, 0.04, 2, leftSleeveMat);
  armLMesh.position.set(0, -0.75, 0);
  armL.add(armLMesh);
  const handL = createBeveledBox(0.96, 0.5, 0.96, 0.03, 2, matSkin);
  handL.position.set(0, -1.5, 0);
  armL.add(handL);
  torso.add(armL);

  armR = buildCorruptedRightArm();
  armR.name = 'CorruptedShadowArm';
  armR.position.set(1.5, 0.75, 0);
  torso.add(armR);
}

