const prompts = JSON.parse(fs.readFileSync(promptsPath, 'utf8')).filter(p => p.num >= 8);

async function parseTranscript() {
  const fileStream = fs.createReadStream(transcriptPath);
  const rl = readline.createInterface({
    input: fileStream,
    crlfDelay: Infinity
  });

  const stepsByPrompt = {};
  for (const p of prompts) {
    stepsByPrompt[p.num] = {
      prompt: p,
      toolCalls: [],
      filesWritten: [],
      filesEdited: [],
      commands: [],
      responses: []
    };
  }

  let currentPromptIdx = 0;

  for await (const line of rl) {
    if (!line.trim()) continue;
    try {
      const step = JSON.parse(line);
      const stepIdx = step.step_index;

      // Find which prompt this belongs to
      while (currentPromptIdx < prompts.length - 1 && stepIdx >= prompts[currentPromptIdx + 1].step) {
        currentPromptIdx++;
      }

      const pNum = prompts[currentPromptIdx].num;
      if (stepIdx < prompts[0].step) continue; // Before GM

      const bucket = stepsByPrompt[pNum];
      if (!bucket) continue;

      if (step.type === 'PLANNER_RESPONSE') {
        if (step.tool_calls && step.tool_calls.length > 0) {
          for (const tc of step.tool_calls) {
            bucket.toolCalls.push({ name: tc.name, args: tc.args });
            if (tc.name === 'write_file' && tc.args?.Path) {
              bucket.filesWritten.push(tc.args.Path);
            } else if (tc.name === 'edit_file' && tc.args?.Path) {
              bucket.filesEdited.push(tc.args.Path);
            } else if (tc.name === 'run_command' && tc.args?.CommandLine) {
              bucket.commands.push(tc.args.toolSummary || tc.args.CommandLine.substring(0, 60));
            }
          }
        }
        if (step.content) {
          bucket.responses.push(step.content);
        }
      }
    } catch (e) {
      // ignore json parse error
    }
  }

  fs.writeFileSync('C:/Users/dirgh/.gemini/antigravity/brain/08383f18-8836-44c0-b898-f0efe2c3452e/scratch/prompt_details.json', JSON.stringify(stepsByPrompt, null, 2));
  console.log('Saved prompt details to scratch/prompt_details.json');
}

