export function generateSkillSpec() {
  return `## 🛠️ Skill Engineering Specification: \`roblox-3d-pipeline\`

To eliminate the manual friction observed across the 46 prompts and enable any AI agent to produce identical, AAA-grade Roblox 3D assets and continuous animations with minimal effort, we codify the entire technical pipeline into a formal Antigravity Skill specification.

---

### 1. Reusable Mathematical & Geometric Formulas

#### A. The Procedural Chamfered Cuboid (\`chamferBox\`)
Roblox characters and accessories require rounded bevels that catch specular studio highlights while preserving blocky proportions.

\`\`\`javascript
/**
 * Generates a procedural chamfered cuboid buffer geometry.
 * @param {number} width - Box width along X
 * @param {number} height - Box height along Y
 * @param {number} depth - Box depth along Z
 * @param {number} radius - Bevel chamfer radius (default: 0.05)
 * @param {number} segments - Bevel smoothness segments (default: 3)
 * @returns {THREE.BufferGeometry}
 */
import * as THREE from 'three';

export function chamferBox(width, height, depth, radius = 0.05, segments = 3) {
  // Clamp radius to prevent internal face intersection
  const maxR = Math.min(width, height, depth) * 0.25;
  const r = Math.min(radius, maxR);

  // Create rounded extrude shape or segmented box geometry
  const shape = new THREE.Shape();
  const hw = width * 0.5 - r;
  const hh = height * 0.5 - r;

  shape.moveTo(-hw, -hh - r);
  shape.lineTo(hw, -hh - r);
  shape.absarc(hw, -hh, r, -Math.PI * 0.5, 0, false);
  shape.lineTo(hw + r, hh);
  shape.absarc(hw, hh, r, 0, Math.PI * 0.5, false);
  shape.lineTo(-hw, hh + r);
  shape.absarc(-hw, hh, r, Math.PI * 0.5, Math.PI, false);
  shape.lineTo(-hw - r, -hh);
  shape.absarc(-hw, -hh, r, Math.PI, Math.PI * 1.5, false);

  const extrudeSettings = {
    steps: 1,
    depth: depth - r * 2,
    bevelEnabled: true,
    bevelThickness: r,
    bevelSize: r,
    bevelOffset: 0,
    bevelSegments: segments
  };

  const geo = new THREE.ExtrudeGeometry(shape, extrudeSettings);
  geo.center();
  geo.computeVertexNormals();
  return geo;
}
\`\`\`

---

#### B. The Procedural 2D Canvas Decal Engine (\`canvasTex\`)
Generates high-resolution textures dynamically without external image dependencies.

\`\`\`javascript
/**
 * Procedural HTML5 Canvas Texture Generator
 * @param {number} width - Canvas texture width in pixels
 * @param {number} height - Canvas texture height in pixels
 * @param {function(CanvasRenderingContext2D, number, number): void} drawFn - Drawing routine
 * @returns {THREE.CanvasTexture}
 */
export function canvasTex(width, height, drawFn) {
  const canvas = document.createElement('canvas');
  canvas.width = width;
  canvas.height = height;
  const ctx = canvas.getContext('2d');

  // Enable crisp subpixel rendering
  ctx.imageSmoothingEnabled = true;
  ctx.imageSmoothingQuality = 'high';

  // Execute custom procedural draw routine
  drawFn(ctx, width, height);

  const texture = new THREE.CanvasTexture(canvas);
  texture.colorSpace = THREE.SRGBColorSpace;
  texture.needsUpdate = true;
  return texture;
}
