export function createRobloxSmileTex() {
  return canvasTex(512, 512, (ctx, w, h) => {
    ctx.fillStyle = '#ffcc00'; // Yellow head base
    ctx.fillRect(0, 0, w, h);

    // Eyes
    ctx.fillStyle = '#111111';
    ctx.beginPath();
    ctx.arc(w * 0.35, h * 0.38, 22, 0, Math.PI * 2);
    ctx.arc(w * 0.65, h * 0.38, 22, 0, Math.PI * 2);
    ctx.fill();

    // Smile Arc
    ctx.lineWidth = 14;
    ctx.lineCap = 'round';
    ctx.strokeStyle = '#111111';
    ctx.beginPath();
    ctx.arc(w * 0.5, h * 0.44, 75, 0.15 * Math.PI, 0.85 * Math.PI, false);
    ctx.stroke();
  });
}
