\`\`\`javascript
export function createShadowMonarchMaterial() {
  return new THREE.ShaderMaterial({
    uniforms: {
      uTime: { value: 0 },
      uColorCore: { value: new THREE.Color('#05010a') },    // Tier 1: Void Core
      uColorPlasma: { value: new THREE.Color('#6A0DAD') },  // Tier 2: Royal Purple Fringe
      uColorData: { value: new THREE.Color('#00F0FF') }     // Tier 3: Cyan Electric Arc
    },
    vertexShader: \`
      varying vec3 vNormal;
      varying vec3 vViewPosition;
      varying vec2 vUv;
      uniform float uTime;

      void main() {
        vUv = uv;
        vNormal = normalize(normalMatrix * normal);

        // Dynamic noise displacement for living tendril undulation
        vec3 displaced = position;
        float wave = sin(position.y * 4.0 - uTime * 6.0) * 0.06;
        displaced.x += wave * normal.x;
        displaced.z += wave * normal.z;

        vec4 mvPosition = modelViewMatrix * vec4(displaced, 1.0);
        vViewPosition = -mvPosition.xyz;
        gl_Position = projectionMatrix * mvPosition;
      }
    \`,
    fragmentShader: \`
      varying vec3 vNormal;
      varying vec3 vViewPosition;
      varying vec2 vUv;
      uniform float uTime;
      uniform vec3 uColorCore;
      uniform vec3 uColorPlasma;
      uniform vec3 uColorData;

      void main() {
        vec3 normal = normalize(vNormal);
        vec3 viewDir = normalize(vViewPosition);

        // Fresnel rim factor
        float fresnel = pow(1.0 - max(dot(normal, viewDir), 0.0), 2.5);

        // Glitch noise sparks
        float spark = step(0.92, fract(sin(dot(vUv * 20.0 + vec2(uTime * 5.0), vec2(12.9898, 78.233))) * 43758.5453));

        // Three-tier layer blend
        vec3 finalColor = mix(uColorCore, uColorPlasma, fresnel);
        finalColor += uColorData * spark * 1.5;

        gl_FragColor = vec4(finalColor, 0.95);
      }
    \`,
    transparent: true,
    side: THREE.DoubleSide
  });
}
