#### D. The Headless 5-Angle Turnaround Studio Script
Automated Puppeteer script that captures 5 calibrated camera views and stitches them into an inspection master sheet.

\`\`\`javascript
// tools/capture_turnaround.mjs
import puppeteer from 'puppeteer';
import { execSync } from 'child_process';
import path from 'path';

export async function captureAssetTurnaround(htmlFilePath, outputDir, assetPrefix) {
  const browser = await puppeteer.launch({
    headless: 'new',
    args: ['--no-sandbox', '--disable-gpu-sandbox', '--window-size=1920,1080']
  });

  const page = await browser.newPage();
  await page.setViewport({ width: 1200, height: 900, deviceScaleFactor: 2 });
  await page.goto('file:///' + path.resolve(htmlFilePath).replace(/\\\\/g, '/'));

  // Wait for WebGL canvas and models to initialize
  await page.waitForFunction(() => window.__READY_FOR_CAPTURE__ === true);

  const angles = ['iso_front', 'side_profile', 'rear_detail', 'top_planar', 'cinematic_low'];
  const capturedFiles = [];

  for (let i = 0; i < angles.length; i++) {
    // Tell the page which camera to switch to
    await page.evaluate((angleIndex) => {
      window.setCameraAngle(angleIndex);
    }, i);

    // Allow Three.js to render 2 frames
    await page.waitForTimeout(200);

    const outPng = path.join(outputDir, \`\${assetPrefix}_angle_\${i+1}_\${angles[i]}.png\`);
    await page.screenshot({ path: outPng, type: 'png' });
    capturedFiles.push(outPng);
  }

  await browser.close();

  // Composite into a master grid sheet using ImageMagick montage or Node Canvas
  const masterSheet = path.join(outputDir, \`\${assetPrefix}_master_sheet.png\`);
  execSync(\`montage "\${outputDir}/\${assetPrefix}_angle_*.png" -geometry 600x450+10+10 -tile 3x2 "\${masterSheet}"\`);

  return { capturedFiles, masterSheet };
}
