The solution that replaces static 2D pan/zoom slideshows with true continuous WebGL animation.

\`\`\`javascript
/**
 * Drives continuous kinematic motion in Three.js
 */
export class RobloxMotionRig {
  constructor(r6Group) {
    this.group = r6Group;
    this.leftArm = r6Group.getObjectByName('LeftArmPivot');
    this.rightArm = r6Group.getObjectByName('RightArmPivot');
    this.leftLeg = r6Group.getObjectByName('LeftLegPivot');
    this.rightLeg = r6Group.getObjectByName('RightLegPivot');
    this.torso = r6Group.getObjectByName('Torso');
    this.head = r6Group.getObjectByName('Head');
  }

  /**
   * Applies kinematic run cycle at simulation time t
   * @param {number} t - Time in seconds
   * @param {number} speed - Gait speed multiplier
   */
  updateRunCycle(t, speed = 8.0) {
    const cycle = t * speed;
    const limbAmp = 0.65; // ~37 degrees

    // Opposite limb oscillation (sinusoidal gait)
    this.leftArm.rotation.x = Math.sin(cycle) * limbAmp;
    this.rightArm.rotation.x = -Math.sin(cycle) * limbAmp;
    this.leftLeg.rotation.x = -Math.sin(cycle) * limbAmp * 1.2;
    this.rightLeg.rotation.x = Math.sin(cycle) * limbAmp * 1.2;

    // Torso bounce and lean
    this.torso.position.y = 1.0 + Math.abs(Math.sin(cycle * 2)) * 0.12;
    this.torso.rotation.x = 0.15; // Forward athletic lean
    this.torso.rotation.y = Math.sin(cycle) * 0.08;

    // Head gaze stabilization
    this.head.rotation.x = -0.15; // Keep eyes forward
  }

  /**
   * Applies vehicle hover and banking physics
   */
  static updateVehicleFlight(vehicleGroup, t, pathCurve) {
    const u = (t * 0.05) % 1.0;
    const pos = pathCurve.getPointAt(u);
    const tangent = pathCurve.getTangentAt(u);

    // Position along spline + sinusoidal hover float
    vehicleGroup.position.copy(pos);
    vehicleGroup.position.y += Math.sin(t * 3.0) * 0.25;

    // Align with forward flight vector
    vehicleGroup.quaternion.setFromUnitVectors(new THREE.Vector3(0, 0, 1), tangent);

    // Bank into curves (roll angle proportional to curvature)
    const curvature = pathCurve.getTangentAt(Math.min(u + 0.01, 1.0)).x - tangent.x;
    vehicleGroup.rotation.z = -curvature * 15.0;
  }
}
