import fs from 'fs';
import path from 'path';

function searchDirectory(dir, depth = 0, maxDepth = 4) {
  if (depth > maxDepth) return [];
  let found = [];
  try {
    const entries = fs.readdirSync(dir, { withFileTypes: true });
    for (const entry of entries) {
      if (entry.name.startsWith('$') || entry.name === 'node_modules' || entry.name === '.git' || entry.name === '.pnpm-store') {
        continue;
      }
      const fullPath = path.join(dir, entry.name);
      if (entry.isFile() && entry.name.toLowerCase() === 'blender.exe') {
        found.push(fullPath);
      } else if (entry.isDirectory()) {
        found = found.concat(searchDirectory(fullPath, depth + 1, maxDepth));
      }
    }
  } catch (e) {}
  return found;
}

console.log('Searching Z:\\ for blender.exe (maxDepth 4)...');
const zResults = searchDirectory('Z:\\', 0, 4);
console.log('Found on Z:\\:', zResults);

